def two_scale_branch(row: dict) -> str:
    if not row.get("twoKernelTested") or row.get("twoKernelGainOverQ", 0.0) < RESIDUAL_MEANINGFUL_GAIN:
        return "no-transferable-two-scale"
    if not row.get("twoKernelRouteRecovered", False):
        return "route-breaking-only"
    eta = row.get("twoKernelEta", math.nan)
    if not math.isfinite(eta):
        return "no-transferable-two-scale"
    if eta < 1.0:
        return "inner-memory"
    if eta > 1.0:
        return "outer-memory"
    return "balanced"


def two_scale_clean_for_training(row: dict) -> bool:
    return row["split"] == "train" and row["finalFailureClass"] not in DATA_SYSTEMATICS_FINAL_CLASSES


def two_scale_ratio(row: dict) -> float:
    a1 = row.get("twoKernelA1", math.nan)
    a2 = row.get("twoKernelA2", math.nan)
    total = a1 + a2 if math.isfinite(a1) and math.isfinite(a2) else math.nan
    return a2 / total if math.isfinite(total) and total > 1e-9 else 0.0


def two_scale_case_rows(deficit_rows: list[dict], split: dict) -> list[dict]:
    split_deficit_rows(deficit_rows, split)
    rows = []
    for row in deficit_rows:
        branch = two_scale_branch(row)
        rows.append(
            {
                "name": row["name"],
                "split": row["split"],
                "route": row["route"],
                "lockedRoute": row["baselineModelRoute"],
                "routeMismatch": row["routeMismatch"],
                "closureBucket": closure_bucket(row),
                "finalFailureClass": row["finalFailureClass"],
                "claimSafeStatus": row["claimSafeStatus"],
                "frameworkClosureCandidate": closure_bucket(row) == "framework-closure candidate",
                "claimSafeCase": closure_bucket(row) == "claim-safe case",
                "excludedFromTraining": row["finalFailureClass"] in DATA_SYSTEMATICS_FINAL_CLASSES,
                "transportFacingFlag": row["transportFacingFlag"],
                "systematicsFacingFlag": row["systematicsFacingFlag"],
                "centralApertureFlag": row["centralApertureFlag"],
                "samplingFacingFlag": row["samplingFacingFlag"],
                "baryonicFloorFlag": row["baryonicFloorFlag"],
                "baselineRmse": row["baselineRmse"],
                "qShapeRmse": row["qShapeRmse"],
                "qShape": row["qShape"],
                "qShapeAmp": row["qShapeAmp"],
                "routeSafeRmse": row["routeSafeRmse"],
                "routeSafeAmp": row["routeSafeAmp"],
                "twoKernelTested": row["twoKernelTested"],
                "twoKernelRmse": row["twoKernelRmse"],
                "twoKernelGainOverQ": row["twoKernelGainOverQ"],
                "twoKernelClass": row["twoKernelClass"],
                "twoKernelEta": row["twoKernelEta"],
                "twoKernelQ1": row["twoKernelQ1"],
                "twoKernelQ2": row["twoKernelQ2"],
                "twoKernelA1": row["twoKernelA1"],
                "twoKernelA2": row["twoKernelA2"],
                "twoKernelA2Share": two_scale_ratio(row),
                "twoKernelRoute": row["twoKernelRoute"],
                "twoKernelRouteRecovered": row["twoKernelRouteRecovered"],
                "twoScaleBranch": branch,
                "postShapeRmse": row["postShapeRmse"],
                "bestRobustRmse": row["bestRobustRmse"],
                "memoryLoad": row["memoryLoad"],
                "u075": row["u075"],
                "uOut": row["uOut"],
                "uMax": row["uMax"],
                "leffOverH": row["leffOverH"],
                "fGasOut": row["fGasOut"],
                "outerHeadroom": row["outerHeadroom"],
                "routeMargin": row["routeMargin"],
                "routeBreakRisk": row["routeBreakRisk"],
            }
        )
    rows.sort(key=lambda item: (item["split"], item["twoScaleBranch"], item["name"]))
    return rows


def two_scale_branch_params(train_rows: list[dict]) -> dict[str, dict]:
    params = {}
    transferable = [row for row in train_rows if row["twoScaleBranch"] not in {"no-transferable-two-scale", "route-breaking-only"}]
    fallback_eta = safe_median(row["twoKernelEta"] for row in transferable)
    fallback_q2 = safe_median(row["twoKernelQ2"] for row in transferable)
    fallback_share = safe_median(row["twoKernelA2Share"] for row in transferable)
    for branch in ["inner-memory", "outer-memory", "balanced"]:
        rows = [row for row in transferable if row["twoScaleBranch"] == branch]
        params[branch] = {
            "count": len(rows),
            "eta": safe_median(row["twoKernelEta"] for row in rows) if rows else fallback_eta,
            "q2": safe_median(row["twoKernelQ2"] for row in rows) if rows else fallback_q2,
            "a2Share": safe_median(row["twoKernelA2Share"] for row in rows) if rows else fallback_share,
        }
    return params


def two_scale_frequency_rule(train_rows: list[dict]) -> dict:
    clean = [row for row in train_rows if two_scale_clean_for_training(row)]
    groups: dict[str, list[str]] = {}
    for row in clean:
        groups.setdefault(row["lockedRoute"], []).append(row["twoScaleBranch"])
    branch_by_locked = {}
    all_branches = []
    for locked, values in groups.items():
        all_branches.extend(values)
        counts = {value: values.count(value) for value in set(values)}
        branch_by_locked[locked] = sorted(counts, key=lambda item: (-counts[item], item))[0]
    counts = {value: all_branches.count(value) for value in set(all_branches)}
    fallback = sorted(counts, key=lambda item: (-counts[item], item))[0] if counts else "no-transferable-two-scale"
    return {
        "id": "two-scale-locked-route-frequency",
        "family": "frequency",
        "lockedRoute": "*",
        "variable": "",
        "direction": "",
        "threshold": math.nan,
        "targetBranch": "",
        "fallbackBranch": fallback,
        "branchByLockedRoute": branch_by_locked,
        "paramsByBranch": two_scale_branch_params(clean),
        "trainRows": clean,
        "description": "Predict most frequent clean train two-scale branch for each locked route",
    }


def two_scale_nearest_rule(train_rows: list[dict]) -> dict:
    clean = [row for row in train_rows if two_scale_clean_for_training(row)]
    return {
        "id": "two-scale-nearest-branch-transfer",
        "family": "nearest",
        "lockedRoute": "*",
        "variable": "",
        "direction": "",
        "threshold": math.nan,
        "targetBranch": "",
        "fallbackBranch": "no-transferable-two-scale",
        "paramsByBranch": two_scale_branch_params(clean),
        "trainRows": clean,
        "scaler": route_state_scaler(
            [
                {
                    **row,
                    "observedRoute": row["route"],
                }
                for row in clean
            ]
        ),
        "description": "Transfer nearest clean train two-scale branch in invariant state space",
    }


def two_scale_thresholds(train_rows: list[dict], variable: str) -> list[float]:
    return route_state_rule_thresholds(train_rows, variable)


def two_scale_candidate_rules(train_rows: list[dict]) -> list[dict]:
    clean = [row for row in train_rows if two_scale_clean_for_training(row)]
    rules = [two_scale_frequency_rule(train_rows), two_scale_nearest_rule(train_rows)]
    branches = sorted({row["twoScaleBranch"] for row in clean if row["twoScaleBranch"] not in {"no-transferable-two-scale", "route-breaking-only"}})
    params_by_branch = two_scale_branch_params(clean)
    for branch in branches:
        branch_rows = [row for row in clean if row["twoScaleBranch"] == branch]
        if len(branch_rows) < 2:
            continue
        for locked_route in sorted({row["lockedRoute"] for row in clean}):
            scoped_rows = [row for row in clean if row["lockedRoute"] == locked_route]
            if len(scoped_rows) < 3:
                continue
            for variable in TWO_SCALE_RULE_VARIABLES:
                for threshold in two_scale_thresholds(scoped_rows, variable):
                    for direction in ["ge", "le"]:
                        rules.append(
                            {
                                "id": f"two-scale-{route_state_short_route(locked_route)}-{branch}-{variable}-{direction}-{fmt_num(threshold)}",
                                "family": "threshold",
                                "lockedRoute": locked_route,
                                "variable": variable,
                                "direction": direction,
                                "threshold": threshold,
                                "targetBranch": branch,
                                "fallbackBranch": "no-transferable-two-scale",
                                "paramsByBranch": params_by_branch,
                                "trainRows": clean,
                                "description": f"if lockedRoute={locked_route} and {variable} {direction} {fmt_num(threshold)} transfer {branch}",
                            }
                        )
    return rules


def two_scale_predict_branch(row: dict, rule: dict) -> str:
    if rule["family"] == "frequency":
        return rule["branchByLockedRoute"].get(row["lockedRoute"], rule["fallbackBranch"])
    if rule["family"] == "nearest":
        train_rows = rule["trainRows"]
        if not train_rows:
            return "no-transferable-two-scale"
        probe = {**row, "observedRoute": row["route"]}
        nearest = min(
            train_rows,
            key=lambda item: (
                route_state_distance(probe, {**item, "observedRoute": item["route"]}, rule["scaler"]),
                item["name"],
            ),
        )
        return nearest["twoScaleBranch"]
    if row["lockedRoute"] == rule["lockedRoute"]:
        value = row.get(rule["variable"], math.nan)
        if math.isfinite(value):
            if rule["direction"] == "le" and value <= rule["threshold"]:
                return rule["targetBranch"]
            if rule["direction"] == "ge" and value >= rule["threshold"]:
                return rule["targetBranch"]
    return rule["fallbackBranch"]


def two_scale_locked_route_amp_map(train_rows: list[dict]) -> dict[str, float]:
    groups: dict[str, list[float]] = {}
    for row in train_rows:
        if two_scale_clean_for_training(row):
            groups.setdefault(row["lockedRoute"], []).append(row["qShapeAmp"])
    return {key: safe_median(values) for key, values in groups.items()}


def two_scale_score_curve(curve: dict, source: dict, rule: dict, amp_by_locked: dict[str, float]) -> dict:
    baseline = score_curve_with_params(curve, 1.0, Q_DEFAULT)
    branch = two_scale_predict_branch(source, rule)
    if branch in {"no-transferable-two-scale", "route-breaking-only"}:
        score = baseline
        score.update({"twoScalePredictedBranch": branch, "twoScaleActive": False, "twoScaleProjectionApplied": False, "twoScaleProjectionSteps": 0})
        return score
    params = rule["paramsByBranch"].get(branch, {})
    eta = params.get("eta", math.nan)
    q2 = params.get("q2", math.nan)
    share = params.get("a2Share", math.nan)
    if not all(math.isfinite(value) for value in [eta, q2, share]):
        score = baseline
        score.update({"twoScalePredictedBranch": "no-transferable-two-scale", "twoScaleActive": False, "twoScaleProjectionApplied": False, "twoScaleProjectionSteps": 0})
        return score
    total_amp = amp_by_locked.get(source["lockedRoute"], 1.0)
    total_amp = clamp(total_amp, QCLOSURE_AMP_MIN, QCLOSURE_AMP_MAX)
    share = clamp(share, 0.0, 0.95)
    a2 = total_amp * share
    a1 = max(0.0, total_amp - a2)
    score = score_curve_with_two_kernel(curve, a1, a2, Q_DEFAULT, q2, eta)
    projection_applied = False
    projection_steps = 0
    if score["candidateRoute"] != baseline["candidateRoute"]:
        for step in range(1, 21):
            factor = 1.0 - step / 20.0
            pa1 = 1.0 + factor * (a1 - 1.0)
            pa2 = factor * a2
            projected = score_curve_with_two_kernel(curve, max(0.0, pa1), max(0.0, pa2), Q_DEFAULT, q2, eta)
            if projected["candidateRoute"] == baseline["candidateRoute"]:
                score = projected
                projection_applied = True
                projection_steps = step
                break
    score.update(
        {
            "twoScalePredictedBranch": branch,
            "twoScaleActive": True,
            "twoScaleProjectionApplied": projection_applied,
            "twoScaleProjectionSteps": projection_steps,
        }
    )
    return score


def two_scale_score_rows(curves: list[dict], case_rows: list[dict], split: dict, rule: dict, train_rows: list[dict]) -> list[dict]:
    by_name = {row["name"]: row for row in case_rows}
    amp_by_locked = two_scale_locked_route_amp_map(train_rows)
    rows = []
    for curve in curves:
        source = by_name[curve["name"]]
        baseline = score_curve_with_params(curve, 1.0, Q_DEFAULT)
        score = two_scale_score_curve(curve, source, rule, amp_by_locked)
        preserved = score["candidateRoute"] == baseline["candidateRoute"]
        rows.append(
            {
                "candidateId": rule["id"],
                "name": curve["name"],
                "split": "holdout" if curve["name"] in split["holdoutNames"] else "train",
                "route": curve["route"],
                "baselineModelRoute": baseline["candidateRoute"],
                "candidateRoute": score["candidateRoute"],
                "routePreserved": preserved,
                "routeTransition": "" if preserved else f"{baseline['candidateRoute']} -> {score['candidateRoute']}",
                "routeBreakReason": route_break_reason(baseline, score),
                "closureBucket": source["closureBucket"],
                "finalFailureClass": source["finalFailureClass"],
                "claimSafeLowLoadProtected": bool(
                    source["closureBucket"] == "claim-safe case"
                    and (curve["route"] == "low-load" or baseline["candidateRoute"] == "low-load")
                ),
                "frameworkClosureCandidate": source["frameworkClosureCandidate"],
                "excludedFromTraining": source["excludedFromTraining"],
                "baselineRmse": baseline["rmse"],
                "candidateRmse": score["rmse"],
                "delta": score["rmse"] - baseline["rmse"],
                "improvement": baseline["rmse"] - score["rmse"],
                "baselineInnerRmse": baseline["innerRmse"],
                "candidateInnerRmse": score["innerRmse"],
                "baselineMidRmse": baseline["midRmse"],
                "candidateMidRmse": score["midRmse"],
                "baselineOuterRmse": baseline["outerRmse"],
                "candidateOuterRmse": score["outerRmse"],
                "localTwoKernelRmse": source["twoKernelRmse"],
                "localTwoKernelBranch": source["twoScaleBranch"],
                "predictedTwoScaleBranch": score["twoScalePredictedBranch"],
                "twoScaleActive": score["twoScaleActive"],
                "gateActive": score["twoScaleActive"],
                "twoScaleProjectionApplied": score["twoScaleProjectionApplied"],
                "twoScaleProjectionSteps": score["twoScaleProjectionSteps"],
                "twoScaleEta": score.get("twoKernelEta", math.nan),
                "twoScaleQ2": score.get("twoKernelQ2", math.nan),
                "twoScaleA1": score.get("twoKernelA1", math.nan),
                "twoScaleA2": score.get("twoKernelA2", math.nan),
            }
        )
    return rows


def two_scale_route_breaking_repair_count(rows: list[dict]) -> int:
    return sum(
        1
        for row in rows
        if row["split"] == "holdout"
        and row["frameworkClosureCandidate"]
        and row["candidateRmse"] < RESIDUAL_REPAIR_RMSE
        and not row["routePreserved"]
    )


def two_scale_training_leak_count(case_rows: list[dict]) -> int:
    return sum(1 for row in case_rows if row["split"] == "train" and row["excludedFromTraining"] and row["twoScaleBranch"] != "no-transferable-two-scale")


def two_scale_guardrails(summary: dict, scalar_gain: float, null_gain: float, leak_count: int, route_breaking_repairs: int) -> list[dict]:
    holdout = summary["holdout"]
    closure_holdout = summary["frameworkClosureHoldout"]
    protected = summary["protectedClaimSafeLowLoad"]
    return [
        guardrail("Holdout mean RMSE improvement", holdout["meanImprovementPct"], ">= 15%", holdout["meanImprovementPct"] >= 15),
        guardrail("Framework-closure holdout RMSE improvement", closure_holdout["meanImprovementPct"], ">= 25%", closure_holdout["meanImprovementPct"] >= 25),
        guardrail("Beats scalar route-median control", holdout["meanImprovementPct"] - scalar_gain, ">= 10 percentage points", holdout["meanImprovementPct"] - scalar_gain >= 10),
        guardrail("Beats two-scale null", holdout["meanImprovementPct"] - null_gain, ">= 10 percentage points", holdout["meanImprovementPct"] - null_gain >= 10),
        guardrail("Route preservation", holdout["routePreservationRate"], ">= 95%", holdout["routePreservationRate"] >= 0.95),
        guardrail("Protected claim-safe low-load regression rate > 2 km/s", protected["regressionOver2Rate"], "< 5%", protected["regressionOver2Rate"] < 0.05),
        guardrail("Maximum single regression", holdout["maxRegression"], "<= 8 km/s", holdout["maxRegression"] <= 8),
        guardrail("No data/systematics training leakage", leak_count, "== 0", leak_count == 0),
        guardrail("No route-breaking framework repairs", route_breaking_repairs, "== 0", route_breaking_repairs == 0),
    ]


def two_scale_rule_record(rule: dict, score_rows: list[dict], scalar_gain: float, null_gain: float, leak_count: int) -> dict:
    summary = summarize_qgate_splits(score_rows)
    route_breaking_repairs = two_scale_route_breaking_repair_count(score_rows)
    guardrails = two_scale_guardrails(summary, scalar_gain, null_gain, leak_count, route_breaking_repairs)
    record = {
        "candidateId": rule["id"],
        "family": rule["family"],
        "lockedRoute": rule["lockedRoute"],
        "variable": rule["variable"],
        "direction": rule["direction"],
        "threshold": rule["threshold"],
        "targetBranch": rule["targetBranch"],
        "description": rule["description"],
        "holdoutImprovementPct": summary["holdout"]["meanImprovementPct"],
        "frameworkHoldoutImprovementPct": summary["frameworkClosureHoldout"]["meanImprovementPct"],
        "holdoutRoutePreservationRate": summary["holdout"]["routePreservationRate"],
        "protectedClaimSafeLowLoadRegressionOver2Rate": summary["protectedClaimSafeLowLoad"]["regressionOver2Rate"],
        "holdoutMaxRegression": summary["holdout"]["maxRegression"],
        "routeBreakingFrameworkRepairCount": route_breaking_repairs,
        "scalarMarginPct": summary["holdout"]["meanImprovementPct"] - scalar_gain,
        "nullMarginPct": summary["holdout"]["meanImprovementPct"] - null_gain,
        "claimStatus": "transferable two-scale memory signal" if all(row["passed"] for row in guardrails) else "rejected",
        "guardrailFailures": "; ".join(row["label"] for row in guardrails if not row["passed"]),
    }
    record["rankScore"] = (
        record["holdoutImprovementPct"]
        + 0.5 * record["frameworkHoldoutImprovementPct"]
        + record["scalarMarginPct"]
        + record["nullMarginPct"]
        - 100 * record["protectedClaimSafeLowLoadRegressionOver2Rate"]
        - 2 * max(0.0, record["holdoutMaxRegression"] - 8.0)
        - 50 * record["routeBreakingFrameworkRepairCount"]
    )
    return record


def two_scale_local_score_rows(curves: list[dict], case_rows: list[dict], split: dict, mode: str) -> list[dict]:
    by_name = {row["name"]: row for row in case_rows}
    rows = []
    for curve in curves:
        source = by_name[curve["name"]]
        baseline = score_curve_with_params(curve, 1.0, Q_DEFAULT)
        if mode == "q-only-local":
            score = score_curve_with_params(curve, source["qShapeAmp"], source["qShape"])
        elif mode == "two-kernel-local-oracle":
            if (
                source["twoKernelTested"]
                and math.isfinite(source["twoKernelA1"])
                and math.isfinite(source["twoKernelA2"])
                and math.isfinite(source["twoKernelQ1"])
                and math.isfinite(source["twoKernelQ2"])
                and math.isfinite(source["twoKernelEta"])
            ):
                score = score_curve_with_two_kernel(
                    curve,
                    source["twoKernelA1"],
                    source["twoKernelA2"],
                    source["twoKernelQ1"],
                    source["twoKernelQ2"],
                    source["twoKernelEta"],
                )
            else:
                score = score_curve_with_params(curve, source["qShapeAmp"], source["qShape"])
        else:
            score = baseline
        preserved = score["candidateRoute"] == baseline["candidateRoute"]
        rows.append(
            {
                "candidateId": mode,
                "name": curve["name"],
                "split": "holdout" if curve["name"] in split["holdoutNames"] else "train",
                "route": curve["route"],
                "baselineModelRoute": baseline["candidateRoute"],
                "candidateRoute": score["candidateRoute"],
                "routePreserved": preserved,
                "routeTransition": "" if preserved else f"{baseline['candidateRoute']} -> {score['candidateRoute']}",
                "routeBreakReason": route_break_reason(baseline, score),
                "closureBucket": source["closureBucket"],
                "finalFailureClass": source["finalFailureClass"],
                "claimSafeLowLoadProtected": bool(
                    source["closureBucket"] == "claim-safe case"
                    and (curve["route"] == "low-load" or baseline["candidateRoute"] == "low-load")
                ),
                "baselineRmse": baseline["rmse"],
                "candidateRmse": score["rmse"],
                "delta": score["rmse"] - baseline["rmse"],
                "improvement": baseline["rmse"] - score["rmse"],
                "baselineInnerRmse": baseline["innerRmse"],
                "candidateInnerRmse": score["innerRmse"],
                "baselineMidRmse": baseline["midRmse"],
                "candidateMidRmse": score["midRmse"],
                "baselineOuterRmse": baseline["outerRmse"],
                "candidateOuterRmse": score["outerRmse"],
                "gateActive": mode != "baseline",
            }
        )
    return rows


def two_scale_control_rows(curves: list[dict], case_rows: list[dict], deficit_rows: list[dict], split: dict) -> list[dict]:
    controls = []
    baseline_rows = two_scale_local_score_rows(curves, case_rows, split, "baseline")
    q_rows = two_scale_local_score_rows(curves, case_rows, split, "q-only-local")
    oracle_rows = two_scale_local_score_rows(curves, case_rows, split, "two-kernel-local-oracle")
    scalar_spec = {"family": "route-median", "targetKey": "qShapeAmp", "routeBasis": "observed", "gate": ampgate_locked_gate()}
    scalar_score_rows, _scalar_result, _targets, _candidate = scalarclosure_score_candidate_for_split(curves, deficit_rows, split, scalar_spec)
    for label, rows in [
        ("canonical-baseline", baseline_rows),
        ("route-median-scalar-control", scalar_score_rows),
        ("q-only-local-oracle", q_rows),
        ("two-kernel-local-oracle", oracle_rows),
    ]:
        summary = summarize_qgate_splits(rows)
        controls.append(
            {
                "control": label,
                "holdoutImprovementPct": summary["holdout"]["meanImprovementPct"],
                "frameworkHoldoutImprovementPct": summary["frameworkClosureHoldout"]["meanImprovementPct"],
                "holdoutRoutePreservationRate": summary["holdout"]["routePreservationRate"],
                "protectedClaimSafeLowLoadRegressionOver2Rate": summary["protectedClaimSafeLowLoad"]["regressionOver2Rate"],
                "holdoutMaxRegression": summary["holdout"]["maxRegression"],
            }
        )
    return controls


def two_scale_shuffle_train_rows(train_rows: list[dict], seed: int) -> list[dict]:
    rng = random.Random(seed)
    rows = [dict(row) for row in train_rows]
    branches = [row["twoScaleBranch"] for row in rows]
    etas = [row["twoKernelEta"] for row in rows]
    q2s = [row["twoKernelQ2"] for row in rows]
    shares = [row["twoKernelA2Share"] for row in rows]
    rng.shuffle(branches)
    rng.shuffle(etas)
    rng.shuffle(q2s)
    rng.shuffle(shares)
    for index, row in enumerate(rows):
        row["twoScaleBranch"] = branches[index]
        row["twoKernelEta"] = etas[index]
        row["twoKernelQ2"] = q2s[index]
        row["twoKernelA2Share"] = shares[index]
    return rows


def two_scale_null_rows(curves: list[dict], case_rows: list[dict], split: dict, best_rule: dict, scalar_gain: float) -> list[dict]:
    train_rows = [row for row in case_rows if row["split"] == "train"]
    rows = []
    for index in range(TWO_SCALE_NULL_COUNT):
        shuffled_train = two_scale_shuffle_train_rows(train_rows, 11100 + index)
        if best_rule["family"] == "nearest":
            rule = two_scale_nearest_rule(shuffled_train)
        elif best_rule["family"] == "frequency":
            rule = two_scale_frequency_rule(shuffled_train)
        else:
            rule = {**best_rule, "paramsByBranch": two_scale_branch_params([row for row in shuffled_train if two_scale_clean_for_training(row)]), "trainRows": shuffled_train}
        score_rows = two_scale_score_rows(curves, case_rows, split, rule, shuffled_train)
        summary = summarize_qgate_splits(score_rows)
        rows.append(
            {
                "nullType": "shuffled-two-scale-targets",
                "nullIndex": index,
                "shuffleSeed": 11100 + index,
                "holdoutImprovementPct": summary["holdout"]["meanImprovementPct"],
                "frameworkHoldoutImprovementPct": summary["frameworkClosureHoldout"]["meanImprovementPct"],
                "holdoutRoutePreservationRate": summary["holdout"]["routePreservationRate"],
                "protectedClaimSafeLowLoadRegressionOver2Rate": summary["protectedClaimSafeLowLoad"]["regressionOver2Rate"],
                "holdoutMaxRegression": summary["holdout"]["maxRegression"],
                "scalarMarginPct": summary["holdout"]["meanImprovementPct"] - scalar_gain,
            }
        )
    clean_train = [row for row in train_rows if two_scale_clean_for_training(row)]
    by_locked: dict[str, list[dict]] = {}
    for row in clean_train:
        by_locked.setdefault(row["lockedRoute"], []).append(row)
    for index in range(TWO_SCALE_NULL_COUNT):
        rng = random.Random(11300 + index)
        random_rows = []
        for row in case_rows:
            item = dict(row)
            pool = by_locked.get(row["lockedRoute"], clean_train)
            if pool:
                chosen = pool[rng.randrange(len(pool))]
                item["twoScaleBranch"] = chosen["twoScaleBranch"]
                item["twoKernelEta"] = chosen["twoKernelEta"]
                item["twoKernelQ2"] = chosen["twoKernelQ2"]
                item["twoKernelA2Share"] = chosen["twoKernelA2Share"]
            random_rows.append(item)
        rule = two_scale_frequency_rule([row for row in random_rows if row["split"] == "train"])
        score_rows = two_scale_score_rows(curves, random_rows, split, rule, [row for row in random_rows if row["split"] == "train"])
        summary = summarize_qgate_splits(score_rows)
        rows.append(
            {
                "nullType": "route-preserving-random-two-scale",
                "nullIndex": index,
                "shuffleSeed": 11300 + index,
                "holdoutImprovementPct": summary["holdout"]["meanImprovementPct"],
                "frameworkHoldoutImprovementPct": summary["frameworkClosureHoldout"]["meanImprovementPct"],
                "holdoutRoutePreservationRate": summary["holdout"]["routePreservationRate"],
                "protectedClaimSafeLowLoadRegressionOver2Rate": summary["protectedClaimSafeLowLoad"]["regressionOver2Rate"],
                "holdoutMaxRegression": summary["holdout"]["maxRegression"],
                "scalarMarginPct": summary["holdout"]["meanImprovementPct"] - scalar_gain,
            }
        )
    rows.sort(key=lambda row: (row["nullType"], row["nullIndex"]))
    return rows


def two_scale_named_case_rows(score_rows: list[dict], case_rows: list[dict]) -> list[dict]:
    score_by_name = {row["name"]: row for row in score_rows}
    case_by_name = {row["name"]: row for row in case_rows}
    rows = []
    for name in TWO_SCALE_NAMED_CASES:
        score = score_by_name.get(name)
        case = case_by_name.get(name)
        if not score or not case:
            continue
        rows.append(
            {
                "name": name,
                "split": score["split"],
                "route": score["route"],
                "lockedRoute": score["baselineModelRoute"],
                "baselineRmse": score["baselineRmse"],
                "candidateRmse": score["candidateRmse"],
                "localTwoKernelRmse": case["twoKernelRmse"],
                "localBranch": case["twoScaleBranch"],
                "predictedBranch": score["predictedTwoScaleBranch"],
                "routePreserved": score["routePreserved"],
                "finalFailureClass": case["finalFailureClass"],
                "bestRobustRmse": case["bestRobustRmse"],
            }
        )
    return rows


def two_scale_oracle_ledger(case_rows: list[dict]) -> list[dict]:
    rows = []
    for row in case_rows:
        if not row["twoKernelTested"]:
            continue
        rows.append(
            {
                "name": row["name"],
                "split": row["split"],
                "route": row["route"],
                "lockedRoute": row["lockedRoute"],
                "finalFailureClass": row["finalFailureClass"],
                "baselineRmse": row["baselineRmse"],
                "qShapeRmse": row["qShapeRmse"],
                "twoKernelRmse": row["twoKernelRmse"],
                "twoKernelGainOverQ": row["twoKernelGainOverQ"],
                "twoScaleBranch": row["twoScaleBranch"],
                "eta": row["twoKernelEta"],
                "q2": row["twoKernelQ2"],
                "a1": row["twoKernelA1"],
                "a2": row["twoKernelA2"],
                "a2Share": row["twoKernelA2Share"],
                "routeRecovered": row["twoKernelRouteRecovered"],
            }
        )
    rows.sort(key=lambda row: (-row["twoKernelGainOverQ"], row["name"]))
    return rows


def two_scale_metrics(rule_rows: list[dict], control_rows: list[dict], null_rows: list[dict], case_rows: list[dict]) -> dict:
    best = rule_rows[0] if rule_rows else {}
    scalar_gain = next((row["holdoutImprovementPct"] for row in control_rows if row["control"] == "route-median-scalar-control"), math.nan)
    oracle_gain = next((row["holdoutImprovementPct"] for row in control_rows if row["control"] == "two-kernel-local-oracle"), math.nan)
    null_best = max([safe_median(row["holdoutImprovementPct"] for row in null_rows if row["nullType"] == null_type) for null_type in sorted({row["nullType"] for row in null_rows})] or [math.nan])
    return {
        "bestCandidateId": best.get("candidateId", ""),
        "bestHoldoutImprovementPct": best.get("holdoutImprovementPct", math.nan),
        "bestFrameworkHoldoutImprovementPct": best.get("frameworkHoldoutImprovementPct", math.nan),
        "bestRoutePreservationRate": best.get("holdoutRoutePreservationRate", math.nan),
        "bestProtectedRegressionOver2Rate": best.get("protectedClaimSafeLowLoadRegressionOver2Rate", math.nan),
        "bestMaxRegression": best.get("holdoutMaxRegression", math.nan),
        "bestScalarMarginPct": best.get("scalarMarginPct", math.nan),
        "bestNullMarginPct": best.get("nullMarginPct", math.nan),
        "scalarControlHoldoutImprovementPct": scalar_gain,
        "localTwoKernelOracleHoldoutImprovementPct": oracle_gain,
        "bestNullHoldoutImprovementPct": null_best,
        "localOracleRepairCount": sum(1 for row in case_rows if row["twoKernelRmse"] < RESIDUAL_REPAIR_RMSE and row["twoKernelGainOverQ"] >= RESIDUAL_MEANINGFUL_GAIN),
        "transferableTrainTargetCount": sum(1 for row in case_rows if two_scale_clean_for_training(row) and row["twoScaleBranch"] not in {"no-transferable-two-scale", "route-breaking-only"}),
        "cleanTransportFacingCount": sum(1 for row in case_rows if row["transportFacingFlag"]),
    }


def two_scale_verdict(metrics: dict) -> str:
    if metrics["transferableTrainTargetCount"] < 3 or metrics["cleanTransportFacingCount"] == 0:
        return "insufficient clean targets"
    if metrics["localOracleRepairCount"] > 0 and metrics["bestHoldoutImprovementPct"] < metrics["localTwoKernelOracleHoldoutImprovementPct"] - 10:
        return "local oracle only"
    if metrics["bestRoutePreservationRate"] < 0.95:
        return "route-breaking only"
    if metrics["bestScalarMarginPct"] < 10:
        return "scalar control sufficient"
    if metrics["bestNullMarginPct"] < 10:
        return "not above two-scale null"
    if (
        metrics["bestHoldoutImprovementPct"] >= 15
        and metrics["bestFrameworkHoldoutImprovementPct"] >= 25
        and metrics["bestProtectedRegressionOver2Rate"] < 0.05
        and metrics["bestMaxRegression"] <= 8
    ):
        return "transferable two-scale memory signal"
    return "not above two-scale null"


def two_scale_report(capsule: dict, rule_rows: list[dict], control_rows: list[dict], null_rows: list[dict], oracle_rows: list[dict], named_rows: list[dict]) -> str:
    metrics = capsule["metrics"]
    lines = [
        "# MTS Two-Scale Radial Memory Learnability Audit",
        "",
        "This diagnostic tests whether local two-kernel structure transfers from invariant state variables. Canonical MTS remains locked.",
        "",
        "## Headline",
        "",
        f"Verdict: **{capsule['verdict']}**.",
        f"Best candidate: `{metrics['bestCandidateId']}`.",
        f"Holdout gain: {fmt(metrics['bestHoldoutImprovementPct'])}%.",
        f"Framework-holdout gain: {fmt(metrics['bestFrameworkHoldoutImprovementPct'])}%.",
        f"Scalar-control gain: {fmt(metrics['scalarControlHoldoutImprovementPct'])}%.",
        f"Local two-kernel oracle gain: {fmt(metrics['localTwoKernelOracleHoldoutImprovementPct'])}%.",
        f"Best two-scale null gain: {fmt(metrics['bestNullHoldoutImprovementPct'])}%.",
        f"Transferable clean train targets: {metrics['transferableTrainTargetCount']}.",
        f"Clean transport-facing targets in v13: {metrics['cleanTransportFacingCount']}.",
        "",
        "## Transfer Rules",
        "",
        "| Rank | Candidate | Family | Target branch | Holdout gain | Framework gain | Route keep | Scalar margin | Null margin | Status |",
        "| ---: | --- | --- | --- | ---: | ---: | ---: | ---: | ---: | --- |",
    ]
    for index, row in enumerate(rule_rows[:12], start=1):
        lines.append(
            f"| {index} | `{row['candidateId']}` | {row['family']} | {row['targetBranch'] or '--'} | "
            f"{fmt(row['holdoutImprovementPct'])}% | {fmt(row['frameworkHoldoutImprovementPct'])}% | "
            f"{fmt(row['holdoutRoutePreservationRate'] * 100)}% | {fmt(row['scalarMarginPct'])} | "
            f"{fmt(row['nullMarginPct'])} | {row['claimStatus']} |"
        )
    lines.extend(
        [
            "",
            "## Controls",
            "",
            "| Control | Holdout gain | Framework gain | Route keep | Protected >2 | Max reg |",
            "| --- | ---: | ---: | ---: | ---: | ---: |",
        ]
    )
    for row in control_rows:
        lines.append(
            f"| {row['control']} | {fmt(row['holdoutImprovementPct'])}% | {fmt(row['frameworkHoldoutImprovementPct'])}% | "
            f"{fmt(row['holdoutRoutePreservationRate'] * 100)}% | {fmt(row['protectedClaimSafeLowLoadRegressionOver2Rate'] * 100)}% | "
            f"{fmt(row['holdoutMaxRegression'])} |"
        )
    lines.extend(
        [
            "",
            "## Null Controls",
            "",
            "| Null type | Median holdout gain | Max holdout gain | Median framework gain |",
            "| --- | ---: | ---: | ---: |",
        ]
    )
    for null_type in sorted({row["nullType"] for row in null_rows}):
        group = [row for row in null_rows if row["nullType"] == null_type]
        lines.append(
            f"| {null_type} | {fmt(safe_median(row['holdoutImprovementPct'] for row in group))}% | "
            f"{fmt(max(row['holdoutImprovementPct'] for row in group))}% | "
            f"{fmt(safe_median(row['frameworkHoldoutImprovementPct'] for row in group))}% |"
        )
    lines.extend(
        [
            "",
            "## Local Two-Kernel Oracle Ledger",
            "",
            "| Galaxy | Split | Branch | q RMSE | Two-kernel RMSE | Gain | eta | q2 | A2 share | Final class |",
            "| --- | --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | --- |",
        ]
    )
    for row in oracle_rows[:20]:
        lines.append(
            f"| {row['name']} | {row['split']} | {row['twoScaleBranch']} | {fmt(row['qShapeRmse'])} | "
            f"{fmt(row['twoKernelRmse'])} | {fmt(row['twoKernelGainOverQ'])} | {fmt(row['eta'])} | "
            f"{fmt(row['q2'])} | {fmt(row['a2Share'])} | {row['finalFailureClass']} |"
        )
    lines.extend(
        [
            "",
            "## Named Cases",
            "",
            "| Galaxy | Split | Local branch | Predicted branch | Baseline | Candidate | Local oracle | Route kept | Final class |",
            "| --- | --- | --- | --- | ---: | ---: | ---: | --- | --- |",
        ]
    )
    for row in named_rows:
        lines.append(
            f"| {row['name']} | {row['split']} | {row['localBranch']} | {row['predictedBranch']} | "
            f"{fmt(row['baselineRmse'])} | {fmt(row['candidateRmse'])} | {fmt(row['localTwoKernelRmse'])} | "
            f"{row['routePreserved']} | {row['finalFailureClass']} |"
        )
    lines.extend(
        [
            "",
            "## Discipline",
            "",
            "- Local two-kernel fits are oracle evidence only.",
            "- Transfer rules use clean train rows and coarse branch medians only.",
            "- Systematics, central-aperture/sampling, error-bar, and baryonic-floor cases are excluded from fitting evidence.",
            "- No galaxy name, raw RMSE, residual sign, or per-galaxy lookup enters transfer rules.",
            "- Canonical MTS remains locked.",
            "",
        ]
    )
    return "\n".join(lines)


def write_two_scale_artifacts(out_dir: Path, curves: list[dict], holdout_fraction: float) -> dict:
    deficit_rows = support_deficit_rows(curves)
    split = stratified_split(curves, SPLIT_SEED, holdout_fraction)
    case_rows = two_scale_case_rows(deficit_rows, split)
    train_rows = [row for row in case_rows if row["split"] == "train"]
    control_rows = two_scale_control_rows(curves, case_rows, deficit_rows, split)
    scalar_gain = next(row["holdoutImprovementPct"] for row in control_rows if row["control"] == "route-median-scalar-control")
    placeholder_null_gain = scalar_gain
    rule_objects = two_scale_candidate_rules(train_rows)
    preliminary = []
    score_by_rule = {}
    for rule in rule_objects:
        score_rows = two_scale_score_rows(curves, case_rows, split, rule, train_rows)
        score_by_rule[rule["id"]] = score_rows
        preliminary.append(two_scale_rule_record(rule, score_rows, scalar_gain, placeholder_null_gain, two_scale_training_leak_count(case_rows)))
    preliminary.sort(key=lambda row: (row["rankScore"], row["holdoutImprovementPct"], row["candidateId"]), reverse=True)
    best_rule_id = preliminary[0]["candidateId"] if preliminary else ""
    best_rule = next((rule for rule in rule_objects if rule["id"] == best_rule_id), two_scale_frequency_rule(train_rows))
    null_rows = two_scale_null_rows(curves, case_rows, split, best_rule, scalar_gain)
    null_gain = max([safe_median(row["holdoutImprovementPct"] for row in null_rows if row["nullType"] == null_type) for null_type in sorted({row["nullType"] for row in null_rows})] or [math.nan])
    rule_rows = []
    for rule in rule_objects:
        score_rows = score_by_rule.get(rule["id"]) or two_scale_score_rows(curves, case_rows, split, rule, train_rows)
        rule_rows.append(two_scale_rule_record(rule, score_rows, scalar_gain, null_gain, two_scale_training_leak_count(case_rows)))
    rule_rows.sort(key=lambda row: (row["rankScore"], row["holdoutImprovementPct"], row["candidateId"]), reverse=True)
    for index, row in enumerate(rule_rows, start=1):
        row["rank"] = index
    best_rule_id = rule_rows[0]["candidateId"] if rule_rows else ""
    best_rule = next((rule for rule in rule_objects if rule["id"] == best_rule_id), two_scale_frequency_rule(train_rows))
    best_score_rows = score_by_rule.get(best_rule_id) or two_scale_score_rows(curves, case_rows, split, best_rule, train_rows)
    oracle_rows = two_scale_oracle_ledger(case_rows)
    named_rows = two_scale_named_case_rows(best_score_rows, case_rows)
    metrics = two_scale_metrics(rule_rows, control_rows, null_rows, case_rows)
    verdict = two_scale_verdict(metrics)
    capsule = {
        "type": "mts-two-scale-radial-memory-learnability-audit",
        "version": 1,
        "generatedAt": dt.datetime.now(dt.UTC).isoformat(),
        "sourceScript": "scripts/mts-failure-lab.py",
        "canonicalMtsStatus": "locked",
        "split": {
            "seed": split["seed"],
            "holdoutFraction": split["holdoutFraction"],
            "trainCount": len(split["train"]),
            "holdoutCount": len(split["holdout"]),
        },
        "verdict": verdict,
        "metrics": metrics,
        "ruleCount": len(rule_rows),
        "rules": {
            "candidateForm": "q1 = q_default; transferred eta/q2/A2-share; locked-route scalar amplitude; route-safe projection",
            "forbiddenVariables": ["galaxy name", "raw RMSE", "residual sign", "per-galaxy lookup"],
            "excludedTrainingClasses": sorted(DATA_SYSTEMATICS_FINAL_CLASSES),
        },
    }
    out_dir.mkdir(parents=True, exist_ok=True)
    write_csv(out_dir / "mts-two-scale-cases.csv", case_rows)
    write_csv(out_dir / "mts-two-scale-transfer-rules.csv", rule_rows)
    write_csv(out_dir / "mts-two-scale-scores.csv", best_score_rows)
    write_csv(out_dir / "mts-two-scale-null-controls.csv", null_rows)
    write_csv(out_dir / "mts-two-scale-oracle-ledger.csv", oracle_rows)
    write_csv(out_dir / "mts-two-scale-named-cases.csv", named_rows)
    (out_dir / "mts-two-scale-audit-report.md").write_text(
        two_scale_report(capsule, rule_rows, control_rows, null_rows, oracle_rows, named_rows),
        encoding="utf-8",
    )
    (out_dir / "mts-two-scale-audit-capsule.json").write_text(json.dumps(json_clean(capsule), indent=2), encoding="utf-8")
    return capsule


def metadata_component_stats(curve: dict, key: str) -> dict:
    points = curve["points"]
    count = len(points)
    finite = [point for point in points if isinstance(point.get(key), (int, float)) and math.isfinite(point[key])]
    active = [point for point in finite if abs(point[key]) > 1e-9]
    return {
        f"{key}CoveragePct": 100.0 * len(finite) / count if count else math.nan,
        f"{key}ActivePct": 100.0 * len(active) / count if count else math.nan,
        f"{key}Active": bool(active),
    }


def metadata_local_readiness(curve: dict) -> dict:
    points = curve["points"]
    point_count = len(points)
    err_points = [
        point
        for point in points
        if isinstance(point.get("err"), (int, float)) and math.isfinite(point["err"]) and point["err"] > 0
    ]
    gas = metadata_component_stats(curve, "vGas")
    disk = metadata_component_stats(curve, "vDisk")
    bulge = metadata_component_stats(curve, "vBulge")
    has_distance = isinstance(curve.get("distanceMpc"), (int, float)) and math.isfinite(curve["distanceMpc"])
    has_err = len(err_points) == point_count and point_count > 0
    has_components = gas["vGasCoveragePct"] == 100.0 and disk["vDiskCoveragePct"] == 100.0 and bulge["vBulgeCoveragePct"] == 100.0
    return {
        "sourcePath": str(SAMPLES_JS.relative_to(ROOT)),
        "sampleFormat": "SPARC-style ROTMOD table",
        "distanceHeaderAvailable": has_distance,
        "distanceMpc": curve.get("distanceMpc", math.nan),
        "errVAvailable": has_err,
        "errVCoveragePct": 100.0 * len(err_points) / point_count if point_count else math.nan,
        "pointCount": point_count,
        "baryonicComponentColumnsAvailable": has_components,
        "gasComponentActive": gas["vGasActive"],
        "diskComponentActive": disk["vDiskActive"],
        "bulgeComponentActive": bulge["vBulgeActive"],
        "gasCoveragePct": gas["vGasCoveragePct"],
        "diskCoveragePct": disk["vDiskCoveragePct"],
        "bulgeCoveragePct": bulge["vBulgeCoveragePct"],
        "gasActivePct": gas["vGasActivePct"],
        "diskActivePct": disk["vDiskActivePct"],
        "bulgeActivePct": bulge["vBulgeActivePct"],
        "localScienceStructureUsable": bool(has_distance and has_err and has_components),
        "missingInclinationMetadata": True,
        "missingBeamFwhmMetadata": True,
        "missingQualityFlags": True,
        "missingCovarianceMetadata": True,
        "missingDecompositionProvenance": True,
        "missingMlPriorProvenance": True,
        "missingRotationExtractionMetadata": True,
        "missingAsymmetricDriftMetadata": True,
        "missingBarWarpMetadata": True,
        "missingReductionProvenance": True,
    }


def metadata_evidence_bucket(row: dict) -> str:
    if row["systematicsClass"] == "M/L-sensitive":
        return "M/L-sensitive"
    if row["systematicsClass"] == "velocity-scale-sensitive":
        return "velocity-scale proxy sensitive"
    if row["finalFailureClass"] == "error-bar dominated" or row["systematicsClass"] == "error-bar dominated":
        return "error-bar dominated"
    if row["finalFailureClass"] == "baryonic-floor limited" or (
        row.get("positiveSupportImpossible") and row.get("postShapeRmse", 0) >= RESIDUAL_REPAIR_RMSE
    ):
        return "baryonic-floor limited"
    if row["finalFailureClass"] == "central-aperture/sampling dominated" or row.get("centralApertureFlag") or row.get("samplingFacingFlag"):
        return "central-aperture/sampling dominated"
    if row["finalFailureClass"] in {"baseline acceptable", "shape-diagnostic repaired"} and row["bestRobustRmse"] < RESIDUAL_REPAIR_RMSE:
        return "metadata-ready claim-safe"
    return "specific systematics unresolved"


def metadata_needed_fields(row: dict, bucket: str) -> list[str]:
    fields: list[str] = []

    def add(*items: str) -> None:
        for item in items:
            if item not in fields:
                fields.append(item)

    if bucket == "M/L-sensitive":
        add(
            "stellar M/L prior and bandpass",
            "bulge/disk decomposition provenance",
            "stellar population calibration",
            "survey/reduction provenance",
        )
    elif bucket == "velocity-scale proxy sensitive":
        add(
            "inclination and inclination source",
            "rotation-curve extraction method",
            "bar/warp/non-circular-motion flags",
            "survey/reduction provenance",
        )
    elif bucket == "baryonic-floor limited":
        add(
            "central mass-model provenance",
            "stellar M/L prior and bandpass",
            "beam/FWHM or aperture metadata",
            "covariance/error model",
            "survey/reduction provenance",
        )
    elif bucket == "central-aperture/sampling dominated":
        add(
            "beam/FWHM or spatial resolution",
            "aperture/PSF or beam-smearing correction",
            "radial sampling and covariance model",
            "bar/warp/non-circular-motion flags",
            "rotation-curve extraction method",
            "survey/reduction provenance",
        )
    elif bucket == "error-bar dominated":
        add(
            "covariance/error model",
            "error-floor provenance",
            "quality flags",
            "rotation-curve extraction method",
            "survey/reduction provenance",
        )
    elif bucket == "specific systematics unresolved":
        add(
            "inclination and distance provenance",
            "beam/FWHM or spatial resolution",
            "stellar M/L and decomposition provenance",
            "covariance/error model",
            "quality flags and reduction provenance",
        )
    elif row["baselineRmse"] >= 30 or row["postShapeRmse"] >= RESIDUAL_REPAIR_RMSE:
        add("quality flags", "survey/reduction provenance")

    if row.get("bestSystematicsKind") == "baryon-scale":
        add("baryonic mass-model normalization provenance")
    if row.get("innerComponentStressClass") in {
        "bulge-dominated central systematics",
        "disk-dominated central systematics",
        "mixed central mass-model sensitive",
    }:
        add("component decomposition uncertainty")
    if row.get("innerKinematicClass") in {"inner-velocity spike dominated", "inner-aperture proxy sensitive"}:
        add("inner kinematic extraction/aperture provenance")
    return fields


def metadata_blocking_question(bucket: str) -> str:
    return {
        "M/L-sensitive": "Do external M/L priors and decomposition choices remove the support deficit without changing MTS?",
        "velocity-scale proxy sensitive": "Does inclination or velocity-normalization provenance explain the observed-velocity scale sensitivity?",
        "baryonic-floor limited": "Do central mass-model and beam/aperture choices explain baryons exceeding the observed curve?",
        "central-aperture/sampling dominated": "Are central aperture, beam smearing, non-circular motion, or dense inner sampling dominating unweighted RMSE?",
        "error-bar dominated": "Does the published covariance/error model make the residual statistically non-robust?",
        "metadata-ready claim-safe": "Is external provenance only needed for release-grade reproducibility rather than current claim safety?",
        "specific systematics unresolved": "Which missing observational assumption is controlling the remaining diagnostic sensitivity?",
    }.get(bucket, "Which missing observational assumption controls this case?")


def metadata_priority_reason(row: dict, bucket: str) -> list[str]:
    reasons = []
    if row["name"] in METADATA_NAMED_CASES:
        reasons.append("named case")
    if row["baselineRmse"] >= 30:
        reasons.append("high baseline RMSE")
    if row["postShapeRmse"] >= RESIDUAL_REPAIR_RMSE:
        reasons.append("remaining post-shape failure")
    if bucket != "metadata-ready claim-safe":
        reasons.append(bucket)
    if reasons and row.get("routeMismatch"):
        reasons.append("locked/observed route mismatch")
    return reasons


def metadata_priority_score(row: dict, bucket: str, reasons: list[str]) -> float:
    score = row["baselineRmse"] / 10.0
    score += 20.0 if row["name"] in METADATA_NAMED_CASES else 0.0
    score += 12.0 if row["postShapeRmse"] >= RESIDUAL_REPAIR_RMSE else 0.0
    score += 8.0 if bucket != "metadata-ready claim-safe" else 0.0
    score += 5.0 if row.get("routeMismatch") else 0.0
    score += 3.0 if row["baselineRmse"] >= 30 else 0.0
    return score


def metadata_readiness_rows(curves: list[dict], deficit_rows: list[dict], split: dict) -> list[dict]:
    split_deficit_rows(deficit_rows, split)
    curves_by_name = {curve["name"]: curve for curve in curves}
    rows = []
    for row in sorted(deficit_rows, key=lambda item: item["name"]):
        curve = curves_by_name[row["name"]]
        local = metadata_local_readiness(curve)
        bucket = metadata_evidence_bucket(row)
        needed = metadata_needed_fields(row, bucket)
        priority_reasons = metadata_priority_reason(row, bucket)
        metadata_dependent_failure = bool(row["postShapeRmse"] >= RESIDUAL_REPAIR_RMSE and needed)
        rows.append(
            {
                "name": row["name"],
                "split": row["split"],
                "evidenceBucket": bucket,
                "priorityCase": bool(priority_reasons),
                "priorityScore": metadata_priority_score(row, bucket, priority_reasons),
                "priorityReason": "; ".join(priority_reasons),
                "metadataDependentFailure": metadata_dependent_failure,
                "neededExternalMetadata": "; ".join(needed),
                "neededExternalMetadataCount": len(needed),
                "blockingQuestion": metadata_blocking_question(bucket),
                **local,
                "route": row["route"],
                "lockedRoute": row["baselineModelRoute"],
                "routeMismatch": row["routeMismatch"],
                "finalFailureClass": row["finalFailureClass"],
                "claimSafeStatus": row["claimSafeStatus"],
                "systematicsClass": row["systematicsClass"],
                "innerLeverageClass": row["innerLeverageClass"],
                "innerComponentStressClass": row["innerComponentStressClass"],
                "innerKinematicClass": row["innerKinematicClass"],
                "componentFloorClass": row["componentFloorClass"],
                "baselineRmse": row["baselineRmse"],
                "postShapeRmse": row["postShapeRmse"],
                "bestDiagnosticRmse": row["bestDiagnosticRmse"],
                "bestDiagnosticSource": row["bestDiagnosticSource"],
                "bestRobustRmse": row["bestRobustRmse"],
                "bestRobustSource": row["bestRobustSource"],
                "weightedPostShapeRmse": row["weightedPostShapeRmse"],
                "bestSystematicsRmse": row["bestSystematicsRmse"],
                "bestSystematicsKind": row["bestSystematicsKind"],
                "bestSystematicsParams": row["bestSystematicsParams"],
                "mlStressRmse": row["mlStressRmse"],
                "mlStressParams": row["mlStressParams"],
                "velocityScaleStressRmse": row["velocityScaleStressRmse"],
                "velocityScaleStressParams": row["velocityScaleStressParams"],
                "baryonScaleStressRmse": row["baryonScaleStressRmse"],
                "baryonScaleStressParams": row["baryonScaleStressParams"],
                "positiveSupportImpossible": row["positiveSupportImpossible"],
                "baryonFloorViolationRate": row["baryonFloorViolationRate"],
                "baryonFloorPointCount": row["baryonFloorPointCount"],
                "centralFloorPointCount": row["centralFloorPointCount"],
                "innerPointFraction": row["innerPointFraction"],
                "innerSseFraction": row["innerSseFraction"],
                "worstPointLeveragePct": row["worstPointLeveragePct"],
                "top3ResidualLeveragePct": row["top3ResidualLeveragePct"],
                "radialBinnedPostShapeRmse": row["radialBinnedPostShapeRmse"],
                "trim90PostShapeRmse": row["trim90PostShapeRmse"],
                "transportFacingFlag": row["transportFacingFlag"],
                "systematicsFacingFlag": row["systematicsFacingFlag"],
                "samplingFacingFlag": row["samplingFacingFlag"],
                "centralApertureFlag": row["centralApertureFlag"],
                "baryonicFloorFlag": row["baryonicFloorFlag"],
            }
        )
    return rows


def metadata_systematics_ledger(readiness_rows: list[dict]) -> list[dict]:
    rows = []
    for row in readiness_rows:
        rows.append(
            {
                "name": row["name"],
                "split": row["split"],
                "evidenceBucket": row["evidenceBucket"],
                "finalFailureClass": row["finalFailureClass"],
                "systematicsClass": row["systematicsClass"],
                "innerLeverageClass": row["innerLeverageClass"],
                "innerComponentStressClass": row["innerComponentStressClass"],
                "innerKinematicClass": row["innerKinematicClass"],
                "baselineRmse": row["baselineRmse"],
                "postShapeRmse": row["postShapeRmse"],
                "bestDiagnosticRmse": row["bestDiagnosticRmse"],
                "bestDiagnosticSource": row["bestDiagnosticSource"],
                "bestRobustRmse": row["bestRobustRmse"],
                "bestRobustSource": row["bestRobustSource"],
                "bestSystematicsKind": row["bestSystematicsKind"],
                "bestSystematicsRmse": row["bestSystematicsRmse"],
                "bestSystematicsParams": row["bestSystematicsParams"],
                "metadataDependentFailure": row["metadataDependentFailure"],
                "neededExternalMetadata": row["neededExternalMetadata"],
                "blockingQuestion": row["blockingQuestion"],
            }
        )
    rows.sort(key=lambda item: (item["evidenceBucket"], -item["baselineRmse"], item["name"]))
    return rows


def metadata_shopping_list(readiness_rows: list[dict]) -> list[dict]:
    rows = []
    for row in readiness_rows:
        if not row["priorityCase"]:
            continue
        rows.append(
            {
                "name": row["name"],
                "priorityScore": row["priorityScore"],
                "priorityReason": row["priorityReason"],
                "evidenceBucket": row["evidenceBucket"],
                "neededExternalMetadata": row["neededExternalMetadata"],
                "blockingQuestion": row["blockingQuestion"],
                "sourcePath": row["sourcePath"],
                "localDistanceAvailable": row["distanceHeaderAvailable"],
                "localErrVAvailable": row["errVAvailable"],
                "localComponentsAvailable": row["baryonicComponentColumnsAvailable"],
            }
        )
    rows.sort(key=lambda item: (-item["priorityScore"], item["name"]))
    return rows


def metadata_priority_rows(readiness_rows: list[dict]) -> list[dict]:
    rows = [
        {
            "name": row["name"],
            "split": row["split"],
            "priorityScore": row["priorityScore"],
            "priorityReason": row["priorityReason"],
            "evidenceBucket": row["evidenceBucket"],
            "finalFailureClass": row["finalFailureClass"],
            "baselineRmse": row["baselineRmse"],
            "postShapeRmse": row["postShapeRmse"],
            "bestDiagnosticRmse": row["bestDiagnosticRmse"],
            "bestDiagnosticSource": row["bestDiagnosticSource"],
            "bestRobustRmse": row["bestRobustRmse"],
            "bestRobustSource": row["bestRobustSource"],
            "neededExternalMetadata": row["neededExternalMetadata"],
            "blockingQuestion": row["blockingQuestion"],
        }
        for row in readiness_rows
        if row["priorityCase"]
    ]
    rows.sort(key=lambda item: (-item["priorityScore"], item["name"]))
    return rows


def metadata_bucket_summary(readiness_rows: list[dict]) -> list[dict]:
    groups: dict[str, list[dict]] = {}
    for row in readiness_rows:
        groups.setdefault(row["evidenceBucket"], []).append(row)
    summary = []
    for bucket, group in sorted(groups.items()):
        summary.append(
            {
                "evidenceBucket": bucket,
                "count": len(group),
                "highRmseCount": sum(1 for row in group if row["baselineRmse"] >= 30),
                "postShapeFailureCount": sum(1 for row in group if row["postShapeRmse"] >= RESIDUAL_REPAIR_RMSE),
                "metadataDependentFailureCount": sum(1 for row in group if row["metadataDependentFailure"]),
                "baselineMean": safe_mean(row["baselineRmse"] for row in group),
                "postShapeMean": safe_mean(row["postShapeRmse"] for row in group),
                "bestRobustMean": safe_mean(row["bestRobustRmse"] for row in group),
                "neededMetadataMean": safe_mean(row["neededExternalMetadataCount"] for row in group),
            }
        )
    return summary


def read_json_if_exists(path: Path) -> dict:
    if not path.exists():
        return {}
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}


def metadata_prior_audit_statuses() -> list[dict]:
    specs = [
        (
            "q-state closure",
            DEFAULT_QCLOSURE_OUT / "mts-q-closure-capsule.json",
            {"promoted for review"},
            True,
        ),
        (
            "q-gate",
            DEFAULT_QGATE_OUT / "mts-q-gate-capsule.json",
            {"promoted for review"},
            True,
        ),
        (
            "q-branch+amplitude closure",
            DEFAULT_QAMP_CLOSURE_OUT / "mts-q-amp-closure-capsule.json",
            set(),
            False,
        ),
        (
            "q-branch+amplitude robustness",
            DEFAULT_QAMP_STRESS_OUT / "mts-q-amp-robustness-capsule.json",
            {"robust for review"},
            False,
        ),
        (
            "amplitude gate",
            DEFAULT_AMP_GATE_AUDIT_OUT / "mts-amp-gate-audit-capsule.json",
            {"robust amplitude closure signal"},
            False,
        ),
        (
            "scalar support normalization",
            DEFAULT_SCALAR_CLOSURE_AUDIT_OUT / "mts-scalar-closure-capsule.json",
            {"robust scalar normalization signal"},
            False,
        ),
        (
            "route-state closure",
            DEFAULT_ROUTE_STATE_AUDIT_OUT / "mts-route-state-audit-capsule.json",
            {"route-state closure signal"},
            False,
        ),
        (
            "two-scale radial memory",
            DEFAULT_TWO_SCALE_AUDIT_OUT / "mts-two-scale-audit-capsule.json",
            {"transferable two-scale memory signal"},
            False,
        ),
    ]
    rows = []
    for label, path, pass_values, count_promoted in specs:
        capsule = read_json_if_exists(path)
        best = capsule.get("bestCandidate") if isinstance(capsule.get("bestCandidate"), dict) else {}
        status = (
            capsule.get("verdict")
            or capsule.get("robustnessVerdict")
            or capsule.get("auditVerdict")
            or best.get("claimStatus")
            or "unavailable"
        )
        promoted_count = capsule.get("promotedCount", 0)
        passed = bool(status in pass_values or (count_promoted and promoted_count))
        rows.append(
            {
                "audit": label,
                "path": str(path.relative_to(ROOT)),
                "status": status,
                "passedClosureGate": passed,
                "available": bool(capsule),
            }
        )
    return rows


def metadata_audit_verdict(readiness_rows: list[dict], prior_rows: list[dict]) -> str:
    post_shape_failures = [row for row in readiness_rows if row["postShapeRmse"] >= RESIDUAL_REPAIR_RMSE]
    metadata_dependent = [row for row in post_shape_failures if row["metadataDependentFailure"]]
    transport_count = sum(1 for row in readiness_rows if row["transportFacingFlag"])
    passed_prior = sum(1 for row in prior_rows if row["passedClosureGate"])
    dependency_rate = len(metadata_dependent) / len(post_shape_failures) if post_shape_failures else 0.0
    if transport_count == 0 and dependency_rate > 0.5 and passed_prior == 0:
        return "metadata-limited, fetch external provenance next"
    if transport_count == 0 and not post_shape_failures and passed_prior == 0:
        return "local sample sufficient for claim-safe summary"
    if transport_count == 0 and passed_prior == 0:
        return "specific systematics unresolved"
    if transport_count == 0 and dependency_rate <= 0.5:
        return "ready for external validation set"
    return "specific systematics unresolved"


def metadata_audit_report(
    capsule: dict,
    readiness_rows: list[dict],
    evidence_rows: list[dict],
    shopping_rows: list[dict],
    priority_rows: list[dict],
) -> str:
    metrics = capsule["metrics"]
    bucket_summary = capsule["bucketSummary"]
    prior_rows = capsule["priorClosureAudits"]
    named = [row for row in priority_rows if row["name"] in METADATA_NAMED_CASES]
    named.sort(key=lambda row: METADATA_NAMED_CASES.index(row["name"]))
    lines = [
        "# MTS Observational Metadata And Systematics Evidence Audit",
        "",
        "This diagnostic asks whether the remaining apparent failures require missing observational metadata rather than another MTS closure law. Canonical MTS remains locked.",
        "",
        "## Headline",
        "",
        f"Verdict: **{capsule['verdict']}**.",
        f"Transport-facing unresolved systems after the v13 claim gate: {metrics['transportFacingUnresolvedCount']}.",
        f"Post-shape failures: {metrics['postShapeFailureCount']}.",
        f"Metadata-dependent post-shape failures: {metrics['metadataDependentPostShapeFailureCount']} ({fmt(metrics['metadataDependentPostShapeFailureRate'] * 100)}%).",
        f"Prior closure audits passing promotion/robustness gates: {metrics['priorClosurePassedCount']}.",
        f"Local sample rows with distance, errors, and baryonic component columns: {metrics['localScienceStructureUsableCount']}/{metrics['totalCount']}.",
        "",
        "## Metadata Readiness",
        "",
        "The local ROTMOD sample provides distance headers, `errV`, and gas/disk/bulge component columns. It does not provide inclination provenance, beam/FWHM, covariance, quality flags, reduction provenance, or decomposition/M/L provenance.",
        "",
        "| Evidence bucket | Count | High RMSE | Post-shape failures | Metadata-dependent failures | Baseline mean | Post-shape mean | Robust mean | Needed fields mean |",
        "| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
    ]
    for row in bucket_summary:
        lines.append(
            f"| {row['evidenceBucket']} | {row['count']} | {row['highRmseCount']} | {row['postShapeFailureCount']} | "
            f"{row['metadataDependentFailureCount']} | {fmt(row['baselineMean'])} | {fmt(row['postShapeMean'])} | "
            f"{fmt(row['bestRobustMean'])} | {fmt(row['neededMetadataMean'])} |"
        )
    lines.extend(
        [
            "",
            "## Prior Closure Gate",
            "",
            "| Audit | Status | Passed gate | Available |",
            "| --- | --- | --- | --- |",
        ]
    )
    for row in prior_rows:
        lines.append(f"| {row['audit']} | {row['status']} | {row['passedClosureGate']} | {row['available']} |")
    lines.extend(
        [
            "",
            "## Priority Cases",
            "",
            "| Galaxy | Bucket | Final class | Baseline | Post-shape | Best diagnostic | Best robust | Needed metadata |",
            "| --- | --- | --- | ---: | ---: | ---: | ---: | --- |",
        ]
    )
    for row in priority_rows[:20]:
        lines.append(
            f"| {row['name']} | {row['evidenceBucket']} | {row['finalFailureClass']} | {fmt(row['baselineRmse'])} | "
            f"{fmt(row['postShapeRmse'])} | {fmt(row['bestDiagnosticRmse'])} ({row['bestDiagnosticSource']}) | "
            f"{fmt(row['bestRobustRmse'])} ({row['bestRobustSource']}) | {row['neededExternalMetadata']} |"
        )
    lines.extend(
        [
            "",
            "## Named Case Read",
            "",
            "| Galaxy | Bucket | Final class | Blocking question | Needed metadata |",
            "| --- | --- | --- | --- | --- |",
        ]
    )
    for row in named:
        lines.append(
            f"| {row['name']} | {row['evidenceBucket']} | {row['finalFailureClass']} | "
            f"{row['blockingQuestion']} | {row['neededExternalMetadata']} |"
        )
    lines.extend(
        [
            "",
            "## External Metadata Shopping List",
            "",
            "| Galaxy | Reason | Needed metadata | Local distance | Local errV | Local components |",
            "| --- | --- | --- | --- | --- | --- |",
        ]
    )
    for row in shopping_rows[:20]:
        lines.append(
            f"| {row['name']} | {row['priorityReason']} | {row['neededExternalMetadata']} | "
            f"{row['localDistanceAvailable']} | {row['localErrVAvailable']} | {row['localComponentsAvailable']} |"
        )
    lines.extend(
        [
            "",
            "## Systematics Evidence Ledger",
            "",
            "| Galaxy | Bucket | Systematics | Inner leverage | Inner kinematics | Best systematics | Metadata dependent |",
            "| --- | --- | --- | --- | --- | ---: | --- |",
        ]
    )
    for row in evidence_rows[:24]:
        lines.append(
            f"| {row['name']} | {row['evidenceBucket']} | {row['systematicsClass']} | {row['innerLeverageClass']} | "
            f"{row['innerKinematicClass']} | {fmt(row['bestSystematicsRmse'])} ({row['bestSystematicsKind']}) | "
            f"{row['metadataDependentFailure']} |"
        )
    lines.extend(
        [
            "",
            "## Claim-Safe Interpretation",
            "",
            "- The local sample is strong enough to reproduce the current claim-safe summary, but not strong enough to prove the detailed observational cause for every high-RMSE central/systematics case.",
            "- The next external work should fetch inclination, beam/aperture, decomposition, covariance, and reduction provenance for the priority ledger before treating any remaining residual as transport-facing.",
            "- No formula is promoted here; this audit is a provenance and systematics readiness gate.",
            "",
        ]
    )
    return "\n".join(lines)


def write_metadata_audit_artifacts(out_dir: Path, curves: list[dict], holdout_fraction: float) -> dict:
    deficit_rows = support_deficit_rows(curves)
    split = stratified_split(curves, SPLIT_SEED, holdout_fraction)
    readiness_rows = metadata_readiness_rows(curves, deficit_rows, split)
    evidence_rows = metadata_systematics_ledger(readiness_rows)
    shopping_rows = metadata_shopping_list(readiness_rows)
    priority_rows = metadata_priority_rows(readiness_rows)
    prior_rows = metadata_prior_audit_statuses()
    post_shape_failures = [row for row in readiness_rows if row["postShapeRmse"] >= RESIDUAL_REPAIR_RMSE]
    metadata_dependent = [row for row in post_shape_failures if row["metadataDependentFailure"]]
    capsule = {
        "type": "mts-observational-metadata-systematics-evidence-audit",
        "version": 1,
        "generatedAt": dt.datetime.now(dt.UTC).isoformat(),
        "sourceScript": "scripts/mts-failure-lab.py",
        "canonicalMtsStatus": "locked",
        "split": {
            "seed": split["seed"],
            "holdoutFraction": split["holdoutFraction"],
            "trainCount": len(split["train"]),
            "holdoutCount": len(split["holdout"]),
        },
        "verdict": metadata_audit_verdict(readiness_rows, prior_rows),
        "metrics": {
            "totalCount": len(readiness_rows),
            "transportFacingUnresolvedCount": sum(1 for row in readiness_rows if row["transportFacingFlag"]),
            "postShapeFailureCount": len(post_shape_failures),
            "metadataDependentPostShapeFailureCount": len(metadata_dependent),
            "metadataDependentPostShapeFailureRate": len(metadata_dependent) / len(post_shape_failures) if post_shape_failures else 0.0,
            "localScienceStructureUsableCount": sum(1 for row in readiness_rows if row["localScienceStructureUsable"]),
            "priorityCaseCount": len(priority_rows),
            "priorClosurePassedCount": sum(1 for row in prior_rows if row["passedClosureGate"]),
        },
        "bucketSummary": metadata_bucket_summary(readiness_rows),
        "priorClosureAudits": prior_rows,
        "rules": {
            "claimStatus": "diagnostic only",
            "forbiddenInterpretation": "missing observational metadata cannot become a hidden MTS support correction",
            "missingLocalMetadata": [
                "inclination provenance",
                "beam/FWHM or aperture metadata",
                "covariance/error model",
                "quality flags",
                "M/L and decomposition provenance",
                "survey/reduction provenance",
            ],
        },
    }
    out_dir.mkdir(parents=True, exist_ok=True)
    write_csv(out_dir / "mts-metadata-readiness.csv", readiness_rows)
    write_csv(out_dir / "mts-systematics-evidence-ledger.csv", evidence_rows)
    write_csv(out_dir / "mts-external-metadata-shopping-list.csv", shopping_rows)
    write_csv(out_dir / "mts-metadata-priority-cases.csv", priority_rows)
    (out_dir / "mts-metadata-audit-report.md").write_text(
        metadata_audit_report(capsule, readiness_rows, evidence_rows, shopping_rows, priority_rows),
        encoding="utf-8",
    )
    (out_dir / "mts-metadata-audit-capsule.json").write_text(json.dumps(json_clean(capsule), indent=2), encoding="utf-8")
    return capsule


def metadata_crosswalk_schema() -> dict:
    field_specs = {
        "name": ("string", "Galaxy identifier matching the local sample name.", True, ""),
        "inclinationDeg": ("number", "Inclination angle in degrees.", False, "deg"),
        "inclinationSource": ("string", "Reference or catalogue source for inclination.", False, ""),
        "inclinationUncertaintyDeg": ("number", "Inclination uncertainty in degrees.", False, "deg"),
        "distanceMpc": ("number", "Distance in megaparsecs.", False, "Mpc"),
        "distanceSource": ("string", "Reference or catalogue source for distance.", False, ""),
        "distanceUncertaintyMpc": ("number", "Distance uncertainty in megaparsecs.", False, "Mpc"),
        "beamFwhmArcsec": ("number", "Beam FWHM or effective aperture in arcsec.", False, "arcsec"),
        "spatialResolutionKpc": ("number", "Physical spatial resolution in kpc.", False, "kpc"),
        "beamSource": ("string", "Reference/source for beam or aperture metadata.", False, ""),
        "mlDisk": ("number", "External disk stellar mass-to-light prior.", False, ""),
        "mlBulge": ("number", "External bulge stellar mass-to-light prior.", False, ""),
        "mlPriorSource": ("string", "Reference/source for stellar M/L prior.", False, ""),
        "decompositionSource": ("string", "Reference/source for bulge/disk decomposition.", False, ""),
        "covarianceAvailable": ("boolean", "Whether covariance or a detailed error model is available.", False, "true|false"),
        "errorModelSource": ("string", "Reference/source for errors or covariance.", False, ""),
        "qualityFlags": ("string", "Quality flags relevant to the rotation curve.", False, ""),
        "barWarpNonCircularFlags": ("string", "Bars, warps, non-circular motion, or asymmetry notes.", False, ""),
        "asymmetricDriftCorrection": ("string", "Asymmetric drift or pressure support correction provenance.", False, ""),
        "rotationCurveExtractionSource": ("string", "Reference/source for rotation-curve extraction method.", False, ""),
        "reductionPipelineSource": ("string", "Survey release or reduction pipeline provenance.", False, ""),
        "notes": ("string", "Free notes for human review.", False, ""),
    }
    return {
        "type": "mts-external-metadata-schema",
        "version": 1,
        "canonicalMtsStatus": "locked",
        "fields": [
            {
                "name": name,
                "type": field_specs[name][0],
                "description": field_specs[name][1],
                "required": field_specs[name][2],
                "unit": field_specs[name][3],
            }
            for name in METADATA_EXTERNAL_FIELDS
        ],
        "diagnosticOnly": True,
    }


def metadata_blank_template_rows(priority_rows: list[dict]) -> list[dict]:
    rows = []
    for row in priority_rows:
        item = {field: "" for field in METADATA_EXTERNAL_FIELDS}
        item.update(
            {
                "name": row["name"],
                "notes": f"{row['evidenceBucket']}; needed: {row['neededExternalMetadata']}",
            }
        )
        rows.append(item)
    return rows


def metadata_read_external(path: Path | None) -> tuple[list[dict], list[dict]]:
    if path is None:
        return [], []
    rows = []
    errors = []
    if not path.exists():
        return [], [
            {
                "name": "",
                "field": "metadataFile",
                "severity": "error",
                "message": f"Metadata file not found: {path}",
            }
        ]
    with path.open(newline="", encoding="utf-8-sig") as handle:
        reader = csv.DictReader(handle)
        headers = reader.fieldnames or []
        for field in METADATA_EXTERNAL_FIELDS:
            if field not in headers:
                errors.append(
                    {
                        "name": "",
                        "field": field,
                        "severity": "error" if field == "name" else "warning",
                        "message": f"Missing metadata column: {field}",
                    }
                )
        for index, raw in enumerate(reader, start=2):
            row = {field: (raw.get(field, "") or "").strip() for field in METADATA_EXTERNAL_FIELDS}
            row["_rowNumber"] = index
            rows.append(row)
    return rows, errors


def metadata_parse_float(value: object) -> float:
    text = str(value or "").strip()
    if not text:
        return math.nan
    try:
        return float(text)
    except ValueError:
        return math.nan


def metadata_parse_bool(value: object) -> bool | None:
    text = str(value or "").strip().lower()
    if not text:
        return None
    if text in {"1", "true", "yes", "y", "available"}:
        return True
    if text in {"0", "false", "no", "n", "none", "unavailable"}:
        return False
    return None


def metadata_has_text(row: dict, field: str) -> bool:
    return bool(str(row.get(field, "") or "").strip())


def metadata_has_positive_number(row: dict, field: str) -> bool:
    value = metadata_parse_float(row.get(field, ""))
    return math.isfinite(value) and value > 0


def metadata_case_support_flags(meta: dict) -> dict:
    covariance = metadata_parse_bool(meta.get("covarianceAvailable"))
    return {
        "hasInclinationEvidence": metadata_has_positive_number(meta, "inclinationDeg") and metadata_has_text(meta, "inclinationSource"),
        "hasDistanceEvidence": metadata_has_positive_number(meta, "distanceMpc") and metadata_has_text(meta, "distanceSource"),
        "hasBeamEvidence": (
            (metadata_has_positive_number(meta, "beamFwhmArcsec") or metadata_has_positive_number(meta, "spatialResolutionKpc"))
            and metadata_has_text(meta, "beamSource")
        ),
        "hasMlEvidence": (
            (metadata_has_positive_number(meta, "mlDisk") or metadata_has_positive_number(meta, "mlBulge"))
            and metadata_has_text(meta, "mlPriorSource")
        ),
        "hasDecompositionEvidence": metadata_has_text(meta, "decompositionSource"),
        "hasCovarianceEvidence": covariance is True and metadata_has_text(meta, "errorModelSource"),
        "hasQualityEvidence": metadata_has_text(meta, "qualityFlags"),
        "hasNonCircularEvidence": metadata_has_text(meta, "barWarpNonCircularFlags"),
        "hasExtractionEvidence": metadata_has_text(meta, "rotationCurveExtractionSource"),
        "hasReductionEvidence": metadata_has_text(meta, "reductionPipelineSource"),
        "hasAsymmetricDriftEvidence": metadata_has_text(meta, "asymmetricDriftCorrection"),
    }


def metadata_required_support(row: dict) -> list[str]:
    bucket = row["evidenceBucket"]
    if bucket == "M/L-sensitive":
        return ["hasMlEvidence", "hasDecompositionEvidence"]
    if bucket == "velocity-scale proxy sensitive":
        return ["hasInclinationEvidence", "hasExtractionEvidence"]
    if bucket == "central-aperture/sampling dominated":
        return ["hasBeamEvidence", "hasExtractionEvidence", "hasQualityEvidence"]
    if bucket == "error-bar dominated":
        return ["hasCovarianceEvidence", "hasQualityEvidence"]
    if bucket == "baryonic-floor limited":
        return ["hasMlEvidence", "hasBeamEvidence", "hasDecompositionEvidence"]
    if bucket == "specific systematics unresolved":
        return ["hasInclinationEvidence", "hasBeamEvidence", "hasMlEvidence", "hasCovarianceEvidence"]
    return ["hasReductionEvidence"]


def metadata_support_count(flags: dict, required: list[str]) -> int:
    return sum(1 for key in required if flags.get(key))


def metadata_counterevidence(row: dict, flags: dict, required: list[str], meta: dict | None = None) -> bool:
    if not meta:
        return False
    text = " ".join(str(meta.get(field, "") or "") for field in METADATA_EXTERNAL_FIELDS).lower()
    explicit_markers = [
        "contradicts diagnosis",
        "rules out diagnosis",
        "rules out current diagnosis",
        "no central aperture issue",
        "no beam or aperture issue",
        "covariance rules out error-bar diagnosis",
        "decomposition rules out m/l sensitivity",
    ]
    return any(marker in text for marker in explicit_markers)


def metadata_crosswalk_verdict(row: dict, meta: dict | None, validation_errors: list[dict]) -> str:
    if row["evidenceBucket"] == "metadata-ready claim-safe" and meta:
        flags = metadata_case_support_flags(meta)
        if flags["hasReductionEvidence"] or flags["hasQualityEvidence"]:
            return "claim-safe with provenance"
    if not meta:
        return "metadata still missing"
    if any(error["severity"] == "error" for error in validation_errors):
        return "metadata still missing"
    flags = metadata_case_support_flags(meta)
    required = metadata_required_support(row)
    count = metadata_support_count(flags, required)
    if metadata_counterevidence(row, flags, required, meta):
        return "metadata contradicts diagnosis"
    if count == len(required):
        return "metadata supports systematics diagnosis"
    if count > 0:
        return "metadata weakly supports diagnosis"
    return "metadata still missing"


def metadata_validate_row(meta: dict, known_names: set[str]) -> list[dict]:
    name = meta.get("name", "")
    errors = []
    if not name:
        errors.append({"name": "", "field": "name", "severity": "error", "message": "Missing galaxy name"})
    elif name not in known_names:
        errors.append({"name": name, "field": "name", "severity": "error", "message": "Galaxy name not found in local sample"})
    numeric_ranges = {
        "inclinationDeg": (0.0, 90.0, "deg"),
        "inclinationUncertaintyDeg": (0.0, 45.0, "deg"),
        "distanceMpc": (0.0, 1000.0, "Mpc"),
        "distanceUncertaintyMpc": (0.0, 1000.0, "Mpc"),
        "beamFwhmArcsec": (0.0, 100000.0, "arcsec"),
        "spatialResolutionKpc": (0.0, 1000.0, "kpc"),
        "mlDisk": (0.0, 20.0, "M/L"),
        "mlBulge": (0.0, 20.0, "M/L"),
    }
    for field, (low, high, unit) in numeric_ranges.items():
        text = str(meta.get(field, "") or "").strip()
        if not text:
            continue
        value = metadata_parse_float(text)
        if not math.isfinite(value):
            errors.append({"name": name, "field": field, "severity": "error", "message": f"Expected numeric {unit}"})
        elif not (low <= value <= high):
            errors.append({"name": name, "field": field, "severity": "error", "message": f"Value {value} outside expected {unit} range"})
    covariance_text = str(meta.get("covarianceAvailable", "") or "").strip()
    if covariance_text and metadata_parse_bool(covariance_text) is None:
        errors.append(
            {
                "name": name,
                "field": "covarianceAvailable",
                "severity": "error",
                "message": "Expected true/false for covarianceAvailable",
            }
        )
    source_pairs = [
        ("inclinationDeg", "inclinationSource"),
        ("distanceMpc", "distanceSource"),
        ("beamFwhmArcsec", "beamSource"),
        ("spatialResolutionKpc", "beamSource"),
        ("mlDisk", "mlPriorSource"),
        ("mlBulge", "mlPriorSource"),
    ]
    for value_field, source_field in source_pairs:
        if metadata_has_positive_number(meta, value_field) and not metadata_has_text(meta, source_field):
            errors.append(
                {
                    "name": name,
                    "field": source_field,
                    "severity": "warning",
                    "message": f"{value_field} provided without provenance source",
                }
            )
    return errors


def metadata_crosswalk_rows(priority_rows: list[dict], external_rows: list[dict], base_errors: list[dict]) -> tuple[list[dict], list[dict], list[dict]]:
    known_names = {row["name"] for row in priority_rows}
    external_by_name = {row["name"]: row for row in external_rows if row.get("name")}
    validation_errors = list(base_errors)
    errors_by_name: dict[str, list[dict]] = {}
    duplicate_names: set[str] = set()
    seen: set[str] = set()
    for meta in external_rows:
        name = meta.get("name", "")
        if name in seen:
            duplicate_names.add(name)
        seen.add(name)
        row_errors = metadata_validate_row(meta, known_names)
        if name in duplicate_names:
            row_errors.append({"name": name, "field": "name", "severity": "error", "message": "Duplicate metadata row for galaxy"})
        validation_errors.extend(row_errors)
        errors_by_name.setdefault(name, []).extend(row_errors)

    crosswalk = []
    verdicts = []
    for row in priority_rows:
        meta = external_by_name.get(row["name"])
        row_errors = errors_by_name.get(row["name"], [])
        flags = metadata_case_support_flags(meta or {})
        required = metadata_required_support(row)
        supplied = [key for key, value in flags.items() if value]
        missing = [key for key in required if not flags.get(key)]
        verdict = metadata_crosswalk_verdict(row, meta, row_errors)
        if verdict == "metadata contradicts diagnosis":
            review_status = "needs renewed MTS/data review"
        elif verdict in {"metadata supports systematics diagnosis", "metadata weakly supports diagnosis", "claim-safe with provenance"}:
            review_status = "metadata-informed systematics review"
        else:
            review_status = "awaiting external metadata"
        crosswalk.append(
            {
                "name": row["name"],
                "evidenceBucket": row["evidenceBucket"],
                "finalFailureClass": row["finalFailureClass"],
                "priorityReason": row["priorityReason"],
                "metadataProvided": bool(meta),
                "metadataVerdict": verdict,
                "reviewStatus": review_status,
                "requiredEvidence": "; ".join(required),
                "suppliedEvidence": "; ".join(supplied),
                "missingEvidence": "; ".join(missing),
                "validationErrorCount": sum(1 for error in row_errors if error["severity"] == "error"),
                "validationWarningCount": sum(1 for error in row_errors if error["severity"] == "warning"),
                "baselineRmse": row["baselineRmse"],
                "postShapeRmse": row["postShapeRmse"],
                "bestDiagnosticRmse": row["bestDiagnosticRmse"],
                "bestDiagnosticSource": row["bestDiagnosticSource"],
                "bestRobustRmse": row["bestRobustRmse"],
                "bestRobustSource": row["bestRobustSource"],
                "neededExternalMetadata": row["neededExternalMetadata"],
            }
        )
        verdicts.append(
            {
                "name": row["name"],
                "metadataVerdict": verdict,
                "reviewStatus": review_status,
                "claimSafeInterpretation": (
                    "metadata can support systematics/quality-gate handling only; canonical MTS remains locked"
                    if verdict != "metadata still missing"
                    else "no external metadata evidence supplied yet"
                ),
                "transportLawChangeAllowed": False,
                "nextAction": metadata_crosswalk_next_action(row, verdict, missing),
            }
        )
    crosswalk.sort(key=lambda item: (-float(item["baselineRmse"]), item["name"]))
    verdicts.sort(key=lambda item: item["name"])
    return crosswalk, verdicts, validation_errors


def metadata_crosswalk_next_action(row: dict, verdict: str, missing: list[str]) -> str:
    if verdict == "metadata supports systematics diagnosis":
        return "record provenance and keep case out of transport-law fitting evidence"
    if verdict == "metadata weakly supports diagnosis":
        return f"fill remaining evidence: {'; '.join(missing)}"
    if verdict == "metadata contradicts diagnosis":
        return "open renewed MTS/data review without promoting a hidden correction"
    if verdict == "claim-safe with provenance":
        return "include provenance in release claim pack"
    return f"fetch external metadata: {row['neededExternalMetadata']}"


def metadata_crosswalk_summary(verdict_rows: list[dict]) -> dict:
    counts: dict[str, int] = {}
    for row in verdict_rows:
        counts[row["metadataVerdict"]] = counts.get(row["metadataVerdict"], 0) + 1
    return {
        "verdictCounts": counts,
        "supportedCount": counts.get("metadata supports systematics diagnosis", 0),
        "weakSupportCount": counts.get("metadata weakly supports diagnosis", 0),
        "contradictionCount": counts.get("metadata contradicts diagnosis", 0),
        "missingCount": counts.get("metadata still missing", 0),
        "claimSafeWithProvenanceCount": counts.get("claim-safe with provenance", 0),
    }


def metadata_crosswalk_headline(metadata_file: Path | None, summary: dict, errors: list[dict]) -> str:
    if metadata_file is None:
        return "awaiting external metadata"
    if any(error["severity"] == "error" for error in errors):
        return "metadata file has validation errors"
    if summary["contradictionCount"] > 0:
        return "needs renewed MTS/data review"
    if summary["supportedCount"] > 0 or summary["weakSupportCount"] > 0 or summary["claimSafeWithProvenanceCount"] > 0:
        return "metadata-informed systematics review ready"
    return "metadata still missing"


def metadata_crosswalk_report(capsule: dict, crosswalk_rows: list[dict], verdict_rows: list[dict], validation_rows: list[dict]) -> str:
    metrics = capsule["metrics"]
    named = [row for row in crosswalk_rows if row["name"] in METADATA_NAMED_CASES]
    named.sort(key=lambda row: METADATA_NAMED_CASES.index(row["name"]))
    lines = [
        "# MTS External Metadata Crosswalk And Validation Harness",
        "",
        "This diagnostic turns the metadata audit into a provenance validation loop. Canonical MTS remains locked.",
        "",
        "## Headline",
        "",
        f"Verdict: **{capsule['verdict']}**.",
        f"Metadata file supplied: {capsule['metadataFileSupplied']}.",
        f"Priority cases: {metrics['priorityCaseCount']}.",
        f"Metadata rows supplied: {metrics['metadataRowsSupplied']}.",
        f"Validation errors: {metrics['validationErrorCount']}; warnings: {metrics['validationWarningCount']}.",
        f"Supported diagnoses: {metrics['supportedCount']}; weakly supported: {metrics['weakSupportCount']}; contradictions: {metrics['contradictionCount']}; missing: {metrics['missingCount']}.",
        "",
        "## Metadata Verdicts",
        "",
        "| Galaxy | Bucket | Verdict | Review status | Missing evidence | Best diagnostic | Best robust |",
        "| --- | --- | --- | --- | --- | ---: | ---: |",
    ]
    for row in crosswalk_rows[:24]:
        lines.append(
            f"| {row['name']} | {row['evidenceBucket']} | {row['metadataVerdict']} | {row['reviewStatus']} | "
            f"{row['missingEvidence']} | {fmt(row['bestDiagnosticRmse'])} ({row['bestDiagnosticSource']}) | "
            f"{fmt(row['bestRobustRmse'])} ({row['bestRobustSource']}) |"
        )
    lines.extend(
        [
            "",
            "## Named Cases",
            "",
            "| Galaxy | Bucket | Verdict | Required evidence | Supplied evidence | Next action |",
            "| --- | --- | --- | --- | --- | --- |",
        ]
    )
    verdict_by_name = {row["name"]: row for row in verdict_rows}
    for row in named:
        verdict = verdict_by_name[row["name"]]
        lines.append(
            f"| {row['name']} | {row['evidenceBucket']} | {row['metadataVerdict']} | "
            f"{row['requiredEvidence']} | {row['suppliedEvidence']} | {verdict['nextAction']} |"
        )
    lines.extend(
        [
            "",
            "## Validation Errors",
            "",
            "| Severity | Galaxy | Field | Message |",
            "| --- | --- | --- | --- |",
        ]
    )
    if validation_rows:
        for row in validation_rows[:40]:
            lines.append(f"| {row['severity']} | {row['name']} | {row['field']} | {row['message']} |")
    else:
        lines.append("| none | -- | -- | -- |")
    lines.extend(
        [
            "",
            "## Discipline",
            "",
            "- External metadata can support systematics handling, quality gates, or renewed data review.",
            "- External metadata cannot silently promote a support-law, q-law, amplitude-law, route-law, or two-scale MTS correction.",
            "- Canonical MTS remains locked.",
            "",
        ]
    )
    return "\n".join(lines)


def write_metadata_crosswalk_artifacts(
    out_dir: Path,
    curves: list[dict],
    holdout_fraction: float,
    metadata_file: Path | None,
) -> dict:
    deficit_rows = support_deficit_rows(curves)
    split = stratified_split(curves, SPLIT_SEED, holdout_fraction)
    readiness_rows = metadata_readiness_rows(curves, deficit_rows, split)
    priority_rows = metadata_priority_rows(readiness_rows)
    schema = metadata_crosswalk_schema()
    template_rows = metadata_blank_template_rows(priority_rows)
    external_rows, base_errors = metadata_read_external(metadata_file)
    crosswalk_rows, verdict_rows, validation_rows = metadata_crosswalk_rows(priority_rows, external_rows, base_errors)
    summary = metadata_crosswalk_summary(verdict_rows)
    validation_error_count = sum(1 for row in validation_rows if row["severity"] == "error")
    validation_warning_count = sum(1 for row in validation_rows if row["severity"] == "warning")
    capsule = {
        "type": "mts-external-metadata-crosswalk-validation-harness",
        "version": 1,
        "generatedAt": dt.datetime.now(dt.UTC).isoformat(),
        "sourceScript": "scripts/mts-failure-lab.py",
        "canonicalMtsStatus": "locked",
        "metadataFileSupplied": metadata_file is not None,
        "metadataFile": str(metadata_file) if metadata_file else "",
        "verdict": metadata_crosswalk_headline(metadata_file, summary, validation_rows),
        "split": {
            "seed": split["seed"],
            "holdoutFraction": split["holdoutFraction"],
            "trainCount": len(split["train"]),
            "holdoutCount": len(split["holdout"]),
        },
        "metrics": {
            "priorityCaseCount": len(priority_rows),
            "metadataRowsSupplied": len(external_rows),
            "validationErrorCount": validation_error_count,
            "validationWarningCount": validation_warning_count,
            **summary,
        },
        "rules": {
            "claimStatus": "diagnostic only",
            "transportLawChangeAllowed": False,
            "externalMetadataUse": "support systematics/quality-gate evidence or renewed data review only",
        },
    }
    out_dir.mkdir(parents=True, exist_ok=True)
    (out_dir / "mts-external-metadata-schema.json").write_text(json.dumps(json_clean(schema), indent=2), encoding="utf-8")
    write_csv(out_dir / "mts-external-metadata-template.csv", template_rows)
    write_csv(out_dir / "mts-metadata-crosswalk.csv", crosswalk_rows)
    write_csv(out_dir / "mts-metadata-informed-verdicts.csv", verdict_rows)
    write_csv(out_dir / "mts-metadata-validation-errors.csv", validation_rows)
    (out_dir / "mts-metadata-crosswalk-report.md").write_text(
        metadata_crosswalk_report(capsule, crosswalk_rows, verdict_rows, validation_rows),
        encoding="utf-8",
    )
    (out_dir / "mts-metadata-crosswalk-capsule.json").write_text(json.dumps(json_clean(capsule), indent=2), encoding="utf-8")
    return capsule


def metadata_source_category_specs() -> list[dict]:
    return [
        {
            "category": "sparc-lelli-master-table",
            "description": "Catalogue-level distance, inclination, quality, and reference metadata.",
            "targetFields": "inclinationDeg; inclinationSource; inclinationUncertaintyDeg; distanceMpc; distanceSource; qualityFlags",
            "expectedSourceFiles": "SPARC master table, Lelli et al. catalogue table, source README",
            "supportsBuckets": "velocity-scale proxy sensitive; metadata-ready claim-safe; central-aperture/sampling dominated",
        },
        {
            "category": "rotation-curve-provenance",
            "description": "Rotation-curve extraction method, reduction pipeline, asymmetric drift, and non-circular-motion notes.",
            "targetFields": "rotationCurveExtractionSource; reductionPipelineSource; asymmetricDriftCorrection; barWarpNonCircularFlags",
            "expectedSourceFiles": "ROTMOD provenance table, survey reduction notes, paper appendix",
            "supportsBuckets": "central-aperture/sampling dominated; error-bar dominated; metadata-ready claim-safe",
        },
        {
            "category": "beam-aperture-resolution",
            "description": "Beam, aperture, PSF, or physical spatial-resolution metadata.",
            "targetFields": "beamFwhmArcsec; spatialResolutionKpc; beamSource",
            "expectedSourceFiles": "HI/CO beam table, observation log, paper instrument table",
            "supportsBuckets": "central-aperture/sampling dominated; baryonic-floor limited",
        },
        {
            "category": "stellar-ml-priors",
            "description": "External stellar M/L priors, bandpass, and population-calibration provenance.",
            "targetFields": "mlDisk; mlBulge; mlPriorSource",
            "expectedSourceFiles": "stellar population table, M/L prior table, decomposition paper",
            "supportsBuckets": "M/L-sensitive; baryonic-floor limited",
        },
        {
            "category": "bulge-disk-decomposition",
            "description": "Bulge/disk decomposition source and central mass-model provenance.",
            "targetFields": "decompositionSource; mlDisk; mlBulge; mlPriorSource",
            "expectedSourceFiles": "bulge/disk decomposition table, photometry profile table, paper appendix",
            "supportsBuckets": "M/L-sensitive; baryonic-floor limited; central-aperture/sampling dominated",
        },
        {
            "category": "error-covariance-model",
            "description": "Published error model, covariance availability, and error-floor provenance.",
            "targetFields": "covarianceAvailable; errorModelSource; qualityFlags",
            "expectedSourceFiles": "error model table, covariance release, quality flag table",
            "supportsBuckets": "error-bar dominated; central-aperture/sampling dominated",
        },
        {
            "category": "paper-derived-systematics-notes",
            "description": "Human-curated notes from source papers for bars, warps, asymmetry, and caution flags.",
            "targetFields": "qualityFlags; barWarpNonCircularFlags; notes",
            "expectedSourceFiles": "paper notes, appendix flags, visual inspection notes",
            "supportsBuckets": "all priority buckets",
        },
    ]


def metadata_source_categories(row: dict) -> list[str]:
    bucket = row["evidenceBucket"]
    categories = []

    def add(*items: str) -> None:
        for item in items:
            if item not in categories:
                categories.append(item)

    if bucket == "M/L-sensitive":
        add("stellar-ml-priors", "bulge-disk-decomposition", "paper-derived-systematics-notes")
    elif bucket == "central-aperture/sampling dominated":
        add("beam-aperture-resolution", "rotation-curve-provenance", "paper-derived-systematics-notes")
    elif bucket == "error-bar dominated":
        add("error-covariance-model", "rotation-curve-provenance", "paper-derived-systematics-notes")
    elif bucket == "baryonic-floor limited":
        add("stellar-ml-priors", "bulge-disk-decomposition", "beam-aperture-resolution", "paper-derived-systematics-notes")
    elif bucket == "velocity-scale proxy sensitive":
        add("sparc-lelli-master-table", "rotation-curve-provenance", "paper-derived-systematics-notes")
    elif bucket == "metadata-ready claim-safe":
        add("sparc-lelli-master-table", "rotation-curve-provenance")
    else:
        add("sparc-lelli-master-table", "rotation-curve-provenance", "paper-derived-systematics-notes")
    return categories


def metadata_confirmation_rule(row: dict) -> dict:
    bucket = row["evidenceBucket"]
    if bucket == "M/L-sensitive":
        confirms = "external M/L prior and decomposition source show plausible disk/bulge normalization sensitivity"
        contradicts = "independent M/L/decomposition is tightly constrained near the local default but residual remains high"
        blocks = "missing M/L prior or decomposition provenance"
    elif bucket == "central-aperture/sampling dominated":
        confirms = "beam/resolution, extraction, quality, or non-circular-motion metadata supports central aperture/sampling sensitivity"
        contradicts = "high-resolution extraction with clean quality flags contradicts central/aperture explanation"
        blocks = "missing beam/resolution, extraction, or quality provenance"
    elif bucket == "error-bar dominated":
        confirms = "published covariance/error model or quality flags make the residual statistically non-robust"
        contradicts = "small independent uncertainties without covariance/quality caveats keep residual significant"
        blocks = "missing covariance/error-model provenance"
    elif bucket == "baryonic-floor limited":
        confirms = "central mass-model, M/L, decomposition, or beam/aperture metadata explains baryonic floor tension"
        contradicts = "central baryonic model is externally secure and still exceeds observed velocities"
        blocks = "missing central mass-model, M/L, decomposition, or beam metadata"
    elif bucket == "velocity-scale proxy sensitive":
        confirms = "inclination or velocity-scale provenance allows the proxy sensitivity range"
        contradicts = "inclination and extraction provenance are too tight to explain velocity-scale sensitivity"
        blocks = "missing inclination/source or extraction provenance"
    else:
        confirms = "source provenance documents the local claim-safe interpretation"
        contradicts = "quality/provenance flags indicate the local claim-safe status should be rechecked"
        blocks = "missing source provenance"
    return {
        "evidenceBucket": bucket,
        "confirmingEvidence": confirms,
        "contradictingEvidence": contradicts,
        "claimBlockingMissingEvidence": blocks,
        "contradictionAction": "needs renewed MTS/data review; do not promote hidden transport correction",
    }


def metadata_source_dir_files(source_dir: Path | None) -> list[dict]:
    if source_dir is None or not source_dir.exists() or not source_dir.is_dir():
        return []
    rows = []
    for path in sorted(source_dir.rglob("*")):
        if path.is_file():
            try:
                relative = str(path.relative_to(source_dir))
            except ValueError:
                relative = str(path)
            rows.append(
                {
                    "path": relative,
                    "suffix": path.suffix.lower(),
                    "sizeBytes": path.stat().st_size,
                }
            )
    return rows


def metadata_source_matches(row: dict, source_files: list[dict]) -> str:
    if not source_files:
        return ""
    needle = row["name"].lower().replace("-", "").replace("_", "")
    matches = []
    for item in source_files:
        compact = item["path"].lower().replace("-", "").replace("_", "")
        if needle in compact:
            matches.append(item["path"])
    return "; ".join(matches[:8])


def metadata_source_targets(priority_rows: list[dict], source_files: list[dict]) -> list[dict]:
    rows = []
    for index, row in enumerate(priority_rows, start=1):
        categories = metadata_source_categories(row)
        rule = metadata_confirmation_rule(row)
        rows.append(
            {
                "rank": index,
                "name": row["name"],
                "namedCase": row["name"] in METADATA_NAMED_CASES,
                "priorityScore": row["priorityScore"],
                "priorityReason": row["priorityReason"],
                "evidenceBucket": row["evidenceBucket"],
                "finalFailureClass": row["finalFailureClass"],
                "baselineRmse": row["baselineRmse"],
                "postShapeRmse": row["postShapeRmse"],
                "bestDiagnosticRmse": row["bestDiagnosticRmse"],
                "bestDiagnosticSource": row["bestDiagnosticSource"],
                "bestRobustRmse": row["bestRobustRmse"],
                "bestRobustSource": row["bestRobustSource"],
                "sourceCategories": "; ".join(categories),
                "targetMetadataFields": row["neededExternalMetadata"],
                "confirmingEvidence": rule["confirmingEvidence"],
                "contradictingEvidence": rule["contradictingEvidence"],
                "claimBlockingMissingEvidence": rule["claimBlockingMissingEvidence"],
                "localSourceFileMatches": metadata_source_matches(row, source_files),
            }
        )
    return rows


def metadata_fetch_checklist(target_rows: list[dict]) -> list[dict]:
    rows = []
    for target in target_rows:
        categories = [item.strip() for item in target["sourceCategories"].split(";") if item.strip()]
        fields = [item.strip() for item in target["targetMetadataFields"].split(";") if item.strip()]
        for category in categories:
            rows.append(
                {
                    "name": target["name"],
                    "rank": target["rank"],
                    "namedCase": target["namedCase"],
                    "evidenceBucket": target["evidenceBucket"],
                    "sourceCategory": category,
                    "fieldsToFetch": "; ".join(fields),
                    "whyNeeded": target["claimBlockingMissingEvidence"],
                    "confirmingEvidence": target["confirmingEvidence"],
                    "contradictingEvidence": target["contradictingEvidence"],
                    "done": "",
                    "sourceFileOrCitation": "",
                    "notes": "",
                }
            )
    rows.sort(key=lambda item: (0 if item["namedCase"] else 1, int(item["rank"]), item["sourceCategory"]))
    return rows


def metadata_confirmation_rules_rows(priority_rows: list[dict]) -> list[dict]:
    seen: set[str] = set()
    rows = []
    for row in priority_rows:
        bucket = row["evidenceBucket"]
        if bucket in seen:
            continue
        seen.add(bucket)
        rule = metadata_confirmation_rule(row)
        rows.append(
            {
                "evidenceBucket": bucket,
                "requiredEvidenceFlags": "; ".join(metadata_required_support(row)),
                "sourceCategories": "; ".join(metadata_source_categories(row)),
                "confirmingEvidence": rule["confirmingEvidence"],
                "contradictingEvidence": rule["contradictingEvidence"],
                "claimBlockingMissingEvidence": rule["claimBlockingMissingEvidence"],
                "contradictionAction": rule["contradictionAction"],
            }
        )
    rows.sort(key=lambda item: item["evidenceBucket"])
    return rows


def metadata_source_pack_manifest(source_dir: Path | None, source_files: list[dict], target_rows: list[dict]) -> dict:
    categories = metadata_source_category_specs()
    counts: dict[str, int] = {}
    for row in target_rows:
        for category in [item.strip() for item in row["sourceCategories"].split(";") if item.strip()]:
            counts[category] = counts.get(category, 0) + 1
    return {
        "type": "mts-metadata-source-pack-manifest",
        "version": 1,
        "canonicalMtsStatus": "locked",
        "sourceDirSupplied": source_dir is not None,
        "sourceDir": str(source_dir) if source_dir else "",
        "sourceFileCount": len(source_files),
        "sourceFiles": source_files,
        "sourceCategories": [{**category, "targetCount": counts.get(category["category"], 0)} for category in categories],
        "priorityTargetCount": len(target_rows),
        "namedCases": METADATA_NAMED_CASES,
        "networkFetching": "disabled in v1",
    }


def metadata_source_pack_report(capsule: dict, target_rows: list[dict], checklist_rows: list[dict], rule_rows: list[dict]) -> str:
    metrics = capsule["metrics"]
    named = [row for row in target_rows if row["name"] in METADATA_NAMED_CASES]
    named.sort(key=lambda row: METADATA_NAMED_CASES.index(row["name"]))
    category_counts: dict[str, int] = {}
    for row in checklist_rows:
        category_counts[row["sourceCategory"]] = category_counts.get(row["sourceCategory"], 0) + 1
    lines = [
        "# MTS External Metadata Source Pack",
        "",
        "This source pack converts metadata-limited cases into a deterministic fetch plan. Canonical MTS remains locked.",
        "",
        "## Headline",
        "",
        f"Verdict: **{capsule['verdict']}**.",
        f"Priority cases: {metrics['priorityCaseCount']}.",
        f"Named priority cases: {metrics['namedPriorityCount']}.",
        f"Checklist rows: {metrics['checklistRowCount']}.",
        f"Source directory supplied: {capsule['sourceDirSupplied']}.",
        f"Local source files discovered: {metrics['sourceFileCount']}.",
        "",
        "## Source Categories",
        "",
        "| Category | Targets |",
        "| --- | ---: |",
    ]
    for category, count in sorted(category_counts.items()):
        lines.append(f"| {category} | {count} |")
    lines.extend(
        [
            "",
            "## Named Cases",
            "",
            "| Galaxy | Bucket | Source categories | Confirming evidence | Contradicting evidence |",
            "| --- | --- | --- | --- | --- |",
        ]
    )
    for row in named:
        lines.append(
            f"| {row['name']} | {row['evidenceBucket']} | {row['sourceCategories']} | "
            f"{row['confirmingEvidence']} | {row['contradictingEvidence']} |"
        )
    lines.extend(
        [
            "",
            "## Top Fetch Targets",
            "",
            "| Rank | Galaxy | Bucket | Needed fields | Source categories | Local matches |",
            "| ---: | --- | --- | --- | --- | --- |",
        ]
    )
    for row in target_rows[:20]:
        lines.append(
            f"| {row['rank']} | {row['name']} | {row['evidenceBucket']} | "
            f"{row['targetMetadataFields']} | {row['sourceCategories']} | {row['localSourceFileMatches'] or '--'} |"
        )
    lines.extend(
        [
            "",
            "## Confirmation Rules",
            "",
            "| Bucket | Required flags | Confirms | Contradicts |",
            "| --- | --- | --- | --- |",
        ]
    )
    for row in rule_rows:
        lines.append(
            f"| {row['evidenceBucket']} | {row['requiredEvidenceFlags']} | "
            f"{row['confirmingEvidence']} | {row['contradictingEvidence']} |"
        )
    lines.extend(
        [
            "",
            "## Next Fetch List",
            "",
            "| Galaxy | Category | Fields | Why needed |",
            "| --- | --- | --- | --- |",
        ]
    )
    for row in checklist_rows[:28]:
        lines.append(f"| {row['name']} | {row['sourceCategory']} | {row['fieldsToFetch']} | {row['whyNeeded']} |")
    lines.extend(
        [
            "",
            "## Discipline",
            "",
            "- This mode prepares source targets only; it does not fetch from the network.",
            "- Missing provenance is not treated as transport-facing evidence.",
            "- Contradictory provenance triggers renewed MTS/data review, not a hidden framework correction.",
            "- Canonical MTS remains locked.",
            "",
        ]
    )
    return "\n".join(lines)


def write_metadata_source_pack_artifacts(
    out_dir: Path,
    curves: list[dict],
    holdout_fraction: float,
    source_dir: Path | None,
) -> dict:
    deficit_rows = support_deficit_rows(curves)
    split = stratified_split(curves, SPLIT_SEED, holdout_fraction)
    readiness_rows = metadata_readiness_rows(curves, deficit_rows, split)
    priority_rows = metadata_priority_rows(readiness_rows)
    source_files = metadata_source_dir_files(source_dir)
    target_rows = metadata_source_targets(priority_rows, source_files)
    checklist_rows = metadata_fetch_checklist(target_rows)
    rule_rows = metadata_confirmation_rules_rows(priority_rows)
    manifest = metadata_source_pack_manifest(source_dir, source_files, target_rows)
    capsule = {
        "type": "mts-external-metadata-source-pack",
        "version": 1,
        "generatedAt": dt.datetime.now(dt.UTC).isoformat(),
        "sourceScript": "scripts/mts-failure-lab.py",
        "canonicalMtsStatus": "locked",
        "verdict": "source pack ready; fetch external provenance next",
        "sourceDirSupplied": source_dir is not None,
        "sourceDir": str(source_dir) if source_dir else "",
        "split": {
            "seed": split["seed"],
            "holdoutFraction": split["holdoutFraction"],
            "trainCount": len(split["train"]),
            "holdoutCount": len(split["holdout"]),
        },
        "metrics": {
            "priorityCaseCount": len(priority_rows),
            "namedPriorityCount": sum(1 for row in priority_rows if row["name"] in METADATA_NAMED_CASES),
            "checklistRowCount": len(checklist_rows),
            "ruleCount": len(rule_rows),
            "sourceFileCount": len(source_files),
        },
        "rules": {
            "claimStatus": "diagnostic only",
            "networkFetching": "disabled in v1",
            "transportLawChangeAllowed": False,
        },
    }
    out_dir.mkdir(parents=True, exist_ok=True)
    write_csv(out_dir / "mts-metadata-source-targets.csv", target_rows)
    (out_dir / "mts-metadata-source-manifest.json").write_text(json.dumps(json_clean(manifest), indent=2), encoding="utf-8")
    write_csv(out_dir / "mts-priority-fetch-checklist.csv", checklist_rows)
    write_csv(out_dir / "mts-diagnosis-confirmation-rules.csv", rule_rows)
    (out_dir / "mts-source-pack-report.md").write_text(
        metadata_source_pack_report(capsule, target_rows, checklist_rows, rule_rows),
        encoding="utf-8",
    )
    (out_dir / "mts-source-pack-capsule.json").write_text(json.dumps(json_clean(capsule), indent=2), encoding="utf-8")
    return capsule


