def file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def archive_members(path: Path) -> tuple[list[str], str]:
    if not path.exists():
        return [], "missing"
    try:
        if path.suffix.lower() == ".zip":
            with zipfile.ZipFile(path) as archive:
                return sorted(item.filename for item in archive.infolist() if not item.is_dir()), "ok"
        if path.name.lower().endswith((".tar.gz", ".tgz")):
            with tarfile.open(path, "r:*") as archive:
                return sorted(item.name for item in archive.getmembers() if item.isfile()), "ok"
    except (OSError, tarfile.TarError, zipfile.BadZipFile) as exc:
        return [], f"error: {exc}"
    return [], "not-archive"


def local_source_inventory_rows(source_dir: Path) -> list[dict]:
    rows = []
    for spec in LOCAL_SOURCE_EXPECTED_FILES:
        path = source_dir / spec["fileName"]
        exists = path.exists()
        members, archive_status = archive_members(path) if exists and spec["parseMode"] != "parse-mrt" else ([], "not-archive")
        checksum = file_sha256(path) if exists else ""
        rows.append(
            {
                "fileName": spec["fileName"],
                "sourceCategory": spec["sourceCategory"],
                "parseMode": spec["parseMode"],
                "requiredForV1": spec["requiredForV1"],
                "exists": exists,
                "sourceFilePath": str(path),
                "sizeBytes": path.stat().st_size if exists else "",
                "sha256": checksum,
                "archiveReadStatus": archive_status,
                "archiveMemberCount": len(members),
                "firstArchiveMembers": "; ".join(members[:5]),
            }
        )
    return rows


def parse_sparc_mrt(path: Path) -> tuple[dict[str, dict], dict]:
    if not path.exists():
        return {}, {"readStatus": "missing", **SPARC_MRT_NOTES}
    text = path.read_text(encoding="utf-8", errors="replace")
    rows_by_name: dict[str, list[dict]] = {}
    for line in text.splitlines():
        parts = line.strip().split()
        if len(parts) < 10:
            continue
        try:
            values = [float(part) for part in parts[1:10]]
        except ValueError:
            continue
        name = parts[0]
        rows_by_name.setdefault(name, []).append(
            {
                "distanceMpc": values[0],
                "radiusKpc": values[1],
                "vObs": values[2],
                "eVobs": values[3],
                "vGas": values[4],
                "vDisk": values[5],
                "vBul": values[6],
                "sbDisk": values[7],
                "sbBul": values[8],
            }
        )
    stats = {}
    for name, rows in sorted(rows_by_name.items()):
        distances = sorted({round(row["distanceMpc"], 8) for row in rows})
        radii = [row["radiusKpc"] for row in rows]
        errors = [row["eVobs"] for row in rows]
        stats[name] = {
            "name": name,
            "mrtRowCount": len(rows),
            "mrtDistanceMpc": distances[0] if len(distances) == 1 else math.nan,
            "mrtDistanceValues": "; ".join(fmt_num(value) for value in distances),
            "mrtDistanceUniqueCount": len(distances),
            "mrtRadiusMinKpc": min(radii),
            "mrtRadiusMaxKpc": max(radii),
            "mrtErrVMinKmS": min(errors),
            "mrtErrVMaxKmS": max(errors),
            "mrtErrVMedianKmS": safe_median(errors),
            "mrtGasRows": sum(1 for row in rows if abs(row["vGas"]) > 0),
            "mrtDiskRows": sum(1 for row in rows if abs(row["vDisk"]) > 0),
            "mrtBulgeRows": sum(1 for row in rows if abs(row["vBul"]) > 0),
            "mrtSbDiskRows": sum(1 for row in rows if row["sbDisk"] > 0),
            "mrtSbBulgeRows": sum(1 for row in rows if row["sbBul"] > 0),
        }
    header = {
        "readStatus": "ok",
        "rowCount": sum(len(rows) for rows in rows_by_name.values()),
        "galaxyCount": len(rows_by_name),
        "distanceUnit": "Mpc",
        "radiusUnit": "kpc",
        "velocityUnit": "km/s",
        "surfaceBrightnessUnit": "solLum/pc2",
        **SPARC_MRT_NOTES,
        "sourceTitle": "SPARC: Mass Models for 175 Disk Galaxies with Spitzer Photometry and Accurate Rotation Curves",
    }
    return stats, header


def archive_galaxy_member_counts(path: Path, archive_kind: str) -> dict[str, int]:
    members, status = archive_members(path)
    if status != "ok":
        return {}
    counts: dict[str, int] = {}
    for member in members:
        base = Path(member).name
        name = ""
        if archive_kind == "rotmod" and base.lower().endswith("_rotmod.dat"):
            name = re.sub(r"_rotmod\.dat$", "", base, flags=re.I)
        elif archive_kind == "sfb" and base.lower().endswith(".sfb"):
            name = re.sub(r"\.sfb$", "", base, flags=re.I)
        elif archive_kind == "mcmc" and base.lower().endswith(".pdf"):
            match = re.match(r"SPARC[0-9]+_(.+?)(?:_triangle)?\.pdf$", base, re.I)
            name = match.group(1) if match else ""
        elif archive_kind == "png" and base.lower().endswith("_massmodel.png"):
            name = re.sub(r"_MassModel\.png$", "", base, flags=re.I)
        if name:
            counts[name] = counts.get(name, 0) + 1
    return counts


def local_archive_coverage(source_dir: Path) -> dict[str, dict[str, int]]:
    return {
        "rotmod": archive_galaxy_member_counts(source_dir / "Rotmod_LTG (4).zip", "rotmod"),
        "sfb": archive_galaxy_member_counts(source_dir / "sfb_LTG (1).zip", "sfb"),
        "mcmc": archive_galaxy_member_counts(source_dir / "MCMCfits.tar.gz", "mcmc"),
        "png": archive_galaxy_member_counts(source_dir / "MassModels_LTG.png.zip", "png"),
        "pngDuplicate": archive_galaxy_member_counts(source_dir / "MassModels_LTG.png (1).zip", "png"),
    }


def source_short_hash(inventory_by_file: dict[str, dict], file_name: str) -> str:
    digest = str(inventory_by_file.get(file_name, {}).get("sha256", ""))
    return digest[:12] if digest else ""


def local_source_paths_for_name(name: str, source_dir: Path, coverage: dict[str, dict[str, int]]) -> str:
    paths = []
    if name in coverage.get("rotmod", {}):
        paths.append(str(source_dir / "Rotmod_LTG (4).zip"))
    if name in coverage.get("sfb", {}):
        paths.append(str(source_dir / "sfb_LTG (1).zip"))
    if name in coverage.get("mcmc", {}):
        paths.append(str(source_dir / "MCMCfits.tar.gz"))
    if name in coverage.get("png", {}) or name in coverage.get("pngDuplicate", {}):
        paths.append(str(source_dir / "MassModels_LTG.png.zip"))
    return "; ".join(paths)


def local_sparc_provenance_rows(
    curves: list[dict],
    source_dir: Path,
    mrt_stats: dict[str, dict],
    mrt_header: dict,
    coverage: dict[str, dict[str, int]],
    inventory_by_file: dict[str, dict],
) -> list[dict]:
    mrt_path = source_dir / "MassModels_Lelli2016c.mrt"
    rows = []
    for curve in sorted(curves, key=lambda item: item["name"]):
        name = curve["name"]
        mrt = mrt_stats.get(name, {})
        in_mrt = bool(mrt)
        source_paths = [str(mrt_path)] if in_mrt else []
        extra_paths = local_source_paths_for_name(name, source_dir, coverage)
        if extra_paths:
            source_paths.extend(extra_paths.split("; "))
        rows.append(
            {
                "name": name,
                "inLocalSample": True,
                "inMassModelsMrt": in_mrt,
                "mrtRowCount": mrt.get("mrtRowCount", 0),
                "localRowCount": len(curve["points"]),
                "rowCountMatchesLocalSample": in_mrt and int(mrt.get("mrtRowCount", -1)) == len(curve["points"]),
                "mrtDistanceMpc": mrt.get("mrtDistanceMpc", ""),
                "localDistanceMpc": curve["distanceMpc"],
                "distanceMatchesLocalSample": (
                    in_mrt
                    and math.isfinite(float(mrt.get("mrtDistanceMpc", math.nan)))
                    and abs(float(mrt.get("mrtDistanceMpc", math.nan)) - curve["distanceMpc"]) < 1e-6
                ),
                "radiusUnit": mrt_header.get("radiusUnit", ""),
                "velocityUnit": mrt_header.get("velocityUnit", ""),
                "errorUnit": mrt_header.get("velocityUnit", ""),
                "distanceUnit": mrt_header.get("distanceUnit", ""),
                "surfaceBrightnessUnit": mrt_header.get("surfaceBrightnessUnit", ""),
                "mrtRadiusMinKpc": mrt.get("mrtRadiusMinKpc", ""),
                "mrtRadiusMaxKpc": mrt.get("mrtRadiusMaxKpc", ""),
                "mrtErrVMedianKmS": mrt.get("mrtErrVMedianKmS", ""),
                "mrtGasRows": mrt.get("mrtGasRows", ""),
                "mrtDiskRows": mrt.get("mrtDiskRows", ""),
                "mrtBulgeRows": mrt.get("mrtBulgeRows", ""),
                "inRotmodArchive": name in coverage.get("rotmod", {}),
                "rotmodMemberCount": coverage.get("rotmod", {}).get(name, 0),
                "inSfbArchive": name in coverage.get("sfb", {}),
                "sfbProfileCount": coverage.get("sfb", {}).get(name, 0),
                "inMcmcFitsArchive": name in coverage.get("mcmc", {}),
                "mcmcFigureCount": coverage.get("mcmc", {}).get(name, 0),
                "inMassModelPngArchive": name in coverage.get("png", {}) or name in coverage.get("pngDuplicate", {}),
                "massModelPngCount": coverage.get("png", {}).get(name, 0) + coverage.get("pngDuplicate", {}).get(name, 0),
                "massModelsMrtSha256": inventory_by_file.get("MassModels_Lelli2016c.mrt", {}).get("sha256", ""),
                "rotmodArchiveSha256": inventory_by_file.get("Rotmod_LTG (4).zip", {}).get("sha256", ""),
                "sfbArchiveSha256": inventory_by_file.get("sfb_LTG (1).zip", {}).get("sha256", ""),
                "sourceFilePaths": "; ".join(dict.fromkeys(source_paths)),
                "errorModelProvenance": mrt_header.get("errorModel", ""),
                "inclinationSystematicsIncludedInErrV": False if in_mrt else "",
                "componentColumnProvenance": (
                    f"{mrt_header.get('gasComponent', '')} {mrt_header.get('stellarComponents', '')}".strip()
                    if in_mrt
                    else ""
                ),
                "localSourceCanFill": "distance; errV provenance; gas/disk/bulge component-column provenance; rotation table source coverage",
                "localSourceCannotFill": "inclination provenance/uncertainty; beam/FWHM; covariance matrix; quality flags; decomposition provenance; external stellar M/L priors",
            }
        )
    return rows


def local_missing_metadata_fields(priority_row: dict) -> list[tuple[str, str]]:
    bucket = priority_row["evidenceBucket"]
    common = [
        ("inclinationSource", "MRT Note (1) says inclination-correction systematics are not included in e_Vobs."),
        ("inclinationUncertaintyDeg", "No inclination uncertainty is present in the local MRT/ROTMOD sample."),
        ("distanceUncertaintyMpc", "MRT gives assumed distance D but not distance uncertainty."),
        ("covarianceAvailable", "MRT provides point random errors but not a covariance matrix."),
        ("qualityFlags", "No per-galaxy quality/bar/warp flag table is present in the local source pack."),
    ]
    bucket_fields = []
    if bucket in {"central-aperture/sampling dominated", "baryonic-floor limited", "specific systematics unresolved"}:
        bucket_fields.extend(
            [
                ("beamFwhmArcsec", "No beam/FWHM or aperture metadata is present in the local source pack."),
                ("spatialResolutionKpc", "No physical spatial-resolution metadata is present in the local source pack."),
                ("beamSource", "No beam or aperture source provenance is present in the local source pack."),
            ]
        )
    if bucket in {"M/L-sensitive", "baryonic-floor limited", "specific systematics unresolved"}:
        bucket_fields.extend(
            [
                ("mlDisk", "MRT Vdisk is normalized to M/L=1 at [3.6], but no external disk M/L prior is supplied."),
                ("mlBulge", "MRT Vbul is normalized to M/L=1 at [3.6], but no external bulge M/L prior is supplied."),
                ("mlPriorSource", "No external stellar M/L prior source is present in the local source pack."),
                ("decompositionSource", "No bulge/disk decomposition provenance table is parsed in v1."),
            ]
        )
    if bucket == "velocity-scale proxy sensitive":
        bucket_fields.append(("rotationCurveExtractionSource", "ROTMOD coverage is present, but inclination-source provenance is still required for a real velocity-scale test."))
    if bucket == "error-bar dominated":
        bucket_fields.append(("covarianceAvailable", "MRT e_Vobs provenance is present, but covariance/error-floor provenance remains missing."))
    if bucket == "metadata-ready claim-safe":
        bucket_fields = [("reductionPipelineSource", "Local SPARC table provenance is prefilled; external release/citation details can still strengthen public claims.")]
    combined: list[tuple[str, str]] = []
    for item in common + bucket_fields:
        if item[0] not in {field for field, _reason in combined}:
            combined.append(item)
    return combined


def local_metadata_prefill_rows(
    priority_rows: list[dict],
    provenance_by_name: dict[str, dict],
    inventory_by_file: dict[str, dict],
) -> list[dict]:
    mrt_hash = source_short_hash(inventory_by_file, "MassModels_Lelli2016c.mrt")
    rotmod_hash = source_short_hash(inventory_by_file, "Rotmod_LTG (4).zip")
    rows = []
    for priority in priority_rows:
        name = priority["name"]
        prov = provenance_by_name.get(name, {})
        row = {field: "" for field in METADATA_EXTERNAL_FIELDS}
        row["name"] = name
        note_parts = [
            f"{priority['evidenceBucket']}; local source ingest prefill.",
            SPARC_MRT_NOTES["errorModel"],
            SPARC_MRT_NOTES["gasComponent"],
            SPARC_MRT_NOTES["stellarComponents"],
            "Still missing: inclination provenance/uncertainty, beam/FWHM, covariance, quality flags, decomposition provenance, and external M/L priors.",
        ]
        if prov.get("inMassModelsMrt"):
            row["distanceMpc"] = fmt_num(float(prov["mrtDistanceMpc"]))
            row["distanceSource"] = f"MassModels_Lelli2016c.mrt D column; sha256={mrt_hash}"
            row["covarianceAvailable"] = "false"
            row["errorModelSource"] = f"MassModels_Lelli2016c.mrt Note (1); sha256={mrt_hash}"
            row["reductionPipelineSource"] = f"SPARC/Lelli2016c local mass-model table; sha256={mrt_hash}"
        if prov.get("inRotmodArchive"):
            row["rotationCurveExtractionSource"] = f"Rotmod_LTG (4).zip contains {name}_rotmod.dat; sha256={rotmod_hash}"
        row["notes"] = " ".join(note_parts)
        rows.append(row)
    rows.sort(key=lambda item: item["name"])
    return rows


def local_source_crosswalk_rows(
    priority_rows: list[dict],
    provenance_by_name: dict[str, dict],
    prefill_by_name: dict[str, dict],
) -> list[dict]:
    rows = []
    for index, priority in enumerate(priority_rows, start=1):
        name = priority["name"]
        prov = provenance_by_name.get(name, {})
        prefill = prefill_by_name.get(name, {})
        fields = [field for field in METADATA_EXTERNAL_FIELDS if field != "name" and str(prefill.get(field, "")).strip()]
        missing_fields = [field for field, _reason in local_missing_metadata_fields(priority)]
        coverage = []
        if prov.get("inMassModelsMrt"):
            coverage.append("MRT")
        if prov.get("inRotmodArchive"):
            coverage.append("ROTMOD")
        if prov.get("inSfbArchive"):
            coverage.append("SFB")
        if prov.get("inMcmcFitsArchive"):
            coverage.append("MCMC")
        rows.append(
            {
                "rank": index,
                "name": name,
                "namedCase": name in METADATA_NAMED_CASES,
                "evidenceBucket": priority["evidenceBucket"],
                "priorityReason": priority["priorityReason"],
                "localSourceCoverage": "; ".join(coverage) if coverage else "none",
                "inMassModelsMrt": prov.get("inMassModelsMrt", False),
                "inRotmodArchive": prov.get("inRotmodArchive", False),
                "inSfbArchive": prov.get("inSfbArchive", False),
                "rowCountMatchesLocalSample": prov.get("rowCountMatchesLocalSample", False),
                "prefilledMetadataFields": "; ".join(fields),
                "stillMissingFields": "; ".join(missing_fields),
                "localEvidenceSummary": (
                    "local source supports distance/error/component-column provenance; missing metadata remains explicit"
                    if coverage
                    else "no local source coverage found"
                ),
                "crosswalkUse": "metadata-file prefill only; no MTS score or candidate status change",
            }
        )
    rows.sort(key=lambda item: (0 if item["namedCase"] else 1, int(item["rank"]), item["name"]))
    return rows


def local_source_missing_field_rows(priority_rows: list[dict], provenance_by_name: dict[str, dict]) -> list[dict]:
    rows = []
    for priority in priority_rows:
        prov = provenance_by_name.get(priority["name"], {})
        for field, reason in local_missing_metadata_fields(priority):
            rows.append(
                {
                    "name": priority["name"],
                    "evidenceBucket": priority["evidenceBucket"],
                    "missingField": field,
                    "reason": reason,
                    "localMrtCoverage": prov.get("inMassModelsMrt", False),
                    "localRotmodCoverage": prov.get("inRotmodArchive", False),
                    "claimImpact": "blocks strong systematics/provenance claim until external metadata is supplied",
                }
            )
    rows.sort(key=lambda item: (item["name"], item["missingField"]))
    return rows


def local_source_ingest_report(
    capsule: dict,
    inventory_rows: list[dict],
    provenance_rows: list[dict],
    crosswalk_rows: list[dict],
    missing_rows: list[dict],
) -> str:
    metrics = capsule["metrics"]
    named = [row for row in crosswalk_rows if row["name"] in METADATA_NAMED_CASES]
    named.sort(key=lambda row: METADATA_NAMED_CASES.index(row["name"]))
    lines = [
        "# MTS Local SPARC/ATLAS Source Ingestion",
        "",
        "This diagnostic mines local source files for provenance metadata only. Canonical MTS remains locked.",
        "",
        "## Headline",
        "",
        f"Verdict: **{capsule['verdict']}**.",
        f"Source directory: `{capsule['sourceDir']}`.",
        f"Local LTG curves covered by `MassModels_Lelli2016c.mrt`: {metrics['localCurveMrtCoverageCount']}/{metrics['localCurveCount']}.",
        f"Priority cases with MRT coverage: {metrics['priorityMrtCoverageCount']}/{metrics['priorityCaseCount']}.",
        f"Priority cases with ROTMOD archive coverage: {metrics['priorityRotmodCoverageCount']}/{metrics['priorityCaseCount']}.",
        f"Metadata prefill rows written: {metrics['prefillRowCount']}.",
        "",
        "## MRT Header Evidence",
        "",
        f"- {SPARC_MRT_NOTES['errorModel']}",
        f"- {SPARC_MRT_NOTES['gasComponent']}",
        f"- {SPARC_MRT_NOTES['stellarComponents']}",
        "- These notes support source provenance and error/component interpretation, but they do not provide beam/FWHM, covariance, decomposition, quality flags, or inclination-systematics metadata.",
        "",
        "## Source Inventory",
        "",
        "| File | Category | Exists | Members | Parse mode |",
        "| --- | --- | --- | ---: | --- |",
    ]
    for row in inventory_rows:
        lines.append(
            f"| {row['fileName']} | {row['sourceCategory']} | {row['exists']} | {row['archiveMemberCount']} | {row['parseMode']} |"
        )
    lines.extend(
        [
            "",
            "## Named Priority Coverage",
            "",
            "| Galaxy | Bucket | Coverage | Prefilled fields | Still missing |",
            "| --- | --- | --- | --- | --- |",
        ]
    )
    for row in named:
        lines.append(
            f"| {row['name']} | {row['evidenceBucket']} | {row['localSourceCoverage']} | "
            f"{row['prefilledMetadataFields']} | {row['stillMissingFields']} |"
        )
    lines.extend(
        [
            "",
            "## LTG Provenance Coverage",
            "",
            "| Galaxy | MRT | ROTMOD | SFB | Rows | Distance | Component provenance |",
            "| --- | --- | --- | --- | ---: | ---: | --- |",
        ]
    )
    for row in provenance_rows[:16]:
        lines.append(
            f"| {row['name']} | {row['inMassModelsMrt']} | {row['inRotmodArchive']} | {row['inSfbArchive']} | "
            f"{row['mrtRowCount']} | {fmt(row['mrtDistanceMpc'])} | {row['componentColumnProvenance']} |"
        )
    lines.extend(
        [
            "",
            "## Missing Fields",
            "",
            "| Galaxy | Field | Reason |",
            "| --- | --- | --- |",
        ]
    )
    for row in missing_rows[:28]:
        lines.append(f"| {row['name']} | {row['missingField']} | {row['reason']} |")
    lines.extend(
        [
            "",
            "## Crosswalk Use",
            "",
            "`mts-local-metadata-prefill.csv` is schema-compatible with `--mode metadatacrosswalk --metadata-file ...`.",
            "It should improve only provenance-backed verdicts. Missing inclination, beam/FWHM, covariance, quality, decomposition, and external M/L fields remain blank.",
            "",
            "## ATLAS3D Discipline",
            "",
            "ATLAS3D archives are inventoried with checksums in v1 only. ETG parsing is deliberately deferred to a dedicated mode.",
            "",
            "## No Framework Mutation",
            "",
            "- No MTS formula, q law, amplitude law, route law, or two-scale law is promoted here.",
            "- Local source provenance feeds metadata handling and quality gates only.",
            "- Canonical MTS remains locked.",
            "",
        ]
    )
    return "\n".join(lines)


def write_local_source_ingest_artifacts(
    out_dir: Path,
    curves: list[dict],
    holdout_fraction: float,
    source_dir: Path,
) -> dict:
    deficit_rows = support_deficit_rows(curves)
    split = stratified_split(curves, SPLIT_SEED, holdout_fraction)
    readiness_rows = metadata_readiness_rows(curves, deficit_rows, split)
    priority_rows = metadata_priority_rows(readiness_rows)
    inventory_rows = local_source_inventory_rows(source_dir)
    inventory_by_file = {row["fileName"]: row for row in inventory_rows}
    mrt_stats, mrt_header = parse_sparc_mrt(source_dir / "MassModels_Lelli2016c.mrt")
    coverage = local_archive_coverage(source_dir)
    provenance_rows = local_sparc_provenance_rows(curves, source_dir, mrt_stats, mrt_header, coverage, inventory_by_file)
    provenance_by_name = {row["name"]: row for row in provenance_rows}
    prefill_rows = local_metadata_prefill_rows(priority_rows, provenance_by_name, inventory_by_file)
    prefill_by_name = {row["name"]: row for row in prefill_rows}
    crosswalk_rows = local_source_crosswalk_rows(priority_rows, provenance_by_name, prefill_by_name)
    missing_rows = local_source_missing_field_rows(priority_rows, provenance_by_name)
    existing_source_count = sum(1 for row in inventory_rows if row["exists"])
    atlas_inventory_count = sum(1 for row in inventory_rows if row["exists"] and str(row["sourceCategory"]).startswith("ATLAS3D"))
    priority_names = {row["name"] for row in priority_rows}
    priority_provenance = [provenance_by_name[name] for name in priority_names if name in provenance_by_name]
    capsule = {
        "type": "mts-local-source-ingestion",
        "version": 1,
        "generatedAt": dt.datetime.now(dt.UTC).isoformat(),
        "sourceScript": "scripts/mts-failure-lab.py",
        "canonicalMtsStatus": "locked",
        "sourceDir": str(source_dir),
        "verdict": "local source provenance prefill ready; external metadata still required for missing systematics fields",
        "split": {
            "seed": split["seed"],
            "holdoutFraction": split["holdoutFraction"],
            "trainCount": len(split["train"]),
            "holdoutCount": len(split["holdout"]),
        },
        "metrics": {
            "inventoryRowCount": len(inventory_rows),
            "existingSourceFileCount": existing_source_count,
            "atlasInventoryOnlyFileCount": atlas_inventory_count,
            "mrtGalaxyCount": len(mrt_stats),
            "mrtDataRowCount": mrt_header.get("rowCount", 0),
            "localCurveCount": len(curves),
            "localCurveMrtCoverageCount": sum(1 for row in provenance_rows if row["inMassModelsMrt"]),
            "localCurveRotmodCoverageCount": sum(1 for row in provenance_rows if row["inRotmodArchive"]),
            "localCurveSfbCoverageCount": sum(1 for row in provenance_rows if row["inSfbArchive"]),
            "priorityCaseCount": len(priority_rows),
            "priorityMrtCoverageCount": sum(1 for row in priority_provenance if row["inMassModelsMrt"]),
            "priorityRotmodCoverageCount": sum(1 for row in priority_provenance if row["inRotmodArchive"]),
            "prioritySfbCoverageCount": sum(1 for row in priority_provenance if row["inSfbArchive"]),
            "prefillRowCount": len(prefill_rows),
            "missingFieldRowCount": len(missing_rows),
        },
        "rules": {
            "claimStatus": "diagnostic only",
            "transportLawChangeAllowed": False,
            "atlas3dParsing": "inventory-only in v1",
            "missingFieldsRemainMissing": [
                "inclination provenance/uncertainty",
                "beam/FWHM",
                "covariance",
                "quality flags",
                "bulge/disk decomposition provenance",
                "external M/L priors",
            ],
        },
    }
    out_dir.mkdir(parents=True, exist_ok=True)
    write_csv(out_dir / "mts-local-source-inventory.csv", inventory_rows)
    write_csv(out_dir / "mts-local-sparc-provenance.csv", provenance_rows)
    write_csv(out_dir / "mts-local-source-crosswalk.csv", crosswalk_rows)
    write_csv(out_dir / "mts-local-metadata-prefill.csv", prefill_rows)
    write_csv(out_dir / "mts-local-source-missing-fields.csv", missing_rows)
    (out_dir / "mts-local-source-ingest-report.md").write_text(
        local_source_ingest_report(capsule, inventory_rows, provenance_rows, crosswalk_rows, missing_rows),
        encoding="utf-8",
    )
    (out_dir / "mts-local-source-ingest-capsule.json").write_text(json.dumps(json_clean(capsule), indent=2), encoding="utf-8")
    return capsule


