def official_source_cache_file(cache_dir: Path, file_name: str) -> Path:
    return cache_dir / file_name


def official_download_file(spec: dict, cache_dir: Path, offline: bool) -> dict:
    path = official_source_cache_file(cache_dir, spec["fileName"])
    row = {
        "fileName": spec["fileName"],
        "url": spec["url"],
        "sourceCategory": spec["sourceCategory"],
        "parseMode": spec["parseMode"],
        "requiredForV1": spec["requiredForV1"],
        "cachePath": str(path),
        "offline": offline,
        "downloaded": False,
        "usedCached": path.exists(),
        "fetchStatus": "",
        "sizeBytes": path.stat().st_size if path.exists() else "",
        "sha256": file_sha256(path) if path.exists() else "",
        "archiveMemberCount": "",
        "firstArchiveMembers": "",
    }
    if offline:
        row["fetchStatus"] = "cached" if path.exists() else "missing-offline"
    else:
        try:
            cache_dir.mkdir(parents=True, exist_ok=True)
            with urllib.request.urlopen(spec["url"], timeout=45) as response:
                content_length = response.headers.get("Content-Length")
                if content_length and int(content_length) > spec["maxBytes"]:
                    row["fetchStatus"] = f"skipped-too-large:{content_length}"
                else:
                    data = response.read(spec["maxBytes"] + 1)
                    if len(data) > spec["maxBytes"]:
                        row["fetchStatus"] = f"skipped-too-large:{len(data)}"
                    else:
                        path.write_bytes(data)
                        row["downloaded"] = True
                        row["usedCached"] = False
                        row["fetchStatus"] = "downloaded"
        except (OSError, urllib.error.URLError, TimeoutError) as exc:
            row["fetchStatus"] = f"download-error:{exc}"
    if path.exists():
        row["sizeBytes"] = path.stat().st_size
        row["sha256"] = file_sha256(path)
        members, status = archive_members(path)
        row["archiveMemberCount"] = len(members) if status == "ok" else 0
        row["firstArchiveMembers"] = "; ".join(members[:5])
        if not row["fetchStatus"]:
            row["fetchStatus"] = "cached"
    return row


def official_source_inventory_rows(cache_dir: Path, offline: bool) -> list[dict]:
    return [official_download_file(spec, cache_dir, offline) for spec in OFFICIAL_SOURCE_TARGETS]


def official_source_inventory_output_rows(rows: list[dict]) -> list[dict]:
    output = []
    for row in rows:
        available = bool(row.get("sha256"))
        output.append(
            {
                "fileName": row["fileName"],
                "url": row["url"],
                "sourceCategory": row["sourceCategory"],
                "parseMode": row["parseMode"],
                "requiredForV1": row["requiredForV1"],
                "cachePath": row["cachePath"],
                "existsInCache": available,
                "cacheStatus": "available" if available else row["fetchStatus"],
                "sizeBytes": row["sizeBytes"],
                "sha256": row["sha256"],
                "archiveMemberCount": row["archiveMemberCount"],
                "firstArchiveMembers": row["firstArchiveMembers"],
            }
        )
    return output


def official_parse_reference_map(text: str) -> dict[str, str]:
    note_match = re.search(r"Note \(4\):(.*?)(?:\n\s*[A-Za-z0-9_\-]+\s+\d+\s+[-0-9.]+\s+[-0-9.]+|\Z)", text, re.S)
    if not note_match:
        return {}
    note = re.sub(r"\s+", " ", note_match.group(1)).strip()
    pattern = re.compile(r"([A-Za-z][A-Za-z0-9]{1,3}\d{2})\s*=\s*(.*?)(?=\s+[A-Za-z][A-Za-z0-9]{1,3}\d{2}\s*=|\Z)")
    refs = {}
    for code, value in pattern.findall(note):
        refs[code] = value.strip().rstrip(".")
    return refs


def parse_official_table1(path: Path) -> tuple[dict[str, dict], dict]:
    if not path.exists():
        return {}, {"readStatus": "missing"}
    text = path.read_text(encoding="utf-8", errors="replace")
    ref_map = official_parse_reference_map(text)
    rows = {}
    for line in text.splitlines():
        parts = line.split()
        if len(parts) < 19:
            continue
        try:
            hubble_type = int(parts[1])
            distance = float(parts[2])
            distance_error = float(parts[3])
            distance_method_code = int(parts[4])
            inclination = float(parts[5])
            inclination_error = float(parts[6])
            luminosity36 = float(parts[7])
            effective_radius = float(parts[9])
            disk_scale_length = float(parts[11])
            hi_mass = float(parts[13])
            hi_radius = float(parts[14])
            vflat = float(parts[15])
            vflat_error = float(parts[16])
            quality_code = int(parts[17])
        except ValueError:
            continue
        ref_codes = " ".join(parts[18:]).replace(" ", "")
        ref_list = [item.strip() for item in re.split(r"[,;]", ref_codes) if item.strip()]
        rows[parts[0]] = {
            "name": parts[0],
            "hubbleType": hubble_type,
            "distanceMpc": distance,
            "distanceUncertaintyMpc": distance_error,
            "distanceMethodCode": distance_method_code,
            "distanceMethod": SPARC_DISTANCE_METHODS.get(distance_method_code, f"unknown method {distance_method_code}"),
            "inclinationDeg": inclination,
            "inclinationUncertaintyDeg": inclination_error,
            "luminosity36_1e9Lsun": luminosity36,
            "effectiveRadiusKpc": effective_radius,
            "diskScaleLengthKpc": disk_scale_length,
            "hiMass_1e9Msun": hi_mass,
            "hiRadiusKpc": hi_radius,
            "vflatKmS": vflat,
            "vflatUncertaintyKmS": vflat_error,
            "qualityCode": quality_code,
            "qualityLabel": SPARC_QUALITY_FLAGS.get(quality_code, f"unknown quality {quality_code}"),
            "rotationCurveRefCodes": ", ".join(ref_list),
            "rotationCurveReferences": "; ".join(
                f"{code}={ref_map.get(code, 'reference text not parsed')}" for code in ref_list
            ),
        }
    return rows, {
        "readStatus": "ok",
        "rowCount": len(rows),
        "referenceCodeCount": len(ref_map),
        "distanceUnit": "Mpc",
        "inclinationUnit": "deg",
        "qualityFlagMeaning": "1=High; 2=Medium; 3=Low",
        "sourceTitle": "SPARC. I. Mass Models for 175 Disk Galaxies with Spitzer Photometry and Accurate Rotation Curves; Table: Galaxy Sample",
    }


def parse_official_bulges(path: Path) -> tuple[dict[str, dict], dict]:
    if not path.exists():
        return {}, {"readStatus": "missing"}
    text = path.read_text(encoding="utf-8", errors="replace")
    rows = {}
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        parts = stripped.split()
        if len(parts) < 2:
            continue
        try:
            lbul = float(parts[1])
        except ValueError:
            continue
        rows[parts[0]] = {
            "name": parts[0],
            "bulgeLuminosity_1e9Lsun": lbul,
            "hasBulgeLuminosity": True,
            "bulgePresent": lbul > 0,
        }
    return rows, {
        "readStatus": "ok",
        "rowCount": len(rows),
        "caution": "SPARC bulge-disk decompositions are non-parametric; bulges are linearly extrapolated in the outer regions.",
    }


def normalize_galaxy_token(value: str) -> str:
    return re.sub(r"[^a-z0-9]", "", value.lower())


def official_decomposition_archive_coverage(path: Path, names: Iterable[str]) -> dict[str, int]:
    members, status = archive_members(path)
    if status != "ok":
        return {}
    normalized_members = [normalize_galaxy_token(Path(member).name) for member in members]
    coverage = {}
    for name in names:
        token = normalize_galaxy_token(name)
        count = sum(1 for member in normalized_members if token and token in member)
        if count:
            coverage[name] = count
    return coverage


def read_metadata_prefill_csv(path: Path) -> dict[str, dict]:
    if not path.exists():
        return {}
    rows: dict[str, dict] = {}
    with path.open(newline="", encoding="utf-8-sig") as handle:
        reader = csv.DictReader(handle)
        for raw in reader:
            name = (raw.get("name") or "").strip()
            if name:
                rows[name] = {field: (raw.get(field, "") or "").strip() for field in METADATA_EXTERNAL_FIELDS}
    return rows


def append_metadata_text(row: dict, field: str, text: str) -> None:
    if not text:
        return
    current = str(row.get(field, "") or "").strip()
    if not current:
        row[field] = text
    elif text not in current:
        row[field] = f"{current} | {text}"


def official_metadata_prefill_rows(
    priority_rows: list[dict],
    local_prefill_by_name: dict[str, dict],
    table1_by_name: dict[str, dict],
    bulges_by_name: dict[str, dict],
    decomp_coverage: dict[str, int],
    inventory_by_file: dict[str, dict],
) -> list[dict]:
    table_hash = source_short_hash(inventory_by_file, "SPARC_Lelli2016c.mrt")
    bulges_hash = source_short_hash(inventory_by_file, "Bulges.mrt")
    decomp_hash = source_short_hash(inventory_by_file, "BulgeDiskDec_LTG.zip")
    rows = []
    for priority in priority_rows:
        name = priority["name"]
        row = {field: "" for field in METADATA_EXTERNAL_FIELDS}
        row.update(local_prefill_by_name.get(name, {}))
        row["name"] = name
        table = table1_by_name.get(name)
        if table:
            row["distanceMpc"] = fmt_num(table["distanceMpc"])
            row["distanceUncertaintyMpc"] = fmt_num(table["distanceUncertaintyMpc"])
            row["distanceSource"] = (
                f"Official SPARC Table1 D/e_D/f_D; method={table['distanceMethod']}; "
                f"sha256={table_hash}"
            )
            row["inclinationDeg"] = fmt_num(table["inclinationDeg"])
            row["inclinationUncertaintyDeg"] = fmt_num(table["inclinationUncertaintyDeg"])
            row["inclinationSource"] = f"Official SPARC Table1 Inc/e_Inc; sha256={table_hash}"
            row["qualityFlags"] = f"Official SPARC quality Q={table['qualityCode']} ({table['qualityLabel']})"
            append_metadata_text(
                row,
                "rotationCurveExtractionSource",
                f"Official SPARC Table1 rotation-curve Ref codes: {table['rotationCurveRefCodes']}; sha256={table_hash}",
            )
            if not row.get("covarianceAvailable"):
                row["covarianceAvailable"] = "false"
            append_metadata_text(
                row,
                "notes",
                "Official SPARC Table1 supplies distance uncertainty, inclination uncertainty, quality flag, and rotation-curve reference codes.",
            )
        bulge = bulges_by_name.get(name)
        if bulge:
            decomp_text = (
                f"Official SPARC Bulges.mrt non-parametric bulge luminosity row; "
                f"Lbul={fmt_num(bulge['bulgeLuminosity_1e9Lsun'])}e9 Lsun; sha256={bulges_hash}"
            )
            if name in decomp_coverage:
                decomp_text += f"; BulgeDiskDec_LTG.zip member count={decomp_coverage[name]}; sha256={decomp_hash}"
            row["decompositionSource"] = decomp_text
            append_metadata_text(
                row,
                "notes",
                "Bulge/decomposition provenance is present, but external stellar M/L priors are still not supplied.",
            )
        append_metadata_text(
            row,
            "notes",
            "Beam/FWHM and covariance remain missing unless supplied by a later source.",
        )
        rows.append(row)
    rows.sort(key=lambda item: item["name"])
    return rows


def official_table1_provenance_rows(
    curves: list[dict],
    table1_by_name: dict[str, dict],
    bulges_by_name: dict[str, dict],
    decomp_coverage: dict[str, int],
    inventory_by_file: dict[str, dict],
) -> list[dict]:
    table_sha = inventory_by_file.get("SPARC_Lelli2016c.mrt", {}).get("sha256", "")
    bulges_sha = inventory_by_file.get("Bulges.mrt", {}).get("sha256", "")
    rows = []
    for curve in sorted(curves, key=lambda item: item["name"]):
        table = table1_by_name.get(curve["name"], {})
        bulge = bulges_by_name.get(curve["name"], {})
        rows.append(
            {
                "name": curve["name"],
                "inOfficialTable1": bool(table),
                "officialDistanceMpc": table.get("distanceMpc", ""),
                "officialDistanceUncertaintyMpc": table.get("distanceUncertaintyMpc", ""),
                "distanceMethodCode": table.get("distanceMethodCode", ""),
                "distanceMethod": table.get("distanceMethod", ""),
                "inclinationDeg": table.get("inclinationDeg", ""),
                "inclinationUncertaintyDeg": table.get("inclinationUncertaintyDeg", ""),
                "qualityCode": table.get("qualityCode", ""),
                "qualityLabel": table.get("qualityLabel", ""),
                "rotationCurveRefCodes": table.get("rotationCurveRefCodes", ""),
                "rotationCurveReferences": table.get("rotationCurveReferences", ""),
                "vflatKmS": table.get("vflatKmS", ""),
                "vflatUncertaintyKmS": table.get("vflatUncertaintyKmS", ""),
                "inOfficialBulges": bool(bulge),
                "bulgeLuminosity_1e9Lsun": bulge.get("bulgeLuminosity_1e9Lsun", ""),
                "bulgePresent": bulge.get("bulgePresent", ""),
                "decompositionArchiveMemberCount": decomp_coverage.get(curve["name"], 0),
                "table1Sha256": table_sha,
                "bulgesSha256": bulges_sha,
            }
        )
    return rows


def official_source_crosswalk_rows(
    priority_rows: list[dict],
    metadata_rows: list[dict],
    crosswalk_rows: list[dict],
    table1_by_name: dict[str, dict],
    bulges_by_name: dict[str, dict],
    decomp_coverage: dict[str, int],
) -> list[dict]:
    meta_by_name = {row["name"]: row for row in metadata_rows}
    cross_by_name = {row["name"]: row for row in crosswalk_rows}
    rows = []
    for index, priority in enumerate(priority_rows, start=1):
        name = priority["name"]
        meta = meta_by_name.get(name, {})
        cross = cross_by_name.get(name, {})
        supplied_fields = [field for field in METADATA_EXTERNAL_FIELDS if field != "name" and str(meta.get(field, "") or "").strip()]
        rows.append(
            {
                "rank": index,
                "name": name,
                "namedCase": name in METADATA_NAMED_CASES,
                "evidenceBucket": priority["evidenceBucket"],
                "metadataVerdict": cross.get("metadataVerdict", ""),
                "reviewStatus": cross.get("reviewStatus", ""),
                "requiredEvidence": cross.get("requiredEvidence", ""),
                "suppliedEvidence": cross.get("suppliedEvidence", ""),
                "missingEvidence": cross.get("missingEvidence", ""),
                "officialTable1Coverage": name in table1_by_name,
                "officialBulgesCoverage": name in bulges_by_name,
                "officialDecompositionArchiveCoverage": name in decomp_coverage,
                "prefilledMetadataFields": "; ".join(supplied_fields),
                "beamFwhmStillMissing": not metadata_has_positive_number(meta, "beamFwhmArcsec"),
                "covarianceStillMissing": metadata_parse_bool(meta.get("covarianceAvailable")) is not True,
                "stellarMlPriorStillMissing": not metadata_has_positive_number(meta, "mlDisk") and not metadata_has_positive_number(meta, "mlBulge"),
                "canonicalMtsChanged": False,
            }
        )
    rows.sort(key=lambda item: (0 if item["namedCase"] else 1, int(item["rank"]), item["name"]))
    return rows


def official_missing_field_rows(priority_rows: list[dict], metadata_rows: list[dict]) -> list[dict]:
    meta_by_name = {row["name"]: row for row in metadata_rows}
    rows = []
    for priority in priority_rows:
        meta = meta_by_name.get(priority["name"], {})
        flags = metadata_case_support_flags(meta)
        missing_evidence = [key for key in metadata_required_support(priority) if not flags.get(key)]
        field_map = {
            "hasInclinationEvidence": [("inclinationDeg", "Official Table1 should supply inclination; missing means table coverage failed.")],
            "hasBeamEvidence": [
                ("beamFwhmArcsec", "Official SPARC Table1 does not provide beam/FWHM."),
                ("spatialResolutionKpc", "Official SPARC Table1 does not provide physical spatial resolution."),
                ("beamSource", "Official SPARC Table1 does not provide beam/aperture source provenance."),
            ],
            "hasMlEvidence": [
                ("mlDisk", "Official SPARC files parsed in v1 do not provide an external disk M/L prior."),
                ("mlBulge", "Official SPARC files parsed in v1 do not provide an external bulge M/L prior."),
                ("mlPriorSource", "Official SPARC files parsed in v1 do not provide external stellar M/L prior provenance."),
            ],
            "hasDecompositionEvidence": [("decompositionSource", "Official bulge/decomposition provenance was not found for this case.")],
            "hasCovarianceEvidence": [
                ("covarianceAvailable", "Official SPARC Table1/MRT files provide errors but not a covariance matrix."),
                ("errorModelSource", "Point-error provenance is present, but covariance/error-floor provenance remains missing."),
            ],
            "hasQualityEvidence": [("qualityFlags", "Official Table1 should supply quality flags; missing means table coverage failed.")],
            "hasExtractionEvidence": [("rotationCurveExtractionSource", "Official Table1 should supply rotation-curve reference codes; missing means table coverage failed.")],
            "hasReductionEvidence": [("reductionPipelineSource", "Official source provenance should be present for claim-safe rows.")],
        }
        for evidence in missing_evidence:
            if evidence == "hasCovarianceEvidence":
                rows.append(
                    {
                        "name": priority["name"],
                        "evidenceBucket": priority["evidenceBucket"],
                        "missingEvidenceFlag": evidence,
                        "missingField": "covarianceAvailable",
                        "reason": "Official SPARC Table1/MRT files provide point-error provenance but not a covariance matrix.",
                        "canonicalMtsChanged": False,
                    }
                )
                if not metadata_has_text(meta, "errorModelSource"):
                    rows.append(
                        {
                            "name": priority["name"],
                            "evidenceBucket": priority["evidenceBucket"],
                            "missingEvidenceFlag": evidence,
                            "missingField": "errorModelSource",
                            "reason": "No point-error or covariance/error-floor provenance was supplied.",
                            "canonicalMtsChanged": False,
                        }
                    )
                continue
            for field, reason in field_map.get(evidence, []):
                rows.append(
                    {
                        "name": priority["name"],
                        "evidenceBucket": priority["evidenceBucket"],
                        "missingEvidenceFlag": evidence,
                        "missingField": field,
                        "reason": reason,
                        "canonicalMtsChanged": False,
                    }
                )
    rows.sort(key=lambda item: (item["name"], item["missingEvidenceFlag"], item["missingField"]))
    return rows


def official_source_fetch_report(
    capsule: dict,
    inventory_rows: list[dict],
    table_rows: list[dict],
    crosswalk_rows: list[dict],
    missing_rows: list[dict],
) -> str:
    metrics = capsule["metrics"]
    named = [row for row in crosswalk_rows if row["name"] in METADATA_NAMED_CASES]
    named.sort(key=lambda row: METADATA_NAMED_CASES.index(row["name"]))
    table_by_name = {row["name"]: row for row in table_rows}
    verdict_counts = metrics["metadataVerdictCounts"]
    missing_counts: dict[str, int] = {}
    for row in missing_rows:
        missing_counts[row["missingField"]] = missing_counts.get(row["missingField"], 0) + 1
    lines = [
        "# MTS Official SPARC Metadata Fetch And Provenance Merge",
        "",
        "This diagnostic fetches small official SPARC provenance files to the D drive and merges them with the local source prefill. Canonical MTS remains locked.",
        "",
        "## Headline",
        "",
        f"Verdict: **{capsule['verdict']}**.",
        f"Source cache: `{capsule['sourceCache']}`.",
        f"Official Table1 LTG coverage: {metrics['officialTable1CoverageCount']}/{metrics['localCurveCount']}.",
        f"Priority cases with Table1 coverage: {metrics['priorityTable1CoverageCount']}/{metrics['priorityCaseCount']}.",
        f"Priority cases with bulge/decomposition provenance: {metrics['priorityBulgesCoverageCount']}/{metrics['priorityCaseCount']}.",
        f"Metadata verdict counts: {', '.join(f'{key}={value}' for key, value in sorted(verdict_counts.items()))}.",
        "",
        "## Source Inventory",
        "",
        "| File | Status | Size | SHA256 |",
        "| --- | --- | ---: | --- |",
    ]
    for row in inventory_rows:
        lines.append(f"| {row['fileName']} | {row['cacheStatus']} | {row['sizeBytes']} | {str(row['sha256'])[:16]} |")
    lines.extend(
        [
            "",
            "## Named Case Official Metadata",
            "",
            "| Galaxy | Bucket | D +- eD | Inc +- eInc | Q | Ref | Verdict | Missing evidence |",
            "| --- | --- | --- | --- | --- | --- | --- | --- |",
        ]
    )
    for row in named:
        table = table_by_name.get(row["name"], {})
        distance = f"{fmt(table.get('officialDistanceMpc'))} +- {fmt(table.get('officialDistanceUncertaintyMpc'))}"
        inclination = f"{fmt(table.get('inclinationDeg'))} +- {fmt(table.get('inclinationUncertaintyDeg'))}"
        quality = f"{table.get('qualityCode', '')} {table.get('qualityLabel', '')}".strip()
        lines.append(
            f"| {row['name']} | {row['evidenceBucket']} | {distance} | {inclination} | {quality} | "
            f"{table.get('rotationCurveRefCodes', '')} | {row['metadataVerdict']} | {row['missingEvidence']} |"
        )
    lines.extend(
        [
            "",
            "## Remaining Missing Fields",
            "",
            "| Field | Count |",
            "| --- | ---: |",
        ]
    )
    for field, count in sorted(missing_counts.items(), key=lambda item: (-item[1], item[0])):
        lines.append(f"| {field} | {count} |")
    lines.extend(
        [
            "",
            "## Interpretation Discipline",
            "",
            "- Official Table1 provides inclination, distance uncertainty, quality flags, and rotation-curve reference codes.",
            "- Bulges.mrt / decomposition coverage supports decomposition provenance, not external stellar M/L priors.",
            "- Beam/FWHM and covariance remain missing unless a later source supplies them directly.",
            "- No MTS formula, q law, amplitude law, route law, two-scale law, or claim status is promoted.",
            "",
        ]
    )
    return "\n".join(lines)


def write_official_source_fetch_artifacts(
    out_dir: Path,
    curves: list[dict],
    holdout_fraction: float,
    source_cache: Path,
    offline: bool,
) -> dict:
    deficit_rows = support_deficit_rows(curves)
    split = stratified_split(curves, SPLIT_SEED, holdout_fraction)
    readiness_rows = metadata_readiness_rows(curves, deficit_rows, split)
    priority_rows = metadata_priority_rows(readiness_rows)
    inventory_rows = official_source_inventory_rows(source_cache, offline)
    inventory_output_rows = official_source_inventory_output_rows(inventory_rows)
    inventory_by_file = {row["fileName"]: row for row in inventory_rows}
    table1_by_name, table1_header = parse_official_table1(source_cache / "SPARC_Lelli2016c.mrt")
    bulges_by_name, bulges_header = parse_official_bulges(source_cache / "Bulges.mrt")
    decomp_coverage = official_decomposition_archive_coverage(
        source_cache / "BulgeDiskDec_LTG.zip",
        [curve["name"] for curve in curves],
    )
    local_prefill = read_metadata_prefill_csv(DEFAULT_LOCAL_SOURCE_INGEST_OUT / "mts-local-metadata-prefill.csv")
    prefill_rows = official_metadata_prefill_rows(
        priority_rows,
        local_prefill,
        table1_by_name,
        bulges_by_name,
        decomp_coverage,
        inventory_by_file,
    )
    crosswalk_base, verdict_rows, validation_rows = metadata_crosswalk_rows(priority_rows, prefill_rows, [])
    source_crosswalk = official_source_crosswalk_rows(
        priority_rows,
        prefill_rows,
        crosswalk_base,
        table1_by_name,
        bulges_by_name,
        decomp_coverage,
    )
    missing_rows = official_missing_field_rows(priority_rows, prefill_rows)
    table_rows = official_table1_provenance_rows(curves, table1_by_name, bulges_by_name, decomp_coverage, inventory_by_file)
    verdict_counts = metadata_crosswalk_summary(verdict_rows)["verdictCounts"]
    priority_names = {row["name"] for row in priority_rows}
    capsule = {
        "type": "mts-official-sparc-source-fetch",
        "version": 1,
        "generatedAt": dt.datetime.now(dt.UTC).isoformat(),
        "sourceScript": "scripts/mts-failure-lab.py",
        "canonicalMtsStatus": "locked",
        "sourceCache": str(source_cache),
        "offline": offline,
        "verdict": "official SPARC provenance merged; beam/FWHM and covariance remain explicit gaps",
        "officialSources": {
            "dataPage": OFFICIAL_SPARC_BASE_URL,
            "table1": urllib.parse.urljoin(OFFICIAL_SPARC_BASE_URL, "SPARC_Lelli2016c.mrt"),
        },
        "split": {
            "seed": split["seed"],
            "holdoutFraction": split["holdoutFraction"],
            "trainCount": len(split["train"]),
            "holdoutCount": len(split["holdout"]),
        },
        "metrics": {
            "localCurveCount": len(curves),
            "officialTable1CoverageCount": sum(1 for curve in curves if curve["name"] in table1_by_name),
            "officialBulgesCoverageCount": sum(1 for curve in curves if curve["name"] in bulges_by_name),
            "officialDecompositionArchiveCoverageCount": len(decomp_coverage),
            "priorityCaseCount": len(priority_rows),
            "priorityTable1CoverageCount": sum(1 for name in priority_names if name in table1_by_name),
            "priorityBulgesCoverageCount": sum(1 for name in priority_names if name in bulges_by_name),
            "priorityDecompositionArchiveCoverageCount": sum(1 for name in priority_names if name in decomp_coverage),
            "metadataVerdictCounts": verdict_counts,
            "validationErrorCount": sum(1 for row in validation_rows if row["severity"] == "error"),
            "validationWarningCount": sum(1 for row in validation_rows if row["severity"] == "warning"),
            "table1ReadStatus": table1_header.get("readStatus", ""),
            "bulgesReadStatus": bulges_header.get("readStatus", ""),
            "downloadedFileCount": sum(1 for row in inventory_rows if row["downloaded"]),
        },
        "rules": {
            "claimStatus": "diagnostic only",
            "transportLawChangeAllowed": False,
            "largeDownloadsExcluded": True,
            "remainingUnsupportedFields": ["beam/FWHM", "covariance", "external stellar M/L priors"],
        },
    }
    out_dir.mkdir(parents=True, exist_ok=True)
    write_csv(out_dir / "mts-official-source-inventory.csv", inventory_output_rows)
    write_csv(out_dir / "mts-official-sparc-table1-provenance.csv", table_rows)
    write_csv(out_dir / "mts-official-source-metadata-prefill.csv", prefill_rows)
    write_csv(out_dir / "mts-official-source-crosswalk.csv", source_crosswalk)
    write_csv(out_dir / "mts-official-source-missing-fields.csv", missing_rows)
    (out_dir / "mts-official-source-fetch-report.md").write_text(
        official_source_fetch_report(capsule, inventory_output_rows, table_rows, source_crosswalk, missing_rows),
        encoding="utf-8",
    )
    (out_dir / "mts-official-source-fetch-capsule.json").write_text(json.dumps(json_clean(capsule), indent=2), encoding="utf-8")
    return capsule


SYSTEMATICS_NAMED_CASES = [
    "ESO563-G021",
    "IC4202",
    "NGC4217",
    "UGC06973",
    "UGC02953",
    "NGC2903",
    "UGC02916",
]


def read_csv_rows(path: Path) -> list[dict]:
    if not path.exists():
        return []
    with path.open(newline="", encoding="utf-8-sig") as handle:
        return [dict(row) for row in csv.DictReader(handle)]


def systematics_closure_group(row: dict) -> str:
    missing = row.get("missingEvidence", "")
    if "hasMlEvidence" in missing and "hasBeamEvidence" in missing:
        return "mixed central mass-model case"
    if "hasBeamEvidence" in missing:
        return "beam/aperture metadata needed"
    if "hasCovarianceEvidence" in missing:
        return "covariance/error model needed"
    if "hasMlEvidence" in missing:
        return "stellar M/L prior needed"
    return "external evidence still required"


def systematics_group_rule(group: str) -> dict:
    rules = {
        "stellar M/L prior needed": {
            "missingFields": "mlDisk; mlBulge; mlPriorSource",
            "supportingEvidence": "external stellar M/L prior or population-synthesis/decomposition uncertainty supports the local M/L-sensitive diagnosis",
            "contradictingEvidence": "independent M/L priors are tight near the defaults but the residual remains high",
            "sourceCategory": "stellar-population M/L prior; decomposition paper; population-calibration table",
        },
        "covariance/error model needed": {
            "missingFields": "covarianceAvailable; errorModelSource",
            "supportingEvidence": "published covariance, error floor, or error-model provenance shows the residual is not statistically robust",
            "contradictingEvidence": "small independent uncertainties with no covariance/quality caveats leave the residual significant",
            "sourceCategory": "rotation-curve error model; covariance table; quality/error-floor notes",
        },
        "beam/aperture metadata needed": {
            "missingFields": "beamFwhmArcsec; spatialResolutionKpc; beamSource",
            "supportingEvidence": "beam/FWHM, aperture, or spatial-resolution metadata supports central/aperture sensitivity",
            "contradictingEvidence": "high-resolution extraction with clean aperture metadata contradicts central/aperture diagnosis",
            "sourceCategory": "HI/Ha beam table; observation log; rotation-curve extraction paper",
        },
        "mixed central mass-model case": {
            "missingFields": "mlDisk; mlBulge; mlPriorSource; beamFwhmArcsec; spatialResolutionKpc; beamSource",
            "supportingEvidence": "central mass-model and beam/aperture metadata jointly explain baryonic-floor or central residual tension",
            "contradictingEvidence": "secure central mass model and high-resolution aperture metadata leave the central residual unresolved",
            "sourceCategory": "stellar M/L prior; bulge/disk decomposition; beam/aperture metadata",
        },
    }
    return rules.get(
        group,
        {
            "missingFields": "external metadata",
            "supportingEvidence": "external provenance supports the current systematics diagnosis",
            "contradictingEvidence": "external provenance contradicts the diagnosis",
            "sourceCategory": "external observational provenance",
        },
    )


def systematics_claim_verdict(row: dict) -> str:
    if row.get("metadataVerdict") == "claim-safe with provenance":
        return "closed by official metadata"
    if row.get("metadataVerdict") == "metadata weakly supports diagnosis":
        return "external evidence still required"
    if row.get("metadataVerdict") == "metadata contradicts diagnosis":
        return "candidate for renewed MTS/data review"
    return "do not use for transport-law fitting yet"


def source_cache_subdir_for_group(source_cache: Path, group: str) -> Path:
    slug = re.sub(r"[^a-z0-9]+", "-", group.lower()).strip("-")
    return source_cache / slug


def systematics_priority_rows(crosswalk_rows: list[dict], table_rows: list[dict]) -> list[dict]:
    table_by_name = {row["name"]: row for row in table_rows}
    weak_rows = [row for row in crosswalk_rows if row.get("metadataVerdict") == "metadata weakly supports diagnosis"]
    priority = []
    for index, row in enumerate(weak_rows, start=1):
        table = table_by_name.get(row["name"], {})
        group = systematics_closure_group(row)
        rule = systematics_group_rule(group)
        priority.append(
            {
                "rank": index,
                "name": row["name"],
                "namedCase": row["name"] in SYSTEMATICS_NAMED_CASES,
                "closureGroup": group,
                "evidenceBucket": row["evidenceBucket"],
                "metadataVerdict": row["metadataVerdict"],
                "claimSafeVerdict": systematics_claim_verdict(row),
                "missingEvidence": row["missingEvidence"],
                "missingFields": rule["missingFields"],
                "suppliedEvidence": row.get("suppliedEvidence", ""),
                "rotationCurveRefCodes": table.get("rotationCurveRefCodes", ""),
                "rotationCurveReferences": table.get("rotationCurveReferences", ""),
                "qualityCode": table.get("qualityCode", ""),
                "qualityLabel": table.get("qualityLabel", ""),
                "inclinationDeg": table.get("inclinationDeg", ""),
                "inclinationUncertaintyDeg": table.get("inclinationUncertaintyDeg", ""),
                "distanceMpc": table.get("officialDistanceMpc", ""),
                "distanceUncertaintyMpc": table.get("officialDistanceUncertaintyMpc", ""),
                "supportingEvidenceNeeded": rule["supportingEvidence"],
                "contradictingEvidence": rule["contradictingEvidence"],
                "transportLawFittingAllowed": False,
                "canonicalMtsChanged": False,
            }
        )
    priority.sort(key=lambda item: (0 if item["namedCase"] else 1, item["closureGroup"], int(item["rank"]), item["name"]))
    for new_rank, row in enumerate(priority, start=1):
        row["rank"] = new_rank
    return priority


def systematics_source_target_rows(priority_rows: list[dict], source_cache: Path) -> list[dict]:
    rows = []
    for row in priority_rows:
        rule = systematics_group_rule(row["closureGroup"])
        cache_dir = source_cache_subdir_for_group(source_cache, row["closureGroup"])
        rows.append(
            {
                "name": row["name"],
                "closureGroup": row["closureGroup"],
                "evidenceBucket": row["evidenceBucket"],
                "spArcReferenceCodes": row["rotationCurveRefCodes"],
                "spArcReferences": row["rotationCurveReferences"],
                "sourceCategory": rule["sourceCategory"],
                "fieldsToFind": row["missingFields"],
                "supportingEvidenceNeeded": rule["supportingEvidence"],
                "contradictingEvidence": rule["contradictingEvidence"],
                "sourceCachePath": str(cache_dir),
                "networkFetchStatus": "not fetched in v1; scaffold only",
                "largeDownloadAllowed": False,
                "nextAction": "fetch small source table or paper-derived metadata into the D-drive cache, then feed it through metadatacrosswalk",
            }
        )
    return rows


def systematics_evidence_rule_rows(priority_rows: list[dict]) -> list[dict]:
    groups = sorted({row["closureGroup"] for row in priority_rows})
    rows = []
    for group in groups:
        rule = systematics_group_rule(group)
        group_rows = [row for row in priority_rows if row["closureGroup"] == group]
        rows.append(
            {
                "closureGroup": group,
                "caseCount": len(group_rows),
                "missingFields": rule["missingFields"],
                "supportingEvidence": rule["supportingEvidence"],
                "contradictingEvidence": rule["contradictingEvidence"],
                "ifSupportedVerdict": "external evidence still required until metadata file is filled; keep out of transport-law fitting",
                "ifContradictedVerdict": "candidate for renewed MTS/data review",
                "transportLawPromotionAllowed": False,
            }
        )
    return rows


def systematics_named_case_rows(priority_rows: list[dict]) -> list[dict]:
    by_name = {row["name"]: row for row in priority_rows}
    rows = []
    for name in SYSTEMATICS_NAMED_CASES:
        row = by_name.get(name)
        if row:
            rows.append(
                {
                    "name": name,
                    "includedInWeakSet": True,
                    "closureGroup": row["closureGroup"],
                    "evidenceBucket": row["evidenceBucket"],
                    "missingEvidence": row["missingEvidence"],
                    "rotationCurveRefCodes": row["rotationCurveRefCodes"],
                    "claimSafeVerdict": row["claimSafeVerdict"],
                    "nextEvidenceTarget": row["missingFields"],
                    "transportLawFittingAllowed": False,
                }
            )
        else:
            rows.append(
                {
                    "name": name,
                    "includedInWeakSet": False,
                    "closureGroup": "already closed or not priority",
                    "evidenceBucket": "",
                    "missingEvidence": "",
                    "rotationCurveRefCodes": "",
                    "claimSafeVerdict": "closed by official metadata",
                    "nextEvidenceTarget": "",
                    "transportLawFittingAllowed": False,
                }
            )
    return rows


def systematics_closure_report(capsule: dict, priority_rows: list[dict], source_rows: list[dict], rule_rows: list[dict], named_rows: list[dict]) -> str:
    metrics = capsule["metrics"]
    group_counts: dict[str, int] = {}
    for row in priority_rows:
        group_counts[row["closureGroup"]] = group_counts.get(row["closureGroup"], 0) + 1
    lines = [
        "# MTS Remaining Systematics Closure Pack",
        "",
        "This diagnostic turns the weak official-crosswalk cases into a focused evidence plan. Canonical MTS remains locked.",
        "",
        "## Headline",
        "",
        f"Verdict: **{capsule['verdict']}**.",
        f"Weak official-crosswalk cases targeted: {metrics['weakCaseCount']}.",
        f"Named weak cases: {metrics['namedWeakCaseCount']}.",
        f"Source cache scaffold: `{capsule['sourceCache']}`.",
        "",
        "## Closure Groups",
        "",
        "| Group | Count |",
        "| --- | ---: |",
    ]
    for group, count in sorted(group_counts.items(), key=lambda item: (-item[1], item[0])):
        lines.append(f"| {group} | {count} |")
    lines.extend(
        [
            "",
            "## Priority Ledger",
            "",
            "| Rank | Galaxy | Group | Bucket | Missing evidence | SPARC refs | Verdict |",
            "| ---: | --- | --- | --- | --- | --- | --- |",
        ]
    )
    for row in priority_rows:
        lines.append(
            f"| {row['rank']} | {row['name']} | {row['closureGroup']} | {row['evidenceBucket']} | "
            f"{row['missingEvidence']} | {row['rotationCurveRefCodes']} | {row['claimSafeVerdict']} |"
        )
    lines.extend(
        [
            "",
            "## Named Case Ledger",
            "",
            "| Galaxy | Included | Group | Missing evidence | Next target |",
            "| --- | --- | --- | --- | --- |",
        ]
    )
    for row in named_rows:
        lines.append(
            f"| {row['name']} | {row['includedInWeakSet']} | {row['closureGroup']} | "
            f"{row['missingEvidence'] or '--'} | {row['nextEvidenceTarget'] or '--'} |"
        )
    lines.extend(
        [
            "",
            "## Evidence Rules",
            "",
            "| Group | Missing fields | Supports diagnosis | Contradicts diagnosis |",
            "| --- | --- | --- | --- |",
        ]
    )
    for row in rule_rows:
        lines.append(
            f"| {row['closureGroup']} | {row['missingFields']} | {row['supportingEvidence']} | {row['contradictingEvidence']} |"
        )
    lines.extend(
        [
            "",
            "## Source Targets",
            "",
            "| Galaxy | Source category | SPARC refs | Cache path |",
            "| --- | --- | --- | --- |",
        ]
    )
    for row in source_rows:
        lines.append(f"| {row['name']} | {row['sourceCategory']} | {row['spArcReferenceCodes']} | `{row['sourceCachePath']}` |")
    lines.extend(
        [
            "",
            "## Discipline",
            "",
            "- Missing metadata is not treated as transport-law evidence.",
            "- Cases remain excluded from transport-law fitting until their systematics evidence is closed or contradicted.",
            "- Large downloads are not fetched in v1.",
            "- Canonical MTS remains locked.",
            "",
        ]
    )
    return "\n".join(lines)


def write_systematics_closure_pack_artifacts(out_dir: Path, source_cache: Path) -> dict:
    official_crosswalk_path = DEFAULT_OFFICIAL_SOURCE_FETCH_OUT / "mts-official-source-crosswalk.csv"
    official_table_path = DEFAULT_OFFICIAL_SOURCE_FETCH_OUT / "mts-official-sparc-table1-provenance.csv"
    crosswalk_rows = read_csv_rows(official_crosswalk_path)
    table_rows = read_csv_rows(official_table_path)
    priority_rows = systematics_priority_rows(crosswalk_rows, table_rows)
    source_rows = systematics_source_target_rows(priority_rows, source_cache)
    rule_rows = systematics_evidence_rule_rows(priority_rows)
    named_rows = systematics_named_case_rows(priority_rows)
    source_cache.mkdir(parents=True, exist_ok=True)
    group_counts: dict[str, int] = {}
    for row in priority_rows:
        group_counts[row["closureGroup"]] = group_counts.get(row["closureGroup"], 0) + 1
    capsule = {
        "type": "mts-remaining-systematics-closure-pack",
        "version": 1,
        "generatedAt": dt.datetime.now(dt.UTC).isoformat(),
        "sourceScript": "scripts/mts-failure-lab.py",
        "canonicalMtsStatus": "locked",
        "sourceCache": str(source_cache),
        "verdict": "external evidence still required; do not use weak cases for transport-law fitting yet",
        "inputs": {
            "officialCrosswalk": str(official_crosswalk_path),
            "officialTable1Provenance": str(official_table_path),
        },
        "metrics": {
            "weakCaseCount": len(priority_rows),
            "namedWeakCaseCount": sum(1 for row in priority_rows if row["namedCase"]),
            "groupCounts": group_counts,
            "sourceTargetCount": len(source_rows),
            "evidenceRuleCount": len(rule_rows),
            "sourceCacheOnDDrive": str(source_cache).lower().startswith("d:"),
        },
        "rules": {
            "claimStatus": "diagnostic only",
            "transportLawChangeAllowed": False,
            "largeDownloadsExcluded": True,
            "missingMetadataIsMtsEvidence": False,
        },
    }
    out_dir.mkdir(parents=True, exist_ok=True)
    write_csv(out_dir / "mts-systematics-closure-priority.csv", priority_rows)
    write_csv(out_dir / "mts-systematics-source-targets.csv", source_rows)
    write_csv(out_dir / "mts-systematics-evidence-rules.csv", rule_rows)
    write_csv(out_dir / "mts-systematics-named-case-ledger.csv", named_rows)
    (out_dir / "mts-systematics-closure-report.md").write_text(
        systematics_closure_report(capsule, priority_rows, source_rows, rule_rows, named_rows),
        encoding="utf-8",
    )
    (out_dir / "mts-systematics-closure-capsule.json").write_text(json.dumps(json_clean(capsule), indent=2), encoding="utf-8")
    return capsule


REFERENCE_FETCH_MAX_BYTES = 512_000


def safe_file_stem(text: str) -> str:
    stem = re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")
    return stem or "unknown"


def split_list_field(value: str) -> list[str]:
    return [item.strip() for item in str(value or "").split(";") if item.strip()]


def parse_reference_texts(row: dict) -> dict[str, str]:
    references: dict[str, str] = {}
    text = row.get("spArcReferences") or row.get("spArcReferenceReferences") or ""
    for item in split_list_field(text):
        if "=" not in item:
            continue
        code, reference = item.split("=", 1)
        references[code.strip()] = reference.strip()
    for code in [item.strip() for item in str(row.get("spArcReferenceCodes", "") or "").split(",") if item.strip()]:
        references.setdefault(code, "")
    return references


def reference_crossref_query_url(reference_text: str) -> str:
    query = urllib.parse.urlencode(
        {
            "query.bibliographic": reference_text,
            "rows": "1",
            "select": "DOI,title,container-title,published-print,published-online,URL,score",
        }
    )
    return f"https://api.crossref.org/works?{query}"


def reference_ads_search_url(reference_text: str) -> str:
    return "https://ui.adsabs.harvard.edu/search/q=" + urllib.parse.quote(f'"{reference_text}"')


def reference_arxiv_search_url(reference_text: str) -> str:
    query = urllib.parse.urlencode(
        {
            "query": reference_text,
            "searchtype": "all",
            "abstracts": "show",
            "order": "-announced_date_first",
            "size": "25",
        }
    )
    return f"https://arxiv.org/search/?{query}"


def reference_cache_path(source_cache: Path, code: str) -> Path:
    return source_cache / "reference-evidence-v1" / "crossref" / f"{safe_file_stem(code)}.json"


def download_small_metadata(url: str, path: Path, offline: bool) -> dict:
    row = {
        "cachePath": str(path),
        "offline": offline,
        "downloaded": False,
        "fetchStatus": "",
    }
    if offline:
        row["fetchStatus"] = "cached" if path.exists() else "missing-offline"
        return row
    if path.exists():
        row["fetchStatus"] = "cached"
        return row
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        request = urllib.request.Request(url, headers={"User-Agent": "MTS-Galaxy-Lab/1.0"})
        with urllib.request.urlopen(request, timeout=30) as response:
            data = response.read(REFERENCE_FETCH_MAX_BYTES + 1)
        if len(data) > REFERENCE_FETCH_MAX_BYTES:
            row["fetchStatus"] = f"skipped-too-large:{len(data)}"
            return row
        path.write_bytes(data)
        row["downloaded"] = True
        row["fetchStatus"] = "downloaded"
    except (OSError, urllib.error.URLError, TimeoutError) as exc:
        row["fetchStatus"] = f"download-error:{exc}"
    return row


def parse_crossref_cache(path: Path) -> dict:
    if not path.exists():
        return {}
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError, UnicodeDecodeError):
        return {}
    items = payload.get("message", {}).get("items", [])
    if not items:
        return {}
    item = items[0]
    title = item.get("title") or []
    container = item.get("container-title") or []
    published = item.get("published-print") or item.get("published-online") or {}
    date_parts = published.get("date-parts") or []
    year = date_parts[0][0] if date_parts and date_parts[0] else ""
    return {
        "doi": item.get("DOI", ""),
        "metadataTitle": title[0] if title else "",
        "containerTitle": container[0] if container else "",
        "publicationYear": year,
        "metadataUrl": item.get("URL", ""),
        "crossrefScore": item.get("score", ""),
    }


def reference_years(reference_text: str) -> set[int]:
    return {int(match) for match in re.findall(r"\b(19[0-9]{2}|20[0-9]{2})\b", reference_text or "")}


def crossref_match_status(reference_text: str, metadata: dict) -> str:
    if not metadata:
        return "missing"
    years = reference_years(reference_text)
    try:
        metadata_year = int(metadata.get("publicationYear") or 0)
    except (TypeError, ValueError):
        metadata_year = 0
    if years and metadata_year in years:
        return "accepted-year-match"
    if years and metadata_year and metadata_year not in years:
        return "suspect-year-mismatch"
    return "unverified"


def unique_reference_records(source_rows: list[dict]) -> list[dict]:
    records: dict[str, dict] = {}
    for row in source_rows:
        for code, reference in parse_reference_texts(row).items():
            if code not in records:
                records[code] = {
                    "referenceCode": code,
                    "referenceText": reference,
                    "caseCount": 0,
                    "galaxies": set(),
                    "closureGroups": set(),
                }
            records[code]["caseCount"] += 1
            records[code]["galaxies"].add(row["name"])
            records[code]["closureGroups"].add(row["closureGroup"])
            if reference and not records[code]["referenceText"]:
                records[code]["referenceText"] = reference
    output = []
    for code, record in records.items():
        reference = record["referenceText"] or code
        output.append(
            {
                "referenceCode": code,
                "referenceText": reference,
                "caseCount": record["caseCount"],
                "galaxies": "; ".join(sorted(record["galaxies"])),
                "closureGroups": "; ".join(sorted(record["closureGroups"])),
                "crossrefQueryUrl": reference_crossref_query_url(reference),
                "adsSearchUrl": reference_ads_search_url(reference),
                "arxivSearchUrl": reference_arxiv_search_url(reference),
            }
        )
    output.sort(key=lambda item: item["referenceCode"])
    return output


def reference_fetch_inventory_rows(reference_rows: list[dict], source_cache: Path, offline: bool) -> tuple[list[dict], int]:
    rows = []
    downloaded_count = 0
    for ref in reference_rows:
        path = reference_cache_path(source_cache, ref["referenceCode"])
        fetch = download_small_metadata(ref["crossrefQueryUrl"], path, offline)
        downloaded_count += 1 if fetch["downloaded"] else 0
        exists = path.exists()
        metadata = parse_crossref_cache(path)
        match_status = crossref_match_status(ref["referenceText"], metadata)
        accepted = match_status in {"accepted-year-match", "unverified"} and bool(metadata.get("metadataTitle") or metadata.get("doi"))
        rows.append(
            {
                "referenceCode": ref["referenceCode"],
                "referenceText": ref["referenceText"],
                "metadataKind": "crossref-json",
                "cachePath": str(path),
                "existsInCache": exists,
                "cacheStatus": "available" if exists else "missing",
                "sizeBytes": path.stat().st_size if exists else "",
                "sha256": file_sha256(path) if exists else "",
                "metadataMatchStatus": match_status,
                "acceptedMetadata": accepted,
                "doi": metadata.get("doi", "") if accepted else "",
                "metadataTitle": metadata.get("metadataTitle", "") if accepted else "",
                "containerTitle": metadata.get("containerTitle", "") if accepted else "",
                "publicationYear": metadata.get("publicationYear", "") if accepted else "",
                "metadataUrl": metadata.get("metadataUrl", "") if accepted else "",
                "candidateDoi": metadata.get("doi", ""),
                "candidateTitle": metadata.get("metadataTitle", ""),
                "candidatePublicationYear": metadata.get("publicationYear", ""),
                "crossrefScore": metadata.get("crossrefScore", ""),
                "largeDownloadAllowed": False,
            }
        )
    return rows, downloaded_count


def reference_source_index_rows(reference_rows: list[dict], fetch_rows: list[dict]) -> list[dict]:
    fetch_by_code = {row["referenceCode"]: row for row in fetch_rows}
    rows = []
    for ref in reference_rows:
        fetch = fetch_by_code.get(ref["referenceCode"], {})
        rows.append(
            {
                "referenceCode": ref["referenceCode"],
                "referenceText": ref["referenceText"],
                "caseCount": ref["caseCount"],
                "galaxies": ref["galaxies"],
                "closureGroups": ref["closureGroups"],
                "adsSearchUrl": ref["adsSearchUrl"],
                "arxivSearchUrl": ref["arxivSearchUrl"],
                "crossrefQueryUrl": ref["crossrefQueryUrl"],
                "crossrefCachePath": fetch.get("cachePath", ""),
                "crossrefCached": fetch.get("existsInCache", False),
                "metadataMatchStatus": fetch.get("metadataMatchStatus", ""),
                "doi": fetch.get("doi", ""),
                "metadataTitle": fetch.get("metadataTitle", ""),
                "containerTitle": fetch.get("containerTitle", ""),
                "publicationYear": fetch.get("publicationYear", ""),
                "metadataUrl": fetch.get("metadataUrl", ""),
                "candidateDoi": fetch.get("candidateDoi", ""),
                "candidateTitle": fetch.get("candidateTitle", ""),
                "candidatePublicationYear": fetch.get("candidatePublicationYear", ""),
            }
        )
    return rows


def evidence_template_rows(source_rows: list[dict], source_index_rows: list[dict]) -> list[dict]:
    source_by_code = {row["referenceCode"]: row for row in source_index_rows}
    rows = []
    for source in source_rows:
        references = parse_reference_texts(source)
        missing_fields = split_list_field(source.get("fieldsToFind", ""))
        for field in missing_fields:
            for code, reference in references.items():
                index = source_by_code.get(code, {})
                rows.append(
                    {
                        "name": source["name"],
                        "closureGroup": source["closureGroup"],
                        "evidenceBucket": source["evidenceBucket"],
                        "missingField": field,
                        "sourceReferenceCode": code,
                        "sourceReferenceText": reference,
                        "sourceMetadataTitle": index.get("metadataTitle", ""),
                        "doi": index.get("doi", ""),
                        "metadataMatchStatus": index.get("metadataMatchStatus", ""),
                        "adsSearchUrl": index.get("adsSearchUrl", ""),
                        "provenanceUrlOrPath": index.get("metadataUrl") or index.get("adsSearchUrl") or index.get("crossrefCachePath", ""),
                        "supportingEvidenceText": "",
                        "contradictingEvidenceText": "",
                        "confidence": "",
                        "verdict": "still missing",
                        "transportLawFittingAllowed": False,
                        "largeDownloadAllowed": False,
                    }
                )
    rows.sort(key=lambda item: (item["name"], item["missingField"], item["sourceReferenceCode"]))
    return rows


def reference_case_map_rows(source_rows: list[dict], source_index_rows: list[dict]) -> list[dict]:
    source_by_code = {row["referenceCode"]: row for row in source_index_rows}
    rows = []
    for source in source_rows:
        references = parse_reference_texts(source)
        cached = [code for code in references if source_by_code.get(code, {}).get("crossrefCached")]
        accepted = [code for code in references if source_by_code.get(code, {}).get("doi") or source_by_code.get(code, {}).get("metadataTitle")]
        rows.append(
            {
                "name": source["name"],
                "closureGroup": source["closureGroup"],
                "evidenceBucket": source["evidenceBucket"],
                "fieldsToFind": source["fieldsToFind"],
                "referenceCodes": ", ".join(references),
                "resolvedReferenceCount": len(references),
                "cachedMetadataCount": len(cached),
                "cachedReferenceCodes": ", ".join(cached),
                "acceptedMetadataCount": len(accepted),
                "acceptedReferenceCodes": ", ".join(accepted),
                "sourceCachePath": source["sourceCachePath"],
                "claimStatus": "do not use for transport-law fitting yet",
                "transportLawFittingAllowed": False,
            }
        )
    rows.sort(key=lambda item: (item["closureGroup"], item["name"]))
    return rows


def reference_evidence_report(capsule: dict, source_index_rows: list[dict], fetch_rows: list[dict], template_rows: list[dict], case_rows: list[dict]) -> str:
    metrics = capsule["metrics"]
    lines = [
        "# MTS SPARC Reference Evidence Resolver",
        "",
        "This diagnostic resolves source references for the remaining weak systematics cases. Canonical MTS remains locked.",
        "",
        "## Headline",
        "",
        f"Verdict: **{capsule['verdict']}**.",
        f"Weak cases targeted: {metrics['weakCaseCount']}.",
        f"Unique reference codes: {metrics['referenceCount']}.",
        f"Cached small metadata files: {metrics['cachedMetadataCount']}.",
        f"Accepted metadata matches: {metrics['acceptedMetadataCount']}.",
        f"Suspect metadata matches: {metrics['suspectMetadataCount']}.",
        f"Evidence template rows: {metrics['evidenceTemplateRowCount']}.",
        f"Source cache: `{capsule['sourceCache']}`.",
        "",
        "## Reference Index",
        "",
        "| Code | Cases | Match | DOI | Title |",
        "| --- | ---: | --- | --- | --- |",
    ]
    fetch_by_code = {row["referenceCode"]: row for row in fetch_rows}
    for row in source_index_rows:
        fetch = fetch_by_code.get(row["referenceCode"], {})
        lines.append(
            f"| {row['referenceCode']} | {row['caseCount']} | {row['metadataMatchStatus']} | "
            f"{row['doi'] or '--'} | {row['metadataTitle'] or row['referenceText']} |"
        )
    lines.extend(
        [
            "",
            "## Case Map",
            "",
            "| Galaxy | Group | Fields | Refs | Cached refs |",
            "| --- | --- | --- | --- | --- |",
        ]
    )
    for row in case_rows:
        lines.append(
            f"| {row['name']} | {row['closureGroup']} | {row['fieldsToFind']} | "
            f"{row['referenceCodes']} | {row['acceptedReferenceCodes'] or row['cachedReferenceCodes'] or '--'} |"
        )
    lines.extend(
        [
            "",
            "## Evidence Entry Template",
            "",
            "Fill `mts-systematics-evidence-entry-template.csv` after reading the source metadata/papers. Leave verdict as `still missing` until direct evidence is found.",
            "",
            "| Galaxy | Field | Ref | Starting verdict |",
            "| --- | --- | --- | --- |",
        ]
    )
    for row in template_rows[:24]:
        lines.append(f"| {row['name']} | {row['missingField']} | {row['sourceReferenceCode']} | {row['verdict']} |")
    lines.extend(
        [
            "",
            "## Discipline",
            "",
            "- Crossref JSON and stable search URLs are source-resolution aids, not physical evidence by themselves.",
            "- Suspect Crossref matches are retained as cached candidates but are not treated as accepted provenance.",
            "- No large PDFs, FITS cubes, archives, or bulk paper downloads are fetched.",
            "- Missing evidence remains non-MTS evidence until a filled evidence template says otherwise.",
            "- Canonical MTS remains locked.",
            "",
        ]
    )
    return "\n".join(lines)


def write_reference_evidence_artifacts(out_dir: Path, source_cache: Path, offline: bool) -> dict:
    source_targets_path = DEFAULT_SYSTEMATICS_CLOSURE_PACK_OUT / "mts-systematics-source-targets.csv"
    source_rows = read_csv_rows(source_targets_path)
    reference_rows = unique_reference_records(source_rows)
    fetch_rows, downloaded_count = reference_fetch_inventory_rows(reference_rows, source_cache, offline)
    source_index = reference_source_index_rows(reference_rows, fetch_rows)
    template_rows = evidence_template_rows(source_rows, source_index)
    case_rows = reference_case_map_rows(source_rows, source_index)
    cached_count = sum(1 for row in fetch_rows if row["existsInCache"])
    accepted_count = sum(1 for row in fetch_rows if row["acceptedMetadata"])
    suspect_count = sum(1 for row in fetch_rows if str(row["metadataMatchStatus"]).startswith("suspect"))
    cache_on_d = str(source_cache).lower().startswith("d:")
    capsule = {
        "type": "mts-sparc-reference-evidence-resolver",
        "version": 1,
        "generatedAt": dt.datetime.now(dt.UTC).isoformat(),
        "sourceScript": "scripts/mts-failure-lab.py",
        "canonicalMtsStatus": "locked",
        "sourceCache": str(source_cache),
        "offline": offline,
        "verdict": "reference evidence template ready; weak cases remain excluded from transport-law fitting",
        "inputs": {"systematicsSourceTargets": str(source_targets_path)},
        "metrics": {
            "weakCaseCount": len({row["name"] for row in source_rows}),
            "sourceTargetCount": len(source_rows),
            "referenceCount": len(reference_rows),
            "cachedMetadataCount": cached_count,
            "acceptedMetadataCount": accepted_count,
            "suspectMetadataCount": suspect_count,
            "downloadedMetadataCount": downloaded_count,
            "evidenceTemplateRowCount": len(template_rows),
            "sourceCacheOnDDrive": cache_on_d,
            "largeDownloadCount": 0,
        },
        "rules": {
            "claimStatus": "diagnostic only",
            "transportLawChangeAllowed": False,
            "largeDownloadsExcluded": True,
            "metadataPagesAreEvidenceOnlyAfterReview": True,
        },
    }
    out_dir.mkdir(parents=True, exist_ok=True)
    write_csv(out_dir / "mts-reference-source-index.csv", source_index)
    write_csv(out_dir / "mts-reference-fetch-inventory.csv", fetch_rows)
    write_csv(out_dir / "mts-systematics-evidence-entry-template.csv", template_rows)
    write_csv(out_dir / "mts-reference-evidence-case-map.csv", case_rows)
    (out_dir / "mts-reference-evidence-report.md").write_text(
        reference_evidence_report(capsule, source_index, fetch_rows, template_rows, case_rows),
        encoding="utf-8",
    )
    (out_dir / "mts-reference-evidence-capsule.json").write_text(json.dumps(json_clean(capsule), indent=2), encoding="utf-8")
    return capsule


CLEAN_RADIUS_NAMED_CASES = [
    "ESO563-G021",
    "IC4202",
    "NGC4217",
    "UGC06973",
    "UGC02953",
    "NGC2903",
    "UGC02916",
    "NGC2998",
    "UGC12506",
    "NGC7331",
    "ESO079-G014",
]


def clean_radius_support2(curve: dict, point: dict) -> float:
    return GAMMA0 * curve["leff"] * (1 - math.exp(-((point["r"] / curve["leff"]) ** Q_DEFAULT)))


def clean_radius_point_trace(curve: dict) -> list[dict]:
    trace = []
    for index, point in enumerate(curve["points"]):
        baryon_v = math.sqrt(max(0.0, point["bar2"]))
        support2 = clean_radius_support2(curve, point)
        mts_v = math.sqrt(max(0.0, point["bar2"] + support2))
        shares = component_shares_for_point(point, curve.get("mlDisk", ML_DISK), curve.get("mlBulge", ML_BULGE))
        bulge_share = shares.get("bulge", math.nan)
        disk_share = shares.get("disk", math.nan)
        gas_share = shares.get("gas", math.nan)
        band = "inner" if point["x"] < 0.33 else ("mid" if point["x"] < 0.66 else "outer")
        trace.append(
            {
                "index": index,
                "r": point["r"],
                "x": point["x"],
                "band": band,
                "vObs": point["vObs"],
                "errV": point.get("err", math.nan),
                "vGas": point["vGas"],
                "vDisk": point["vDisk"],
                "vBulge": point["vBulge"],
                "baryonV": baryon_v,
                "mtsV": mts_v,
                "baryonResidual": baryon_v - point["vObs"],
                "mtsResidual": mts_v - point["vObs"],
                "gasShare": gas_share,
                "diskShare": disk_share,
                "bulgeShare": bulge_share,
                "bulgeDominated": bool(math.isfinite(bulge_share) and bulge_share >= 0.50),
                "diskDominated": bool(math.isfinite(disk_share) and disk_share >= 0.50),
                "gasDominated": bool(math.isfinite(gas_share) and gas_share >= 0.50),
            }
        )
    return trace


def clean_radius_metric(point_rows: list[dict], predicate: Callable[[dict], bool]) -> dict:
    selected = [row for row in point_rows if predicate(row)]
    mts_rmse = rmse_from_residuals(row["mtsResidual"] for row in selected)
    baryon_rmse = rmse_from_residuals(row["baryonResidual"] for row in selected)
    mts_bias = safe_mean(row["mtsResidual"] for row in selected)
    baryon_bias = safe_mean(row["baryonResidual"] for row in selected)
    worst = max(selected, key=lambda row: abs(row["mtsResidual"]), default=None)
    return {
        "n": len(selected),
        "mtsRmse": mts_rmse,
        "baryonRmse": baryon_rmse,
        "mtsBias": mts_bias,
        "baryonBias": baryon_bias,
        "mtsGainVsBaryon": baryon_rmse - mts_rmse if math.isfinite(baryon_rmse) and math.isfinite(mts_rmse) else math.nan,
        "worstResidual": worst["mtsResidual"] if worst else math.nan,
        "worstR": worst["r"] if worst else math.nan,
        "worstX": worst["x"] if worst else math.nan,
        "worstBand": worst["band"] if worst else "",
    }


def clean_radius_view_specs() -> list[tuple[str, str, Callable[[dict], bool]]]:
    return [
        ("full", "full curve", lambda _row: True),
        ("dropInner1", "exclude inner 1 point", lambda row: row["index"] >= 1),
        ("dropInner2", "exclude inner 2 points", lambda row: row["index"] >= 2),
        ("outer10", "x >= 0.10", lambda row: row["x"] >= 0.10),
        ("outer20", "x >= 0.20", lambda row: row["x"] >= 0.20),
        ("outer33", "x >= 0.33", lambda row: row["x"] >= 0.33),
        ("noBulgeDominated", "exclude bulge-dominated points", lambda row: not row["bulgeDominated"]),
        (
            "cleanOuter10NoBulge",
            "x >= 0.10 and no bulge-dominated points",
            lambda row: row["x"] >= 0.10 and not row["bulgeDominated"],
        ),
        (
            "cleanOuter20NoBulge",
            "x >= 0.20 and no bulge-dominated points",
            lambda row: row["x"] >= 0.20 and not row["bulgeDominated"],
        ),
    ]


def clean_radius_class(row: dict) -> str:
    if row["fullMtsRmse"] < 20.0:
        return "baseline acceptable"
    if row["bestRobustPointCount"] < 3 or not math.isfinite(row["bestRobustMtsRmse"]):
        return "too few clean points"
    if row["bestRobustMtsRmse"] < 20.0:
        return "central/local dominated"
    if row["bestRobustGain"] >= 5.0:
        return "central/local softened"
    return "still fails globally"


def clean_radius_plain_read(row: dict) -> str:
    if row["robustClass"] == "baseline acceptable":
        return "Locked MTS is already below 20 km/s on the full ROTMOD curve."
    if row["robustClass"] == "central/local dominated":
        return (
            f"Full RMSE is high, but the clean view `{row['bestRobustViewLabel']}` drops to "
            f"{fmt(row['bestRobustMtsRmse'])} km/s. Treat this as central/local leverage before changing MTS."
        )
    if row["robustClass"] == "central/local softened":
        return (
            f"The clean view `{row['bestRobustViewLabel']}` improves RMSE by {fmt(row['bestRobustGain'])} km/s "
            "but does not fully clear the 20 km/s threshold."
        )
    if row["robustClass"] == "still fails globally":
        return "This remains a global-looking residual under the clean-radius stress views."
    return "Not enough clean points remain after the masks for a strong robustness read."


def clean_radius_row(curve: dict) -> tuple[dict, list[dict]]:
    point_rows = clean_radius_point_trace(curve)
    metrics = {}
    labels = {}
    for prefix, label, predicate in clean_radius_view_specs():
        metric = clean_radius_metric(point_rows, predicate)
        metrics[prefix] = metric
        labels[prefix] = label

    full = metrics["full"]
    robust_candidates = [
        (prefix, metric)
        for prefix, metric in metrics.items()
        if prefix != "full" and metric["n"] >= 3 and math.isfinite(metric["mtsRmse"])
    ]
    best_prefix, best_metric = min(robust_candidates, key=lambda item: item[1]["mtsRmse"], default=("", {"mtsRmse": math.nan, "n": 0}))
    worst = max(point_rows, key=lambda item: abs(item["mtsResidual"]), default={})
    row = {
        "name": curve["name"],
        "route": curve["route"],
        "lockedRoute": curve["lockedModelRoute"],
        "routeTransition": "" if curve["route"] == curve["lockedModelRoute"] else f"{curve['lockedModelRoute']} -> {curve['route']}",
        "pointCount": len(point_rows),
        "inner10PointCount": sum(1 for item in point_rows if item["x"] < 0.10),
        "inner20PointCount": sum(1 for item in point_rows if item["x"] < 0.20),
        "inner33PointCount": sum(1 for item in point_rows if item["x"] < 0.33),
        "bulgeDominatedPointCount": sum(1 for item in point_rows if item["bulgeDominated"]),
        "fullMtsRmse": full["mtsRmse"],
        "fullBaryonRmse": full["baryonRmse"],
        "fullMtsGainVsBaryon": full["mtsGainVsBaryon"],
        "bestRobustView": best_prefix,
        "bestRobustViewLabel": labels.get(best_prefix, ""),
        "bestRobustPointCount": best_metric["n"],
        "bestRobustMtsRmse": best_metric["mtsRmse"],
        "bestRobustBaryonRmse": best_metric.get("baryonRmse", math.nan),
        "bestRobustMtsGainVsBaryon": best_metric.get("mtsGainVsBaryon", math.nan),
        "bestRobustGain": full["mtsRmse"] - best_metric["mtsRmse"] if math.isfinite(full["mtsRmse"]) and math.isfinite(best_metric["mtsRmse"]) else math.nan,
        "worstPointRadius": worst.get("r", math.nan),
        "worstPointX": worst.get("x", math.nan),
        "worstPointBand": worst.get("band", ""),
        "worstPointResidual": worst.get("mtsResidual", math.nan),
        "worstPointBulgeShare": worst.get("bulgeShare", math.nan),
        "worstPointDiskShare": worst.get("diskShare", math.nan),
        "worstPointGasShare": worst.get("gasShare", math.nan),
        "caseNote": "",
    }
    for prefix, metric in metrics.items():
        row[f"{prefix}PointCount"] = metric["n"]
        row[f"{prefix}MtsRmse"] = metric["mtsRmse"]
        row[f"{prefix}BaryonRmse"] = metric["baryonRmse"]
        row[f"{prefix}MtsBias"] = metric["mtsBias"]
        row[f"{prefix}BaryonBias"] = metric["baryonBias"]
        row[f"{prefix}MtsGainVsBaryon"] = metric["mtsGainVsBaryon"]
    row["robustClass"] = clean_radius_class(row)
    row["plainRead"] = clean_radius_plain_read(row)
    return row, point_rows


def clean_radius_summary_rows(rows: list[dict]) -> list[dict]:
    summary = []
    for robust_class in sorted({row["robustClass"] for row in rows}):
        group = [row for row in rows if row["robustClass"] == robust_class]
        summary.append(
            {
                "robustClass": robust_class,
                "count": len(group),
                "highFullRmseCount": sum(1 for row in group if row["fullMtsRmse"] >= 20.0),
                "meanFullMtsRmse": safe_mean(row["fullMtsRmse"] for row in group),
                "meanBestRobustMtsRmse": safe_mean(row["bestRobustMtsRmse"] for row in group),
                "meanBestRobustGain": safe_mean(row["bestRobustGain"] for row in group),
                "meanFullMtsGainVsBaryon": safe_mean(row["fullMtsGainVsBaryon"] for row in group),
                "meanBestRobustMtsGainVsBaryon": safe_mean(row["bestRobustMtsGainVsBaryon"] for row in group),
            }
        )
    return summary


def clean_radius_markdown_table(rows: list[dict], columns: list[tuple[str, str]], limit: int | None = None) -> list[str]:
    selected = rows[:limit] if limit else rows
    lines = [
        "| " + " | ".join(label for label, _key in columns) + " |",
        "| " + " | ".join("---" for _label, _key in columns) + " |",
    ]
    for row in selected:
        cells = []
        for _label, key in columns:
            value = row.get(key, "")
            if isinstance(value, (int, float)):
                cells.append(fmt(value))
            else:
                cells.append(str(value or "--").replace("|", "/"))
        lines.append("| " + " | ".join(cells) + " |")
    return lines


def clean_radius_case_note(row: dict, point_rows: list[dict]) -> str:
    worst_rows = sorted(point_rows, key=lambda item: abs(item["mtsResidual"]), reverse=True)[:10]
    columns = [
        ("i", "index"),
        ("x", "x"),
        ("r", "r"),
        ("band", "band"),
        ("Vobs", "vObs"),
        ("MTS", "mtsV"),
        ("MTS resid", "mtsResidual"),
        ("baryon", "baryonV"),
        ("baryon resid", "baryonResidual"),
        ("bulge share", "bulgeShare"),
    ]
    lines = [
        f"# {row['name']} Clean-Radius Case Note",
        "",
        "Canonical MTS is locked. This note is a robustness read only.",
        "",
        f"- Route: `{row['route']}`",
        f"- Locked MTS route: `{row['lockedRoute']}`",
        f"- Verdict: `{row['robustClass']}`",
        f"- Plain read: {row['plainRead']}",
        f"- Full MTS RMSE: `{fmt(row['fullMtsRmse'])}` km/s",
        f"- Best clean view: `{row['bestRobustViewLabel']}` at `{fmt(row['bestRobustMtsRmse'])}` km/s",
        f"- Full MTS gain over baryons-only: `{fmt(row['fullMtsGainVsBaryon'])}` km/s",
        f"- Clean-view MTS gain over baryons-only: `{fmt(row['bestRobustMtsGainVsBaryon'])}` km/s",
        "",
        "## Stress Views",
        "",
        "| View | Points | MTS RMSE | Baryon RMSE | MTS gain vs baryon |",
        "| --- | ---: | ---: | ---: | ---: |",
    ]
    for prefix, label, _predicate in clean_radius_view_specs():
        lines.append(
            f"| {label} | {row[f'{prefix}PointCount']} | {fmt(row[f'{prefix}MtsRmse'])} | "
            f"{fmt(row[f'{prefix}BaryonRmse'])} | {fmt(row[f'{prefix}MtsGainVsBaryon'])} |"
        )
    lines.extend(
        [
            "",
            "## Worst MTS Residual Points",
            "",
            *clean_radius_markdown_table(worst_rows, columns),
            "",
            "## Read Discipline",
            "",
            "- Inner masks are not data deletion; they test whether a score is dominated by central leverage.",
            "- Bulge masks are not a physical correction; they test whether central mass-model leverage is carrying the failure.",
            "- A global-looking residual here is worth renewed MTS investigation. A central/local residual is a data/model-interface problem first.",
            "",
        ]
    )
    return "\n".join(lines)


def write_clean_radius_case_notes(out_dir: Path, rows: list[dict], traces: dict[str, list[dict]]) -> None:
    case_dir = out_dir / "case-notes"
    case_dir.mkdir(parents=True, exist_ok=True)
    selected = [
        row
        for row in rows
        if row["fullMtsRmse"] >= 20.0 or row["robustClass"] in {"central/local softened", "still fails globally", "too few clean points"}
    ]
    for row in selected:
        filename = f"{safe_file_stem(row['name'])}.md"
        path = case_dir / filename
        path.write_text(clean_radius_case_note(row, traces[row["name"]]), encoding="utf-8")
        row["caseNote"] = f"case-notes/{filename}"


def clean_radius_report(capsule: dict, rows: list[dict], summary_rows: list[dict]) -> str:
    top_full = sorted(rows, key=lambda row: row["fullMtsRmse"], reverse=True)[:20]
    collapse = sorted(
        [row for row in rows if row["fullMtsRmse"] >= 20.0 and row["bestRobustMtsRmse"] < 20.0],
        key=lambda row: row["bestRobustGain"],
        reverse=True,
    )
    global_fail = sorted([row for row in rows if row["robustClass"] == "still fails globally"], key=lambda row: row["fullMtsRmse"], reverse=True)
    named = [row for name in CLEAN_RADIUS_NAMED_CASES for row in rows if row["name"] == name]
    common_cols = [
        ("Galaxy", "name"),
        ("Class", "robustClass"),
        ("Full MTS", "fullMtsRmse"),
        ("Best clean", "bestRobustMtsRmse"),
        ("Gain", "bestRobustGain"),
        ("Best view", "bestRobustViewLabel"),
        ("MTS vs baryon", "bestRobustMtsGainVsBaryon"),
    ]
    lines = [
        "# Clean-Radius Robustness Test",
        "",
        "This is a ROTMOD-only physics stress test. It does not ask for Excel work, manual evidence entry, or external provenance reading.",
        "",
        "Canonical MTS is locked. The test asks one direct question: if the inner or bulge-dominated points stop controlling the score, does the apparent failure still look global?",
        "",
        "## Headline",
        "",
        f"- Curves tested: `{capsule['metrics']['curveCount']}`",
        f"- Mean locked-MTS full RMSE: `{fmt(capsule['metrics']['meanFullMtsRmse'])}` km/s",
        f"- Full-RMSE failures above 20 km/s: `{capsule['metrics']['fullFailureCount']}`",
        f"- Failures that drop below 20 km/s in a clean view: `{capsule['metrics']['centralLocalDominatedCount']}`",
        f"- Failures still global-looking after clean views: `{capsule['metrics']['globalFailureCount']}`",
        "",
        "## Class Summary",
        "",
        "| Class | Count | High full RMSE | Full MTS | Best clean MTS | Clean gain | Clean MTS vs baryon |",
        "| --- | ---: | ---: | ---: | ---: | ---: | ---: |",
    ]
    for row in summary_rows:
        lines.append(
            f"| {row['robustClass']} | {row['count']} | {row['highFullRmseCount']} | "
            f"{fmt(row['meanFullMtsRmse'])} | {fmt(row['meanBestRobustMtsRmse'])} | "
            f"{fmt(row['meanBestRobustGain'])} | {fmt(row['meanBestRobustMtsGainVsBaryon'])} |"
        )
    lines.extend(
        [
            "",
            "## Top Full-RMSE Cases",
            "",
            *clean_radius_markdown_table(top_full, common_cols),
            "",
            "## Cases That Collapse Under Clean Radius View",
            "",
            *clean_radius_markdown_table(collapse, common_cols, limit=30),
            "",
            "## Still Global-Looking After Clean Views",
            "",
        ]
    )
    if global_fail:
        lines.extend(clean_radius_markdown_table(global_fail, common_cols, limit=30))
    else:
        lines.append("No full-RMSE failure remains in the strict `still fails globally` class under this test.")
    lines.extend(
        [
            "",
            "## Named Cases",
            "",
            *clean_radius_markdown_table(named, common_cols),
            "",
            "## What This Means",
            "",
            "- `central/local dominated` means the full-curve score is not a clean reason to change MTS transport physics yet.",
            "- `central/local softened` means the issue is partly local, but some wider residual remains worth inspecting.",
            "- `still fails globally` is the cleanest bucket for renewed MTS framework investigation.",
            "- MTS beating baryons-only in the clean view means the locked transport term is still doing useful work after the central stress test.",
            "",
            "## Outputs",
            "",
            "- `mts-clean-radius-robustness.csv`: all per-galaxy scores.",
            "- `mts-clean-radius-summary.csv`: class summary.",
            "- `case-notes/`: Markdown case notes for high/full or unresolved cases.",
            "- `mts-clean-radius-capsule.json`: reproducibility capsule.",
            "",
        ]
    )
    return "\n".join(lines)


def write_clean_radius_robustness_artifacts(out_dir: Path, curves: list[dict]) -> dict:
    rows = []
    traces = {}
    for curve in sorted(curves, key=lambda item: item["name"]):
        row, point_rows = clean_radius_row(curve)
        rows.append(row)
        traces[curve["name"]] = point_rows
    summary_rows = clean_radius_summary_rows(rows)
    out_dir.mkdir(parents=True, exist_ok=True)
    write_clean_radius_case_notes(out_dir, rows, traces)
    capsule = {
        "type": "mts-clean-radius-robustness",
        "version": 1,
        "generatedAt": dt.datetime.now(dt.UTC).isoformat(),
        "sourceScript": "scripts/mts-failure-lab.py",
        "canonicalMtsStatus": "locked",
        "claimStatus": "diagnostic only",
        "inputs": {"samplePack": str(SAMPLES_JS)},
        "metrics": {
            "curveCount": len(rows),
            "meanFullMtsRmse": safe_mean(row["fullMtsRmse"] for row in rows),
            "meanBestRobustMtsRmse": safe_mean(row["bestRobustMtsRmse"] for row in rows),
            "fullFailureCount": sum(1 for row in rows if row["fullMtsRmse"] >= 20.0),
            "centralLocalDominatedCount": sum(1 for row in rows if row["robustClass"] == "central/local dominated"),
            "centralLocalSoftenedCount": sum(1 for row in rows if row["robustClass"] == "central/local softened"),
            "globalFailureCount": sum(1 for row in rows if row["robustClass"] == "still fails globally"),
            "caseNoteCount": sum(1 for row in rows if row["caseNote"]),
        },
        "rules": {
            "masksAreDiagnosticsOnly": True,
            "canonicalMtsChanged": False,
            "repairThresholdKmS": 20,
            "bulgeDominatedDefinition": "bulge share >= 0.50 of baryonic velocity squared",
            "cleanViews": [label for _prefix, label, _predicate in clean_radius_view_specs()],
        },
    }
    write_csv(out_dir / "mts-clean-radius-robustness.csv", rows)
    write_csv(out_dir / "mts-clean-radius-summary.csv", summary_rows)
    (out_dir / "mts-clean-radius-report.md").write_text(clean_radius_report(capsule, rows, summary_rows), encoding="utf-8")
    (out_dir / "mts-clean-radius-capsule.json").write_text(json.dumps(json_clean(capsule), indent=2), encoding="utf-8")
    return capsule


def route_gate(route: str, target: str) -> float:
    return 1.0 if route == target else 0.0


def deficit_feature_vector(row: dict) -> list[float]:
    return [
        math.log1p(row["memoryLoad"]),
        row["u075"],
        row["uOut"],
        row["leffOverH"],
        row["fGasOut"],
        row["hOverRout"],
        route_gate(row["route"], "buffered single-crossing"),
        route_gate(row["route"], "buffered upward-crossing"),
        route_gate(row["route"], "outer-infeasible"),
        route_gate(row["route"], "CDC-low-load"),
    ]


DEFICIT_FEATURE_NAMES = [
    "log1p(memoryLoad)",
    "u075",
    "uOut",
    "L_eff/h",
    "fGasOut",
    "h/rOut",
    "routeSingle",
    "routeUpward",
    "routeOuterInfeasible",
    "routeCdc",
]


def solve_linear_system(matrix: list[list[float]], rhs: list[float]) -> list[float]:
    n = len(rhs)
    aug = [row[:] + [rhs[index]] for index, row in enumerate(matrix)]
    for col in range(n):
        pivot = max(range(col, n), key=lambda row: abs(aug[row][col]))
        if abs(aug[pivot][col]) < 1e-12:
            continue
        aug[col], aug[pivot] = aug[pivot], aug[col]
        scale = aug[col][col]
        aug[col] = [value / scale for value in aug[col]]
        for row in range(n):
            if row == col:
                continue
            factor = aug[row][col]
            if abs(factor) < 1e-12:
                continue
            aug[row] = [value - factor * aug[col][idx] for idx, value in enumerate(aug[row])]
    return [aug[row][-1] for row in range(n)]


def fit_deficit_proxy(train_rows: list[dict], ridge: float = 0.05) -> dict:
    raw = [deficit_feature_vector(row) for row in train_rows]
    columns = list(zip(*raw))
    means = [safe_mean(col) for col in columns]
    stds = []
    for col, mean in zip(columns, means):
        variance = safe_mean((value - mean) ** 2 for value in col)
        stds.append(math.sqrt(variance) if variance > 1e-12 else 1.0)

    def normalized(row: dict) -> list[float]:
        return [(value - mean) / std for value, mean, std in zip(deficit_feature_vector(row), means, stds)]

    x_rows = [[1.0] + normalized(row) for row in train_rows]
    y_values = [math.log(clamp(row["optimalAmp"], 0.02, 80.0)) for row in train_rows]
    n = len(x_rows[0])
    xtx = [[0.0 for _ in range(n)] for _ in range(n)]
    xty = [0.0 for _ in range(n)]
    for x_row, y_value in zip(x_rows, y_values):
        for i in range(n):
            xty[i] += x_row[i] * y_value
            for j in range(n):
                xtx[i][j] += x_row[i] * x_row[j]
    for index in range(1, n):
        xtx[index][index] += ridge
    coefficients = solve_linear_system(xtx, xty)
    return {
        "featureNames": DEFICIT_FEATURE_NAMES,
        "means": means,
        "stds": stds,
        "coefficients": coefficients,
        "ridge": ridge,
    }


def predict_deficit_amp(model: dict, row: dict) -> float:
    features = deficit_feature_vector(row)
    total = model["coefficients"][0]
    for value, mean, std, coefficient in zip(features, model["means"], model["stds"], model["coefficients"][1:]):
        total += ((value - mean) / std) * coefficient
    return clamp(math.exp(total), 0.02, 80.0)


def r2_score(rows: list[dict], prediction_key: str, target_key: str) -> float:
    values = [
        (row[target_key], row[prediction_key])
        for row in rows
        if math.isfinite(row[target_key]) and math.isfinite(row[prediction_key])
    ]
    if len(values) < 3:
        return math.nan
    mean_target = safe_mean(target for target, _ in values)
    ss_tot = sum((target - mean_target) ** 2 for target, _ in values)
    ss_res = sum((target - pred) ** 2 for target, pred in values)
    return 1 - ss_res / ss_tot if ss_tot > 0 else math.nan


def proxy_score_rows(curves: list[dict], deficit_rows: list[dict], split: dict, model: dict) -> list[dict]:
    by_name = {row["name"]: row for row in deficit_rows}
    rows = []
    for curve in curves:
        deficit = by_name[curve["name"]]
        amp = predict_deficit_amp(model, deficit)
        proxy = score_curve_with_amp(curve, amp)
        interval = {
            "floor": deficit["routeSafeAmpFloor"],
            "ceiling": deficit["routeSafeAmpCeiling"],
        }
        safe_amp = clamp_amp_to_interval(amp, interval)
        safe_proxy = score_curve_with_amp(curve, safe_amp)
        deficit["proxyAmp"] = amp
        deficit["safeProxyAmp"] = safe_amp
        deficit["proxyLogAmp"] = math.log(amp)
        deficit["targetLogAmp"] = math.log(clamp(deficit["optimalAmp"], 0.02, 80.0))
        rows.append(
            {
                "name": curve["name"],
                "split": split_label(curve, split),
                "route": curve["route"],
                "baselineModelRoute": deficit["baselineModelRoute"],
                "proxyRoute": proxy["candidateRoute"],
                "safeProxyRoute": safe_proxy["candidateRoute"],
                "routePreservedVsBaseline": proxy["candidateRoute"] == deficit["baselineModelRoute"],
                "safeProxyRoutePreservedVsBaseline": safe_proxy["candidateRoute"] == deficit["baselineModelRoute"],
                "baselineRmse": deficit["baselineRmse"],
                "proxyRmse": proxy["rmse"],
                "safeProxyRmse": safe_proxy["rmse"],
                "optimalRmse": deficit["optimalRmse"],
                "routeSafeRmse": deficit["routeSafeRmse"],
                "deltaProxy": proxy["rmse"] - deficit["baselineRmse"],
                "deltaSafeProxy": safe_proxy["rmse"] - deficit["baselineRmse"],
                "proxyImprovementPct": pct_improvement(deficit["baselineRmse"], proxy["rmse"]),
                "safeProxyImprovementPct": pct_improvement(deficit["baselineRmse"], safe_proxy["rmse"]),
                "optimalAmp": deficit["optimalAmp"],
                "proxyAmp": amp,
                "safeProxyAmp": safe_amp,
                "routeSafeAmpFloor": deficit["routeSafeAmpFloor"],
                "routeSafeAmpCeiling": deficit["routeSafeAmpCeiling"],
                "failureMode": deficit["failureMode"],
                "closureShapeBranch": deficit["closureShapeBranch"],
                "qShapeClass": deficit["qShapeClass"],
                "qShape": deficit["qShape"],
                "qShapeRmse": deficit["qShapeRmse"],
            }
        )
    return rows


def proxy_summary(rows: list[dict]) -> dict:
    base = safe_mean(row["baselineRmse"] for row in rows)
    proxy = safe_mean(row["proxyRmse"] for row in rows)
    safe_proxy = safe_mean(row["safeProxyRmse"] for row in rows)
    optimal = safe_mean(row["optimalRmse"] for row in rows)
    route_safe = safe_mean(row["routeSafeRmse"] for row in rows)
    hard_base = safe_mean(row["baselineRmse"] for row in rows if row["route"] in HARD_ROUTES)
    hard_proxy = safe_mean(row["proxyRmse"] for row in rows if row["route"] in HARD_ROUTES)
    hard_safe_proxy = safe_mean(row["safeProxyRmse"] for row in rows if row["route"] in HARD_ROUTES)
    return {
        "count": len(rows),
        "baselineMean": base,
        "proxyMean": proxy,
        "safeProxyMean": safe_proxy,
        "optimalMean": optimal,
        "routeSafeMean": route_safe,
        "proxyImprovementPct": pct_improvement(base, proxy),
        "safeProxyImprovementPct": pct_improvement(base, safe_proxy),
        "optimalImprovementPct": pct_improvement(base, optimal),
        "routeSafeImprovementPct": pct_improvement(base, route_safe),
        "hardBaselineMean": hard_base,
        "hardProxyMean": hard_proxy,
        "hardSafeProxyMean": hard_safe_proxy,
        "hardProxyImprovementPct": pct_improvement(hard_base, hard_proxy),
        "hardSafeProxyImprovementPct": pct_improvement(hard_base, hard_safe_proxy),
        "routePreservationRate": safe_mean(1.0 if row["routePreservedVsBaseline"] else 0.0 for row in rows),
        "safeProxyRoutePreservationRate": safe_mean(1.0 if row["safeProxyRoutePreservedVsBaseline"] else 0.0 for row in rows),
        "wins": sum(1 for row in rows if row["proxyRmse"] < row["baselineRmse"]),
        "safeProxyWins": sum(1 for row in rows if row["safeProxyRmse"] < row["baselineRmse"]),
    }


def support_deficit_report(capsule: dict, deficit_rows: list[dict], proxy_rows: list[dict]) -> str:
    route_summary = capsule["routeSummary"]
    mode_summary = capsule["failureModeSummary"]
    branch_summary = capsule["closureShapeSummary"]
    q_shape_summary = capsule["qShapeSummary"]
    two_kernel_summary = capsule["twoKernelSummary"]
    residual_mode_summary = capsule["residualModeSummary"]
    residual_probe_summary = capsule["residualProbeSummary"]
    baryon_floor_summary = capsule["baryonFloorSummary"]
    systematics_summary = capsule["systematicsSummary"]
    route_closure_summary = capsule["routeClosureSummary"]
    route_transition_summary = capsule["routeTransitionSummary"]
    case_file_summary = capsule["caseFileSummary"]
    inner_leverage_summary = capsule["innerLeverageSummary"]
    component_stress_summary = capsule["componentStressSummary"]
    inner_kinematic_summary = capsule["innerKinematicSummary"]
    final_verdict_summary = capsule["finalVerdictSummary"]
    claim_safe_summary = capsule["claimSafeSummary"]
    correlations = capsule["correlations"]
    proxy = capsule["proxy"]
    top = sorted(deficit_rows, key=lambda row: row["baselineRmse"], reverse=True)[:20]
    high = [row for row in deficit_rows if row["baselineRmse"] >= 30]
    conflicts = [row for row in deficit_rows if not row["ampRouteCompatible"]]
    high_conflicts = [row for row in high if not row["ampRouteCompatible"]]
    signature_counts: dict[str, int] = {}
    for row in high:
        signature_counts[row["residualSignature"]] = signature_counts.get(row["residualSignature"], 0) + 1
    high_branch_text = ", ".join(
        f"{row['closureShapeBranch']}={row['highRmseCount']}" for row in branch_summary if row["highRmseCount"]
    )
    transport_facing_rows = sorted(
        [row for row in deficit_rows if row["transportFacingFlag"]],
        key=lambda row: (row["baselineRmse"], row["postShapeRmse"]),
        reverse=True,
    )
    systematics_sampling_rows = sorted(
        [
            row
            for row in deficit_rows
            if row["baselineRmse"] >= 30
            and row["finalFailureClass"] in {
                "systematics-facing",
                "central-aperture/sampling dominated",
                "baryonic-floor limited",
                "error-bar dominated",
            }
        ],
        key=lambda row: (row["postShapeRmse"], row["baselineRmse"]),
        reverse=True,
    )[:20]
    named_final_rows = [row for row in deficit_rows if row["name"] in FINAL_VERDICT_WATCHLIST]
    named_final_rows.sort(key=lambda row: FINAL_VERDICT_WATCHLIST.index(row["name"]))

    lines = [
        "# MTS Support-Deficit Diagnosis",
        "",
        "This is a failure-anatomy report, not a promoted support law. It keeps canonical MTS locked, then asks how much scalar support each galaxy would need if the radial MTS shape were left unchanged.",
        "",
        "## Headline",
        "",
        f"High-RMSE systems (`RMSE >= 30 km/s`): {len(high)} / {len(deficit_rows)}.",
        f"Dominant high-RMSE residual signature: `{max(signature_counts, key=signature_counts.get) if signature_counts else '--'}`.",
        f"Route mismatch between observed state and locked MTS model state: {sum(1 for row in deficit_rows if row['routeMismatch'])} / {len(deficit_rows)}.",
        f"Required scalar support outside the locked-route-safe interval: {len(conflicts)} / {len(deficit_rows)} overall, {len(high_conflicts)} / {len(high)} for high-RMSE systems.",
        f"Primary high-RMSE branches: {high_branch_text}.",
        f"Strict final claim gate leaves {len(transport_facing_rows)} transport-facing unresolved systems.",
        "",
        "## Final Diagnostic Verdict",
        "",
        "This synthesis layer does not change MTS. It classifies each galaxy using the full diagnostic evidence stack and only labels a case transport-facing if it survives every robustness, systematics, central-component, and sampling check.",
        "",
        "| Final class | Count | High RMSE | Post-shape failures | Baseline mean | Post-shape mean | Best diagnostic | Best robust | Transport-facing |",
        "| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
    ]
    for row in final_verdict_summary:
        lines.append(
            f"| {row['finalFailureClass']} | {row['count']} | {row['highRmseCount']} | {row['postShapeFailureCount']} | "
            f"{fmt(row['baselineMean'])} | {fmt(row['postShapeMean'])} | {fmt(row['bestDiagnosticMean'])} | "
            f"{fmt(row['bestRobustMean'])} | {row['transportFacingCount']} |"
        )

    lines.extend(
        [
            "",
            "## Transport-Facing Residual Ledger",
            "",
            "| Galaxy | Route | Locked route | Baseline | Post-shape | Best diagnostic | Diagnostic source | Best robust | Robust source | Claim status |",
            "| --- | --- | --- | ---: | ---: | ---: | --- | ---: | --- | --- |",
        ]
    )
    if transport_facing_rows:
        for row in transport_facing_rows:
            lines.append(
                f"| {row['name']} | {row['route']} | {row['baselineModelRoute']} | {fmt(row['baselineRmse'])} | "
                f"{fmt(row['postShapeRmse'])} | {fmt(row['bestDiagnosticRmse'])} | {row['bestDiagnosticSource']} | "
                f"{fmt(row['bestRobustRmse'])} | {row['bestRobustSource']} | {row['claimSafeStatus']} |"
            )
    else:
        lines.append("| none | -- | -- | -- | -- | -- | -- | -- | -- | no robust transport-facing failures survive the claim gate |")

    lines.extend(
        [
            "",
            "## Systematics And Sampling Ledger",
            "",
            "| Galaxy | Final class | Post-shape | Best diagnostic | Source | Best robust | Robust source | Systematics | Inner kinematic | Component |",
            "| --- | --- | ---: | ---: | --- | ---: | --- | --- | --- | --- |",
        ]
    )
    for row in systematics_sampling_rows:
        lines.append(
            f"| {row['name']} | {row['finalFailureClass']} | {fmt(row['postShapeRmse'])} | "
            f"{fmt(row['bestDiagnosticRmse'])} | {row['bestDiagnosticSource']} | {fmt(row['bestRobustRmse'])} | "
            f"{row['bestRobustSource']} | {row['systematicsClass']} | {row['innerKinematicClass']} | "
            f"{row['innerComponentStressClass']} |"
        )
    if not systematics_sampling_rows:
        lines.append("| none | -- | -- | -- | -- | -- | -- | -- | -- | -- |")

    lines.extend(
        [
            "",
            "## Named Case Final Verdicts",
            "",
            "| Galaxy | Final class | Claim status | Baseline | Post-shape | Best robust | Robust source | Best diagnostic | Source | Notes |",
            "| --- | --- | --- | ---: | ---: | ---: | --- | ---: | --- | --- |",
        ]
    )
    for row in named_final_rows:
        notes = []
        if row["baryonicFloorFlag"]:
            notes.append("baryonic floor")
