def v20_build_rows(curves: list[dict]) -> tuple[list[dict], dict]:
    curve_by_name = {curve["name"]: curve for curve in curves}
    profile_rows = {row["name"]: row for row in read_csv_rows(V20_PROFILE_CASES_PATH)}
    mode_rows = {row["name"]: row for row in read_csv_rows(V20_RESIDUAL_MODE_CASES_PATH)}
    anatomy_rows = {row["name"]: row for row in read_csv_rows(V20_ANATOMY_PATH)}
    weak_names = v19_clean_context(curves)["weakNames"]
    rows = []
    for name, profile in sorted(profile_rows.items()):
        if name not in curve_by_name or name not in mode_rows:
            continue
        mode = mode_rows[name]
        anatomy = anatomy_rows.get(name, {})
        row = {
            "name": name,
            "curve": curve_by_name[name],
            "actualMode": mode.get("residualMode", profile.get("residualMode", "")),
            "residualSignature": mode.get("residualSignature", ""),
            "failureClass": profile.get("failureClass", anatomy.get("failureClass", "")),
            "observedRoute": profile.get("observedRoute", profile.get("route", "")),
            "lockedRoute": profile.get("lockedRoute", ""),
            "routeTransition": profile.get("routeTransition", ""),
            "weakHoldoutExcluded": name in weak_names or parse_bool(profile.get("weakHoldoutExcluded")),
            "baselineRmse": parse_float(profile.get("baselineRmse")),
            "scalarAmp": parse_float(profile.get("scalarAmp"), 1.0),
            "scalarRmse": parse_float(profile.get("scalarRmse")),
            "qShape": parse_float(profile.get("qShape"), Q_DEFAULT),
            "qShapeAmp": parse_float(profile.get("qShapeAmp"), 1.0),
            "twoKernelEta": parse_float(profile.get("twoKernelEta"), parse_float(anatomy.get("twoKernelEta"), 1.6)),
            "twoKernelQ1": parse_float(profile.get("qShape"), Q_DEFAULT),
            "twoKernelQ2": parse_float(profile.get("twoKernelQ2"), parse_float(anatomy.get("twoKernelQ2"), Q_DEFAULT)),
            "twoKernelA1": parse_float(profile.get("twoKernelA1"), parse_float(anatomy.get("twoKernelA1"), 1.0)),
            "twoKernelA2": parse_float(profile.get("twoKernelA2"), parse_float(anatomy.get("twoKernelA2"), 0.0)),
        }
        for key in sorted(set(V20_STATE_FEATURES + V20_PROFILE_FEATURES)):
            row[key] = parse_float(profile.get(key))
        rows.append(row)
    facts = {
        "primaryAnatomyCount": len(rows),
        "weakHoldoutLeakage": sum(1 for row in rows if row["weakHoldoutExcluded"]),
        "inputPaths": {
            "profileCases": str(V20_PROFILE_CASES_PATH),
            "residualModeCases": str(V20_RESIDUAL_MODE_CASES_PATH),
            "failureAnatomy": str(V20_ANATOMY_PATH),
        },
    }
    return rows, facts


def v20_split_rows(rows: list[dict], seed: int, holdout_fraction: float) -> dict:
    rng = random.Random(seed)
    by_mode: dict[str, list[dict]] = {}
    for row in rows:
        by_mode.setdefault(row["actualMode"], []).append(row)
    train = []
    holdout = []
    for mode, group in sorted(by_mode.items()):
        shuffled = group[:]
        rng.shuffle(shuffled)
        count = max(1, int(round(len(shuffled) * holdout_fraction))) if len(shuffled) > 2 else 1
        holdout.extend(shuffled[:count])
        train.extend(shuffled[count:])
    train_names = {row["name"] for row in train}
    holdout_names = {row["name"] for row in holdout}
    return {"seed": seed, "trainNames": train_names, "holdoutNames": holdout_names, "train": train, "holdout": holdout}


def v20_assign_split(rows: list[dict], split: dict) -> list[dict]:
    out = []
    for row in rows:
        clone = dict(row)
        clone["split"] = "holdout" if row["name"] in split["holdoutNames"] else "train"
        out.append(clone)
    return out


def v20_scaler(train_rows: list[dict], features: list[str]) -> dict[str, tuple[float, float]]:
    scaler = {}
    for key in features:
        values = [row[key] for row in train_rows if math.isfinite(row.get(key, math.nan))]
        mean_value = safe_mean(values)
        std_value = math.sqrt(safe_mean((value - mean_value) ** 2 for value in values)) if values and math.isfinite(mean_value) else 1.0
        scaler[key] = (mean_value if math.isfinite(mean_value) else 0.0, max(1e-9, std_value))
    return scaler


def v20_scaled(row: dict, features: list[str], scaler: dict[str, tuple[float, float]]) -> list[float]:
    values = []
    for key in features:
        mean_value, std_value = scaler[key]
        value = row.get(key, mean_value)
        if not math.isfinite(value):
            value = mean_value
        values.append((value - mean_value) / std_value)
    return values


def v20_centroids(train_rows: list[dict], features: list[str], scaler: dict[str, tuple[float, float]], label_key: str = "actualMode") -> dict[str, list[float]]:
    centroids = {}
    for branch in V20_BRANCHES:
        group = [row for row in train_rows if row[label_key] == branch]
        if not group:
            continue
        scaled = [v20_scaled(row, features, scaler) for row in group]
        centroids[branch] = [safe_median(vector[index] for vector in scaled) for index in range(len(features))]
    return centroids


def v20_predict_branch(row: dict, features: list[str], scaler: dict[str, tuple[float, float]], centroids: dict[str, list[float]]) -> tuple[str, float, str]:
    vector = v20_scaled(row, features, scaler)
    distances = []
    for branch, centroid in centroids.items():
        distance = math.sqrt(sum((vector[index] - centroid[index]) ** 2 for index in range(len(features))) / max(1, len(features)))
        distances.append((distance, branch))
    distances.sort(key=lambda item: (item[0], item[1]))
    if not distances:
        return "global support deficit", math.nan, ""
    margin = distances[1][0] - distances[0][0] if len(distances) > 1 else math.nan
    return distances[0][1], margin, "; ".join(f"{branch}:{fmt(distance)}" for distance, branch in distances)


def v20_branch_params(train_rows: list[dict], label_key: str = "actualMode") -> dict[str, dict]:
    params = {}
    fallback = train_rows
    for branch in V20_BRANCHES:
        group = [row for row in train_rows if row[label_key] == branch] or fallback
        params[branch] = {
            "scalarAmp": safe_median(row["scalarAmp"] for row in group),
            "qShape": safe_median(row["qShape"] for row in group),
            "qShapeAmp": safe_median(row["qShapeAmp"] for row in group),
            "twoKernelEta": safe_median(row["twoKernelEta"] for row in group),
            "twoKernelQ1": safe_median(row["twoKernelQ1"] for row in group),
            "twoKernelQ2": safe_median(row["twoKernelQ2"] for row in group),
            "twoKernelA1": safe_median(row["twoKernelA1"] for row in group),
            "twoKernelA2": safe_median(row["twoKernelA2"] for row in group),
        }
    return params


def score_v20_route_driver_branch(curve: dict, params: dict, branch: str, strength: float) -> dict:
    strength = clamp(strength, 0.0, 1.0)
    if branch == "global support deficit":
        amp = 1.0 + strength * (params["scalarAmp"] - 1.0)
        return score_curve_with_params(curve, amp, Q_DEFAULT)
    if branch == "mid dip deficit":
        amp = 1.0 + strength * (params["scalarAmp"] - 1.0)
        mid_amp = 1.0 + strength * (params["qShapeAmp"] - 1.0)
        outer_amp = 1.0 + strength * (params["scalarAmp"] - 1.0)
        return score_curve_with_three_zone(curve, amp, mid_amp, outer_amp, Q_DEFAULT)
    if branch == "outer deficit":
        a1 = 1.0 + strength * (params["twoKernelA1"] - 1.0)
        a2 = max(0.0, strength * params["twoKernelA2"])
        eta = params["twoKernelEta"] if math.isfinite(params["twoKernelEta"]) else 1.6
        q2 = params["twoKernelQ2"] if math.isfinite(params["twoKernelQ2"]) else Q_DEFAULT
        return score_curve_with_two_kernel(curve, a1, a2, Q_DEFAULT, q2, eta)
    if branch == "global oversupport":
        amp = max(0.0, 1.0 - strength * 0.75)
        return score_curve_with_params(curve, amp, Q_DEFAULT)
    return score_curve_with_params(curve, 1.0, Q_DEFAULT)


def v20_case_row(row: dict, branch: str, margin: float, distances: str, params: dict, strength: float, candidate_id: str) -> dict:
    curve = row["curve"]
    score = score_v20_route_driver_branch(curve, params.get(branch, params["global support deficit"]), branch, strength)
    baseline = score_curve_with_params(curve, 1.0, Q_DEFAULT)
    delta = score["rmse"] - baseline["rmse"]
    protected = row["failureClass"] in {"low-load over-support", "baryonic/over-support problem"} or (
        row["lockedRoute"] == "low-load" and branch == "global oversupport"
    )
    return {
        "candidateId": candidate_id,
        "name": row["name"],
        "split": row["split"],
        "actualMode": row["actualMode"],
        "predictedBranch": branch,
        "branchCorrect": branch == row["actualMode"],
        "branchMargin": margin,
        "branchDistances": distances,
        "failureClass": row["failureClass"],
        "observedRoute": row["observedRoute"],
        "lockedRoute": row["lockedRoute"],
        "candidateRoute": score["candidateRoute"],
        "oldRoutePreserved": score["candidateRoute"] == row["lockedRoute"],
        "observedRouteRecovered": score["candidateRoute"] == row["observedRoute"],
        "baselineRmse": baseline["rmse"],
        "candidateRmse": score["rmse"],
        "delta": delta,
        "improvement": baseline["rmse"] - score["rmse"],
        "improvementPct": pct_improvement(baseline["rmse"], score["rmse"]),
        "protectedCase": protected,
        "protectedRegression": protected and delta > 2.0,
        "regressionOver2": delta > 2.0,
        "regressionOver8": delta > 8.0,
        "weakHoldoutExcluded": row["weakHoldoutExcluded"],
        "memoryLoad": row["memoryLoad"],
        "u075": row["u075"],
        "uOut": row["uOut"],
        "uMax": row["uMax"],
        "leffOverH": row["leffOverH"],
        "fGasOut": row["fGasOut"],
        "gasOuterDominance": row.get("gasOuterDominance", math.nan),
        "diskConcentration": row.get("diskConcentration", math.nan),
        "barShapeCurvature": row.get("barShapeCurvature", math.nan),
    }


def v20_score_candidate(rows: list[dict], split: dict, feature_space: str, strength: float, label_overrides: dict[str, str] | None = None) -> tuple[dict, list[dict]]:
    assigned = v20_assign_split(rows, split)
    train_rows = [row for row in assigned if row["split"] == "train"]
    features = V20_FEATURE_SPACES[feature_space]
    if label_overrides:
        train_rows = [{**row, "trainLabel": label_overrides.get(row["name"], row["actualMode"])} for row in train_rows]
        label_key = "trainLabel"
    else:
        label_key = "actualMode"
    scaler = v20_scaler(train_rows, features)
    centroids = v20_centroids(train_rows, features, scaler, label_key=label_key)
    params = v20_branch_params(train_rows, label_key=label_key)
    candidate_id = f"v20-route-driver-{feature_space}-centroid-s{fmt_num(strength)}"
    ledgers = []
    for row in assigned:
        branch, margin, distances = v20_predict_branch(row, features, scaler, centroids)
        ledgers.append(v20_case_row(row, branch, margin, distances, params, strength, candidate_id))
    score = v20_score_summary(ledgers)
    score.update(
        {
            "candidateId": candidate_id,
            "featureSpace": feature_space,
            "strength": strength,
            "trainCount": len(train_rows),
            "holdoutCount": len([row for row in assigned if row["split"] == "holdout"]),
            "features": "; ".join(features),
        }
    )
    return score, ledgers


def v20_score_summary(rows: list[dict]) -> dict:
    holdout = [row for row in rows if row["split"] == "holdout"]
    high_holdout = [row for row in holdout if row["baselineRmse"] >= RESIDUAL_REPAIR_RMSE]
    protected = [row for row in rows if row["protectedCase"]]
    baseline_holdout = safe_mean(row["baselineRmse"] for row in holdout)
    candidate_holdout = safe_mean(row["candidateRmse"] for row in holdout)
    high_base = safe_mean(row["baselineRmse"] for row in high_holdout)
    high_cand = safe_mean(row["candidateRmse"] for row in high_holdout)
    return {
        "holdoutBaselineMean": baseline_holdout,
        "holdoutCandidateMean": candidate_holdout,
        "holdoutGainPct": pct_improvement(baseline_holdout, candidate_holdout),
        "highHoldoutBaselineMean": high_base,
        "highHoldoutCandidateMean": high_cand,
        "highHoldoutGainPct": pct_improvement(high_base, high_cand),
        "holdoutBranchAccuracy": safe_mean(1.0 if row["branchCorrect"] else 0.0 for row in holdout),
        "balancedBranchRecall": safe_mean(
            safe_mean(1.0 if row["branchCorrect"] else 0.0 for row in holdout if row["actualMode"] == branch)
            for branch in V20_BRANCHES
        ),
        "oldRoutePreservation": safe_mean(1.0 if row["oldRoutePreserved"] else 0.0 for row in rows),
        "observedRouteRecovery": safe_mean(1.0 if row["observedRouteRecovered"] else 0.0 for row in rows),
        "protectedRegressionCount": sum(1 for row in protected if row["protectedRegression"]),
        "protectedRegressionRate": safe_mean(1.0 if row["protectedRegression"] else 0.0 for row in protected),
        "regressionOver2Rate": safe_mean(1.0 if row["regressionOver2"] else 0.0 for row in holdout),
        "maxHoldoutRegression": max([row["delta"] for row in holdout] or [math.nan]),
        "weakSystematicsLeakage": sum(1 for row in rows if row["weakHoldoutExcluded"]),
    }


def v20_candidate_grid(rows: list[dict], split: dict) -> tuple[list[dict], list[dict]]:
    scores = []
    ledgers_by_id = {}
    for feature_space in ["state", "profile", "combined"]:
        for strength in [0.35, 0.50, 0.70, 1.00]:
            score, ledgers = v20_score_candidate(rows, split, feature_space, strength)
            scores.append(score)
            ledgers_by_id[score["candidateId"]] = ledgers
    for index, row in enumerate(sorted(scores, key=v20_score_sort_key, reverse=True), start=1):
        row["rank"] = index
    best = sorted(scores, key=v20_score_sort_key, reverse=True)[0]
    return scores, ledgers_by_id[best["candidateId"]]


def v20_score_sort_key(row: dict) -> tuple:
    protected_penalty = 20.0 * row["protectedRegressionCount"]
    regression_penalty = 5.0 * max(0.0, row["maxHoldoutRegression"] - 8.0 if math.isfinite(row["maxHoldoutRegression"]) else 0.0)
    return (
        row["holdoutGainPct"] + 0.35 * row["highHoldoutGainPct"] + 12.0 * row["balancedBranchRecall"] - protected_penalty - regression_penalty,
        -row["protectedRegressionCount"],
        -row["maxHoldoutRegression"] if math.isfinite(row["maxHoldoutRegression"]) else -999,
        row["candidateId"],
    )


def v20_null_controls(rows: list[dict], split: dict, best_score: dict) -> list[dict]:
    controls = []
    train_rows = [row for row in v20_assign_split(rows, split) if row["split"] == "train"]
    labels = [row["actualMode"] for row in train_rows]
    for index, seed in enumerate(V19_SEEDS):
        rng = random.Random(52000 + seed)
        shuffled = labels[:]
        rng.shuffle(shuffled)
        overrides = {row["name"]: label for row, label in zip(train_rows, shuffled)}
        score, _ledgers = v20_score_candidate(
            rows,
            split,
            best_score["featureSpace"],
            best_score["strength"],
            label_overrides=overrides,
        )
        controls.append(
            {
                "controlType": "shuffled-train-branch-labels",
                "seed": seed,
                "featureSpace": best_score["featureSpace"],
                "strength": best_score["strength"],
                "holdoutGainPct": score["holdoutGainPct"],
                "highHoldoutGainPct": score["highHoldoutGainPct"],
                "holdoutBranchAccuracy": score["holdoutBranchAccuracy"],
                "protectedRegressionCount": score["protectedRegressionCount"],
                "maxHoldoutRegression": score["maxHoldoutRegression"],
            }
        )
    for branch in V20_BRANCHES:
        overrides = {row["name"]: branch for row in train_rows}
        score, _ledgers = v20_score_candidate(rows, split, best_score["featureSpace"], best_score["strength"], label_overrides=overrides)
        controls.append(
            {
                "controlType": "single-branch-control",
                "seed": SPLIT_SEED,
                "featureSpace": best_score["featureSpace"],
                "strength": best_score["strength"],
                "forcedBranch": branch,
                "holdoutGainPct": score["holdoutGainPct"],
                "highHoldoutGainPct": score["highHoldoutGainPct"],
                "holdoutBranchAccuracy": score["holdoutBranchAccuracy"],
                "protectedRegressionCount": score["protectedRegressionCount"],
                "maxHoldoutRegression": score["maxHoldoutRegression"],
            }
        )
    return controls


def v20_seed_replay(rows: list[dict], holdout_fraction: float) -> tuple[list[dict], list[dict], list[dict]]:
    seed_rows = []
    best_ledgers = []
    best_scores = []
    for seed in V19_SEEDS:
        split = v20_split_rows(rows, seed, holdout_fraction)
        scores, ledgers = v20_candidate_grid(rows, split)
        best = sorted(scores, key=v20_score_sort_key, reverse=True)[0]
        seed_rows.append(
            {
                "seed": seed,
                "candidateId": best["candidateId"],
                "featureSpace": best["featureSpace"],
                "strength": best["strength"],
                "holdoutGainPct": best["holdoutGainPct"],
                "highHoldoutGainPct": best["highHoldoutGainPct"],
                "holdoutBranchAccuracy": best["holdoutBranchAccuracy"],
                "balancedBranchRecall": best["balancedBranchRecall"],
                "protectedRegressionCount": best["protectedRegressionCount"],
                "regressionOver2Rate": best["regressionOver2Rate"],
                "maxHoldoutRegression": best["maxHoldoutRegression"],
                "weakSystematicsLeakage": best["weakSystematicsLeakage"],
            }
        )
        if seed == SPLIT_SEED:
            best_ledgers = ledgers
            best_scores = scores
    return seed_rows, best_ledgers, best_scores


def v20_verdict(seed_rows: list[dict], null_rows: list[dict]) -> tuple[str, list[str], dict]:
    median_gain = safe_median(row["holdoutGainPct"] for row in seed_rows)
    median_high_gain = safe_median(row["highHoldoutGainPct"] for row in seed_rows)
    median_accuracy = safe_median(row["holdoutBranchAccuracy"] for row in seed_rows)
    median_recall = safe_median(row["balancedBranchRecall"] for row in seed_rows)
    max_protected = max([row["protectedRegressionCount"] for row in seed_rows] or [0])
    max_regression = max([row["maxHoldoutRegression"] for row in seed_rows if math.isfinite(row["maxHoldoutRegression"])] or [math.nan])
    best_null = max([row["holdoutGainPct"] for row in null_rows if math.isfinite(row["holdoutGainPct"])] or [math.nan])
    margin = median_gain - best_null if math.isfinite(best_null) else math.nan
    failures = []
    if median_gain < 15:
        failures.append("median holdout gain < 15%")
    if median_high_gain < 25:
        failures.append("high-RMSE holdout gain < 25%")
    if median_accuracy < 0.70:
        failures.append("branch accuracy < 70%")
    if median_recall < 0.60:
        failures.append("balanced branch recall < 60%")
    if max_protected > 1:
        failures.append("protected regressions > 1")
    if math.isfinite(max_regression) and max_regression > 8:
        failures.append("max holdout regression > 8 km/s")
    if not math.isfinite(margin) or margin < 10:
        failures.append("does not beat branch/null controls by 10 points")
    if any(row["weakSystematicsLeakage"] for row in seed_rows):
        failures.append("weak/systematics leakage")
    if not failures:
        verdict = "MTS v20 route-driver candidate promoted for review"
    elif median_gain >= 15 and (not math.isfinite(margin) or margin < 10):
        verdict = "route-driver signal but not above null"
    elif max_protected > 1 or (math.isfinite(max_regression) and max_regression > 8):
        verdict = "protected-case failure"
    elif median_accuracy < 0.70 or median_recall < 0.60:
        verdict = "branch driver not learnable"
    else:
        verdict = "route-driver idea rejected"
    metrics = {
        "medianHoldoutGainPct": median_gain,
        "medianHighHoldoutGainPct": median_high_gain,
        "medianBranchAccuracy": median_accuracy,
        "medianBalancedBranchRecall": median_recall,
        "maxProtectedRegressionCount": max_protected,
        "maxHoldoutRegression": max_regression,
        "bestNullHoldoutGainPct": best_null,
        "nullMarginPct": margin,
    }
    return verdict, failures, metrics


def v20_route_driver_report(capsule: dict, score_rows: list[dict], seed_rows: list[dict], case_rows: list[dict], protected_rows: list[dict], null_rows: list[dict]) -> str:
    best = score_rows[0]
    metrics = capsule["decisionMetrics"]
    lines = [
        "# MTS v20 Route-Driver Candidate",
        "",
        "This is a framework proposal test. It asks whether the missing MTS variable is a pre-residual route-driver state that chooses the branch mechanism, rather than a scalar support or `L_eff` correction.",
        "",
        "## Headline",
        "",
        f"Verdict: **{capsule['verdict']}**.",
        f"Best main-split candidate: `{best['candidateId']}`.",
        f"Feature space: `{best['featureSpace']}`; strength: `{fmt(best['strength'])}`.",
        f"Primary anatomy cases: `{capsule['facts']['primaryAnatomyCount']}`.",
        f"Weak/systematics leakage: `{capsule['facts']['weakHoldoutLeakage']}`.",
        "",
        "## Decision Metrics",
        "",
        "| Metric | Value |",
        "| --- | ---: |",
        f"| Median holdout gain | {fmt(metrics['medianHoldoutGainPct'])}% |",
        f"| Median high-RMSE holdout gain | {fmt(metrics['medianHighHoldoutGainPct'])}% |",
        f"| Median branch accuracy | {fmt(100 * metrics['medianBranchAccuracy'])}% |",
        f"| Median balanced branch recall | {fmt(100 * metrics['medianBalancedBranchRecall'])}% |",
        f"| Protected regressions | {metrics['maxProtectedRegressionCount']} |",
        f"| Max holdout regression | {fmt(metrics['maxHoldoutRegression'])} km/s |",
        f"| Best branch/null control gain | {fmt(metrics['bestNullHoldoutGainPct'])}% |",
        f"| Null margin | {fmt(metrics['nullMarginPct'])} points |",
        "",
        "## Guardrail Failures",
        "",
    ]
    if capsule["guardrailFailures"]:
        lines.extend(f"- {failure}" for failure in capsule["guardrailFailures"])
    else:
        lines.append("- none")
    lines.extend(
        [
            "",
            "## Candidate Scores",
            "",
            "| Rank | Candidate | Feature space | Strength | Holdout gain | High gain | Accuracy | Balanced recall | Protected regressions | Max regression |",
            "| ---: | --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
        ]
    )
    for row in score_rows[:12]:
        lines.append(
            f"| {row['rank']} | `{row['candidateId']}` | {row['featureSpace']} | {fmt(row['strength'])} | "
            f"{fmt(row['holdoutGainPct'])}% | {fmt(row['highHoldoutGainPct'])}% | "
            f"{fmt(100 * row['holdoutBranchAccuracy'])}% | {fmt(100 * row['balancedBranchRecall'])}% | "
            f"{row['protectedRegressionCount']} | {fmt(row['maxHoldoutRegression'])} |"
        )
    lines.extend(
        [
            "",
            "## Seed Replay",
            "",
            "| Seed | Candidate | Gain | High gain | Accuracy | Recall | Protected regressions | Max regression |",
            "| ---: | --- | ---: | ---: | ---: | ---: | ---: | ---: |",
        ]
    )
    for row in seed_rows:
        lines.append(
            f"| {row['seed']} | `{row['candidateId']}` | {fmt(row['holdoutGainPct'])}% | "
            f"{fmt(row['highHoldoutGainPct'])}% | {fmt(100 * row['holdoutBranchAccuracy'])}% | "
            f"{fmt(100 * row['balancedBranchRecall'])}% | {row['protectedRegressionCount']} | "
            f"{fmt(row['maxHoldoutRegression'])} |"
        )
    lines.extend(
        [
            "",
            "## Case Ledger",
            "",
            "| Galaxy | Split | Actual mode | Predicted branch | Baseline | Candidate | Gain | Route |",
            "| --- | --- | --- | --- | ---: | ---: | ---: | --- |",
        ]
    )
    for row in sorted(case_rows, key=lambda item: item["improvement"], reverse=True)[:30]:
        lines.append(
            f"| {row['name']} | {row['split']} | {row['actualMode']} | {row['predictedBranch']} | "
            f"{fmt(row['baselineRmse'])} | {fmt(row['candidateRmse'])} | {fmt(row['improvement'])} | {row['candidateRoute']} |"
        )
    lines.extend(
        [
            "",
            "## Protected Ledger",
            "",
            "| Galaxy | Split | Failure class | Predicted branch | Baseline | Candidate | Delta | Protected regression |",
            "| --- | --- | --- | --- | ---: | ---: | ---: | --- |",
        ]
    )
    for row in protected_rows:
        lines.append(
            f"| {row['name']} | {row['split']} | {row['failureClass']} | {row['predictedBranch']} | "
            f"{fmt(row['baselineRmse'])} | {fmt(row['candidateRmse'])} | {fmt(row['delta'])} | {row['protectedRegression']} |"
        )
    lines.extend(
        [
            "",
            "## Null Controls",
            "",
            "| Control | Seed | Gain | High gain | Accuracy | Protected regressions | Max regression |",
            "| --- | ---: | ---: | ---: | ---: | ---: | ---: |",
        ]
    )
    for row in null_rows:
        lines.append(
            f"| {row['controlType']} | {row['seed']} | {fmt(row['holdoutGainPct'])}% | "
            f"{fmt(row['highHoldoutGainPct'])}% | {fmt(100 * row['holdoutBranchAccuracy'])}% | "
            f"{row['protectedRegressionCount']} | {fmt(row['maxHoldoutRegression'])} |"
        )
    lines.extend(
        [
            "",
            "## Formula Discipline",
            "",
            "- Candidate inputs are profile/state variables only.",
            "- Residual labels are train targets only; holdout predictions use centroid state distance.",
            "- Galaxy names, raw residuals, raw RMSE, and weak/systematics cases are not formula inputs.",
            "- Old route preservation is reported, but not used as the primary rejection criterion because this is explicitly a route-driver proposal.",
            "",
            f"Final verdict: **{capsule['verdict']}**.",
            "",
        ]
    )
    return "\n".join(lines)


def write_v20_route_driver_artifacts(out_dir: Path, curves: list[dict], holdout_fraction: float) -> dict:
    rows, facts = v20_build_rows(curves)
    rows = [row for row in rows if not row["weakHoldoutExcluded"]]
    split = v20_split_rows(rows, SPLIT_SEED, holdout_fraction)
    score_rows, case_rows = v20_candidate_grid(rows, split)
    score_rows.sort(key=v20_score_sort_key, reverse=True)
    for index, row in enumerate(score_rows, start=1):
        row["rank"] = index
    best = score_rows[0]
    null_rows = v20_null_controls(rows, split, best)
    seed_rows, seed_case_rows, seed_score_rows = v20_seed_replay(rows, holdout_fraction)
    if seed_case_rows:
        case_rows = seed_case_rows
    if seed_score_rows:
        seed_score_rows.sort(key=v20_score_sort_key, reverse=True)
        for index, row in enumerate(seed_score_rows, start=1):
            row["rank"] = index
        score_rows = seed_score_rows
        best = score_rows[0]
    verdict, failures, decision_metrics = v20_verdict(seed_rows, null_rows)
    protected_rows = sorted(
        [row for row in case_rows if row["protectedCase"] or row["protectedRegression"]],
        key=lambda row: (not row["protectedRegression"], -row["delta"], row["name"]),
    )
    formula = {
        "candidateId": best["candidateId"],
        "featureSpace": best["featureSpace"],
        "strength": best["strength"],
        "features": best["features"].split("; "),
        "branchActions": {
            "global support deficit": "scalar support normalization using train branch median scalarAmp",
            "mid dip deficit": "three-zone mid redistribution using train branch median qShapeAmp",
            "outer deficit": "two-kernel outer radial-memory branch using train branch medians",
            "global oversupport": "low-load support suppression",
        },
        "forbiddenInputs": ["galaxy name", "raw residuals", "raw RMSE", "weak/systematics cases", "per-galaxy lookup"],
    }
    capsule = {
        "type": "mts-v20-route-driver-candidate",
        "version": 1,
        "generatedAt": "deterministic",
        "sourceScript": "scripts/mts-failure-lab.py",
        "canonicalMtsStatus": "locked baseline; v20 route-driver proposal branch only",
        "verdict": verdict,
        "guardrailFailures": failures,
        "decisionMetrics": decision_metrics,
        "bestFormula": formula,
        "facts": {
            **facts,
            "primaryAnatomyCount": len(rows),
            "weakHoldoutLeakage": sum(1 for row in rows if row["weakHoldoutExcluded"]),
            "allGalaxyLockedMtsMean": baseline_summary(curves)["baselineMean"],
            "cleanSetLockedMtsMean": 19.33,
        },
        "seeds": V19_SEEDS,
        "rules": {
            "routePreservationIsPrimaryGuardrail": False,
            "reason": "this is a route-driver proposal, so old locked route changes are evidence rather than automatic failure",
        },
    }
    out_dir.mkdir(parents=True, exist_ok=True)
    write_csv(out_dir / "mts_v20_route_driver_candidate_scores.csv", score_rows)
    write_csv(out_dir / "mts_v20_route_driver_seed_replay.csv", seed_rows)
    write_csv(out_dir / "mts_v20_route_driver_case_ledger.csv", case_rows)
    write_csv(out_dir / "mts_v20_route_driver_protected_ledger.csv", protected_rows)
    write_csv(out_dir / "mts_v20_route_driver_null_controls.csv", null_rows)
    (out_dir / "mts_v20_route_driver_formula.json").write_text(json.dumps(json_clean(formula), indent=2), encoding="utf-8")
    report = v20_route_driver_report(capsule, score_rows, seed_rows, case_rows, protected_rows, null_rows)
    (out_dir / "mts_v20_route_driver_report.md").write_text(report, encoding="utf-8")
    (out_dir / "mts_v20_route_driver_report.txt").write_text(report, encoding="utf-8")
    (out_dir / "mts_v20_route_driver_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2), encoding="utf-8")
    return capsule


V21_BETAS = [0.50, 1.00, 1.50, 2.00, 2.50, 3.00, 3.50, 4.00, 4.50, 5.00]
V21_RULE_SPECS = [
    (("boundaryScore", "ge"), ("uOut", "ge")),
    (("boundaryScore", "ge"), ("u075", "ge")),
    (("memoryLoad", "ge"), ("uOut", "ge")),
    (("memoryLoad", "ge"), ("uMax", "ge")),
    (("uMax", "ge"), ("routeMargin", "ge")),
    (("uMax", "ge"), ("routeBreakRisk", "le")),
    (("boundaryScore", "ge"), ("fGasOut", "le")),
    (("uOut", "ge"), ("lGap", "ge")),
]
V21_QUANTILES = [0.15, 0.25, 0.33, 0.50, 0.66, 0.75, 0.85, 0.90]


def v21_curve_feature_row(curve: dict, context: dict) -> dict:
    base = score_curve_with_params(curve, 1.0, Q_DEFAULT)
    terms = v19_curve_memory_terms(curve)
    stretch_scores = {
        beta: score_curve_with_leff_value(curve, terms["lExact"] * (1.0 + beta))
        for beta in V21_BETAS
    }
    name = curve["name"]
    return {
        "name": name,
        "curve": curve,
        "baseline": base,
        "stretchScores": stretch_scores,
        "cleanSet": name in context["cleanNames"],
        "primaryCase": name in context["primaryNames"],
        "lowloadRouteLockTarget": name in context["lowloadRouteLockNames"],
        "protectedCase": name in context["protectedNames"],
        "oversupportCase": name in context["oversupportNames"],
        "weakHoldoutExcluded": name in context["weakNames"],
        "failureClass": context["anatomyByName"].get(name, {}).get("failureClass", ""),
        "noGoClass": context["noGoByName"].get(name, {}).get("noGoClass", ""),
        "lockedRoute": base["candidateRoute"],
        "boundaryScore": terms["boundaryScore"],
        "memoryLoad": curve["memoryLoad"],
        "u075": curve["u075"],
        "uOut": curve["uOut"],
        "uMax": curve["uMax"],
        "lockedUOut": curve["lockedModelUOut"],
        "lockedUMax": curve["lockedModelUMax"],
        "routeMargin": curve["routeMargin"],
        "routeBreakRisk": curve["routeBreakRisk"],
        "hOverRout": curve["h"] / curve["rOut"] if curve["rOut"] else math.nan,
        "fGasOut": curve["fGasOut"],
        "lExact": terms["lExact"],
        "lSat": terms["lSat"],
        "lGap": terms["lGap"],
        "leffOverH": curve["leffOverH"],
    }


def v21_build_rows(curves: list[dict]) -> tuple[list[dict], dict]:
    context = v19_clean_context(curves)
    clean_rows = [v21_curve_feature_row(curve, context) for curve in context["cleanCurves"]]
    facts = {
        "cleanCurveCount": len(clean_rows),
        "primaryAnatomyCount": len(context["primaryNames"]),
        "lowloadRouteLockCount": len(context["lowloadRouteLockNames"]),
        "weakHoldoutCount": len(context["weakNames"]),
        "weakHoldoutLeakage": sum(1 for row in clean_rows if row["weakHoldoutExcluded"]),
        "allGalaxyLockedMtsMean": baseline_summary(curves)["baselineMean"],
        "cleanSetLockedMtsMean": 19.33,
        "inputPaths": context["inputPaths"],
    }
    return clean_rows, facts


def v21_split_rows(rows: list[dict], seed: int, holdout_fraction: float) -> dict:
    split = stratified_split([row["curve"] for row in rows], seed, holdout_fraction)
    return {
        "seed": seed,
        "trainNames": {curve["name"] for curve in split["train"]},
        "holdoutNames": {curve["name"] for curve in split["holdout"]},
    }


def v21_threshold_values(rows: list[dict], names: set[str], key: str) -> list[float]:
    values = sorted(
        row[key]
        for row in rows
        if row["name"] in names and row["lockedRoute"] == "low-load" and math.isfinite(row.get(key, math.nan))
    )
    if not values:
        return [0.0]
    out = []
    for fraction in V21_QUANTILES:
        index = min(len(values) - 1, max(0, int(round((len(values) - 1) * fraction))))
        out.append(round(values[index], 6))
    return v19_unique_floats(out)


def v21_condition_passes(row: dict, condition: tuple[str, str, float]) -> bool:
    key, direction, threshold = condition
    value = row.get(key, math.nan)
    if not math.isfinite(value):
        return False
    return value >= threshold if direction == "ge" else value <= threshold


def v21_rule_passes(row: dict, rule: tuple[tuple[str, str, float], ...]) -> bool:
    return row["lockedRoute"] == "low-load" and all(v21_condition_passes(row, condition) for condition in rule)


def v21_rule_id(rule: tuple[tuple[str, str, float], ...], beta: float) -> str:
    pieces = [f"{key}{direction}{fmt_num(threshold)}" for key, direction, threshold in rule]
    return "v21-memory-stretch-" + "-and-".join(pieces).replace(".", "p") + f"-b{fmt_num(beta)}".replace(".", "p")


def v21_candidate_rules(rows: list[dict], train_names: set[str]) -> list[tuple[tuple[str, str, float], ...]]:
    rules: list[tuple[tuple[str, str, float], ...]] = []
    for (first, second) in V21_RULE_SPECS:
        first_key, first_direction = first
        second_key, second_direction = second
        for first_threshold in v21_threshold_values(rows, train_names, first_key):
            for second_threshold in v21_threshold_values(rows, train_names, second_key):
                rules.append(((first_key, first_direction, first_threshold), (second_key, second_direction, second_threshold)))
    # Preserve deterministic order while dropping duplicate threshold combinations.
    seen = set()
    unique = []
    for rule in rules:
        if rule not in seen:
            seen.add(rule)
            unique.append(rule)
    return unique


def v21_case_rows(
    rows: list[dict],
    split: dict,
    rule: tuple[tuple[str, str, float], ...],
    beta: float,
    *,
    active_override: set[str] | None = None,
    candidate_id: str | None = None,
    family: str = "state-gated-memory-stretch",
) -> list[dict]:
    candidate_id = candidate_id or v21_rule_id(rule, beta)
    out = []
    for row in rows:
        if active_override is None:
            active = v21_rule_passes(row, rule)
        else:
            active = row["lockedRoute"] == "low-load" and row["name"] in active_override
        score = row["stretchScores"][beta] if active else row["baseline"]
        baseline = row["baseline"]
        delta = score["rmse"] - baseline["rmse"]
        out.append(
            {
                "candidateFamily": family,
                "candidateId": candidate_id,
                "name": row["name"],
                "split": "holdout" if row["name"] in split["holdoutNames"] else "train",
                "failureClass": row["failureClass"],
                "noGoClass": row["noGoClass"],
                "lockedRoute": row["lockedRoute"],
                "candidateRoute": score["candidateRoute"],
                "oldRoutePreserved": score["candidateRoute"] == row["lockedRoute"],
                "weakHoldoutExcluded": row["weakHoldoutExcluded"],
                "primaryCase": row["primaryCase"],
                "lowloadRouteLockTarget": row["lowloadRouteLockTarget"],
                "protectedCase": row["protectedCase"] and not row["lowloadRouteLockTarget"],
                "oversupportCase": row["oversupportCase"],
                "baselineRmse": baseline["rmse"],
                "candidateRmse": score["rmse"],
                "delta": delta,
                "improvement": baseline["rmse"] - score["rmse"],
                "improvementPct": pct_improvement(baseline["rmse"], score["rmse"]),
                "activeStretch": active,
                "beta": beta,
                "leffExact": row["lExact"],
                "leffCandidate": score.get("candidateLeff", row["lExact"]),
                "leffStretchFactor": (score.get("candidateLeff", row["lExact"]) / row["lExact"]) if row["lExact"] else math.nan,
                "boundaryScore": row["boundaryScore"],
                "memoryLoad": row["memoryLoad"],
                "u075": row["u075"],
                "uOut": row["uOut"],
                "uMax": row["uMax"],
                "routeMargin": row["routeMargin"],
                "routeBreakRisk": row["routeBreakRisk"],
                "hOverRout": row["hOverRout"],
                "fGasOut": row["fGasOut"],
                "lGap": row["lGap"],
                "protectedFalseRelease": active and row["protectedCase"] and not row["lowloadRouteLockTarget"] and delta > 2.0,
                "oversupportWorsened": row["oversupportCase"] and delta > 0.0,
                "regressionOver2": delta > 2.0,
                "regressionOver8": delta > 8.0,
            }
        )
    return out


def v21_metric_summary(case_rows: list[dict]) -> dict:
    holdout = [row for row in case_rows if row["split"] == "holdout"]
    train = [row for row in case_rows if row["split"] == "train"]
    holdout_primary = [row for row in holdout if row["primaryCase"]]
    train_primary = [row for row in train if row["primaryCase"]]
    holdout_lowlock = [row for row in holdout if row["lowloadRouteLockTarget"]]
    train_lowlock = [row for row in train if row["lowloadRouteLockTarget"]]
    protected = [row for row in case_rows if row["protectedCase"]]
    oversupport = [row for row in case_rows if row["oversupportCase"]]
    train_protected = [row for row in train if row["protectedCase"]]
    train_oversupport = [row for row in train if row["oversupportCase"]]

    def gain(rows_in: list[dict]) -> float:
        base = safe_mean(row["baselineRmse"] for row in rows_in)
        candidate = safe_mean(row["candidateRmse"] for row in rows_in)
        return pct_improvement(base, candidate)

    max_holdout_regression = max([row["delta"] for row in holdout] or [math.nan])
    protected_false = sum(1 for row in protected if row["protectedFalseRelease"])
    oversupport_worse = sum(1 for row in oversupport if row["oversupportWorsened"])
    train_max_regression = max([row["delta"] for row in train] or [math.nan])
    train_protected_false = sum(1 for row in train_protected if row["protectedFalseRelease"])
    train_oversupport_worse = sum(1 for row in train_oversupport if row["oversupportWorsened"])
    utility = (
        gain(train_lowlock)
        + 0.60 * gain(train_primary)
        + 0.25 * gain(train)
        + 2.0 * sum(1 for row in train_lowlock if row["candidateRmse"] < RESIDUAL_REPAIR_RMSE)
        - 30.0 * train_protected_false
        - 25.0 * train_oversupport_worse
        - 5.0 * max(0.0, train_max_regression - 8.0 if math.isfinite(train_max_regression) else 0.0)
    )
    return {
        "trainUtility": utility,
        "trainCleanGainPct": gain(train),
        "trainPrimaryGainPct": gain(train_primary),
        "holdoutCleanGainPct": gain(holdout),
        "holdoutPrimaryGainPct": gain(holdout_primary),
        "trainLowLoadRouteLockGainPct": gain(train_lowlock),
        "trainLowLoadRouteLockRepairCount": sum(1 for row in train_lowlock if row["candidateRmse"] < RESIDUAL_REPAIR_RMSE),
        "holdoutLowLoadRouteLockGainPct": gain(holdout_lowlock),
        "holdoutLowLoadRouteLockCount": len(holdout_lowlock),
        "holdoutLowLoadRouteLockRepairCount": sum(1 for row in holdout_lowlock if row["candidateRmse"] < RESIDUAL_REPAIR_RMSE),
        "protectedFalseReleaseCount": protected_false,
        "trainProtectedFalseReleaseCount": train_protected_false,
        "oversupportWorsenedCount": oversupport_worse,
        "trainOversupportWorsenedCount": train_oversupport_worse,
        "maxHoldoutRegression": max_holdout_regression,
        "maxTrainRegression": train_max_regression,
        "activeStretchCount": sum(1 for row in case_rows if row["activeStretch"]),
        "activeProtectedCount": sum(1 for row in protected if row["activeStretch"]),
        "routeChangeCount": sum(1 for row in case_rows if not row["oldRoutePreserved"]),
        "weakSystematicsLeakage": sum(1 for row in case_rows if row["weakHoldoutExcluded"]),
    }


def v21_candidate_score_row(
    rank: int,
    rule: tuple[tuple[str, str, float], ...],
    beta: float,
    metrics: dict,
) -> dict:
    return {
        "rank": rank,
        "candidateId": v21_rule_id(rule, beta),
        "ruleText": " and ".join(f"{key} {direction} {fmt(threshold)}" for key, direction, threshold in rule),
        "beta": beta,
        **metrics,
    }


def v21_score_sort_key(row: dict) -> tuple:
    return (
        row["trainUtility"],
        row["trainLowLoadRouteLockGainPct"],
        row["holdoutLowLoadRouteLockGainPct"],
        -row["trainProtectedFalseReleaseCount"],
        -row["trainOversupportWorsenedCount"],
        -row["maxTrainRegression"] if math.isfinite(row["maxTrainRegression"]) else -999,
        row["candidateId"],
    )


def v21_candidate_grid(rows: list[dict], split: dict) -> tuple[list[dict], list[dict], tuple[tuple[str, str, float], ...], float]:
    score_rows = []
    ledgers: dict[str, list[dict]] = {}
    for rule in v21_candidate_rules(rows, split["trainNames"]):
        for beta in V21_BETAS:
            case_rows = v21_case_rows(rows, split, rule, beta)
            metrics = v21_metric_summary(case_rows)
            record = v21_candidate_score_row(0, rule, beta, metrics)
            score_rows.append(record)
            ledgers[record["candidateId"]] = case_rows
    score_rows.sort(key=v21_score_sort_key, reverse=True)
    for index, row in enumerate(score_rows, start=1):
        row["rank"] = index
    best = score_rows[0]
    best_rule = next(rule for rule in v21_candidate_rules(rows, split["trainNames"]) if v21_rule_id(rule, best["beta"]) == best["candidateId"])
    return score_rows, ledgers[best["candidateId"]], best_rule, best["beta"]


def v21_random_null_rows(
    rows: list[dict],
    split: dict,
    rule: tuple[tuple[str, str, float], ...],
    beta: float,
    *,
    count: int,
    seed: int,
) -> list[dict]:
    lowload_names = sorted(row["name"] for row in rows if row["lockedRoute"] == "low-load")
    rng = random.Random(seed)
    out = []
    for index in range(20):
        active = set(rng.sample(lowload_names, min(count, len(lowload_names))))
        case_rows = v21_case_rows(
            rows,
            split,
            rule,
            beta,
            active_override=active,
            candidate_id=f"v21-random-lowload-stretch-null-{seed}-{index}",
            family="random-lowload-stretch-null",
        )
        metrics = v21_metric_summary(case_rows)
        out.append(
            {
                "controlType": "random-lowload-stretch-null",
                "seed": seed,
                "iteration": index,
                "activeCount": count,
                **metrics,
            }
        )
    all_low = {
        row["name"]
        for row in rows
        if row["lockedRoute"] == "low-load"
    }
    all_low_rows = v21_case_rows(
        rows,
        split,
        rule,
        beta,
        active_override=all_low,
        candidate_id="v21-all-lowload-stretch-control",
        family="all-lowload-stretch-control",
    )
    out.append({"controlType": "all-lowload-stretch-control", "seed": seed, "iteration": -1, "activeCount": len(all_low), **v21_metric_summary(all_low_rows)})
    return out


def v21_utility_margin(metrics: dict, null_rows: list[dict]) -> float:
    best_null = max([row["trainUtility"] for row in null_rows if math.isfinite(row["trainUtility"])] or [math.nan])
    return metrics["trainUtility"] - best_null if math.isfinite(best_null) else math.nan


def v21_seed_replay(rows: list[dict], holdout_fraction: float) -> tuple[list[dict], list[dict], list[dict], list[dict]]:
    seed_rows = []
    all_null_rows = []
    main_case_rows = []
    main_score_rows = []
    for seed in V19_SEEDS:
        split = v21_split_rows(rows, seed, holdout_fraction)
        score_rows, case_rows, rule, beta = v21_candidate_grid(rows, split)
        best = score_rows[0]
        active_count = sum(1 for row in case_rows if row["activeStretch"] and row["lockedRoute"] == "low-load")
        null_rows = v21_random_null_rows(rows, split, rule, beta, count=active_count, seed=seed + 61000)
        null_best_utility = max([row["trainUtility"] for row in null_rows if math.isfinite(row["trainUtility"])] or [math.nan])
        seed_rows.append(
            {
                "seed": seed,
                "candidateId": best["candidateId"],
                "ruleText": best["ruleText"],
                "beta": beta,
                "holdoutCleanGainPct": best["holdoutCleanGainPct"],
                "holdoutPrimaryGainPct": best["holdoutPrimaryGainPct"],
                "holdoutLowLoadRouteLockGainPct": best["holdoutLowLoadRouteLockGainPct"],
                "holdoutLowLoadRouteLockRepairCount": best["holdoutLowLoadRouteLockRepairCount"],
                "protectedFalseReleaseCount": best["protectedFalseReleaseCount"],
                "oversupportWorsenedCount": best["oversupportWorsenedCount"],
                "maxHoldoutRegression": best["maxHoldoutRegression"],
                "activeStretchCount": best["activeStretchCount"],
                "routeChangeCount": best["routeChangeCount"],
                "weakSystematicsLeakage": best["weakSystematicsLeakage"],
                "bestNullTrainUtility": null_best_utility,
                "utilityMarginVsNull": best["trainUtility"] - null_best_utility if math.isfinite(null_best_utility) else math.nan,
            }
        )
        all_null_rows.extend(null_rows)
        if seed == SPLIT_SEED:
            main_case_rows = case_rows
            main_score_rows = score_rows
    return seed_rows, all_null_rows, main_case_rows, main_score_rows


def v21_verdict(seed_rows: list[dict]) -> tuple[str, list[str], dict]:
    metrics = {
        "medianCleanHoldoutGainPct": safe_median(row["holdoutCleanGainPct"] for row in seed_rows),
        "medianPrimaryHoldoutGainPct": safe_median(row["holdoutPrimaryGainPct"] for row in seed_rows),
        "medianLowLoadRouteLockHoldoutGainPct": safe_median(row["holdoutLowLoadRouteLockGainPct"] for row in seed_rows),
        "medianUtilityMarginVsNull": safe_median(row["utilityMarginVsNull"] for row in seed_rows),
        "maxProtectedFalseReleaseCount": max([row["protectedFalseReleaseCount"] for row in seed_rows] or [0]),
        "maxOversupportWorsenedCount": max([row["oversupportWorsenedCount"] for row in seed_rows] or [0]),
        "maxHoldoutRegression": max([row["maxHoldoutRegression"] for row in seed_rows if math.isfinite(row["maxHoldoutRegression"])] or [math.nan]),
        "maxWeakSystematicsLeakage": max([row["weakSystematicsLeakage"] for row in seed_rows] or [0]),
    }
    failures = []
    if metrics["medianCleanHoldoutGainPct"] < 5:
        failures.append("median clean holdout gain < 5%")
    if metrics["medianPrimaryHoldoutGainPct"] < 8:
        failures.append("median clean high-RMSE holdout gain < 8%")
    if metrics["medianLowLoadRouteLockHoldoutGainPct"] < 25:
        failures.append("low-load route-lock holdout gain < 25%")
    if metrics["maxProtectedFalseReleaseCount"] > 1:
        failures.append("protected false releases > 1")
    if metrics["maxOversupportWorsenedCount"] > 0:
        failures.append("low-load oversupport cases worsen")
    if math.isfinite(metrics["maxHoldoutRegression"]) and metrics["maxHoldoutRegression"] > 8:
        failures.append("max holdout regression > 8 km/s")
    if not math.isfinite(metrics["medianUtilityMarginVsNull"]) or metrics["medianUtilityMarginVsNull"] < 10:
        failures.append("does not beat random low-load stretch null utility by 10 points")
    if metrics["maxWeakSystematicsLeakage"] != 0:
        failures.append("weak/systematics leakage")
    if not failures:
        verdict = "MTS v21 memory-stretch branch promoted for review"
    elif metrics["medianLowLoadRouteLockHoldoutGainPct"] >= 25 and metrics["maxProtectedFalseReleaseCount"] <= 1:
        verdict = "memory-stretch branch signal but not above null"
    elif metrics["maxProtectedFalseReleaseCount"] > 1 or metrics["maxOversupportWorsenedCount"] > 0:
        verdict = "protected-case failure"
    else:
        verdict = "memory-stretch idea rejected"
    return verdict, failures, metrics


def v21_formula_from_score(best: dict) -> dict:
    return {
        "candidateId": best["candidateId"],
        "formulaText": "For locked low-load galaxies passing the learned state gate: L_eff_v21 = L_exact * (1 + beta); otherwise canonical L_exact.",
        "ruleText": best["ruleText"],
        "beta": best["beta"],
        "q": Q_DEFAULT,
        "gamma0": GAMMA0,
        "mlDisk": ML_DISK,
        "mlBulge": ML_BULGE,
        "allowedInputs": ["locked route", "boundaryScore", "memoryLoad", "u_0.75", "u_out", "u_max", "routeMargin", "routeBreakRisk", "fGasOut", "L_eff/h", "L_gap"],
        "forbiddenInputs": ["galaxy name", "raw residuals", "raw RMSE as formula input", "q changes", "amplitude patches", "weak/systematics fitting"],
    }


def v21_report(capsule: dict, score_rows: list[dict], seed_rows: list[dict], case_rows: list[dict], protected_rows: list[dict], null_rows: list[dict]) -> str:
    best = score_rows[0]
    metrics = capsule["decisionMetrics"]
    lines = [
        "# MTS v21 Memory-Boundary Stretch Candidate",
        "",
        "This is a framework proposal test. It asks whether low-load route-lock systems need a controlled memory-length stretch beyond the small canonical saturation gap.",
        "",
        "## Headline",
        "",
        f"Verdict: **{capsule['verdict']}**.",
        f"Best main-split candidate: `{best['candidateId']}`.",
        f"Rule: `{best['ruleText']}`; beta: `{fmt(best['beta'])}`.",
        f"Clean curves: `{capsule['facts']['cleanCurveCount']}`; weak/systematics leakage: `{capsule['facts']['weakHoldoutLeakage']}`.",
        f"Clean anatomy cases: `{capsule['facts']['primaryAnatomyCount']}`; low-load route-lock targets: `{capsule['facts']['lowloadRouteLockCount']}`.",
        "",
        "## Decision Metrics",
        "",
        "| Metric | Value |",
        "| --- | ---: |",
        f"| Median clean holdout gain | {fmt(metrics['medianCleanHoldoutGainPct'])}% |",
        f"| Median clean high-RMSE holdout gain | {fmt(metrics['medianPrimaryHoldoutGainPct'])}% |",
        f"| Median low-load route-lock holdout gain | {fmt(metrics['medianLowLoadRouteLockHoldoutGainPct'])}% |",
        f"| Median utility margin vs random low-load stretch null | {fmt(metrics['medianUtilityMarginVsNull'])} points |",
        f"| Max protected false releases | {metrics['maxProtectedFalseReleaseCount']} |",
        f"| Max oversupport worsened count | {metrics['maxOversupportWorsenedCount']} |",
        f"| Max holdout regression | {fmt(metrics['maxHoldoutRegression'])} km/s |",
        "",
        "## Guardrail Failures",
        "",
    ]
    lines.extend([f"- {failure}" for failure in capsule["guardrailFailures"]] or ["- none"])
    lines.extend(
        [
            "",
            "## Candidate Scores",
            "",
            "| Rank | Candidate | Rule | beta | Holdout gain | Primary gain | Low-load route-lock gain | False releases | Oversupport worsened | Max regression |",
            "| ---: | --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
        ]
    )
    for row in score_rows[:15]:
        lines.append(
            f"| {row['rank']} | `{row['candidateId']}` | {row['ruleText']} | {fmt(row['beta'])} | "
            f"{fmt(row['holdoutCleanGainPct'])}% | {fmt(row['holdoutPrimaryGainPct'])}% | "
            f"{fmt(row['holdoutLowLoadRouteLockGainPct'])}% | {row['protectedFalseReleaseCount']} | "
            f"{row['oversupportWorsenedCount']} | {fmt(row['maxHoldoutRegression'])} |"
        )
    lines.extend(
        [
            "",
            "## Seed Replay",
            "",
            "| Seed | Candidate | Clean gain | Primary gain | Low-load route-lock gain | False releases | Oversupport worsened | Max regression | Null margin |",
            "| ---: | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
        ]
    )
    for row in seed_rows:
        lines.append(
            f"| {row['seed']} | `{row['candidateId']}` | {fmt(row['holdoutCleanGainPct'])}% | "
            f"{fmt(row['holdoutPrimaryGainPct'])}% | {fmt(row['holdoutLowLoadRouteLockGainPct'])}% | "
            f"{row['protectedFalseReleaseCount']} | {row['oversupportWorsenedCount']} | "
            f"{fmt(row['maxHoldoutRegression'])} | {fmt(row['utilityMarginVsNull'])} |"
        )
    lines.extend(
        [
            "",
            "## Low-Load Route-Lock Targets",
            "",
            "| Galaxy | Split | Baseline | Candidate | Gain | Active | Route |",
            "| --- | --- | ---: | ---: | ---: | --- | --- |",
        ]
    )
    for row in sorted([row for row in case_rows if row["lowloadRouteLockTarget"]], key=lambda item: -item["improvement"]):
        lines.append(
            f"| {row['name']} | {row['split']} | {fmt(row['baselineRmse'])} | {fmt(row['candidateRmse'])} | "
            f"{fmt(row['improvement'])} | {row['activeStretch']} | {row['candidateRoute']} |"
        )
    lines.extend(
        [
            "",
            "## Protected Ledger",
            "",
            "| Galaxy | Split | Class | Baseline | Candidate | Delta | Active | False release | Oversupport worsened |",
            "| --- | --- | --- | ---: | ---: | ---: | --- | --- | --- |",
        ]
    )
    for row in protected_rows:
        lines.append(
            f"| {row['name']} | {row['split']} | {row['failureClass'] or row['noGoClass']} | "
            f"{fmt(row['baselineRmse'])} | {fmt(row['candidateRmse'])} | {fmt(row['delta'])} | "
            f"{row['activeStretch']} | {row['protectedFalseRelease']} | {row['oversupportWorsened']} |"
        )
    lines.extend(
        [
            "",
            "## Null Controls",
            "",
            "| Control | Seed | Active | Low-load route-lock gain | False releases | Oversupport worsened | Max regression | Utility |",
            "| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
        ]
    )
    for row in null_rows[:60]:
        lines.append(
            f"| {row['controlType']} | {row['seed']} | {row['activeStretchCount']} | "
            f"{fmt(row['holdoutLowLoadRouteLockGainPct'])}% | {row['protectedFalseReleaseCount']} | "
            f"{row['oversupportWorsenedCount']} | {fmt(row['maxHoldoutRegression'])} | {fmt(row['trainUtility'])} |"
        )
    lines.extend(
        [
            "",
            "## Formula Discipline",
            "",
            "- Candidate formula changes memory length only: no q, Gamma0, disk M/L, bulge M/L, or scalar amplitude patch.",
            "- Candidate inputs are locked route and pre-residual MTS/profile state variables.",
            "- Galaxy names, raw residuals, raw RMSE, and weak/systematics cases are not formula inputs.",
            "- Route changes are tracked as boundary behavior; protected false releases and regressions remain guardrails.",
            "",
            f"Final verdict: **{capsule['verdict']}**.",
            "",
        ]
    )
    return "\n".join(lines)


def write_v21_memory_stretch_artifacts(out_dir: Path, curves: list[dict], holdout_fraction: float) -> dict:
    rows, facts = v21_build_rows(curves)
    split = v21_split_rows(rows, SPLIT_SEED, holdout_fraction)
    score_rows, case_rows, rule, beta = v21_candidate_grid(rows, split)
    best = score_rows[0]
    active_count = sum(1 for row in case_rows if row["activeStretch"] and row["lockedRoute"] == "low-load")
    null_rows = v21_random_null_rows(rows, split, rule, beta, count=active_count, seed=SPLIT_SEED + 61000)
    seed_rows, seed_null_rows, seed_case_rows, seed_score_rows = v21_seed_replay(rows, holdout_fraction)
    if seed_case_rows:
        case_rows = seed_case_rows
    if seed_score_rows:
        score_rows = seed_score_rows
        best = score_rows[0]
    null_rows = seed_null_rows or null_rows
    verdict, failures, decision_metrics = v21_verdict(seed_rows)
    protected_rows = sorted(
        [
            row
            for row in case_rows
            if row["protectedCase"] or row["oversupportCase"] or row["protectedFalseRelease"] or row["oversupportWorsened"]
        ],
        key=lambda row: (not row["protectedFalseRelease"], not row["oversupportWorsened"], -row["delta"], row["name"]),
    )
    formula = v21_formula_from_score(best)
    capsule = {
        "type": "mts-v21-memory-boundary-stretch-candidate",
        "version": 1,
        "generatedAt": "deterministic",
        "sourceScript": "scripts/mts-failure-lab.py",
        "canonicalMtsStatus": "locked baseline; v21 memory-stretch proposal branch only",
        "verdict": verdict,
        "guardrailFailures": failures,
        "decisionMetrics": decision_metrics,
        "bestFormula": formula,
        "facts": facts,
        "seeds": V19_SEEDS,
    }
    out_dir.mkdir(parents=True, exist_ok=True)
    write_csv(out_dir / "mts_v21_memory_stretch_candidate_scores.csv", score_rows)
    write_csv(out_dir / "mts_v21_memory_stretch_seed_replay.csv", seed_rows)
    write_csv(out_dir / "mts_v21_memory_stretch_case_ledger.csv", case_rows)
    write_csv(out_dir / "mts_v21_memory_stretch_protected_ledger.csv", protected_rows)
    write_csv(out_dir / "mts_v21_memory_stretch_null_controls.csv", null_rows)
    (out_dir / "mts_v21_memory_stretch_formula.json").write_text(json.dumps(json_clean(formula), indent=2), encoding="utf-8")
    report = v21_report(capsule, score_rows, seed_rows, case_rows, protected_rows, null_rows)
    (out_dir / "mts_v21_memory_stretch_report.md").write_text(report, encoding="utf-8")
    (out_dir / "mts_v21_memory_stretch_report.txt").write_text(report, encoding="utf-8")
    (out_dir / "mts_v21_memory_stretch_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2), encoding="utf-8")
    return capsule


V21_REVIEW_BETAS = [3.00, 3.50, 4.00, 4.50, 5.00]
V21_REVIEW_RULE_SPECS = [
    (("boundaryScore", "ge"), ("uOut", "ge")),
    (("boundaryScore", "ge"), ("u075", "ge")),
    (("memoryLoad", "ge"), ("uMax", "ge")),
]
V21_REVIEW_QUANTILES = [0.15, 0.25, 0.33, 0.50, 0.66, 0.75, 0.85, 0.90]
V21_REVIEW_NULL_ITERATIONS = 30


def v21_review_rule_family(rule: tuple[tuple[str, str, float], ...]) -> str:
    return "+".join(condition[0] for condition in rule)


def v21_review_threshold_values(rows: list[dict], names: set[str], key: str) -> list[float]:
    values = sorted(
        row[key]
        for row in rows
        if row["name"] in names and row["lockedRoute"] == "low-load" and math.isfinite(row.get(key, math.nan))
    )
    if not values:
        return [0.0]
    out = []
    for fraction in V21_REVIEW_QUANTILES:
        index = min(len(values) - 1, max(0, int(round((len(values) - 1) * fraction))))
        out.append(round(values[index], 6))
    return v19_unique_floats(out)


def v21_review_candidate_rules(rows: list[dict], train_names: set[str]) -> list[tuple[tuple[str, str, float], ...]]:
    rules: list[tuple[tuple[str, str, float], ...]] = []
    for (first, second) in V21_REVIEW_RULE_SPECS:
        first_key, first_direction = first
        second_key, second_direction = second
        for first_threshold in v21_review_threshold_values(rows, train_names, first_key):
            for second_threshold in v21_review_threshold_values(rows, train_names, second_key):
                rules.append(((first_key, first_direction, first_threshold), (second_key, second_direction, second_threshold)))
    seen = set()
    unique = []
    for rule in rules:
        if rule not in seen:
            seen.add(rule)
            unique.append(rule)
    return unique


def v21_review_train_utility(metrics: dict) -> float:
    max_train_regression = metrics["maxTrainRegression"] if math.isfinite(metrics["maxTrainRegression"]) else 0.0
    return (
        metrics["trainLowLoadRouteLockGainPct"]
        + 0.75 * metrics["trainPrimaryGainPct"]
        + 0.35 * metrics["trainCleanGainPct"]
        + 3.0 * metrics["trainLowLoadRouteLockRepairCount"]
        - 55.0 * metrics["trainProtectedFalseReleaseCount"]
        - 45.0 * metrics["trainOversupportWorsenedCount"]
        - 8.0 * max(0.0, max_train_regression - 8.0)
    )


def v21_review_candidate_score_row(
    rank: int,
    rule: tuple[tuple[str, str, float], ...],
    beta: float,
    metrics: dict,
) -> dict:
    record = v21_candidate_score_row(rank, rule, beta, metrics)
    record["formulaFamily"] = v21_review_rule_family(rule)
    record["reviewTrainUtility"] = v21_review_train_utility(metrics)
    return record


def v21_review_score_sort_key(row: dict) -> tuple:
    return (
        row["reviewTrainUtility"],
        row["trainLowLoadRouteLockGainPct"],
        row["trainPrimaryGainPct"],
        row["trainCleanGainPct"],
        -row["trainProtectedFalseReleaseCount"],
        -row["trainOversupportWorsenedCount"],
        -row["maxTrainRegression"] if math.isfinite(row["maxTrainRegression"]) else -999,
        row["candidateId"],
    )


def v21_review_candidate_grid(rows: list[dict], split: dict) -> tuple[list[dict], list[dict], tuple[tuple[str, str, float], ...], float]:
    score_rows = []
    ledgers: dict[str, list[dict]] = {}
    rules_by_id: dict[str, tuple[tuple[str, str, float], ...]] = {}
    rules = v21_review_candidate_rules(rows, split["trainNames"])
    for rule in rules:
        for beta in V21_REVIEW_BETAS:
            case_rows = v21_case_rows(rows, split, rule, beta, family=f"v21-review-{v21_review_rule_family(rule)}")
            metrics = v21_metric_summary(case_rows)
            record = v21_review_candidate_score_row(0, rule, beta, metrics)
            score_rows.append(record)
            ledgers[record["candidateId"]] = case_rows
            rules_by_id[record["candidateId"]] = rule
    score_rows.sort(key=v21_review_score_sort_key, reverse=True)
    for index, row in enumerate(score_rows, start=1):
        row["rank"] = index
    best = score_rows[0]
    return score_rows, ledgers[best["candidateId"]], rules_by_id[best["candidateId"]], best["beta"]


def v21_review_active_names_for_rule(rows: list[dict], rule: tuple[tuple[str, str, float], ...]) -> set[str]:
    return {row["name"] for row in rows if v21_rule_passes(row, rule)}


def v21_review_lowload_names(rows: list[dict]) -> list[str]:
    return sorted(row["name"] for row in rows if row["lockedRoute"] == "low-load")


def v21_review_control_metrics_row(
    rows: list[dict],
    split: dict,
    rule: tuple[tuple[str, str, float], ...],
    beta: float,
    active: set[str],
    *,
    seed: int,
    iteration: int,
    control_type: str,
    source_candidate_id: str,
) -> dict:
    case_rows = v21_case_rows(
        rows,
        split,
        rule,
        beta,
        active_override=active,
        candidate_id=f"{control_type}-{seed}-{iteration}",
        family=control_type,
    )
    metrics = v21_metric_summary(case_rows)
    return {
        "controlType": control_type,
        "seed": seed,
        "iteration": iteration,
        "sourceCandidateId": source_candidate_id,
        "ruleText": " and ".join(f"{key} {direction} {fmt(threshold)}" for key, direction, threshold in rule),
        "formulaFamily": v21_review_rule_family(rule),
        "beta": beta,
        "requestedActiveCount": len(active),
        "activeNames": ";".join(sorted(active)),
        **metrics,
    }


def v21_review_shuffled_gate_active_names(
    rows: list[dict],
    rule: tuple[tuple[str, str, float], ...],
    rng: random.Random,
) -> set[str]:
    lowload_rows = sorted([row for row in rows if row["lockedRoute"] == "low-load"], key=lambda item: item["name"])
    shuffled_values: dict[str, dict[str, float]] = {}
    for key, _direction, _threshold in rule:
        values = [row.get(key, math.nan) for row in lowload_rows]
        rng.shuffle(values)
        shuffled_values[key] = {row["name"]: values[index] for index, row in enumerate(lowload_rows)}
    active = set()
    for row in lowload_rows:
        fake = dict(row)
        for key in shuffled_values:
            fake[key] = shuffled_values[key][row["name"]]
        if all(v21_condition_passes(fake, condition) for condition in rule):
            active.add(row["name"])
    return active


def v21_review_rule_distance(row: dict, rule: tuple[tuple[str, str, float], ...], scales: dict[str, float]) -> float:
    distance = 0.0
    for key, direction, threshold in rule:
        value = row.get(key, math.nan)
        if not math.isfinite(value):
            return math.inf
        scale = max(scales.get(key, 1.0), 1e-9)
        if direction == "ge":
            distance += max(0.0, threshold - value) / scale
        else:
            distance += max(0.0, value - threshold) / scale
    return distance


def v21_review_protected_lookalike_active_names(
    rows: list[dict],
    rule: tuple[tuple[str, str, float], ...],
    count: int,
) -> set[str]:
    protected_lowload = [
        row
        for row in rows
        if row["lockedRoute"] == "low-load" and row["protectedCase"] and not row["lowloadRouteLockTarget"]
    ]
    lowload_rows = [row for row in rows if row["lockedRoute"] == "low-load"]
    scales = {}
    for key, _direction, _threshold in rule:
        values = [row.get(key, math.nan) for row in lowload_rows if math.isfinite(row.get(key, math.nan))]
        scales[key] = (max(values) - min(values)) if len(values) >= 2 else 1.0
    ordered = sorted(
        protected_lowload,
        key=lambda row: (v21_review_rule_distance(row, rule, scales), row["name"]),
    )
    return {row["name"] for row in ordered[: min(count, len(ordered))]}


def v21_review_null_control_rows(
    rows: list[dict],
    split: dict,
    rule: tuple[tuple[str, str, float], ...],
    beta: float,
    *,
    seed: int,
    source_candidate_id: str,
) -> list[dict]:
    rng = random.Random(seed)
    lowload_names = v21_review_lowload_names(rows)
    route_lock_names = sorted(
        row["name"]
        for row in rows
        if row["lockedRoute"] == "low-load" and row["lowloadRouteLockTarget"]
    )
    active_count = len(v21_review_active_names_for_rule(rows, rule))
    out = []

    for index in range(V21_REVIEW_NULL_ITERATIONS):
        active = set(rng.sample(lowload_names, min(active_count, len(lowload_names))))
        out.append(
            v21_review_control_metrics_row(
                rows,
                split,
                rule,
                beta,
                active,
                seed=seed,
                iteration=index,
                control_type="same-active-count-random-lowload-stretch-null",
                source_candidate_id=source_candidate_id,
            )
        )

    for index in range(V21_REVIEW_NULL_ITERATIONS):
        active = v21_review_shuffled_gate_active_names(rows, rule, rng)
        out.append(
            v21_review_control_metrics_row(
                rows,
                split,
                rule,
                beta,
                active,
                seed=seed,
                iteration=index,
                control_type="shuffled-state-gate-null",
                source_candidate_id=source_candidate_id,
            )
        )

    all_lowload = set(lowload_names)
    out.append(
        v21_review_control_metrics_row(
            rows,
            split,
            rule,
            beta,
            all_lowload,
            seed=seed,
            iteration=-1,
            control_type="all-low-load-stretch-control",
            source_candidate_id=source_candidate_id,
        )
    )

    for index in range(V21_REVIEW_NULL_ITERATIONS):
        active = set(rng.sample(route_lock_names, min(active_count, len(route_lock_names))))
        out.append(
            v21_review_control_metrics_row(
                rows,
                split,
                rule,
                beta,
                active,
                seed=seed,
                iteration=index,
                control_type="route-lock-only-random-stretch-control",
                source_candidate_id=source_candidate_id,
            )
        )

    lookalikes = v21_review_protected_lookalike_active_names(rows, rule, active_count)
    out.append(
        v21_review_control_metrics_row(
            rows,
            split,
            rule,
            beta,
            lookalikes,
            seed=seed,
            iteration=-1,
            control_type="protected-low-load-lookalike-stretch-control",
            source_candidate_id=source_candidate_id,
        )
    )
    return out


def v21_review_null_best(null_rows: list[dict], key: str) -> float:
    return max([row[key] for row in null_rows if math.isfinite(row.get(key, math.nan))] or [math.nan])


def v21_review_seed_replay(rows: list[dict], holdout_fraction: float) -> tuple[list[dict], list[dict], list[dict], list[dict], list[dict]]:
    seed_rows = []
    all_null_rows = []
    false_release_rows = []
    main_case_rows = []
    main_score_rows = []
    for seed in V19_SEEDS:
        split = v21_split_rows(rows, seed, holdout_fraction)
        score_rows, case_rows, rule, beta = v21_review_candidate_grid(rows, split)
        best = score_rows[0]
        null_rows = v21_review_null_control_rows(
            rows,
            split,
            rule,
            beta,
            seed=seed + 71000,
            source_candidate_id=best["candidateId"],
        )
        lowlock_null_best = v21_review_null_best(null_rows, "holdoutLowLoadRouteLockGainPct")
        primary_null_best = v21_review_null_best(null_rows, "holdoutPrimaryGainPct")
        clean_null_best = v21_review_null_best(null_rows, "holdoutCleanGainPct")
        protected_null_best = min([row["protectedFalseReleaseCount"] for row in null_rows] or [math.nan])
        seed_rows.append(
            {
                "seed": seed,
                "candidateId": best["candidateId"],
                "formulaFamily": best["formulaFamily"],
                "ruleText": best["ruleText"],
                "beta": beta,
                "trainUtility": best["trainUtility"],
                "reviewTrainUtility": best["reviewTrainUtility"],
                "holdoutCleanGainPct": best["holdoutCleanGainPct"],
                "holdoutPrimaryGainPct": best["holdoutPrimaryGainPct"],
                "holdoutLowLoadRouteLockGainPct": best["holdoutLowLoadRouteLockGainPct"],
                "holdoutLowLoadRouteLockRepairCount": best["holdoutLowLoadRouteLockRepairCount"],
                "protectedFalseReleaseCount": best["protectedFalseReleaseCount"],
                "protectedFalseReleaseAllowanceMargin": 1 - best["protectedFalseReleaseCount"],
                "oversupportWorsenedCount": best["oversupportWorsenedCount"],
                "maxHoldoutRegression": best["maxHoldoutRegression"],
                "activeStretchCount": best["activeStretchCount"],
                "activeProtectedCount": best["activeProtectedCount"],
                "routeChangeCount": best["routeChangeCount"],
                "weakSystematicsLeakage": best["weakSystematicsLeakage"],
                "lowLoadRouteLockGainNullBestPct": lowlock_null_best,
                "lowLoadRouteLockGainMarginPct": best["holdoutLowLoadRouteLockGainPct"] - lowlock_null_best if math.isfinite(lowlock_null_best) else math.nan,
                "cleanHighRmseGainNullBestPct": primary_null_best,
                "cleanHighRmseGainMarginPct": best["holdoutPrimaryGainPct"] - primary_null_best if math.isfinite(primary_null_best) else math.nan,
                "cleanGainNullBestPct": clean_null_best,
                "cleanGainMarginPct": best["holdoutCleanGainPct"] - clean_null_best if math.isfinite(clean_null_best) else math.nan,
                "bestNullProtectedFalseReleaseCount": protected_null_best,
            }
        )
        for row in case_rows:
            if row["protectedFalseRelease"]:
                copy = dict(row)
                copy["seed"] = seed
                copy["ruleText"] = best["ruleText"]
                copy["formulaFamily"] = best["formulaFamily"]
                false_release_rows.append(copy)
        all_null_rows.extend(null_rows)
        if seed == SPLIT_SEED:
            main_case_rows = case_rows
            main_score_rows = score_rows
    return seed_rows, all_null_rows, main_case_rows, main_score_rows, false_release_rows


def v21_review_false_release_ledger(rows: list[dict], false_release_rows: list[dict]) -> list[dict]:
    feature_rows = {row["name"]: row for row in rows}
    grouped: dict[str, dict] = {}
    for row in false_release_rows:
        group = grouped.setdefault(
            row["name"],
            {
                "name": row["name"],
                "recurrenceCount": 0,
                "falseReleaseSeeds": [],
                "formulaFamilies": set(),
                "rules": set(),
                "maxDelta": -math.inf,
                "maxRegression": -math.inf,
            },
        )
        group["recurrenceCount"] += 1
        group["falseReleaseSeeds"].append(str(row["seed"]))
        group["formulaFamilies"].add(row.get("formulaFamily", ""))
        group["rules"].add(row.get("ruleText", ""))
        group["maxDelta"] = max(group["maxDelta"], row["delta"])
        group["maxRegression"] = max(group["maxRegression"], row["delta"])

    if "F565-V2" in feature_rows and "F565-V2" not in grouped:
        grouped["F565-V2"] = {
            "name": "F565-V2",
            "recurrenceCount": 0,
            "falseReleaseSeeds": [],
            "formulaFamilies": set(),
            "rules": set(),
            "maxDelta": math.nan,
            "maxRegression": math.nan,
        }

    ledger = []
    for name, group in grouped.items():
        feature = feature_rows.get(name, {})
        ledger.append(
            {
                "name": name,
                "recurrenceCount": group["recurrenceCount"],
                "falseReleaseSeeds": ";".join(group["falseReleaseSeeds"]),
                "recurringAcrossMoreThan2Seeds": group["recurrenceCount"] > 2,
                "formulaFamilies": ";".join(sorted(group["formulaFamilies"])),
                "rules": " | ".join(sorted(group["rules"])),
                "maxDelta": group["maxDelta"],
                "lockedRoute": feature.get("lockedRoute", ""),
                "failureClass": feature.get("failureClass", ""),
                "noGoClass": feature.get("noGoClass", ""),
                "boundaryScore": feature.get("boundaryScore", math.nan),
                "memoryLoad": feature.get("memoryLoad", math.nan),
                "u075": feature.get("u075", math.nan),
                "uOut": feature.get("uOut", math.nan),
                "uMax": feature.get("uMax", math.nan),
                "routeMargin": feature.get("routeMargin", math.nan),
                "routeBreakRisk": feature.get("routeBreakRisk", math.nan),
                "fGasOut": feature.get("fGasOut", math.nan),
            }
        )
    ledger.sort(key=lambda row: (-row["recurrenceCount"], row["name"]))
    return ledger


def v21_review_family_counts(seed_rows: list[dict]) -> dict:
    counts: dict[str, int] = {}
    for row in seed_rows:
        counts[row["formulaFamily"]] = counts.get(row["formulaFamily"], 0) + 1
    return dict(sorted(counts.items()))


def v21_review_verdict(seed_rows: list[dict], false_release_ledger: list[dict]) -> tuple[str, list[str], dict]:
    family_counts = v21_review_family_counts(seed_rows)
    stable_family_count = max(family_counts.values() or [0])
    metrics = {
        "medianCleanHoldoutGainPct": safe_median(row["holdoutCleanGainPct"] for row in seed_rows),
        "medianCleanHighRmseHoldoutGainPct": safe_median(row["holdoutPrimaryGainPct"] for row in seed_rows),
        "medianLowLoadRouteLockHoldoutGainPct": safe_median(row["holdoutLowLoadRouteLockGainPct"] for row in seed_rows),
        "minLowLoadRouteLockGainMarginVsNullPct": min([row["lowLoadRouteLockGainMarginPct"] for row in seed_rows if math.isfinite(row["lowLoadRouteLockGainMarginPct"])] or [math.nan]),
        "medianLowLoadRouteLockGainMarginVsNullPct": safe_median(row["lowLoadRouteLockGainMarginPct"] for row in seed_rows),
        "medianCleanHighRmseGainMarginVsNullPct": safe_median(row["cleanHighRmseGainMarginPct"] for row in seed_rows),
        "maxProtectedFalseReleaseCount": max([row["protectedFalseReleaseCount"] for row in seed_rows] or [0]),
        "maxProtectedFalseReleaseRecurrence": max([row["recurrenceCount"] for row in false_release_ledger] or [0]),
        "maxOversupportWorsenedCount": max([row["oversupportWorsenedCount"] for row in seed_rows] or [0]),
        "maxHoldoutRegression": max([row["maxHoldoutRegression"] for row in seed_rows if math.isfinite(row["maxHoldoutRegression"])] or [math.nan]),
        "maxWeakSystematicsLeakage": max([row["weakSystematicsLeakage"] for row in seed_rows] or [0]),
        "formulaFamilyCounts": family_counts,
        "dominantFormulaFamilyCount": stable_family_count,
        "dominantFormulaFamily": max(family_counts, key=family_counts.get) if family_counts else "",
        "formulaFamilyStable": stable_family_count >= 5,
    }
    failures = []
    if metrics["medianCleanHoldoutGainPct"] < 8:
        failures.append("median clean holdout gain < 8%")
    if metrics["medianCleanHighRmseHoldoutGainPct"] < 10:
        failures.append("median clean high-RMSE holdout gain < 10%")
    if metrics["medianLowLoadRouteLockHoldoutGainPct"] < 30:
        failures.append("median low-load route-lock holdout gain < 30%")
    if metrics["maxProtectedFalseReleaseCount"] > 1:
        failures.append("protected false releases > 1 in at least one seed")
    if metrics["maxProtectedFalseReleaseRecurrence"] > 2:
        failures.append("recurring protected false release across more than 2 seeds")
    if metrics["maxOversupportWorsenedCount"] > 0:
        failures.append("low-load oversupport cases worsen")
    if math.isfinite(metrics["maxHoldoutRegression"]) and metrics["maxHoldoutRegression"] > 8:
        failures.append("max holdout regression > 8 km/s")
    if not math.isfinite(metrics["minLowLoadRouteLockGainMarginVsNullPct"]) or metrics["minLowLoadRouteLockGainMarginVsNullPct"] < 10:
        failures.append("candidate does not beat every low-load random/stretch null by 10 points on low-load route-lock gain")
    if metrics["maxWeakSystematicsLeakage"] != 0:
        failures.append("weak/systematics leakage")
    if not metrics["formulaFamilyStable"]:
        failures.append("formula family not stable across seed replay")

    if not failures:
        verdict = "MTS v21 candidate promoted for review"
    elif metrics["maxProtectedFalseReleaseCount"] > 1 or metrics["maxProtectedFalseReleaseRecurrence"] > 2 or metrics["maxOversupportWorsenedCount"] > 0:
        verdict = "protected-case failure"
    elif "candidate does not beat every low-load random/stretch null by 10 points on low-load route-lock gain" in failures:
        verdict = "not above null"
    elif metrics["medianLowLoadRouteLockHoldoutGainPct"] >= 30 or not metrics["formulaFamilyStable"]:
        verdict = "promising but not stable"
    else:
        verdict = "state-transfer idea rejected"
    return verdict, failures, metrics


def v21_review_formula_from_score(best: dict, seed_rows: list[dict], verdict: str) -> dict:
    return {
        "candidateId": best["candidateId"],
        "reviewStatus": verdict,
        "mechanism": "low-load memory-boundary stretch",
        "formulaText": "If lockedRoute == low-load and the frozen state gate passes, L_eff_candidate = L_exact * (1 + beta); otherwise L_eff_candidate = L_exact.",
        "ruleText": best["ruleText"],
        "formulaFamily": best["formulaFamily"],
        "beta": best["beta"],
        "betaGrid": V21_REVIEW_BETAS,
        "familiesHardened": [f"{first[0]}+{second[0]}" for first, second in V21_REVIEW_RULE_SPECS],
        "seedReplayFamilyCounts": v21_review_family_counts(seed_rows),
        "q": Q_DEFAULT,
        "gamma0": GAMMA0,
        "mlDisk": ML_DISK,
        "mlBulge": ML_BULGE,
        "allowedInputs": ["locked route", "boundaryScore", "memoryLoad", "u_0.75", "u_out", "u_max"],
        "forbiddenInputs": ["galaxy name", "raw residuals", "raw RMSE as formula input", "q changes", "amplitude patches", "weak/systematics fitting"],
    }


def v21_review_report(
    capsule: dict,
    score_rows: list[dict],
    seed_rows: list[dict],
    case_rows: list[dict],
    false_release_ledger: list[dict],
    null_rows: list[dict],
) -> str:
    best = score_rows[0]
    metrics = capsule["decisionMetrics"]
    null_by_type: dict[str, list[dict]] = {}
    for row in null_rows:
        null_by_type.setdefault(row["controlType"], []).append(row)
    lines = [
        "# MTS v21 Memory-Stretch Review v2",
        "",
        "This is a hardening review for the frozen v21 low-load memory-boundary stretch candidate. Canonical MTS remains locked.",
        "",
        "## Headline",
        "",
        f"Verdict: **{capsule['verdict']}**.",
        f"Main split best candidate: `{best['candidateId']}`.",
        f"Rule: `{best['ruleText']}`; beta: `{fmt(best['beta'])}`; family: `{best['formulaFamily']}`.",
        f"Weak/systematics leakage: `{capsule['facts']['weakHoldoutLeakage']}`.",
        "",
        "## Acceptance Gate Status",
        "",
        "| Gate | Value |",
        "| --- | ---: |",
        f"| Median clean holdout gain | {fmt(metrics['medianCleanHoldoutGainPct'])}% |",
        f"| Median clean high-RMSE holdout gain | {fmt(metrics['medianCleanHighRmseHoldoutGainPct'])}% |",
        f"| Median low-load route-lock holdout gain | {fmt(metrics['medianLowLoadRouteLockHoldoutGainPct'])}% |",
        f"| Min low-load route-lock gain margin vs null | {fmt(metrics['minLowLoadRouteLockGainMarginVsNullPct'])} points |",
        f"| Median clean high-RMSE gain margin vs null | {fmt(metrics['medianCleanHighRmseGainMarginVsNullPct'])} points |",
        f"| Max protected false releases in any seed | {metrics['maxProtectedFalseReleaseCount']} |",
        f"| Max protected false-release recurrence | {metrics['maxProtectedFalseReleaseRecurrence']} seeds |",
        f"| Max oversupport worsened count | {metrics['maxOversupportWorsenedCount']} |",
        f"| Max holdout regression | {fmt(metrics['maxHoldoutRegression'])} km/s |",
        f"| Dominant formula family | {metrics['dominantFormulaFamily']} ({metrics['dominantFormulaFamilyCount']}/{len(seed_rows)}) |",
        "",
        "## Guardrail Failures",
        "",
    ]
    lines.extend([f"- {failure}" for failure in capsule["guardrailFailures"]] or ["- none"])
    lines.extend(
        [
            "",
            "## Hardened Candidate Families",
            "",
            "| Family | Seed wins |",
            "| --- | ---: |",
        ]
    )
    for family, count in metrics["formulaFamilyCounts"].items():
        lines.append(f"| {family} | {count} |")
    lines.extend(
        [
            "",
            "## Main-Split Candidate Scores",
            "",
            "| Rank | Family | Rule | beta | Train utility | Clean gain | High-RMSE gain | Low-load route-lock gain | False releases | Max regression |",
            "| ---: | --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
        ]
    )
    for row in score_rows[:25]:
        lines.append(
            f"| {row['rank']} | {row['formulaFamily']} | {row['ruleText']} | {fmt(row['beta'])} | "
            f"{fmt(row['reviewTrainUtility'])} | {fmt(row['holdoutCleanGainPct'])}% | "
            f"{fmt(row['holdoutPrimaryGainPct'])}% | {fmt(row['holdoutLowLoadRouteLockGainPct'])}% | "
            f"{row['protectedFalseReleaseCount']} | {fmt(row['maxHoldoutRegression'])} |"
        )
    lines.extend(
        [
            "",
            "## Seed Replay",
            "",
            "| Seed | Family | Rule | beta | Clean gain | High-RMSE gain | Low-load route-lock gain | Null margin | False releases | Max regression |",
            "| ---: | --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
        ]
    )
    for row in seed_rows:
        lines.append(
            f"| {row['seed']} | {row['formulaFamily']} | {row['ruleText']} | {fmt(row['beta'])} | "
            f"{fmt(row['holdoutCleanGainPct'])}% | {fmt(row['holdoutPrimaryGainPct'])}% | "
            f"{fmt(row['holdoutLowLoadRouteLockGainPct'])}% | {fmt(row['lowLoadRouteLockGainMarginPct'])} | "
            f"{row['protectedFalseReleaseCount']} | {fmt(row['maxHoldoutRegression'])} |"
        )
    lines.extend(
        [
            "",
            "## Null Controls",
            "",
            "| Control | Rows | Best low-load route-lock gain | Best clean high-RMSE gain | Min false releases | Max regression |",
            "| --- | ---: | ---: | ---: | ---: | ---: |",
        ]
    )
    for control_type, grouped in sorted(null_by_type.items()):
        lines.append(
            f"| {control_type} | {len(grouped)} | "
            f"{fmt(v21_review_null_best(grouped, 'holdoutLowLoadRouteLockGainPct'))}% | "
            f"{fmt(v21_review_null_best(grouped, 'holdoutPrimaryGainPct'))}% | "
            f"{min([row['protectedFalseReleaseCount'] for row in grouped] or [0])} | "
            f"{fmt(max([row['maxHoldoutRegression'] for row in grouped if math.isfinite(row['maxHoldoutRegression'])] or [math.nan]))} |"
        )
    lines.extend(
        [
            "",
            "## Protected False-Release Ledger",
            "",
            "| Galaxy | Recurrence | Seeds | Family | Max delta | State notes |",
            "| --- | ---: | --- | --- | ---: | --- |",
        ]
    )
    if false_release_ledger:
        for row in false_release_ledger:
            lines.append(
                f"| {row['name']} | {row['recurrenceCount']} | {row['falseReleaseSeeds']} | "
                f"{row['formulaFamilies']} | {fmt(row['maxDelta'])} | "
                f"u_out={fmt(row['uOut'])}, u_max={fmt(row['uMax'])}, B={fmt(row['boundaryScore'])} |"
            )
    else:
        lines.append("| none | 0 |  |  |  |  |")
    lines.extend(
        [
            "",
            "## Low-Load Route-Lock Holdout Ledger",
            "",
            "| Galaxy | Split | Baseline | Candidate | Gain | Active | Route |",
            "| --- | --- | ---: | ---: | ---: | --- | --- |",
        ]
    )
    for row in sorted([row for row in case_rows if row["lowloadRouteLockTarget"]], key=lambda item: (-item["improvement"], item["name"])):
        lines.append(
            f"| {row['name']} | {row['split']} | {fmt(row['baselineRmse'])} | {fmt(row['candidateRmse'])} | "
            f"{fmt(row['improvement'])} | {row['activeStretch']} | {row['candidateRoute']} |"
        )
    lines.extend(
        [
            "",
            "## Formula Discipline",
            "",
            "- Mechanism is memory length stretch only: `L_eff_candidate = L_exact * (1 + beta)` inside the state gate.",
            "- `q`, `Gamma0`, disk M/L, bulge M/L, and scalar support amplitude are unchanged.",
            "- Candidate ranking uses train-only state thresholds; holdout rows are validation only.",
            "- Weak/systematics galaxies remain excluded from fitting and framework-facing claims.",
            "- Galaxy names, residual lookup, and raw RMSE are not candidate inputs.",
            "",
            f"Final verdict: **{capsule['verdict']}**.",
            "",
        ]
    )
    return "\n".join(lines)


def write_v21_review_artifacts(out_dir: Path, curves: list[dict], holdout_fraction: float) -> dict:
    rows, facts = v21_build_rows(curves)
    split = v21_split_rows(rows, SPLIT_SEED, holdout_fraction)
    score_rows, case_rows, _rule, _beta = v21_review_candidate_grid(rows, split)
    seed_rows, null_rows, seed_case_rows, seed_score_rows, false_release_rows = v21_review_seed_replay(rows, holdout_fraction)
    if seed_case_rows:
        case_rows = seed_case_rows
    if seed_score_rows:
        score_rows = seed_score_rows
    false_release_ledger = v21_review_false_release_ledger(rows, false_release_rows)
    verdict, failures, decision_metrics = v21_review_verdict(seed_rows, false_release_ledger)
    best = score_rows[0]
    formula = v21_review_formula_from_score(best, seed_rows, verdict)
    capsule = {
        "type": "mts-v21-memory-stretch-review-v2",
        "version": 2,
        "generatedAt": "deterministic",
        "sourceScript": "scripts/mts-failure-lab.py",
        "canonicalMtsStatus": "locked baseline; v21 review branch only",
        "verdict": verdict,
        "guardrailFailures": failures,
        "decisionMetrics": decision_metrics,
        "bestFormula": formula,
        "facts": facts,
        "seeds": V19_SEEDS,
        "nullControls": [
            "same-active-count-random-lowload-stretch-null",
            "shuffled-state-gate-null",
            "all-low-load-stretch-control",
            "route-lock-only-random-stretch-control",
            "protected-low-load-lookalike-stretch-control",
        ],
    }
    out_dir.mkdir(parents=True, exist_ok=True)
    write_csv(out_dir / "mts_v21_review_candidate_scores.csv", score_rows)
    write_csv(out_dir / "mts_v21_review_seed_replay.csv", seed_rows)
    write_csv(out_dir / "mts_v21_review_case_ledger.csv", case_rows)
    write_csv(out_dir / "mts_v21_review_protected_false_release_ledger.csv", false_release_ledger)
    write_csv(out_dir / "mts_v21_review_null_controls.csv", null_rows)
    (out_dir / "mts_v21_review_formula.json").write_text(json.dumps(json_clean(formula), indent=2), encoding="utf-8")
    report = v21_review_report(capsule, score_rows, seed_rows, case_rows, false_release_ledger, null_rows)
    (out_dir / "mts_v21_review_report.md").write_text(report, encoding="utf-8")
    (out_dir / "mts_v21_review_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2), encoding="utf-8")
    return capsule


V21_LAW_GATE_STYLES = ["hard", "hinge", "logistic"]
V21_LAW_WIDTH_SCALES = [0.25, 0.50]
V21_LAW_ACTIVE_EPSILON = 0.05
V21_LAW_PROMOTABLE_NULL_TYPES = {
    "same-active-count-random-lowload-stretch-null",
    "shuffled-state-gate-null",
    "protected-low-load-lookalike-stress-control",
}


def v21_law_feature_span(rows: list[dict], train_names: set[str], key: str) -> float:
    values = [
        row.get(key, math.nan)
        for row in rows
        if row["name"] in train_names and row["lockedRoute"] == "low-load" and math.isfinite(row.get(key, math.nan))
    ]
    if len(values) < 2:
        return 1.0
    span = max(values) - min(values)
    return span if span > 1e-9 else max(1.0, abs(values[0]))


def v21_law_candidate_id(candidate: dict) -> str:
    pieces = []
    for key, direction, threshold in candidate["rule"]:
        pieces.append(f"{key}{direction}{fmt_num(threshold)}")
    width = "" if candidate["gateStyle"] == "hard" else f"-w{fmt_num(candidate['widthScale'])}"
    return (
        f"v21-law-{candidate['gateStyle']}-"
        + "-and-".join(pieces)
        + f"-b{fmt_num(candidate['beta'])}{width}"
    ).replace(".", "p")


def v21_law_candidate_rules(rows: list[dict], train_names: set[str]) -> list[dict]:
    candidates = []
    for rule in v21_review_candidate_rules(rows, train_names):
        spans = {key: v21_law_feature_span(rows, train_names, key) for key, _direction, _threshold in rule}
        for beta in V21_REVIEW_BETAS:
            hard = {
                "rule": rule,
                "beta": beta,
                "gateStyle": "hard",
                "widthScale": math.nan,
                "widths": {},
                "formulaFamily": v21_review_rule_family(rule),
            }
            hard["candidateId"] = v21_law_candidate_id(hard)
            candidates.append(hard)
            for style in ["hinge", "logistic"]:
                for width_scale in V21_LAW_WIDTH_SCALES:
                    item = {
                        "rule": rule,
                        "beta": beta,
                        "gateStyle": style,
                        "widthScale": width_scale,
                        "widths": {
                            key: max(1e-9, spans[key] * width_scale)
                            for key, _direction, _threshold in rule
                        },
                        "formulaFamily": v21_review_rule_family(rule),
                    }
                    item["candidateId"] = v21_law_candidate_id(item)
                    candidates.append(item)
    seen = set()
    unique = []
    for candidate in candidates:
        if candidate["candidateId"] not in seen:
            seen.add(candidate["candidateId"])
            unique.append(candidate)
    return unique


def v21_law_condition_activation(row: dict, candidate: dict, condition: tuple[str, str, float]) -> float:
    key, direction, threshold = condition
    value = row.get(key, math.nan)
    if not math.isfinite(value):
        return 0.0
    if candidate["gateStyle"] == "hard":
        return 1.0 if v21_condition_passes(row, condition) else 0.0
    width = max(1e-9, candidate["widths"].get(key, 1.0))
    signed = (value - threshold) / width if direction == "ge" else (threshold - value) / width
    if candidate["gateStyle"] == "hinge":
        return clamp(signed, 0.0, 1.0)
    logistic = 1.0 / (1.0 + math.exp(-clamp(signed, -60.0, 60.0)))
    return clamp((logistic - 0.5) / 0.5, 0.0, 1.0)


def v21_law_activation(row: dict, candidate: dict) -> float:
    if row["lockedRoute"] != "low-load":
        return 0.0
    activations = [v21_law_condition_activation(row, candidate, condition) for condition in candidate["rule"]]
    return min(activations) if activations else 0.0


def v21_law_score_for_row(row: dict, beta: float, activation: float, score_cache: dict[tuple[str, float], dict]) -> dict:
    activation = clamp(activation, 0.0, 1.0)
    if activation < 1e-12:
        return row["baseline"]
    beta_activation = round(beta * activation, 8)
    cache_key = (row["name"], beta_activation)
    if cache_key not in score_cache:
        score_cache[cache_key] = score_curve_with_leff_value(row["curve"], row["lExact"] * (1.0 + beta_activation))
    return score_cache[cache_key]


def v21_law_case_rows(
    rows: list[dict],
    split: dict,
    candidate: dict,
    *,
    activation_override: dict[str, float] | None = None,
    candidate_id: str | None = None,
    family: str | None = None,
    score_cache: dict[tuple[str, float], dict] | None = None,
) -> list[dict]:
    score_cache = score_cache if score_cache is not None else {}
    candidate_id = candidate_id or candidate["candidateId"]
    family = family or f"v21-law-{candidate['gateStyle']}-{candidate['formulaFamily']}"
    out = []
    for row in rows:
        activation = activation_override.get(row["name"], 0.0) if activation_override is not None else v21_law_activation(row, candidate)
        if row["lockedRoute"] != "low-load":
            activation = 0.0
        score = v21_law_score_for_row(row, candidate["beta"], activation, score_cache)
        baseline = row["baseline"]
        delta = score["rmse"] - baseline["rmse"]
        active = activation >= V21_LAW_ACTIVE_EPSILON
        out.append(
            {
                "candidateFamily": family,
                "candidateId": candidate_id,
                "name": row["name"],
                "split": "holdout" if row["name"] in split["holdoutNames"] else "train",
                "failureClass": row["failureClass"],
                "noGoClass": row["noGoClass"],
                "lockedRoute": row["lockedRoute"],
                "candidateRoute": score["candidateRoute"],
                "oldRoutePreserved": score["candidateRoute"] == row["lockedRoute"],
                "weakHoldoutExcluded": row["weakHoldoutExcluded"],
                "primaryCase": row["primaryCase"],
                "lowloadRouteLockTarget": row["lowloadRouteLockTarget"],
                "protectedCase": row["protectedCase"] and not row["lowloadRouteLockTarget"],
                "oversupportCase": row["oversupportCase"],
                "baselineRmse": baseline["rmse"],
                "candidateRmse": score["rmse"],
                "delta": delta,
                "improvement": baseline["rmse"] - score["rmse"],
                "improvementPct": pct_improvement(baseline["rmse"], score["rmse"]),
                "activeStretch": active,
                "activation": activation,
                "beta": candidate["beta"],
                "effectiveBeta": candidate["beta"] * activation,
                "gateStyle": candidate["gateStyle"],
                "formulaFamily": candidate["formulaFamily"],
                "ruleText": v21_law_rule_text(candidate),
                "leffExact": row["lExact"],
                "leffCandidate": score.get("candidateLeff", row["lExact"]),
                "leffStretchFactor": (score.get("candidateLeff", row["lExact"]) / row["lExact"]) if row["lExact"] else math.nan,
                "boundaryScore": row["boundaryScore"],
                "memoryLoad": row["memoryLoad"],
                "u075": row["u075"],
                "uOut": row["uOut"],
                "uMax": row["uMax"],
                "routeMargin": row["routeMargin"],
                "routeBreakRisk": row["routeBreakRisk"],
                "hOverRout": row["hOverRout"],
                "fGasOut": row["fGasOut"],
                "lGap": row["lGap"],
                "protectedFalseRelease": active and row["protectedCase"] and not row["lowloadRouteLockTarget"] and delta > 2.0,
                "oversupportWorsened": row["oversupportCase"] and delta > 0.0,
                "regressionOver2": delta > 2.0,
                "regressionOver8": delta > 8.0,
            }
        )
    return out


def v21_law_rule_text(candidate: dict) -> str:
    condition_text = " and ".join(f"{key} {direction} {fmt(threshold)}" for key, direction, threshold in candidate["rule"])
    if candidate["gateStyle"] == "hard":
        return condition_text
    return f"{candidate['gateStyle']}({condition_text}; widthScale {fmt(candidate['widthScale'])})"


def v21_law_activation_map(case_rows: list[dict]) -> dict[str, float]:
    return {
        row["name"]: row["activation"]
        for row in case_rows
        if row["lockedRoute"] == "low-load" and row.get("activation", 0.0) >= V21_LAW_ACTIVE_EPSILON
    }


def v21_law_target_recall(case_rows: list[dict], split_name: str | None = None) -> float:
    targets = [
        row
        for row in case_rows
        if row["lowloadRouteLockTarget"] and (split_name is None or row["split"] == split_name)
    ]
    if not targets:
        return math.nan
    active = sum(1 for row in targets if row["activeStretch"])
    return active / len(targets)


def v21_law_metric_summary(case_rows: list[dict]) -> dict:
    metrics = v21_metric_summary(case_rows)
    metrics.update(
        {
            "trainRouteLockRecall": v21_law_target_recall(case_rows, "train"),
            "holdoutRouteLockRecall": v21_law_target_recall(case_rows, "holdout"),
            "allRouteLockRecall": v21_law_target_recall(case_rows, None),
            "activeLowLoadRouteLockCount": sum(1 for row in case_rows if row["lowloadRouteLockTarget"] and row["activeStretch"]),
            "activeLowLoadProtectedCount": sum(1 for row in case_rows if row["protectedCase"] and row["lockedRoute"] == "low-load" and row["activeStretch"]),
            "meanActiveActivation": safe_mean(row["activation"] for row in case_rows if row["activeStretch"]),
        }
    )
    return metrics


def v21_law_train_utility(metrics: dict) -> float:
    max_train_regression = metrics["maxTrainRegression"] if math.isfinite(metrics["maxTrainRegression"]) else 0.0
    recall = metrics["trainRouteLockRecall"] if math.isfinite(metrics["trainRouteLockRecall"]) else 0.0
    return (
        metrics["trainLowLoadRouteLockGainPct"]
        + 0.65 * metrics["trainPrimaryGainPct"]
        + 0.30 * metrics["trainCleanGainPct"]
        + 18.0 * recall
        - 60.0 * metrics["trainProtectedFalseReleaseCount"]
        - 45.0 * metrics["trainOversupportWorsenedCount"]
        - 8.0 * max(0.0, max_train_regression - 8.0)
    )


def v21_law_score_row(rank: int, candidate: dict, metrics: dict) -> dict:
    return {
        "rank": rank,
        "candidateId": candidate["candidateId"],
        "formulaFamily": candidate["formulaFamily"],
        "gateStyle": candidate["gateStyle"],
        "ruleText": v21_law_rule_text(candidate),
        "beta": candidate["beta"],
        "widthScale": candidate["widthScale"],
        "lawTrainUtility": v21_law_train_utility(metrics),
        **metrics,
    }


def v21_law_score_sort_key(row: dict) -> tuple:
    return (
        row["lawTrainUtility"],
        row["trainLowLoadRouteLockGainPct"],
        row["trainRouteLockRecall"] if math.isfinite(row["trainRouteLockRecall"]) else 0.0,
        row["trainPrimaryGainPct"],
        -row["trainProtectedFalseReleaseCount"],
        -row["trainOversupportWorsenedCount"],
        -row["maxTrainRegression"] if math.isfinite(row["maxTrainRegression"]) else -999.0,
        row["candidateId"],
    )


def v21_law_candidate_grid(rows: list[dict], split: dict) -> tuple[list[dict], list[dict], dict]:
    score_rows = []
    ledgers: dict[str, list[dict]] = {}
    candidates_by_id: dict[str, dict] = {}
    score_cache: dict[tuple[str, float], dict] = {}
    for candidate in v21_law_candidate_rules(rows, split["trainNames"]):
        case_rows = v21_law_case_rows(rows, split, candidate, score_cache=score_cache)
        metrics = v21_law_metric_summary(case_rows)
        record = v21_law_score_row(0, candidate, metrics)
        score_rows.append(record)
        ledgers[candidate["candidateId"]] = case_rows
        candidates_by_id[candidate["candidateId"]] = candidate
    score_rows.sort(key=v21_law_score_sort_key, reverse=True)
    for index, row in enumerate(score_rows, start=1):
        row["rank"] = index
    best = score_rows[0]
    return score_rows, ledgers[best["candidateId"]], candidates_by_id[best["candidateId"]]


def v21_law_assign_activation_values(names: list[str], values: list[float]) -> dict[str, float]:
    ordered_names = sorted(names)
    ordered_values = sorted(values, reverse=True)
    return {
        name: ordered_values[index]
        for index, name in enumerate(ordered_names[: len(ordered_values)])
    }


def v21_law_shuffled_activation_map(rows: list[dict], candidate: dict, rng: random.Random) -> dict[str, float]:
    lowload_rows = sorted([row for row in rows if row["lockedRoute"] == "low-load"], key=lambda item: item["name"])
    shuffled_values: dict[str, dict[str, float]] = {}
    for key, _direction, _threshold in candidate["rule"]:
        values = [row.get(key, math.nan) for row in lowload_rows]
        rng.shuffle(values)
        shuffled_values[key] = {row["name"]: values[index] for index, row in enumerate(lowload_rows)}
    out = {}
    for row in lowload_rows:
        fake = dict(row)
        for key in shuffled_values:
            fake[key] = shuffled_values[key][row["name"]]
        activation = v21_law_activation(fake, candidate)
        if activation >= V21_LAW_ACTIVE_EPSILON:
            out[row["name"]] = activation
    return out


def v21_law_control_metrics_row(
    rows: list[dict],
    split: dict,
    candidate: dict,
    activation_override: dict[str, float],
    *,
    seed: int,
    iteration: int,
    control_type: str,
    source_candidate_id: str,
    score_cache: dict[tuple[str, float], dict],
) -> dict:
    case_rows = v21_law_case_rows(
        rows,
        split,
        candidate,
        activation_override=activation_override,
        candidate_id=f"{control_type}-{seed}-{iteration}",
        family=control_type,
        score_cache=score_cache,
    )
    metrics = v21_law_metric_summary(case_rows)
    return {
        "controlType": control_type,
        "seed": seed,
        "iteration": iteration,
        "sourceCandidateId": source_candidate_id,
        "formulaFamily": candidate["formulaFamily"],
        "gateStyle": candidate["gateStyle"],
        "ruleText": v21_law_rule_text(candidate),
        "beta": candidate["beta"],
        "requestedActiveCount": len(activation_override),
        "activeNames": ";".join(sorted(activation_override)),
        **metrics,
    }


def v21_law_null_control_rows(
    rows: list[dict],
    split: dict,
    candidate: dict,
    candidate_case_rows: list[dict],
    *,
    seed: int,
) -> tuple[list[dict], dict]:
    rng = random.Random(seed)
    score_cache: dict[tuple[str, float], dict] = {}
    lowload_names = v21_review_lowload_names(rows)
    activation_map = v21_law_activation_map(candidate_case_rows)
    active_values = sorted(activation_map.values(), reverse=True)
    active_count = len(active_values)
    out = []

    for index in range(V21_REVIEW_NULL_ITERATIONS):
        sampled = rng.sample(lowload_names, min(active_count, len(lowload_names)))
        override = v21_law_assign_activation_values(sampled, active_values)
        out.append(
            v21_law_control_metrics_row(
                rows,
                split,
                candidate,
                override,
                seed=seed,
                iteration=index,
                control_type="same-active-count-random-lowload-stretch-null",
                source_candidate_id=candidate["candidateId"],
                score_cache=score_cache,
            )
        )

    for index in range(V21_REVIEW_NULL_ITERATIONS):
        override = v21_law_shuffled_activation_map(rows, candidate, rng)
        out.append(
            v21_law_control_metrics_row(
                rows,
                split,
                candidate,
                override,
                seed=seed,
                iteration=index,
                control_type="shuffled-state-gate-null",
                source_candidate_id=candidate["candidateId"],
                score_cache=score_cache,
            )
        )

    all_lowload = {name: 1.0 for name in lowload_names}
    out.append(
        v21_law_control_metrics_row(
            rows,
            split,
            candidate,
            all_lowload,
            seed=seed,
            iteration=-1,
            control_type="all-low-load-stretch-control",
            source_candidate_id=candidate["candidateId"],
            score_cache=score_cache,
        )
    )

    lookalike_names = v21_review_protected_lookalike_active_names(rows, candidate["rule"], active_count)
    lookalike_override = v21_law_assign_activation_values(sorted(lookalike_names), active_values)
    out.append(
        v21_law_control_metrics_row(
            rows,
            split,
            candidate,
            lookalike_override,
            seed=seed,
            iteration=-1,
            control_type="protected-low-load-lookalike-stress-control",
            source_candidate_id=candidate["candidateId"],
            score_cache=score_cache,
        )
    )

    oracle_override = {
        row["name"]: 1.0
        for row in rows
        if row["lockedRoute"] == "low-load" and row["lowloadRouteLockTarget"]
    }
    oracle_case_rows = v21_law_case_rows(
        rows,
        split,
        candidate,
        activation_override=oracle_override,
        candidate_id=f"forbidden-route-lock-oracle-ceiling-{seed}",
        family="forbidden-route-lock-oracle-ceiling",
        score_cache=score_cache,
    )
    oracle_metrics = v21_law_metric_summary(oracle_case_rows)
    oracle_record = {
        "controlType": "forbidden-route-lock-oracle-ceiling",
        "seed": seed,
        "iteration": -1,
        "sourceCandidateId": candidate["candidateId"],
        "formulaFamily": candidate["formulaFamily"],
        "gateStyle": candidate["gateStyle"],
        "ruleText": "FORBIDDEN: route-lock target labels activate memory stretch",
        "beta": candidate["beta"],
        "requestedActiveCount": len(oracle_override),
        "activeNames": ";".join(sorted(oracle_override)),
        **oracle_metrics,
    }
    return out, oracle_record


def v21_law_best_allowed_null(null_rows: list[dict], key: str) -> float:
    return max(
        [
            row[key]
            for row in null_rows
            if row["controlType"] in V21_LAW_PROMOTABLE_NULL_TYPES and math.isfinite(row.get(key, math.nan))
        ]
        or [math.nan]
    )


def v21_law_oracle_recovery(candidate_gain: float, oracle_gain: float) -> float:
    if not math.isfinite(candidate_gain) or not math.isfinite(oracle_gain) or oracle_gain <= 0:
        return math.nan
    return 100.0 * candidate_gain / oracle_gain


def v21_law_seed_replay(rows: list[dict], holdout_fraction: float) -> tuple[list[dict], list[dict], list[dict], list[dict], list[dict], list[dict]]:
    seed_rows = []
    null_rows_all = []
    oracle_rows = []
    false_release_rows = []
    main_case_rows = []
    main_score_rows = []
    for seed in V19_SEEDS:
        split = v21_split_rows(rows, seed, holdout_fraction)
        score_rows, case_rows, candidate = v21_law_candidate_grid(rows, split)
        best = score_rows[0]
        null_rows, oracle_row = v21_law_null_control_rows(
            rows,
            split,
            candidate,
            case_rows,
            seed=seed + 81000,
        )
        allowed_lowlock_best = v21_law_best_allowed_null(null_rows, "holdoutLowLoadRouteLockGainPct")
        allowed_primary_best = v21_law_best_allowed_null(null_rows, "holdoutPrimaryGainPct")
        allowed_clean_best = v21_law_best_allowed_null(null_rows, "holdoutCleanGainPct")
        oracle_recovery = v21_law_oracle_recovery(
            best["holdoutLowLoadRouteLockGainPct"],
            oracle_row["holdoutLowLoadRouteLockGainPct"],
        )
        seed_rows.append(
            {
                "seed": seed,
                "candidateId": best["candidateId"],
                "formulaFamily": best["formulaFamily"],
                "gateStyle": best["gateStyle"],
                "ruleText": best["ruleText"],
                "beta": best["beta"],
                "widthScale": best["widthScale"],
                "lawTrainUtility": best["lawTrainUtility"],
                "holdoutCleanGainPct": best["holdoutCleanGainPct"],
                "holdoutPrimaryGainPct": best["holdoutPrimaryGainPct"],
                "holdoutLowLoadRouteLockGainPct": best["holdoutLowLoadRouteLockGainPct"],
                "holdoutRouteLockRecall": best["holdoutRouteLockRecall"],
                "protectedFalseReleaseCount": best["protectedFalseReleaseCount"],
                "oversupportWorsenedCount": best["oversupportWorsenedCount"],
                "maxHoldoutRegression": best["maxHoldoutRegression"],
                "activeStretchCount": best["activeStretchCount"],
                "activeLowLoadRouteLockCount": best["activeLowLoadRouteLockCount"],
                "activeLowLoadProtectedCount": best["activeLowLoadProtectedCount"],
                "weakSystematicsLeakage": best["weakSystematicsLeakage"],
                "allowedNullLowLoadRouteLockGainBestPct": allowed_lowlock_best,
                "allowedNullLowLoadRouteLockGainMarginPct": best["holdoutLowLoadRouteLockGainPct"] - allowed_lowlock_best if math.isfinite(allowed_lowlock_best) else math.nan,
                "allowedNullCleanHighRmseGainBestPct": allowed_primary_best,
                "allowedNullCleanHighRmseGainMarginPct": best["holdoutPrimaryGainPct"] - allowed_primary_best if math.isfinite(allowed_primary_best) else math.nan,
                "allowedNullCleanGainBestPct": allowed_clean_best,
                "allowedNullCleanGainMarginPct": best["holdoutCleanGainPct"] - allowed_clean_best if math.isfinite(allowed_clean_best) else math.nan,
                "oracleLowLoadRouteLockGainPct": oracle_row["holdoutLowLoadRouteLockGainPct"],
                "oracleCleanHighRmseGainPct": oracle_row["holdoutPrimaryGainPct"],
                "oracleRecoveryPct": oracle_recovery,
            }
        )
        oracle_rows.append(
            {
                "seed": seed,
                "candidateId": best["candidateId"],
                "candidateLowLoadRouteLockGainPct": best["holdoutLowLoadRouteLockGainPct"],
                "oracleLowLoadRouteLockGainPct": oracle_row["holdoutLowLoadRouteLockGainPct"],
                "oracleRecoveryPct": oracle_recovery,
                "oracleCleanHighRmseGainPct": oracle_row["holdoutPrimaryGainPct"],
                "oracleProtectedFalseReleaseCount": oracle_row["protectedFalseReleaseCount"],
                "oracleActiveNames": oracle_row["activeNames"],
                "oracleStatus": "forbidden route-lock target oracle ceiling; not promotable",
            }
        )
        for row in case_rows:
            if row["protectedFalseRelease"]:
                copy = dict(row)
                copy["seed"] = seed
                false_release_rows.append(copy)
        null_rows_all.extend(null_rows)
        if seed == SPLIT_SEED:
            main_case_rows = case_rows
            main_score_rows = score_rows
    return seed_rows, null_rows_all, oracle_rows, main_case_rows, main_score_rows, false_release_rows


def v21_law_false_release_ledger(rows: list[dict], false_release_rows: list[dict]) -> list[dict]:
    feature_rows = {row["name"]: row for row in rows}
    grouped: dict[str, dict] = {}
    for row in false_release_rows:
        group = grouped.setdefault(
            row["name"],
            {
                "name": row["name"],
                "recurrenceCount": 0,
                "falseReleaseSeeds": [],
                "formulaFamilies": set(),
                "gateStyles": set(),
                "rules": set(),
                "maxDelta": -math.inf,
            },
        )
        group["recurrenceCount"] += 1
        group["falseReleaseSeeds"].append(str(row["seed"]))
        group["formulaFamilies"].add(row.get("formulaFamily", ""))
        group["gateStyles"].add(row.get("gateStyle", ""))
        group["rules"].add(row.get("ruleText", ""))
        group["maxDelta"] = max(group["maxDelta"], row["delta"])
    if "F565-V2" in feature_rows and "F565-V2" not in grouped:
        grouped["F565-V2"] = {
            "name": "F565-V2",
            "recurrenceCount": 0,
            "falseReleaseSeeds": [],
            "formulaFamilies": set(),
            "gateStyles": set(),
            "rules": set(),
            "maxDelta": math.nan,
        }
    ledger = []
    for name, group in grouped.items():
        feature = feature_rows.get(name, {})
        ledger.append(
            {
                "name": name,
                "recurrenceCount": group["recurrenceCount"],
                "falseReleaseSeeds": ";".join(group["falseReleaseSeeds"]),
                "recurringAcrossMoreThan2Seeds": group["recurrenceCount"] > 2,
                "formulaFamilies": ";".join(sorted(group["formulaFamilies"])),
                "gateStyles": ";".join(sorted(group["gateStyles"])),
                "rules": " | ".join(sorted(group["rules"])),
                "maxDelta": group["maxDelta"],
                "lockedRoute": feature.get("lockedRoute", ""),
                "failureClass": feature.get("failureClass", ""),
                "noGoClass": feature.get("noGoClass", ""),
                "boundaryScore": feature.get("boundaryScore", math.nan),
                "memoryLoad": feature.get("memoryLoad", math.nan),
                "u075": feature.get("u075", math.nan),
                "uOut": feature.get("uOut", math.nan),
                "uMax": feature.get("uMax", math.nan),
            }
        )
    ledger.sort(key=lambda row: (-row["recurrenceCount"], row["name"]))
    return ledger


def v21_law_family_counts(seed_rows: list[dict]) -> dict:
    counts: dict[str, int] = {}
    for row in seed_rows:
        key = f"{row['formulaFamily']}:{row['gateStyle']}"
        counts[key] = counts.get(key, 0) + 1
    return dict(sorted(counts.items()))


def v21_law_verdict(seed_rows: list[dict], false_release_ledger: list[dict]) -> tuple[str, list[str], dict]:
    family_counts = v21_law_family_counts(seed_rows)
    dominant_count = max(family_counts.values() or [0])
    metrics = {
        "medianCleanHoldoutGainPct": safe_median(row["holdoutCleanGainPct"] for row in seed_rows),
        "medianCleanHighRmseHoldoutGainPct": safe_median(row["holdoutPrimaryGainPct"] for row in seed_rows),
        "medianLowLoadRouteLockHoldoutGainPct": safe_median(row["holdoutLowLoadRouteLockGainPct"] for row in seed_rows),
        "medianRouteLockRecallPct": 100.0 * safe_median(row["holdoutRouteLockRecall"] for row in seed_rows),
        "minAllowedNullLowLoadRouteLockGainMarginPct": min([row["allowedNullLowLoadRouteLockGainMarginPct"] for row in seed_rows if math.isfinite(row["allowedNullLowLoadRouteLockGainMarginPct"])] or [math.nan]),
        "medianAllowedNullLowLoadRouteLockGainMarginPct": safe_median(row["allowedNullLowLoadRouteLockGainMarginPct"] for row in seed_rows),
        "medianOracleRecoveryPct": safe_median(row["oracleRecoveryPct"] for row in seed_rows),
        "minOracleRecoveryPct": min([row["oracleRecoveryPct"] for row in seed_rows if math.isfinite(row["oracleRecoveryPct"])] or [math.nan]),
        "maxProtectedFalseReleaseCount": max([row["protectedFalseReleaseCount"] for row in seed_rows] or [0]),
        "maxProtectedFalseReleaseRecurrence": max([row["recurrenceCount"] for row in false_release_ledger] or [0]),
        "maxOversupportWorsenedCount": max([row["oversupportWorsenedCount"] for row in seed_rows] or [0]),
        "maxHoldoutRegression": max([row["maxHoldoutRegression"] for row in seed_rows if math.isfinite(row["maxHoldoutRegression"])] or [math.nan]),
        "maxWeakSystematicsLeakage": max([row["weakSystematicsLeakage"] for row in seed_rows] or [0]),
        "formulaFamilyCounts": family_counts,
        "dominantFormulaFamily": max(family_counts, key=family_counts.get) if family_counts else "",
        "dominantFormulaFamilyCount": dominant_count,
        "formulaFamilyStable": dominant_count >= 5,
    }
    failures = []
    if metrics["maxWeakSystematicsLeakage"] != 0:
        failures.append("weak/systematics leakage")
    if metrics["medianCleanHoldoutGainPct"] < 8:
        failures.append("median clean holdout gain < 8%")
    if metrics["medianCleanHighRmseHoldoutGainPct"] < 10:
        failures.append("median clean high-RMSE holdout gain < 10%")
    if metrics["medianLowLoadRouteLockHoldoutGainPct"] < 30:
        failures.append("median low-load route-lock holdout gain < 30%")
    if metrics["medianRouteLockRecallPct"] < 70:
        failures.append("route-lock target recall < 70%")
    if metrics["maxProtectedFalseReleaseCount"] > 1:
        failures.append("protected false releases > 1 in at least one seed")
    if metrics["maxProtectedFalseReleaseRecurrence"] > 2:
        failures.append("protected false release recurs across more than 2 seeds")
    if metrics["maxOversupportWorsenedCount"] > 0:
        failures.append("low-load oversupport cases worsen")
    if math.isfinite(metrics["maxHoldoutRegression"]) and metrics["maxHoldoutRegression"] > 8:
        failures.append("max holdout regression > 8 km/s")
    if not math.isfinite(metrics["minAllowedNullLowLoadRouteLockGainMarginPct"]) or metrics["minAllowedNullLowLoadRouteLockGainMarginPct"] < 10:
        failures.append("candidate does not beat allowed random/shuffled/lookalike nulls by 10 points on low-load route-lock gain")
    if not math.isfinite(metrics["medianOracleRecoveryPct"]) or metrics["medianOracleRecoveryPct"] < 60:
        failures.append("candidate recovers < 60% of forbidden route-lock oracle ceiling")
    if not metrics["formulaFamilyStable"]:
        failures.append("formula family not stable across seed replay")

    if not failures:
        verdict = "promoted for review"
    elif metrics["maxProtectedFalseReleaseCount"] > 1 or metrics["maxProtectedFalseReleaseRecurrence"] > 2 or metrics["maxOversupportWorsenedCount"] > 0:
        verdict = "protected-case failure"
    elif any("null" in failure for failure in failures):
        verdict = "not above allowed null"
    elif not metrics["formulaFamilyStable"]:
        verdict = "promising but not stable"
    else:
        verdict = "missing discriminator not in current state vector"
    return verdict, failures, metrics


def v21_law_formula_from_score(best: dict, seed_rows: list[dict], verdict: str) -> dict:
    return {
        "candidateId": best["candidateId"],
        "reviewStatus": verdict,
        "mechanism": "low-load memory-boundary stretch law-vs-oracle discriminator",
        "formulaText": "If lockedRoute == low-load and the allowed state gate activates: L_eff_candidate = L_exact * (1 + beta * activation); otherwise L_eff_candidate = L_exact.",
        "ruleText": best["ruleText"],
        "formulaFamily": best["formulaFamily"],
        "gateStyle": best["gateStyle"],
        "beta": best["beta"],
        "widthScale": best["widthScale"],
        "betaGrid": V21_REVIEW_BETAS,
        "gateStyles": V21_LAW_GATE_STYLES,
        "seedReplayFamilyCounts": v21_law_family_counts(seed_rows),
        "q": Q_DEFAULT,
        "gamma0": GAMMA0,
        "mlDisk": ML_DISK,
        "mlBulge": ML_BULGE,
        "allowedInputs": ["locked route", "boundaryScore", "memoryLoad", "u_0.75", "u_out", "u_max"],
        "forbiddenInputs": ["galaxy name", "raw residuals", "raw RMSE as formula input", "q changes", "amplitude patches", "route-lock labels as formula inputs", "weak/systematics fitting"],
    }


def v21_law_report(capsule: dict, score_rows: list[dict], seed_rows: list[dict], case_rows: list[dict], oracle_rows: list[dict], null_rows: list[dict]) -> str:
    best = score_rows[0]
    metrics = capsule["decisionMetrics"]
    null_by_type: dict[str, list[dict]] = {}
    for row in null_rows:
        null_by_type.setdefault(row["controlType"], []).append(row)
    lines = [
        "# MTS v21.1 Law-vs-Oracle Discriminator",
        "",
        "This test separates allowed state-gated memory stretch from the forbidden route-lock target oracle ceiling. Canonical MTS remains locked.",
        "",
        "## Headline",
        "",
        f"Verdict: **{capsule['verdict']}**.",
        f"Main split best candidate: `{best['candidateId']}`.",
        f"Rule: `{best['ruleText']}`; beta: `{fmt(best['beta'])}`; family: `{best['formulaFamily']}`; gate: `{best['gateStyle']}`.",
        f"Weak/systematics leakage: `{capsule['facts']['weakHoldoutLeakage']}`.",
        "",
        "## Acceptance Gate Status",
        "",
        "| Gate | Value |",
        "| --- | ---: |",
        f"| Median clean holdout gain | {fmt(metrics['medianCleanHoldoutGainPct'])}% |",
        f"| Median clean high-RMSE holdout gain | {fmt(metrics['medianCleanHighRmseHoldoutGainPct'])}% |",
        f"| Median low-load route-lock holdout gain | {fmt(metrics['medianLowLoadRouteLockHoldoutGainPct'])}% |",
        f"| Median route-lock recall | {fmt(metrics['medianRouteLockRecallPct'])}% |",
        f"| Min allowed-null low-load gain margin | {fmt(metrics['minAllowedNullLowLoadRouteLockGainMarginPct'])} points |",
        f"| Median forbidden-oracle recovery | {fmt(metrics['medianOracleRecoveryPct'])}% |",
        f"| Max protected false releases | {metrics['maxProtectedFalseReleaseCount']} |",
        f"| Max protected false-release recurrence | {metrics['maxProtectedFalseReleaseRecurrence']} seeds |",
        f"| Max oversupport worsened count | {metrics['maxOversupportWorsenedCount']} |",
        f"| Max holdout regression | {fmt(metrics['maxHoldoutRegression'])} km/s |",
        f"| Dominant formula family | {metrics['dominantFormulaFamily']} ({metrics['dominantFormulaFamilyCount']}/{len(seed_rows)}) |",
        "",
        "## Guardrail Failures",
        "",
    ]
    lines.extend([f"- {failure}" for failure in capsule["guardrailFailures"]] or ["- none"])
    lines.extend(
        [
            "",
            "## Main-Split Candidate Scores",
            "",
            "| Rank | Family | Gate | Rule | beta | Train utility | Clean gain | High-RMSE gain | Low-load gain | Recall | False releases | Max regression |",
            "| ---: | --- | --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
        ]
    )
    for row in score_rows[:25]:
        lines.append(
            f"| {row['rank']} | {row['formulaFamily']} | {row['gateStyle']} | {row['ruleText']} | {fmt(row['beta'])} | "
            f"{fmt(row['lawTrainUtility'])} | {fmt(row['holdoutCleanGainPct'])}% | {fmt(row['holdoutPrimaryGainPct'])}% | "
            f"{fmt(row['holdoutLowLoadRouteLockGainPct'])}% | {fmt(100 * row['holdoutRouteLockRecall'])}% | "
            f"{row['protectedFalseReleaseCount']} | {fmt(row['maxHoldoutRegression'])} |"
        )
    lines.extend(
        [
            "",
            "## Seed Replay",
            "",
            "| Seed | Family | Gate | beta | Clean gain | High-RMSE gain | Low-load gain | Recall | Allowed-null margin | Oracle recovery | False releases |",
            "| ---: | --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
        ]
    )
    for row in seed_rows:
        lines.append(
            f"| {row['seed']} | {row['formulaFamily']} | {row['gateStyle']} | {fmt(row['beta'])} | "
            f"{fmt(row['holdoutCleanGainPct'])}% | {fmt(row['holdoutPrimaryGainPct'])}% | "
            f"{fmt(row['holdoutLowLoadRouteLockGainPct'])}% | {fmt(100 * row['holdoutRouteLockRecall'])}% | "
            f"{fmt(row['allowedNullLowLoadRouteLockGainMarginPct'])} | {fmt(row['oracleRecoveryPct'])}% | "
            f"{row['protectedFalseReleaseCount']} |"
        )
    lines.extend(
        [
            "",
            "## Allowed Null Controls",
            "",
            "| Control | Rows | Best low-load route-lock gain | Best clean high-RMSE gain | Max regression |",
            "| --- | ---: | ---: | ---: | ---: |",
        ]
    )
    for control_type, grouped in sorted(null_by_type.items()):
        lines.append(
            f"| {control_type} | {len(grouped)} | {fmt(v21_review_null_best(grouped, 'holdoutLowLoadRouteLockGainPct'))}% | "
            f"{fmt(v21_review_null_best(grouped, 'holdoutPrimaryGainPct'))}% | "
            f"{fmt(max([row['maxHoldoutRegression'] for row in grouped if math.isfinite(row['maxHoldoutRegression'])] or [math.nan]))} |"
        )
    lines.extend(
        [
            "",
            "## Forbidden Oracle Ceiling",
            "",
            "| Seed | Candidate gain | Oracle gain | Recovery | Oracle status |",
            "| ---: | ---: | ---: | ---: | --- |",
        ]
    )
    for row in oracle_rows:
        lines.append(
            f"| {row['seed']} | {fmt(row['candidateLowLoadRouteLockGainPct'])}% | {fmt(row['oracleLowLoadRouteLockGainPct'])}% | "
            f"{fmt(row['oracleRecoveryPct'])}% | {row['oracleStatus']} |"
        )
    lines.extend(
        [
            "",
            "## Main-Split Case Ledger",
            "",
            "| Galaxy | Split | Target | Protected | Baseline | Candidate | Gain | Activation |",
            "| --- | --- | --- | --- | ---: | ---: | ---: | ---: |",
        ]
    )
    important_rows = [
        row
        for row in case_rows
        if row["lowloadRouteLockTarget"] or row["protectedFalseRelease"] or (row["protectedCase"] and row["activeStretch"])
    ]
    for row in sorted(important_rows, key=lambda item: (not item["lowloadRouteLockTarget"], item["name"])):
        lines.append(
            f"| {row['name']} | {row['split']} | {row['lowloadRouteLockTarget']} | {row['protectedCase']} | "
            f"{fmt(row['baselineRmse'])} | {fmt(row['candidateRmse'])} | {fmt(row['improvement'])} | {fmt(row['activation'])} |"
        )
    lines.extend(
        [
            "",
            "## Formula Discipline",
            "",
            "- The only mechanism is memory-length stretch: `L_eff_candidate = L_exact * (1 + beta * activation)`.",
            "- `q`, `Gamma0`, disk M/L, bulge M/L, and scalar amplitude are unchanged.",
            "- Route-lock labels are used only after prediction for scoring and the forbidden oracle ceiling.",
            "- Weak/systematics cases, galaxy names, raw residuals, and raw RMSE are not formula inputs.",
            "",
            f"Final verdict: **{capsule['verdict']}**.",
            "",
        ]
    )
    return "\n".join(lines)


def v21_law_paper_note(capsule: dict) -> str:
    metrics = capsule["decisionMetrics"]
    return "\n".join(
        [
            "# MTS v21.1 Candidate Note",
            "",
            f"Status: **{capsule['verdict']}**.",
            "",
            "The v21.1 discriminator tests whether a low-load memory-length stretch can be selected by allowed MTS state variables rather than by a forbidden route-lock target oracle.",
            "",
            f"Median clean holdout gain: `{fmt(metrics['medianCleanHoldoutGainPct'])}%`.",
            f"Median clean high-RMSE holdout gain: `{fmt(metrics['medianCleanHighRmseHoldoutGainPct'])}%`.",
            f"Median low-load route-lock holdout gain: `{fmt(metrics['medianLowLoadRouteLockHoldoutGainPct'])}%`.",
            f"Median route-lock recall: `{fmt(metrics['medianRouteLockRecallPct'])}%`.",
            f"Median forbidden-oracle recovery: `{fmt(metrics['medianOracleRecoveryPct'])}%`.",
            "",
            "This note is diagnostic. It does not alter canonical MTS.",
            "",
        ]
    )


def write_v21_law_discriminator_artifacts(out_dir: Path, curves: list[dict], holdout_fraction: float) -> dict:
    rows, facts = v21_build_rows(curves)
    split = v21_split_rows(rows, SPLIT_SEED, holdout_fraction)
    score_rows, case_rows, _candidate = v21_law_candidate_grid(rows, split)
    seed_rows, null_rows, oracle_rows, seed_case_rows, seed_score_rows, false_release_rows = v21_law_seed_replay(rows, holdout_fraction)
    if seed_case_rows:
        case_rows = seed_case_rows
    if seed_score_rows:
        score_rows = seed_score_rows
    false_release_ledger = v21_law_false_release_ledger(rows, false_release_rows)
    verdict, failures, decision_metrics = v21_law_verdict(seed_rows, false_release_ledger)
    best = score_rows[0]
    formula = v21_law_formula_from_score(best, seed_rows, verdict)
    capsule = {
        "type": "mts-v21-law-vs-oracle-discriminator-v3",
        "version": 3,
        "generatedAt": "deterministic",
        "sourceScript": "scripts/mts-failure-lab.py",
        "canonicalMtsStatus": "locked baseline; v21.1 discriminator branch only",
        "verdict": verdict,
        "guardrailFailures": failures,
        "decisionMetrics": decision_metrics,
        "bestFormula": formula,
        "facts": facts,
        "seeds": V19_SEEDS,
        "allowedNullControls": sorted(V21_LAW_PROMOTABLE_NULL_TYPES),
        "oracleStatus": "route-lock target oracle is reported as a forbidden ceiling, not a promotable null",
    }
    out_dir.mkdir(parents=True, exist_ok=True)
    write_csv(out_dir / "mts_v21_law_discriminator_scores.csv", score_rows)
    write_csv(out_dir / "mts_v21_law_discriminator_seed_replay.csv", seed_rows)
    write_csv(out_dir / "mts_v21_law_discriminator_case_ledger.csv", case_rows)
    write_csv(out_dir / "mts_v21_law_discriminator_oracle_gap.csv", oracle_rows)
    write_csv(out_dir / "mts_v21_law_discriminator_null_controls.csv", null_rows)
    (out_dir / "mts_v21_law_discriminator_formula.json").write_text(json.dumps(json_clean(formula), indent=2), encoding="utf-8")
    report = v21_law_report(capsule, score_rows, seed_rows, case_rows, oracle_rows, null_rows)
    (out_dir / "mts_v21_law_discriminator_report.md").write_text(report, encoding="utf-8")
    (out_dir / "mts_v21_law_discriminator_paper_note.md").write_text(v21_law_paper_note(capsule), encoding="utf-8")
    (out_dir / "mts_v21_law_discriminator_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2), encoding="utf-8")
    return capsule


V21_SAFETY_FEATURES = [
    "uOutOverUMax",
    "u075OverUMax",
    "uMaxMinusUOut",
    "u075MinusUOut",
    "routeMargin",
    "routeBreakRisk",
    "fGasOut",
    "memoryLoad",
    "boundaryScore",
]
V21_SAFETY_PAIR_SPECS = [
    ("uOutOverUMax", "memoryLoad"),
    ("uOutOverUMax", "u075OverUMax"),
    ("uOutOverUMax", "routeBreakRisk"),
    ("uMaxMinusUOut", "memoryLoad"),
    ("uMaxMinusUOut", "boundaryScore"),
    ("fGasOut", "memoryLoad"),
    ("routeMargin", "routeBreakRisk"),
]
V21_SAFETY_QUANTILES = [0.15, 0.25, 0.33, 0.50, 0.66, 0.75, 0.85]
V21_SAFETY_PAIR_QUANTILES = [0.25, 0.50, 0.75]
V21_SAFETY_DIRECTIONS = ["ge", "le"]
V21_SAFETY_EDGE_CASES = ["NGC3769", "PGC51017", "NGC0247", "UGC05829", "UGC06818", "NGC3726"]


def v21_safety_feature_value(row: dict, feature: str) -> float:
    u_max = row.get("uMax", math.nan)
    if feature == "uOutOverUMax":
        return row["uOut"] / u_max if math.isfinite(u_max) and abs(u_max) > 1e-12 else math.nan
    if feature == "u075OverUMax":
        return row["u075"] / u_max if math.isfinite(u_max) and abs(u_max) > 1e-12 else math.nan
    if feature == "uMaxMinusUOut":
        return row["uMax"] - row["uOut"]
    if feature == "u075MinusUOut":
        return row["u075"] - row["uOut"]
    return row.get(feature, math.nan)


def v21_safety_feature_row(row: dict) -> dict:
    return {feature: v21_safety_feature_value(row, feature) for feature in V21_SAFETY_FEATURES}


def v21_safety_threshold_values(rows: list[dict], train_names: set[str], feature: str, quantiles: list[float]) -> list[float]:
    values = sorted(
        v21_safety_feature_value(row, feature)
        for row in rows
        if row["name"] in train_names and row["lockedRoute"] == "low-load" and math.isfinite(v21_safety_feature_value(row, feature))
    )
    if not values:
        return [0.0]
    out = []
    for fraction in quantiles:
        index = min(len(values) - 1, max(0, int(round((len(values) - 1) * fraction))))
        out.append(round(values[index], 6))
    return v19_unique_floats(out)


def v21_safety_condition_text(condition: tuple[str, str, float]) -> str:
    feature, direction, threshold = condition
    return f"{feature} {direction} {fmt(threshold)}"


def v21_safety_rule_text(safety: dict) -> str:
    strategy = safety["strategy"]
    if strategy == "none":
        return "no safety gate"
    condition_text = " and ".join(v21_safety_condition_text(condition) for condition in safety["conditions"])
    if strategy.endswith("hard-veto"):
        return f"hard veto keep if {condition_text}"
    if strategy.endswith("continuous-safety-cap"):
        return f"continuous cap by {condition_text}"
    return f"two-condition veto keep if {condition_text}"


def v21_safety_candidate_id(base_candidate: dict, safety: dict) -> str:
    if safety["strategy"] == "none":
        suffix = "no-safety"
    else:
        suffix = safety["strategy"] + "-" + "-and-".join(
            f"{feature}{direction}{fmt_num(threshold)}" for feature, direction, threshold in safety["conditions"]
        )
    return (base_candidate["candidateId"] + "-safety-" + suffix).replace(".", "p")


def v21_safety_condition_passes(row: dict, condition: tuple[str, str, float]) -> bool:
    feature, direction, threshold = condition
    value = v21_safety_feature_value(row, feature)
    if not math.isfinite(value):
        return False
    return value >= threshold if direction == "ge" else value <= threshold


def v21_safety_condition_activation(row: dict, condition: tuple[str, str, float], widths: dict[str, float]) -> float:
    feature, direction, threshold = condition
    value = v21_safety_feature_value(row, feature)
    if not math.isfinite(value):
        return 0.0
    width = max(1e-9, widths.get(feature, 1.0))
    signed = (value - threshold) / width if direction == "ge" else (threshold - value) / width
    return clamp(signed, 0.0, 1.0)


def v21_safety_value(row: dict, safety: dict) -> float:
    if safety["strategy"] == "none":
        return 1.0
    if safety["strategy"] in {"hard-veto", "two-condition-veto"}:
        return 1.0 if all(v21_safety_condition_passes(row, condition) for condition in safety["conditions"]) else 0.0
    activations = [v21_safety_condition_activation(row, condition, safety["widths"]) for condition in safety["conditions"]]
    return min(activations) if activations else 1.0


def v21_safety_feature_span(rows: list[dict], train_names: set[str], feature: str) -> float:
    values = [
        v21_safety_feature_value(row, feature)
        for row in rows
        if row["name"] in train_names and row["lockedRoute"] == "low-load" and math.isfinite(v21_safety_feature_value(row, feature))
    ]
    if len(values) < 2:
        return 1.0
    span = max(values) - min(values)
    return span if span > 1e-9 else max(1.0, abs(values[0]))


def v21_safety_candidates(rows: list[dict], train_names: set[str], base_candidate: dict) -> list[dict]:
    out = [
        {
            "strategy": "none",
            "conditions": (),
            "widths": {},
            "safetyRuleText": "no safety gate",
        }
    ]
    spans = {feature: v21_safety_feature_span(rows, train_names, feature) for feature in V21_SAFETY_FEATURES}
    for feature in V21_SAFETY_FEATURES:
        for direction in V21_SAFETY_DIRECTIONS:
            for threshold in v21_safety_threshold_values(rows, train_names, feature, V21_SAFETY_QUANTILES):
                hard = {
                    "strategy": "hard-veto",
                    "conditions": ((feature, direction, threshold),),
                    "widths": {},
                }
                hard["safetyRuleText"] = v21_safety_rule_text(hard)
                out.append(hard)
                cap = {
                    "strategy": "continuous-safety-cap",
                    "conditions": ((feature, direction, threshold),),
                    "widths": {feature: max(1e-9, spans[feature] * 0.25)},
                }
                cap["safetyRuleText"] = v21_safety_rule_text(cap)
                out.append(cap)
    for first_feature, second_feature in V21_SAFETY_PAIR_SPECS:
        first_thresholds = v21_safety_threshold_values(rows, train_names, first_feature, V21_SAFETY_PAIR_QUANTILES)
        second_thresholds = v21_safety_threshold_values(rows, train_names, second_feature, V21_SAFETY_PAIR_QUANTILES)
        for first_direction in V21_SAFETY_DIRECTIONS:
            for second_direction in V21_SAFETY_DIRECTIONS:
                for first_threshold in first_thresholds:
                    for second_threshold in second_thresholds:
                        pair = {
                            "strategy": "two-condition-veto",
                            "conditions": (
                                (first_feature, first_direction, first_threshold),
                                (second_feature, second_direction, second_threshold),
                            ),
                            "widths": {},
                        }
                        pair["safetyRuleText"] = v21_safety_rule_text(pair)
                        out.append(pair)
    seen = set()
    unique = []
    for safety in out:
        identity = (safety["strategy"], safety["conditions"])
        if identity in seen:
            continue
        seen.add(identity)
        safety["safetyId"] = v21_safety_candidate_id(base_candidate, safety)
        unique.append(safety)
    return unique


def v21_safety_case_rows(
    rows: list[dict],
    split: dict,
    base_candidate: dict,
    safety: dict,
    *,
    activation_override: dict[str, float] | None = None,
    candidate_id: str | None = None,
    family: str | None = None,
    score_cache: dict[tuple[str, float], dict] | None = None,
) -> list[dict]:
    score_cache = score_cache if score_cache is not None else {}
    candidate_id = candidate_id or safety["safetyId"]
    family = family or f"v21-safety-{base_candidate['formulaFamily']}-{base_candidate['gateStyle']}-{safety['strategy']}"
    out = []
    for row in rows:
        if activation_override is not None:
            activation = activation_override.get(row["name"], 0.0)
            base_activation = math.nan
            safety_value = math.nan
        else:
            base_activation = v21_law_activation(row, base_candidate)
            safety_value = v21_safety_value(row, safety)
            activation = base_activation * safety_value
        if row["lockedRoute"] != "low-load":
            activation = 0.0
        score = v21_law_score_for_row(row, base_candidate["beta"], activation, score_cache)
        baseline = row["baseline"]
        delta = score["rmse"] - baseline["rmse"]
        active = activation >= V21_LAW_ACTIVE_EPSILON
        feature_values = v21_safety_feature_row(row)
        out.append(
            {
                "candidateFamily": family,
                "candidateId": candidate_id,
                "baseCandidateId": base_candidate["candidateId"],
                "name": row["name"],
                "split": "holdout" if row["name"] in split["holdoutNames"] else "train",
                "failureClass": row["failureClass"],
                "noGoClass": row["noGoClass"],
                "lockedRoute": row["lockedRoute"],
                "candidateRoute": score["candidateRoute"],
                "oldRoutePreserved": score["candidateRoute"] == row["lockedRoute"],
                "weakHoldoutExcluded": row["weakHoldoutExcluded"],
                "primaryCase": row["primaryCase"],
                "lowloadRouteLockTarget": row["lowloadRouteLockTarget"],
                "protectedCase": row["protectedCase"] and not row["lowloadRouteLockTarget"],
                "oversupportCase": row["oversupportCase"],
                "baselineRmse": baseline["rmse"],
                "candidateRmse": score["rmse"],
                "delta": delta,
                "improvement": baseline["rmse"] - score["rmse"],
                "improvementPct": pct_improvement(baseline["rmse"], score["rmse"]),
                "activeStretch": active,
                "activation": activation,
                "baseActivation": base_activation,
                "safety": safety_value,
                "beta": base_candidate["beta"],
                "effectiveBeta": base_candidate["beta"] * activation,
                "formulaFamily": base_candidate["formulaFamily"],
                "gateStyle": base_candidate["gateStyle"],
                "baseRuleText": v21_law_rule_text(base_candidate),
                "safetyStrategy": safety["strategy"],
                "safetyRuleText": safety["safetyRuleText"],
                "leffExact": row["lExact"],
                "leffCandidate": score.get("candidateLeff", row["lExact"]),
                "leffStretchFactor": (score.get("candidateLeff", row["lExact"]) / row["lExact"]) if row["lExact"] else math.nan,
                "boundaryScore": row["boundaryScore"],
                "memoryLoad": row["memoryLoad"],
                "u075": row["u075"],
                "uOut": row["uOut"],
                "uMax": row["uMax"],
                "routeMargin": row["routeMargin"],
                "routeBreakRisk": row["routeBreakRisk"],
                "hOverRout": row["hOverRout"],
                "fGasOut": row["fGasOut"],
                "lGap": row["lGap"],
                **feature_values,
                "protectedFalseRelease": active and row["protectedCase"] and not row["lowloadRouteLockTarget"] and delta > 2.0,
                "oversupportWorsened": row["oversupportCase"] and delta > 0.0,
                "regressionOver2": delta > 2.0,
                "regressionOver8": delta > 8.0,
            }
        )
    return out


def v21_safety_metric_summary(case_rows: list[dict]) -> dict:
    return v21_law_metric_summary(case_rows)


def v21_safety_train_utility(metrics: dict) -> float:
    max_train_regression = metrics["maxTrainRegression"] if math.isfinite(metrics["maxTrainRegression"]) else 0.0
    recall = metrics["trainRouteLockRecall"] if math.isfinite(metrics["trainRouteLockRecall"]) else 0.0
    return (
        metrics["trainLowLoadRouteLockGainPct"]
        + 0.65 * metrics["trainPrimaryGainPct"]
        + 0.30 * metrics["trainCleanGainPct"]
        + 20.0 * recall
        - 95.0 * metrics["trainProtectedFalseReleaseCount"]
        - 65.0 * metrics["trainOversupportWorsenedCount"]
        - 12.0 * max(0.0, max_train_regression - 8.0)
    )


def v21_safety_score_row(rank: int, base_candidate: dict, safety: dict, metrics: dict) -> dict:
    return {
        "rank": rank,
        "candidateId": safety["safetyId"],
        "baseCandidateId": base_candidate["candidateId"],
        "formulaFamily": base_candidate["formulaFamily"],
        "gateStyle": base_candidate["gateStyle"],
        "baseRuleText": v21_law_rule_text(base_candidate),
        "safetyStrategy": safety["strategy"],
        "safetyRuleText": safety["safetyRuleText"],
        "beta": base_candidate["beta"],
        "safetyTrainUtility": v21_safety_train_utility(metrics),
        **metrics,
    }


def v21_safety_score_sort_key(row: dict) -> tuple:
    return (
        row["safetyTrainUtility"],
        -row["trainProtectedFalseReleaseCount"],
        -row["trainOversupportWorsenedCount"],
        -max(0.0, row["maxTrainRegression"] - 8.0 if math.isfinite(row["maxTrainRegression"]) else 0.0),
        row["trainLowLoadRouteLockGainPct"],
        row["trainRouteLockRecall"] if math.isfinite(row["trainRouteLockRecall"]) else 0.0,
        row["trainPrimaryGainPct"],
        row["candidateId"],
    )


def v21_safety_candidate_grid(rows: list[dict], split: dict, base_candidate: dict) -> tuple[list[dict], list[dict], dict]:
    score_rows = []
    ledgers: dict[str, list[dict]] = {}
    safety_by_id: dict[str, dict] = {}
    score_cache: dict[tuple[str, float], dict] = {}
    for safety in v21_safety_candidates(rows, split["trainNames"], base_candidate):
        case_rows = v21_safety_case_rows(rows, split, base_candidate, safety, score_cache=score_cache)
        metrics = v21_safety_metric_summary(case_rows)
        record = v21_safety_score_row(0, base_candidate, safety, metrics)
        score_rows.append(record)
        ledgers[safety["safetyId"]] = case_rows
        safety_by_id[safety["safetyId"]] = safety
    score_rows.sort(key=v21_safety_score_sort_key, reverse=True)
    for index, row in enumerate(score_rows, start=1):
        row["rank"] = index
    best = score_rows[0]
    return score_rows, ledgers[best["candidateId"]], safety_by_id[best["candidateId"]]


def v21_safety_activation_map(case_rows: list[dict]) -> dict[str, float]:
    return {
        row["name"]: row["activation"]
        for row in case_rows
        if row["lockedRoute"] == "low-load" and row["activation"] >= V21_LAW_ACTIVE_EPSILON
    }


def v21_safety_control_metrics_row(
    rows: list[dict],
    split: dict,
    base_candidate: dict,
    safety: dict,
    activation_override: dict[str, float],
    *,
    seed: int,
    iteration: int,
    control_type: str,
    source_candidate_id: str,
    score_cache: dict[tuple[str, float], dict],
) -> dict:
    case_rows = v21_safety_case_rows(
        rows,
        split,
        base_candidate,
        safety,
        activation_override=activation_override,
        candidate_id=f"{control_type}-{seed}-{iteration}",
        family=control_type,
        score_cache=score_cache,
    )
    metrics = v21_safety_metric_summary(case_rows)
    return {
        "controlType": control_type,
        "seed": seed,
        "iteration": iteration,
        "sourceCandidateId": source_candidate_id,
        "formulaFamily": base_candidate["formulaFamily"],
        "gateStyle": base_candidate["gateStyle"],
        "baseRuleText": v21_law_rule_text(base_candidate),
        "safetyStrategy": safety["strategy"],
        "safetyRuleText": safety["safetyRuleText"],
        "beta": base_candidate["beta"],
        "requestedActiveCount": len(activation_override),
        "activeNames": ";".join(sorted(activation_override)),
        **metrics,
    }


def v21_safety_null_control_rows(
    rows: list[dict],
    split: dict,
    base_candidate: dict,
    safety: dict,
    case_rows: list[dict],
    *,
    seed: int,
) -> tuple[list[dict], dict, dict]:
    rng = random.Random(seed)
    score_cache: dict[tuple[str, float], dict] = {}
    lowload_names = v21_review_lowload_names(rows)
    activation_map = v21_safety_activation_map(case_rows)
    active_values = sorted(activation_map.values(), reverse=True)
    active_count = len(active_values)
    out = []
    for index in range(V21_REVIEW_NULL_ITERATIONS):
        sampled = rng.sample(lowload_names, min(active_count, len(lowload_names)))
        override = v21_law_assign_activation_values(sampled, active_values)
        out.append(
            v21_safety_control_metrics_row(
                rows,
                split,
                base_candidate,
                safety,
                override,
                seed=seed,
                iteration=index,
                control_type="same-active-count-random-lowload-stretch-null",
                source_candidate_id=safety["safetyId"],
                score_cache=score_cache,
            )
        )
    for index in range(V21_REVIEW_NULL_ITERATIONS):
        shuffled_names = rng.sample(lowload_names, len(lowload_names))
        shuffled_values = active_values + [0.0] * max(0, len(lowload_names) - len(active_values))
        rng.shuffle(shuffled_values)
        override = {
            name: value
            for name, value in zip(shuffled_names, shuffled_values)
            if value >= V21_LAW_ACTIVE_EPSILON
        }
        out.append(
            v21_safety_control_metrics_row(
                rows,
                split,
                base_candidate,
                safety,
                override,
                seed=seed,
                iteration=index,
                control_type="shuffled-state-gate-null",
                source_candidate_id=safety["safetyId"],
                score_cache=score_cache,
            )
        )
    all_lowload = {name: 1.0 for name in lowload_names}
    out.append(
        v21_safety_control_metrics_row(
            rows,
            split,
            base_candidate,
            safety,
            all_lowload,
            seed=seed,
            iteration=-1,
            control_type="all-low-load-stretch-control",
            source_candidate_id=safety["safetyId"],
            score_cache=score_cache,
        )
    )
    lookalike_names = v21_review_protected_lookalike_active_names(rows, base_candidate["rule"], active_count)
    lookalike_override = v21_law_assign_activation_values(sorted(lookalike_names), active_values)
    out.append(
        v21_safety_control_metrics_row(
            rows,
            split,
            base_candidate,
            safety,
            lookalike_override,
            seed=seed,
            iteration=-1,
            control_type="protected-low-load-lookalike-stress-control",
            source_candidate_id=safety["safetyId"],
            score_cache=score_cache,
        )
    )
    no_safety = {
        "strategy": "none",
        "conditions": (),
        "widths": {},
        "safetyRuleText": "no safety gate",
        "safetyId": base_candidate["candidateId"] + "-safety-no-safety",
    }
    no_safety_case_rows = v21_safety_case_rows(
        rows,
        split,
        base_candidate,
        no_safety,
        candidate_id=f"v21-1-no-safety-control-{seed}",
        family="v21-1-no-safety-control",
        score_cache=score_cache,
    )
    no_safety_record = {
        "controlType": "v21-1-no-safety-control",
        "seed": seed,
        "iteration": -1,
        "sourceCandidateId": safety["safetyId"],
        "formulaFamily": base_candidate["formulaFamily"],
        "gateStyle": base_candidate["gateStyle"],
        "baseRuleText": v21_law_rule_text(base_candidate),
        "safetyStrategy": "none",
        "safetyRuleText": "no safety gate",
        "beta": base_candidate["beta"],
        "requestedActiveCount": len(v21_safety_activation_map(no_safety_case_rows)),
        "activeNames": ";".join(sorted(v21_safety_activation_map(no_safety_case_rows))),
        **v21_safety_metric_summary(no_safety_case_rows),
    }
    oracle_override = {
        row["name"]: 1.0
        for row in rows
        if row["lockedRoute"] == "low-load" and row["lowloadRouteLockTarget"]
    }
    oracle_case_rows = v21_safety_case_rows(
        rows,
        split,
        base_candidate,
        no_safety,
        activation_override=oracle_override,
        candidate_id=f"forbidden-route-lock-oracle-ceiling-{seed}",
        family="forbidden-route-lock-oracle-ceiling",
        score_cache=score_cache,
    )
    oracle_record = {
        "controlType": "forbidden-route-lock-oracle-ceiling",
        "seed": seed,
        "iteration": -1,
        "sourceCandidateId": safety["safetyId"],
        "formulaFamily": base_candidate["formulaFamily"],
        "gateStyle": base_candidate["gateStyle"],
        "baseRuleText": "FORBIDDEN: route-lock target labels activate memory stretch",
        "safetyStrategy": "none",
        "safetyRuleText": "FORBIDDEN: route-lock target labels",
        "beta": base_candidate["beta"],
        "requestedActiveCount": len(oracle_override),
        "activeNames": ";".join(sorted(oracle_override)),
        **v21_safety_metric_summary(oracle_case_rows),
    }
    return out + [no_safety_record], oracle_record, no_safety_record


def v21_safety_best_allowed_null(null_rows: list[dict], key: str) -> float:
    return max(
        [
            row[key]
            for row in null_rows
            if row["controlType"] in V21_LAW_PROMOTABLE_NULL_TYPES and math.isfinite(row.get(key, math.nan))
        ]
        or [math.nan]
    )


def v21_safety_seed_replay(rows: list[dict], holdout_fraction: float) -> tuple[list[dict], list[dict], list[dict], list[dict], list[dict], list[dict]]:
    seed_rows = []
    null_rows_all = []
    oracle_rows = []
    false_release_rows = []
    main_case_rows = []
    main_score_rows = []
    for seed in V19_SEEDS:
        split = v21_split_rows(rows, seed, holdout_fraction)
        _base_scores, _base_cases, base_candidate = v21_law_candidate_grid(rows, split)
        score_rows, case_rows, safety = v21_safety_candidate_grid(rows, split, base_candidate)
        best = score_rows[0]
        null_rows, oracle_row, no_safety_row = v21_safety_null_control_rows(
            rows,
            split,
            base_candidate,
            safety,
            case_rows,
            seed=seed + 91000,
        )
        allowed_lowlock_best = v21_safety_best_allowed_null(null_rows, "holdoutLowLoadRouteLockGainPct")
        allowed_primary_best = v21_safety_best_allowed_null(null_rows, "holdoutPrimaryGainPct")
        oracle_recovery = v21_law_oracle_recovery(
            best["holdoutLowLoadRouteLockGainPct"],
            oracle_row["holdoutLowLoadRouteLockGainPct"],
        )
        seed_rows.append(
            {
                "seed": seed,
                "candidateId": best["candidateId"],
                "baseCandidateId": best["baseCandidateId"],
                "formulaFamily": best["formulaFamily"],
                "gateStyle": best["gateStyle"],
                "baseRuleText": best["baseRuleText"],
                "safetyStrategy": best["safetyStrategy"],
                "safetyRuleText": best["safetyRuleText"],
                "beta": best["beta"],
                "safetyTrainUtility": best["safetyTrainUtility"],
                "holdoutCleanGainPct": best["holdoutCleanGainPct"],
                "holdoutPrimaryGainPct": best["holdoutPrimaryGainPct"],
                "holdoutLowLoadRouteLockGainPct": best["holdoutLowLoadRouteLockGainPct"],
                "holdoutRouteLockRecall": best["holdoutRouteLockRecall"],
                "protectedFalseReleaseCount": best["protectedFalseReleaseCount"],
                "oversupportWorsenedCount": best["oversupportWorsenedCount"],
                "maxHoldoutRegression": best["maxHoldoutRegression"],
                "activeStretchCount": best["activeStretchCount"],
                "activeLowLoadRouteLockCount": best["activeLowLoadRouteLockCount"],
                "activeLowLoadProtectedCount": best["activeLowLoadProtectedCount"],
                "weakSystematicsLeakage": best["weakSystematicsLeakage"],
                "allowedNullLowLoadRouteLockGainBestPct": allowed_lowlock_best,
                "allowedNullLowLoadRouteLockGainMarginPct": best["holdoutLowLoadRouteLockGainPct"] - allowed_lowlock_best if math.isfinite(allowed_lowlock_best) else math.nan,
                "allowedNullCleanHighRmseGainBestPct": allowed_primary_best,
                "allowedNullCleanHighRmseGainMarginPct": best["holdoutPrimaryGainPct"] - allowed_primary_best if math.isfinite(allowed_primary_best) else math.nan,
                "oracleLowLoadRouteLockGainPct": oracle_row["holdoutLowLoadRouteLockGainPct"],
                "oracleRecoveryPct": oracle_recovery,
                "noSafetyLowLoadRouteLockGainPct": no_safety_row["holdoutLowLoadRouteLockGainPct"],
                "noSafetyProtectedFalseReleaseCount": no_safety_row["protectedFalseReleaseCount"],
                "noSafetyMaxHoldoutRegression": no_safety_row["maxHoldoutRegression"],
            }
        )
        oracle_rows.append(
            {
                "seed": seed,
                "candidateId": best["candidateId"],
                "candidateLowLoadRouteLockGainPct": best["holdoutLowLoadRouteLockGainPct"],
                "oracleLowLoadRouteLockGainPct": oracle_row["holdoutLowLoadRouteLockGainPct"],
                "oracleRecoveryPct": oracle_recovery,
                "noSafetyLowLoadRouteLockGainPct": no_safety_row["holdoutLowLoadRouteLockGainPct"],
                "oracleProtectedFalseReleaseCount": oracle_row["protectedFalseReleaseCount"],
                "oracleActiveNames": oracle_row["activeNames"],
                "oracleStatus": "forbidden route-lock target oracle ceiling; not promotable",
            }
        )
        for row in case_rows:
            if row["protectedFalseRelease"]:
                copy = dict(row)
                copy["seed"] = seed
                false_release_rows.append(copy)
        null_rows_all.extend(null_rows)
        if seed == SPLIT_SEED:
            main_case_rows = case_rows
            main_score_rows = score_rows
    return seed_rows, null_rows_all, oracle_rows, main_case_rows, main_score_rows, false_release_rows


def v21_safety_false_release_ledger(rows: list[dict], false_release_rows: list[dict]) -> list[dict]:
    feature_rows = {row["name"]: row for row in rows}
    grouped: dict[str, dict] = {}
    for row in false_release_rows:
        group = grouped.setdefault(
            row["name"],
            {
                "name": row["name"],
                "recurrenceCount": 0,
                "falseReleaseSeeds": [],
                "formulaFamilies": set(),
                "gateStyles": set(),
                "safetyStrategies": set(),
                "safetyRules": set(),
                "maxDelta": -math.inf,
            },
        )
        group["recurrenceCount"] += 1
        group["falseReleaseSeeds"].append(str(row["seed"]))
        group["formulaFamilies"].add(row.get("formulaFamily", ""))
        group["gateStyles"].add(row.get("gateStyle", ""))
        group["safetyStrategies"].add(row.get("safetyStrategy", ""))
        group["safetyRules"].add(row.get("safetyRuleText", ""))
        group["maxDelta"] = max(group["maxDelta"], row["delta"])
    for name in V21_SAFETY_EDGE_CASES:
        if name in feature_rows and name not in grouped:
            grouped[name] = {
                "name": name,
                "recurrenceCount": 0,
                "falseReleaseSeeds": [],
                "formulaFamilies": set(),
                "gateStyles": set(),
                "safetyStrategies": set(),
                "safetyRules": set(),
                "maxDelta": math.nan,
            }
    ledger = []
    for name, group in grouped.items():
        feature = feature_rows.get(name, {})
        ledger_row = {
            "name": name,
            "recurrenceCount": group["recurrenceCount"],
            "falseReleaseSeeds": ";".join(group["falseReleaseSeeds"]),
            "recurringAcrossMoreThan1Seed": group["recurrenceCount"] > 1,
            "formulaFamilies": ";".join(sorted(group["formulaFamilies"])),
            "gateStyles": ";".join(sorted(group["gateStyles"])),
            "safetyStrategies": ";".join(sorted(group["safetyStrategies"])),
            "safetyRules": " | ".join(sorted(group["safetyRules"])),
            "maxDelta": group["maxDelta"],
            "lockedRoute": feature.get("lockedRoute", ""),
            "failureClass": feature.get("failureClass", ""),
            "noGoClass": feature.get("noGoClass", ""),
        }
        if feature:
            ledger_row.update(v21_safety_feature_row(feature))
        ledger.append(ledger_row)
    ledger.sort(key=lambda row: (-row["recurrenceCount"], row["name"]))
    return ledger


def v21_safety_family_counts(seed_rows: list[dict]) -> dict:
    counts: dict[str, int] = {}
    for row in seed_rows:
        key = f"{row['formulaFamily']}:{row['gateStyle']}:{row['safetyStrategy']}:{row['safetyRuleText']}"
        counts[key] = counts.get(key, 0) + 1
    return dict(sorted(counts.items()))


def v21_safety_verdict(seed_rows: list[dict], false_release_ledger: list[dict]) -> tuple[str, list[str], dict]:
    family_counts = v21_safety_family_counts(seed_rows)
    dominant_count = max(family_counts.values() or [0])
    metrics = {
        "medianCleanHoldoutGainPct": safe_median(row["holdoutCleanGainPct"] for row in seed_rows),
        "medianCleanHighRmseHoldoutGainPct": safe_median(row["holdoutPrimaryGainPct"] for row in seed_rows),
        "medianLowLoadRouteLockHoldoutGainPct": safe_median(row["holdoutLowLoadRouteLockGainPct"] for row in seed_rows),
        "medianRouteLockRecallPct": 100.0 * safe_median(row["holdoutRouteLockRecall"] for row in seed_rows),
        "minAllowedNullLowLoadRouteLockGainMarginPct": min([row["allowedNullLowLoadRouteLockGainMarginPct"] for row in seed_rows if math.isfinite(row["allowedNullLowLoadRouteLockGainMarginPct"])] or [math.nan]),
        "medianAllowedNullLowLoadRouteLockGainMarginPct": safe_median(row["allowedNullLowLoadRouteLockGainMarginPct"] for row in seed_rows),
        "medianOracleRecoveryPct": safe_median(row["oracleRecoveryPct"] for row in seed_rows),
        "minOracleRecoveryPct": min([row["oracleRecoveryPct"] for row in seed_rows if math.isfinite(row["oracleRecoveryPct"])] or [math.nan]),
        "maxProtectedFalseReleaseCount": max([row["protectedFalseReleaseCount"] for row in seed_rows] or [0]),
        "maxProtectedFalseReleaseRecurrence": max([row["recurrenceCount"] for row in false_release_ledger] or [0]),
        "maxOversupportWorsenedCount": max([row["oversupportWorsenedCount"] for row in seed_rows] or [0]),
        "maxHoldoutRegression": max([row["maxHoldoutRegression"] for row in seed_rows if math.isfinite(row["maxHoldoutRegression"])] or [math.nan]),
        "maxWeakSystematicsLeakage": max([row["weakSystematicsLeakage"] for row in seed_rows] or [0]),
        "formulaFamilyCounts": family_counts,
        "dominantFormulaFamily": max(family_counts, key=family_counts.get) if family_counts else "",
        "dominantFormulaFamilyCount": dominant_count,
        "formulaFamilyStable": dominant_count >= 5,
    }
    failures = []
    if metrics["maxWeakSystematicsLeakage"] != 0:
        failures.append("weak/systematics leakage")
    if metrics["medianCleanHoldoutGainPct"] < 8:
        failures.append("median clean holdout gain < 8%")
    if metrics["medianCleanHighRmseHoldoutGainPct"] < 10:
        failures.append("median clean high-RMSE holdout gain < 10%")
    if metrics["medianLowLoadRouteLockHoldoutGainPct"] < 30:
        failures.append("median low-load route-lock holdout gain < 30%")
    if metrics["medianRouteLockRecallPct"] < 70:
        failures.append("route-lock target recall < 70%")
    if metrics["maxProtectedFalseReleaseCount"] > 1:
        failures.append("protected false releases > 1 in at least one seed")
    if metrics["maxProtectedFalseReleaseRecurrence"] > 1:
        failures.append("protected false release recurs in more than 1 seed")
    if metrics["maxOversupportWorsenedCount"] > 0:
        failures.append("low-load oversupport cases worsen")
    if math.isfinite(metrics["maxHoldoutRegression"]) and metrics["maxHoldoutRegression"] > 8:
        failures.append("max holdout regression > 8 km/s")
    if not math.isfinite(metrics["minAllowedNullLowLoadRouteLockGainMarginPct"]) or metrics["minAllowedNullLowLoadRouteLockGainMarginPct"] < 10:
        failures.append("candidate does not beat allowed random/shuffled/lookalike nulls by 10 points on low-load route-lock gain")
    if not math.isfinite(metrics["medianOracleRecoveryPct"]) or metrics["medianOracleRecoveryPct"] < 60:
        failures.append("candidate recovers < 60% of forbidden route-lock oracle ceiling")
    if not metrics["formulaFamilyStable"]:
        failures.append("selected base law plus safety gate not stable across seed replay")

    if not failures:
        verdict = "promoted for review"
    elif metrics["maxProtectedFalseReleaseCount"] > 1 or metrics["maxProtectedFalseReleaseRecurrence"] > 1 or metrics["maxOversupportWorsenedCount"] > 0:
        verdict = "protected-case failure"
    elif any("null" in failure for failure in failures):
        verdict = "not above allowed null"
    elif not metrics["formulaFamilyStable"]:
        verdict = "promising but not stable"
    else:
        verdict = "safety discriminator not sufficient"
    return verdict, failures, metrics


def v21_safety_formula_from_score(best: dict, seed_rows: list[dict], verdict: str) -> dict:
    return {
        "candidateId": best["candidateId"],
        "reviewStatus": verdict,
        "mechanism": "v21 memory-stretch plus protected-lookalike safety gate",
        "formulaText": "activation = activation0 * safety; if lockedRoute == low-load, L_eff_candidate = L_exact * (1 + beta * activation); otherwise L_eff_candidate = L_exact.",
        "baseRuleText": best["baseRuleText"],
        "safetyRuleText": best["safetyRuleText"],
        "formulaFamily": best["formulaFamily"],
        "gateStyle": best["gateStyle"],
        "safetyStrategy": best["safetyStrategy"],
        "beta": best["beta"],
        "q": Q_DEFAULT,
        "gamma0": GAMMA0,
        "mlDisk": ML_DISK,
        "mlBulge": ML_BULGE,
        "allowedInputs": ["locked route", "boundaryScore", "memoryLoad", "u_0.75", "u_out", "u_max", "u_out/u_max", "u_0.75/u_max", "routeMargin", "routeBreakRisk", "fGasOut"],
        "forbiddenInputs": ["galaxy name", "raw residuals", "raw RMSE as formula input", "q changes", "amplitude patches", "route-lock labels as formula inputs", "weak/systematics fitting"],
        "seedReplayFamilyCounts": v21_safety_family_counts(seed_rows),
    }


def v21_safety_edge_case_rows(rows: list[dict], case_rows: list[dict], false_release_ledger: list[dict]) -> list[dict]:
    names = set(V21_SAFETY_EDGE_CASES)
    names.update(row["name"] for row in false_release_ledger if row["recurrenceCount"] > 0)
    by_case = {row["name"]: row for row in case_rows}
    by_feature = {row["name"]: row for row in rows}
    out = []
    for name in sorted(names):
        row = by_case.get(name)
        feature = by_feature.get(name, {})
        base = {
            "name": name,
            "listedEdgeCase": name in V21_SAFETY_EDGE_CASES,
            "presentInMainCaseLedger": row is not None,
            "lockedRoute": feature.get("lockedRoute", ""),
            "lowloadRouteLockTarget": feature.get("lowloadRouteLockTarget", False),
            "protectedCase": feature.get("protectedCase", False) and not feature.get("lowloadRouteLockTarget", False),
            "failureClass": feature.get("failureClass", ""),
            "noGoClass": feature.get("noGoClass", ""),
        }
        if feature:
            base.update(v21_safety_feature_row(feature))
        if row:
            base.update(
                {
                    "split": row["split"],
                    "baselineRmse": row["baselineRmse"],
                    "candidateRmse": row["candidateRmse"],
                    "delta": row["delta"],
                    "improvement": row["improvement"],
                    "activation": row["activation"],
                    "baseActivation": row["baseActivation"],
                    "safety": row["safety"],
                    "protectedFalseRelease": row["protectedFalseRelease"],
                    "regressionOver8": row["regressionOver8"],
                    "safetyStrategy": row["safetyStrategy"],
                    "safetyRuleText": row["safetyRuleText"],
                }
            )
        out.append(base)
    return out


def v21_safety_report(capsule: dict, score_rows: list[dict], seed_rows: list[dict], case_rows: list[dict], edge_rows: list[dict], oracle_rows: list[dict], null_rows: list[dict]) -> str:
    best = score_rows[0]
    metrics = capsule["decisionMetrics"]
    null_by_type: dict[str, list[dict]] = {}
    for row in null_rows:
        null_by_type.setdefault(row["controlType"], []).append(row)
    lines = [
        "# MTS v21.2 Protected-Lookalike Safety Gate",
        "",
        "This tests whether the v21 memory-stretch branch can be made safe against protected low-load lookalikes. Canonical MTS remains locked.",
        "",
        "## Headline",
        "",
        f"Verdict: **{capsule['verdict']}**.",
        f"Main split best candidate: `{best['candidateId']}`.",
        f"Base: `{best['baseRuleText']}`.",
        f"Safety: `{best['safetyRuleText']}`.",
        f"Weak/systematics leakage: `{capsule['facts']['weakHoldoutLeakage']}`.",
        "",
        "## Acceptance Gate Status",
        "",
        "| Gate | Value |",
        "| --- | ---: |",
        f"| Median clean holdout gain | {fmt(metrics['medianCleanHoldoutGainPct'])}% |",
        f"| Median clean high-RMSE holdout gain | {fmt(metrics['medianCleanHighRmseHoldoutGainPct'])}% |",
        f"| Median low-load route-lock holdout gain | {fmt(metrics['medianLowLoadRouteLockHoldoutGainPct'])}% |",
        f"| Median route-lock recall | {fmt(metrics['medianRouteLockRecallPct'])}% |",
        f"| Min allowed-null low-load gain margin | {fmt(metrics['minAllowedNullLowLoadRouteLockGainMarginPct'])} points |",
        f"| Median forbidden-oracle recovery | {fmt(metrics['medianOracleRecoveryPct'])}% |",
        f"| Max protected false releases | {metrics['maxProtectedFalseReleaseCount']} |",
        f"| Max protected false-release recurrence | {metrics['maxProtectedFalseReleaseRecurrence']} seeds |",
        f"| Max holdout regression | {fmt(metrics['maxHoldoutRegression'])} km/s |",
        f"| Dominant base+safety law | {metrics['dominantFormulaFamily']} ({metrics['dominantFormulaFamilyCount']}/{len(seed_rows)}) |",
        "",
        "## Guardrail Failures",
        "",
    ]
    lines.extend([f"- {failure}" for failure in capsule["guardrailFailures"]] or ["- none"])
    lines.extend(
        [
            "",
            "## Seed Replay",
            "",
            "| Seed | Base family | Gate | Safety | Low-load gain | Recall | Null margin | Oracle recovery | False releases | Max regression |",
            "| ---: | --- | --- | --- | ---: | ---: | ---: | ---: | ---: | ---: |",
        ]
    )
    for row in seed_rows:
        lines.append(
            f"| {row['seed']} | {row['formulaFamily']} | {row['gateStyle']} | {row['safetyStrategy']} | "
            f"{fmt(row['holdoutLowLoadRouteLockGainPct'])}% | {fmt(100 * row['holdoutRouteLockRecall'])}% | "
            f"{fmt(row['allowedNullLowLoadRouteLockGainMarginPct'])} | {fmt(row['oracleRecoveryPct'])}% | "
            f"{row['protectedFalseReleaseCount']} | {fmt(row['maxHoldoutRegression'])} |"
        )
    lines.extend(
        [
            "",
            "## Top Candidate Scores",
            "",
            "| Rank | Base | Safety | Train utility | Clean gain | High-RMSE gain | Low-load gain | Recall | False releases |",
            "| ---: | --- | --- | ---: | ---: | ---: | ---: | ---: | ---: |",
        ]
    )
    for row in score_rows[:25]:
        lines.append(
            f"| {row['rank']} | {row['formulaFamily']}:{row['gateStyle']} | {row['safetyStrategy']} | "
            f"{fmt(row['safetyTrainUtility'])} | {fmt(row['holdoutCleanGainPct'])}% | "
            f"{fmt(row['holdoutPrimaryGainPct'])}% | {fmt(row['holdoutLowLoadRouteLockGainPct'])}% | "
            f"{fmt(100 * row['holdoutRouteLockRecall'])}% | {row['protectedFalseReleaseCount']} |"
        )
    lines.extend(
        [
            "",
            "## Edge Cases",
            "",
            "| Galaxy | Target | Protected | Baseline | Candidate | Delta | Activation | Safety | False release |",
            "| --- | --- | --- | ---: | ---: | ---: | ---: | ---: | --- |",
        ]
    )
    for row in edge_rows:
        lines.append(
            f"| {row['name']} | {row.get('lowloadRouteLockTarget', '')} | {row.get('protectedCase', '')} | "
            f"{fmt(row.get('baselineRmse', math.nan))} | {fmt(row.get('candidateRmse', math.nan))} | "
            f"{fmt(row.get('delta', math.nan))} | {fmt(row.get('activation', math.nan))} | "
            f"{fmt(row.get('safety', math.nan))} | {row.get('protectedFalseRelease', '')} |"
        )
    lines.extend(
        [
            "",
            "## Null And Oracle Controls",
            "",
            "| Control | Rows | Best low-load gain | Best high-RMSE gain | Max regression |",
            "| --- | ---: | ---: | ---: | ---: |",
        ]
    )
    for control_type, grouped in sorted(null_by_type.items()):
        lines.append(
            f"| {control_type} | {len(grouped)} | {fmt(v21_review_null_best(grouped, 'holdoutLowLoadRouteLockGainPct'))}% | "
            f"{fmt(v21_review_null_best(grouped, 'holdoutPrimaryGainPct'))}% | "
            f"{fmt(max([row['maxHoldoutRegression'] for row in grouped if math.isfinite(row['maxHoldoutRegression'])] or [math.nan]))} |"
        )
    lines.extend(
        [
            "",
            "## Formula Discipline",
            "",
            "- The only mechanism is memory-length stretch with a multiplicative safety gate.",
            "- `q`, `Gamma0`, disk M/L, bulge M/L, and scalar amplitude are unchanged.",
            "- Route-lock/protected labels are used only for train-split scoring and validation guardrails, not as formula inputs.",
            "- Weak/systematics cases, galaxy names, raw residuals, and raw RMSE are not formula inputs.",
            "",
            f"Final verdict: **{capsule['verdict']}**.",
            "",
        ]
    )
    return "\n".join(lines)


def write_v21_safety_gate_artifacts(out_dir: Path, curves: list[dict], holdout_fraction: float) -> dict:
    rows, facts = v21_build_rows(curves)
    split = v21_split_rows(rows, SPLIT_SEED, holdout_fraction)
    _base_scores, _base_case_rows, base_candidate = v21_law_candidate_grid(rows, split)
    score_rows, case_rows, _safety = v21_safety_candidate_grid(rows, split, base_candidate)
    seed_rows, null_rows, oracle_rows, seed_case_rows, seed_score_rows, false_release_rows = v21_safety_seed_replay(rows, holdout_fraction)
    if seed_case_rows:
        case_rows = seed_case_rows
    if seed_score_rows:
        score_rows = seed_score_rows
    false_release_ledger = v21_safety_false_release_ledger(rows, false_release_rows)
    edge_rows = v21_safety_edge_case_rows(rows, case_rows, false_release_ledger)
    verdict, failures, decision_metrics = v21_safety_verdict(seed_rows, false_release_ledger)
    best = score_rows[0]
    formula = v21_safety_formula_from_score(best, seed_rows, verdict)
    capsule = {
        "type": "mts-v21-protected-lookalike-safety-gate-v4",
        "version": 4,
        "generatedAt": "deterministic",
        "sourceScript": "scripts/mts-failure-lab.py",
        "canonicalMtsStatus": "locked baseline; v21.2 safety branch only",
        "verdict": verdict,
        "guardrailFailures": failures,
        "decisionMetrics": decision_metrics,
        "bestFormula": formula,
        "facts": facts,
        "seeds": V19_SEEDS,
        "edgeCases": V21_SAFETY_EDGE_CASES,
        "allowedNullControls": sorted(V21_LAW_PROMOTABLE_NULL_TYPES),
        "oracleStatus": "route-lock target oracle is reported as a forbidden ceiling, not a promotable null",
    }
    out_dir.mkdir(parents=True, exist_ok=True)
    write_csv(out_dir / "mts_v21_safety_candidate_scores.csv", score_rows)
    write_csv(out_dir / "mts_v21_safety_seed_replay.csv", seed_rows)
    write_csv(out_dir / "mts_v21_safety_case_ledger.csv", case_rows)
    write_csv(out_dir / "mts_v21_safety_edge_cases.csv", edge_rows)
    write_csv(out_dir / "mts_v21_safety_oracle_gap.csv", oracle_rows)
    write_csv(out_dir / "mts_v21_safety_null_controls.csv", null_rows)
    (out_dir / "mts_v21_safety_formula.json").write_text(json.dumps(json_clean(formula), indent=2), encoding="utf-8")
    report = v21_safety_report(capsule, score_rows, seed_rows, case_rows, edge_rows, oracle_rows, null_rows)
    (out_dir / "mts_v21_safety_report.md").write_text(report, encoding="utf-8")
    (out_dir / "mts_v21_safety_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2), encoding="utf-8")
    return capsule


