def v21_profile_formula_from_score(best: dict, seed_rows: list[dict], verdict: str) -> dict:
    return {
        "candidateId": best["candidateId"],
        "reviewStatus": verdict,
        "mechanism": "v21 memory-stretch plus profile-state safety gate",
        "formulaText": "activation = v21_state_gate * profile_safety_gate; if lockedRoute == low-load, L_eff_candidate = L_exact * (1 + beta * activation); otherwise L_eff_candidate = L_exact.",
        "baseRuleText": best["baseRuleText"],
        "safetyRuleText": best["safetyRuleText"],
        "formulaFamily": best["formulaFamily"],
        "gateStyle": best["gateStyle"],
        "safetyCategory": best["safetyCategory"],
        "safetyStrategy": best["safetyStrategy"],
        "beta": best["beta"],
        "q": Q_DEFAULT,
        "gamma0": GAMMA0,
        "mlDisk": ML_DISK,
        "mlBulge": ML_BULGE,
        "profileInputPath": str(V21_PROFILE_CASES_PATH),
        "allowedInputs": ["locked route", "v21 state gate variables", "pre-residual baryonic/profile descriptors"],
        "forbiddenInputs": ["galaxy name", "raw residuals", "raw RMSE as formula input", "q changes", "amplitude patches", "route-lock labels as formula inputs", "weak/systematics fitting"],
        "seedReplayFamilyCounts": v21_profile_family_counts(seed_rows),
    }


def v21_profile_edge_case_rows(rows: list[dict], case_rows: list[dict], false_release_ledger: list[dict]) -> list[dict]:
    edge_rows = v21_safety_edge_case_rows(rows, case_rows, false_release_ledger)
    by_name = {row["name"]: row for row in rows}
    for item in edge_rows:
        source = by_name.get(item["name"], {})
        if source:
            item.update(v21_profile_feature_row(source))
    return edge_rows


