def v21_frozen_reference_summary() -> dict:
    path = DEFAULT_V21_FULL_PROFILE_OUT / "mts_v21_full_profile_capsule.json"
    if not path.exists():
        return {"status": "missing", "path": str(path)}
    try:
        capsule = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        return {"status": f"unreadable: {exc}", "path": str(path)}
    metrics = capsule.get("decisionMetrics", {})
    facts = capsule.get("facts", {})
    return {
        "status": "loaded",
        "path": str(path),
        "verdict": capsule.get("verdict", ""),
        "profileCoverageCleanCount": facts.get("profileCoverageCleanCount", ""),
        "profileEdgeCasesFinite": facts.get("profileEdgeCasesFinite", ""),
        "profileEdgeCasesExpected": facts.get("profileEdgeCasesExpected", ""),
        "medianCleanHoldoutGainPct": metrics.get("medianCleanHoldoutGainPct"),
        "medianCleanHighRmseHoldoutGainPct": metrics.get("medianCleanHighRmseHoldoutGainPct"),
        "medianLowLoadRouteLockHoldoutGainPct": metrics.get("medianLowLoadRouteLockHoldoutGainPct"),
        "maxProtectedFalseReleaseCount": metrics.get("maxProtectedFalseReleaseCount"),
        "maxHoldoutRegression": metrics.get("maxHoldoutRegression"),
        "minAllowedNullLowLoadRouteLockGainMarginPct": metrics.get("minAllowedNullLowLoadRouteLockGainMarginPct"),
    }


def v21_frozen_base_candidate(track: dict, style: str, beta: float, thresholds: tuple[float, float], rows: list[dict], train_names: set[str]) -> dict:
    rule = tuple(
        (feature, direction, threshold)
        for (feature, direction), threshold in zip(track["base"], thresholds)
    )
    spans = {feature: v21_law_feature_span(rows, train_names, feature) for feature, _direction, _threshold in rule}
    candidate = {
        "rule": rule,
        "beta": beta,
        "gateStyle": style,
        "widthScale": 0.25 if style != "hard" else math.nan,
        "widths": {} if style == "hard" else {feature: max(1e-9, spans[feature] * 0.25) for feature in spans},
        "formulaFamily": f"{track['base'][0][0]}+{track['base'][1][0]}",
        "frozenTrack": track["trackName"],
    }
    candidate["candidateId"] = v21_law_candidate_id(candidate)
    return candidate


def v21_frozen_safety(track: dict, base_candidate: dict, rows: list[dict], train_names: set[str], threshold: float) -> dict:
    feature, direction = track["safety"]
    span = v21_profile_feature_span(rows, train_names, feature)
    safety = {
        "strategy": "profile-continuous-safety-cap",
        "conditions": ((feature, direction, threshold),),
        "widths": {feature: max(1e-9, span * 0.25)},
        "safetyCategory": "profile-only",
        "frozenTrack": track["trackName"],
    }
    safety["safetyRuleText"] = v21_safety_rule_text(safety)
    safety["safetyId"] = v21_profile_safety_id(base_candidate, safety)
    return safety


def v21_frozen_candidate_grid(rows: list[dict], split: dict) -> tuple[list[dict], list[dict], dict, dict]:
    score_rows = []
    ledgers: dict[str, list[dict]] = {}
    base_by_id: dict[str, dict] = {}
    safety_by_id: dict[str, dict] = {}
    score_cache: dict[tuple[str, float], dict] = {}
    for track in V21_FROZEN_TRACKS:
        first_feature = track["base"][0][0]
        second_feature = track["base"][1][0]
        safety_feature = track["safety"][0]
        first_thresholds = v21_profile_threshold_values(rows, split["trainNames"], first_feature, V21_FROZEN_QUANTILES)
        second_thresholds = v21_profile_threshold_values(rows, split["trainNames"], second_feature, V21_FROZEN_QUANTILES)
        safety_thresholds = v21_profile_threshold_values(rows, split["trainNames"], safety_feature, V21_PROFILE_QUANTILES)
        for style in track["gateStyles"]:
            for beta in V21_FROZEN_BETAS:
                for first_threshold in first_thresholds:
                    for second_threshold in second_thresholds:
                        base_candidate = v21_frozen_base_candidate(
                            track,
                            style,
                            beta,
                            (first_threshold, second_threshold),
                            rows,
                            split["trainNames"],
                        )
                        for safety_threshold in safety_thresholds:
                            safety = v21_frozen_safety(track, base_candidate, rows, split["trainNames"], safety_threshold)
                            case_rows = v21_profile_case_rows(rows, split, base_candidate, safety, score_cache=score_cache)
                            metrics = v21_safety_metric_summary(case_rows)
                            record = v21_profile_score_row(0, base_candidate, safety, metrics)
                            record["frozenTrack"] = track["trackName"]
                            record["frozenTrainUtility"] = record["profileTrainUtility"]
                            score_rows.append(record)
                            ledgers[safety["safetyId"]] = case_rows
                            base_by_id[safety["safetyId"]] = base_candidate
                            safety_by_id[safety["safetyId"]] = safety
    score_rows.sort(key=v21_profile_score_sort_key, reverse=True)
    for index, row in enumerate(score_rows, start=1):
        row["rank"] = index
    best = score_rows[0]
    return score_rows, ledgers[best["candidateId"]], base_by_id[best["candidateId"]], safety_by_id[best["candidateId"]]


def v21_frozen_seed_replay(rows: list[dict], holdout_fraction: float) -> tuple[list[dict], list[dict], list[dict], list[dict], list[dict], list[dict], list[dict]]:
    seed_rows = []
    null_rows_all = []
    oracle_rows = []
    harm_rows = []
    false_release_rows = []
    main_case_rows = []
    main_score_rows = []
    for seed in V19_SEEDS:
        split = v21_split_rows(rows, seed, holdout_fraction)
        score_rows, case_rows, base_candidate, safety = v21_frozen_candidate_grid(rows, split)
        best = score_rows[0]
        null_rows, oracle_row, no_safety_row, state_only_row = v21_profile_null_control_rows(
            rows,
            split,
            base_candidate,
            safety,
            case_rows,
            seed=seed + 130000,
        )
        allowed_lowlock_best = v21_safety_best_allowed_null(null_rows, "holdoutLowLoadRouteLockGainPct")
        allowed_primary_best = v21_safety_best_allowed_null(null_rows, "holdoutPrimaryGainPct")
        oracle_recovery = v21_law_oracle_recovery(
            best["holdoutLowLoadRouteLockGainPct"],
            oracle_row["holdoutLowLoadRouteLockGainPct"],
        )
        frozen_family = f"{best['frozenTrack']}:{best['gateStyle']}"
        seed_rows.append(
            {
                "seed": seed,
                "candidateId": best["candidateId"],
                "frozenTrack": best["frozenTrack"],
                "frozenFamily": frozen_family,
                "formulaFamily": best["formulaFamily"],
                "gateStyle": best["gateStyle"],
                "baseRuleText": best["baseRuleText"],
                "safetyStrategy": best["safetyStrategy"],
                "safetyCategory": best["safetyCategory"],
                "safetyRuleText": best["safetyRuleText"],
                "beta": best["beta"],
                "frozenTrainUtility": best["frozenTrainUtility"],
                "holdoutCleanGainPct": best["holdoutCleanGainPct"],
                "holdoutPrimaryGainPct": best["holdoutPrimaryGainPct"],
                "holdoutLowLoadRouteLockGainPct": best["holdoutLowLoadRouteLockGainPct"],
                "holdoutRouteLockRecall": best["holdoutRouteLockRecall"],
                "protectedFalseReleaseCount": best["protectedFalseReleaseCount"],
                "oversupportWorsenedCount": best["oversupportWorsenedCount"],
                "maxHoldoutRegression": best["maxHoldoutRegression"],
                "activeStretchCount": best["activeStretchCount"],
                "activeLowLoadRouteLockCount": best["activeLowLoadRouteLockCount"],
                "activeLowLoadProtectedCount": best["activeLowLoadProtectedCount"],
                "weakSystematicsLeakage": best["weakSystematicsLeakage"],
                "allowedNullLowLoadRouteLockGainBestPct": allowed_lowlock_best,
                "allowedNullLowLoadRouteLockGainMarginPct": best["holdoutLowLoadRouteLockGainPct"] - allowed_lowlock_best if math.isfinite(allowed_lowlock_best) else math.nan,
                "allowedNullCleanHighRmseGainBestPct": allowed_primary_best,
                "allowedNullCleanHighRmseGainMarginPct": best["holdoutPrimaryGainPct"] - allowed_primary_best if math.isfinite(allowed_primary_best) else math.nan,
                "oracleLowLoadRouteLockGainPct": oracle_row["holdoutLowLoadRouteLockGainPct"],
                "oracleRecoveryPct": oracle_recovery,
                "stateOnlyLowLoadRouteLockGainPct": state_only_row["holdoutLowLoadRouteLockGainPct"],
                "stateOnlyProtectedFalseReleaseCount": state_only_row["protectedFalseReleaseCount"],
                "noSafetyLowLoadRouteLockGainPct": no_safety_row["holdoutLowLoadRouteLockGainPct"],
                "noSafetyProtectedFalseReleaseCount": no_safety_row["protectedFalseReleaseCount"],
            }
        )
        oracle_rows.append(
            {
                "seed": seed,
                "candidateId": best["candidateId"],
                "candidateLowLoadRouteLockGainPct": best["holdoutLowLoadRouteLockGainPct"],
                "oracleLowLoadRouteLockGainPct": oracle_row["holdoutLowLoadRouteLockGainPct"],
                "oracleRecoveryPct": oracle_recovery,
                "stateOnlyLowLoadRouteLockGainPct": state_only_row["holdoutLowLoadRouteLockGainPct"],
                "noSafetyLowLoadRouteLockGainPct": no_safety_row["holdoutLowLoadRouteLockGainPct"],
                "oracleProtectedFalseReleaseCount": oracle_row["protectedFalseReleaseCount"],
                "oracleActiveNames": oracle_row["activeNames"],
                "oracleStatus": "forbidden route-lock target oracle ceiling; not promotable",
            }
        )
        for row in case_rows:
            copy = dict(row)
            copy["seed"] = seed
            if row["protectedFalseRelease"]:
                false_release_rows.append(copy)
                harm_rows.append({**copy, "harmType": "protected false release"})
            if row["split"] == "holdout" and row["regressionOver8"]:
                harm_rows.append({**copy, "harmType": "holdout regression over 8 km/s"})
        holdout_rows = [row for row in case_rows if row["split"] == "holdout"]
        if holdout_rows:
            worst = max(holdout_rows, key=lambda item: item["delta"])
            harm_rows.append({**dict(worst), "seed": seed, "harmType": "seed max holdout regression"})
        null_rows_all.extend(null_rows)
        if seed == SPLIT_SEED:
            main_case_rows = case_rows
            main_score_rows = score_rows
    return seed_rows, null_rows_all, oracle_rows, main_case_rows, main_score_rows, false_release_rows, harm_rows


def v21_frozen_family_counts(seed_rows: list[dict]) -> dict:
    counts: dict[str, int] = {}
    for row in seed_rows:
        key = row["frozenFamily"]
        counts[key] = counts.get(key, 0) + 1
    return dict(sorted(counts.items()))


def v21_frozen_false_release_recurrence(rows: list[dict], false_release_rows: list[dict]) -> list[dict]:
    ledger = v21_profile_false_release_ledger(rows, false_release_rows)
    seed_map: dict[str, list[str]] = {}
    for row in false_release_rows:
        seed_map.setdefault(row["name"], []).append(str(row["seed"]))
    for item in ledger:
        item["seeds"] = ";".join(sorted(set(seed_map.get(item["name"], [])), key=lambda value: int(value)))
    return ledger


def v21_frozen_verdict(seed_rows: list[dict], false_release_ledger: list[dict], facts: dict) -> tuple[str, list[str], dict]:
    family_counts = v21_frozen_family_counts(seed_rows)
    dominant_count = max(family_counts.values() or [0])
    metrics = {
        "medianCleanHoldoutGainPct": safe_median(row["holdoutCleanGainPct"] for row in seed_rows),
        "medianCleanHighRmseHoldoutGainPct": safe_median(row["holdoutPrimaryGainPct"] for row in seed_rows),
        "medianLowLoadRouteLockHoldoutGainPct": safe_median(row["holdoutLowLoadRouteLockGainPct"] for row in seed_rows),
        "medianRouteLockRecallPct": 100.0 * safe_median(row["holdoutRouteLockRecall"] for row in seed_rows),
        "minAllowedNullLowLoadRouteLockGainMarginPct": min([row["allowedNullLowLoadRouteLockGainMarginPct"] for row in seed_rows if math.isfinite(row["allowedNullLowLoadRouteLockGainMarginPct"])] or [math.nan]),
        "medianAllowedNullLowLoadRouteLockGainMarginPct": safe_median(row["allowedNullLowLoadRouteLockGainMarginPct"] for row in seed_rows),
        "medianOracleRecoveryPct": safe_median(row["oracleRecoveryPct"] for row in seed_rows),
        "maxProtectedFalseReleaseCount": max([row["protectedFalseReleaseCount"] for row in seed_rows] or [0]),
        "maxProtectedFalseReleaseRecurrence": max([row["recurrenceCount"] for row in false_release_ledger] or [0]),
        "maxOversupportWorsenedCount": max([row["oversupportWorsenedCount"] for row in seed_rows] or [0]),
        "maxHoldoutRegression": max([row["maxHoldoutRegression"] for row in seed_rows if math.isfinite(row["maxHoldoutRegression"])] or [math.nan]),
        "maxWeakSystematicsLeakage": max([row["weakSystematicsLeakage"] for row in seed_rows] or [0]),
        "profileRowsMatched": facts.get("profileRowsMatched", math.nan),
        "profileRowsFinite": facts.get("profileRowsFinite", math.nan),
        "profileEdgeCasesFinite": facts.get("profileEdgeCasesFinite", math.nan),
        "profileEdgeCasesExpected": facts.get("profileEdgeCasesExpected", math.nan),
        "frozenFamilyCounts": family_counts,
        "dominantFrozenFamily": max(family_counts, key=family_counts.get) if family_counts else "",
        "dominantFrozenFamilyCount": dominant_count,
        "frozenFamilyStable": dominant_count >= 5,
    }
    failures = []
    clean_gain_failure = metrics["medianCleanHoldoutGainPct"] < 8
    if round(facts.get("allGalaxyLockedMtsMean", math.nan), 2) != 21.90:
        failures.append("baseline mean differs from 21.90")
    if round(facts.get("cleanSetLockedMtsMean", math.nan), 2) != 19.33:
        failures.append("clean-set baseline differs from 19.33")
    if metrics["maxWeakSystematicsLeakage"] != 0:
        failures.append("weak/systematics leakage")
    if metrics["profileRowsMatched"] != facts.get("cleanCurveCount") or metrics["profileRowsFinite"] != facts.get("cleanCurveCount"):
        failures.append("clean profile coverage is not 160/160")
    if metrics["profileEdgeCasesFinite"] != metrics["profileEdgeCasesExpected"]:
        failures.append("protected lookalike profile coverage is not 6/6")
    if clean_gain_failure:
        failures.append("median clean holdout gain < 8%")
    if metrics["medianCleanHighRmseHoldoutGainPct"] < 10:
        failures.append("median clean high-RMSE holdout gain < 10%")
    if metrics["medianLowLoadRouteLockHoldoutGainPct"] < 30:
        failures.append("median low-load route-lock holdout gain < 30%")
    if metrics["medianRouteLockRecallPct"] < 70:
        failures.append("route-lock target recall < 70%")
    if metrics["maxProtectedFalseReleaseCount"] > 1:
        failures.append("protected false releases > 1 in at least one seed")
    if metrics["maxProtectedFalseReleaseRecurrence"] > 1:
        failures.append("protected false-release galaxy recurs in more than 1 seed")
    if math.isfinite(metrics["maxHoldoutRegression"]) and metrics["maxHoldoutRegression"] > 8:
        failures.append("max holdout regression > 8 km/s")
    if metrics["maxOversupportWorsenedCount"] > 0:
        failures.append("low-load oversupport cases worsen")
    if not math.isfinite(metrics["minAllowedNullLowLoadRouteLockGainMarginPct"]) or metrics["minAllowedNullLowLoadRouteLockGainMarginPct"] < 10:
        failures.append("candidate does not beat random/shuffled/lookalike nulls by 10 points on low-load route-lock gain")
    if not metrics["frozenFamilyStable"]:
        failures.append("selected law family does not appear in at least 5/9 seed replays")

    non_clean_failures = [failure for failure in failures if failure != "median clean holdout gain < 8%"]
    if not failures:
        verdict = "promoted for review"
    elif clean_gain_failure and not non_clean_failures:
        verdict = "conservative frontier candidate"
    elif metrics["maxProtectedFalseReleaseCount"] > 1 or metrics["maxProtectedFalseReleaseRecurrence"] > 1 or metrics["maxOversupportWorsenedCount"] > 0 or (math.isfinite(metrics["maxHoldoutRegression"]) and metrics["maxHoldoutRegression"] > 8):
        verdict = "protected-case failure"
    elif not metrics["frozenFamilyStable"]:
        verdict = "search-selection artifact"
    else:
        verdict = "not above null"
    return verdict, failures, metrics


def v21_frozen_formula(best: dict, seed_rows: list[dict], verdict: str) -> dict:
    return {
        "candidateId": best["candidateId"],
        "reviewStatus": verdict,
        "mechanism": "v21 frozen low-load memory-stretch frontier",
        "formulaText": "activation = frozen_v21_state_gate * frozen_profile_safety_cap; if lockedRoute == low-load, L_eff_candidate = L_exact * (1 + beta * activation); otherwise L_eff_candidate = L_exact.",
        "frozenTrack": best["frozenTrack"],
        "baseRuleText": best["baseRuleText"],
        "safetyRuleText": best["safetyRuleText"],
        "formulaFamily": best["formulaFamily"],
        "gateStyle": best["gateStyle"],
        "safetyStrategy": best["safetyStrategy"],
        "beta": best["beta"],
        "q": Q_DEFAULT,
        "gamma0": GAMMA0,
        "mlDisk": ML_DISK,
        "mlBulge": ML_BULGE,
        "betaGrid": V21_FROZEN_BETAS,
        "frozenTracks": [track["trackName"] for track in V21_FROZEN_TRACKS],
        "allowedInputs": ["locked route", "frozen v21 state gate variables", "pre-residual full-clean profile descriptors"],
        "forbiddenInputs": ["galaxy name", "raw residuals", "raw RMSE as formula input", "q changes", "amplitude patches", "route-lock labels as formula inputs", "weak/systematics fitting"],
        "seedReplayFrozenFamilyCounts": v21_frozen_family_counts(seed_rows),
    }


def v21_frozen_report(capsule: dict, score_rows: list[dict], seed_rows: list[dict], case_rows: list[dict], harm_rows: list[dict], false_release_rows: list[dict], null_rows: list[dict]) -> str:
    best = score_rows[0]
    metrics = capsule["decisionMetrics"]
    reference = capsule["v21_4Reference"]
    top_benefits = sorted([row for row in case_rows if row["lowloadRouteLockTarget"]], key=lambda row: row["improvement"], reverse=True)[:12]
    top_harms = sorted([row for row in case_rows if row["protectedCase"] or row["regressionOver8"] or row["delta"] > 2.0], key=lambda row: row["delta"], reverse=True)[:12]
    lines = [
        "# MTS v21.5 Frozen Frontier + Harm Anatomy",
        "",
        "This freezes the v21 memory-stretch family and tests conservative frontier behavior without open-ended profile safety search. Canonical MTS remains locked.",
        "",
        "## Headline",
        "",
        f"Verdict: **{capsule['verdict']}**.",
        f"Main split best candidate: `{best['candidateId']}`.",
        f"Frozen track: `{best['frozenTrack']}`.",
        f"Base: `{best['baseRuleText']}`.",
        f"Safety: `{best['safetyRuleText']}`.",
        f"Weak/systematics leakage: `{capsule['facts']['weakHoldoutLeakage']}`.",
        f"Profile coverage: `{capsule['facts']['profileCoverageCleanCount']}`.",
        f"Protected lookalike profile coverage: `{capsule['facts']['profileEdgeCasesFinite']}/{capsule['facts']['profileEdgeCasesExpected']}`.",
        "",
        "## v21.4 Search Reference",
        "",
        f"Reference status: `{reference.get('status')}`.",
        f"Reference verdict: `{reference.get('verdict', '')}`.",
        f"Reference low-load gain: `{fmt(parse_float(reference.get('medianLowLoadRouteLockHoldoutGainPct')))}%`.",
        f"Reference max false releases: `{reference.get('maxProtectedFalseReleaseCount', '')}`.",
        "",
        "## Acceptance Gate Status",
        "",
        "| Gate | Value |",
        "| --- | ---: |",
        f"| Median clean holdout gain | {fmt(metrics['medianCleanHoldoutGainPct'])}% |",
        f"| Median clean high-RMSE holdout gain | {fmt(metrics['medianCleanHighRmseHoldoutGainPct'])}% |",
        f"| Median low-load route-lock holdout gain | {fmt(metrics['medianLowLoadRouteLockHoldoutGainPct'])}% |",
        f"| Median route-lock recall | {fmt(metrics['medianRouteLockRecallPct'])}% |",
        f"| Min allowed-null low-load gain margin | {fmt(metrics['minAllowedNullLowLoadRouteLockGainMarginPct'])} points |",
        f"| Median forbidden-oracle recovery | {fmt(metrics['medianOracleRecoveryPct'])}% |",
        f"| Max protected false releases | {metrics['maxProtectedFalseReleaseCount']} |",
        f"| Max protected false-release recurrence | {metrics['maxProtectedFalseReleaseRecurrence']} seeds |",
        f"| Max holdout regression | {fmt(metrics['maxHoldoutRegression'])} km/s |",
        f"| Dominant frozen law family | {metrics['dominantFrozenFamily']} ({metrics['dominantFrozenFamilyCount']}/{len(seed_rows)}) |",
        "",
        "## Guardrail Failures",
        "",
    ]
    lines.extend([f"- {failure}" for failure in capsule["guardrailFailures"]] or ["- none"])
    lines.extend(
        [
            "",
            "## Seed Replay",
            "",
            "| Seed | Frozen family | Safety | Beta | Clean gain | High-RMSE gain | Low-load gain | Recall | Null margin | False releases | Max regression |",
            "| ---: | --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
        ]
    )
    for row in seed_rows:
        lines.append(
            f"| {row['seed']} | {row['frozenFamily']} | {row['safetyRuleText']} | {fmt(row['beta'])} | "
            f"{fmt(row['holdoutCleanGainPct'])}% | {fmt(row['holdoutPrimaryGainPct'])}% | {fmt(row['holdoutLowLoadRouteLockGainPct'])}% | "
            f"{fmt(100 * row['holdoutRouteLockRecall'])}% | {fmt(row['allowedNullLowLoadRouteLockGainMarginPct'])} | "
            f"{row['protectedFalseReleaseCount']} | {fmt(row['maxHoldoutRegression'])} |"
        )
    lines.extend(
        [
            "",
            "## Main Split Benefit/Harm Anatomy",
            "",
            "| Galaxy | Target | Protected | Baseline | Candidate | Improvement | Delta | Activation |",
            "| --- | --- | --- | ---: | ---: | ---: | ---: | ---: |",
        ]
    )
    for row in top_benefits:
        lines.append(
            f"| {row['name']} | {row['lowloadRouteLockTarget']} | {row['protectedCase']} | {fmt(row['baselineRmse'])} | "
            f"{fmt(row['candidateRmse'])} | {fmt(row['improvement'])} | {fmt(row['delta'])} | {fmt(row['activation'])} |"
        )
    lines.extend(["", "| Galaxy | Split | Protected | Baseline | Candidate | Delta | Harm flags |", "| --- | --- | --- | ---: | ---: | ---: | --- |"])
    for row in top_harms:
        flags = []
        if row["protectedFalseRelease"]:
            flags.append("protected false release")
        if row["regressionOver8"]:
            flags.append("regression > 8")
        if row["oversupportWorsened"]:
            flags.append("oversupport worsened")
        lines.append(
            f"| {row['name']} | {row['split']} | {row['protectedCase']} | {fmt(row['baselineRmse'])} | "
            f"{fmt(row['candidateRmse'])} | {fmt(row['delta'])} | {'; '.join(flags)} |"
        )
    lines.extend(
        [
            "",
            "## Harm Ledger Summary",
            "",
            f"- Harm ledger rows: `{len(harm_rows)}`.",
            f"- Protected false-release recurrence rows: `{len(false_release_rows)}`.",
            "",
            "## Formula Discipline",
            "",
            "- The only mechanism is low-load memory-length stretch.",
            "- Frozen tracks remove open-ended feature search freedom.",
            "- `q`, `Gamma0`, disk M/L, bulge M/L, and scalar amplitude are unchanged.",
            "- Weak/systematics cases, galaxy names, raw residuals, and raw RMSE are not formula inputs.",
            "",
            f"Final verdict: **{capsule['verdict']}**.",
            "",
        ]
    )
    return "\n".join(lines)


def write_v21_frozen_frontier_artifacts(out_dir: Path, curves: list[dict], holdout_fraction: float) -> dict:
    rows, facts = v21_full_profile_build_rows(curves)
    split = v21_split_rows(rows, SPLIT_SEED, holdout_fraction)
    score_rows, case_rows, _base, _safety = v21_frozen_candidate_grid(rows, split)
    seed_rows, null_rows, oracle_rows, seed_case_rows, seed_score_rows, false_release_rows, harm_rows = v21_frozen_seed_replay(rows, holdout_fraction)
    if seed_case_rows:
        case_rows = seed_case_rows
    if seed_score_rows:
        score_rows = seed_score_rows
    false_release_ledger = v21_frozen_false_release_recurrence(rows, false_release_rows)
    verdict, failures, decision_metrics = v21_frozen_verdict(seed_rows, false_release_ledger, facts)
    best = score_rows[0]
    formula = v21_frozen_formula(best, seed_rows, verdict)
    capsule = {
        "type": "mts-v21-frozen-frontier-v7",
        "version": 7,
        "generatedAt": "deterministic",
        "sourceScript": "scripts/mts-failure-lab.py",
        "canonicalMtsStatus": "locked baseline; v21.5 frozen frontier only",
        "verdict": verdict,
        "guardrailFailures": failures,
        "decisionMetrics": decision_metrics,
        "bestFormula": formula,
        "facts": facts,
        "v21_4Reference": v21_frozen_reference_summary(),
        "seeds": V19_SEEDS,
        "edgeCases": V21_SAFETY_EDGE_CASES,
        "frozenTracks": V21_FROZEN_TRACKS,
        "allowedNullControls": sorted(V21_LAW_PROMOTABLE_NULL_TYPES),
        "oracleStatus": "route-lock target oracle is reported as a forbidden ceiling, not a promotable null",
    }
    out_dir.mkdir(parents=True, exist_ok=True)
    write_csv(out_dir / "mts_v21_frozen_frontier_candidate_scores.csv", score_rows)
    write_csv(out_dir / "mts_v21_frozen_frontier_seed_replay.csv", seed_rows)
    write_csv(out_dir / "mts_v21_frozen_frontier_case_ledger.csv", case_rows)
    write_csv(out_dir / "mts_v21_frozen_frontier_harm_ledger.csv", harm_rows)
    write_csv(out_dir / "mts_v21_frozen_frontier_false_release_recurrence.csv", false_release_ledger)
    write_csv(out_dir / "mts_v21_frozen_frontier_null_controls.csv", null_rows)
    write_csv(out_dir / "mts_v21_frozen_frontier_oracle_gap.csv", oracle_rows)
    (out_dir / "mts_v21_frozen_frontier_formula.json").write_text(json.dumps(json_clean(formula), indent=2), encoding="utf-8")
    report = v21_frozen_report(capsule, score_rows, seed_rows, case_rows, harm_rows, false_release_ledger, null_rows)
    (out_dir / "mts_v21_frozen_frontier_report.md").write_text(report, encoding="utf-8")
    (out_dir / "mts_v21_frozen_frontier_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2), encoding="utf-8")
    return capsule


