def v21_false_read_pack(source_dir: Path = DEFAULT_V21_FROZEN_FRONTIER_OUT) -> dict:
    return {
        key: read_csv_rows(source_dir / filename)
        for key, filename in V21_FALSE_FRONTIER_FILES.items()
    }


def v21_false_metadata_by_name() -> dict[str, dict]:
    rows = read_csv_rows(DEFAULT_OFFICIAL_SOURCE_FETCH_OUT / "mts-official-source-metadata-prefill.csv")
    table_rows = read_csv_rows(DEFAULT_OFFICIAL_SOURCE_FETCH_OUT / "mts-official-sparc-table1-provenance.csv")
    out = {row.get("name", ""): dict(row) for row in rows if row.get("name")}
    for row in table_rows:
        name = row.get("name", "")
        if not name:
            continue
        out.setdefault(name, {})
        for key in [
            "qualityCode",
            "qualityLabel",
            "rotationCurveRefCodes",
            "rotationCurveReferences",
            "vflatKmS",
            "vflatUncertaintyKmS",
        ]:
            if key in row:
                out[name][key] = row[key]
    return out


def v21_false_quality_code(meta: dict) -> float:
    value = parse_float(meta.get("qualityCode"))
    if math.isfinite(value):
        return value
    match = re.search(r"\bQ\s*=\s*([0-9]+)", meta.get("qualityFlags", ""))
    return float(match.group(1)) if match else math.nan


def v21_false_case_group(row: dict, recurring_false_names: set[str]) -> str:
    name = row["name"]
    if name in recurring_false_names:
        return "recurring protected false release"
    if parse_bool(row.get("lowloadRouteLockTarget")):
        return "true low-load route-lock benefit"
    if parse_bool(row.get("protectedCase")) and row.get("lockedRoute") == "low-load":
        return "protected clean lookalike safe"
    if parse_bool(row.get("protectedCase")):
        return "protected non-low clean case"
    if row.get("lockedRoute") == "low-load":
        return "other low-load clean case"
    return "other clean case"


def v21_false_build_cases(pack: dict) -> tuple[list[dict], dict]:
    recurrence_rows = pack["recurrenceLedger"]
    recurrence_by_name = {row.get("name", ""): row for row in recurrence_rows if row.get("name")}
    recurring_false_names = {
        name
        for name, row in recurrence_by_name.items()
        if parse_float(row.get("recurrenceCount"), 0.0) > 1
    }
    metadata = v21_false_metadata_by_name()
    cases = []
    for row in pack["caseLedger"]:
        name = row.get("name", "")
        if not name or parse_bool(row.get("weakHoldoutExcluded")):
            continue
        meta = metadata.get(name, {})
        recurrence = recurrence_by_name.get(name, {})
        group = v21_false_case_group(row, recurring_false_names)
        item = {
            "name": name,
            "comparisonGroup": group,
            "recurringFalseRelease": name in recurring_false_names,
            "recurrenceCount": parse_float(recurrence.get("recurrenceCount"), 0.0),
            "falseReleaseSeeds": recurrence.get("falseReleaseSeeds", ""),
            "lockedRoute": row.get("lockedRoute", ""),
            "split": row.get("split", ""),
            "primaryCase": parse_bool(row.get("primaryCase")),
            "lowloadRouteLockTarget": parse_bool(row.get("lowloadRouteLockTarget")),
            "protectedCase": parse_bool(row.get("protectedCase")),
            "oversupportCase": parse_bool(row.get("oversupportCase")),
            "baselineRmse": parse_float(row.get("baselineRmse")),
            "candidateRmse": parse_float(row.get("candidateRmse")),
            "improvement": parse_float(row.get("improvement")),
            "delta": parse_float(row.get("delta")),
            "activation": parse_float(row.get("activation")),
            "protectedFalseRelease": parse_bool(row.get("protectedFalseRelease")),
            "regressionOver8": parse_bool(row.get("regressionOver8")),
            "qualityFlags": meta.get("qualityFlags", ""),
            "qualityCode": v21_false_quality_code(meta),
            "qualityLabel": meta.get("qualityLabel", ""),
            "rotationCurveRefCodes": meta.get("rotationCurveRefCodes", ""),
            "inclinationDeg": parse_float(meta.get("inclinationDeg")),
            "inclinationUncertaintyDeg": parse_float(meta.get("inclinationUncertaintyDeg")),
            "distanceUncertaintyMpc": parse_float(meta.get("distanceUncertaintyMpc")),
            "beamFwhmArcsec": parse_float(meta.get("beamFwhmArcsec")),
            "spatialResolutionKpc": parse_float(meta.get("spatialResolutionKpc")),
            "barWarpNonCircularFlags": meta.get("barWarpNonCircularFlags", ""),
            "metadataNotes": meta.get("notes", ""),
        }
        for feature in V21_FALSE_DISTANCE_FEATURES:
            item[feature] = parse_float(row.get(feature))
        cases.append(item)
    facts = {
        "caseLedgerRows": len(pack["caseLedger"]),
        "harmLedgerRows": len(pack["harmLedger"]),
        "recurrenceLedgerRows": len(pack["recurrenceLedger"]),
        "recurringFalseReleaseNames": sorted(recurring_false_names),
        "recurringFalseReleaseCount": len(recurring_false_names),
        "trueRouteLockTargetCount": sum(1 for row in cases if row["lowloadRouteLockTarget"]),
        "protectedLowLoadCount": sum(1 for row in cases if row["protectedCase"] and row["lockedRoute"] == "low-load"),
        "metadataRowsMatched": sum(1 for row in cases if row["name"] in metadata),
        "sourceDir": str(DEFAULT_V21_FROZEN_FRONTIER_OUT),
    }
    return cases, facts


def v21_false_group_contrast_rows(cases: list[dict]) -> list[dict]:
    groups = [
        "recurring protected false release",
        "true low-load route-lock benefit",
        "protected clean lookalike safe",
    ]
    by_group = {group: [row for row in cases if row["comparisonGroup"] == group] for group in groups}
    out = []
    for feature in V21_FALSE_RULE_FEATURES:
        record = {"feature": feature}
        for group in groups:
            values = [parse_float(row.get(feature)) for row in by_group[group]]
            record[group.replace(" ", "_") + "_count"] = len([value for value in values if math.isfinite(value)])
            record[group.replace(" ", "_") + "_median"] = safe_median(values)
            record[group.replace(" ", "_") + "_mean"] = safe_mean(values)
        false_median = record["recurring_protected_false_release_median"]
        target_median = record["true_low-load_route-lock_benefit_median"]
        safe_median_value = record["protected_clean_lookalike_safe_median"]
        record["falseMinusTargetMedian"] = false_median - target_median if math.isfinite(false_median) and math.isfinite(target_median) else math.nan
        record["falseMinusSafeProtectedMedian"] = false_median - safe_median_value if math.isfinite(false_median) and math.isfinite(safe_median_value) else math.nan
        out.append(record)
    return out


def v21_false_feature_scales(rows: list[dict], features: list[str]) -> dict[str, dict]:
    scales = {}
    for feature in features:
        values = [parse_float(row.get(feature)) for row in rows if math.isfinite(parse_float(row.get(feature)))]
        scales[feature] = {
            "mean": safe_mean(values) if values else 0.0,
            "std": statistics.pstdev(values) if len(values) > 1 else 1.0,
        }
        if not math.isfinite(scales[feature]["std"]) or scales[feature]["std"] < 1e-9:
            scales[feature]["std"] = 1.0
    return scales


def v21_false_distance(a: dict, b: dict, features: list[str], scales: dict[str, dict]) -> float:
    total = 0.0
    count = 0
    for feature in features:
        av = parse_float(a.get(feature))
        bv = parse_float(b.get(feature))
        if not math.isfinite(av) or not math.isfinite(bv):
            continue
        std = scales[feature]["std"]
        total += ((av - bv) / std) ** 2
        count += 1
    return math.sqrt(total / count) if count else math.nan


def v21_false_nearest_neighbor_rows(cases: list[dict]) -> list[dict]:
    comparison = [
        row for row in cases
        if row["comparisonGroup"] in {
            "recurring protected false release",
            "true low-load route-lock benefit",
            "protected clean lookalike safe",
        }
    ]
    scales = v21_false_feature_scales(comparison, V21_FALSE_DISTANCE_FEATURES)
    false_rows = [row for row in comparison if row["comparisonGroup"] == "recurring protected false release"]
    out = []
    for false_row in false_rows:
        target_neighbors = [
            (v21_false_distance(false_row, row, V21_FALSE_DISTANCE_FEATURES, scales), row)
            for row in comparison
            if row["comparisonGroup"] == "true low-load route-lock benefit"
        ]
        safe_neighbors = [
            (v21_false_distance(false_row, row, V21_FALSE_DISTANCE_FEATURES, scales), row)
            for row in comparison
            if row["comparisonGroup"] == "protected clean lookalike safe"
        ]
        target_neighbors = sorted((item for item in target_neighbors if math.isfinite(item[0])), key=lambda item: (item[0], item[1]["name"]))
        safe_neighbors = sorted((item for item in safe_neighbors if math.isfinite(item[0])), key=lambda item: (item[0], item[1]["name"]))
        target_distance, target = target_neighbors[0] if target_neighbors else (math.nan, {})
        safe_distance, safe = safe_neighbors[0] if safe_neighbors else (math.nan, {})
        out.append(
            {
                "name": false_row["name"],
                "recurrenceCount": false_row["recurrenceCount"],
                "nearestTrueTarget": target.get("name", ""),
                "nearestTrueTargetDistance": target_distance,
                "nearestSafeProtected": safe.get("name", ""),
                "nearestSafeProtectedDistance": safe_distance,
                "overlapClass": (
                    "closer to true target"
                    if math.isfinite(target_distance) and (not math.isfinite(safe_distance) or target_distance <= safe_distance)
                    else "closer to safe protected"
                ),
                "boundaryScore": false_row.get("boundaryScore"),
                "memoryLoad": false_row.get("memoryLoad"),
                "midGasShare": false_row.get("midGasShare"),
                "midBarToOuterBar": false_row.get("midBarToOuterBar"),
            }
        )
    return out


def v21_false_rule_thresholds(cases: list[dict], feature: str) -> list[float]:
    values = sorted(
        parse_float(row.get(feature))
        for row in cases
        if row["lockedRoute"] == "low-load" and row["comparisonGroup"] in {
            "recurring protected false release",
            "true low-load route-lock benefit",
            "protected clean lookalike safe",
        } and math.isfinite(parse_float(row.get(feature)))
    )
    if not values:
        return []
    return v19_unique_floats([v19_quantile(values, fraction) for fraction in [0.20, 0.33, 0.50, 0.66, 0.80]])


def v21_false_rule_predicts(row: dict, rule: dict) -> bool:
    for feature, direction, threshold in rule["conditions"]:
        value = parse_float(row.get(feature))
        if not math.isfinite(value):
            return False
        if direction == "ge" and value < threshold:
            return False
        if direction == "le" and value > threshold:
            return False
    return True


def v21_false_score_rule(cases: list[dict], rule: dict, false_names: set[str] | None = None) -> dict:
    false_names = false_names if false_names is not None else {row["name"] for row in cases if row["recurringFalseRelease"]}
    true_targets = [row for row in cases if row["lowloadRouteLockTarget"] and row["lockedRoute"] == "low-load"]
    safe_protected = [
        row for row in cases
        if row["comparisonGroup"] == "protected clean lookalike safe" and row["lockedRoute"] == "low-load"
    ]
    false_rows = [row for row in cases if row["name"] in false_names]
    predictions = {row["name"]: v21_false_rule_predicts(row, rule) for row in cases if row["lockedRoute"] == "low-load"}
    false_recall = safe_mean(1.0 if predictions.get(row["name"], False) else 0.0 for row in false_rows)
    true_keep = safe_mean(0.0 if predictions.get(row["name"], False) else 1.0 for row in true_targets)
    safe_keep = safe_mean(0.0 if predictions.get(row["name"], False) else 1.0 for row in safe_protected)
    predicted_false = [name for name, predicted in predictions.items() if predicted]
    precision = (sum(1 for name in predicted_false if name in false_names) / len(predicted_false)) if predicted_false else 0.0
    score = (
        100.0 * (false_recall if math.isfinite(false_recall) else 0.0)
        + 70.0 * (true_keep if math.isfinite(true_keep) else 0.0)
        + 35.0 * (safe_keep if math.isfinite(safe_keep) else 0.0)
        + 20.0 * precision
        - 2.0 * max(0, len(predicted_false) - len(false_names))
    )
    return {
        "falseReleaseRecallPct": 100.0 * false_recall if math.isfinite(false_recall) else math.nan,
        "trueRouteLockTargetKeepRecallPct": 100.0 * true_keep if math.isfinite(true_keep) else math.nan,
        "safeProtectedKeepSpecificityPct": 100.0 * safe_keep if math.isfinite(safe_keep) else math.nan,
        "predictedFalsePrecisionPct": 100.0 * precision,
        "predictedFalseCount": len(predicted_false),
        "predictedFalseNames": ";".join(sorted(predicted_false)),
        "score": score,
    }


def v21_false_rule_text(rule: dict) -> str:
    return " and ".join(f"{feature} {direction} {fmt(threshold)}" for feature, direction, threshold in rule["conditions"])


def v21_false_candidate_rules(cases: list[dict]) -> list[dict]:
    out = []
    feature_thresholds = {feature: v21_false_rule_thresholds(cases, feature) for feature in V21_FALSE_RULE_FEATURES}
    for feature, thresholds in feature_thresholds.items():
        for direction in ["ge", "le"]:
            for threshold in thresholds:
                out.append({"ruleType": "one-variable", "conditions": ((feature, direction, threshold),), "ruleFamily": f"{feature}:{direction}"})
    pair_features = [feature for feature in V21_FALSE_RULE_FEATURES if feature_thresholds.get(feature)]
    for i, first in enumerate(pair_features):
        for second in pair_features[i + 1:]:
            for first_direction in ["ge", "le"]:
                for second_direction in ["ge", "le"]:
                    for first_threshold in feature_thresholds[first]:
                        for second_threshold in feature_thresholds[second]:
                            out.append(
                                {
                                    "ruleType": "two-variable",
                                    "conditions": (
                                        (first, first_direction, first_threshold),
                                        (second, second_direction, second_threshold),
                                    ),
                                    "ruleFamily": f"{first}:{first_direction}+{second}:{second_direction}",
                                }
                            )
    seen = set()
    unique = []
    for rule in out:
        identity = rule["conditions"]
        if identity in seen:
            continue
        seen.add(identity)
        unique.append(rule)
    return unique


def v21_false_separator_rows(cases: list[dict]) -> list[dict]:
    rows = []
    for rule in v21_false_candidate_rules(cases):
        metrics = v21_false_score_rule(cases, rule)
        rows.append(
            {
                "rank": 0,
                "ruleType": rule["ruleType"],
                "ruleFamily": rule["ruleFamily"],
                "ruleText": v21_false_rule_text(rule),
                **metrics,
            }
        )
    rows.sort(
        key=lambda row: (
            row["score"],
            row["falseReleaseRecallPct"],
            row["trueRouteLockTargetKeepRecallPct"],
            row["safeProtectedKeepSpecificityPct"],
            -row["predictedFalseCount"],
            row["ruleText"],
        ),
        reverse=True,
    )
    for index, row in enumerate(rows, start=1):
        row["rank"] = index
    return rows


def v21_false_null_controls(cases: list[dict], rules: list[dict]) -> list[dict]:
    protected_names = sorted(
        row["name"]
        for row in cases
        if row["protectedCase"] and row["lockedRoute"] == "low-load"
    )
    false_count = sum(1 for row in cases if row["recurringFalseRelease"])
    out = []
    for seed in V19_SEEDS:
        rng = random.Random(seed + 170000)
        for iteration in range(20):
            shuffled_false = set(rng.sample(protected_names, min(false_count, len(protected_names))))
            scored = []
            for rule in rules:
                metrics = v21_false_score_rule(cases, rule, shuffled_false)
                scored.append((metrics["score"], metrics, rule))
            scored.sort(key=lambda item: (item[0], item[1]["falseReleaseRecallPct"], item[1]["trueRouteLockTargetKeepRecallPct"]), reverse=True)
            _score, metrics, rule = scored[0]
            out.append(
                {
                    "seed": seed,
                    "iteration": iteration,
                    "controlType": "shuffled-recurring-false-release-label-null",
                    "shuffledFalseNames": ";".join(sorted(shuffled_false)),
                    "bestRuleFamily": rule["ruleFamily"],
                    "bestRuleText": v21_false_rule_text(rule),
                    **metrics,
                }
            )
    return out


def v21_false_seed_stability_rows(cases: list[dict], harm_rows: list[dict], rules: list[dict]) -> list[dict]:
    out = []
    for seed in V19_SEEDS:
        false_names = {
            row.get("name", "")
            for row in harm_rows
            if str(row.get("seed")) == str(seed) and row.get("harmType") == "protected false release"
        }
        if not false_names:
            out.append(
                {
                    "seed": seed,
                    "falseReleaseNames": "",
                    "bestRuleFamily": "none",
                    "bestRuleText": "no protected false release in this seed",
                    "falseReleaseRecallPct": math.nan,
                    "trueRouteLockTargetKeepRecallPct": math.nan,
                    "score": math.nan,
                }
            )
            continue
        scored = []
        for rule in rules:
            metrics = v21_false_score_rule(cases, rule, false_names)
            scored.append((metrics["score"], metrics, rule))
        scored.sort(key=lambda item: (item[0], item[1]["falseReleaseRecallPct"], item[1]["trueRouteLockTargetKeepRecallPct"]), reverse=True)
        _score, metrics, rule = scored[0]
        out.append(
            {
                "seed": seed,
                "falseReleaseNames": ";".join(sorted(false_names)),
                "bestRuleFamily": rule["ruleFamily"],
                "bestRuleText": v21_false_rule_text(rule),
                **metrics,
            }
        )
    return out


def v21_false_metadata_needs(cases: list[dict], neighbor_rows: list[dict]) -> list[dict]:
    neighbor_by_name = {row["name"]: row for row in neighbor_rows}
    out = []
    for row in cases:
        if row["comparisonGroup"] not in {"recurring protected false release", "protected clean lookalike safe"}:
            continue
        missing = []
        if not row.get("barWarpNonCircularFlags"):
            missing.append("bar/warp/non-circular-motion flags")
        if not math.isfinite(row.get("beamFwhmArcsec", math.nan)) and not math.isfinite(row.get("spatialResolutionKpc", math.nan)):
            missing.append("beam/FWHM or spatial-resolution metadata")
        if "covariance" not in str(row.get("metadataNotes", "")).lower():
            missing.append("covariance/error-model provenance")
        if not row.get("rotationCurveRefCodes"):
            missing.append("rotation-curve reference code")
        neighbor = neighbor_by_name.get(row["name"], {})
        out.append(
            {
                "name": row["name"],
                "comparisonGroup": row["comparisonGroup"],
                "recurrenceCount": row["recurrenceCount"],
                "qualityFlags": row.get("qualityFlags", ""),
                "qualityCode": row.get("qualityCode", math.nan),
                "inclinationDeg": row.get("inclinationDeg", math.nan),
                "inclinationUncertaintyDeg": row.get("inclinationUncertaintyDeg", math.nan),
                "rotationCurveRefCodes": row.get("rotationCurveRefCodes", ""),
                "nearestTrueTarget": neighbor.get("nearestTrueTarget", ""),
                "nearestTrueTargetDistance": neighbor.get("nearestTrueTargetDistance", ""),
                "nearestSafeProtected": neighbor.get("nearestSafeProtected", ""),
                "nearestSafeProtectedDistance": neighbor.get("nearestSafeProtectedDistance", ""),
                "missingEvidence": "; ".join(missing),
                "nextEvidenceNeeded": (
                    "fetch morphology/quality notes from source paper and beam/resolution provenance"
                    if missing
                    else "local metadata has basic provenance; inspect source-paper morphology notes if v21 remains active"
                ),
            }
        )
    return out


def v21_false_verdict(cases: list[dict], separator_rows: list[dict], null_rows: list[dict], stability_rows: list[dict], neighbor_rows: list[dict], metadata_rows: list[dict]) -> tuple[str, list[str], dict]:
    best = separator_rows[0] if separator_rows else {}
    max_null_score = max([row["score"] for row in null_rows if math.isfinite(parse_float(row.get("score")))] or [math.nan])
    null_margin = best.get("score", math.nan) - max_null_score if math.isfinite(max_null_score) else math.nan
    family_counts: dict[str, int] = {}
    for row in stability_rows:
        family = row.get("bestRuleFamily", "")
        if family and family != "none":
            family_counts[family] = family_counts.get(family, 0) + 1
    dominant_count = max(family_counts.values() or [0])
    false_closer_to_targets = sum(1 for row in neighbor_rows if row.get("overlapClass") == "closer to true target")
    false_count = sum(1 for row in cases if row["recurringFalseRelease"])
    metadata_missing_count = sum(1 for row in metadata_rows if row["comparisonGroup"] == "recurring protected false release" and row["missingEvidence"])
    metrics = {
        "recurringFalseReleaseCount": false_count,
        "bestRuleText": best.get("ruleText", ""),
        "bestRuleFamily": best.get("ruleFamily", ""),
        "bestFalseReleaseRecallPct": best.get("falseReleaseRecallPct", math.nan),
        "bestTrueRouteLockTargetKeepRecallPct": best.get("trueRouteLockTargetKeepRecallPct", math.nan),
        "bestSafeProtectedKeepSpecificityPct": best.get("safeProtectedKeepSpecificityPct", math.nan),
        "bestScore": best.get("score", math.nan),
        "maxShuffledNullScore": max_null_score,
        "nullScoreMargin": null_margin,
        "dominantSeedRuleFamily": max(family_counts, key=family_counts.get) if family_counts else "",
        "dominantSeedRuleFamilyCount": dominant_count,
        "seedRuleFamilyStable": dominant_count >= 5,
        "falseReleaseCloserToTrueTargetCount": false_closer_to_targets,
        "metadataMissingFalseReleaseCount": metadata_missing_count,
        "weakSystematicsLeakage": sum(1 for row in cases if row.get("weakHoldoutExcluded")),
    }
    failures = []
    if metrics["bestFalseReleaseRecallPct"] < 80:
        failures.append("recurring false-release recall < 80%")
    if metrics["bestTrueRouteLockTargetKeepRecallPct"] < 70:
        failures.append("true route-lock target keep recall < 70%")
    if not math.isfinite(null_margin) or null_margin < 10:
        failures.append("separator does not beat shuffled false-label null by 10 points")
    if not metrics["seedRuleFamilyStable"]:
        failures.append("same discriminator family is not stable across v21.5 seed replays")
    if not failures:
        verdict = "current-vector separable"
    elif false_closer_to_targets >= max(1, math.ceil(false_count / 2)):
        verdict = "false releases are target-overlap"
    elif metadata_missing_count > 0:
        verdict = "metadata discriminator likely needed"
    else:
        verdict = "v21 not promotable from current variables"
    return verdict, failures, metrics


def v21_false_report(capsule: dict, cases: list[dict], contrast_rows: list[dict], neighbor_rows: list[dict], separator_rows: list[dict], metadata_rows: list[dict], null_rows: list[dict], stability_rows: list[dict]) -> str:
    metrics = capsule["decisionMetrics"]
    false_cases = [row for row in cases if row["recurringFalseRelease"]]
    safe_cases = [row for row in cases if row["comparisonGroup"] == "protected clean lookalike safe"]
    top_separator = separator_rows[0] if separator_rows else {}
    lines = [
        "# MTS v21.6 False-Release Anatomy / Missing-Discriminator Audit",
        "",
        "This diagnoses the v21.5 protected false-release failure. It does not test or promote a new MTS law. Canonical MTS remains locked.",
        "",
        "## Headline",
        "",
        f"Verdict: **{capsule['verdict']}**.",
        f"Recurring false releases: `{', '.join(capsule['facts']['recurringFalseReleaseNames'])}`.",
        f"Best separator: `{metrics['bestRuleText']}`.",
        f"False-release recall: `{fmt(metrics['bestFalseReleaseRecallPct'])}%`.",
        f"True target keep recall: `{fmt(metrics['bestTrueRouteLockTargetKeepRecallPct'])}%`.",
        f"Null score margin: `{fmt(metrics['nullScoreMargin'])}`.",
        f"Stable seed family: `{metrics['dominantSeedRuleFamily']}` ({metrics['dominantSeedRuleFamilyCount']}/9).",
        "",
        "## Explicit False-Release Cases",
        "",
        "| Galaxy | Recurrence | Seeds | Boundary score | Memory load | uOut/uMax | Mid gas | Mid bar/outer bar | Metadata need |",
        "| --- | ---: | --- | ---: | ---: | ---: | ---: | ---: | --- |",
    ]
    metadata_by_name = {row["name"]: row for row in metadata_rows}
    for row in false_cases:
        meta = metadata_by_name.get(row["name"], {})
        lines.append(
            f"| {row['name']} | {fmt(row['recurrenceCount'])} | {row['falseReleaseSeeds']} | "
            f"{fmt(row['boundaryScore'])} | {fmt(row['memoryLoad'])} | {fmt(row['uOutOverUMax'])} | "
            f"{fmt(row['midGasShare'])} | {fmt(row['midBarToOuterBar'])} | {meta.get('missingEvidence', '')} |"
        )
    lines.extend(
        [
            "",
            "## Separability",
            "",
            "| Rank | Rule | False recall | True target keep | Safe protected keep | Null-aware note |",
            "| ---: | --- | ---: | ---: | ---: | --- |",
        ]
    )
    for row in separator_rows[:10]:
        note = "candidate" if row.get("ruleText") == top_separator.get("ruleText") else ""
        lines.append(
            f"| {row['rank']} | {row['ruleText']} | {fmt(row['falseReleaseRecallPct'])}% | "
            f"{fmt(row['trueRouteLockTargetKeepRecallPct'])}% | {fmt(row['safeProtectedKeepSpecificityPct'])}% | {note} |"
        )
    lines.extend(
        [
            "",
            "## Nearest-Neighbor Overlap",
            "",
            "| False-release galaxy | Nearest true target | Distance | Nearest safe protected | Distance | Overlap class |",
            "| --- | --- | ---: | --- | ---: | --- |",
        ]
    )
    for row in neighbor_rows:
        lines.append(
            f"| {row['name']} | {row['nearestTrueTarget']} | {fmt(row['nearestTrueTargetDistance'])} | "
            f"{row['nearestSafeProtected']} | {fmt(row['nearestSafeProtectedDistance'])} | {row['overlapClass']} |"
        )
    lines.extend(
        [
            "",
            "## Safe Protected Lookalikes",
            "",
            "| Galaxy | Quality | Inclination | Boundary score | Memory load | Mid gas | Disk concentration |",
            "| --- | --- | ---: | ---: | ---: | ---: | ---: |",
        ]
    )
    for row in safe_cases[:16]:
        lines.append(
            f"| {row['name']} | {row.get('qualityFlags', '')} | {fmt(row.get('inclinationDeg', math.nan))} | "
            f"{fmt(row['boundaryScore'])} | {fmt(row['memoryLoad'])} | {fmt(row['midGasShare'])} | {fmt(row['diskConcentration'])} |"
        )
    lines.extend(
        [
            "",
            "## Group Contrast Highlights",
            "",
            "| Feature | False median | Target median | Safe protected median | False-target delta | False-safe delta |",
            "| --- | ---: | ---: | ---: | ---: | ---: |",
        ]
    )
    for row in contrast_rows[:16]:
        lines.append(
            f"| {row['feature']} | {fmt(row['recurring_protected_false_release_median'])} | "
            f"{fmt(row['true_low-load_route-lock_benefit_median'])} | "
            f"{fmt(row['protected_clean_lookalike_safe_median'])} | "
            f"{fmt(row['falseMinusTargetMedian'])} | {fmt(row['falseMinusSafeProtectedMedian'])} |"
        )
    lines.extend(
        [
            "",
            "## Decision",
            "",
            f"- Current-vector separability failures: {', '.join(capsule['guardrailFailures']) if capsule['guardrailFailures'] else 'none'}.",
            f"- Shuffled-label null rows: `{len(null_rows)}`.",
            f"- Seed stability rows: `{len(stability_rows)}`.",
            "- This audit does not promote v21; it only tells whether the missing safety discriminator is present in current variables.",
            "",
            f"Final verdict: **{capsule['verdict']}**.",
            "",
        ]
    )
    return "\n".join(lines)


def write_v21_false_anatomy_artifacts(out_dir: Path) -> dict:
    pack = v21_false_read_pack(DEFAULT_V21_FROZEN_FRONTIER_OUT)
    cases, facts = v21_false_build_cases(pack)
    contrast_rows = v21_false_group_contrast_rows(cases)
    neighbor_rows = v21_false_nearest_neighbor_rows(cases)
    separator_rows = v21_false_separator_rows(cases)
    rules = v21_false_candidate_rules(cases)
    null_rows = v21_false_null_controls(cases, rules)
    stability_rows = v21_false_seed_stability_rows(cases, pack["harmLedger"], rules)
    metadata_rows = v21_false_metadata_needs(cases, neighbor_rows)
    verdict, failures, metrics = v21_false_verdict(cases, separator_rows, null_rows, stability_rows, neighbor_rows, metadata_rows)
    capsule = {
        "type": "mts-v21-false-release-anatomy-v8",
        "version": 8,
        "generatedAt": "deterministic",
        "sourceScript": "scripts/mts-failure-lab.py",
        "canonicalMtsStatus": "locked baseline; v21.6 false-release anatomy only",
        "verdict": verdict,
        "guardrailFailures": failures,
        "decisionMetrics": metrics,
        "facts": facts,
        "sourceFiles": {key: str(DEFAULT_V21_FROZEN_FRONTIER_OUT / filename) for key, filename in V21_FALSE_FRONTIER_FILES.items()},
        "allowedInputs": ["pre-residual MTS state variables", "full-clean baryonic/profile descriptors", "already-ingested observational metadata"],
        "forbiddenInputs": ["galaxy name as rule input", "raw residuals", "raw RMSE", "q changes", "amplitude patches", "weak/systematics fitting"],
    }
    out_dir.mkdir(parents=True, exist_ok=True)
    write_csv(out_dir / "mts_v21_false_anatomy_cases.csv", cases)
    write_csv(out_dir / "mts_v21_false_anatomy_group_contrast.csv", contrast_rows)
    write_csv(out_dir / "mts_v21_false_anatomy_nearest_neighbors.csv", neighbor_rows)
    write_csv(out_dir / "mts_v21_false_anatomy_separator_rules.csv", separator_rows)
    write_csv(out_dir / "mts_v21_false_anatomy_metadata_needs.csv", metadata_rows)
    write_csv(out_dir / "mts_v21_false_anatomy_null_controls.csv", null_rows)
    write_csv(out_dir / "mts_v21_false_anatomy_seed_stability.csv", stability_rows)
    report = v21_false_report(capsule, cases, contrast_rows, neighbor_rows, separator_rows, metadata_rows, null_rows, stability_rows)
    (out_dir / "mts_v21_false_anatomy_report.md").write_text(report, encoding="utf-8")
    (out_dir / "mts_v21_false_anatomy_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2), encoding="utf-8")
    return capsule


