def cmd_closure(args: argparse.Namespace) -> None:
    curves = build_curves()
    split = stratified_split(curves, args.seed, args.holdout_fraction)
    out_dir = DEFAULT_CLOSURE_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_closure_artifacts(out_dir, curves, split)
    print(f"Loaded {len(curves)} LTG curves; train={len(split['train'])}, holdout={len(split['holdout'])}, seed={args.seed}")
    print("Framework closure roadmap: canonical MTS locked; v13 claim gate controls eligibility")
    print(f"transport_facing_unresolved={capsule['transportFacingCount']}")
    print("CLOSURE POPULATION")
    print("bucket\tcount\thigh_rmse\tpost_shape_failures\tbaseline\tpost_shape\tbest_diagnostic\tbest_robust")
    for row in capsule["populationSummary"]:
        print(
            "\t".join(
                [
                    row["closureBucket"],
                    str(row["count"]),
                    str(row["highRmseCount"]),
                    str(row["postShapeFailureCount"]),
                    fmt(row["baselineMean"]),
                    fmt(row["postShapeMean"]),
                    fmt(row["bestDiagnosticMean"]),
                    fmt(row["bestRobustMean"]),
                ]
            )
        )
    print("CLOSURE HYPOTHESIS MATRIX")
    print("hypothesis\tstatus\teligible\tholdout\tholdout_gain%\troute_keep%\tmetric\tfailures")
    for row in capsule["hypothesisMatrix"]:
        print(
            "\t".join(
                [
                    row["hypothesis"],
                    row["status"],
                    str(row["eligibleCount"]),
                    str(row["holdoutCount"]),
                    fmt(row["holdoutImprovementPct"]),
                    fmt(row["holdoutRoutePreservationRate"] * 100),
                    row["candidateMetric"],
                    row["guardrailFailures"] or "none",
                ]
            )
        )
    print(f"Wrote closure roadmap to {out_dir.resolve()}")


