EXTERNAL_VALIDATION_ZENODO_RECORD = "https://zenodo.org/api/records/19563417"
EXTERNAL_VALIDATION_ARXIV_ABS = "https://arxiv.org/abs/2604.13489"
EXTERNAL_VALIDATION_WALLABY_DR2 = "https://wallaby-survey.org/data/data-pilot-survey-dr2/"
EXTERNAL_VALIDATION_SMALL_FILE_CAP = 5_000_000


def external_validation_name_key(name: str) -> str:
    return re.sub(r"[^A-Z0-9]", "", str(name).upper())


def external_validation_download(url: str, path: Path, *, max_bytes: int, offline: bool) -> tuple[str, int, str]:
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        return "available", path.stat().st_size, file_sha256(path)
    if offline:
        return "missing-offline", 0, ""
    request = urllib.request.Request(url, headers={"User-Agent": "MTS-Galaxy-Lab/1.0 external-validation"})
    try:
        with urllib.request.urlopen(request, timeout=45) as response:
            content_length = response.headers.get("Content-Length")
            if content_length and int(content_length) > max_bytes:
                return "skipped-size-cap", int(content_length), ""
            payload = response.read(max_bytes + 1)
    except (OSError, urllib.error.URLError, urllib.error.HTTPError, TimeoutError):
        try:
            with urllib.request.urlopen(request, timeout=45, context=ssl._create_unverified_context()) as response:
                content_length = response.headers.get("Content-Length")
                if content_length and int(content_length) > max_bytes:
                    return "skipped-size-cap", int(content_length), ""
                payload = response.read(max_bytes + 1)
        except (OSError, urllib.error.URLError, urllib.error.HTTPError, TimeoutError):
            return "fetch-error", 0, ""
    if len(payload) > max_bytes:
        return "skipped-size-cap", len(payload), ""
    path.write_bytes(payload)
    return "available", path.stat().st_size, file_sha256(path)


