def external_validation_fetch_inventory(source_cache: Path, offline: bool) -> list[dict]:
    inventory = []
    for spec in external_validation_base_sources():
        if spec["downloadPolicy"] == "excluded-large-data":
            inventory.append(
                {
                    "sourceId": spec["sourceId"],
                    "sourceName": spec["sourceName"],
                    "survey": spec["survey"],
                    "url": spec["url"],
                    "cachePath": "",
                    "fileType": spec["fileType"],
                    "downloadPolicy": spec["downloadPolicy"],
                    "cacheStatus": "excluded-large-data",
                    "sizeBytes": 0,
                    "sha256": "",
                    "sourceCacheOnD": str(source_cache).upper().startswith("D:"),
                    "notes": "large FITS/cube/archive data intentionally not fetched in v1",
                }
            )
            continue
        path = source_cache / spec["cacheRelativePath"]
        status, size, digest = external_validation_download(spec["url"], path, max_bytes=spec["maxBytes"], offline=offline)
        inventory.append(
            {
                "sourceId": spec["sourceId"],
                "sourceName": spec["sourceName"],
                "survey": spec["survey"],
                "url": spec["url"],
                "cachePath": str(path),
                "fileType": spec["fileType"],
                "downloadPolicy": spec["downloadPolicy"],
                "cacheStatus": status,
                "sizeBytes": size,
                "sha256": digest,
                "sourceCacheOnD": str(source_cache).upper().startswith("D:"),
                "notes": "",
            }
        )

    record_path = source_cache / "unified-hi-corpus" / "zenodo-record-19563417.json"
    record = read_json_if_exists(record_path)
    for file_record in record.get("files", []) if isinstance(record, dict) else []:
        key = file_record.get("key", "")
        size = int(file_record.get("size") or 0)
        suffix = Path(key).suffix.lower()
        link = file_record.get("links", {}).get("self", "")
        allowed_suffix = suffix in {".json", ".csv", ".md", ".txt", ".py", ".docx"}
        cache_path = source_cache / "unified-hi-corpus" / "zenodo-files" / key
        policy = "small corpus file" if allowed_suffix and size <= EXTERNAL_VALIDATION_SMALL_FILE_CAP else "skipped-large-or-archive"
        if policy == "small corpus file":
            status, actual_size, digest = external_validation_download(link, cache_path, max_bytes=EXTERNAL_VALIDATION_SMALL_FILE_CAP, offline=offline)
        else:
            status, actual_size, digest = "skipped-large-or-archive", size, ""
        inventory.append(
            {
                "sourceId": f"zenodo-file-{key}",
                "sourceName": key,
                "survey": "SPARC/THINGS/LITTLE-THINGS/WALLABY",
                "url": link,
                "cachePath": str(cache_path) if policy == "small corpus file" else "",
                "fileType": suffix.lstrip(".") or "unknown",
                "downloadPolicy": policy,
                "cacheStatus": status,
                "sizeBytes": actual_size,
                "sha256": digest,
                "sourceCacheOnD": str(source_cache).upper().startswith("D:"),
                "notes": "Zenodo public corpus file; archives are not needed for scoreability v1",
            }
        )
    return sorted(inventory, key=lambda row: (row["sourceId"], row["sourceName"]))


def external_validation_read_corpus(source_cache: Path) -> tuple[list[dict], dict]:
    corpus_path = source_cache / "unified-hi-corpus" / "zenodo-files" / "rotation_curve_corpus_v7.json"
    if not corpus_path.exists():
        return [], {"status": "missing", "path": str(corpus_path)}
    try:
        payload = json.loads(corpus_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError, UnicodeDecodeError) as exc:
        return [], {"status": f"unreadable: {exc.__class__.__name__}", "path": str(corpus_path)}
    galaxies = payload.get("galaxies", []) if isinstance(payload, dict) else []
    return galaxies if isinstance(galaxies, list) else [], {
        "status": "available",
        "path": str(corpus_path),
        "sha256": file_sha256(corpus_path),
        "metadata": payload.get("metadata", {}) if isinstance(payload, dict) else {},
    }


def external_validation_columns(record: dict) -> set[str]:
    columns = set()
    if isinstance(record.get("columns"), dict):
        columns.update(str(key) for key in record["columns"].keys())
    for point_key in ("data", "rotation_curve"):
        data = record.get(point_key) or []
        if isinstance(data, list):
            for point in data[:3]:
                if isinstance(point, dict):
                    columns.update(str(key) for key in point.keys())
    return columns


def external_validation_has_column(columns: set[str], names: set[str]) -> bool:
    norm = {re.sub(r"[^a-z0-9]", "", col.lower()) for col in columns}
    targets = {re.sub(r"[^a-z0-9]", "", name.lower()) for name in names}
    return bool(norm & targets)


def external_baryon_prefill_rows(path: Path | None) -> list[dict]:
    return read_csv_rows(path) if path and path.exists() else []


def external_baryon_prefill_key(row: dict) -> str:
    return f"{external_validation_name_key(row.get('galaxy', ''))}:{str(row.get('survey', '')).upper()}"


def external_baryon_prefill_map(rows: list[dict]) -> dict[str, dict]:
    return {external_baryon_prefill_key(row): row for row in rows if row.get("galaxy") and row.get("survey")}


def external_validation_scoreability_rows(
    galaxies: list[dict],
    curves: list[dict],
    external_baryon_rows: list[dict] | None = None,
) -> list[dict]:
    local_by_key = {external_validation_name_key(curve["name"]): curve["name"] for curve in curves}
    external_baryon_by_key = external_baryon_prefill_map(external_baryon_rows or [])
    out = []
    for record in galaxies:
        name = str(record.get("galaxy") or record.get("name") or "").strip()
        survey = str(record.get("survey") or "unknown").strip() or "unknown"
        columns = external_validation_columns(record)
        data = record.get("data") or record.get("rotation_curve") or []
        has_radius = external_validation_has_column(columns, {"Rad", "R", "radius", "radius_kpc", "r_kpc", "rad_kpc"})
        has_velocity = external_validation_has_column(columns, {"Vobs", "Vrot", "Vrot_kms", "velocity", "v_circ", "vrot_kms"})
        has_error = external_validation_has_column(columns, {"errV", "e_Vobs", "Verr", "eVrot", "velocity_error"})
        has_vgas = external_validation_has_column(columns, {"Vgas", "V_gas", "vgas"})
        has_vdisk = external_validation_has_column(columns, {"Vdisk", "V_disk", "vdisk"})
        has_vbul = external_validation_has_column(columns, {"Vbul", "V_bul", "vbul", "Vbulge"})
        has_surface_brightness = external_validation_has_column(columns, {"SBdisk", "SBbul", "surface_brightness"})
        has_scale_state = external_validation_has_column(columns, {"h", "h_kpc", "scale_length", "scaleLength", "r_out_over_h"}) or (
            survey.upper() == "SPARC" and external_validation_name_key(name) in local_by_key
        )
        has_point_curve = isinstance(data, list) and len(data) > 0 and has_radius and has_velocity
        prefill = external_baryon_by_key.get(f"{external_validation_name_key(name)}:{survey.upper()}", {})
        if prefill:
            has_error = has_error or parse_bool(prefill.get("hasVelocityUncertainty"))
            has_vgas = has_vgas or parse_bool(prefill.get("hasVgas"))
            has_vdisk = has_vdisk or parse_bool(prefill.get("hasVdisk"))
            has_vbul = has_vbul or parse_bool(prefill.get("hasVbul"))
            has_scale_state = has_scale_state or parse_bool(prefill.get("hasMtsStateScale"))
        has_baryonic_components = has_vgas and has_vdisk
        local_match = local_by_key.get(external_validation_name_key(name), "")
        missing = []
        if not has_radius:
            missing.append("radius")
        if not has_velocity:
            missing.append("observedVelocity")
        if not has_error:
            missing.append("velocityUncertainty")
        if not has_vgas:
            missing.append("Vgas")
        if not has_vdisk:
            missing.append("Vdisk")
        if not has_scale_state:
            missing.append("MTSStateScale_h_or_localState")
        if has_point_curve and has_error and has_baryonic_components and has_scale_state:
            scoreability = "full MTS-scoreable"
        elif has_point_curve:
            scoreability = "kinematic-only"
        else:
            scoreability = "metadata-only"
        independent = survey.upper() != "SPARC"
        evidence_role = "non-SPARC independent validation row" if independent else "SPARC overlap/control row"
        out.append(
            {
                "galaxy": name,
                "survey": survey,
                "reference": record.get("reference", ""),
                "evidenceRole": evidence_role,
                "scoreability": scoreability,
                "canScoreMts": scoreability == "full MTS-scoreable",
                "isNonSparc": independent,
                "localSparcMatch": local_match,
                "nPoints": int(record.get("n_points") or len(data) or 0),
                "hasRadius": has_radius,
                "hasObservedVelocity": has_velocity,
                "hasVelocityUncertainty": has_error,
                "hasVgas": has_vgas,
                "hasVdisk": has_vdisk,
                "hasVbulOptional": has_vbul,
                "hasSurfaceBrightness": has_surface_brightness,
                "hasMtsStateScale": has_scale_state,
                "qualityTier": record.get("quality_tier", ""),
                "distanceMpc": record.get("distance_Mpc", record.get("distance_mpc", "")),
                "inclinationDeg": record.get("inc_deg", ""),
                "dataColumns": ";".join(sorted(columns)),
                "missingInputs": ";".join(missing),
                "sourceFile": "rotation_curve_corpus_v7.json",
                "externalBaryonPrefill": bool(prefill),
                "externalBaryonVerdict": prefill.get("scoreabilityVerdict", ""),
                "externalBaryonSource": prefill.get("provenanceUrlOrPath", ""),
                "frameworkEvidenceAllowed": scoreability == "full MTS-scoreable" and independent,
            }
        )
    return sorted(out, key=lambda row: (str(row["survey"]), str(row["galaxy"])))


def external_validation_survey_summary(scoreability_rows: list[dict]) -> list[dict]:
    surveys = sorted({row["survey"] for row in scoreability_rows})
    out = []
    for survey in surveys:
        rows = [row for row in scoreability_rows if row["survey"] == survey]
        out.append(
            {
                "survey": survey,
                "galaxyCount": len(rows),
                "fullMtsScoreable": sum(1 for row in rows if row["scoreability"] == "full MTS-scoreable"),
                "kinematicOnly": sum(1 for row in rows if row["scoreability"] == "kinematic-only"),
                "metadataOnly": sum(1 for row in rows if row["scoreability"] == "metadata-only"),
                "nonSparcIndependentRows": sum(1 for row in rows if row["isNonSparc"]),
                "frameworkEvidenceAllowed": sum(1 for row in rows if row["frameworkEvidenceAllowed"]),
                "commonMissingInputs": ";".join(
                    f"{key}:{value}"
                    for key, value in sorted(
                        {
                            item: sum(1 for row in rows if item and item in str(row["missingInputs"]).split(";"))
                            for item in sorted({item for row in rows for item in str(row["missingInputs"]).split(";") if item})
                        }.items()
                    )
                ),
            }
        )
    return out


def external_validation_missing_input_rows(scoreability_rows: list[dict]) -> list[dict]:
    out = []
    for row in scoreability_rows:
        for missing in [item for item in str(row["missingInputs"]).split(";") if item]:
            out.append(
                {
                    "galaxy": row["galaxy"],
                    "survey": row["survey"],
                    "scoreability": row["scoreability"],
                    "missingInput": missing,
                    "frameworkEvidenceAllowed": row["frameworkEvidenceAllowed"],
                    "sourceFile": row["sourceFile"],
                }
            )
    return out


def external_validation_load_v21_quality_rows(curves: list[dict]) -> tuple[list[dict], list[dict], dict]:
    score_path = DEFAULT_V21_QUALITY_GATE_OUT / "mts_v21_quality_gate_candidate_scores.csv"
    case_path = DEFAULT_V21_QUALITY_GATE_OUT / "mts_v21_quality_gate_case_ledger.csv"
    capsule_path = DEFAULT_V21_QUALITY_GATE_OUT / "mts_v21_quality_gate_capsule.json"
    score_rows = read_csv_rows(score_path)
    case_rows = read_csv_rows(case_path)
    capsule = read_json_if_exists(capsule_path)
    if score_rows and case_rows and capsule:
        return score_rows, case_rows, capsule
    capsule = write_v21_quality_gate_artifacts(DEFAULT_V21_QUALITY_GATE_OUT, curves, HOLDOUT_FRACTION)
    return (
        read_csv_rows(score_path),
        read_csv_rows(case_path),
        read_json_if_exists(capsule_path) or capsule,
    )


def external_validation_case_ledger(
    scoreability_rows: list[dict],
    curves: list[dict],
    v21_case_rows: list[dict],
) -> list[dict]:
    local_by_key = {external_validation_name_key(curve["name"]): curve for curve in curves}
    v21_by_name = {row.get("name", ""): row for row in v21_case_rows}
    out = []
    for row in scoreability_rows:
        local_name = row.get("localSparcMatch", "")
        curve = local_by_key.get(external_validation_name_key(row["galaxy"]))
        v21 = v21_by_name.get(local_name, {})
        baseline_rmse = parse_float(v21.get("baselineRmse"))
        candidate_rmse = parse_float(v21.get("candidateRmse"))
        out.append(
            {
                "galaxy": row["galaxy"],
                "survey": row["survey"],
                "evidenceRole": row["evidenceRole"],
                "scoreability": row["scoreability"],
                "frameworkEvidenceAllowed": row["frameworkEvidenceAllowed"],
                "localSparcMatch": local_name,
                "candidateScored": bool(v21),
                "canonicalRmse": baseline_rmse if math.isfinite(baseline_rmse) else "",
                "frozenV21Rmse": candidate_rmse if math.isfinite(candidate_rmse) else "",
                "frozenV21GainPct": pct_improvement(baseline_rmse, candidate_rmse) if math.isfinite(baseline_rmse) and math.isfinite(candidate_rmse) else "",
                "lockedRoute": v21.get("lockedRoute", ""),
                "candidateRoute": v21.get("candidateRoute", ""),
                "qualityGroup": v21.get("qualityGroup", row.get("qualityTier", "")),
                "weakOrProtectedInternal": bool(curve) and not bool(v21),
                "missingInputs": row["missingInputs"],
                "notes": "SPARC overlap scored only as control" if row["survey"].upper() == "SPARC" and v21 else "not scored as framework evidence",
            }
        )
    return out


def external_validation_candidate_score_rows(
    scoreability_rows: list[dict],
    v21_score_rows: list[dict],
    v21_case_rows: list[dict],
    v21_capsule: dict,
) -> list[dict]:
    non_sparc_full = [row for row in scoreability_rows if row["isNonSparc"] and row["scoreability"] == "full MTS-scoreable"]
    sparc_cases = [row for row in v21_case_rows if row.get("weakHoldoutExcluded") in {False, "False", "false", "0", 0, ""}]
    baseline_mean = safe_mean(parse_float(row.get("baselineRmse")) for row in sparc_cases)
    candidate_mean = safe_mean(parse_float(row.get("candidateRmse")) for row in sparc_cases)
    top = v21_score_rows[0] if v21_score_rows else {}
    return [
        {
            "candidateId": "canonical-locked-mts",
            "evaluationSet": "SPARC-overlap-clean-control",
            "frameworkEvidenceAllowed": False,
            "caseCount": len(sparc_cases),
            "meanRmse": baseline_mean,
            "candidateMeanRmse": baseline_mean,
            "gainPct": 0.0,
            "status": "control-only",
            "notes": "Internal SPARC control; not independent external evidence.",
        },
        {
            "candidateId": top.get("candidateId", "frozen-v21-quality-reference"),
            "evaluationSet": "SPARC-overlap-clean-control",
            "frameworkEvidenceAllowed": False,
            "caseCount": len(sparc_cases),
            "meanRmse": baseline_mean,
            "candidateMeanRmse": candidate_mean,
            "gainPct": pct_improvement(baseline_mean, candidate_mean),
            "status": v21_capsule.get("verdict", ""),
            "notes": "Frozen v21.9 reference replayed only on SPARC overlap/control rows.",
        },
        {
            "candidateId": "frozen-v21-external-independent",
            "evaluationSet": "non-SPARC-independent-full-MTS-scoreable",
            "frameworkEvidenceAllowed": bool(len(non_sparc_full) >= 20),
            "caseCount": len(non_sparc_full),
            "meanRmse": "",
            "candidateMeanRmse": "",
            "gainPct": "",
            "status": "insufficient external scoreable data" if len(non_sparc_full) < 20 else "not evaluated in v1 harness",
            "notes": "No v21 promotion unless at least 20 non-SPARC galaxies have full MTS scoring inputs.",
        },
    ]


def external_validation_null_rows(scoreability_rows: list[dict], v21_null_rows: list[dict]) -> list[dict]:
    non_sparc_full = sum(1 for row in scoreability_rows if row["isNonSparc"] and row["scoreability"] == "full MTS-scoreable")
    out = []
    for row in v21_null_rows[:120]:
        out.append(
            {
                "controlType": row.get("controlType", ""),
                "evaluationSet": "SPARC-overlap-clean-control",
                "frameworkEvidenceAllowed": False,
                "holdoutLowLoadRouteLockGainPct": row.get("holdoutLowLoadRouteLockGainPct", ""),
                "holdoutPrimaryGainPct": row.get("holdoutPrimaryGainPct", ""),
                "protectedFalseReleaseCount": row.get("protectedFalseReleaseCount", ""),
                "maxHoldoutRegression": row.get("maxHoldoutRegression", ""),
                "notes": "Internal SPARC null, retained only as control context.",
            }
        )
    if non_sparc_full < 20:
        out.append(
            {
                "controlType": "survey-stratified-external-null",
                "evaluationSet": "non-SPARC-independent-full-MTS-scoreable",
                "frameworkEvidenceAllowed": False,
                "holdoutLowLoadRouteLockGainPct": "",
                "holdoutPrimaryGainPct": "",
                "protectedFalseReleaseCount": "",
                "maxHoldoutRegression": "",
                "notes": "Not run because non-SPARC full MTS-scoreable count is below 20.",
            }
        )
    return out


def external_validation_report(capsule: dict, survey_rows: list[dict], candidate_rows: list[dict]) -> str:
    metrics = capsule["metrics"]
    source = capsule["sourceCorpus"]
    survey_lines = [
        f"- {row['survey']}: {row['galaxyCount']} galaxies, {row['fullMtsScoreable']} full MTS-scoreable, "
        f"{row['kinematicOnly']} kinematic-only, {row['frameworkEvidenceAllowed']} independent framework rows."
        for row in survey_rows
    ]
    candidate_lines = [
        f"- {row['candidateId']}: set={row['evaluationSet']}, cases={row['caseCount']}, status={row['status']}."
        for row in candidate_rows
    ]
    return "\n".join(
        [
            "# MTS v21.10 External Scoreability / High-Quality Validation Harness",
            "",
            "Canonical MTS remains locked. Frozen v21 memory stretch is replayed only where the required inputs exist; no new q, amplitude, residual, RMSE, or galaxy-name rule is introduced.",
            "",
            f"Verdict: **{capsule['verdict']}**",
            "",
            "## Source Cache",
            "",
            f"- Source cache: `{capsule['sourceCache']}`",
            f"- Source cache on D: `{metrics['sourceCacheOnDDrive']}`",
            f"- Large downloads: `{metrics['largeDownloadCount']}`",
            f"- Unified corpus status: `{source.get('status', '')}`",
            f"- Unified corpus file: `{source.get('path', '')}`",
            "",
            "## Scoreability",
            "",
            f"- Corpus galaxies: `{metrics['corpusGalaxyCount']}`",
            f"- Full MTS-scoreable rows: `{metrics['fullMtsScoreableCount']}`",
            f"- Non-SPARC full MTS-scoreable rows: `{metrics['nonSparcFullMtsScoreableCount']}`",
            f"- Kinematic-only rows: `{metrics['kinematicOnlyCount']}`",
            f"- Metadata-only rows: `{metrics['metadataOnlyCount']}`",
            "",
            "## Survey Summary",
            "",
            *survey_lines,
            "",
            "## Candidate / Control Scores",
            "",
            *candidate_lines,
            "",
            "## External Validation Interpretation",
            "",
            "Rows with rotation curves but without baryonic component and MTS state inputs are reported as kinematic-only and are not counted as MTS framework evidence. SPARC overlap rows are controls, not independent validation. If the non-SPARC full-scoreable count is below 20, the harness intentionally stops at scoreability and reports insufficient external scoreable data.",
            "",
            "## Guardrail Status",
            "",
            f"- Baseline all-galaxy mean: `{metrics['allGalaxyLockedMtsMean']}`",
            f"- v21.9 verdict carried forward: `{metrics['v21QualityVerdict']}`",
            f"- Weak/systematics leakage: `{metrics['weakSystematicsLeakage']}`",
            f"- External review candidate: `{metrics['externalReviewCandidate']}`",
        ]
    )


def write_external_validation_artifacts(
    out_dir: Path,
    source_cache: Path,
    curves: list[dict],
    offline: bool,
    external_baryon_file: Path | None = None,
) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    source_cache.mkdir(parents=True, exist_ok=True)
    inventory_rows = external_validation_fetch_inventory(source_cache, offline)
    corpus_galaxies, corpus_info = external_validation_read_corpus(source_cache)
    external_baryon_rows = external_baryon_prefill_rows(external_baryon_file)
    scoreability_rows = external_validation_scoreability_rows(corpus_galaxies, curves, external_baryon_rows)
    survey_rows = external_validation_survey_summary(scoreability_rows)
    missing_rows = external_validation_missing_input_rows(scoreability_rows)
    v21_score_rows, v21_case_rows, v21_capsule = external_validation_load_v21_quality_rows(curves)
    v21_null_rows = read_csv_rows(DEFAULT_V21_QUALITY_GATE_OUT / "mts_v21_quality_gate_null_controls.csv")
    case_rows = external_validation_case_ledger(scoreability_rows, curves, v21_case_rows)
    candidate_rows = external_validation_candidate_score_rows(scoreability_rows, v21_score_rows, v21_case_rows, v21_capsule)
    null_rows = external_validation_null_rows(scoreability_rows, v21_null_rows)

    baseline = baseline_summary(curves)
    non_sparc_full = [row for row in scoreability_rows if row["isNonSparc"] and row["scoreability"] == "full MTS-scoreable"]
    full_scoreable = [row for row in scoreability_rows if row["scoreability"] == "full MTS-scoreable"]
    kinematic = [row for row in scoreability_rows if row["scoreability"] == "kinematic-only"]
    metadata = [row for row in scoreability_rows if row["scoreability"] == "metadata-only"]
    large_downloads = [row for row in inventory_rows if row["downloadPolicy"] == "excluded-large-data" and row["cacheStatus"] != "excluded-large-data"]
    weak_leakage = parse_float(v21_capsule.get("facts", {}).get("weakHoldoutLeakage"), 0.0)
    v21_verdict = v21_capsule.get("verdict", "")
    verdict = "insufficient external scoreable data" if len(non_sparc_full) < 20 else "external scoreability ready; scoring needed"

    metrics = {
        "allGalaxyLockedMtsMean": round(baseline["baselineMean"], 2),
        "sourceCacheOnDDrive": str(source_cache).upper().startswith("D:"),
        "inventoryCount": len(inventory_rows),
        "cachedAvailableCount": sum(1 for row in inventory_rows if row["cacheStatus"] == "available"),
        "largeDownloadCount": len(large_downloads),
        "corpusGalaxyCount": len(corpus_galaxies),
        "fullMtsScoreableCount": len(full_scoreable),
        "nonSparcFullMtsScoreableCount": len(non_sparc_full),
        "kinematicOnlyCount": len(kinematic),
        "metadataOnlyCount": len(metadata),
        "externalBaryonPrefillRows": len(external_baryon_rows),
        "externalBaryonPrefillPath": str(external_baryon_file) if external_baryon_file else "",
        "weakSystematicsLeakage": int(weak_leakage),
        "v21QualityVerdict": v21_verdict,
        "externalReviewCandidate": verdict != "insufficient external scoreable data",
    }
    suffix = "_v2" if external_baryon_file else ""
    capsule = {
        "mode": "externalvalidate",
        "createdUtc": "deterministic",
        "verdict": verdict,
        "sourceCache": str(source_cache.resolve()),
        "externalBaryonFile": str(external_baryon_file.resolve()) if external_baryon_file else "",
        "sourceCorpus": corpus_info,
        "metrics": metrics,
        "acceptanceGates": {
            "nonSparcFullMtsScoreableAtLeast20": len(non_sparc_full) >= 20,
            "weakSystematicsLeakageZero": int(weak_leakage) == 0,
            "largeDownloadCountZero": len(large_downloads) == 0,
            "v21QualityGatePriorVerdict": v21_verdict,
        },
        "outputs": {
            "inventory": f"mts_external_validation_inventory{suffix}.csv",
            "scoreability": f"mts_external_validation_scoreability{suffix}.csv",
            "caseLedger": f"mts_external_validation_case_ledger{suffix}.csv",
            "surveySummary": f"mts_external_validation_survey_summary{suffix}.csv",
            "candidateScores": f"mts_external_validation_candidate_scores{suffix}.csv",
            "nullControls": f"mts_external_validation_null_controls{suffix}.csv",
            "missingInputs": f"mts_external_validation_missing_inputs{suffix}.csv",
            "report": f"mts_external_validation_report{suffix}.md",
        },
    }

    write_csv(out_dir / f"mts_external_validation_inventory{suffix}.csv", inventory_rows)
    write_csv(out_dir / f"mts_external_validation_scoreability{suffix}.csv", scoreability_rows)
    write_csv(out_dir / f"mts_external_validation_case_ledger{suffix}.csv", case_rows)
    write_csv(out_dir / f"mts_external_validation_survey_summary{suffix}.csv", survey_rows)
    write_csv(out_dir / f"mts_external_validation_candidate_scores{suffix}.csv", candidate_rows)
    write_csv(out_dir / f"mts_external_validation_null_controls{suffix}.csv", null_rows)
    write_csv(out_dir / f"mts_external_validation_missing_inputs{suffix}.csv", missing_rows)
    (out_dir / f"mts_external_validation_report{suffix}.md").write_text(
        external_validation_report(capsule, survey_rows, candidate_rows),
        encoding="utf-8",
    )
    (out_dir / "mts_external_validation_capsule.json").write_text(
        json.dumps(json_clean(capsule), indent=2, sort_keys=True),
        encoding="utf-8",
    )
    return capsule


def cmd_externalvalidate(args: argparse.Namespace) -> None:
    curves = build_curves()
    out_dir = DEFAULT_EXTERNAL_VALIDATION_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    source_cache = Path(args.source_cache) if args.source_cache else DEFAULT_EXTERNAL_VALIDATION_CACHE
    external_baryon_file = Path(args.external_baryon_file) if args.external_baryon_file else None
    capsule = write_external_validation_artifacts(out_dir, source_cache, curves, args.offline, external_baryon_file)
    metrics = capsule["metrics"]
    print("MTS v21.10 external scoreability / validation harness: canonical MTS locked")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"all_mean={fmt(metrics['allGalaxyLockedMtsMean'])}",
                f"corpus={metrics['corpusGalaxyCount']}",
                f"full_scoreable={metrics['fullMtsScoreableCount']}",
                f"non_sparc_full={metrics['nonSparcFullMtsScoreableCount']}",
                f"kinematic_only={metrics['kinematicOnlyCount']}",
                f"metadata_only={metrics['metadataOnlyCount']}",
                f"weak_leakage={metrics['weakSystematicsLeakage']}",
                f"large_downloads={metrics['largeDownloadCount']}",
                f"source_cache_on_d={metrics['sourceCacheOnDDrive']}",
            ]
        )
    )
    print(f"source_cache={source_cache.resolve()}")
    print(f"Wrote MTS v21.10 external validation pack to {out_dir.resolve()}")


EXTERNAL_BARYON_LITTLE_CDS_SOURCE = "J/AJ/149/180"
EXTERNAL_BARYON_LITTLE_VIZIER_TSV = "https://vizier.cds.unistra.fr/viz-bin/asu-tsv"
EXTERNAL_BARYON_LITTLE_README_HTML = "https://cdsarc.cds.unistra.fr/viz-bin/ReadMe/J/AJ/149/180?format=html&tex=true"
EXTERNAL_BARYON_LITTLE_ARXIV = "1502.01281"
EXTERNAL_BARYON_THINGS_ARXIV = "0810.2100"
EXTERNAL_BARYON_SOURCE_CAP = 20_000_000


def external_baryon_source_specs() -> list[dict]:
    little_files = ["ReadMe", "galaxies.dat", "rotdmbar.dat", "dendmbar.dat", "rotdm.dat", "dendm.dat", "nfwac.dat", "nfwbd.dat"]
    specs = [
        {
            "sourceId": "little-things-cds-readme-html",
            "sourceName": "LITTLE THINGS VizieR catalogue metadata TSV",
            "survey": "LITTLE_THINGS",
            "url": f"{EXTERNAL_BARYON_LITTLE_VIZIER_TSV}?-source={urllib.parse.quote(EXTERNAL_BARYON_LITTLE_CDS_SOURCE)}&-out.max=0",
            "cacheRelativePath": "little-things-cds/ReadMe.html",
            "fileType": "tsv",
            "maxBytes": 2_000_000,
            "downloadPolicy": "small CDS/VizieR metadata query",
        }
    ]
    for file_name in little_files:
        table_name = Path(file_name).stem if file_name != "ReadMe" else ""
        source = EXTERNAL_BARYON_LITTLE_CDS_SOURCE if file_name == "ReadMe" else f"{EXTERNAL_BARYON_LITTLE_CDS_SOURCE}/{table_name}"
        specs.append(
            {
                "sourceId": f"little-things-cds-{safe_file_stem(file_name)}",
                "sourceName": f"LITTLE THINGS CDS table {file_name}",
                "survey": "LITTLE_THINGS",
                "url": f"{EXTERNAL_BARYON_LITTLE_VIZIER_TSV}?-source={urllib.parse.quote(source)}&-out.all",
                "cacheRelativePath": f"little-things-cds/{file_name}",
                "fileType": "tsv",
                "maxBytes": 5_000_000,
                "downloadPolicy": "small CDS/VizieR TSV table",
            }
        )
    for arxiv_id, survey, label in [
        (EXTERNAL_BARYON_LITTLE_ARXIV, "LITTLE_THINGS", "LITTLE THINGS mass-model paper"),
        (EXTERNAL_BARYON_THINGS_ARXIV, "THINGS", "THINGS mass-model paper"),
    ]:
        stem = arxiv_id.replace(".", "_")
        specs.extend(
            [
                {
                    "sourceId": f"{survey.lower()}-arxiv-abs",
                    "sourceName": f"{label} arXiv abstract",
                    "survey": survey,
                    "url": f"https://arxiv.org/abs/{arxiv_id}",
                    "cacheRelativePath": f"{survey.lower()}-arxiv/{stem}.html",
                    "fileType": "html",
                    "maxBytes": 1_500_000,
                    "downloadPolicy": "small arXiv metadata page",
                },
                {
                    "sourceId": f"{survey.lower()}-arxiv-pdf",
                    "sourceName": f"{label} PDF",
                    "survey": survey,
                    "url": f"https://arxiv.org/pdf/{arxiv_id}",
                    "cacheRelativePath": f"{survey.lower()}-arxiv/{stem}.pdf",
                    "fileType": "pdf",
                    "maxBytes": EXTERNAL_BARYON_SOURCE_CAP,
                    "downloadPolicy": "bounded source paper PDF",
                },
                {
                    "sourceId": f"{survey.lower()}-arxiv-source",
                    "sourceName": f"{label} arXiv source",
                    "survey": survey,
                    "url": f"https://arxiv.org/e-print/{arxiv_id}",
                    "cacheRelativePath": f"{survey.lower()}-arxiv/{stem}.source",
                    "fileType": "source",
                    "maxBytes": EXTERNAL_BARYON_SOURCE_CAP,
                    "downloadPolicy": "bounded arXiv source bundle",
                },
            ]
        )
    return specs


def external_baryon_fetch_inventory(source_cache: Path, offline: bool) -> list[dict]:
    rows = []
    for row in external_validation_fetch_inventory(source_cache, offline):
        row = dict(row)
        row["sourceCategory"] = "unified-hi-corpus-control"
        rows.append(row)
    for spec in external_baryon_source_specs():
        path = source_cache / spec["cacheRelativePath"]
        status, size, digest = external_validation_download(spec["url"], path, max_bytes=spec["maxBytes"], offline=offline)
        rows.append(
            {
                "sourceId": spec["sourceId"],
                "sourceName": spec["sourceName"],
                "survey": spec["survey"],
                "url": spec["url"],
                "cachePath": str(path),
                "fileType": spec["fileType"],
                "downloadPolicy": spec["downloadPolicy"],
                "cacheStatus": status,
                "sizeBytes": size,
                "sha256": digest,
                "sourceCacheOnD": str(source_cache).upper().startswith("D:"),
                "notes": "",
                "sourceCategory": "external-baryon-source",
            }
        )
    return sorted(rows, key=lambda row: (row["sourceCategory"], row["survey"], row["sourceId"]))


def external_baryon_record_count(path: Path) -> int:
    if not path.exists() or path.is_dir():
        return 0
    try:
        lines = path.read_text(encoding="utf-8", errors="ignore").splitlines()
    except OSError:
        return 0
    return sum(1 for line in lines if re.match(r"^\s*[-+]?\d", line))


def external_baryon_table_catalog(source_cache: Path) -> list[dict]:
    table_notes = {
        "ReadMe": ("catalog documentation", False, False, False, "Defines available CDS tables and confirms table content."),
        "galaxies.dat": ("galaxy properties plus global mass-model results", False, True, True, "Merged VizieR table for original Tables 1 and 2; includes global Mgas/Mstar terms but not radial Vgas/Vdisk/Vbul component curves."),
        "rotdmbar.dat": ("scaled total rotation and halo model", True, False, False, "Scaled total rotation curve plus pseudo-isothermal model; not separate baryonic components."),
        "dendmbar.dat": ("scaled density profile", True, False, False, "Density profile table; not usable for MTS component scoring."),
        "rotdm.dat": ("DM-only scaled rotation", True, False, False, "DM-only diagnostic curve; not a baryonic component source."),
        "dendm.dat": ("DM-only density profile", True, False, False, "DM-only diagnostic density table; not a baryonic component source."),
        "nfwac.dat": ("NFW model rotation curves", True, False, False, "Halo model curve; not observed baryonic decomposition."),
        "nfwbd.dat": ("NFW model density profiles", True, False, False, "Halo model density table; not observed baryonic decomposition."),
    }
    rows = []
    for file_name, (kind, has_radial, has_global_mass, has_state, notes) in table_notes.items():
        path = source_cache / "little-things-cds" / file_name
        record_count = 0 if file_name == "ReadMe" else external_baryon_record_count(path)
        rows.append(
            {
                "survey": "LITTLE_THINGS",
                "tableName": file_name,
                "cachePath": str(path),
                "cacheStatus": "available" if path.exists() else "missing",
                "recordCount": record_count,
                "tableKind": kind,
                "hasRadialRows": has_radial,
                "hasGlobalBaryonicMass": has_global_mass,
                "hasRadialVgas": False,
                "hasRadialVdisk": False,
                "hasRadialVbul": False,
                "hasMtsStateScaleCandidate": has_state,
                "usableForMtsComponentScoring": False,
                "notes": notes,
            }
        )
    for survey, arxiv_id in [("THINGS", EXTERNAL_BARYON_THINGS_ARXIV), ("LITTLE_THINGS", EXTERNAL_BARYON_LITTLE_ARXIV)]:
        source_path = source_cache / f"{survey.lower()}-arxiv" / f"{arxiv_id.replace('.', '_')}.source"
        pdf_path = source_cache / f"{survey.lower()}-arxiv" / f"{arxiv_id.replace('.', '_')}.pdf"
        rows.append(
            {
                "survey": survey,
                "tableName": f"arxiv-{arxiv_id}",
                "cachePath": f"{source_path};{pdf_path}",
                "cacheStatus": "available" if source_path.exists() or pdf_path.exists() else "missing",
                "recordCount": 0,
                "tableKind": "paper/source bundle",
                "hasRadialRows": False,
                "hasGlobalBaryonicMass": False,
                "hasRadialVgas": False,
                "hasRadialVdisk": False,
                "hasRadialVbul": False,
                "hasMtsStateScaleCandidate": False,
                "usableForMtsComponentScoring": False,
                "notes": "Fetched for provenance; no bounded machine-readable radial Vgas/Vdisk table is exposed by this mode.",
            }
        )
    return rows


def external_baryon_prefill_for_record(record: dict, table_catalog: list[dict]) -> dict:
    name = str(record.get("galaxy") or record.get("name") or "").strip()
    survey = str(record.get("survey") or "").strip()
    columns = external_validation_columns(record)
    point_rows = record.get("data") or record.get("rotation_curve") or []
    has_point_rows = isinstance(point_rows, list) and len(point_rows) > 0
    has_radius = external_validation_has_column(columns, {"Rad", "R", "radius", "radius_kpc", "r_kpc", "rad_kpc"})
    has_vobs = external_validation_has_column(columns, {"Vobs", "Vrot", "Vrot_kms", "vrot_kms"})
    has_err = external_validation_has_column(columns, {"errV", "e_Vobs", "e_Vrot", "Verr"})
    survey_upper = survey.upper()
    if survey_upper == "LITTLE_THINGS":
        vobs = "Vobs"
        err = "errV"
        provenance = str(DEFAULT_EXTERNAL_BARYON_BUILD_CACHE / "little-things-cds")
        missing = ["radialVgas", "radialVdisk", "MTSStateScale_h_or_equivalent"]
        verdict = "kinematic-only; CDS mass-model tables do not expose radial Vgas/Vdisk component curves"
        vgas_source = "MISSING: table2 has global Mgas; no radial Vgas component column"
        vdisk_source = "MISSING: table2 has global stellar mass terms; no radial Vdisk component column"
        vbul_source = "absent/not supplied as radial bulge component for LITTLE THINGS dwarf sample"
        ml = "global mass-model / Spitzer 3.6um context only; no SPARC-style ML=1 radial component velocity table"
    elif survey_upper == "THINGS":
        vobs = "Vrot"
        err = "e_Vrot"
        provenance = f"arXiv:{EXTERNAL_BARYON_THINGS_ARXIV}"
        missing = ["radialVgas", "radialVdisk", "MTSStateScale_h_or_equivalent"]
        verdict = "kinematic-only; bounded source fetch did not expose machine-readable radial baryonic component curves"
        vgas_source = "MISSING: paper provenance says gas contribution exists, but no bounded radial Vgas table was found"
        vdisk_source = "MISSING: paper provenance says SINGS 3.6um mass models exist, but no bounded radial Vdisk table was found"
        vbul_source = "MISSING/optional: no radial bulge component table found"
        ml = "THINGS paper mass-model convention; not machine-readable as per-ring component velocities in v2"
    elif survey_upper == "WALLABY":
        vobs = "vrot_kms"
        err = ""
        provenance = "Unified HI corpus / WALLABY DR2 page"
        missing = ["velocityUncertainty", "radialVgas", "radialVdisk", "MTSStateScale_h_or_equivalent"]
        verdict = "kinematic/quality-only; no baryonic decomposition and no usable per-ring velocity uncertainty"
        vgas_source = "MISSING"
        vdisk_source = "MISSING"
        vbul_source = "MISSING"
        ml = "not available"
    else:
        vobs = "Vobs" if "Vobs" in columns else "Vrot"
        err = "errV" if "errV" in columns else "e_Vrot"
        provenance = "Unified HI corpus"
        missing = ["radialVgas", "radialVdisk", "MTSStateScale_h_or_equivalent"]
        verdict = "not targeted in external baryon build v2"
        vgas_source = "MISSING"
        vdisk_source = "MISSING"
        vbul_source = "MISSING"
        ml = "not available"
    has_vgas = False
    has_vdisk = False
    has_state = False
    usable = has_point_rows and has_radius and has_vobs and has_err and has_vgas and has_vdisk and has_state
    if not has_point_rows:
        missing = ["perPointRotationCurve"] + missing
    if not has_err:
        missing = ["velocityUncertainty"] + [item for item in missing if item != "velocityUncertainty"]
    return {
        "galaxy": name,
        "survey": survey,
        "radiusColumn": "Rad" if survey_upper in {"THINGS", "LITTLE_THINGS"} else ("rad_kpc" if survey_upper == "WALLABY" else ""),
        "vobsColumn": vobs,
        "uncertaintyColumn": err,
        "vobsUncertaintySource": "Unified HI corpus per-ring table" if has_err else "MISSING",
        "vgasSource": vgas_source,
        "vdiskSource": vdisk_source,
        "vbulSource": vbul_source,
        "scaleLengthStateSource": "MISSING: no h/r_out over h or equivalent MTS state scale in bounded sources",
        "mlConvention": ml,
        "provenanceUrlOrPath": provenance,
        "hasPointCurve": has_point_rows,
        "hasVelocityUncertainty": has_err,
        "hasVgas": has_vgas,
        "hasVdisk": has_vdisk,
        "hasVbul": False,
        "hasMtsStateScale": has_state,
        "usableForMtsScoring": usable,
        "scoreabilityVerdict": "full MTS-scoreable" if usable else verdict,
        "missingInputs": ";".join(dict.fromkeys(missing)),
    }


def external_baryon_prefill_rows_from_corpus(galaxies: list[dict], table_catalog: list[dict]) -> list[dict]:
    rows = []
    for record in galaxies:
        survey = str(record.get("survey") or "").upper()
        if survey in {"THINGS", "LITTLE_THINGS", "WALLABY"}:
            rows.append(external_baryon_prefill_for_record(record, table_catalog))
    return sorted(rows, key=lambda row: (row["survey"], row["galaxy"]))


def external_baryon_scoreability_rows(prefill_rows: list[dict]) -> list[dict]:
    out = []
    for row in prefill_rows:
        out.append(
            {
                "galaxy": row["galaxy"],
                "survey": row["survey"],
                "scoreabilityVerdict": row["scoreabilityVerdict"],
                "usableForMtsScoring": row["usableForMtsScoring"],
                "missingInputs": row["missingInputs"],
                "hasPointCurve": row["hasPointCurve"],
                "hasVelocityUncertainty": row["hasVelocityUncertainty"],
                "hasVgas": row["hasVgas"],
                "hasVdisk": row["hasVdisk"],
                "hasMtsStateScale": row["hasMtsStateScale"],
                "provenanceUrlOrPath": row["provenanceUrlOrPath"],
            }
        )
    return out


def external_baryon_extraction_error_rows(prefill_rows: list[dict], inventory_rows: list[dict], table_catalog: list[dict]) -> list[dict]:
    rows = []
    for inv in inventory_rows:
        if inv["cacheStatus"] not in {"available", "excluded-large-data", "skipped-large-or-archive"}:
            rows.append(
                {
                    "scope": "source-fetch",
                    "galaxy": "",
                    "survey": inv["survey"],
                    "issue": inv["cacheStatus"],
                    "missingInput": "",
                    "source": inv["sourceName"],
                    "notes": inv.get("notes", ""),
                }
            )
    for row in prefill_rows:
        for missing in [item for item in row["missingInputs"].split(";") if item]:
            rows.append(
                {
                    "scope": "per-galaxy-scoreability",
                    "galaxy": row["galaxy"],
                    "survey": row["survey"],
                    "issue": "missing-required-input",
                    "missingInput": missing,
                    "source": row["provenanceUrlOrPath"],
                    "notes": row["scoreabilityVerdict"],
                }
            )
    for table in table_catalog:
        if table["survey"] in {"LITTLE_THINGS", "THINGS"} and not parse_bool(table["usableForMtsComponentScoring"]):
            rows.append(
                {
                    "scope": "table-capability",
                    "galaxy": "",
                    "survey": table["survey"],
                    "issue": "table-not-component-scoreable",
                    "missingInput": "radialVgas/radialVdisk",
                    "source": table["cachePath"],
                    "notes": table["notes"],
                }
            )
    return rows


def external_baryon_report(capsule: dict, scoreability_rows: list[dict], table_catalog: list[dict]) -> str:
    metrics = capsule["metrics"]
    by_survey = []
    for survey in sorted({row["survey"] for row in scoreability_rows}):
        rows = [row for row in scoreability_rows if row["survey"] == survey]
        by_survey.append(
            f"- {survey}: {len(rows)} rows, {sum(1 for row in rows if parse_bool(row['usableForMtsScoring']))} full MTS-scoreable, "
            f"missing inputs: {', '.join(sorted({item for row in rows for item in row['missingInputs'].split(';') if item}))}"
        )
    table_lines = [
        f"- {row['survey']} `{row['tableName']}`: status={row['cacheStatus']}, records={row['recordCount']}, usable={row['usableForMtsComponentScoring']}."
        for row in table_catalog
    ]
    return "\n".join(
        [
            "# MTS v21.11 External Baryonic Scoreability Builder",
            "",
            f"Verdict: **{capsule['verdict']}**",
            "",
            "This mode fetches bounded source material and builds a strict prefill for external MTS scoreability. It does not invent baryonic components, fit new M/L values, or promote v21.",
            "",
            "## Source Cache",
            "",
            f"- Source cache: `{capsule['sourceCache']}`",
            f"- Source cache on D: `{metrics['sourceCacheOnDDrive']}`",
            f"- Large downloads: `{metrics['largeDownloadCount']}`",
            "",
            "## Scoreability Result",
            "",
            f"- Target external rows: `{metrics['targetExternalRows']}`",
            f"- Full non-SPARC MTS-scoreable rows created: `{metrics['nonSparcFullMtsScoreableCount']}`",
            f"- THINGS/LITTLE THINGS rows with per-point kinematics: `{metrics['thingsLittleThingsKinematicRows']}`",
            "",
            *by_survey,
            "",
            "## Table Capability",
            "",
            *table_lines,
            "",
            "## Interpretation",
            "",
            "LITTLE THINGS has useful CDS mass-model tables, but the bounded VizieR tables expose global mass-model quantities and scaled total/halo curves, not SPARC-style per-radius Vgas/Vdisk component velocities. THINGS source material confirms mass-model provenance, but this v2 fetch did not expose a bounded machine-readable radial component table. These rows remain kinematic-only for full MTS scoring until radial baryonic component curves and an MTS state scale are acquired.",
        ]
    )


def write_external_baryon_build_artifacts(out_dir: Path, source_cache: Path, offline: bool) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    source_cache.mkdir(parents=True, exist_ok=True)
    inventory_rows = external_baryon_fetch_inventory(source_cache, offline)
    corpus_galaxies, corpus_info = external_validation_read_corpus(source_cache)
    table_catalog = external_baryon_table_catalog(source_cache)
    prefill_rows = external_baryon_prefill_rows_from_corpus(corpus_galaxies, table_catalog)
    scoreability_rows = external_baryon_scoreability_rows(prefill_rows)
    error_rows = external_baryon_extraction_error_rows(prefill_rows, inventory_rows, table_catalog)
    non_sparc_full = [row for row in scoreability_rows if parse_bool(row["usableForMtsScoring"])]
    things_little_kinematic = [
        row for row in scoreability_rows
        if row["survey"] in {"THINGS", "LITTLE_THINGS"} and parse_bool(row["hasPointCurve"])
    ]
    large_downloads = [
        row for row in inventory_rows
        if row["cacheStatus"] == "skipped-size-cap" and parse_float(row.get("sizeBytes"), 0.0) > EXTERNAL_BARYON_SOURCE_CAP
    ]
    verdict = "external baryonic inputs still missing" if len(non_sparc_full) < 20 else "external baryonic validation prefill ready"
    metrics = {
        "sourceCacheOnDDrive": str(source_cache).upper().startswith("D:"),
        "largeDownloadCount": len(large_downloads),
        "sourceInventoryRows": len(inventory_rows),
        "tableCatalogRows": len(table_catalog),
        "targetExternalRows": len(scoreability_rows),
        "nonSparcFullMtsScoreableCount": len(non_sparc_full),
        "thingsLittleThingsKinematicRows": len(things_little_kinematic),
        "corpusStatus": corpus_info.get("status", ""),
    }
    capsule = {
        "mode": "externalbaryonbuild",
        "createdUtc": "deterministic",
        "verdict": verdict,
        "sourceCache": str(source_cache.resolve()),
        "sourceCorpus": corpus_info,
        "metrics": metrics,
        "outputs": {
            "sourceInventory": "mts_external_baryon_source_inventory.csv",
            "tableCatalog": "mts_external_baryon_table_catalog.csv",
            "prefill": "mts_external_baryon_prefill.csv",
            "scoreability": "mts_external_baryon_scoreability.csv",
            "extractionErrors": "mts_external_baryon_extraction_errors.csv",
            "report": "mts_external_baryon_report.md",
        },
    }
    write_csv(out_dir / "mts_external_baryon_source_inventory.csv", inventory_rows)
    write_csv(out_dir / "mts_external_baryon_table_catalog.csv", table_catalog)
    write_csv(out_dir / "mts_external_baryon_prefill.csv", prefill_rows)
    write_csv(out_dir / "mts_external_baryon_scoreability.csv", scoreability_rows)
    write_csv(out_dir / "mts_external_baryon_extraction_errors.csv", error_rows)
    (out_dir / "mts_external_baryon_report.md").write_text(
        external_baryon_report(capsule, scoreability_rows, table_catalog),
        encoding="utf-8",
    )
    (out_dir / "mts_external_baryon_capsule.json").write_text(
        json.dumps(json_clean(capsule), indent=2, sort_keys=True),
        encoding="utf-8",
    )
    return capsule


def cmd_externalbaryonbuild(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_EXTERNAL_BARYON_BUILD_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    source_cache = Path(args.source_cache) if args.source_cache else DEFAULT_EXTERNAL_BARYON_BUILD_CACHE
    capsule = write_external_baryon_build_artifacts(out_dir, source_cache, args.offline)
    metrics = capsule["metrics"]
    print("MTS v21.11 external baryonic scoreability builder: canonical MTS locked")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"targets={metrics['targetExternalRows']}",
                f"non_sparc_full={metrics['nonSparcFullMtsScoreableCount']}",
                f"things_little_kinematic={metrics['thingsLittleThingsKinematicRows']}",
                f"large_downloads={metrics['largeDownloadCount']}",
                f"source_cache_on_d={metrics['sourceCacheOnDDrive']}",
            ]
        )
    )
    print(f"source_cache={source_cache.resolve()}")
    print(f"Wrote MTS v21.11 external baryon build pack to {out_dir.resolve()}")


def external_proxy_source_paths(source_cache: Path) -> dict[str, Path]:
    return {
        "unified-hi-corpus": source_cache / "unified-hi-corpus" / "zenodo-files" / "rotation_curve_corpus_v7.json",
        "little-things-galaxies": source_cache / "little-things-cds" / "galaxies.dat",
        "little-things-rotdmbar": source_cache / "little-things-cds" / "rotdmbar.dat",
        "little-things-rotdm": source_cache / "little-things-cds" / "rotdm.dat",
        "v21-quality-formula": DEFAULT_V21_QUALITY_GATE_OUT / "mts_v21_quality_gate_formula.json",
        "v21-frozen-formula": DEFAULT_V21_FROZEN_FRONTIER_OUT / "mts_v21_frozen_frontier_formula.json",
        "external-baryon-build-capsule": DEFAULT_EXTERNAL_BARYON_BUILD_OUT / "mts_external_baryon_capsule.json",
    }


def external_proxy_read_vizier_tsv(path: Path) -> list[dict]:
    if not path.exists():
        return []
    try:
        lines = path.read_text(encoding="utf-8", errors="ignore").splitlines()
    except OSError:
        return []
    header: list[str] | None = None
    start_index = 0
    for index, line in enumerate(lines):
        if line.startswith("recno\t"):
            header = [part.strip() for part in line.split("\t")]
            start_index = index + 1
            break
    if not header:
        return []
    rows = []
    for line in lines[start_index:]:
        if not line.strip() or line.startswith("#"):
            continue
        if line.strip().startswith("--------"):
            continue
        parts = [part.strip() for part in line.split("\t")]
        if len(parts) != len(header):
            continue
        if not re.match(r"^\s*\d+$", parts[0]):
            continue
        rows.append(dict(zip(header, parts)))
    return rows


def external_proxy_scaled_curve_groups(path: Path) -> dict[str, list[dict]]:
    groups: dict[str, list[dict]] = {}
    for row in external_proxy_read_vizier_tsv(path):
        if row.get("Type", "").strip().lower() != "data":
            continue
        name = row.get("Name", "").strip()
        r03 = parse_float(row.get("R0.3"))
        v03 = parse_float(row.get("V0.3"))
        r_scaled = parse_float(row.get("R"))
        v_scaled = parse_float(row.get("V"))
        ev_scaled = parse_float(row.get("e_V"))
        if not all(math.isfinite(value) for value in [r03, v03, r_scaled, v_scaled]):
            continue
        key = external_validation_name_key(name)
        groups.setdefault(key, []).append(
            {
                "galaxy": name,
                "r03": r03,
                "v03": v03,
                "rScaled": r_scaled,
                "vScaled": v_scaled,
                "errScaled": ev_scaled,
                "r": r_scaled * r03,
                "v": v_scaled * v03,
                "err": ev_scaled * v03 if math.isfinite(ev_scaled) else math.nan,
                "sourcePath": str(path),
            }
        )
    for points in groups.values():
        points.sort(key=lambda item: item["r"])
    return groups


def external_proxy_global_props(path: Path) -> dict[str, dict]:
    out: dict[str, dict] = {}
    for row in external_proxy_read_vizier_tsv(path):
        name = row.get("Name", "").strip()
        if name:
            out[external_validation_name_key(name)] = row
    return out


def external_proxy_point_value(point: dict, names: Iterable[str]) -> float:
    normalized = {re.sub(r"[^a-z0-9]", "", str(key).lower()): key for key in point.keys()}
    for name in names:
        key = normalized.get(re.sub(r"[^a-z0-9]", "", name.lower()))
        if key is not None:
            value = parse_float(point.get(key))
            if math.isfinite(value):
                return value
    return math.nan


def external_proxy_interp(points: list[dict], radius: float, key: str) -> tuple[float, str]:
    clean = sorted(
        [point for point in points if math.isfinite(point.get("r", math.nan)) and math.isfinite(point.get(key, math.nan))],
        key=lambda point: point["r"],
    )
    if not clean or not math.isfinite(radius):
        return math.nan, "missing-source-curve"
    if radius < clean[0]["r"] or radius > clean[-1]["r"]:
        return math.nan, "outside-source-radius-range"
    if len(clean) == 1:
        return clean[0][key], "single-point"
    for index in range(1, len(clean)):
        left = clean[index - 1]
        right = clean[index]
        if radius <= right["r"]:
            denom = right["r"] - left["r"]
            if abs(denom) < 1e-12:
                return right[key], "duplicate-radius"
            t = (radius - left["r"]) / denom
            return left[key] * (1 - t) + right[key] * t, "interpolated"
    return clean[-1][key], "edge"


def external_proxy_little_records(corpus: list[dict]) -> dict[str, dict]:
    out = {}
    for record in corpus:
        if str(record.get("survey", "")).upper() == "LITTLE_THINGS":
            name = str(record.get("galaxy") or record.get("name") or "").strip()
            if name:
                out[external_validation_name_key(name)] = record
    return out


def external_proxy_mass_fraction(props: dict) -> tuple[float, str]:
    m_gas = parse_float(props.get("Mgas"))
    m_star_k = parse_float(props.get("MstarK"))
    m_star_sed = parse_float(props.get("MstarSED"))
    if math.isfinite(m_star_k) and m_star_k > 0:
        m_star = m_star_k
        source = "Mgas/(Mgas+MstarK)"
    elif math.isfinite(m_star_sed) and m_star_sed > 0:
        m_star = m_star_sed
        source = "Mgas/(Mgas+MstarSED)"
    else:
        m_star = 0.0
        source = "Mgas only; stellar mass missing"
    if not math.isfinite(m_gas) or m_gas < 0:
        return math.nan, "MISSING"
    return clamp(m_gas / (m_gas + m_star) if (m_gas + m_star) > 0 else math.nan, 0.0, 1.0), source


def external_proxy_curve_from_rows(name: str, point_rows: list[dict], props: dict) -> dict | None:
    rows = []
    for row in point_rows:
        if not parse_bool(row.get("includedInProxyScore")):
            continue
        r = parse_float(row.get("radiusKpc"))
        v_obs = parse_float(row.get("vObs"))
        err = parse_float(row.get("errV"))
        vbar = parse_float(row.get("vbarProxy"))
        if not all(math.isfinite(value) for value in [r, v_obs, err, vbar]) or r <= 0:
            continue
        rows.append(
            {
                "r": r,
                "vObs": v_obs,
                "err": err,
                "vGas": vbar,
                "vDisk": 0.0,
                "vBulge": 0.0,
                "sbDisk": 0.0,
                "sbBulge": 0.0,
            }
        )
    rows.sort(key=lambda item: item["r"])
    if len(rows) < 3:
        return None
    r03 = parse_float(props.get("R0.3"))
    rmax = parse_float(props.get("Rmax"))
    h = r03 if math.isfinite(r03) and r03 > 0 else max(0.25, rows[-1]["r"] / 3.0)
    r_out = max([rows[-1]["r"]] + ([rmax] if math.isfinite(rmax) and rmax > 0 else []))
    f_gas_out, f_gas_source = external_proxy_mass_fraction(props)
    if not math.isfinite(f_gas_out):
        f_gas_out = 0.5
        f_gas_source = "fallback 0.5 because global Mgas/Mstar missing"
    leff = leff_exact(h, r_out, f_gas_out)
    memory = (1 - f_gas_out) * (r_out / h)

    points = []
    for row in rows:
        bar2 = row["vGas"] ** 2
        u = row["vObs"] ** 2 / (GAMMA0 * row["r"] * R_MAX)
        points.append({**row, "bar2": bar2, "x": row["r"] / r_out, "u": u})
    state = route_state(points, r_out)
    locked_points = []
    for point in points:
        support2 = GAMMA0 * leff * (1 - math.exp(-((point["r"] / leff) ** Q_DEFAULT)))
        model2 = point["bar2"] + support2
        u = model2 / (GAMMA0 * point["r"] * R_MAX)
        locked_points.append({**point, "u": u})
    locked_state = route_state(locked_points, r_out)
    safety = route_safety(locked_state)
    return {
        "name": name,
        "points": points,
        "distanceMpc": parse_float(props.get("Dist")),
        "mlDisk": ML_DISK,
        "mlBulge": ML_BULGE,
        "h": h,
        "rOut": r_out,
        "r03Proxy": r03,
        "rmaxProxy": rmax,
        "fGasOut": f_gas_out,
        "fGasProxySource": f_gas_source,
        "leff": leff,
        "leffOverH": leff / h if h else math.nan,
        "memoryLoad": memory,
        "lockedModelRoute": locked_state["route"],
        "lockedModelU0": locked_state["u0"],
        "lockedModelUOut": locked_state["uOut"],
        "lockedModelUMax": locked_state["uMax"],
        "lockedModelU075": locked_state["u075"],
        "lockedModelXCross": locked_state["xCross"],
        "lockedModelDownCrossings": locked_state["downCrossings"],
        "lockedModelUpCrossings": locked_state["upCrossings"],
        **safety,
        **state,
    }


def external_proxy_build_rows(source_cache: Path) -> tuple[list[dict], list[dict], list[dict], list[dict]]:
    paths = external_proxy_source_paths(source_cache)
    corpus, _info = external_validation_read_corpus(source_cache)
    records = external_proxy_little_records(corpus)
    props = external_proxy_global_props(paths["little-things-galaxies"])
    dmbar = external_proxy_scaled_curve_groups(paths["little-things-rotdmbar"])
    dmonly = external_proxy_scaled_curve_groups(paths["little-things-rotdm"])

    point_rows: list[dict] = []
    check_rows: list[dict] = []
    scoreability_rows: list[dict] = []
    curves: list[dict] = []
    all_keys = sorted(set(records.keys()) | set(dmbar.keys()) | set(dmonly.keys()) | set(props.keys()))
    for key in all_keys:
        record = records.get(key, {})
        raw_name = str(record.get("galaxy") or props.get(key, {}).get("Name") or (dmbar.get(key, [{}])[0].get("galaxy", ""))).strip()
        dmbar_points = dmbar.get(key, [])
        dmonly_points = dmonly.get(key, [])
        proxy_points = []
        clipped_count = 0
        for point in dmbar_points:
            v_dm, status = external_proxy_interp(dmonly_points, point["r"], "v")
            diff = point["v"] ** 2 - v_dm ** 2 if math.isfinite(v_dm) else math.nan
            clipped = math.isfinite(diff) and diff < 0
            if clipped:
                clipped_count += 1
            if math.isfinite(diff):
                proxy_points.append(
                    {
                        "r": point["r"],
                        "vDmbar": point["v"],
                        "vDmonly": v_dm,
                        "vbarProxy": math.sqrt(max(diff, 0.0)),
                        "dmOnlyMatchStatus": status,
                        "baryonDiffClipped": clipped,
                    }
                )
        observed_points = record.get("data") or record.get("rotation_curve") or []
        outside_count = 0
        included_count = 0
        for index, obs in enumerate(observed_points):
            radius = external_proxy_point_value(obs, {"Rad", "R", "radius", "radius_kpc", "r_kpc"})
            v_obs = external_proxy_point_value(obs, {"Vobs", "Vrot", "Vrot_kms", "velocity", "vrot_kms"})
            err_v = external_proxy_point_value(obs, {"errV", "e_Vobs", "e_Vrot", "Verr", "velocity_error"})
            vbar, status = external_proxy_interp(proxy_points, radius, "vbarProxy")
            v_dmbar, _status_dmbar = external_proxy_interp(proxy_points, radius, "vDmbar")
            v_dmonly, _status_dmonly = external_proxy_interp(proxy_points, radius, "vDmonly")
            included = all(math.isfinite(value) for value in [radius, v_obs, err_v, vbar]) and radius > 0
            if status == "outside-source-radius-range":
                outside_count += 1
            if included:
                included_count += 1
            point_rows.append(
                {
                    "galaxy": raw_name,
                    "survey": "LITTLE_THINGS",
                    "pointIndex": index,
                    "radiusKpc": radius,
                    "vObs": v_obs,
                    "errV": err_v,
                    "vDmbarInterp": v_dmbar,
                    "vDmonlyInterp": v_dmonly,
                    "vbarProxy": vbar,
                    "interpStatus": status,
                    "includedInProxyScore": included,
                    "sourceObserved": paths["unified-hi-corpus"],
                    "sourceDmBaryons": paths["little-things-rotdmbar"],
                    "sourceDmOnly": paths["little-things-rotdm"],
                }
            )
        galaxy_point_rows = [row for row in point_rows if row["galaxy"] == raw_name]
        curve = external_proxy_curve_from_rows(raw_name, galaxy_point_rows, props.get(key, {}))
        if curve:
            curves.append(curve)
        missing = []
        if key not in records:
            missing.append("unifiedObservedCurve")
        if key not in dmbar:
            missing.append("rotdmbarDataRows")
        if key not in dmonly:
            missing.append("rotdmDataRows")
        if key not in props:
            missing.append("galaxiesDatRow")
        if included_count < 3:
            missing.append("atLeast3MatchedProxyPoints")
        strict_missing = ["radialVgas", "radialVdisk", "MTSStateScale_h_from_component_model"]
        proxy_scoreable = curve is not None
        scoreability_rows.append(
            {
                "galaxy": raw_name,
                "survey": "LITTLE_THINGS",
                "strictScoreability": "not full MTS-scoreable",
                "strictCanScoreMts": False,
                "strictMissingInputs": ";".join(strict_missing),
                "proxyScoreability": "external baryonic proxy" if proxy_scoreable else "proxy reconstruction failed",
                "proxyCanScore": proxy_scoreable,
                "proxyEvidenceRole": "direction-finding only; not SPARC-equivalent validation",
                "nObservedPoints": len(observed_points),
                "nProxySourcePoints": len(proxy_points),
                "nProxyScoredPoints": included_count,
                "missingProxyInputs": ";".join(missing),
            }
        )
        check_rows.append(
            {
                "galaxy": raw_name,
                "survey": "LITTLE_THINGS",
                "hasUnifiedObservedCurve": key in records,
                "hasRotDmBarData": key in dmbar,
                "hasRotDmData": key in dmonly,
                "hasGalaxiesDatProps": key in props,
                "nObservedPoints": len(observed_points),
                "nRotDmBarDataPoints": len(dmbar_points),
                "nRotDmDataPoints": len(dmonly_points),
                "nDerivedProxyPoints": len(proxy_points),
                "nProxyScoredPoints": included_count,
                "outsideProxyRadiusCount": outside_count,
                "negativeBaryonDiffClippedCount": clipped_count,
                "proxyNumericallyStable": proxy_scoreable,
                "failedReason": ";".join(missing),
            }
        )
    return point_rows, scoreability_rows, check_rows, curves


def external_proxy_source_ledger(source_cache: Path) -> list[dict]:
    ledger = []
    for source_id, path in external_proxy_source_paths(source_cache).items():
        if path.suffix.lower() in {".dat", ".tsv", ".mrt"}:
            rows = external_proxy_read_vizier_tsv(path)
            row_count = len(rows) if rows else external_baryon_record_count(path)
        elif path.suffix.lower() == ".json":
            payload = read_json_if_exists(path)
            if source_id == "unified-hi-corpus" and isinstance(payload.get("galaxies"), list):
                row_count = len(payload.get("galaxies", []))
            else:
                row_count = len(payload) if isinstance(payload, dict) else 0
        else:
            row_count = 0
        ledger.append(
            {
                "sourceId": source_id,
                "path": str(path),
                "fileType": path.suffix.lower().lstrip(".") or "unknown",
                "exists": path.exists(),
                "rowCount": row_count,
                "sha256": file_sha256(path) if path.exists() else "",
                "reasonIncluded": {
                    "unified-hi-corpus": "observed LITTLE THINGS rotation curves",
                    "little-things-galaxies": "global masses, R0.3, Rmax, inclination, and scale proxies",
                    "little-things-rotdmbar": "published DM+baryons scaled curve source",
                    "little-things-rotdm": "published DM-only scaled curve source",
                    "v21-quality-formula": "frozen v21 gate metadata for proxy anatomy replay",
                    "v21-frozen-formula": "frozen frontier provenance",
                    "external-baryon-build-capsule": "v21.11 strict scoreability context",
                }.get(source_id, ""),
                "stage": "v21.12 external baryonic proxy",
            }
        )
    return sorted(ledger, key=lambda row: row["sourceId"])


def external_proxy_span(values: Iterable[float]) -> float:
    clean = [value for value in values if isinstance(value, (int, float)) and math.isfinite(value)]
    return max(clean) - min(clean) if len(clean) >= 2 else 1.0


def external_proxy_candidate_rows(curves: list[dict]) -> tuple[list[dict], list[dict]]:
    formula = read_json_if_exists(DEFAULT_V21_QUALITY_GATE_OUT / "mts_v21_quality_gate_formula.json")
    beta = parse_float(formula.get("beta"), 5.0)
    boundary_threshold = 29.03
    u075_threshold = 0.5444
    width_scale = 0.25
    state_rows = []
    for curve in curves:
        terms = v19_curve_memory_terms(curve)
        base = score_curve_with_params(curve, 1.0, Q_DEFAULT)
        baryon = score_curve_baryon_only(curve)
        state_rows.append(
            {
                "name": curve["name"],
                "curve": curve,
                "baseline": base,
                "baryonOnly": baryon,
                "lockedRoute": base["candidateRoute"],
                "boundaryScore": terms["boundaryScore"],
                "u075": curve["lockedModelU075"],
                "uOut": curve["lockedModelUOut"],
                "uMax": curve["lockedModelUMax"],
                "memoryLoad": terms["memoryLoad"],
                "lExact": terms["lExact"],
                "lSat": terms["lSat"],
                "lGap": terms["lGap"],
            }
        )
    widths = {
        "boundaryScore": max(1e-9, external_proxy_span(row["boundaryScore"] for row in state_rows) * width_scale),
        "u075": max(1e-9, external_proxy_span(row["u075"] for row in state_rows) * width_scale),
    }
    candidate = {
        "rule": (("boundaryScore", "ge", boundary_threshold), ("u075", "ge", u075_threshold)),
        "beta": beta,
        "gateStyle": "hinge",
        "widthScale": width_scale,
        "widths": widths,
        "formulaFamily": "boundaryScore+u075",
        "candidateId": "frozen-v21-state-gate-proxy-anatomy",
    }
    case_rows = []
    for row in state_rows:
        activation = v21_law_activation(row, candidate)
        score = score_curve_with_leff_value(row["curve"], row["lExact"] * (1.0 + beta * activation))
        baseline = row["baseline"]
        baryon = row["baryonOnly"]
        delta = score["rmse"] - baseline["rmse"]
        case_rows.append(
            {
                "galaxy": row["name"],
                "survey": "LITTLE_THINGS",
                "evidenceTier": "external baryonic proxy",
                "strictFullMtsScoreable": False,
                "proxyScoreable": True,
                "nPoints": len(row["curve"]["points"]),
                "baryonOnlyRmse": baryon["rmse"],
                "canonicalRmse": baseline["rmse"],
                "frozenV21ProxyRmse": score["rmse"],
                "v21DeltaVsCanonical": delta,
                "v21GainPctVsCanonical": pct_improvement(baseline["rmse"], score["rmse"]),
                "canonicalGainPctVsBaryonOnly": pct_improvement(baryon["rmse"], baseline["rmse"]),
                "lockedRoute": row["lockedRoute"],
                "candidateRoute": score["candidateRoute"],
                "routePreservedVsCanonical": score["candidateRoute"] == row["lockedRoute"],
                "activeStretch": activation > 1e-12,
                "activation": activation,
                "beta": beta,
                "effectiveBeta": beta * activation,
                "leffExact": row["lExact"],
                "leffCandidate": score.get("candidateLeff", row["lExact"]),
                "boundaryScore": row["boundaryScore"],
                "u075": row["u075"],
                "uOut": row["uOut"],
                "uMax": row["uMax"],
                "memoryLoad": row["memoryLoad"],
                "lGap": row["lGap"],
                "fGasProxy": row["curve"]["fGasOut"],
                "fGasProxySource": row["curve"]["fGasProxySource"],
                "r03Proxy": row["curve"]["r03Proxy"],
                "rmaxProxy": row["curve"]["rmaxProxy"],
                "proxyInterpretation": "direction-finding only; total baryon proxy, no radial Vgas/Vdisk split",
            }
        )
    def metric_row(candidate_id: str, tier: str, rmse_key: str, baseline_key: str | None = None) -> dict:
        mean_rmse = safe_mean(row[rmse_key] for row in case_rows)
        baseline_mean = safe_mean(row[baseline_key] for row in case_rows) if baseline_key else math.nan
        return {
            "candidateId": candidate_id,
            "evidenceTier": tier,
            "scoreableGalaxies": len(case_rows),
            "meanRmse": mean_rmse,
            "medianRmse": safe_median(row[rmse_key] for row in case_rows),
            "meanGainPctVsComparator": pct_improvement(baseline_mean, mean_rmse) if baseline_key else math.nan,
            "comparator": baseline_key or "",
            "activeStretchCount": sum(1 for row in case_rows if parse_bool(row["activeStretch"])) if "v21" in candidate_id else 0,
            "routeChangeCount": sum(1 for row in case_rows if not parse_bool(row["routePreservedVsCanonical"])) if "v21" in candidate_id else 0,
            "maxRegressionVsCanonical": max([row["v21DeltaVsCanonical"] for row in case_rows] or [math.nan]) if "v21" in candidate_id else math.nan,
            "promotionEligible": False,
            "notes": "proxy anatomy only; not full SPARC-equivalent framework validation",
        }
    score_rows = [
        {
            "candidateId": "strict-full-mts-scoreability",
            "evidenceTier": "strict",
            "scoreableGalaxies": 0,
            "meanRmse": math.nan,
            "medianRmse": math.nan,
            "meanGainPctVsComparator": math.nan,
            "comparator": "",
            "activeStretchCount": 0,
            "routeChangeCount": 0,
            "maxRegressionVsCanonical": math.nan,
            "promotionEligible": False,
            "notes": "blocked: LITTLE THINGS source tables do not expose radial Vgas/Vdisk component curves or SPARC-style h/state inputs",
        },
        metric_row("baryon-only-total-proxy", "external baryonic proxy", "baryonOnlyRmse"),
        metric_row("canonical-mts-total-baryon-proxy", "external baryonic proxy", "canonicalRmse", "baryonOnlyRmse"),
        metric_row("frozen-v21-state-gate-total-baryon-proxy", "external baryonic proxy", "frozenV21ProxyRmse", "canonicalRmse"),
    ]
    return score_rows, sorted(case_rows, key=lambda row: row["galaxy"])


def external_proxy_report(capsule: dict, score_rows: list[dict]) -> str:
    metrics = capsule["metrics"]
    score_lines = [
        f"- `{row['candidateId']}`: n={row['scoreableGalaxies']}, mean RMSE={fmt(parse_float(row['meanRmse']))}, gain vs comparator={fmt(parse_float(row['meanGainPctVsComparator']))}%, promotionEligible={row['promotionEligible']}."
        for row in score_rows
    ]
    return "\n".join(
        [
            "# MTS v21.12 LITTLE THINGS Baryonic-Proxy Validation Pilot",
            "",
            f"Verdict: **{capsule['verdict']}**",
            "",
            "This mode uses cached D-drive sources only. It does not fetch new data, does not create SPARC-equivalent validation rows, and does not promote v21.",
            "",
            "## Proxy Reconstruction",
            "",
            f"- LITTLE THINGS galaxies in proxy source union: `{metrics['littleThingsSourceUnionCount']}`",
            f"- Proxy-scoreable LITTLE THINGS galaxies: `{metrics['proxyScoreableCount']}`",
            f"- Strict full MTS-scoreable LITTLE THINGS galaxies: `{metrics['strictFullMtsScoreableCount']}`",
            f"- Proxy curve points written: `{metrics['proxyCurvePointRows']}`",
            f"- Numerically stable proxy cases: `{metrics['numericallyStableProxyCount']}`",
            "",
            "The proxy baryonic support is reconstructed as `sqrt(max(V_DM+baryons^2 - V_DM-only^2, 0))` after converting the published scaled curves by `R0.3` and `V0.3`, then interpolating onto observed LITTLE THINGS radii from the Unified HI corpus.",
            "",
            "## Candidate Scores",
            "",
            *score_lines,
            "",
            "## Interpretation",
            "",
            "The strict tier remains blocked because LITTLE THINGS does not provide SPARC-style radial `Vgas`/`Vdisk` component curves or the same component-derived MTS state scale. The proxy tier is useful for direction-finding only: it tests numerical behavior against an external dwarf-galaxy total-baryon proxy, not a framework-promotion dataset.",
            "",
            f"- Canonical proxy mean RMSE: `{fmt(metrics['canonicalProxyMeanRmse'])}`",
            f"- Frozen v21 proxy mean RMSE: `{fmt(metrics['v21ProxyMeanRmse'])}`",
            f"- Frozen v21 proxy mean gain vs canonical: `{fmt(metrics['v21ProxyGainPct'])}%`",
            "",
            "No q change, amplitude patch, residual lookup, RMSE lookup, galaxy-name rule, or weak/systematics training is introduced.",
        ]
    )


def write_external_baryon_proxy_artifacts(out_dir: Path, source_cache: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    source_rows = external_proxy_source_ledger(source_cache)
    point_rows, scoreability_rows, check_rows, curves = external_proxy_build_rows(source_cache)
    candidate_rows, case_rows = external_proxy_candidate_rows(curves)
    proxy_scoreable = [row for row in scoreability_rows if parse_bool(row["proxyCanScore"])]
    strict_full = [row for row in scoreability_rows if parse_bool(row["strictCanScoreMts"])]
    stable = [row for row in check_rows if parse_bool(row["proxyNumericallyStable"])]
    canonical_row = next((row for row in candidate_rows if row["candidateId"] == "canonical-mts-total-baryon-proxy"), {})
    v21_row = next((row for row in candidate_rows if row["candidateId"] == "frozen-v21-state-gate-total-baryon-proxy"), {})
    verdict = "proxy evidence only; no framework promotion" if proxy_scoreable else "proxy reconstruction failed"
    metrics = {
        "sourceCache": str(source_cache.resolve()),
        "sourceCacheOnDDrive": str(source_cache).upper().startswith("D:"),
        "littleThingsSourceUnionCount": len(scoreability_rows),
        "proxyScoreableCount": len(proxy_scoreable),
        "strictFullMtsScoreableCount": len(strict_full),
        "proxyCurvePointRows": len(point_rows),
        "numericallyStableProxyCount": len(stable),
        "canonicalProxyMeanRmse": parse_float(canonical_row.get("meanRmse")),
        "v21ProxyMeanRmse": parse_float(v21_row.get("meanRmse")),
        "v21ProxyGainPct": parse_float(v21_row.get("meanGainPctVsComparator")),
        "networkFetchRequired": False,
        "promotionEligible": False,
    }
    capsule = {
        "mode": "externalbaryonproxy",
        "createdUtc": "deterministic",
        "verdict": verdict,
        "metrics": metrics,
        "formulaDiscipline": {
            "canonicalQ": Q_DEFAULT,
            "canonicalGamma0": GAMMA0,
            "frozenV21ProxyRole": "proxy anatomy only",
            "strictRowsCountedAsFullMtsEvidence": 0,
            "forbiddenInputs": ["q changes", "amplitude patches", "residual lookup", "RMSE lookup", "galaxy-name rules"],
        },
        "outputs": {
            "sourceLedger": "mts_external_proxy_source_ledger.csv",
            "curvePoints": "mts_external_proxy_curve_points.csv",
            "scoreability": "mts_external_proxy_scoreability.csv",
            "candidateScores": "mts_external_proxy_candidate_scores.csv",
            "caseLedger": "mts_external_proxy_case_ledger.csv",
            "reconstructionChecks": "mts_external_proxy_reconstruction_checks.csv",
            "report": "mts_external_proxy_report.md",
        },
    }
    write_csv(out_dir / "mts_external_proxy_source_ledger.csv", source_rows)
    write_csv(out_dir / "mts_external_proxy_curve_points.csv", sorted(point_rows, key=lambda row: (row["galaxy"], int(row["pointIndex"]))))
    write_csv(out_dir / "mts_external_proxy_scoreability.csv", sorted(scoreability_rows, key=lambda row: row["galaxy"]))
    write_csv(out_dir / "mts_external_proxy_candidate_scores.csv", candidate_rows)
    write_csv(out_dir / "mts_external_proxy_case_ledger.csv", case_rows)
    write_csv(out_dir / "mts_external_proxy_reconstruction_checks.csv", sorted(check_rows, key=lambda row: row["galaxy"]))
    (out_dir / "mts_external_proxy_report.md").write_text(
        external_proxy_report(capsule, candidate_rows),
        encoding="utf-8",
    )
    (out_dir / "mts_external_proxy_capsule.json").write_text(
        json.dumps(json_clean(capsule), indent=2, sort_keys=True),
        encoding="utf-8",
    )
    return capsule


def cmd_externalbaryonproxy(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_EXTERNAL_BARYON_PROXY_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    source_cache = Path(args.source_cache) if args.source_cache else DEFAULT_EXTERNAL_BARYON_BUILD_CACHE
    capsule = write_external_baryon_proxy_artifacts(out_dir, source_cache)
    metrics = capsule["metrics"]
    print("MTS v21.12 LITTLE THINGS baryonic-proxy validation pilot: canonical MTS locked")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"proxy_scoreable={metrics['proxyScoreableCount']}",
                f"strict_full={metrics['strictFullMtsScoreableCount']}",
                f"points={metrics['proxyCurvePointRows']}",
                f"canonical_proxy_mean={fmt(metrics['canonicalProxyMeanRmse'])}",
                f"v21_proxy_mean={fmt(metrics['v21ProxyMeanRmse'])}",
                f"v21_gain={fmt(metrics['v21ProxyGainPct'])}%",
                f"network_fetch_required={metrics['networkFetchRequired']}",
            ]
        )
    )
    print(f"source_cache={source_cache.resolve()}")
    print(f"Wrote MTS v21.12 external baryon proxy pack to {out_dir.resolve()}")


