def external_component_manual_overlay_rows(review_dir: Path, validation_dir: Path, calibration_dir: Path, overlay_dir: Path) -> list[dict]:
    axis_rows = read_csv_rows(review_dir / "mts_external_component_axis_sanity.csv")
    point_rows = read_csv_rows(validation_dir / "mts_external_component_validation_curve_points.csv")
    validated_rows = read_csv_rows(calibration_dir / "mts_external_component_validated_points.csv")
    axis_map = {row.get("galaxy", ""): row for row in axis_rows if row.get("galaxy")}
    rows = []
    for galaxy in sorted(axis_map):
        svg = external_component_manual_svg(
            galaxy,
            axis_map[galaxy],
            point_rows,
            validated_rows,
        )
        svg_name = f"{external_validation_name_key(galaxy)}_component_review.svg"
        svg_path = overlay_dir / svg_name
        svg_path.write_text(svg, encoding="utf-8")
        rows.append(
            {
                "galaxy": galaxy,
                "overlayPath": f"overlays/{svg_name}",
                "axisSanityRisk": axis_map[galaxy].get("axisSanityRisk", ""),
                "manualReviewPriority": axis_map[galaxy].get("manualReviewPriority", ""),
                "medianVbarOverVobs": axis_map[galaxy].get("medianVbarOverVobs", ""),
                "baryonOnlyRmse": axis_map[galaxy].get("baryonOnlyRmse", ""),
                "canonicalRmse": axis_map[galaxy].get("canonicalRmse", ""),
            }
        )
    return rows


def external_component_manual_review_decision_rows(axis_rows: list[dict], control_rows: list[dict]) -> list[dict]:
    original = next((row for row in control_rows if row.get("candidateId") == "original-selected-components"), {})
    half_scale = next((row for row in control_rows if row.get("candidateId") == "half-scale-components"), {})
    original_gain = parse_float(original.get("canonicalGainPctVsBaryonOnly"))
    half_gain = parse_float(half_scale.get("canonicalGainPctVsBaryonOnly"))
    high = [row for row in axis_rows if row.get("manualReviewPriority") == "high"]
    if len(high) >= 5 and math.isfinite(original_gain) and math.isfinite(half_gain) and half_gain > original_gain + 50:
        decision = "do not use reconstructed components for external scoring yet"
        next_step = "manual digitization or switch to a source with native component tables"
        reason = "selected components are too scale/identity sensitive; half-scale control changes the conclusion"
    elif high:
        decision = "manual review required before scoring"
        next_step = "visually inspect selected source paths and reassign component identities"
        reason = "one or more selected components fail amplitude sanity"
    else:
        decision = "manual pack passed"
        next_step = "externalcomponentvalidate can be rerun with reviewed identities"
        reason = "no high-priority selected-component sanity risk"
    return [
        {
            "decision": decision,
            "nextStep": next_step,
            "reason": reason,
            "highPriorityManualReviewCount": len(high),
            "originalCanonicalGainPctVsBaryonOnly": original_gain,
            "halfScaleCanonicalGainPctVsBaryonOnly": half_gain,
            "promotionEligible": False,
        }
    ]


def external_component_manual_report(capsule: dict, overlay_rows: list[dict], decision_rows: list[dict]) -> str:
    metrics = capsule["metrics"]
    overlay_lines = [
        f"- `{row['galaxy']}`: [{Path(row['overlayPath']).name}](overlays/{Path(row['overlayPath']).name}) - {row['axisSanityRisk']}"
        for row in overlay_rows
    ]
    decision = decision_rows[0] if decision_rows else {}
    return "\n".join(
        [
            "# MTS External Component Manual Review Pack v10",
            "",
            f"Verdict: **{capsule['verdict']}**",
            "",
            "This pack turns the v9 selected-component sanity failure into visual review artifacts. It does not fetch, score v21, promote canonical MTS, or treat LITTLE THINGS vector reconstructions as SPARC-equivalent component tables.",
            "",
            "## Summary",
            "",
            f"- Network fetch required: `{metrics['networkFetchRequired']}`",
            f"- Overlay SVGs written: `{metrics['overlayCount']}`",
            f"- High-priority manual review targets: `{metrics['highPriorityManualReviewCount']}`",
            f"- Original selected-component gain: `{fmt(metrics['originalCanonicalGainPctVsBaryonOnly'])}%`",
            f"- Half-scale selected-component gain: `{fmt(metrics['halfScaleCanonicalGainPctVsBaryonOnly'])}%`",
            "",
            "## Decision",
            "",
            f"- Decision: `{decision.get('decision', '')}`",
            f"- Next step: `{decision.get('nextStep', '')}`",
            f"- Reason: {decision.get('reason', '')}",
            "",
            "## Overlays",
            "",
            *overlay_lines,
            "",
            "## How To Read The SVGs",
            "",
            "The left panel compares observed Vobs, selected gas, selected stellar disk, and derived Vbar in physical score space. The right panel shows the selected gas and stellar paths in raw figure coordinates. If Vbar already follows or exceeds Vobs, canonical support overshoot is expected and the case is not valid external scoring evidence yet.",
        ]
    )


def write_external_component_manual_artifacts(out_dir: Path, review_dir: Path, validation_dir: Path, calibration_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    overlay_dir = out_dir / "overlays"
    overlay_dir.mkdir(parents=True, exist_ok=True)
    axis_rows = read_csv_rows(review_dir / "mts_external_component_axis_sanity.csv")
    control_rows = read_csv_rows(review_dir / "mts_external_component_null_controls.csv")
    manual_rows = read_csv_rows(review_dir / "mts_external_component_manual_review_targets.csv")
    overlay_rows = external_component_manual_overlay_rows(review_dir, validation_dir, calibration_dir, overlay_dir)
    decision_rows = external_component_manual_review_decision_rows(axis_rows, control_rows)
    original = next((row for row in control_rows if row.get("candidateId") == "original-selected-components"), {})
    half_scale = next((row for row in control_rows if row.get("candidateId") == "half-scale-components"), {})
    verdict = decision_rows[0]["decision"] if decision_rows else "manual review required before scoring"
    metrics = {
        "componentReviewDir": str(review_dir.resolve()),
        "componentValidationDir": str(validation_dir.resolve()),
        "componentCalibrationDir": str(calibration_dir.resolve()),
        "networkFetchRequired": False,
        "overlayCount": len(overlay_rows),
        "manualReviewTargetCount": len(manual_rows),
        "highPriorityManualReviewCount": sum(1 for row in manual_rows if row.get("manualReviewPriority") == "high"),
        "originalCanonicalGainPctVsBaryonOnly": parse_float(original.get("canonicalGainPctVsBaryonOnly")),
        "halfScaleCanonicalGainPctVsBaryonOnly": parse_float(half_scale.get("canonicalGainPctVsBaryonOnly")),
        "promotionEligible": False,
    }
    capsule = {
        "mode": "externalcomponentmanualpack",
        "createdUtc": "deterministic",
        "verdict": verdict,
        "metrics": metrics,
        "outputs": {
            "report": "mts_external_component_manual_review_report.md",
            "overlayIndex": "mts_external_component_manual_overlay_index.csv",
            "manualReviewTargets": "mts_external_component_manual_review_targets.csv",
            "decision": "mts_external_component_manual_review_decision.csv",
            "overlays": "overlays/*.svg",
        },
    }
    write_csv(out_dir / "mts_external_component_manual_overlay_index.csv", overlay_rows)
    write_csv(out_dir / "mts_external_component_manual_review_targets.csv", manual_rows)
    write_csv(out_dir / "mts_external_component_manual_review_decision.csv", decision_rows)
    (out_dir / "mts_external_component_manual_review_report.md").write_text(
        external_component_manual_report(capsule, overlay_rows, decision_rows),
        encoding="utf-8",
    )
    (out_dir / "mts_external_component_manual_review_capsule.json").write_text(
        json.dumps(json_clean(capsule), indent=2, sort_keys=True),
        encoding="utf-8",
    )
    return capsule


def cmd_externalcomponentmanualpack(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_EXTERNAL_COMPONENT_MANUAL_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    review_dir = Path(args.component_review_dir) if args.component_review_dir else DEFAULT_EXTERNAL_COMPONENT_REVIEW_OUT
    validation_dir = Path(args.component_validation_dir) if args.component_validation_dir else DEFAULT_EXTERNAL_COMPONENT_VALIDATE_OUT
    calibration_dir = Path(args.component_calibration_dir) if args.component_calibration_dir else DEFAULT_EXTERNAL_COMPONENT_CALIBRATE_OUT
    capsule = write_external_component_manual_artifacts(out_dir, review_dir, validation_dir, calibration_dir)
    metrics = capsule["metrics"]
    print("MTS external component manual review pack v10: SVG overlays written; no framework scoring")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"overlays={metrics['overlayCount']}",
                f"manual_targets={metrics['manualReviewTargetCount']}",
                f"high_priority={metrics['highPriorityManualReviewCount']}",
                f"network_fetch_required={metrics['networkFetchRequired']}",
            ]
        )
    )
    print(f"component_review_dir={review_dir.resolve()}")
    print(f"Wrote MTS external component manual review pack to {out_dir.resolve()}")


EXTERNAL_NATIVE_SOURCE_CAP = 20_000_000
EXTERNAL_NATIVE_DISKMASS_ARXIV = "1308.0336"


def external_native_source_specs() -> list[dict]:
    specs = [
        {
            "sourceId": "sparc-official-page",
            "sourceName": "SPARC official data page",
            "survey": "SPARC",
            "url": "https://astroweb.cwru.edu/SPARC/",
            "cacheRelativePath": "sparc/sparc-official-page.html",
            "fileType": "html",
            "maxBytes": 2_000_000,
            "sourceRole": "parser/control provenance",
            "evidenceUse": "parser-control-only",
            "reasonIncluded": "Official control source for native SPARC radial Vgas/Vdisk/Vbul tables.",
        },
        {
            "sourceId": "sparc-mass-models",
            "sourceName": "SPARC official Newtonian mass models",
            "survey": "SPARC",
            "url": "https://astroweb.cwru.edu/SPARC/MassModels_Lelli2016c.mrt",
            "cacheRelativePath": "sparc/MassModels_Lelli2016c.mrt",
            "fileType": "mrt",
            "maxBytes": 2_000_000,
            "sourceRole": "native component parser control",
            "evidenceUse": "parser-control-only",
            "reasonIncluded": "Known native radial component table: R, Vobs, errV, Vgas, Vdisk, Vbul.",
        },
        {
            "sourceId": "sparc-table1",
            "sourceName": "SPARC official galaxy sample / references",
            "survey": "SPARC",
            "url": "https://astroweb.cwru.edu/SPARC/SPARC_Lelli2016c.mrt",
            "cacheRelativePath": "sparc/SPARC_Lelli2016c.mrt",
            "fileType": "mrt",
            "maxBytes": 1_500_000,
            "sourceRole": "metadata control",
            "evidenceUse": "parser-control-only",
            "reasonIncluded": "Distance, inclination, quality, and reference metadata control for SPARC rows.",
        },
    ]
    for spec in external_baryon_source_specs():
        if spec["survey"] == "LITTLE_THINGS":
            specs.append(
                {
                    "sourceId": f"native-{spec['sourceId']}",
                    "sourceName": spec["sourceName"],
                    "survey": spec["survey"],
                    "url": spec["url"],
                    "cacheRelativePath": spec["cacheRelativePath"],
                    "fileType": spec["fileType"],
                    "maxBytes": spec["maxBytes"],
                    "sourceRole": "native component search",
                    "evidenceUse": "external-search",
                    "reasonIncluded": "LITTLE THINGS is kept proxy/manual-only unless a native radial component table is found.",
                }
            )
    for arxiv_id, survey, label in [
        (EXTERNAL_BARYON_THINGS_ARXIV, "THINGS", "THINGS / de Blok et al. 2008"),
        (EXTERNAL_NATIVE_DISKMASS_ARXIV, "DISKMASS", "DiskMass Survey VII"),
    ]:
        stem = arxiv_id.replace(".", "_")
        specs.extend(
            [
                {
                    "sourceId": f"{survey.lower()}-arxiv-abs",
                    "sourceName": f"{label} arXiv abstract",
                    "survey": survey,
                    "url": f"https://arxiv.org/abs/{arxiv_id}",
                    "cacheRelativePath": f"{survey.lower()}-arxiv/{stem}.html",
                    "fileType": "html",
                    "maxBytes": 1_500_000,
                    "sourceRole": "native component search",
                    "evidenceUse": "external-search",
                    "reasonIncluded": "Small paper metadata page for source provenance and links.",
                },
                {
                    "sourceId": f"{survey.lower()}-arxiv-source",
                    "sourceName": f"{label} arXiv source bundle",
                    "survey": survey,
                    "url": f"https://arxiv.org/e-print/{arxiv_id}",
                    "cacheRelativePath": f"{survey.lower()}-arxiv/{stem}.source",
                    "fileType": "source",
                    "maxBytes": EXTERNAL_NATIVE_SOURCE_CAP,
                    "sourceRole": "native component search",
                    "evidenceUse": "external-search",
                    "reasonIncluded": "Bounded source bundle; scanned for machine-readable radial component tables.",
                },
                {
                    "sourceId": f"{survey.lower()}-arxiv-pdf",
                    "sourceName": f"{label} PDF",
                    "survey": survey,
                    "url": f"https://arxiv.org/pdf/{arxiv_id}",
                    "cacheRelativePath": f"{survey.lower()}-arxiv/{stem}.pdf",
                    "fileType": "pdf",
                    "maxBytes": EXTERNAL_NATIVE_SOURCE_CAP,
                    "sourceRole": "provenance only",
                    "evidenceUse": "manual-review-only",
                    "reasonIncluded": "Bounded PDF retained for provenance; not used for manual digitization in this mode.",
                },
            ]
        )
    return specs


def external_native_source_inventory_rows() -> list[dict]:
    rows = []
    for spec in external_native_source_specs():
        rows.append(
            {
                "sourceId": spec["sourceId"],
                "sourceName": spec["sourceName"],
                "survey": spec["survey"],
                "url": spec["url"],
                "fileType": spec["fileType"],
                "maxBytes": spec["maxBytes"],
                "sourceRole": spec["sourceRole"],
                "evidenceUse": spec["evidenceUse"],
                "reasonIncluded": spec["reasonIncluded"],
                "largeDownloadAllowed": False,
            }
        )
    return rows


def external_native_fetch_inventory_rows(source_cache: Path, offline: bool) -> list[dict]:
    rows = []
    for spec in external_native_source_specs():
        path = source_cache / spec["cacheRelativePath"]
        status, size, digest = external_validation_download(spec["url"], path, max_bytes=spec["maxBytes"], offline=offline)
        exists = path.exists()
        # Keep repeat artifacts deterministic: online fetch errors and offline missing states
        # both mean that no usable cached source exists.
        cache_status = "available" if exists else ("skipped-size-cap" if status == "skipped-size-cap" else "unavailable")
        rows.append(
            {
                "sourceId": spec["sourceId"],
                "sourceName": spec["sourceName"],
                "survey": spec["survey"],
                "url": spec["url"],
                "cachePath": str(path),
                "fileType": spec["fileType"],
                "sourceRole": spec["sourceRole"],
                "evidenceUse": spec["evidenceUse"],
                "cacheStatus": cache_status,
                "sizeBytes": path.stat().st_size if exists else size,
                "sha256": file_sha256(path) if exists else digest,
                "sourceCacheOnD": str(source_cache).upper().startswith("D:"),
                "downloadPolicy": "bounded small source/table fetch",
                "maxBytes": spec["maxBytes"],
                "largeDownloadAllowed": False,
            }
        )
    return sorted(rows, key=lambda row: (row["survey"], row["sourceId"]))


def external_native_text_has_component_columns(text: str) -> dict:
    lower = text.lower()
    radius_hit = any(token in lower for token in [" radius", " rad ", " r ", "r(kpc", "radius_kpc", " kpc"])
    observed_hit = any(token in lower for token in ["vobs", "vrot", "v_c", "rotation"])
    gas_hit = any(token in lower for token in ["vgas", "v_gas", "v atom", "vatom", "gas contribution", "vhi", "v_hi"])
    disk_hit = any(token in lower for token in ["vdisk", "v_disk", "vstar", "v_star", "stellar disk", "stellar contribution"])
    bulge_hit = any(token in lower for token in ["vbul", "v_bul", "bulge contribution"])
    numeric_lines = sum(1 for line in text.splitlines() if re.match(r"^\s*[-+]?\d+(?:\.\d+)?(?:\s+[-+]?\d+(?:\.\d+)?){3,}", line))
    return {
        "radiusColumnHint": radius_hit,
        "observedVelocityHint": observed_hit,
        "gasComponentHint": gas_hit,
        "stellarComponentHint": disk_hit,
        "bulgeComponentHint": bulge_hit,
        "numericDataLineCount": numeric_lines,
        "nativeComponentCandidate": radius_hit and observed_hit and gas_hit and disk_hit and numeric_lines >= 5,
    }


def external_native_read_member_texts(path: Path, max_members: int = 80) -> list[dict]:
    rows = []
    if not path.exists():
        return rows
    text_suffixes = {".tex", ".txt", ".dat", ".csv", ".tsv", ".mrt", ".table", ".tbl", ".html"}
    try:
        if tarfile.is_tarfile(path):
            with tarfile.open(path, "r:*") as archive:
                members = [member for member in archive.getmembers() if member.isfile()]
                for member in members[:max_members]:
                    suffix = Path(member.name).suffix.lower()
                    if suffix not in text_suffixes and suffix:
                        rows.append(
                            {
                                "memberName": member.name,
                                "memberSize": member.size,
                                "memberKind": "non-table-source-member",
                                "scanStatus": "not-text-table",
                                **external_native_text_has_component_columns(""),
                            }
                        )
                        continue
                    if member.size > 1_000_000:
                        rows.append(
                            {
                                "memberName": member.name,
                                "memberSize": member.size,
                                "memberKind": "large-text-member",
                                "scanStatus": "skipped-large-member",
                                **external_native_text_has_component_columns(""),
                            }
                        )
                        continue
                    handle = archive.extractfile(member)
                    if handle is None:
                        continue
                    text = handle.read().decode("utf-8", errors="ignore")
                    hints = external_native_text_has_component_columns(text)
                    rows.append(
                        {
                            "memberName": member.name,
                            "memberSize": member.size,
                            "memberKind": "text/source-member",
                            "scanStatus": "scanned",
                            **hints,
                        }
                    )
        elif path.suffix.lower() in text_suffixes or path.suffix.lower() in {".source", ".mrt"}:
            text = path.read_text(encoding="utf-8", errors="ignore")
            rows.append(
                {
                    "memberName": Path(path).name,
                    "memberSize": path.stat().st_size,
                    "memberKind": "standalone-text",
                    "scanStatus": "scanned",
                    **external_native_text_has_component_columns(text),
                }
            )
    except (OSError, tarfile.TarError, UnicodeError):
        rows.append(
            {
                "memberName": Path(path).name,
                "memberSize": path.stat().st_size if path.exists() else 0,
                "memberKind": "read-error",
                "scanStatus": "read-error",
                **external_native_text_has_component_columns(""),
            }
        )
    return rows


def external_native_sparc_component_rows(path: Path) -> list[dict]:
    rows = []
    if not path.exists():
        return rows
    for line in path.read_text(encoding="utf-8", errors="ignore").splitlines():
        parts = line.strip().split()
        if len(parts) < 10:
            continue
        try:
            values = [float(part) for part in parts[1:10]]
        except ValueError:
            continue
        rows.append(
            {
                "galaxy": parts[0],
                "survey": "SPARC",
                "sourceId": "sparc-mass-models",
                "evidenceUse": "parser-control-only",
                "radiusKpc": values[1],
                "vObs": values[2],
                "errV": values[3],
                "vGas": values[4],
                "vDisk": values[5],
                "vBul": values[6],
                "sbDisk": values[7],
                "sbBul": values[8],
                "mlConvention": "Vdisk and Vbul are stellar component circular speeds for M/L=1; Vgas includes gas contribution as supplied by SPARC",
                "provenancePath": str(path),
                "frameworkEvidenceAllowed": False,
                "notes": "SPARC control row only; not independent external validation.",
            }
        )
    return rows


def external_native_table_catalog_rows(source_cache: Path, fetch_rows: list[dict]) -> list[dict]:
    rows = []
    sparc_rows = external_native_sparc_component_rows(source_cache / "sparc" / "MassModels_Lelli2016c.mrt")
    rows.append(
        {
            "survey": "SPARC",
            "sourceId": "sparc-mass-models",
            "tableName": "MassModels_Lelli2016c.mrt",
            "cachePath": str(source_cache / "sparc" / "MassModels_Lelli2016c.mrt"),
            "cacheStatus": "available" if sparc_rows else "missing",
            "classification": "native radial components found",
            "recordCount": len(sparc_rows),
            "galaxyCount": len({row["galaxy"] for row in sparc_rows}),
            "hasRadius": bool(sparc_rows),
            "hasVobs": bool(sparc_rows),
            "hasErrV": bool(sparc_rows),
            "hasRadialVgas": bool(sparc_rows),
            "hasRadialVdisk": bool(sparc_rows),
            "hasRadialVbul": bool(sparc_rows),
            "hasMtsStateScaleCandidate": True,
            "usableForMtsComponentScoring": False,
            "frameworkEvidenceAllowed": False,
            "notes": "Native component table exists but is SPARC parser/control evidence only.",
        }
    )
    little_catalog = external_baryon_table_catalog(source_cache)
    for row in little_catalog:
        if row["survey"] != "LITTLE_THINGS":
            continue
        if parse_bool(row["hasRadialRows"]):
            classification = "figure/manual digitization only" if row["tableName"].startswith("rot") else "not usable for MTS scoring"
        elif parse_bool(row["hasGlobalBaryonicMass"]):
            classification = "global baryonic metadata only"
        else:
            classification = "not usable for MTS scoring"
        rows.append(
            {
                "survey": row["survey"],
                "sourceId": f"native-little-things-{safe_file_stem(row['tableName'])}",
                "tableName": row["tableName"],
                "cachePath": row["cachePath"],
                "cacheStatus": row["cacheStatus"],
                "classification": classification,
                "recordCount": row["recordCount"],
                "galaxyCount": "",
                "hasRadius": row["hasRadialRows"],
                "hasVobs": row["hasRadialRows"],
                "hasErrV": False,
                "hasRadialVgas": False,
                "hasRadialVdisk": False,
                "hasRadialVbul": False,
                "hasMtsStateScaleCandidate": row["hasMtsStateScaleCandidate"],
                "usableForMtsComponentScoring": False,
                "frameworkEvidenceAllowed": False,
                "notes": row["notes"],
            }
        )
    for fetch in fetch_rows:
        if fetch["fileType"] not in {"source", "html", "mrt"} or fetch["survey"] in {"SPARC", "LITTLE_THINGS"}:
            continue
        path = Path(fetch["cachePath"])
        member_rows = external_native_read_member_texts(path)
        candidates = [row for row in member_rows if parse_bool(row.get("nativeComponentCandidate"))]
        classification = "native radial components found" if candidates else "observed rotation only"
        if fetch["fileType"] == "html" and not candidates:
            classification = "global baryonic metadata only"
        rows.append(
            {
                "survey": fetch["survey"],
                "sourceId": fetch["sourceId"],
                "tableName": Path(fetch["cachePath"]).name,
                "cachePath": fetch["cachePath"],
                "cacheStatus": fetch["cacheStatus"],
                "classification": classification,
                "recordCount": sum(parse_float(row.get("numericDataLineCount"), 0.0) for row in member_rows),
                "galaxyCount": "",
                "hasRadius": any(parse_bool(row.get("radiusColumnHint")) for row in member_rows),
                "hasVobs": any(parse_bool(row.get("observedVelocityHint")) for row in member_rows),
                "hasErrV": False,
                "hasRadialVgas": any(parse_bool(row.get("gasComponentHint")) for row in member_rows),
                "hasRadialVdisk": any(parse_bool(row.get("stellarComponentHint")) for row in member_rows),
                "hasRadialVbul": any(parse_bool(row.get("bulgeComponentHint")) for row in member_rows),
                "hasMtsStateScaleCandidate": False,
                "usableForMtsComponentScoring": bool(candidates),
                "frameworkEvidenceAllowed": bool(candidates),
                "notes": "Source bundle scan; candidate requires a machine-readable radial component import before scoring." if candidates else "No bounded machine-readable radial Vgas/Vdisk table detected.",
            }
        )
        for member in candidates[:12]:
            rows.append(
                {
                    "survey": fetch["survey"],
                    "sourceId": f"{fetch['sourceId']}::{safe_file_stem(member['memberName'])}",
                    "tableName": member["memberName"],
                    "cachePath": fetch["cachePath"],
                    "cacheStatus": fetch["cacheStatus"],
                    "classification": "native radial components found",
                    "recordCount": member["numericDataLineCount"],
                    "galaxyCount": "",
                    "hasRadius": member["radiusColumnHint"],
                    "hasVobs": member["observedVelocityHint"],
                    "hasErrV": False,
                    "hasRadialVgas": member["gasComponentHint"],
                    "hasRadialVdisk": member["stellarComponentHint"],
                    "hasRadialVbul": member["bulgeComponentHint"],
                    "hasMtsStateScaleCandidate": False,
                    "usableForMtsComponentScoring": False,
                    "frameworkEvidenceAllowed": False,
                    "notes": "Potential component-like source member found, but no parser is promoted in v21.17.",
                }
            )
    return sorted(rows, key=lambda row: (row["survey"], row["sourceId"], str(row["tableName"])))


def external_native_component_prefill_rows(source_cache: Path, table_rows: list[dict]) -> list[dict]:
    rows = external_native_sparc_component_rows(source_cache / "sparc" / "MassModels_Lelli2016c.mrt")
    # Non-SPARC native imports are intentionally empty unless a true machine-readable
    # component table is found and a parser is written for that exact source.
    for table in table_rows:
        if table["survey"] == "SPARC" or table["classification"] != "native radial components found":
            continue
        if parse_bool(table.get("frameworkEvidenceAllowed")):
            rows.append(
                {
                    "galaxy": "",
                    "survey": table["survey"],
                    "sourceId": table["sourceId"],
                    "evidenceUse": "external-search-needs-parser",
                    "radiusKpc": "",
                    "vObs": "",
                    "errV": "",
                    "vGas": "",
                    "vDisk": "",
                    "vBul": "",
                    "sbDisk": "",
                    "sbBul": "",
                    "mlConvention": "MISSING: source-specific import parser required",
                    "provenancePath": table["cachePath"],
                    "frameworkEvidenceAllowed": False,
                    "notes": "Native-looking member detected but not imported in v21.17.",
                }
            )
    return rows


def external_native_scoreability_rows(table_rows: list[dict], component_rows: list[dict]) -> list[dict]:
    rows = []
    surveys = sorted({row["survey"] for row in table_rows} | {"SPARC", "THINGS", "LITTLE_THINGS", "DISKMASS"})
    for survey in surveys:
        survey_tables = [row for row in table_rows if row["survey"] == survey]
        native_tables = [row for row in survey_tables if row["classification"] == "native radial components found"]
        imported_rows = [row for row in component_rows if row["survey"] == survey]
        imported_galaxies = sorted({row["galaxy"] for row in imported_rows if row.get("galaxy")})
        external_allowed = survey != "SPARC" and any(parse_bool(row.get("frameworkEvidenceAllowed")) for row in survey_tables)
        if survey == "SPARC" and imported_rows:
            verdict = "native radial components found; parser-control only"
            missing = ""
        elif external_allowed:
            verdict = "native component candidate found; parser/import still required"
            missing = "sourceSpecificParser;velocityUncertaintyOrStateScaleAudit"
        elif survey == "LITTLE_THINGS":
            verdict = "figure/manual digitization only"
            missing = "nativeRadialVgas;nativeRadialVdisk;MTSStateScale"
        elif survey == "THINGS":
            verdict = "observed rotation only"
            missing = "nativeRadialVgas;nativeRadialVdisk;MTSStateScale"
        elif survey == "DISKMASS":
            verdict = "global baryonic metadata only"
            missing = "nativePerGalaxyRadialComponentRows;externalObservedCurveJoin;MTSStateScale"
        else:
            verdict = "not usable for MTS scoring"
            missing = "nativeRadialComponents"
        rows.append(
            {
                "survey": survey,
                "nativeComponentTables": len(native_tables),
                "importedComponentRows": len(imported_rows),
                "importedGalaxyCount": len(imported_galaxies),
                "nonSparcFrameworkScoreableGalaxyCount": len(imported_galaxies) if survey != "SPARC" and external_allowed else 0,
                "scoreabilityVerdict": verdict,
                "missingInputs": missing,
                "frameworkEvidenceAllowed": external_allowed,
                "notes": "SPARC rows are controls only." if survey == "SPARC" else "",
            }
        )
    return rows


def external_native_import_error_rows(fetch_rows: list[dict], table_rows: list[dict], score_rows: list[dict]) -> list[dict]:
    rows = []
    for fetch in fetch_rows:
        if fetch["cacheStatus"] != "available":
            rows.append(
                {
                    "scope": "source-fetch",
                    "survey": fetch["survey"],
                    "sourceId": fetch["sourceId"],
                    "issue": fetch["cacheStatus"],
                    "missingInput": "cachedSourceFile",
                    "source": fetch["url"],
                    "notes": "Source unavailable under bounded fetch policy.",
                }
            )
    for table in table_rows:
        if table["survey"] == "SPARC":
            continue
        if table["classification"] != "native radial components found":
            rows.append(
                {
                    "scope": "table-capability",
                    "survey": table["survey"],
                    "sourceId": table["sourceId"],
                    "issue": table["classification"],
                    "missingInput": "native radial Vgas/Vdisk/Vbul-style component curves",
                    "source": table["cachePath"],
                    "notes": table["notes"],
                }
            )
    for row in score_rows:
        if row["survey"] != "SPARC" and parse_float(row["nonSparcFrameworkScoreableGalaxyCount"], 0.0) < 1:
            rows.append(
                {
                    "scope": "survey-scoreability",
                    "survey": row["survey"],
                    "sourceId": "",
                    "issue": row["scoreabilityVerdict"],
                    "missingInput": row["missingInputs"],
                    "source": "",
                    "notes": "No non-SPARC full MTS-scoreable native component rows produced.",
                }
            )
    return rows


def external_native_report(capsule: dict, score_rows: list[dict], table_rows: list[dict]) -> str:
    metrics = capsule["metrics"]
    score_lines = [
        f"- {row['survey']}: native tables `{row['nativeComponentTables']}`, imported rows `{row['importedComponentRows']}`, non-SPARC scoreable galaxies `{row['nonSparcFrameworkScoreableGalaxyCount']}`, verdict `{row['scoreabilityVerdict']}`."
        for row in score_rows
    ]
    table_lines = [
        f"- {row['survey']} `{row['tableName']}`: {row['classification']} ({row['recordCount']} rows)."
        for row in table_rows[:40]
    ]
    return "\n".join(
        [
            "# MTS v21.17 Native Component Table Search + Import Pilot",
            "",
            f"Verdict: **{capsule['verdict']}**",
            "",
            "This mode searches bounded source products for native radial baryonic component tables. It does not use LITTLE THINGS vector reconstructions as validation evidence, does not manually digitize PDFs, and does not promote v21.",
            "",
            "## Source Cache",
            "",
            f"- Source cache: `{capsule['sourceCache']}`",
            f"- Source cache on D: `{metrics['sourceCacheOnDDrive']}`",
            f"- Source files available: `{metrics['availableSourceCount']}` / `{metrics['sourceInventoryRows']}`",
            f"- Large download policy violations: `{metrics['largeDownloadPolicyViolations']}`",
            "",
            "## Scoreability",
            "",
            f"- SPARC control component rows: `{metrics['sparcControlComponentRows']}`",
            f"- Non-SPARC native component tables detected: `{metrics['nonSparcNativeComponentTableCount']}`",
            f"- Non-SPARC full-scoreable galaxies imported: `{metrics['nonSparcFrameworkScoreableGalaxyCount']}`",
            f"- Next step: `{metrics['nextStep']}`",
            "",
            *score_lines,
            "",
            "## Table Classification",
            "",
            *table_lines,
            "",
            "## Interpretation",
            "",
            "SPARC remains the parser/control source. External rows are only framework evidence when a native, machine-readable radial component table can supply observed velocity, uncertainty, gas component, stellar component, and MTS state/scale inputs. If no such source is found, the external validation path is blocked by missing baryonic components rather than by MTS/v21 physics.",
        ]
    )


def write_external_native_components_artifacts(out_dir: Path, source_cache: Path, offline: bool) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    source_cache.mkdir(parents=True, exist_ok=True)
    source_rows = external_native_source_inventory_rows()
    fetch_rows = external_native_fetch_inventory_rows(source_cache, offline)
    table_rows = external_native_table_catalog_rows(source_cache, fetch_rows)
    component_rows = external_native_component_prefill_rows(source_cache, table_rows)
    score_rows = external_native_scoreability_rows(table_rows, component_rows)
    error_rows = external_native_import_error_rows(fetch_rows, table_rows, score_rows)
    non_sparc_native_tables = [
        row for row in table_rows
        if row["survey"] != "SPARC" and row["classification"] == "native radial components found" and parse_bool(row.get("frameworkEvidenceAllowed"))
    ]
    non_sparc_scoreable = sum(int(parse_float(row["nonSparcFrameworkScoreableGalaxyCount"], 0.0)) for row in score_rows)
    sparc_control_rows = sum(1 for row in component_rows if row["survey"] == "SPARC")
    available_sources = sum(1 for row in fetch_rows if row["cacheStatus"] == "available")
    policy_violations = sum(1 for row in fetch_rows if parse_float(row.get("sizeBytes"), 0.0) > parse_float(row.get("maxBytes"), EXTERNAL_NATIVE_SOURCE_CAP))
    if non_sparc_scoreable >= 5:
        verdict = "external native-component validation ready"
        next_step = "externalnativevalidate"
    elif non_sparc_native_tables:
        verdict = "native component source found; parser required"
        next_step = "write source-specific native component parser"
    else:
        verdict = "external full scoring blocked by missing baryonic components"
        next_step = "manual digitization or switch source family"
    metrics = {
        "sourceCacheOnDDrive": str(source_cache).upper().startswith("D:"),
        "sourceInventoryRows": len(source_rows),
        "availableSourceCount": available_sources,
        "largeDownloadPolicyViolations": policy_violations,
        "tableCatalogRows": len(table_rows),
        "sparcControlComponentRows": sparc_control_rows,
        "nonSparcNativeComponentTableCount": len(non_sparc_native_tables),
        "nonSparcFrameworkScoreableGalaxyCount": non_sparc_scoreable,
        "littleThingsVectorReconstructionsCountedAsValidation": False,
        "sparcControlOnly": True,
        "v21Promoted": False,
        "nextStep": next_step,
    }
    capsule = {
        "mode": "externalnativecomponents",
        "createdUtc": "deterministic",
        "verdict": verdict,
        "sourceCache": str(source_cache.resolve()),
        "metrics": metrics,
        "outputs": {
            "sourceInventory": "mts_external_native_source_inventory.csv",
            "fetchInventory": "mts_external_native_fetch_inventory.csv",
            "tableCatalog": "mts_external_native_table_catalog.csv",
            "componentPrefill": "mts_external_native_component_prefill.csv",
            "scoreability": "mts_external_native_scoreability.csv",
            "importErrors": "mts_external_native_import_errors.csv",
            "report": "mts_external_native_report.md",
        },
    }
    write_csv(out_dir / "mts_external_native_source_inventory.csv", source_rows)
    write_csv(out_dir / "mts_external_native_fetch_inventory.csv", fetch_rows)
    write_csv(out_dir / "mts_external_native_table_catalog.csv", table_rows)
    write_csv(out_dir / "mts_external_native_component_prefill.csv", component_rows)
    write_csv(out_dir / "mts_external_native_scoreability.csv", score_rows)
    write_csv(out_dir / "mts_external_native_import_errors.csv", error_rows)
    if non_sparc_scoreable >= 5:
        write_csv(out_dir / "mts_external_native_candidate_scores.csv", [])
        write_csv(out_dir / "mts_external_native_case_ledger.csv", [])
    (out_dir / "mts_external_native_report.md").write_text(
        external_native_report(capsule, score_rows, table_rows),
        encoding="utf-8",
    )
    (out_dir / "mts_external_native_capsule.json").write_text(
        json.dumps(json_clean(capsule), indent=2, sort_keys=True),
        encoding="utf-8",
    )
    return capsule


def cmd_externalnativecomponents(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_EXTERNAL_NATIVE_COMPONENTS_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    source_cache = Path(args.source_cache) if args.source_cache else DEFAULT_EXTERNAL_NATIVE_COMPONENTS_CACHE
    capsule = write_external_native_components_artifacts(out_dir, source_cache, args.offline)
    metrics = capsule["metrics"]
    print("MTS v21.17 native component table search/import pilot: no v21 promotion")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"sources={metrics['availableSourceCount']}/{metrics['sourceInventoryRows']}",
                f"sparc_control_rows={metrics['sparcControlComponentRows']}",
                f"non_sparc_native_tables={metrics['nonSparcNativeComponentTableCount']}",
                f"non_sparc_scoreable={metrics['nonSparcFrameworkScoreableGalaxyCount']}",
                f"source_cache_on_d={metrics['sourceCacheOnDDrive']}",
                f"large_policy_violations={metrics['largeDownloadPolicyViolations']}",
            ]
        )
    )
    print(f"source_cache={source_cache.resolve()}")
    print(f"Wrote MTS v21.17 native component pack to {out_dir.resolve()}")


