def external_component_scout_manifest_specs(manifest_path: Path | None) -> list[dict]:
    if not manifest_path or not manifest_path.exists():
        return []
    rows = []
    for row in read_csv_rows(manifest_path):
        url = str(row.get("url", "")).strip()
        source_id = str(row.get("sourceId") or row.get("source_id") or safe_file_stem(url)).strip()
        if not url or not source_id:
            continue
        cache_relative = str(row.get("cacheRelativePath") or row.get("cache_relative_path") or f"manifest/{safe_file_stem(source_id)}").strip()
        max_bytes = int(parse_float(row.get("maxBytes") or row.get("max_bytes"), 5_000_000))
        rows.append(
            {
                "sourceId": f"manifest-{safe_file_stem(source_id)}",
                "sourceName": str(row.get("sourceName") or row.get("source_name") or source_id),
                "sourceFamily": str(row.get("sourceFamily") or row.get("source_family") or "manifest-supplied"),
                "survey": str(row.get("survey") or "MANIFEST"),
                "url": url,
                "cacheRelativePath": cache_relative,
                "fileType": str(row.get("fileType") or row.get("file_type") or Path(cache_relative).suffix.lower().lstrip(".") or "html"),
                "maxBytes": max(1_000, max_bytes),
                "expectedUtility": str(row.get("expectedUtility") or row.get("expected_utility") or "manifest-scout"),
                "reasonIncluded": str(row.get("reasonIncluded") or row.get("reason_included") or "User-supplied source manifest row."),
            }
        )
    return rows


def external_component_scout_targets(manifest_path: Path | None) -> list[dict]:
    by_id: dict[str, dict] = {}
    for spec in external_component_scout_source_specs() + external_component_scout_manifest_specs(manifest_path):
        by_id[spec["sourceId"]] = spec
    rows = []
    for spec in by_id.values():
        rows.append(
            {
                "sourceId": spec["sourceId"],
                "sourceName": spec["sourceName"],
                "sourceFamily": spec["sourceFamily"],
                "survey": spec["survey"],
                "url": spec["url"],
                "cacheRelativePath": spec["cacheRelativePath"],
                "fileType": spec["fileType"],
                "maxBytes": spec["maxBytes"],
                "expectedUtility": spec["expectedUtility"],
                "reasonIncluded": spec["reasonIncluded"],
                "largeDownloadAllowed": False,
            }
        )
    return sorted(rows, key=lambda row: (row["sourceFamily"], row["survey"], row["sourceId"]))


def external_component_scout_fetch_rows(source_cache: Path, targets: list[dict], offline: bool) -> list[dict]:
    rows = []
    for target in targets:
        path = source_cache / target["cacheRelativePath"]
        status, size, digest = external_validation_download(target["url"], path, max_bytes=int(parse_float(target["maxBytes"], 5_000_000)), offline=offline)
        exists = path.exists()
        cache_status = "available" if exists else ("skipped-size-cap" if status == "skipped-size-cap" else "unavailable")
        rows.append(
            {
                "sourceId": target["sourceId"],
                "sourceName": target["sourceName"],
                "sourceFamily": target["sourceFamily"],
                "survey": target["survey"],
                "url": target["url"],
                "cachePath": str(path),
                "fileType": target["fileType"],
                "cacheStatus": cache_status,
                "sizeBytes": path.stat().st_size if exists else size,
                "sha256": file_sha256(path) if exists else digest,
                "sourceCacheOnD": str(source_cache).upper().startswith("D:"),
                "downloadPolicy": "bounded source scout fetch",
                "maxBytes": target["maxBytes"],
                "largeDownloadAllowed": False,
            }
        )
    return sorted(rows, key=lambda row: (row["sourceFamily"], row["survey"], row["sourceId"]))


def external_component_scout_keyword_snippet(text: str) -> tuple[str, str]:
    lowered = text.lower()
    tokens = ["vgas", "v_gas", "vhi", "v_hi", "vdisk", "v_disk", "vstar", "v_star", "vbul", "v_bul", "v atom", "stellar disk", "gas contribution"]
    hits = [token for token in tokens if token in lowered]
    if not hits:
        return "", ""
    index = min(lowered.find(token) for token in hits if lowered.find(token) >= 0)
    start = max(0, index - 120)
    end = min(len(text), index + 220)
    snippet = re.sub(r"\s+", " ", text[start:end]).strip()
    return ";".join(sorted(hits)), snippet


def external_component_scout_text_for_path(path: Path, file_type: str) -> str:
    if not path.exists():
        return ""
    if file_type.lower() == "pdf":
        return ""
    suffix = path.suffix.lower()
    if suffix in EXTERNAL_COMPONENT_SCOUT_TEXT_SUFFIXES or file_type.lower() in {"html", "tsv", "txt", "dat", "mrt", "readme"}:
        try:
            return path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            return ""
    return ""


def external_component_scout_scan_hits(fetch_rows: list[dict]) -> list[dict]:
    rows = []
    for fetch in fetch_rows:
        if fetch["cacheStatus"] != "available":
            continue
        path = Path(fetch["cachePath"])
        file_type = str(fetch.get("fileType", "")).lower()
        member_rows = []
        if file_type == "source" or (path.exists() and tarfile.is_tarfile(path)):
            member_rows = external_native_read_member_texts(path, max_members=220)
        else:
            text = external_component_scout_text_for_path(path, file_type)
            if text:
                hints = external_native_text_has_component_columns(text)
                tokens, snippet = external_component_scout_keyword_snippet(text)
                member_rows = [
                    {
                        "memberName": path.name,
                        "memberSize": path.stat().st_size,
                        "memberKind": "standalone-text",
                        "scanStatus": "scanned",
                        "matchedTokens": tokens,
                        "snippet": snippet,
                        **hints,
                    }
                ]
        for member in member_rows:
            suffix = Path(str(member.get("memberName", ""))).suffix.lower()
            table_like = suffix in EXTERNAL_COMPONENT_SCOUT_TABLE_SUFFIXES or fetch["fileType"] in {"mrt", "tsv", "dat", "csv"}
            native_candidate = table_like and parse_bool(member.get("nativeComponentCandidate"))
            tokens = member.get("matchedTokens", "")
            snippet = member.get("snippet", "")
            if not tokens and any(parse_bool(member.get(key)) for key in ["gasComponentHint", "stellarComponentHint", "bulgeComponentHint"]):
                source_text = ""
                if file_type != "source":
                    source_text = external_component_scout_text_for_path(path, file_type)
                tokens, snippet = external_component_scout_keyword_snippet(source_text)
            if not native_candidate and not any(parse_bool(member.get(key)) for key in ["radiusColumnHint", "observedVelocityHint", "gasComponentHint", "stellarComponentHint", "bulgeComponentHint"]):
                continue
            rows.append(
                {
                    "sourceId": fetch["sourceId"],
                    "sourceName": fetch["sourceName"],
                    "sourceFamily": fetch["sourceFamily"],
                    "survey": fetch["survey"],
                    "cachePath": fetch["cachePath"],
                    "memberName": member.get("memberName", ""),
                    "memberKind": member.get("memberKind", ""),
                    "scanStatus": member.get("scanStatus", ""),
                    "tableLikeMember": table_like,
                    "radiusColumnHint": member.get("radiusColumnHint", False),
                    "observedVelocityHint": member.get("observedVelocityHint", False),
                    "gasComponentHint": member.get("gasComponentHint", False),
                    "stellarComponentHint": member.get("stellarComponentHint", False),
                    "bulgeComponentHint": member.get("bulgeComponentHint", False),
                    "numericDataLineCount": member.get("numericDataLineCount", 0),
                    "nativeComponentCandidate": native_candidate,
                    "matchedTokens": tokens,
                    "snippet": snippet,
                }
            )
    return sorted(rows, key=lambda row: (row["survey"], row["sourceId"], row["memberName"]))


def external_component_scout_classification(fetch: dict, hits: list[dict]) -> str:
    if fetch["cacheStatus"] != "available":
        return "large-data/source unavailable"
    if fetch["survey"] == "SPARC" and "mass-models" in fetch["sourceId"]:
        return "native component table candidate"
    native = [row for row in hits if parse_bool(row.get("nativeComponentCandidate"))]
    if native:
        return "native component table candidate"
    has_radius_obs = any(parse_bool(row.get("radiusColumnHint")) and parse_bool(row.get("observedVelocityHint")) for row in hits)
    has_component_words = any(parse_bool(row.get("gasComponentHint")) or parse_bool(row.get("stellarComponentHint")) for row in hits)
    has_numeric = any(parse_float(row.get("numericDataLineCount"), 0.0) >= 5 for row in hits)
    if has_radius_obs and not has_component_words:
        return "observed rotation only"
    if has_component_words and has_numeric:
        return "figure/manual digitization only"
    if has_component_words or "mass" in str(fetch.get("sourceName", "")).lower() or "baryon" in str(fetch.get("sourceName", "")).lower():
        return "global baryonic metadata only"
    return "not useful for MTS scoring"


def external_component_scout_scoreability_rows(targets: list[dict], fetch_rows: list[dict], hit_rows: list[dict]) -> list[dict]:
    hits_by_source: dict[str, list[dict]] = {}
    for row in hit_rows:
        hits_by_source.setdefault(row["sourceId"], []).append(row)
    targets_by_source = {row["sourceId"]: row for row in targets}
    rows = []
    for fetch in fetch_rows:
        target = targets_by_source.get(fetch["sourceId"], {})
        hits = hits_by_source.get(fetch["sourceId"], [])
        classification = external_component_scout_classification(fetch, hits)
        framework_allowed = classification == "native component table candidate" and fetch["survey"] != "SPARC"
        if framework_allowed:
            next_action = "externalnativeparser"
        elif fetch["survey"] == "SPARC":
            next_action = "parser control only"
        elif classification == "figure/manual digitization only":
            next_action = "manual digitization candidate"
        else:
            next_action = "dead end for full MTS scoring"
        rows.append(
            {
                "sourceId": fetch["sourceId"],
                "sourceName": fetch["sourceName"],
                "sourceFamily": fetch["sourceFamily"],
                "survey": fetch["survey"],
                "url": fetch["url"],
                "cacheStatus": fetch["cacheStatus"],
                "classification": classification,
                "scanHitCount": len(hits),
                "nativeComponentHitCount": sum(1 for row in hits if parse_bool(row.get("nativeComponentCandidate"))),
                "frameworkEvidenceAllowed": framework_allowed,
                "sparcControlOnly": fetch["survey"] == "SPARC",
                "littleThingsVectorExcluded": fetch["survey"] == "LITTLE_THINGS",
                "nextAction": next_action,
                "reasonIncluded": target.get("reasonIncluded", ""),
            }
        )
    return sorted(rows, key=lambda row: (row["sourceFamily"], row["survey"], row["sourceId"]))


def external_component_scout_next_action_rows(score_rows: list[dict]) -> list[dict]:
    candidates = [row for row in score_rows if parse_bool(row.get("frameworkEvidenceAllowed"))]
    manual = [row for row in score_rows if row["classification"] == "figure/manual digitization only" and row["survey"] != "SPARC"]
    rows = []
    if candidates:
        for row in candidates:
            rows.append(
                {
                    "priority": "1",
                    "sourceId": row["sourceId"],
                    "survey": row["survey"],
                    "nextAction": "externalnativeparser",
                    "why": "Non-SPARC native component table candidate found.",
                    "url": row["url"],
                }
            )
    else:
        rows.append(
            {
                "priority": "1",
                "sourceId": "none",
                "survey": "ALL",
                "nextAction": "manual digitization or new data provider",
                "why": "no public small native-component source found; external validation requires manual digitization or a new data provider",
                "url": "",
            }
        )
    for row in manual[:12]:
        rows.append(
            {
                "priority": "2",
                "sourceId": row["sourceId"],
                "survey": row["survey"],
                "nextAction": "manual digitization candidate",
                "why": row["classification"],
                "url": row["url"],
            }
        )
    return rows


def external_component_scout_report(capsule: dict, score_rows: list[dict], next_rows: list[dict]) -> str:
    metrics = capsule["metrics"]
    score_lines = [
        f"- {row['survey']} `{row['sourceId']}`: {row['classification']}; next `{row['nextAction']}`."
        for row in score_rows
    ]
    next_lines = [
        f"- Priority {row['priority']}: {row['nextAction']} ({row['survey']} / {row['sourceId']}) - {row['why']}"
        for row in next_rows
    ]
    return "\n".join(
        [
            "# MTS v21.18 External Component Source Scout",
            "",
            f"Verdict: **{capsule['verdict']}**",
            "",
            "This mode scouts source families for machine-readable radial baryonic component tables. It does not score MTS, does not promote v21, and does not count SPARC as independent external evidence.",
            "",
            "## Source Cache",
            "",
            f"- Source cache: `{capsule['sourceCache']}`",
            f"- Source cache on D: `{metrics['sourceCacheOnDDrive']}`",
            f"- Available sources: `{metrics['availableSourceCount']}` / `{metrics['targetCount']}`",
            f"- Large download policy violations: `{metrics['largeDownloadPolicyViolations']}`",
            "",
            "## Result",
            "",
            f"- Non-SPARC native component candidates: `{metrics['nonSparcNativeCandidateCount']}`",
            f"- Manual/digitization candidates: `{metrics['manualDigitizationCandidateCount']}`",
            f"- SPARC control-only sources: `{metrics['sparcControlSourceCount']}`",
            f"- LITTLE THINGS vector reconstructions counted as validation: `{metrics['littleThingsVectorReconstructionsCountedAsValidation']}`",
            "",
            "## Next Actions",
            "",
            *next_lines,
            "",
            "## Source Classifications",
            "",
            *score_lines,
            "",
            "## Plain-English Conclusion",
            "",
            "If no non-SPARC native component candidate appears above, then no public small native-component source was found in this scout; external validation requires manual digitization or a new data provider.",
        ]
    )


def write_external_component_scout_artifacts(out_dir: Path, source_cache: Path, source_manifest: Path | None, offline: bool) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    source_cache.mkdir(parents=True, exist_ok=True)
    target_rows = external_component_scout_targets(source_manifest)
    fetch_rows = external_component_scout_fetch_rows(source_cache, target_rows, offline)
    hit_rows = external_component_scout_scan_hits(fetch_rows)
    score_rows = external_component_scout_scoreability_rows(target_rows, fetch_rows, hit_rows)
    next_rows = external_component_scout_next_action_rows(score_rows)
    candidates = [row for row in score_rows if parse_bool(row.get("frameworkEvidenceAllowed"))]
    manual = [row for row in score_rows if row["classification"] == "figure/manual digitization only" and row["survey"] != "SPARC"]
    policy_violations = sum(1 for row in fetch_rows if parse_float(row.get("sizeBytes"), 0.0) > parse_float(row.get("maxBytes"), EXTERNAL_COMPONENT_SCOUT_CAP))
    if candidates:
        verdict = "native component parser target found"
    else:
        verdict = "no public small native-component source found; external validation requires manual digitization or a new data provider"
    metrics = {
        "sourceCacheOnDDrive": str(source_cache).upper().startswith("D:"),
        "targetCount": len(target_rows),
        "availableSourceCount": sum(1 for row in fetch_rows if row["cacheStatus"] == "available"),
        "largeDownloadPolicyViolations": policy_violations,
        "scanHitCount": len(hit_rows),
        "nonSparcNativeCandidateCount": len(candidates),
        "manualDigitizationCandidateCount": len(manual),
        "sparcControlSourceCount": sum(1 for row in score_rows if row["survey"] == "SPARC"),
        "littleThingsVectorReconstructionsCountedAsValidation": False,
        "v21Promoted": False,
        "sourceManifest": str(source_manifest.resolve()) if source_manifest and source_manifest.exists() else "",
    }
    capsule = {
        "mode": "externalcomponentscout",
        "createdUtc": "deterministic",
        "verdict": verdict,
        "sourceCache": str(source_cache.resolve()),
        "metrics": metrics,
        "outputs": {
            "targets": "mts_external_source_scout_targets.csv",
            "fetchInventory": "mts_external_source_scout_fetch_inventory.csv",
            "scanHits": "mts_external_source_scout_scan_hits.csv",
            "scoreability": "mts_external_source_scout_scoreability.csv",
            "nextActions": "mts_external_source_scout_next_actions.csv",
            "report": "mts_external_source_scout_report.md",
        },
    }
    write_csv(out_dir / "mts_external_source_scout_targets.csv", target_rows)
    write_csv(out_dir / "mts_external_source_scout_fetch_inventory.csv", fetch_rows)
    write_csv(out_dir / "mts_external_source_scout_scan_hits.csv", hit_rows)
    write_csv(out_dir / "mts_external_source_scout_scoreability.csv", score_rows)
    write_csv(out_dir / "mts_external_source_scout_next_actions.csv", next_rows)
    (out_dir / "mts_external_source_scout_report.md").write_text(
        external_component_scout_report(capsule, score_rows, next_rows),
        encoding="utf-8",
    )
    (out_dir / "mts_external_source_scout_capsule.json").write_text(
        json.dumps(json_clean(capsule), indent=2, sort_keys=True),
        encoding="utf-8",
    )
    return capsule


def cmd_externalcomponentscout(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_EXTERNAL_COMPONENT_SCOUT_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    source_cache = Path(args.source_cache) if args.source_cache else DEFAULT_EXTERNAL_COMPONENT_SCOUT_CACHE
    source_manifest = Path(args.source_manifest) if args.source_manifest else None
    capsule = write_external_component_scout_artifacts(out_dir, source_cache, source_manifest, args.offline)
    metrics = capsule["metrics"]
    print("MTS v21.18 external component source scout: no framework scoring")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"sources={metrics['availableSourceCount']}/{metrics['targetCount']}",
                f"native_candidates={metrics['nonSparcNativeCandidateCount']}",
                f"manual_candidates={metrics['manualDigitizationCandidateCount']}",
                f"scan_hits={metrics['scanHitCount']}",
                f"source_cache_on_d={metrics['sourceCacheOnDDrive']}",
                f"large_policy_violations={metrics['largeDownloadPolicyViolations']}",
            ]
        )
    )
    print(f"source_cache={source_cache.resolve()}")
    print(f"Wrote MTS v21.18 source scout pack to {out_dir.resolve()}")


def organize_folder_stats(path: Path) -> tuple[int, int]:
    file_count = 0
    total_bytes = 0
    for root, _dirs, files in os.walk(path):
        for name in files:
            file_count += 1
            try:
                total_bytes += (Path(root) / name).stat().st_size
            except OSError:
                pass
    return file_count, total_bytes


def organize_outputs_manifest_rows() -> list[dict]:
    OUTPUT_PACK_ROOT.mkdir(parents=True, exist_ok=True)
    rows = []
    excluded_names = {"mts-galaxy-lab-repo", "g project", "galaxy work"}
    for source in sorted(DESKTOP_ROOT.iterdir(), key=lambda item: item.name.lower()):
        source_name = source.name.lower()
        if not source.is_dir() or not source_name.startswith("mts-") or source_name in excluded_names:
            continue
        target = OUTPUT_PACK_ROOT / source.name
        file_count, total_bytes = organize_folder_stats(source)
        status = "pending"
        message = ""
        if target.exists():
            status = "collision-skipped"
            message = "destination already exists; source left in place"
        else:
            try:
                shutil.move(str(source), str(target))
                status = "moved"
                message = "moved into Galaxy Work output pack root"
            except OSError as exc:
                status = "move-error"
                message = str(exc)
        rows.append(
            {
                "folderName": source.name,
                "oldPath": str(source),
                "newPath": str(target),
                "fileCount": file_count,
                "totalSizeBytes": total_bytes,
                "moveStatus": status,
                "message": message,
            }
        )
    return rows


def write_organize_outputs_artifacts() -> dict:
    rows = organize_outputs_manifest_rows()
    manifest_path = OUTPUT_PACK_ROOT / "mts_output_pack_manifest.csv"
    if rows:
        write_csv(manifest_path, rows)
    elif manifest_path.exists():
        rows = read_csv_rows(manifest_path)
    else:
        write_csv(manifest_path, rows)
    excluded_names = {"mts-galaxy-lab-repo", "g project", "galaxy work"}
    remaining = [
        path for path in DESKTOP_ROOT.iterdir()
        if path.is_dir() and path.name.lower().startswith("mts-") and path.name.lower() not in excluded_names
    ]
    excluded_remaining = [
        path for path in DESKTOP_ROOT.iterdir()
        if path.is_dir() and path.name.lower().startswith("mts-") and path.name.lower() in excluded_names
    ]
    capsule = {
        "mode": "organizeoutputs",
        "createdUtc": "deterministic",
        "outputPackRoot": str(OUTPUT_PACK_ROOT.resolve()),
        "manifestPath": str(manifest_path.resolve()),
        "movedCount": sum(1 for row in rows if row["moveStatus"] == "moved"),
        "collisionSkippedCount": sum(1 for row in rows if row["moveStatus"] == "collision-skipped"),
        "moveErrorCount": sum(1 for row in rows if row["moveStatus"] == "move-error"),
        "remainingDesktopMtsFolderCount": len(remaining),
        "excludedDesktopMtsFolderCount": len(excluded_remaining),
        "repoJunctionUntouched": (GALAXY_WORK_ROOT / "MTS-Galaxy-Lab-repo").exists(),
        "gProjectJunctionUntouched": (GALAXY_WORK_ROOT / "g project").exists(),
    }
    (OUTPUT_PACK_ROOT / "mts_output_pack_organize_capsule.json").write_text(
        json.dumps(json_clean(capsule), indent=2, sort_keys=True),
        encoding="utf-8",
    )
    return capsule


def cmd_organizeoutputs(_args: argparse.Namespace) -> None:
    capsule = write_organize_outputs_artifacts()
    print("MTS output organizer: desktop output packs moved into Galaxy Work")
    print(
        "\t".join(
            [
                f"moved={capsule['movedCount']}",
                f"collisions={capsule['collisionSkippedCount']}",
                f"errors={capsule['moveErrorCount']}",
                f"remaining_desktop_mts={capsule['remainingDesktopMtsFolderCount']}",
            ]
        )
    )
    print(f"output_root={capsule['outputPackRoot']}")
    print(f"manifest={capsule['manifestPath']}")


def output_pack_dir(folder_name: str) -> Path:
    organized = OUTPUT_PACK_ROOT / folder_name
    if organized.exists():
        return organized
    desktop = DESKTOP_ROOT / folder_name
    if desktop.exists():
        return desktop
    return organized


def external_manual_digitize_targets(v10_dir: Path, v12_dir: Path) -> list[dict]:
    manual_rows = read_csv_rows(v10_dir / "mts_external_component_manual_review_targets.csv")
    overlay_rows = {row.get("galaxy", ""): row for row in read_csv_rows(v10_dir / "mts_external_component_manual_overlay_index.csv")}
    rows = []
    for index, row in enumerate(manual_rows, start=1):
        galaxy = row.get("galaxy", "")
        overlay = overlay_rows.get(galaxy, {})
        overlay_path = overlay.get("overlayPath", "")
        rows.append(
            {
                "priority": index,
                "galaxy": galaxy,
                "survey": "LITTLE_THINGS",
                "targetType": "manual component digitization pilot",
                "componentsToDigitize": "observed/reference;gas candidate;stellar disk candidate",
                "sourceFigureStatus": "vector/manual review available; native table unavailable",
                "sourceReviewPath": f"../{v10_dir.name}/{overlay_path}" if overlay_path else str(v10_dir),
                "blockingReason": row.get("reason", ""),
                "templateRowsPrepared": 75,
                "usedForMtsScoringNow": False,
                "usedForV21PromotionNow": False,
                "notes": "Digitized values must pass a later calibration and identity validation mode before any MTS scoring.",
            }
        )
    scout_rows = read_csv_rows(v12_dir / "mts_external_source_scout_scoreability.csv")
    for source in scout_rows:
        if source.get("survey") not in {"THINGS", "GHASP"}:
            continue
        if source.get("classification") not in {"figure/manual digitization only", "global baryonic metadata only"}:
            continue
        rows.append(
            {
                "priority": len(rows) + 1,
                "galaxy": "",
                "survey": source.get("survey", ""),
                "targetType": "source-family review before galaxy selection",
                "componentsToDigitize": "TBD after figure selection",
                "sourceFigureStatus": source.get("classification", ""),
                "sourceReviewPath": source.get("url", ""),
                "blockingReason": "source family has no native component table in v21.18 scout",
                "templateRowsPrepared": 0,
                "usedForMtsScoringNow": False,
                "usedForV21PromotionNow": False,
                "notes": "No concrete galaxy/component template is prepared until a source figure is selected.",
            }
        )
    return rows


def external_manual_digitize_template_rows(target_rows: list[dict]) -> list[dict]:
    rows = []
    components = [
        ("observed/reference", "observed rotation curve used for axis/calibration check"),
        ("gas candidate", "gas circular-speed component"),
        ("stellar disk candidate", "stellar disk circular-speed component"),
    ]
    for target in target_rows:
        galaxy = target.get("galaxy", "")
        if not galaxy:
            continue
        for component, description in components:
            for point_index in range(25):
                rows.append(
                    {
                        "galaxy": galaxy,
                        "survey": target["survey"],
                        "componentLabel": component,
                        "componentDescription": description,
                        "pointIndex": point_index,
                        "radiusKpc": "",
                        "velocityKms": "",
                        "sourceFigurePath": target["sourceReviewPath"],
                        "axisCalibrationNotes": "",
                        "digitizerTool": "",
                        "digitizedBy": "",
                        "reviewStatus": "blank-template",
                        "usableForMtsScoring": False,
                    }
                )
    return rows


def external_manual_digitize_source_pack_rows(v10_dir: Path, v12_dir: Path) -> list[dict]:
    rows = []
    for overlay in read_csv_rows(v10_dir / "mts_external_component_manual_overlay_index.csv"):
        rows.append(
            {
                "sourceType": "manual-review-overlay",
                "survey": "LITTLE_THINGS",
                "galaxy": overlay.get("galaxy", ""),
                "sourcePathOrUrl": f"../{v10_dir.name}/{overlay.get('overlayPath', '')}",
                "sourceStatus": "available",
                "intendedUse": "visual calibration and component identity review",
                "notes": overlay.get("axisSanityRisk", ""),
            }
        )
    for scout in read_csv_rows(v12_dir / "mts_external_source_scout_scoreability.csv"):
        if scout.get("survey") in {"THINGS", "GHASP", "LITTLE_THINGS"}:
            rows.append(
                {
                    "sourceType": "source-family-scout-row",
                    "survey": scout.get("survey", ""),
                    "galaxy": "",
                    "sourcePathOrUrl": scout.get("url", ""),
                    "sourceStatus": scout.get("classification", ""),
                    "intendedUse": scout.get("nextAction", ""),
                    "notes": scout.get("reasonIncluded", ""),
                }
            )
    return rows


def external_manual_digitize_instructions(capsule: dict) -> str:
    metrics = capsule["metrics"]
    return "\n".join(
        [
            "# MTS External Manual Digitization Instructions v13",
            "",
            "This is a preparation pack only. It does not score MTS, does not promote v21, and does not treat blank or future digitized values as evidence until a later validation mode checks calibration and component identity.",
            "",
            "## What To Digitize",
            "",
            "- Use the target CSV to pick a pilot galaxy.",
            "- Digitize three curves only: observed/reference, gas candidate, and stellar disk candidate.",
            "- Keep every point tied to its source figure path.",
            "- Do not invent missing bulge components for dwarf galaxies.",
            "",
            "## Guardrails",
            "",
            "- Digitized points must preserve axis calibration notes.",
            "- A later mode must compare observed/reference digitization to known kinematic points before accepting gas/disk values.",
            "- These templates are not spreadsheet homework; they are machine-ingest scaffolding for a later digitizer/parser workflow.",
            "",
            "## Counts",
            "",
            f"- Concrete pilot galaxies: `{metrics['concretePilotGalaxyCount']}`",
            f"- Blank template rows: `{metrics['templateRowCount']}`",
            f"- Source-pack rows: `{metrics['sourcePackRowCount']}`",
        ]
    )


def external_manual_digitize_report(capsule: dict, target_rows: list[dict]) -> str:
    metrics = capsule["metrics"]
    target_lines = [
        f"- `{row['galaxy'] or row['survey']}`: {row['targetType']} - {row['blockingReason']}"
        for row in target_rows[:16]
    ]
    return "\n".join(
        [
            "# MTS v13 External Manual Digitization Prep Pack",
            "",
            f"Verdict: **{capsule['verdict']}**",
            "",
            "This pack prepares the manual/external digitization route after v21.18 found no public small non-SPARC native component table. It is not a physics test.",
            "",
            "## Summary",
            "",
            f"- Output root: `{OUTPUT_PACK_ROOT}`",
            f"- Concrete pilot galaxies: `{metrics['concretePilotGalaxyCount']}`",
            f"- Source-family review rows: `{metrics['sourceFamilyReviewCount']}`",
            f"- Blank template rows: `{metrics['templateRowCount']}`",
            f"- MTS scoring performed: `{metrics['mtsScoringPerformed']}`",
            f"- v21 promoted: `{metrics['v21Promoted']}`",
            "",
            "## Pilot Targets",
            "",
            *target_lines,
            "",
            "## Next Step",
            "",
            "Use these templates with a controlled digitizer workflow, then add a later `externalmanualdigitizevalidate` mode that rejects any case whose observed/reference digitization does not match known rotation-curve points.",
        ]
    )


def write_external_manual_digitize_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    v10_dir = output_pack_dir("mts-external-component-manual-review-v10")
    v12_dir = output_pack_dir("mts-external-component-source-scout-v12")
    target_rows = external_manual_digitize_targets(v10_dir, v12_dir)
    template_rows = external_manual_digitize_template_rows(target_rows)
    source_pack_rows = external_manual_digitize_source_pack_rows(v10_dir, v12_dir)
    concrete = [row for row in target_rows if row.get("galaxy")]
    source_family = [row for row in target_rows if not row.get("galaxy")]
    metrics = {
        "v10EvidenceDir": str(v10_dir.resolve()),
        "v12EvidenceDir": str(v12_dir.resolve()),
        "concretePilotGalaxyCount": len(concrete),
        "sourceFamilyReviewCount": len(source_family),
        "targetRowCount": len(target_rows),
        "templateRowCount": len(template_rows),
        "sourcePackRowCount": len(source_pack_rows),
        "mtsScoringPerformed": False,
        "v21Promoted": False,
        "digitizedValuesAcceptedAsEvidence": False,
    }
    capsule = {
        "mode": "externalmanualdigitizepack",
        "createdUtc": "deterministic",
        "verdict": "manual digitization prep pack ready",
        "metrics": metrics,
        "outputs": {
            "targets": "mts_external_manual_digitize_targets.csv",
            "templates": "mts_external_manual_digitize_templates.csv",
            "sourcePack": "mts_external_manual_digitize_source_pack.csv",
            "instructions": "mts_external_manual_digitize_instructions.md",
            "report": "mts_external_manual_digitize_report.md",
        },
    }
    write_csv(out_dir / "mts_external_manual_digitize_targets.csv", target_rows)
    write_csv(out_dir / "mts_external_manual_digitize_templates.csv", template_rows)
    write_csv(out_dir / "mts_external_manual_digitize_source_pack.csv", source_pack_rows)
    (out_dir / "mts_external_manual_digitize_instructions.md").write_text(
        external_manual_digitize_instructions(capsule),
        encoding="utf-8",
    )
    (out_dir / "mts_external_manual_digitize_report.md").write_text(
        external_manual_digitize_report(capsule, target_rows),
        encoding="utf-8",
    )
    (out_dir / "mts_external_manual_digitize_capsule.json").write_text(
        json.dumps(json_clean(capsule), indent=2, sort_keys=True),
        encoding="utf-8",
    )
    return capsule


def cmd_externalmanualdigitizepack(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_EXTERNAL_MANUAL_DIGITIZE_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_external_manual_digitize_artifacts(out_dir)
    metrics = capsule["metrics"]
    print("MTS external manual digitization prep pack v13: no physics scoring")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"pilot_galaxies={metrics['concretePilotGalaxyCount']}",
                f"source_reviews={metrics['sourceFamilyReviewCount']}",
                f"template_rows={metrics['templateRowCount']}",
                f"scoring={metrics['mtsScoringPerformed']}",
                f"v21_promoted={metrics['v21Promoted']}",
            ]
        )
    )
    print(f"Wrote MTS manual digitization prep pack to {out_dir.resolve()}")


def external_digitize_workspace_relpath(path: Path, out_dir: Path) -> str:
    try:
        return path.resolve().relative_to(out_dir.resolve()).as_posix()
    except ValueError:
        return str(path.resolve())


def external_digitize_source_role(member_name: str) -> str:
    stem = Path(member_name).name.lower()
    if stem.startswith("rmd_dh_dm_profiles"):
        return "massModelProfile"
    if stem.startswith("rrotcur_adc_hd"):
        return "rotationCurveSupport"
    if stem.startswith("hi_spitzer_data_pv"):
        return "hiSpitzerPv"
    return "sourceFigure"


def external_digitize_role_order(role: str) -> int:
    order = {
        "massModelProfile": 0,
        "rotationCurveSupport": 1,
        "hiSpitzerPv": 2,
        "sourceFigure": 3,
    }
    return order.get(role, 99)


def external_digitize_copy_overlays(out_dir: Path, target_rows: list[dict], v10_dir: Path) -> dict[str, dict]:
    overlay_dir = out_dir / "review_overlays"
    overlay_dir.mkdir(parents=True, exist_ok=True)
    copied: dict[str, dict] = {}
    for target in target_rows:
        galaxy = target.get("galaxy", "")
        if not galaxy:
            continue
        key = external_validation_name_key(galaxy)
        source = v10_dir / "overlays" / f"{key}_component_review.svg"
        if not source.exists():
            copied[galaxy] = {
                "status": "missing",
                "sourcePath": str(source.resolve()),
                "localPath": "",
                "sha256": "",
            }
            continue
        dest = overlay_dir / source.name
        shutil.copy2(source, dest)
        copied[galaxy] = {
            "status": "copied",
            "sourcePath": str(source.resolve()),
            "localPath": external_digitize_workspace_relpath(dest, out_dir),
            "sha256": file_sha256(dest),
        }
    return copied


def external_digitize_copy_source_figures(out_dir: Path, target_rows: list[dict], source_cache: Path) -> dict[str, list[dict]]:
    source_bundle = source_cache / "little_things-arxiv" / "1502_01281.source"
    figure_root = out_dir / "source_figures"
    figure_root.mkdir(parents=True, exist_ok=True)
    figures: dict[str, list[dict]] = {row.get("galaxy", ""): [] for row in target_rows if row.get("galaxy")}
    if not source_bundle.exists():
        for galaxy in figures:
            figures[galaxy].append(
                {
                    "role": "missing",
                    "member": "",
                    "memberPath": "",
                    "archivePath": str(source_bundle.resolve()),
                    "localPath": "",
                    "sha256": "",
                    "status": "source-bundle-missing",
                }
            )
        return figures

    keys = {row.get("galaxy", ""): external_validation_name_key(row.get("galaxy", "")) for row in target_rows if row.get("galaxy")}
    with tarfile.open(source_bundle) as archive:
        members = [
            member
            for member in archive.getmembers()
            if member.isfile() and member.name.lower().endswith(".pdf")
        ]
        for galaxy, key in keys.items():
            matched = []
            for member in members:
                member_key = external_validation_name_key(Path(member.name).stem)
                if key not in member_key:
                    continue
                role = external_digitize_source_role(member.name)
                if role == "sourceFigure":
                    continue
                matched.append((role, member))
            for role, member in sorted(matched, key=lambda item: (external_digitize_role_order(item[0]), item[1].name.lower())):
                safe_dir = figure_root / external_validation_name_key(galaxy)
                safe_dir.mkdir(parents=True, exist_ok=True)
                dest = safe_dir / Path(member.name).name
                handle = archive.extractfile(member)
                if handle is None:
                    figures[galaxy].append(
                        {
                            "role": role,
                            "member": Path(member.name).name,
                            "memberPath": member.name,
                            "archivePath": str(source_bundle.resolve()),
                            "localPath": "",
                            "sha256": "",
                            "status": "extract-failed",
                        }
                    )
                    continue
                with handle, dest.open("wb") as output:
                    shutil.copyfileobj(handle, output)
                figures[galaxy].append(
                    {
                        "role": role,
                        "member": Path(member.name).name,
                        "memberPath": member.name,
                        "archivePath": str(source_bundle.resolve()),
                        "localPath": external_digitize_workspace_relpath(dest, out_dir),
                        "sha256": file_sha256(dest),
                        "status": "copied",
                    }
                )
            if not figures[galaxy]:
                figures[galaxy].append(
                    {
                        "role": "missing",
                        "member": "",
                        "memberPath": "",
                        "archivePath": str(source_bundle.resolve()),
                        "localPath": "",
                        "sha256": "",
                        "status": "no-target-figure-match",
                    }
                )
    return figures


def external_digitize_workspace_html(targets_json: str) -> str:
    return """<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>MTS External Component Digitization Workspace v14</title>
  <style>
    :root {
      --bg: #f5f5f2;
      --ink: #202124;
      --muted: #656760;
      --line: #cfcfc7;
      --panel: #ffffff;
      --accent: #146c94;
      --gas: #188c8c;
      --disk: #b8472d;
      --obs: #333333;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: Segoe UI, Arial, sans-serif;
      background: var(--bg);
      color: var(--ink);
    }
    header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      padding: 12px 16px;
      border-bottom: 1px solid var(--line);
      background: #fafaf7;
      position: sticky;
      top: 0;
      z-index: 3;
    }
    h1 { font-size: 18px; margin: 0; font-weight: 650; }
    .notice { color: var(--muted); font-size: 13px; }
    main {
      display: grid;
      grid-template-columns: 260px minmax(420px, 1fr) minmax(420px, 1fr);
      min-height: calc(100vh - 58px);
    }
    aside, section {
      border-right: 1px solid var(--line);
      padding: 12px;
      overflow: auto;
    }
    section:last-child { border-right: 0; }
    .target-button {
      display: block;
      width: 100%;
      text-align: left;
      border: 1px solid var(--line);
      background: var(--panel);
      padding: 9px 10px;
      margin-bottom: 8px;
      cursor: pointer;
      border-radius: 6px;
      color: var(--ink);
    }
    .target-button.active { border-color: var(--accent); outline: 2px solid rgba(20, 108, 148, 0.18); }
    .card {
      background: var(--panel);
      border: 1px solid var(--line);
      border-radius: 6px;
      padding: 10px;
      margin-bottom: 12px;
    }
    .row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
    label { font-size: 12px; color: var(--muted); display: block; margin-bottom: 4px; }
    select, input, button, textarea {
      font: inherit;
      border: 1px solid var(--line);
      border-radius: 5px;
      padding: 7px 8px;
      background: #fff;
      color: var(--ink);
    }
    button { cursor: pointer; }
    button.primary { background: var(--accent); color: #fff; border-color: var(--accent); }
    button.danger { border-color: #b8472d; color: #8f2c1b; }
    .layer-button.active[data-layer="observed/reference"] { border-color: var(--obs); box-shadow: inset 0 0 0 2px var(--obs); }
    .layer-button.active[data-layer="gas candidate"] { border-color: var(--gas); box-shadow: inset 0 0 0 2px var(--gas); }
    .layer-button.active[data-layer="stellar disk candidate"] { border-color: var(--disk); box-shadow: inset 0 0 0 2px var(--disk); }
    iframe, object, img.overlay {
      width: 100%;
      height: 460px;
      border: 1px solid var(--line);
      background: #fff;
      border-radius: 6px;
    }
    img.overlay { object-fit: contain; }
    #digitizer {
      width: 100%;
      aspect-ratio: 1.35;
      border: 1px solid var(--line);
      background: #fff;
      border-radius: 6px;
      touch-action: none;
    }
    table { width: 100%; border-collapse: collapse; font-size: 12px; }
    th, td { border-bottom: 1px solid var(--line); padding: 6px; text-align: left; vertical-align: top; }
    th { color: var(--muted); font-weight: 600; }
    .small { font-size: 12px; color: var(--muted); }
    .path { word-break: break-all; font-family: Consolas, monospace; font-size: 12px; }
    @media (max-width: 1100px) {
      main { grid-template-columns: 1fr; }
      aside, section { border-right: 0; border-bottom: 1px solid var(--line); }
    }
  </style>
</head>
<body>
  <script type="application/json" id="targets-json">__TARGET_DATA__</script>
  <header>
    <h1>MTS External Component Digitization Workspace v14</h1>
    <div class="notice">Manual component recovery only. No MTS scoring. No v21 promotion.</div>
  </header>
  <main>
    <aside>
      <div class="card">
        <label for="targetFilter">Targets</label>
        <input id="targetFilter" placeholder="Filter galaxy">
      </div>
      <div id="targetList"></div>
      <div class="card small">
        Click points on the digitizer panel after setting axis bounds. Exported rows remain provisional until a later validation mode matches the observed/reference curve.
      </div>
    </aside>
    <section>
      <div class="card">
        <div class="row">
          <div>
            <label for="figureSelect">Source figure</label>
            <select id="figureSelect"></select>
          </div>
          <a id="figureLink" target="_blank" rel="noreferrer">open source</a>
        </div>
        <div id="figureProvenance" class="path"></div>
      </div>
      <object id="sourceViewer" type="application/pdf"></object>
      <div class="card">
        <h3 style="margin:0 0 8px 0;font-size:15px;">Review overlay</h3>
        <img id="overlayImage" class="overlay" alt="review overlay">
        <div id="overlayPath" class="path"></div>
      </div>
    </section>
    <section>
      <div class="card">
        <div class="row" id="layerButtons"></div>
      </div>
      <div class="card">
        <div class="row">
          <div><label for="xMin">radius min</label><input id="xMin" type="number" step="0.01" value="0"></div>
          <div><label for="xMax">radius max</label><input id="xMax" type="number" step="0.01" value="10"></div>
          <div><label for="yMin">velocity min</label><input id="yMin" type="number" step="0.01" value="0"></div>
          <div><label for="yMax">velocity max</label><input id="yMax" type="number" step="0.01" value="120"></div>
        </div>
        <label for="calNotes" style="margin-top:8px;">axis calibration notes</label>
        <input id="calNotes" style="width:100%;" placeholder="axis bounds/source notes">
      </div>
      <svg id="digitizer" viewBox="0 0 800 590" role="img" aria-label="digitization canvas"></svg>
      <div class="card">
        <div class="row">
          <button id="undoPoint">Undo last point</button>
          <button id="clearTarget" class="danger">Clear this target</button>
          <button id="downloadJson" class="primary">Download JSON</button>
          <button id="downloadCsv" class="primary">Download CSV</button>
          <button id="saveExports">Save to exports folder</button>
        </div>
        <div class="small">Download filenames are mts_digitized_components.json and mts_digitized_components.csv. The Save button can write directly to a chosen exports folder in browsers that support it.</div>
      </div>
      <div class="card">
        <h3 style="margin:0 0 8px 0;font-size:15px;">Points</h3>
        <table>
          <thead><tr><th>layer</th><th>radius</th><th>velocity</th><th>source</th><th></th></tr></thead>
          <tbody id="pointTable"></tbody>
        </table>
      </div>
    </section>
  </main>
  <script>
    const payload = JSON.parse(document.getElementById('targets-json').textContent);
    const targets = payload.targets;
    const storageKey = 'mts-digitize-workspace-v14';
    const layers = ['observed/reference', 'gas candidate', 'stellar disk candidate'];
    let state = JSON.parse(localStorage.getItem(storageKey) || '{"points":[]}');
    let currentTarget = targets[0]?.galaxy || '';
    let currentLayer = layers[0];

    const colorForLayer = (layer) => layer === 'gas candidate' ? '#188c8c' : layer === 'stellar disk candidate' ? '#b8472d' : '#333333';
    const byId = (id) => document.getElementById(id);
    const activeTarget = () => targets.find(t => t.galaxy === currentTarget) || targets[0];
    const figureSelect = byId('figureSelect');

    function persist() {
      localStorage.setItem(storageKey, JSON.stringify(state));
    }

    function targetPoints() {
      return state.points.filter(p => p.galaxy === currentTarget);
    }

    function renderTargets() {
      const filter = byId('targetFilter').value.trim().toLowerCase();
      const list = byId('targetList');
      list.innerHTML = '';
      targets.filter(t => !filter || t.galaxy.toLowerCase().includes(filter)).forEach(t => {
        const button = document.createElement('button');
        button.className = 'target-button' + (t.galaxy === currentTarget ? ' active' : '');
        button.textContent = `${t.priority}. ${t.galaxy}`;
        button.onclick = () => { currentTarget = t.galaxy; renderAll(); };
        list.appendChild(button);
      });
    }

    function renderLayers() {
      const holder = byId('layerButtons');
      holder.innerHTML = '';
      layers.forEach(layer => {
        const button = document.createElement('button');
        button.className = 'layer-button' + (layer === currentLayer ? ' active' : '');
        button.dataset.layer = layer;
        button.textContent = layer;
        button.onclick = () => { currentLayer = layer; renderLayers(); };
        holder.appendChild(button);
      });
    }

    function renderFigure() {
      const target = activeTarget();
      figureSelect.innerHTML = '';
      target.sourceFigures.filter(f => f.status === 'copied').forEach((figure, index) => {
        const option = document.createElement('option');
        option.value = String(index);
        option.textContent = `${figure.role}: ${figure.member}`;
        figureSelect.appendChild(option);
      });
      if (!figureSelect.options.length) {
        const option = document.createElement('option');
        option.textContent = 'no copied source figure';
        figureSelect.appendChild(option);
      }
      updateFigureViewer();
      byId('overlayImage').src = target.reviewOverlay.localPath || '';
      byId('overlayPath').textContent = target.reviewOverlay.localPath ? `overlay: ${target.reviewOverlay.localPath}` : 'overlay missing';
    }

    function updateFigureViewer() {
      const target = activeTarget();
      const figures = target.sourceFigures.filter(f => f.status === 'copied');
      const figure = figures[Number(figureSelect.value || 0)];
      const viewer = byId('sourceViewer');
      const link = byId('figureLink');
      if (!figure) {
        viewer.removeAttribute('data');
        link.removeAttribute('href');
        byId('figureProvenance').textContent = 'No copied source figure for this target.';
        return;
      }
      viewer.setAttribute('data', figure.localPath);
      link.href = figure.localPath;
      byId('figureProvenance').textContent = `source: ${figure.archivePath} :: ${figure.memberPath}`;
    }

    function axis() {
      const xMin = Number(byId('xMin').value);
      const xMax = Number(byId('xMax').value);
      const yMin = Number(byId('yMin').value);
      const yMax = Number(byId('yMax').value);
      return {xMin, xMax, yMin, yMax};
    }

    function pointToSvg(p) {
      const a = axis();
      const left = 60, top = 30, width = 700, height = 500;
      const x = left + ((p.radiusKpc - a.xMin) / (a.xMax - a.xMin || 1)) * width;
      const y = top + height - ((p.velocityKms - a.yMin) / (a.yMax - a.yMin || 1)) * height;
      return {x, y};
    }

    function svgToPoint(evt) {
      const svg = byId('digitizer');
      const rect = svg.getBoundingClientRect();
      const sx = (evt.clientX - rect.left) * 800 / rect.width;
      const sy = (evt.clientY - rect.top) * 590 / rect.height;
      const left = 60, top = 30, width = 700, height = 500;
      const a = axis();
      const radiusKpc = a.xMin + ((sx - left) / width) * (a.xMax - a.xMin);
      const velocityKms = a.yMax - ((sy - top) / height) * (a.yMax - a.yMin);
      return {radiusKpc, velocityKms};
    }

    function renderCanvas() {
      const svg = byId('digitizer');
      svg.innerHTML = '';
      const left = 60, top = 30, width = 700, height = 500;
      const grid = document.createElementNS('http://www.w3.org/2000/svg', 'g');
      for (let i = 0; i <= 10; i++) {
        const x = left + width * i / 10;
        const y = top + height * i / 10;
        grid.insertAdjacentHTML('beforeend', `<line x1="${x}" y1="${top}" x2="${x}" y2="${top + height}" stroke="#e4e4de"/>`);
        grid.insertAdjacentHTML('beforeend', `<line x1="${left}" y1="${y}" x2="${left + width}" y2="${y}" stroke="#e4e4de"/>`);
      }
      grid.insertAdjacentHTML('beforeend', `<rect x="${left}" y="${top}" width="${width}" height="${height}" fill="none" stroke="#333"/>`);
      svg.appendChild(grid);
      targetPoints().forEach((p, index) => {
        const pt = pointToSvg(p);
        const c = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
        c.setAttribute('cx', pt.x);
        c.setAttribute('cy', pt.y);
        c.setAttribute('r', '5');
        c.setAttribute('fill', colorForLayer(p.componentLabel));
        c.setAttribute('stroke', '#fff');
        c.setAttribute('stroke-width', '1.5');
        c.dataset.index = String(index);
        svg.appendChild(c);
      });
      const a = axis();
      svg.insertAdjacentHTML('beforeend', `<text x="60" y="565" font-size="12">radius ${a.xMin} to ${a.xMax} kpc</text>`);
      svg.insertAdjacentHTML('beforeend', `<text x="8" y="30" font-size="12" transform="rotate(-90 8,30)">velocity ${a.yMin} to ${a.yMax} km/s</text>`);
    }

    function currentFigure() {
      const target = activeTarget();
      const figures = target.sourceFigures.filter(f => f.status === 'copied');
      return figures[Number(figureSelect.value || 0)] || {};
    }

    function addPoint(evt) {
      const p = svgToPoint(evt);
      const a = axis();
      const figure = currentFigure();
      state.points.push({
        galaxy: currentTarget,
        survey: activeTarget().survey,
        componentLabel: currentLayer,
        radiusKpc: Number(p.radiusKpc.toFixed(4)),
        velocityKms: Number(p.velocityKms.toFixed(4)),
        sourceFigureRole: figure.role || '',
        sourceFigurePath: figure.localPath || '',
        sourceMemberPath: figure.memberPath || '',
        axisXMin: a.xMin,
        axisXMax: a.xMax,
        axisYMin: a.yMin,
        axisYMax: a.yMax,
        axisCalibrationNotes: byId('calNotes').value,
        digitizerTool: 'mts-browser-digitizer-v14',
        reviewStatus: 'manual-digitized-provisional',
        usableForMtsScoring: false
      });
      persist();
      renderPoints();
      renderCanvas();
    }

    function renderPoints() {
      const body = byId('pointTable');
      body.innerHTML = '';
      targetPoints().forEach((p, index) => {
        const tr = document.createElement('tr');
        tr.innerHTML = `<td>${p.componentLabel}</td><td>${p.radiusKpc}</td><td>${p.velocityKms}</td><td class="path">${p.sourceFigureRole}</td><td><button data-index="${index}">delete</button></td>`;
        tr.querySelector('button').onclick = () => {
          const globalIndex = state.points.indexOf(targetPoints()[index]);
          if (globalIndex >= 0) state.points.splice(globalIndex, 1);
          persist();
          renderPoints();
          renderCanvas();
        };
        body.appendChild(tr);
      });
    }

    function exportRows() {
      return state.points.map((p, index) => ({...p, pointIndex: index}));
    }

    function csvEscape(value) {
      const s = String(value ?? '');
      return /[",\\n]/.test(s) ? `"${s.replaceAll('"', '""')}"` : s;
    }

    function exportCsvText() {
      const rows = exportRows();
      const headers = payload.exportSchema;
      return [headers.join(','), ...rows.map(row => headers.map(h => csvEscape(row[h])).join(','))].join('\\n');
    }

    function download(filename, text, type) {
      const blob = new Blob([text], {type});
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      a.click();
      URL.revokeObjectURL(url);
    }

    async function saveExports() {
      if (!window.showDirectoryPicker) {
        alert('This browser cannot write directly to a folder. Use the download buttons and place the files in exports/.');
        return;
      }
      const dir = await window.showDirectoryPicker();
      const jsonFile = await dir.getFileHandle('mts_digitized_components.json', {create: true});
      const jsonWriter = await jsonFile.createWritable();
      await jsonWriter.write(JSON.stringify({schema: payload.exportSchema, rows: exportRows()}, null, 2));
      await jsonWriter.close();
      const csvFile = await dir.getFileHandle('mts_digitized_components.csv', {create: true});
      const csvWriter = await csvFile.createWritable();
      await csvWriter.write(exportCsvText());
      await csvWriter.close();
      alert('Exports written.');
    }

    function renderAll() {
      renderTargets();
      renderLayers();
      renderFigure();
      renderPoints();
      renderCanvas();
    }

    byId('targetFilter').oninput = renderTargets;
    figureSelect.onchange = updateFigureViewer;
    byId('digitizer').addEventListener('click', addPoint);
    ['xMin','xMax','yMin','yMax'].forEach(id => byId(id).addEventListener('input', renderCanvas));
    byId('undoPoint').onclick = () => {
      const last = state.points.map((p, i) => [p, i]).filter(([p]) => p.galaxy === currentTarget).pop();
      if (last) state.points.splice(last[1], 1);
      persist();
      renderPoints();
      renderCanvas();
    };
    byId('clearTarget').onclick = () => {
      if (!confirm(`Clear all points for ${currentTarget}?`)) return;
      state.points = state.points.filter(p => p.galaxy !== currentTarget);
      persist();
      renderPoints();
      renderCanvas();
    };
    byId('downloadJson').onclick = () => download('mts_digitized_components.json', JSON.stringify({schema: payload.exportSchema, rows: exportRows()}, null, 2), 'application/json');
    byId('downloadCsv').onclick = () => download('mts_digitized_components.csv', exportCsvText(), 'text/csv');
    byId('saveExports').onclick = saveExports;
    renderAll();
  </script>
</body>
</html>
""".replace("__TARGET_DATA__", targets_json)


def external_digitize_workspace_report(capsule: dict) -> str:
    metrics = capsule["metrics"]
    return "\n".join(
        [
            "# MTS v21.19 Browser Digitization Workspace",
            "",
            f"Verdict: **{capsule['verdict']}**",
            "",
            "This is a local browser workspace for manual component recovery. It does not score MTS, does not promote v21, and does not accept digitized values as evidence until a later validation mode checks observed/reference calibration and component identity.",
            "",
            "## Counts",
            "",
            f"- Pilot galaxies loaded: `{metrics['pilotGalaxyCount']}`",
            f"- Source PDFs copied: `{metrics['sourceFigureCopiedCount']}`",
            f"- Review overlays copied: `{metrics['reviewOverlayCopiedCount']}`",
            f"- Blank template rows preloaded: `{metrics['templateRowCount']}`",
            f"- MTS scoring performed: `{metrics['mtsScoringPerformed']}`",
            f"- v21 promoted: `{metrics['v21Promoted']}`",
            "",
            "## How To Use",
            "",
            "Open `mts_external_digitize_workspace.html` locally. Select a target, use the source figure and review overlay panels, set axis bounds, click provisional points on the digitizer canvas, then export JSON/CSV into the `exports` folder.",
            "",
            "## Export Contract",
            "",
            "- JSON: `exports/mts_digitized_components.json`",
            "- CSV: `exports/mts_digitized_components.csv`",
            "- Every row is marked `usableForMtsScoring=false` until a future validation mode accepts it.",
        ]
    )


def write_external_digitize_workspace_artifacts(out_dir: Path, source_cache: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    v13_dir = output_pack_dir("mts-external-manual-digitize-pack-v13")
    v10_dir = output_pack_dir("mts-external-component-manual-review-v10")
    if not (v13_dir / "mts_external_manual_digitize_targets.csv").exists():
        write_external_manual_digitize_artifacts(v13_dir)

    target_rows_all = read_csv_rows(v13_dir / "mts_external_manual_digitize_targets.csv")
    template_rows_all = read_csv_rows(v13_dir / "mts_external_manual_digitize_templates.csv")
    target_rows = [row for row in target_rows_all if row.get("galaxy")]
    overlays = external_digitize_copy_overlays(out_dir, target_rows, v10_dir)
    source_figures = external_digitize_copy_source_figures(out_dir, target_rows, source_cache)
    template_by_galaxy: dict[str, list[dict]] = {}
    for row in template_rows_all:
        template_by_galaxy.setdefault(row.get("galaxy", ""), []).append(row)

    targets_payload = []
    target_csv_rows = []
    for row in target_rows:
        galaxy = row.get("galaxy", "")
        figures = source_figures.get(galaxy, [])
        copied_figures = [figure for figure in figures if figure.get("status") == "copied"]
        overlay = overlays.get(galaxy, {})
        templates = []
        for item in template_by_galaxy.get(galaxy, []):
            item_copy = dict(item)
            item_copy["sourceFigurePath"] = overlay.get("localPath", item_copy.get("sourceFigurePath", ""))
            templates.append(item_copy)
        payload_row = {
            "priority": int(float(row.get("priority") or 0)),
            "galaxy": galaxy,
            "survey": row.get("survey", ""),
            "targetType": row.get("targetType", ""),
            "componentsToDigitize": row.get("componentsToDigitize", ""),
            "blockingReason": row.get("blockingReason", ""),
            "reviewOverlay": overlay,
            "sourceFigures": figures,
            "templateRows": templates,
        }
        targets_payload.append(payload_row)
        target_csv_rows.append(
            {
                "priority": row.get("priority", ""),
                "galaxy": galaxy,
                "survey": row.get("survey", ""),
                "componentsToDigitize": row.get("componentsToDigitize", ""),
                "reviewOverlayPath": overlay.get("localPath", ""),
                "sourceFigureCount": len(copied_figures),
                "sourceFigureRoles": ";".join(figure.get("role", "") for figure in copied_figures),
                "sourceFigurePaths": ";".join(figure.get("localPath", "") for figure in copied_figures),
                "sourceMembers": ";".join(figure.get("memberPath", "") for figure in copied_figures),
                "templateRowsPreloaded": len(templates),
                "usedForMtsScoringNow": False,
                "usedForV21PromotionNow": False,
            }
        )

    export_schema = [
        "galaxy",
        "survey",
        "componentLabel",
        "pointIndex",
        "radiusKpc",
        "velocityKms",
        "sourceFigureRole",
        "sourceFigurePath",
        "sourceMemberPath",
        "axisXMin",
        "axisXMax",
        "axisYMin",
        "axisYMax",
        "axisCalibrationNotes",
        "digitizerTool",
        "reviewStatus",
        "usableForMtsScoring",
    ]
    payload = {
        "workspaceVersion": "v14",
        "purpose": "manual component digitization only",
        "mtsScoringPerformed": False,
        "v21Promoted": False,
        "exportSchema": export_schema,
        "targets": targets_payload,
    }
    targets_json = json.dumps(json_clean(payload), indent=2, sort_keys=True)
    (out_dir / "mts_external_digitize_workspace_targets.json").write_text(targets_json, encoding="utf-8")
    write_csv(out_dir / "mts_external_digitize_workspace_targets.csv", target_csv_rows)
    (out_dir / "mts_external_digitize_workspace.html").write_text(
        external_digitize_workspace_html(targets_json),
        encoding="utf-8",
    )
    exports_dir = out_dir / "exports"
    exports_dir.mkdir(parents=True, exist_ok=True)
    (exports_dir / "README.md").write_text(
        "\n".join(
            [
                "# MTS Digitized Component Exports",
                "",
                "Save browser exports here using these filenames:",
                "",
                "- `mts_digitized_components.json`",
                "- `mts_digitized_components.csv`",
                "",
                "These files are provisional. A later validation mode must reject any target whose observed/reference curve does not match known rotation-curve points.",
            ]
        ),
        encoding="utf-8",
    )
    metrics = {
        "pilotGalaxyCount": len(targets_payload),
        "sourceFigureCopiedCount": sum(1 for figures in source_figures.values() for figure in figures if figure.get("status") == "copied"),
        "reviewOverlayCopiedCount": sum(1 for overlay in overlays.values() if overlay.get("status") == "copied"),
        "templateRowCount": sum(len(target.get("templateRows", [])) for target in targets_payload),
        "sourceBundlePath": str((source_cache / "little_things-arxiv" / "1502_01281.source").resolve()),
        "mtsScoringPerformed": False,
        "v21Promoted": False,
        "digitizedValuesAcceptedAsEvidence": False,
    }
    capsule = {
        "mode": "externaldigitizeworkspace",
        "createdUtc": "deterministic",
        "verdict": "browser digitization workspace ready",
        "metrics": metrics,
        "outputs": {
            "html": "mts_external_digitize_workspace.html",
            "targetsJson": "mts_external_digitize_workspace_targets.json",
            "targetsCsv": "mts_external_digitize_workspace_targets.csv",
            "sourceFiguresDir": "source_figures",
            "reviewOverlaysDir": "review_overlays",
            "exportsReadme": "exports/README.md",
            "report": "mts_external_digitize_workspace_report.md",
        },
    }
    (out_dir / "mts_external_digitize_workspace_report.md").write_text(
        external_digitize_workspace_report(capsule),
        encoding="utf-8",
    )
    (out_dir / "mts_external_digitize_workspace_capsule.json").write_text(
        json.dumps(json_clean(capsule), indent=2, sort_keys=True),
        encoding="utf-8",
    )
    return capsule


def cmd_externaldigitizeworkspace(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_EXTERNAL_DIGITIZE_WORKSPACE_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    source_cache = Path(args.source_cache) if args.source_cache else DEFAULT_EXTERNAL_BARYON_BUILD_CACHE
    capsule = write_external_digitize_workspace_artifacts(out_dir, source_cache)
    metrics = capsule["metrics"]
    print("MTS browser digitization workspace v14: no physics scoring")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"pilot_galaxies={metrics['pilotGalaxyCount']}",
                f"source_pdfs={metrics['sourceFigureCopiedCount']}",
                f"overlays={metrics['reviewOverlayCopiedCount']}",
                f"template_rows={metrics['templateRowCount']}",
                f"scoring={metrics['mtsScoringPerformed']}",
                f"v21_promoted={metrics['v21Promoted']}",
            ]
        )
    )
    print(f"html={(out_dir / 'mts_external_digitize_workspace.html').resolve()}")
    print(f"Wrote MTS browser digitization workspace to {out_dir.resolve()}")


def external_figure_sanity_source_text(source_cache: Path) -> str:
    source_bundle = source_cache / "little_things-arxiv" / "1502_01281.source"
    if not source_bundle.exists():
        return ""
    try:
        with tarfile.open(source_bundle) as archive:
            member = archive.getmember("ms.tex")
            handle = archive.extractfile(member)
            if handle is None:
                return ""
            with handle:
                return handle.read().decode("utf-8", errors="replace")
    except (tarfile.TarError, KeyError, OSError):
        return ""


def external_figure_sanity_source_facts(source_cache: Path) -> list[dict]:
    source_bundle = source_cache / "little_things-arxiv" / "1502_01281.source"
    text = external_figure_sanity_source_text(source_cache)
    facts = [
        {
            "factId": "source-bundle",
            "sourcePath": str(source_bundle.resolve()),
            "fact": "cached LITTLE THINGS arXiv source bundle is the only source used",
            "supportsAutomation": True,
            "supportsHumanDigitizationTask": False,
        },
        {
            "factId": "mass-model-figures",
            "sourcePath": str(source_bundle.resolve()) + "::ms.tex",
            "fact": "source text identifies the rMD_DH_DM_profiles figures as mass-model / disk-halo / density-profile figures",
            "supportsAutomation": True,
            "supportsHumanDigitizationTask": False,
        },
        {
            "factId": "component-method",
            "sourcePath": str(source_bundle.resolve()) + "::ms.tex",
            "fact": "source text describes gas and stellar mass-model construction, but the cached bundle does not expose native radial Vgas/Vdisk tables",
            "supportsAutomation": True,
            "supportsHumanDigitizationTask": False,
        },
        {
            "factId": "caption-limit",
            "sourcePath": str(source_bundle.resolve()) + "::ms.tex",
            "fact": "parsed captions do not provide enough machine-readable color/style-to-component mapping to make manual web clicks a trustworthy evidence route",
            "supportsAutomation": False,
            "supportsHumanDigitizationTask": False,
        },
    ]
    if not text:
        facts.append(
            {
                "factId": "source-text-missing",
                "sourcePath": str(source_bundle.resolve()),
                "fact": "ms.tex could not be read from the cached bundle",
                "supportsAutomation": False,
                "supportsHumanDigitizationTask": False,
            }
        )
        return facts
    lowered = text.lower()
    facts.append(
        {
            "factId": "native-table-check",
            "sourcePath": str(source_bundle.resolve()) + "::ms.tex",
            "fact": "no parsed source marker indicates a machine-readable radial Vgas/Vdisk data table in the arXiv source bundle",
            "supportsAutomation": ("v_gas" not in lowered and "vgas" not in lowered and "v_disk" not in lowered and "vdisk" not in lowered),
            "supportsHumanDigitizationTask": False,
        }
    )
    return facts


def external_figure_sanity_case_rows(v9_dir: Path, v10_dir: Path) -> list[dict]:
    axis_rows = read_csv_rows(v9_dir / "mts_external_component_axis_sanity.csv")
    manual_rows = {
        row.get("galaxy", ""): row
        for row in read_csv_rows(v10_dir / "mts_external_component_manual_review_targets.csv")
    }
    rows = []
    for row in axis_rows:
        galaxy = row.get("galaxy", "")
        manual = manual_rows.get(galaxy, {})
        rows.append(
            {
                "galaxy": galaxy,
                "v9AxisSanityRisk": row.get("axisSanityRisk", ""),
                "baryonOnlyRmse": row.get("baryonOnlyRmse", ""),
                "canonicalRmse": row.get("canonicalRmse", ""),
                "canonicalGainPctVsBaryonOnly": row.get("canonicalGainPctVsBaryonOnly", ""),
                "medianVbarOverVobs": row.get("medianVbarOverVobs", ""),
                "vbarGreaterThanVobsRate": row.get("vbarGreaterThanVobsRate", ""),
                "gasCurveId": row.get("gasCurveId", ""),
                "stellarCurveId": row.get("stellarCurveId", ""),
                "sourceOverlay": manual.get("overlayPath", ""),
                "browserDigitizerRequired": False,
                "manualUserWorkExpected": False,
                "usableForExternalMtsEvidenceNow": False,
                "decision": "blocked by figure identity/axis sanity; do not ask user to digitize",
            }
        )
    return rows


def external_figure_sanity_component_rows(v7_dir: Path, v9_dir: Path) -> list[dict]:
    selected = read_csv_rows(v9_dir / "mts_external_component_selected_curve_review.csv")
    rows = []
    for row in selected:
        rows.append(
            {
                "galaxy": row.get("galaxy", ""),
                "componentLabel": row.get("componentLabel", ""),
                "curveId": row.get("curveId", ""),
                "figureMember": row.get("figureMember", ""),
                "panelId": row.get("panelId", ""),
                "radiusCoverageFraction": row.get("radiusCoverageFraction", ""),
                "identityScore": row.get("identityScore", ""),
                "filterReason": row.get("filterReason", ""),
                "sourceProvenance": row.get("provenance", ""),
                "machineCurveRecovered": True,
                "sourceAuthenticatedComponent": False,
                "safeToUseForMtsScoring": False,
                "reason": "vector path is recovered, but v9/v10 show selected component scale/identity is not source-authenticated enough for framework evidence",
            }
        )
    if rows:
        return rows
    for row in read_csv_rows(v7_dir / "mts_external_component_curve_identity.csv"):
        if row.get("componentIdentityUsable") != "True":
            continue
        rows.append(
            {
                "galaxy": row.get("galaxy", ""),
                "componentLabel": row.get("componentLabel", ""),
                "curveId": row.get("curveId", ""),
                "figureMember": row.get("figureMember", ""),
                "panelId": row.get("panelId", ""),
                "radiusCoverageFraction": row.get("radiusCoverageFraction", ""),
                "identityScore": row.get("identityScore", ""),
                "filterReason": row.get("filterReason", ""),
                "sourceProvenance": row.get("provenance", ""),
                "machineCurveRecovered": True,
                "sourceAuthenticatedComponent": False,
                "safeToUseForMtsScoring": False,
                "reason": "usable vector path exists, but source-authenticated component identity is not established",
            }
        )
    return rows


def external_figure_sanity_blocker_rows(v8_dir: Path, v9_dir: Path, v10_dir: Path) -> list[dict]:
    controls = {
        row.get("candidateId", ""): row
        for row in read_csv_rows(v9_dir / "mts_external_component_null_controls.csv")
    }
    review_capsule_path = v9_dir / "mts_external_component_review_capsule.json"
    manual_capsule_path = v10_dir / "mts_external_component_manual_review_capsule.json"
    validation_capsule_path = v8_dir / "mts_external_component_validation_capsule.json"
    rows = [
        {
            "blocker": "selected-components-overfit-observed-scale",
            "evidence": "v9 axis sanity shows selected Vbar often tracks or exceeds Vobs, so canonical support naturally overshoots",
            "sourceFile": str((v9_dir / "mts_external_component_axis_sanity.csv").resolve()),
            "blocksUserDigitization": True,
            "blocksExternalMtsEvidence": True,
        },
        {
            "blocker": "half-scale-control-flips-conclusion",
            "evidence": f"original selected components gain {controls.get('original-selected-components', {}).get('canonicalGainPctVsBaryonOnly', '')}; half-scale gain {controls.get('half-scale-components', {}).get('canonicalGainPctVsBaryonOnly', '')}",
            "sourceFile": str((v9_dir / "mts_external_component_null_controls.csv").resolve()),
            "blocksUserDigitization": True,
            "blocksExternalMtsEvidence": True,
        },
        {
            "blocker": "manual-review-pack-already-rejected-scoring",
            "evidence": "v10 decision says reconstructed components should not be used for external scoring yet",
            "sourceFile": str(manual_capsule_path.resolve()),
            "blocksUserDigitization": True,
            "blocksExternalMtsEvidence": True,
        },
        {
            "blocker": "browser-digitizer-not-a-scientific-gate",
            "evidence": "a user-clicked web grid cannot resolve source-authenticated curve identity or axis scaling",
            "sourceFile": str((DEFAULT_EXTERNAL_DIGITIZE_WORKSPACE_OUT / "mts_external_digitize_workspace.html").resolve()),
            "blocksUserDigitization": True,
            "blocksExternalMtsEvidence": True,
        },
        {
            "blocker": "v8-score-is-not-final-evidence",
            "evidence": "v8 scored reconstructed curves, but v9/v10 supersede it because curve identity/axis sanity failed",
            "sourceFile": str(validation_capsule_path.resolve()),
            "blocksUserDigitization": False,
            "blocksExternalMtsEvidence": True,
        },
        {
            "blocker": "v9-capsule",
            "evidence": "component identity/axis review required",
            "sourceFile": str(review_capsule_path.resolve()),
            "blocksUserDigitization": True,
            "blocksExternalMtsEvidence": True,
        },
    ]
    return rows


def external_figure_sanity_report(capsule: dict, case_rows: list[dict]) -> str:
    metrics = capsule["metrics"]
    cases = "\n".join(
        f"- `{row['galaxy']}`: {row['v9AxisSanityRisk']}" for row in case_rows
    )
    return "\n".join(
        [
            "# MTS v21.20 External Figure Sanity / No-Manual Gate",
            "",
            f"Verdict: **{capsule['verdict']}**",
            "",
            "This mode exists because the browser digitization workspace asked for manual scientific judgment that should not be put on the user. It reads the existing vector extraction, calibration, validation, review, and source-text evidence and decides whether the LITTLE THINGS figures can be used without human curve interpretation.",
            "",
            "## Plain Answer",
            "",
            "Do not fill in the browser digitizer. It is optional visual tooling only. The current evidence says the LITTLE THINGS figure-derived components are not safe external MTS evidence because the selected curves are scale/identity-sensitive.",
            "",
            "## Counts",
            "",
            f"- Cases reviewed: `{metrics['caseCount']}`",
            f"- User digitization tasks required: `{metrics['userDigitizationTasksRequired']}`",
            f"- Machine curves recovered: `{metrics['machineCurveRecoveredCount']}`",
            f"- Source-authenticated components ready for MTS scoring: `{metrics['sourceAuthenticatedComponentCount']}`",
            f"- Browser workspace required: `{metrics['browserWorkspaceRequired']}`",
            f"- MTS scoring performed: `{metrics['mtsScoringPerformed']}`",
            f"- v21 promoted: `{metrics['v21Promoted']}`",
            "",
            "## Case Decisions",
            "",
            cases,
            "",
            "## Next Scientific Move",
            "",
            "Stop the LITTLE THINGS manual-digitization branch unless a collaborator/source provides native radial component tables or an unambiguous component-data product. The framework-forward work should use the locked SPARC result and write the external LITTLE THINGS branch as blocked by source-product limitations, not as a task for Martin.",
        ]
    )


def write_external_figure_sanity_artifacts(out_dir: Path, source_cache: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    v7_dir = output_pack_dir("mts-external-component-calibration-v7")
    v8_dir = output_pack_dir("mts-external-component-validation-v8")
    v9_dir = output_pack_dir("mts-external-component-review-v9")
    v10_dir = output_pack_dir("mts-external-component-manual-review-v10")
    source_rows = external_figure_sanity_source_facts(source_cache)
    case_rows = external_figure_sanity_case_rows(v9_dir, v10_dir)
    component_rows = external_figure_sanity_component_rows(v7_dir, v9_dir)
    blocker_rows = external_figure_sanity_blocker_rows(v8_dir, v9_dir, v10_dir)
    source_authenticated = [row for row in component_rows if row.get("sourceAuthenticatedComponent") is True]
    metrics = {
        "sourceCache": str(source_cache.resolve()),
        "componentCalibrationDir": str(v7_dir.resolve()),
        "componentValidationDir": str(v8_dir.resolve()),
        "componentReviewDir": str(v9_dir.resolve()),
        "manualReviewDir": str(v10_dir.resolve()),
        "caseCount": len(case_rows),
        "machineCurveRecoveredCount": len(component_rows),
        "sourceAuthenticatedComponentCount": len(source_authenticated),
        "userDigitizationTasksRequired": 0,
        "browserWorkspaceRequired": False,
        "mtsScoringPerformed": False,
        "v21Promoted": False,
    }
    verdict = "little-things-figure-components blocked; no manual user task"
    capsule = {
        "mode": "externalfiguresanity",
        "createdUtc": "deterministic",
        "verdict": verdict,
        "metrics": metrics,
        "outputs": {
            "sourceFacts": "mts_external_figure_sanity_source_facts.csv",
            "caseLedger": "mts_external_figure_sanity_case_ledger.csv",
            "componentDecision": "mts_external_figure_sanity_component_decision.csv",
            "blockers": "mts_external_figure_sanity_blockers.csv",
            "report": "mts_external_figure_sanity_report.md",
        },
    }
    write_csv(out_dir / "mts_external_figure_sanity_source_facts.csv", source_rows)
    write_csv(out_dir / "mts_external_figure_sanity_case_ledger.csv", case_rows)
    write_csv(out_dir / "mts_external_figure_sanity_component_decision.csv", component_rows)
    write_csv(out_dir / "mts_external_figure_sanity_blockers.csv", blocker_rows)
    (out_dir / "mts_external_figure_sanity_report.md").write_text(
        external_figure_sanity_report(capsule, case_rows),
        encoding="utf-8",
    )
    (out_dir / "mts_external_figure_sanity_capsule.json").write_text(
        json.dumps(json_clean(capsule), indent=2, sort_keys=True),
        encoding="utf-8",
    )
    return capsule


def cmd_externalfiguresanity(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_EXTERNAL_FIGURE_SANITY_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    source_cache = Path(args.source_cache) if args.source_cache else DEFAULT_EXTERNAL_BARYON_BUILD_CACHE
    capsule = write_external_figure_sanity_artifacts(out_dir, source_cache)
    metrics = capsule["metrics"]
    print("MTS external figure sanity v15: no manual user task")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"cases={metrics['caseCount']}",
                f"machine_curves={metrics['machineCurveRecoveredCount']}",
                f"source_authenticated={metrics['sourceAuthenticatedComponentCount']}",
                f"user_tasks={metrics['userDigitizationTasksRequired']}",
                f"scoring={metrics['mtsScoringPerformed']}",
                f"v21_promoted={metrics['v21Promoted']}",
            ]
        )
    )
    print(f"Wrote MTS external figure sanity pack to {out_dir.resolve()}")


def external_guided_digitize_overlay_limits(svg_path: Path) -> dict:
    text = svg_path.read_text(encoding="utf-8", errors="replace") if svg_path.exists() else ""
    x_match = re.search(r"radius kpc,\s*0 to\s*([0-9.]+)", text)
    y_match = re.search(r'<text x="8" y="128"[^>]*>([0-9.]+)</text>', text)
    return {
        "xMin": 0.0,
        "xMax": parse_float(x_match.group(1)) if x_match else math.nan,
        "yMin": 0.0,
        "yMax": parse_float(y_match.group(1)) if y_match else math.nan,
        "plotBox": {"x": 70, "y": 120, "width": 500, "height": 430},
        "viewBox": {"width": 1180, "height": 780},
    }


def external_guided_digitize_workspace_html(targets_json: str) -> str:
    return """<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>MTS Guided Component Digitizer v16</title>
  <style>
    :root {
      --bg: #f4f4ef;
      --panel: #ffffff;
      --ink: #202124;
      --muted: #62645e;
      --line: #cfcfc7;
      --green: #14803d;
      --orange: #c76a00;
      --red: #b42318;
      --blue: #1f78b4;
      --disk: #e66101;
    }
    * { box-sizing: border-box; }
    body { margin: 0; font-family: Segoe UI, Arial, sans-serif; background: var(--bg); color: var(--ink); }
    header { padding: 12px 16px; border-bottom: 1px solid var(--line); background: #fbfbf8; position: sticky; top: 0; z-index: 3; }
    h1 { font-size: 20px; margin: 0 0 4px 0; }
    .sub { color: var(--muted); font-size: 13px; }
    main { display: grid; grid-template-columns: 250px minmax(620px, 1fr) 360px; min-height: calc(100vh - 65px); }
    aside, section { padding: 12px; border-right: 1px solid var(--line); overflow: auto; }
    section:last-child { border-right: 0; }
    .card { background: var(--panel); border: 1px solid var(--line); border-radius: 6px; padding: 10px; margin-bottom: 12px; }
    button, input { font: inherit; padding: 8px 10px; border: 1px solid var(--line); border-radius: 6px; background: #fff; color: var(--ink); }
    button { cursor: pointer; }
    button.primary { background: #146c94; border-color: #146c94; color: #fff; }
    button.danger { color: var(--red); border-color: #e0a29b; }
    .target { display: block; width: 100%; text-align: left; margin: 0 0 8px 0; }
    .target.active { outline: 2px solid #146c94; border-color: #146c94; }
    .step { border-left: 8px solid var(--red); }
    .step.current { border-left-color: var(--orange); background: #fff8ed; }
    .step.done { border-left-color: var(--green); background: #effaf2; }
    .step.locked { opacity: 0.72; }
    .label { font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: .03em; }
    #board { width: 100%; max-height: calc(100vh - 120px); background: white; border: 1px solid var(--line); border-radius: 6px; }
    .hint { font-size: 14px; line-height: 1.45; }
    .green { color: var(--green); font-weight: 650; }
    .orange { color: var(--orange); font-weight: 650; }
    .red { color: var(--red); font-weight: 650; }
    table { width: 100%; border-collapse: collapse; font-size: 12px; }
    th, td { border-bottom: 1px solid var(--line); padding: 6px; text-align: left; }
    .row { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
    .mono { font-family: Consolas, monospace; font-size: 12px; word-break: break-all; color: var(--muted); }
    @media (max-width: 1150px) { main { grid-template-columns: 1fr; } aside, section { border-right: 0; border-bottom: 1px solid var(--line); } }
  </style>
</head>
<body>
  <script type="application/json" id="targets-json">__TARGET_DATA__</script>
  <header>
    <h1>MTS Guided Component Digitizer v16</h1>
    <div class="sub">One thing at a time: black observed points, then blue gas curve, then orange stellar curve. Do not click the purple Vbar curve.</div>
  </header>
  <main>
    <aside>
      <div class="card hint">
        <b>What goes in the old boxes?</b><br>
        Nothing. Axis bounds are read from the overlay automatically.
      </div>
      <div id="targets"></div>
    </aside>
    <section>
      <svg id="board" viewBox="0 0 1180 780" aria-label="guided digitization overlay">
        <image id="overlay" x="0" y="0" width="1180" height="780"></image>
        <rect id="clickPane" x="70" y="120" width="500" height="430" fill="rgba(255,255,255,0.02)" stroke="#ff9900" stroke-width="3" stroke-dasharray="8 6"/>
        <g id="points"></g>
      </svg>
    </section>
    <section>
      <div class="card">
        <div class="label">Current target</div>
        <h2 id="targetTitle" style="margin:4px 0 6px 0;"></h2>
        <div id="risk" class="hint"></div>
        <div id="axis" class="mono" style="margin-top:8px;"></div>
      </div>
      <div id="steps"></div>
      <div class="card">
        <div class="row">
          <button id="undo">Undo last point</button>
          <button id="markDone" class="primary">Mark step done</button>
          <button id="clearTarget" class="danger">Clear target</button>
        </div>
      </div>
      <div class="card">
        <div class="row">
          <button id="downloadJson" class="primary">Download JSON</button>
          <button id="downloadCsv" class="primary">Download CSV</button>
        </div>
        <p class="hint">Save downloads as <code>mts_guided_digitized_components.json</code> and <code>mts_guided_digitized_components.csv</code>. These remain provisional until a later validator checks them.</p>
      </div>
      <div class="card">
        <div class="label">Clicked points</div>
        <table><thead><tr><th>layer</th><th>radius</th><th>velocity</th></tr></thead><tbody id="pointTable"></tbody></table>
      </div>
    </section>
  </main>
  <script>
    const payload = JSON.parse(document.getElementById('targets-json').textContent);
    const targets = payload.targets;
    const stepDefs = [
      { id: 'observed/reference', color: '#222222', min: 5, text: 'Click the black observed Vobs points in the left plot. This checks the axis calibration.' },
      { id: 'gas candidate', color: '#1f78b4', min: 6, text: 'Click along the blue gas candidate curve in the left plot.' },
      { id: 'stellar disk candidate', color: '#e66101', min: 6, text: 'Click along the orange stellar disk candidate curve in the left plot.' },
    ];
    const storageKey = 'mts-guided-digitizer-v16';
    let state = JSON.parse(localStorage.getItem(storageKey) || '{"points":[],"done":{}}');
    let current = targets[0]?.galaxy || '';
    const byId = id => document.getElementById(id);
    const target = () => targets.find(t => t.galaxy === current) || targets[0];
    const targetPoints = () => state.points.filter(p => p.galaxy === current);
    const stepPoints = id => targetPoints().filter(p => p.componentLabel === id);
    const doneMap = () => state.done[current] || (state.done[current] = {});
    const isDone = step => Boolean(doneMap()[step.id]) || stepPoints(step.id).length >= step.min;
    const firstOpenStep = () => stepDefs.find(s => !isDone(s)) || stepDefs[stepDefs.length - 1];
    const persist = () => localStorage.setItem(storageKey, JSON.stringify(state));
    const fmt = n => Number.isFinite(n) ? n.toFixed(3).replace(/\\.000$/, '') : '';

    function renderTargets() {
      const holder = byId('targets');
      holder.innerHTML = '';
      targets.forEach(t => {
        const b = document.createElement('button');
        b.className = 'target' + (t.galaxy === current ? ' active' : '');
        b.textContent = `${t.priority}. ${t.galaxy}`;
        b.onclick = () => { current = t.galaxy; renderAll(); };
        holder.appendChild(b);
      });
    }

    function renderMeta() {
      const t = target();
      byId('targetTitle').textContent = t.galaxy;
      byId('risk').innerHTML = `<span class="orange">Status:</span> ${t.axisSanityRisk}<br><b>Do not click purple.</b> Purple is derived Vbar, not a source curve.`;
      byId('axis').textContent = `auto axis: radius ${t.axis.xMin} to ${t.axis.xMax} kpc; velocity ${t.axis.yMin} to ${t.axis.yMax} km/s`;
      byId('overlay').setAttribute('href', t.overlayPath);
      const p = t.axis.plotBox;
      byId('clickPane').setAttribute('x', p.x);
      byId('clickPane').setAttribute('y', p.y);
      byId('clickPane').setAttribute('width', p.width);
      byId('clickPane').setAttribute('height', p.height);
    }

    function renderSteps() {
      const holder = byId('steps');
      holder.innerHTML = '';
      const currentStep = firstOpenStep();
      let unlocked = true;
      stepDefs.forEach(step => {
        const done = isDone(step);
        const locked = !done && !unlocked;
        const div = document.createElement('div');
        div.className = 'card step' + (done ? ' done' : step.id === currentStep.id ? ' current' : '') + (locked ? ' locked' : '');
        div.innerHTML = `<div class="label">${done ? '<span class="green">done</span>' : step.id === currentStep.id ? '<span class="orange">do next</span>' : '<span class="red">cannot do yet</span>'}</div><b>${step.id}</b><p class="hint">${step.text}</p><div>${stepPoints(step.id).length}/${step.min} points</div>`;
        holder.appendChild(div);
        if (!done) unlocked = false;
      });
    }

    function svgCoords(evt) {
      const svg = byId('board');
      const pt = svg.createSVGPoint();
      pt.x = evt.clientX;
      pt.y = evt.clientY;
      return pt.matrixTransform(svg.getScreenCTM().inverse());
    }

    function inPlot(pos) {
      const p = target().axis.plotBox;
      return pos.x >= p.x && pos.x <= p.x + p.width && pos.y >= p.y && pos.y <= p.y + p.height;
    }

    function toPhysical(pos) {
      const t = target();
      const p = t.axis.plotBox;
      const x = t.axis.xMin + ((pos.x - p.x) / p.width) * (t.axis.xMax - t.axis.xMin);
      const y = t.axis.yMax - ((pos.y - p.y) / p.height) * (t.axis.yMax - t.axis.yMin);
      return { radiusKpc: x, velocityKms: y };
    }

    function renderPoints() {
      const g = byId('points');
      g.innerHTML = '';
      targetPoints().forEach(p => {
        const c = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
        c.setAttribute('cx', p.svgX);
        c.setAttribute('cy', p.svgY);
        c.setAttribute('r', 5.5);
        c.setAttribute('fill', stepDefs.find(s => s.id === p.componentLabel)?.color || '#222');
        c.setAttribute('stroke', '#fff');
        c.setAttribute('stroke-width', '2');
        g.appendChild(c);
      });
      const table = byId('pointTable');
      table.innerHTML = '';
      targetPoints().forEach(p => {
        const tr = document.createElement('tr');
        tr.innerHTML = `<td>${p.componentLabel}</td><td>${fmt(p.radiusKpc)}</td><td>${fmt(p.velocityKms)}</td>`;
        table.appendChild(tr);
      });
    }

    function addPoint(evt) {
      const step = firstOpenStep();
      const pos = svgCoords(evt);
      if (!inPlot(pos)) return;
      const phys = toPhysical(pos);
      state.points.push({
        galaxy: current,
        survey: target().survey,
        componentLabel: step.id,
        radiusKpc: Number(phys.radiusKpc.toFixed(5)),
        velocityKms: Number(phys.velocityKms.toFixed(5)),
        svgX: Number(pos.x.toFixed(2)),
        svgY: Number(pos.y.toFixed(2)),
        sourceOverlayPath: target().overlayPath,
        digitizerTool: 'mts-guided-digitizer-v16',
        reviewStatus: 'manual-guided-provisional',
        usableForMtsScoring: false
      });
      persist();
      renderAll();
    }

    function rows() {
      return state.points.map((p, i) => ({ pointIndex: i, ...p }));
    }

    function csvEscape(v) {
      const s = String(v ?? '');
      return /[",\\n]/.test(s) ? `"${s.replaceAll('"', '""')}"` : s;
    }

    function csvText() {
      const headers = payload.exportSchema;
      return [headers.join(','), ...rows().map(r => headers.map(h => csvEscape(r[h])).join(','))].join('\\n');
    }

    function download(name, text, type) {
      const blob = new Blob([text], {type});
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = name;
      a.click();
      URL.revokeObjectURL(url);
    }

    byId('board').addEventListener('click', addPoint);
    byId('undo').onclick = () => {
      const indexes = state.points.map((p, i) => [p, i]).filter(([p]) => p.galaxy === current);
      const last = indexes[indexes.length - 1];
      if (last) state.points.splice(last[1], 1);
      persist();
      renderAll();
    };
    byId('markDone').onclick = () => {
      const step = firstOpenStep();
      doneMap()[step.id] = true;
      persist();
      renderAll();
    };
    byId('clearTarget').onclick = () => {
      if (!confirm(`Clear ${current}?`)) return;
      state.points = state.points.filter(p => p.galaxy !== current);
      state.done[current] = {};
      persist();
      renderAll();
    };
    byId('downloadJson').onclick = () => download('mts_guided_digitized_components.json', JSON.stringify({schema: payload.exportSchema, rows: rows()}, null, 2), 'application/json');
    byId('downloadCsv').onclick = () => download('mts_guided_digitized_components.csv', csvText(), 'text/csv');

    function renderAll() {
      renderTargets();
      renderMeta();
      renderSteps();
      renderPoints();
    }
    renderAll();
  </script>
</body>
</html>
""".replace("__TARGET_DATA__", targets_json)


def write_external_guided_digitize_workspace_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    overlay_out = out_dir / "guided_overlays"
    overlay_out.mkdir(parents=True, exist_ok=True)
    export_dir = out_dir / "exports"
    export_dir.mkdir(parents=True, exist_ok=True)
    v10_dir = output_pack_dir("mts-external-component-manual-review-v10")
    rows = read_csv_rows(v10_dir / "mts_external_component_manual_overlay_index.csv")
    target_rows = []
    for row in rows:
        galaxy = row.get("galaxy", "")
        source = v10_dir / row.get("overlayPath", "")
        if not galaxy or not source.exists():
            continue
        dest = overlay_out / source.name
        shutil.copy2(source, dest)
        axis = external_guided_digitize_overlay_limits(dest)
        target_rows.append(
            {
                "priority": len(target_rows) + 1,
                "galaxy": galaxy,
                "survey": "LITTLE_THINGS",
                "axisSanityRisk": row.get("axisSanityRisk", ""),
                "medianVbarOverVobs": row.get("medianVbarOverVobs", ""),
                "baryonOnlyRmse": row.get("baryonOnlyRmse", ""),
                "canonicalRmse": row.get("canonicalRmse", ""),
                "overlayPath": external_digitize_workspace_relpath(dest, out_dir),
                "sourceOverlayPath": str(source.resolve()),
                "axis": axis,
                "instructions": "Click black observed points first, then blue gas candidate, then orange stellar disk candidate. Do not click the purple derived Vbar curve.",
            }
        )
    export_schema = [
        "pointIndex",
        "galaxy",
        "survey",
        "componentLabel",
        "radiusKpc",
        "velocityKms",
        "svgX",
        "svgY",
        "sourceOverlayPath",
        "digitizerTool",
        "reviewStatus",
        "usableForMtsScoring",
    ]
    payload = {
        "workspaceVersion": "v16",
        "purpose": "guided overlay digitization only",
        "mtsScoringPerformed": False,
        "v21Promoted": False,
        "exportSchema": export_schema,
        "targets": target_rows,
    }
    targets_json = json.dumps(json_clean(payload), indent=2, sort_keys=True)
    (out_dir / "mts_external_guided_digitize_workspace_targets.json").write_text(targets_json, encoding="utf-8")
    write_csv(
        out_dir / "mts_external_guided_digitize_workspace_targets.csv",
        [
            {
                "priority": row["priority"],
                "galaxy": row["galaxy"],
                "survey": row["survey"],
                "xMin": row["axis"]["xMin"],
                "xMax": row["axis"]["xMax"],
                "yMin": row["axis"]["yMin"],
                "yMax": row["axis"]["yMax"],
                "overlayPath": row["overlayPath"],
                "instruction": row["instructions"],
            }
            for row in target_rows
        ],
    )
    (out_dir / "mts_external_guided_digitize_workspace.html").write_text(
        external_guided_digitize_workspace_html(targets_json),
        encoding="utf-8",
    )
    (export_dir / "README.md").write_text(
        "\n".join(
            [
                "# Guided Digitizer Exports",
                "",
                "Use the browser buttons to download:",
                "",
                "- `mts_guided_digitized_components.json`",
                "- `mts_guided_digitized_components.csv`",
                "",
                "Rows are provisional and must be validated before MTS scoring.",
            ]
        ),
        encoding="utf-8",
    )
    metrics = {
        "targetCount": len(target_rows),
        "overlayCount": len(target_rows),
        "axisBoundsAutoFilled": True,
        "stepFlowEnabled": True,
        "userFreeformAxisBoxesRequired": False,
        "purpleCurveShouldBeClicked": False,
        "mtsScoringPerformed": False,
        "v21Promoted": False,
    }
    capsule = {
        "mode": "externalguideddigitizeworkspace",
        "createdUtc": "deterministic",
        "verdict": "guided overlay digitizer ready",
        "metrics": metrics,
        "outputs": {
            "html": "mts_external_guided_digitize_workspace.html",
            "targetsJson": "mts_external_guided_digitize_workspace_targets.json",
            "targetsCsv": "mts_external_guided_digitize_workspace_targets.csv",
            "overlays": "guided_overlays",
            "exportsReadme": "exports/README.md",
        },
    }
    (out_dir / "mts_external_guided_digitize_workspace_report.md").write_text(
        "\n".join(
            [
                "# MTS Guided Component Digitizer v16",
                "",
                f"Verdict: **{capsule['verdict']}**",
                "",
                "This workspace replaces the open-ended v14 grid with a step-by-step overlay workflow.",
                "",
                "## What To Click",
                "",
                "1. Click black observed Vobs points.",
                "2. Click the blue gas candidate curve.",
                "3. Click the orange stellar disk candidate curve.",
                "4. Do not click the purple dashed Vbar curve; it is derived from gas and disk.",
                "",
                "Axis bounds are auto-filled from the overlay. No freeform axis boxes are required.",
                "",
                "## Counts",
                "",
                f"- Targets: `{metrics['targetCount']}`",
                f"- Overlay backgrounds: `{metrics['overlayCount']}`",
                f"- MTS scoring performed: `{metrics['mtsScoringPerformed']}`",
                f"- v21 promoted: `{metrics['v21Promoted']}`",
            ]
        ),
        encoding="utf-8",
    )
    (out_dir / "mts_external_guided_digitize_workspace_capsule.json").write_text(
        json.dumps(json_clean(capsule), indent=2, sort_keys=True),
        encoding="utf-8",
    )
    return capsule


def cmd_externalguideddigitizeworkspace(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_EXTERNAL_GUIDED_DIGITIZE_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_external_guided_digitize_workspace_artifacts(out_dir)
    metrics = capsule["metrics"]
    print("MTS guided overlay digitizer v16: no freeform axis boxes")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"targets={metrics['targetCount']}",
                f"overlays={metrics['overlayCount']}",
                f"axis_autofill={metrics['axisBoundsAutoFilled']}",
                f"step_flow={metrics['stepFlowEnabled']}",
                f"scoring={metrics['mtsScoringPerformed']}",
                f"v21_promoted={metrics['v21Promoted']}",
            ]
        )
    )
    print(f"html={(out_dir / 'mts_external_guided_digitize_workspace.html').resolve()}")


def read_guided_digitized_rows(path: Path) -> list[dict]:
    if not path.exists():
        return []
    if path.suffix.lower() == ".json":
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            return []
        rows = payload.get("rows", []) if isinstance(payload, dict) else []
        return [dict(row) for row in rows if isinstance(row, dict)]
    return read_csv_rows(path)


def dedupe_radius_velocity(points: list[dict], r_key: str, v_key: str, err_key: str = "") -> list[dict]:
    grouped: dict[float, list[dict]] = {}
    for point in points:
        radius = parse_float(point.get(r_key))
        velocity = parse_float(point.get(v_key))
        if not math.isfinite(radius) or not math.isfinite(velocity):
            continue
        grouped.setdefault(round(radius, 6), []).append(point)
    rows = []
    for radius, items in grouped.items():
        velocities = [parse_float(item.get(v_key)) for item in items if math.isfinite(parse_float(item.get(v_key)))]
        errors = [parse_float(item.get(err_key)) for item in items if err_key and math.isfinite(parse_float(item.get(err_key)))]
        rows.append(
            {
                "r": radius,
                "v": safe_mean(velocities),
                "err": safe_median(errors) if errors else math.nan,
                "provenance": ";".join(str(item.get("provenance", "")) for item in items if item.get("provenance")),
            }
        )
    return sorted(rows, key=lambda row: row["r"])


def simple_interp_series(series: list[dict], radius: float) -> float:
    if not series or not math.isfinite(radius):
        return math.nan
    if radius <= series[0]["r"]:
        return series[0]["v"]
    if radius >= series[-1]["r"]:
        return series[-1]["v"]
    for left, right in zip(series, series[1:]):
        if left["r"] <= radius <= right["r"]:
            denom = right["r"] - left["r"]
            if abs(denom) < 1e-12:
                return right["v"]
            t = (radius - left["r"]) / denom
            return left["v"] * (1 - t) + right["v"] * t
    return math.nan


def guided_digitize_manual_series(rows: list[dict], galaxy: str, component: str, digitized_file: Path) -> list[dict]:
    series = []
    for row in rows:
        if row.get("galaxy") != galaxy or row.get("componentLabel") != component:
            continue
        radius = parse_float(row.get("radiusKpc"))
        velocity = parse_float(row.get("velocityKms"))
        if not math.isfinite(radius) or not math.isfinite(velocity):
            continue
        series.append(
            {
                "r": radius,
                "v": velocity,
                "provenance": f"{digitized_file.resolve()}::{galaxy}:{component}:{row.get('pointIndex', '')}",
            }
        )
    series.sort(key=lambda row: row["r"])
    return series


def guided_digitize_calibration_rows(rows: list[dict], source_cache: Path) -> list[dict]:
    galaxies = sorted({row.get("galaxy", "") for row in rows if row.get("galaxy")})
    out = []
    for galaxy in galaxies:
        observed_clicks = guided_digitize_manual_series(rows, galaxy, "observed/reference", Path("manual-guided-export"))
        known_points = external_component_observed_points(source_cache, galaxy)
        known_series = dedupe_radius_velocity(
            [{"radiusKpc": point["radiusKpc"], "vObs": point["vObs"], "errV": point["errV"]} for point in known_points],
            "radiusKpc",
            "vObs",
            "errV",
        )
        residuals = []
        for click in observed_clicks:
            expected = simple_interp_series(known_series, click["r"])
            if math.isfinite(expected):
                residuals.append(click["v"] - expected)
        med_err = safe_median(point["err"] for point in known_series)
        rmse = math.sqrt(safe_mean(value * value for value in residuals)) if residuals else math.nan
        mae = safe_mean(abs(value) for value in residuals)
        threshold = max(5.0, 1.5 * med_err) if math.isfinite(med_err) else 5.0
        out.append(
            {
                "galaxy": galaxy,
                "observedClickCount": len(observed_clicks),
                "knownObservedPointCount": len(known_series),
                "observedCalibrationRmse": rmse,
                "observedCalibrationMae": mae,
                "medianErrV": med_err,
                "calibrationThresholdKms": threshold,
                "calibrationPassed": len(observed_clicks) >= 5 and math.isfinite(rmse) and rmse <= threshold,
                "maxAbsObservedResidual": max((abs(value) for value in residuals), default=math.nan),
                "residualsKms": ";".join(fmt(value) for value in residuals),
            }
        )
    return out


def guided_digitize_component_validation_rows(rows: list[dict], source_cache: Path, digitized_file: Path) -> tuple[list[dict], list[dict], list[dict], list[dict]]:
    calibration_rows = guided_digitize_calibration_rows(rows, source_cache)
    calibration_map = {row["galaxy"]: row for row in calibration_rows}
    props_map = external_proxy_global_props(external_reconstruct_source_paths(source_cache)["little-things-cds-galaxies"])
    point_rows = []
    case_ledger = []
    component_points = []
    for galaxy in sorted(calibration_map):
        passed = parse_bool(calibration_map[galaxy].get("calibrationPassed"))
        observed = external_component_observed_points(source_cache, galaxy)
        gas_series = guided_digitize_manual_series(rows, galaxy, "gas candidate", digitized_file)
        disk_series = guided_digitize_manual_series(rows, galaxy, "stellar disk candidate", digitized_file)
        for component, series in [("gas candidate", gas_series), ("stellar disk candidate", disk_series)]:
            for index, point in enumerate(series):
                component_points.append(
                    {
                        "galaxy": galaxy,
                        "componentLabel": component,
                        "pointIndex": index,
                        "radiusKpc": point["r"],
                        "velocityKms": point["v"],
                        "provenance": point["provenance"],
                        "usedForInterpolation": True,
                    }
                )
        component_rows = []
        outside_count = 0
        for index, obs in enumerate(observed):
            gas, gas_status, gas_prov = external_component_interp_with_provenance(gas_series, obs["radiusKpc"])
            disk, disk_status, disk_prov = external_component_interp_with_provenance(disk_series, obs["radiusKpc"])
            included = passed and all(math.isfinite(value) for value in [obs["radiusKpc"], obs["vObs"], obs["errV"], gas, disk])
            if gas_status == "outside-component-radius-range" or disk_status == "outside-component-radius-range":
                outside_count += 1
            point_rows.append(
                {
                    "galaxy": galaxy,
                    "survey": "LITTLE_THINGS",
                    "pointIndex": index,
                    "radiusKpc": obs["radiusKpc"],
                    "vObs": obs["vObs"],
                    "errV": obs["errV"],
                    "vGasManual": gas,
                    "vDiskManual": disk,
                    "vBulgeManual": 0.0,
                    "gasInterpStatus": gas_status,
                    "diskInterpStatus": disk_status,
                    "includedInManualComponentScore": included,
                    "gasProvenance": gas_prov,
                    "diskProvenance": disk_prov,
                }
            )
            if included:
                component_rows.append(
                    {
                        "r": obs["radiusKpc"],
                        "vObs": obs["vObs"],
                        "err": obs["errV"],
                        "vGas": gas,
                        "vDisk": disk,
                    }
                )
        props = props_map.get(external_validation_name_key(galaxy), {})
        curve = external_component_curve_from_component_rows(galaxy, component_rows, props) if passed else None
        if curve is None:
            continue
        baryon = score_curve_baryon_only(curve)
        canonical = score_curve(curve)
        case_ledger.append(
            {
                "galaxy": galaxy,
                "survey": "LITTLE_THINGS",
                "evidenceTier": "guided manual reconstructed components",
                "observedCalibrationRmse": calibration_map[galaxy].get("observedCalibrationRmse"),
                "observedCalibrationThresholdKms": calibration_map[galaxy].get("calibrationThresholdKms"),
                "observedCalibrationPassed": passed,
                "manualObservedPoints": calibration_map[galaxy].get("observedClickCount"),
                "manualGasPoints": len(gas_series),
                "manualDiskPoints": len(disk_series),
                "nScoredObservedPoints": len(component_rows),
                "outsideComponentRadiusCount": outside_count,
                "baryonOnlyRmse": baryon["rmse"],
                "canonicalRmse": canonical["rmse"],
                "canonicalGainPctVsBaryonOnly": pct_improvement(baryon["rmse"], canonical["rmse"]),
                "baryonOnlyInnerRmse": baryon["innerRmse"],
                "canonicalInnerRmse": canonical["innerRmse"],
                "baryonOnlyMidRmse": baryon["midRmse"],
                "canonicalMidRmse": canonical["midRmse"],
                "baryonOnlyOuterRmse": baryon["outerRmse"],
                "canonicalOuterRmse": canonical["outerRmse"],
                "canonicalWorstResidual": canonical["worstResidual"],
                "lockedRoute": canonical["candidateRoute"],
                "observedRouteFromManualComponentData": curve["route"],
                "routeMismatch": canonical["candidateRoute"] != curve["route"],
                "hProxy": curve["h"],
                "rOut": curve["rOut"],
                "leff": curve["leff"],
                "leffOverH": curve["leffOverH"],
                "fGasOut": curve["fGasOut"],
                "memoryLoad": curve["memoryLoad"],
                "uOut": curve["lockedModelUOut"],
                "uMax": curve["lockedModelUMax"],
                "u075": curve["lockedModelU075"],
                "componentSource": str(digitized_file.resolve()),
                "promotionEligible": False,
            }
        )
    scoreability_rows = []
    for cal in calibration_rows:
        galaxy = cal["galaxy"]
        case = next((row for row in case_ledger if row["galaxy"] == galaxy), {})
        scoreability_rows.append(
            {
                "galaxy": galaxy,
                "survey": "LITTLE_THINGS",
                "observedCalibrationPassed": cal["calibrationPassed"],
                "observedCalibrationRmse": cal["observedCalibrationRmse"],
                "manualComponentScoreability": "guided manual component scoreable" if case else "not scoreable",
                "nScoredObservedPoints": case.get("nScoredObservedPoints", 0),
                "missingOrBlockingInputs": "" if case else "calibrationFailedOrInsufficientComponentCoverage",
                "evidenceTier": "guided manual reconstruction; not SPARC-equivalent; not v21 promotion evidence",
            }
        )
    return calibration_rows, component_points, point_rows, sorted(case_ledger, key=lambda row: row["galaxy"]), scoreability_rows


def guided_digitize_candidate_scores(case_ledger: list[dict]) -> list[dict]:
    mean_baryon = safe_mean(parse_float(row.get("baryonOnlyRmse")) for row in case_ledger)
    mean_canonical = safe_mean(parse_float(row.get("canonicalRmse")) for row in case_ledger)
    return [
        {
            "candidateId": "baryon-only-guided-manual-components",
            "evidenceTier": "guided manual reconstructed components",
            "scoreableGalaxies": len(case_ledger),
            "meanRmse": mean_baryon,
            "medianRmse": safe_median(parse_float(row.get("baryonOnlyRmse")) for row in case_ledger),
            "meanGainPctVsComparator": math.nan,
            "comparator": "",
            "promotionEligible": False,
        },
        {
            "candidateId": "canonical-mts-guided-manual-components",
            "evidenceTier": "guided manual reconstructed components",
            "scoreableGalaxies": len(case_ledger),
            "meanRmse": mean_canonical,
            "medianRmse": safe_median(parse_float(row.get("canonicalRmse")) for row in case_ledger),
            "meanGainPctVsComparator": pct_improvement(mean_baryon, mean_canonical),
            "comparator": "baryonOnlyRmse",
            "routeMismatchCount": sum(1 for row in case_ledger if parse_bool(row.get("routeMismatch"))),
            "promotionEligible": False,
        },
    ]


def guided_digitize_validation_report(capsule: dict, calibration_rows: list[dict], case_ledger: list[dict], score_rows: list[dict]) -> str:
    metrics = capsule["metrics"]
    calibration_lines = [
        f"- `{row['galaxy']}`: observed RMSE `{fmt(parse_float(row['observedCalibrationRmse']))}` km/s, threshold `{fmt(parse_float(row['calibrationThresholdKms']))}`, pass `{row['calibrationPassed']}`."
        for row in calibration_rows
    ]
    case_lines = [
        f"- `{row['galaxy']}`: baryon-only `{fmt(parse_float(row['baryonOnlyRmse']))}`, canonical `{fmt(parse_float(row['canonicalRmse']))}`, gain `{fmt(parse_float(row['canonicalGainPctVsBaryonOnly']))}%`."
        for row in case_ledger
    ]
    score_lines = [
        f"- `{row['candidateId']}`: n={row['scoreableGalaxies']}, mean RMSE `{fmt(parse_float(row['meanRmse']))}`, gain `{fmt(parse_float(row['meanGainPctVsComparator']))}%`."
        for row in score_rows
    ]
    return "\n".join(
        [
            "# MTS Guided Digitized Component Validation v17",
            "",
            f"Verdict: **{capsule['verdict']}**",
            "",
            "This validates the guided browser-click export. It first checks observed/reference clicks against the known LITTLE THINGS observed rotation curves, then uses the manually clicked gas/disk candidates as provisional component curves only for cases that pass calibration.",
            "",
            "This is not SPARC-equivalent external evidence, does not promote v21, and does not make the manually clicked values canonical.",
            "",
            "## Calibration",
            "",
            *calibration_lines,
            "",
            "## Scores",
            "",
            *score_lines,
            "",
            "## Case Ledger",
            "",
            *case_lines,
            "",
            "## Interpretation",
            "",
            f"- Observed calibration passed for `{metrics['observedCalibrationPassCount']}` / `{metrics['targetCount']}` targets.",
            f"- Guided manual component scoreable targets: `{metrics['guidedManualScoreableCount']}`.",
            f"- Mean baryon-only RMSE: `{fmt(metrics['meanBaryonOnlyRmse'])}`.",
            f"- Mean canonical RMSE: `{fmt(metrics['meanCanonicalRmse'])}`.",
            f"- Canonical gain vs baryon-only: `{fmt(metrics['canonicalGainPctVsBaryonOnly'])}%`.",
            "",
            "If the guided manual result differs from the machine-vector reconstruction, the next useful step is a small uncertainty/re-click sensitivity pass, not another blind spreadsheet or open-ended digitizer task.",
        ]
    )


def write_external_guided_digitize_validate_artifacts(out_dir: Path, digitized_file: Path, source_cache: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    rows = read_guided_digitized_rows(digitized_file)
    calibration_rows, component_points, point_rows, case_ledger, scoreability_rows = guided_digitize_component_validation_rows(rows, source_cache, digitized_file)
    score_rows = guided_digitize_candidate_scores(case_ledger)
    mean_baryon = safe_mean(parse_float(row.get("baryonOnlyRmse")) for row in case_ledger)
    mean_canonical = safe_mean(parse_float(row.get("canonicalRmse")) for row in case_ledger)
    gain = pct_improvement(mean_baryon, mean_canonical)
    pass_count = sum(1 for row in calibration_rows if parse_bool(row.get("calibrationPassed")))
    verdict = "guided manual component validation usable for sensitivity review" if len(case_ledger) >= 5 and pass_count == len(calibration_rows) else "guided manual component validation incomplete"
    metrics = {
        "digitizedFile": str(digitized_file.resolve()),
        "sourceCache": str(source_cache.resolve()),
        "targetCount": len(calibration_rows),
        "manualPointCount": len(rows),
        "observedCalibrationPassCount": pass_count,
        "guidedManualScoreableCount": len(case_ledger),
        "meanBaryonOnlyRmse": mean_baryon,
        "meanCanonicalRmse": mean_canonical,
        "canonicalGainPctVsBaryonOnly": gain,
        "mtsScoringPerformed": True,
        "v21Promoted": False,
        "promotionEligible": False,
        "evidenceTier": "guided manual reconstruction; sensitivity review only",
    }
    capsule = {
        "mode": "externalguideddigitizevalidate",
        "createdUtc": "deterministic",
        "verdict": verdict,
        "metrics": metrics,
        "outputs": {
            "calibration": "mts_guided_digitize_calibration.csv",
            "componentPoints": "mts_guided_digitize_component_points.csv",
            "curvePoints": "mts_guided_digitize_curve_points.csv",
            "scoreability": "mts_guided_digitize_scoreability.csv",
            "caseLedger": "mts_guided_digitize_case_ledger.csv",
            "candidateScores": "mts_guided_digitize_candidate_scores.csv",
            "report": "mts_guided_digitize_validation_report.md",
        },
    }
    write_csv(out_dir / "mts_guided_digitize_calibration.csv", calibration_rows)
    write_csv(out_dir / "mts_guided_digitize_component_points.csv", component_points)
    write_csv(out_dir / "mts_guided_digitize_curve_points.csv", point_rows)
    write_csv(out_dir / "mts_guided_digitize_scoreability.csv", scoreability_rows)
    write_csv(out_dir / "mts_guided_digitize_case_ledger.csv", case_ledger)
    write_csv(out_dir / "mts_guided_digitize_candidate_scores.csv", score_rows)
    (out_dir / "mts_guided_digitize_validation_report.md").write_text(
        guided_digitize_validation_report(capsule, calibration_rows, case_ledger, score_rows),
        encoding="utf-8",
    )
    (out_dir / "mts_guided_digitize_validation_capsule.json").write_text(
        json.dumps(json_clean(capsule), indent=2, sort_keys=True),
        encoding="utf-8",
    )
    return capsule


def cmd_externalguideddigitizevalidate(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_EXTERNAL_GUIDED_DIGITIZE_VALIDATE_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    digitized_file = Path(args.digitized_file) if args.digitized_file else DEFAULT_GUIDED_DIGITIZED_FILE
    source_cache = Path(args.source_cache) if args.source_cache else DEFAULT_EXTERNAL_BARYON_BUILD_CACHE
    capsule = write_external_guided_digitize_validate_artifacts(out_dir, digitized_file, source_cache)
    metrics = capsule["metrics"]
    print("MTS guided digitized component validation v17: sensitivity evidence only")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"targets={metrics['targetCount']}",
                f"calibration_pass={metrics['observedCalibrationPassCount']}",
                f"scoreable={metrics['guidedManualScoreableCount']}",
                f"baryon_mean={fmt(metrics['meanBaryonOnlyRmse'])}",
                f"canonical_mean={fmt(metrics['meanCanonicalRmse'])}",
                f"gain={fmt(metrics['canonicalGainPctVsBaryonOnly'])}%",
                f"v21_promoted={metrics['v21Promoted']}",
            ]
        )
    )
    print(f"Wrote guided digitization validation to {out_dir.resolve()}")


def tng_api_key_status() -> tuple[str, str]:
    key = os.environ.get("TNG_API_KEY", "").strip()
    if not key:
        return "", "missing"
    return key, "set"


def tng_cache_key(url: str, params: dict | None = None) -> str:
    parts = [url]
    if params:
        parts.append(urllib.parse.urlencode(sorted((key, str(value)) for key, value in params.items())))
    return hashlib.sha256("?".join(parts).encode("utf-8")).hexdigest()


def tng_json_cache_path(source_cache: Path, url: str, params: dict | None = None) -> Path:
    return source_cache / "api-json" / f"{tng_cache_key(url, params)}.json"


def tng_cutout_cache_path(source_cache: Path, sim_name: str, subhalo_id: int | str) -> Path:
    return source_cache / "cutouts" / safe_file_stem(sim_name) / f"subhalo-{subhalo_id}.hdf5"


def tng_api_get_json(
    url: str,
    source_cache: Path,
    api_key: str,
    *,
    params: dict | None = None,
    offline: bool = False,
    reason: str = "",
) -> tuple[dict | list | None, dict]:
    cache_path = tng_json_cache_path(source_cache, url, params)
    row = {
        "kind": "api-json",
        "reason": reason,
        "url": url,
        "params": urllib.parse.urlencode(sorted((key, str(value)) for key, value in (params or {}).items())),
        "cachePath": str(cache_path),
        "cacheStatus": "missing",
        "status": "",
        "sizeBytes": 0,
        "sha256": "",
    }
    if cache_path.exists():
        try:
            data = json.loads(cache_path.read_text(encoding="utf-8"))
            row.update(
                {
                    "cacheStatus": "cached",
                    "status": "ok",
                    "sizeBytes": cache_path.stat().st_size,
                    "sha256": file_sha256(cache_path),
                }
            )
            return data, row
        except (OSError, json.JSONDecodeError) as exc:
            row["status"] = f"cache-error:{exc}"
            if offline:
                return None, row
    if offline:
        row["status"] = "missing-offline"
        return None, row
    if not api_key:
        row["status"] = "missing-api-key"
        return None, row
    try:
        full_url = url
        if params:
            full_url = f"{url}?{urllib.parse.urlencode(params)}"
        request = urllib.request.Request(
            full_url,
            headers={"api-key": api_key, "User-Agent": "MTS-Galaxy-Lab/1.0"},
        )
        with urllib.request.urlopen(request, timeout=60) as response:
            payload = response.read()
        data = json.loads(payload.decode("utf-8"))
        cache_path.parent.mkdir(parents=True, exist_ok=True)
        cache_path.write_bytes(json.dumps(json_clean(data), indent=2, sort_keys=True).encode("utf-8"))
        row.update(
            {
                "cacheStatus": "downloaded",
                "status": "ok",
                "sizeBytes": cache_path.stat().st_size,
                "sha256": file_sha256(cache_path),
            }
        )
        return data, row
    except (OSError, urllib.error.URLError, TimeoutError, json.JSONDecodeError) as exc:
        row["status"] = f"download-error:{exc}"
        return None, row


def tng_api_download_file(
    url: str,
    path: Path,
    api_key: str,
    *,
    params: dict | None = None,
    offline: bool = False,
    max_bytes: int = TNG_MAX_CUTOUT_BYTES,
) -> dict:
    row = {
        "kind": "cutout-hdf5",
        "url": url,
        "params": urllib.parse.urlencode(sorted((key, str(value)) for key, value in (params or {}).items())),
        "cachePath": str(path),
        "cacheStatus": "missing",
        "status": "",
        "sizeBytes": path.stat().st_size if path.exists() else 0,
        "sha256": file_sha256(path) if path.exists() else "",
        "maxBytes": max_bytes,
    }
    if path.exists():
        row["cacheStatus"] = "cached"
        row["status"] = "ok"
        return row
    if offline:
        row["status"] = "missing-offline"
        return row
    if not api_key:
        row["status"] = "missing-api-key"
        return row
    try:
        full_url = url
        if params:
            full_url = f"{url}?{urllib.parse.urlencode(params)}"
        request = urllib.request.Request(
            full_url,
            headers={"api-key": api_key, "User-Agent": "MTS-Galaxy-Lab/1.0"},
        )
        with urllib.request.urlopen(request, timeout=180) as response:
            length = response.headers.get("Content-Length", "")
            if length and int(length) > max_bytes:
                row["status"] = "skipped-size-cap"
                row["sizeBytes"] = int(length)
                return row
            path.parent.mkdir(parents=True, exist_ok=True)
            total = 0
            tmp_path = path.with_suffix(path.suffix + ".part")
            with tmp_path.open("wb") as handle:
                while True:
                    chunk = response.read(1024 * 1024)
                    if not chunk:
                        break
                    total += len(chunk)
                    if total > max_bytes:
                        handle.close()
                        try:
                            tmp_path.unlink()
                        except OSError:
                            pass
                        row["status"] = "skipped-size-cap"
                        row["sizeBytes"] = total
                        return row
                    handle.write(chunk)
            tmp_path.replace(path)
        row.update(
            {
                "cacheStatus": "downloaded",
                "status": "ok",
                "sizeBytes": path.stat().st_size,
                "sha256": file_sha256(path),
            }
        )
        return row
    except (OSError, urllib.error.URLError, TimeoutError, ValueError) as exc:
        row["status"] = f"download-error:{exc}"
        return row


def tng_endpoint(base: str, *parts: str) -> str:
    url = base.rstrip("/") + "/"
    for part in parts:
        url = urllib.parse.urljoin(url, str(part).strip("/") + "/")
    return url


def tng_field(row: dict, *names: str, default=math.nan):
    for name in names:
        if name in row and row[name] not in {"", None}:
            return row[name]
    return default


def tng_float(row: dict, *names: str, default: float = math.nan) -> float:
    return parse_float(tng_field(row, *names, default=default), default)


def tng_int(row: dict, *names: str, default: int = 0) -> int:
    value = tng_field(row, *names, default=default)
    try:
        return int(float(value))
    except (TypeError, ValueError):
        return default


def tng_code_mass_to_msun(value: float, hubble: float) -> float:
    return value * 1.0e10 / hubble if math.isfinite(value) and math.isfinite(hubble) and hubble > 0 else math.nan


def tng_full_subhalo_url(item: dict) -> str:
    url = str(item.get("_apiUrl") or item.get("url", ""))
    return url if url.endswith("/") else url + "/"


def tng_subhalo_id(item: dict) -> int:
    return tng_int(item, "id", "subhalo_id", "subfind_id", default=-1)


def tng_search_param_sets() -> list[dict]:
    return [
        {
            "limit": TNG_CANDIDATE_SCAN_LIMIT,
            "mass_stars__gt": 0.02,
            "mass_stars__lt": 30.0,
            "mass_gas__gt": 0.002,
            "len_stars__gt": 300,
            "len_gas__gt": 30,
        },
        {"limit": TNG_CANDIDATE_SCAN_LIMIT, "mass_stars__gt": 0.02, "mass_stars__lt": 30.0},
        {"limit": TNG_CANDIDATE_SCAN_LIMIT},
    ]


def tng_results(data: dict | list | None) -> list[dict]:
    if isinstance(data, dict) and isinstance(data.get("results"), list):
        return data["results"]
    if isinstance(data, list):
        return [item for item in data if isinstance(item, dict)]
    return []


def tng_root_sim_names(data: dict | list | None) -> list[str]:
    rows = tng_results(data)
    names = []
    for row in rows:
        name = str(row.get("name", ""))
        if name:
            names.append(name)
    if not names and isinstance(data, dict):
        for key in ["simulations", "runs"]:
            if isinstance(data.get(key), list):
                names.extend(str(item.get("name", "")) for item in data[key] if isinstance(item, dict))
    return sorted({name for name in names if name})


def write_tng_api_scout_artifacts(out_dir: Path, source_cache: Path, offline: bool) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    source_cache.mkdir(parents=True, exist_ok=True)
    api_key, key_status = tng_api_key_status()
    rows = []
    root_data, root_row = tng_api_get_json(TNG_BASE_URL, source_cache, api_key, offline=offline, reason="api-root")
    rows.append({**root_row, "sim": "", "endpoint": "root", "resultCount": len(tng_root_sim_names(root_data))})
    sim_names = tng_root_sim_names(root_data)
    sims_to_check = [name for name in TNG_SIM_CANDIDATES if not sim_names or name in sim_names]
    if not sims_to_check:
        sims_to_check = TNG_SIM_CANDIDATES[:]
    selected_sim = ""
    z0_snapshot_url = ""
    sample_subhalo_url = ""
    for sim_name in sims_to_check:
        sim_url = tng_endpoint(TNG_BASE_URL, sim_name)
        sim_data, sim_row = tng_api_get_json(sim_url, source_cache, api_key, offline=offline, reason="simulation")
        rows.append({**sim_row, "sim": sim_name, "endpoint": "simulation", "resultCount": 1 if isinstance(sim_data, dict) else 0})
        snap_url = tng_endpoint(sim_url, "snapshots", "z=0")
        snap_data, snap_row = tng_api_get_json(snap_url, source_cache, api_key, offline=offline, reason="z0-snapshot")
        rows.append({**snap_row, "sim": sim_name, "endpoint": "snapshots/z=0", "resultCount": 1 if isinstance(snap_data, dict) else 0})
        subhalos_url = tng_endpoint(snap_url, "subhalos")
        sub_data = None
        sub_row = {}
        for params in tng_search_param_sets():
            sub_data, sub_row = tng_api_get_json(
                subhalos_url,
                source_cache,
                api_key,
                params=params,
                offline=offline,
                reason="subhalo-search",
            )
            if tng_results(sub_data):
                break
        sub_results = tng_results(sub_data)
        rows.append({**sub_row, "sim": sim_name, "endpoint": "subhalos", "resultCount": len(sub_results)})
        if sub_results and not selected_sim:
            selected_sim = sim_name
            z0_snapshot_url = snap_url
            sample_subhalo_url = tng_full_subhalo_url(sub_results[0])
        if sub_results:
            full_data, full_row = tng_api_get_json(
                tng_full_subhalo_url(sub_results[0]),
                source_cache,
                api_key,
                offline=offline,
                reason="sample-subhalo",
            )
            rows.append({**full_row, "sim": sim_name, "endpoint": "sample-subhalo", "resultCount": 1 if isinstance(full_data, dict) else 0})
    cutout_pattern = ""
    if sample_subhalo_url:
        cutout_pattern = sample_subhalo_url + "cutout.hdf5?gas=Coordinates,Masses&stars=Coordinates,Masses&dm=Coordinates"
    metrics = {
        "apiKeyStatus": key_status,
        "offline": offline,
        "sourceCache": str(source_cache.resolve()),
        "sourceCacheOnDDrive": str(source_cache).lower().startswith("d:"),
        "simCandidates": TNG_SIM_CANDIDATES,
        "selectedPilotSim": selected_sim,
        "z0SnapshotUrl": z0_snapshot_url,
        "sampleSubhaloUrl": sample_subhalo_url,
        "cutoutUrlPattern": cutout_pattern,
        "largeDownloadsAllowed": False,
        "apiKeySerialized": False,
    }
    verdict = "api scout ready" if selected_sim else ("api key missing" if key_status == "missing" and not offline else "api scout incomplete")
    capsule = {
        "mode": "tngapiscout",
        "createdUtc": "deterministic",
        "verdict": verdict,
        "metrics": metrics,
        "rules": {
            "simulationOnly": True,
            "observationalValidation": False,
            "canonicalMtsPromotionAllowed": False,
            "v21PromotionAllowed": False,
        },
    }
    write_csv(out_dir / "mts_tng_api_scout_inventory.csv", rows)
    report_lines = [
        "# MTS v22 TNG API Scout",
        "",
        f"Verdict: **{verdict}**",
        "",
        "This is a bounded IllustrisTNG API scout for a simulation mechanism sandbox. It does not score MTS, does not fetch large products, and does not serialize the API key.",
        "",
        f"- API key status: `{key_status}`",
        f"- Source cache: `{source_cache.resolve()}`",
        f"- Source cache on D: `{metrics['sourceCacheOnDDrive']}`",
        f"- Selected pilot sim: `{selected_sim or 'not selected'}`",
        f"- Cutout size cap: `{TNG_MAX_CUTOUT_BYTES}` bytes",
        "",
        "## Endpoint Inventory",
        "",
        "| Sim | Endpoint | Status | Count | Cache |",
        "| --- | --- | --- | ---: | --- |",
    ]
    for row in rows:
        report_lines.append(
            f"| {row.get('sim', '')} | {row.get('endpoint', '')} | {row.get('status', '')} | {row.get('resultCount', '')} | {Path(row.get('cachePath', '')).name if row.get('cachePath') else ''} |"
        )
    report_lines.extend(
        [
            "",
            "## Interpretation",
            "",
            "TNG evidence will be simulation-only mechanism evidence. It cannot replace SPARC or promote v21 by itself.",
        ]
    )
    (out_dir / "mts_tng_api_scout_report.md").write_text("\n".join(report_lines), encoding="utf-8")
    (out_dir / "mts_tng_api_scout_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_tngapiscout(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_TNG_API_SCOUT_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    source_cache = Path(args.source_cache) if args.source_cache else DEFAULT_TNG_SOURCE_CACHE
    capsule = write_tng_api_scout_artifacts(out_dir, source_cache, args.offline)
    metrics = capsule["metrics"]
    print("MTS TNG API scout v1: simulation mechanism sandbox only")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"api_key={metrics['apiKeyStatus']}",
                f"selected_sim={metrics['selectedPilotSim'] or 'none'}",
                f"cache_on_d={metrics['sourceCacheOnDDrive']}",
                "api_key_serialized=false",
            ]
        )
    )
    print(f"Wrote TNG API scout to {out_dir.resolve()}")


def tng_ensure_hdf5_deps(offline: bool) -> tuple[object | None, object | None, str]:
    try:
        import h5py  # type: ignore
        import numpy as np  # type: ignore

        return h5py, np, "system"
    except ImportError:
        pass
    if str(DEFAULT_TNG_PYTHON_LIB) not in sys.path:
        sys.path.insert(0, str(DEFAULT_TNG_PYTHON_LIB))
    try:
        import h5py  # type: ignore
        import numpy as np  # type: ignore

        return h5py, np, str(DEFAULT_TNG_PYTHON_LIB)
    except ImportError:
        if offline:
            return None, None, "missing-offline"
    DEFAULT_TNG_PYTHON_LIB.mkdir(parents=True, exist_ok=True)
    pip_cache = DEFAULT_TNG_PYTHON_LIB.parent / "pip-cache"
    pip_cache.mkdir(parents=True, exist_ok=True)
    env = os.environ.copy()
    env["PIP_CACHE_DIR"] = str(pip_cache)
    try:
        subprocess.run(
            [
                sys.executable,
                "-m",
                "pip",
                "install",
                "--disable-pip-version-check",
                "--target",
                str(DEFAULT_TNG_PYTHON_LIB),
                "numpy",
                "h5py",
            ],
            check=True,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            env=env,
        )
        importlib.invalidate_caches()
        import h5py  # type: ignore
        import numpy as np  # type: ignore

        return h5py, np, str(DEFAULT_TNG_PYTHON_LIB)
    except (ImportError, OSError, subprocess.CalledProcessError) as exc:
        return None, None, f"install-error:{exc}"


def tng_select_sim_and_subhalos(source_cache: Path, api_key: str, offline: bool) -> tuple[str, list[dict], list[dict]]:
    inventory = []
    for sim_name in TNG_SIM_CANDIDATES:
        snap_url = tng_endpoint(TNG_BASE_URL, sim_name, "snapshots", "z=0")
        subhalos_url = tng_endpoint(snap_url, "subhalos")
        for params in tng_search_param_sets():
            data, row = tng_api_get_json(
                subhalos_url,
                source_cache,
                api_key,
                params=params,
                offline=offline,
                reason="pilot-subhalo-search",
            )
            inventory.append({**row, "sim": sim_name, "endpoint": "subhalos", "resultCount": len(tng_results(data))})
            results = tng_results(data)
            if results:
                return sim_name, results, inventory
    return "", [], inventory


def tng_subhalo_inventory_row(sim_name: str, full: dict, status: str, reason: str) -> dict:
    sub_id = tng_subhalo_id(full)
    return {
        "sim": sim_name,
        "subhaloId": sub_id,
        "status": status,
        "reason": reason,
        "massLogMsun": tng_float(full, "mass_log_msun"),
        "massStarsCode": tng_float(full, "mass_stars"),
        "massGasCode": tng_float(full, "mass_gas"),
        "massDmCode": tng_float(full, "mass_dm"),
        "sfr": tng_float(full, "sfr"),
        "halfMassRadStarsCode": tng_float(full, "halfmassrad_stars", "halfmassrad_star"),
        "lenStars": tng_int(full, "len_stars"),
        "lenGas": tng_int(full, "len_gas"),
        "lenDm": tng_int(full, "len_dm"),
        "estimatedCutoutBytes": tng_estimated_cutout_bytes(full),
        "cutoutCachePath": "",
        "cutoutStatus": "",
        "parserStatus": "",
    }


def tng_estimated_cutout_bytes(full: dict) -> int:
    len_gas = max(0, tng_int(full, "len_gas"))
    len_stars = max(0, tng_int(full, "len_stars"))
    len_dm = max(0, tng_int(full, "len_dm"))
    return int((len_gas + len_stars + len_dm) * 32 + (len_gas + len_stars) * 8)


def tng_candidate_passes(full: dict) -> tuple[bool, str]:
    sub_id = tng_subhalo_id(full)
    if sub_id < 0:
        return False, "missing subhalo id"
    len_stars = tng_int(full, "len_stars")
    len_gas = tng_int(full, "len_gas")
    half = tng_float(full, "halfmassrad_stars", "halfmassrad_star")
    if len_stars < 300:
        return False, "too few star particles"
    if len_gas < 30:
        return False, "too few gas cells"
    if not math.isfinite(half) or half <= 0:
        return False, "missing stellar half-mass radius"
    if tng_estimated_cutout_bytes(full) > TNG_MAX_CUTOUT_BYTES:
        return False, "estimated cutout exceeds size cap"
    flag = tng_field(full, "flag", "subhaloflag", "SubhaloFlag", default=True)
    if str(flag).lower() in {"false", "0"}:
        return False, "subhalo flag false"
    return True, "selected disk-like proxy: stars+gas with bounded cutout"


def tng_hdf5_array(handle, group: str, field: str):
    if group not in handle or field not in handle[group]:
        return None
    return handle[group][field][()]


def tng_enclosed_velocity(np, radii: object, masses: object, bins: object) -> object:
    if radii is None or masses is None or len(radii) == 0:
        return np.zeros(len(bins), dtype=float)
    order = np.argsort(radii)
    sorted_r = radii[order]
    sorted_m = masses[order]
    cumulative = np.cumsum(sorted_m)
    idx = np.searchsorted(sorted_r, bins, side="right") - 1
    enclosed = np.where(idx >= 0, cumulative[np.clip(idx, 0, len(cumulative) - 1)], 0.0)
    return np.sqrt(np.maximum(0.0, TNG_G * enclosed / np.maximum(bins, 1e-9)))


def tng_parse_cutout_to_curve(path: Path, full: dict, sim_name: str, h5py, np) -> tuple[dict | None, list[dict], dict]:
    with h5py.File(path, "r") as handle:
        header = handle["Header"].attrs if "Header" in handle else {}
        hubble = float(header.get("HubbleParam", 0.6774))
        box_size = float(header.get("BoxSize", 0.0))
        mass_table = header.get("MassTable", [0, 0, 0, 0, 0, 0])
        center = np.array(
            [
                tng_float(full, "pos_x"),
                tng_float(full, "pos_y"),
                tng_float(full, "pos_z"),
            ],
            dtype=float,
        )
        if not np.all(np.isfinite(center)):
            raise RuntimeError("subhalo center missing")

        def component_radii(group: str):
            coords = tng_hdf5_array(handle, group, "Coordinates")
            if coords is None or len(coords) == 0:
                return np.array([], dtype=float)
            delta = coords.astype(float) - center
            if box_size > 0:
                delta -= box_size * np.round(delta / box_size)
            return np.sqrt(np.sum(delta * delta, axis=1)) / hubble

        gas_r = component_radii("PartType0")
        star_r = component_radii("PartType4")
        dm_r = component_radii("PartType1")
        gas_m = tng_hdf5_array(handle, "PartType0", "Masses")
        star_m = tng_hdf5_array(handle, "PartType4", "Masses")
        gas_m = gas_m.astype(float) * 1.0e10 / hubble if gas_m is not None else np.zeros(len(gas_r), dtype=float)
        star_m = star_m.astype(float) * 1.0e10 / hubble if star_m is not None else np.zeros(len(star_r), dtype=float)
        dm_mass_code = float(mass_table[1]) if len(mass_table) > 1 else 0.0
        if dm_mass_code <= 0 and len(dm_r) > 0:
            dm_code_total = tng_float(full, "mass_dm")
            dm_mass_code = dm_code_total / len(dm_r) if math.isfinite(dm_code_total) and len(dm_r) else 0.0
        dm_m = np.full(len(dm_r), dm_mass_code * 1.0e10 / hubble, dtype=float)

    half_code = tng_float(full, "halfmassrad_stars", "halfmassrad_star")
    half_kpc = half_code / hubble if math.isfinite(half_code) and half_code > 0 else math.nan
    h_proxy = clamp(half_kpc / 1.678 if math.isfinite(half_kpc) else math.nan, 0.25, 20.0)
    if not math.isfinite(h_proxy):
        raise RuntimeError("invalid h proxy")
    all_r = np.concatenate([gas_r, star_r, dm_r]) if len(gas_r) + len(star_r) + len(dm_r) else np.array([], dtype=float)
    if len(all_r) < 500:
        raise RuntimeError("too few particles in cutout")
    r_available = float(np.percentile(all_r, 92))
    r_out = clamp(min(30.0, r_available), max(1.5, 3.0 * h_proxy), max(3.0, 8.0 * h_proxy, r_available))
    r_out = min(r_out, r_available if r_available > 0 else r_out)
    if not math.isfinite(r_out) or r_out <= 1.0:
        raise RuntimeError("invalid outer radius")
    bins = np.linspace(max(0.25, 0.15 * h_proxy), r_out, 28)
    v_gas = tng_enclosed_velocity(np, gas_r, gas_m, bins)
    v_star = tng_enclosed_velocity(np, star_r, star_m, bins)
    v_dm = tng_enclosed_velocity(np, dm_r, dm_m, bins)
    v_total = np.sqrt(np.maximum(0.0, v_gas * v_gas + v_star * v_star + v_dm * v_dm))
    profile_rows = []
    curve_rows = []
    for index, radius in enumerate(bins):
        if v_total[index] <= 0:
            continue
        v_disk_for_mts = v_star[index] / math.sqrt(ML_DISK) if ML_DISK > 0 else v_star[index]
        err = max(5.0, 0.05 * float(v_total[index]))
        curve_rows.append(
            {
                "r": float(radius),
                "vObs": float(v_total[index]),
                "err": err,
                "vGas": float(v_gas[index]),
                "vDisk": float(v_disk_for_mts),
                "vBulge": 0.0,
                "sbDisk": max(1e-12, math.exp(-float(radius) / h_proxy)),
                "sbBulge": 0.0,
            }
        )
        profile_rows.append(
            {
                "sim": sim_name,
                "subhaloId": tng_subhalo_id(full),
                "radiusKpc": float(radius),
                "vTotal": float(v_total[index]),
                "vGas": float(v_gas[index]),
                "vStars": float(v_star[index]),
                "vDm": float(v_dm[index]),
                "vBar": float(math.sqrt(max(0.0, v_gas[index] * v_gas[index] + v_star[index] * v_star[index]))),
                "syntheticErr": err,
                "sourceCutout": str(path),
                "evidenceTier": "simulation-only",
            }
        )
    if len(curve_rows) < 8:
        raise RuntimeError("fewer than 8 scoreable radial bins")
    curve = build_curve_from_rows(
        f"{sim_name}_subhalo_{tng_subhalo_id(full)}",
        curve_rows,
        math.nan,
        ml_disk=ML_DISK,
        ml_bulge=ML_BULGE,
    )
    # Preserve the TNG stellar half-mass scale instead of fitting a fake surface-brightness scale.
    curve["h"] = h_proxy
    curve["rOut"] = curve_rows[-1]["r"]
    last = curve_rows[-1]
    vbar_out2 = last["vGas"] ** 2 + ML_DISK * last["vDisk"] ** 2
    curve["fGasOut"] = clamp(last["vGas"] ** 2 / vbar_out2 if vbar_out2 > 0 else 0.0, 0.0, 1.0)
    curve["leff"] = leff_exact(curve["h"], curve["rOut"], curve["fGasOut"])
    curve["leffOverH"] = curve["leff"] / curve["h"] if curve["h"] else math.nan
    curve["memoryLoad"] = (1.0 - curve["fGasOut"]) * (curve["rOut"] / curve["h"])
    rebuilt = build_curve_from_rows(curve["name"], curve_rows, math.nan, ml_disk=ML_DISK, ml_bulge=ML_BULGE)
    rebuilt.update({"h": curve["h"], "rOut": curve["rOut"], "fGasOut": curve["fGasOut"], "leff": curve["leff"], "leffOverH": curve["leffOverH"], "memoryLoad": curve["memoryLoad"]})
    # Rebuild state once with the fixed TNG h/leff proxy.
    points = []
    for row in curve_rows:
        bar2 = row["vGas"] ** 2 + ML_DISK * row["vDisk"] ** 2
        u = (row["vObs"] ** 2 - ML_DISK * row["vDisk"] ** 2) / (GAMMA0 * row["r"] * R_MAX)
        points.append({**row, "bar2": bar2, "x": row["r"] / curve["rOut"], "u": u})
    state = route_state(points, curve["rOut"])
    locked_points = []
    for point in points:
        support2 = GAMMA0 * curve["leff"] * (1 - math.exp(-((point["r"] / curve["leff"]) ** Q_DEFAULT)))
        model2 = point["bar2"] + support2
        u = (model2 - ML_DISK * point["vDisk"] ** 2) / (GAMMA0 * point["r"] * R_MAX)
        locked_points.append({**point, "u": u})
    locked_state = route_state(locked_points, curve["rOut"])
    curve.update(
        {
            "points": points,
            "lockedModelRoute": locked_state["route"],
            "lockedModelU0": locked_state["u0"],
            "lockedModelUOut": locked_state["uOut"],
            "lockedModelUMax": locked_state["uMax"],
            "lockedModelU075": locked_state["u075"],
            "lockedModelXCross": locked_state["xCross"],
            "lockedModelDownCrossings": locked_state["downCrossings"],
            "lockedModelUpCrossings": locked_state["upCrossings"],
            **route_safety(locked_state),
            **state,
            "sim": sim_name,
            "subhaloId": tng_subhalo_id(full),
            "stellarHalfMassRadiusKpc": half_kpc,
            "hProxySource": "stellar_half_mass_radius/1.678",
            "sourceCutout": str(path),
        }
    )
    return curve, profile_rows, {
        "hubble": hubble,
        "hProxy": h_proxy,
        "rOut": curve["rOut"],
        "rAvailableP92": r_available,
        "gasCellCount": len(gas_r),
        "starParticleCount": len(star_r),
        "dmParticleCount": len(dm_r),
    }


def tng_clone_curve_with_rows(curve: dict, rows: list[dict], name_suffix: str) -> dict:
    clone = build_curve_from_rows(curve["name"] + name_suffix, rows, math.nan, ml_disk=ML_DISK, ml_bulge=ML_BULGE)
    clone["name"] = curve["name"] + name_suffix
    return clone


def tng_resampled_component_rows(target: dict, source: dict) -> list[dict]:
    source_points = source["points"]
    rows = []
    for point in target["points"]:
        x = point["x"]
        source_r = x * source["rOut"]
        gas = value_at(source_points, source_r, "vGas")
        disk = value_at(source_points, source_r, "vDisk")
        rows.append(
            {
                "r": point["r"],
                "vObs": point["vObs"],
                "err": point["err"],
                "vGas": max(0.0, gas),
                "vDisk": max(0.0, disk),
                "vBulge": 0.0,
                "sbDisk": max(1e-12, math.exp(-point["r"] / max(target["h"], 0.25))),
                "sbBulge": 0.0,
            }
        )
    return rows


def tng_radius_scrambled_rows(curve: dict, seed: int) -> list[dict]:
    rng = random.Random(seed)
    gas_values = [point["vGas"] for point in curve["points"]]
    disk_values = [point["vDisk"] for point in curve["points"]]
    rng.shuffle(gas_values)
    rng.shuffle(disk_values)
    rows = []
    for index, point in enumerate(curve["points"]):
        rows.append(
            {
                "r": point["r"],
                "vObs": point["vObs"],
                "err": point["err"],
                "vGas": gas_values[index],
                "vDisk": disk_values[index],
                "vBulge": 0.0,
                "sbDisk": point["sbDisk"],
                "sbBulge": 0.0,
            }
        )
    return rows


def tng_v21_formula_path() -> Path:
    frozen = DEFAULT_V21_FROZEN_FRONTIER_OUT / "mts_v21_frozen_frontier_formula.json"
    quality = DEFAULT_V21_QUALITY_GATE_OUT / "mts_v21_quality_gate_capsule.json"
    if frozen.exists():
        return frozen
    return quality


def tng_load_v21_candidate() -> tuple[dict | None, dict | None, str]:
    path = tng_v21_formula_path()
    if not path.exists():
        return None, None, "missing formula artifact"
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        if "bestFormula" in data:
            data = data["bestFormula"]
    except (OSError, json.JSONDecodeError) as exc:
        return None, None, f"unreadable formula artifact: {exc}"
    candidate_id = data.get("candidateId", "")
    beta = parse_float(data.get("beta"), math.nan)
    gate_style = data.get("gateStyle", "hinge")
    base_match = re.search(r"(boundaryScore|memoryLoad|uOut|u075|uMax)(ge|le)([0-9p]+)-and-(boundaryScore|memoryLoad|uOut|u075|uMax)(ge|le)([0-9p]+)", candidate_id)
    safety_match = re.search(r"(midGasShare|innerGasShare|midBarToOuterBar)(ge|le)([0-9p]+)", candidate_id)
    if not base_match or not math.isfinite(beta):
        return None, None, "formula artifact present but not parseable for simulation replay"

    def num(text: str) -> float:
        return parse_float(text.replace("p", "."))

    curves = build_curves()
    rows, _facts = v21_full_profile_build_rows(curves)
    split = v21_split_rows(rows, SPLIT_SEED, HOLDOUT_FRACTION)
    rule = (
        (base_match.group(1), base_match.group(2), num(base_match.group(3))),
        (base_match.group(4), base_match.group(5), num(base_match.group(6))),
    )
    widths = {
        feature: max(1e-9, v21_law_feature_span(rows, split["trainNames"], feature) * 0.25)
        for feature, _direction, _threshold in rule
    }
    candidate = {
        "candidateId": candidate_id,
        "rule": rule,
        "beta": beta,
        "gateStyle": gate_style,
        "widthScale": 0.25 if gate_style != "hard" else math.nan,
        "widths": widths if gate_style != "hard" else {},
        "formulaFamily": data.get("formulaFamily", f"{rule[0][0]}+{rule[1][0]}"),
        "sourceFormulaPath": str(path),
    }
    if safety_match:
        safety_feature = safety_match.group(1)
        safety = {
            "strategy": "profile-continuous-safety-cap",
            "conditions": ((safety_feature, safety_match.group(2), num(safety_match.group(3))),),
            "widths": {safety_feature: max(1e-9, v21_profile_feature_span(rows, split["trainNames"], safety_feature) * 0.25)},
            "safetyRuleText": data.get("safetyRuleText", ""),
        }
    else:
        safety = {"strategy": "none", "conditions": (), "widths": {}, "safetyRuleText": "no safety gate"}
    return candidate, safety, "loaded"


def tng_curve_feature_row(curve: dict) -> dict:
    base = score_curve_with_params(curve, 1.0, Q_DEFAULT)
    terms = v19_curve_memory_terms(curve)
    row = {
        "name": curve["name"],
        "curve": curve,
        "baseline": base,
        "lockedRoute": base["candidateRoute"],
        "boundaryScore": terms["boundaryScore"],
        "memoryLoad": curve["memoryLoad"],
        "u075": curve["u075"],
        "uOut": curve["uOut"],
        "uMax": curve["uMax"],
        "lockedUOut": curve["lockedModelUOut"],
        "lockedUMax": curve["lockedModelUMax"],
        "routeMargin": curve["routeMargin"],
        "routeBreakRisk": curve["routeBreakRisk"],
        "hOverRout": curve["h"] / curve["rOut"] if curve["rOut"] else math.nan,
        "fGasOut": curve["fGasOut"],
        "lExact": terms["lExact"],
        "lSat": terms["lSat"],
        "lGap": terms["lGap"],
        "leffOverH": curve["leffOverH"],
    }
    row.update(v21_full_profile_features(curve))
    return row


def tng_score_v21(curve: dict, candidate: dict | None, safety: dict | None) -> tuple[dict, float]:
    if not candidate:
        return score_curve_with_params(curve, 1.0, Q_DEFAULT), 0.0
    row = tng_curve_feature_row(curve)
    activation = v21_law_activation(row, candidate)
    if safety:
        activation *= v21_safety_value(row, safety)
    score = v21_law_score_for_row(row, candidate["beta"], activation, {})
    return score, activation


def tng_candidate_score_rows(curves: list[dict], v21_candidate: dict | None, v21_safety: dict | None) -> tuple[list[dict], list[dict], list[dict]]:
    case_rows = []
    for curve in curves:
        baryon = score_curve_baryon_only(curve)
        canonical = score_curve_with_params(curve, 1.0, Q_DEFAULT)
        v21_score, activation = tng_score_v21(curve, v21_candidate, v21_safety)
        terms = v19_curve_memory_terms(curve)
        case_rows.append(
            {
                "name": curve["name"],
                "sim": curve.get("sim", ""),
                "subhaloId": curve.get("subhaloId", ""),
                "evidenceTier": "simulation-only",
                "baryonOnlyRmse": baryon["rmse"],
                "canonicalRmse": canonical["rmse"],
                "canonicalGainPctVsBaryonOnly": pct_improvement(baryon["rmse"], canonical["rmse"]),
                "v21Rmse": v21_score["rmse"] if v21_candidate else math.nan,
                "v21GainPctVsCanonical": pct_improvement(canonical["rmse"], v21_score["rmse"]) if v21_candidate else math.nan,
                "v21Activation": activation if v21_candidate else math.nan,
                "route": curve["route"],
                "lockedRoute": canonical["candidateRoute"],
                "v21CandidateRoute": v21_score["candidateRoute"] if v21_candidate else "",
                "rOut": curve["rOut"],
                "hProxy": curve["h"],
                "fGasOut": curve["fGasOut"],
                "S_mem": terms["sMem"],
                "memoryLoad": terms["memoryLoad"],
                "L_exact": terms["lExact"],
                "L_sat": terms["lSat"],
                "L_gap": terms["lGap"],
                "u075": curve["u075"],
                "uOut": curve["uOut"],
                "uMax": curve["uMax"],
                "boundaryScore": terms["boundaryScore"],
                "sourceCutout": curve.get("sourceCutout", ""),
            }
        )

    def score_summary(candidate_id: str, rmse_key: str, comparator_key: str = "baryonOnlyRmse") -> dict:
        comparator = safe_mean(parse_float(row.get(comparator_key)) for row in case_rows)
        mean_rmse = safe_mean(parse_float(row.get(rmse_key)) for row in case_rows)
        return {
            "candidateId": candidate_id,
            "evidenceTier": "simulation-only",
            "galaxyCount": len(case_rows),
            "meanComparatorRmse": comparator,
            "meanRmse": mean_rmse,
            "meanGainPctVsComparator": pct_improvement(comparator, mean_rmse),
            "promotionEligible": False,
        }

    score_rows = [
        score_summary("baryon-only", "baryonOnlyRmse", "baryonOnlyRmse"),
        score_summary("canonical-locked-mts", "canonicalRmse", "baryonOnlyRmse"),
    ]
    if v21_candidate:
        score_rows.append(score_summary("frozen-v21-memory-stretch", "v21Rmse", "canonicalRmse"))

    null_rows = []
    if curves:
        sorted_curves = sorted(curves, key=lambda item: item.get("subhaloId", 0))
        shuffled_scores = []
        scrambled_scores = []
        leff_shuffle_scores = []
        for index, curve in enumerate(sorted_curves):
            source = sorted_curves[(index + 1) % len(sorted_curves)]
            galaxy_rows = tng_resampled_component_rows(curve, source)
            galaxy_curve = tng_clone_curve_with_rows(curve, galaxy_rows, "-galaxy-shuffled-null")
            shuffled_scores.append(score_curve_with_params(galaxy_curve, 1.0, Q_DEFAULT)["rmse"])
            scrambled_rows = tng_radius_scrambled_rows(curve, SPLIT_SEED + index)
            scrambled_curve = tng_clone_curve_with_rows(curve, scrambled_rows, "-radius-scrambled-null")
            scrambled_scores.append(score_curve_with_params(scrambled_curve, 1.0, Q_DEFAULT)["rmse"])
            source_leff = max(1e-9, source["leff"])
            leff_shuffle_scores.append(score_curve_with_leff_value(curve, source_leff)["rmse"])
        baryon_mean = safe_mean(parse_float(row.get("baryonOnlyRmse")) for row in case_rows)
        for null_id, values in [
            ("galaxy-shuffled-baryon-profile-null", shuffled_scores),
            ("radius-scrambled-baryon-profile-null", scrambled_scores),
            ("state-shuffled-leff-null", leff_shuffle_scores),
        ]:
            mean_rmse = safe_mean(values)
            null_rows.append(
                {
                    "nullId": null_id,
                    "evidenceTier": "simulation-only",
                    "galaxyCount": len(values),
                    "meanRmse": mean_rmse,
                    "meanGainPctVsBaryonOnly": pct_improvement(baryon_mean, mean_rmse),
                    "promotionEligible": False,
                }
            )
    return score_rows, case_rows, null_rows


def write_tng_mechanism_pilot_artifacts(out_dir: Path, source_cache: Path, offline: bool) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    source_cache.mkdir(parents=True, exist_ok=True)
    api_key, key_status = tng_api_key_status()
    fetch_rows = []
    inventory_rows = []
    profile_rows = []
    state_rows = []
    curves = []
    h5py = None
    np = None
    deps_status = "not-required-yet"
    sim_name, candidates, search_rows = tng_select_sim_and_subhalos(source_cache, api_key, offline)
    fetch_rows.extend(search_rows)
    full_items = []
    for item in candidates[: TNG_CANDIDATE_SCAN_LIMIT]:
        full_url = tng_full_subhalo_url(item)
        full_data, full_row = tng_api_get_json(full_url, source_cache, api_key, offline=offline, reason="pilot-subhalo-detail")
        fetch_rows.append({**full_row, "sim": sim_name, "endpoint": "subhalo-detail", "resultCount": 1 if isinstance(full_data, dict) else 0})
        if isinstance(full_data, dict):
            full_data["_apiUrl"] = full_url
            full_items.append(full_data)
        if len(full_items) >= TNG_CANDIDATE_SCAN_LIMIT:
            break

    accepted = 0
    for full in full_items:
        selected, reason = tng_candidate_passes(full)
        inventory = tng_subhalo_inventory_row(sim_name, full, "selected" if selected else "skipped", reason)
        if not selected or accepted >= TNG_TARGET_ACCEPTED:
            if accepted >= TNG_TARGET_ACCEPTED and selected:
                inventory["status"] = "skipped"
                inventory["reason"] = "pilot accepted target count reached"
            inventory_rows.append(inventory)
            continue
        sub_id = tng_subhalo_id(full)
        cutout_url = tng_full_subhalo_url(full) + "cutout.hdf5"
        cutout_path = tng_cutout_cache_path(source_cache, sim_name, sub_id)
        params = {
            "gas": "Coordinates,Masses",
            "stars": "Coordinates,Masses",
            "dm": "Coordinates",
        }
        cutout_row = tng_api_download_file(
            cutout_url,
            cutout_path,
            api_key,
            params=params,
            offline=offline,
            max_bytes=TNG_MAX_CUTOUT_BYTES,
        )
        fetch_rows.append({**cutout_row, "sim": sim_name, "endpoint": "cutout", "subhaloId": sub_id})
        inventory["cutoutCachePath"] = str(cutout_path)
        inventory["cutoutStatus"] = cutout_row["status"]
        if cutout_row["status"] != "ok":
            inventory["status"] = "skipped"
            inventory["reason"] = f"cutout {cutout_row['status']}"
            inventory_rows.append(inventory)
            continue
        if h5py is None or np is None:
            h5py, np, deps_status = tng_ensure_hdf5_deps(offline)
        if h5py is None or np is None:
            inventory["status"] = "skipped"
            inventory["reason"] = f"hdf5 deps {deps_status}"
            inventory["parserStatus"] = deps_status
            inventory_rows.append(inventory)
            continue
        try:
            curve, per_point, meta = tng_parse_cutout_to_curve(cutout_path, full, sim_name, h5py, np)
            if curve is None:
                raise RuntimeError("curve parser returned none")
            curves.append(curve)
            profile_rows.extend(per_point)
            terms = v19_curve_memory_terms(curve)
            state_rows.append(
                {
                    "name": curve["name"],
                    "sim": sim_name,
                    "subhaloId": sub_id,
                    "rOut": curve["rOut"],
                    "hProxy": curve["h"],
                    "hProxySource": curve["hProxySource"],
                    "fGasOut": curve["fGasOut"],
                    "S_mem": terms["sMem"],
                    "memoryLoad": terms["memoryLoad"],
                    "L_exact": terms["lExact"],
                    "L_sat": terms["lSat"],
                    "L_gap": terms["lGap"],
                    "u075": curve["u075"],
                    "uOut": curve["uOut"],
                    "uMax": curve["uMax"],
                    "lockedRoute": curve["lockedModelRoute"],
                    "boundaryScore": terms["boundaryScore"],
                    "profileGasMidShare": v21_full_profile_features(curve).get("midGasShare", math.nan),
                    "sourceCutout": str(cutout_path),
                    **meta,
                }
            )
            inventory["parserStatus"] = "ok"
            inventory["status"] = "accepted"
            accepted += 1
        except Exception as exc:  # noqa: BLE001 - source-product parser needs to preserve exact blocker
            inventory["parserStatus"] = f"parse-error:{exc}"
            inventory["status"] = "skipped"
            inventory["reason"] = "cutout parse failed"
        inventory_rows.append(inventory)

    v21_candidate, v21_safety, v21_status = tng_load_v21_candidate()
    score_rows, case_rows, null_rows = tng_candidate_score_rows(curves, v21_candidate, v21_safety)
    baseline = baseline_summary(build_curves())
    metrics = {
        "apiKeyStatus": key_status,
        "offline": offline,
        "sourceCache": str(source_cache.resolve()),
        "sourceCacheOnDDrive": str(source_cache).lower().startswith("d:"),
        "selectedSim": sim_name,
        "candidateSubhalosSeen": len(full_items),
        "acceptedScoreableGalaxies": len(curves),
        "targetAcceptedGalaxies": TNG_TARGET_ACCEPTED,
        "hdf5DependencyStatus": deps_status,
        "v21FormulaStatus": v21_status,
        "allGalaxyLockedMtsMean": baseline["baselineMean"],
        "simulationOnly": True,
        "observationalValidation": False,
        "canonicalMtsPromoted": False,
        "v21Promoted": False,
        "apiKeySerialized": False,
    }
    verdict = "simulation mechanism pilot ready" if len(curves) >= 10 else ("api key missing" if key_status == "missing" and not offline else "insufficient simulation scoreable data")
    capsule = {
        "mode": "tngmechanismpilot",
        "createdUtc": "deterministic",
        "verdict": verdict,
        "metrics": metrics,
        "rules": {
            "evidenceTier": "simulation-only mechanism sandbox",
            "noObservationalValidationClaim": True,
            "noCanonicalPromotion": True,
            "noV21Promotion": True,
            "cutoutSizeCapBytes": TNG_MAX_CUTOUT_BYTES,
            "apiKeyStoredInArtifacts": False,
        },
    }
    write_csv(out_dir / "mts_tng_pilot_inventory.csv", inventory_rows)
    write_csv(out_dir / "mts_tng_pilot_fetch_inventory.csv", fetch_rows)
    write_csv(out_dir / "mts_tng_pilot_profiles.csv", profile_rows)
    write_csv(out_dir / "mts_tng_pilot_state_ledger.csv", state_rows)
    write_csv(out_dir / "mts_tng_pilot_candidate_scores.csv", score_rows)
    write_csv(out_dir / "mts_tng_pilot_null_controls.csv", null_rows)
    write_csv(out_dir / "mts_tng_pilot_case_ledger.csv", case_rows)
    lines = [
        "# MTS v22 TNG Mechanism Pilot",
        "",
        f"Verdict: **{verdict}**",
        "",
        "This is simulation-only mechanism evidence. It is not observational validation and cannot promote canonical MTS or v21 by itself.",
        "",
        "## Facts",
        "",
        f"- Selected simulation: `{sim_name or 'none'}`",
        f"- Accepted scoreable simulated galaxies: `{len(curves)}`",
        f"- HDF5 dependency status: `{deps_status}`",
        f"- Source cache on D: `{metrics['sourceCacheOnDDrive']}`",
        f"- API key serialized: `False`",
        f"- SPARC locked baseline mean: `{fmt(metrics['allGalaxyLockedMtsMean'])}`",
        "",
        "## Candidate Scores",
        "",
        "| Candidate | Count | Mean RMSE | Gain vs comparator |",
        "| --- | ---: | ---: | ---: |",
    ]
    for row in score_rows:
        lines.append(
            f"| {row['candidateId']} | {row['galaxyCount']} | {fmt(row['meanRmse'])} | {fmt(row['meanGainPctVsComparator'])}% |"
        )
    lines.extend(
        [
            "",
            "## Null Controls",
            "",
            "| Null | Count | Mean RMSE | Gain vs baryon-only |",
            "| --- | ---: | ---: | ---: |",
        ]
    )
    for row in null_rows:
        lines.append(f"| {row['nullId']} | {row['galaxyCount']} | {fmt(row['meanRmse'])} | {fmt(row['meanGainPctVsBaryonOnly'])}% |")
    lines.extend(
        [
            "",
            "## Interpretation",
            "",
            "TNG provides known baryon/dark-matter circular-speed decomposition, so it can test whether MTS state variables track a simulated residual-support structure. It does not replace SPARC, and any v21 behavior here stays mechanism anatomy until observational data support it.",
        ]
    )
    (out_dir / "mts_tng_pilot_report.md").write_text("\n".join(lines), encoding="utf-8")
    (out_dir / "mts_tng_pilot_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_tngmechanismpilot(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_TNG_MECHANISM_PILOT_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    source_cache = Path(args.source_cache) if args.source_cache else DEFAULT_TNG_SOURCE_CACHE
    capsule = write_tng_mechanism_pilot_artifacts(out_dir, source_cache, args.offline)
    metrics = capsule["metrics"]
    print("MTS TNG mechanism pilot v1: simulation-only")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"api_key={metrics['apiKeyStatus']}",
                f"sim={metrics['selectedSim'] or 'none'}",
                f"accepted={metrics['acceptedScoreableGalaxies']}",
                f"deps={metrics['hdf5DependencyStatus']}",
                f"v21_promoted={metrics['v21Promoted']}",
            ]
        )
    )
    print(f"Wrote TNG mechanism pilot to {out_dir.resolve()}")


def tng_state_audit_curve_from_profile(name: str, profile_rows: list[dict], state: dict, h_scale: float = 1.0, r_limit: float | None = None) -> dict | None:
    h_proxy = parse_float(state.get("hProxy"), math.nan) * h_scale
    if not math.isfinite(h_proxy) or h_proxy <= 0:
        return None
    curve_rows = []
    for row in sorted(profile_rows, key=lambda item: parse_float(item.get("radiusKpc"))):
        radius = parse_float(row.get("radiusKpc"))
        if not math.isfinite(radius) or radius <= 0:
            continue
        if r_limit is not None and radius > r_limit:
            continue
        v_total = parse_float(row.get("vTotal"))
        v_gas = parse_float(row.get("vGas"))
        v_stars = parse_float(row.get("vStars"))
        err = parse_float(row.get("syntheticErr"), max(5.0, 0.05 * v_total if math.isfinite(v_total) else 5.0))
        if not all(math.isfinite(value) for value in [v_total, v_gas, v_stars, err]):
            continue
        curve_rows.append(
            {
                "r": radius,
                "vObs": v_total,
                "err": max(1e-6, err),
                "vGas": max(0.0, v_gas),
                "vDisk": max(0.0, v_stars / math.sqrt(ML_DISK)),
                "vBulge": 0.0,
                "sbDisk": max(1e-12, math.exp(-radius / max(h_proxy, 0.25))),
                "sbBulge": 0.0,
                "vDm": parse_float(row.get("vDm")),
                "vStars": max(0.0, v_stars),
                "sourceCutout": row.get("sourceCutout", ""),
            }
        )
    if len(curve_rows) < 5:
        return None
    r_out = curve_rows[-1]["r"]
    last = curve_rows[-1]
    vbar_out2 = last["vGas"] ** 2 + ML_DISK * last["vDisk"] ** 2
    f_gas_out = clamp(last["vGas"] ** 2 / vbar_out2 if vbar_out2 > 0 else 0.0, 0.0, 1.0)
    leff = leff_exact(h_proxy, r_out, f_gas_out)
    points = []
    for row in curve_rows:
        bar2 = row["vGas"] ** 2 + ML_DISK * row["vDisk"] ** 2
        u = (row["vObs"] ** 2 - ML_DISK * row["vDisk"] ** 2) / (GAMMA0 * row["r"] * R_MAX)
        points.append({**row, "bar2": bar2, "x": row["r"] / r_out, "u": u})
    state_obs = route_state(points, r_out)
    locked_points = []
    for point in points:
        support2 = GAMMA0 * leff * (1.0 - math.exp(-((point["r"] / leff) ** Q_DEFAULT)))
        model2 = point["bar2"] + support2
        u = (model2 - ML_DISK * point["vDisk"] ** 2) / (GAMMA0 * point["r"] * R_MAX)
        locked_points.append({**point, "u": u})
    locked_state = route_state(locked_points, r_out)
    safety = route_safety(locked_state)
    return {
        "name": name,
        "points": points,
        "distanceMpc": math.nan,
        "mlDisk": ML_DISK,
        "mlBulge": ML_BULGE,
        "h": h_proxy,
        "rOut": r_out,
        "fGasOut": f_gas_out,
        "leff": leff,
        "leffOverH": leff / h_proxy if h_proxy else math.nan,
        "memoryLoad": (1.0 - f_gas_out) * (r_out / h_proxy),
        "lockedModelRoute": locked_state["route"],
        "lockedModelU0": locked_state["u0"],
        "lockedModelUOut": locked_state["uOut"],
        "lockedModelUMax": locked_state["uMax"],
        "lockedModelU075": locked_state["u075"],
        "lockedModelXCross": locked_state["xCross"],
        "lockedModelDownCrossings": locked_state["downCrossings"],
        "lockedModelUpCrossings": locked_state["upCrossings"],
        **safety,
        **state_obs,
        "sim": state.get("sim", ""),
        "subhaloId": state.get("subhaloId", ""),
        "sourceCutout": state.get("sourceCutout", ""),
        "hProxySource": "reconstructed from TNG pilot profile CSV",
    }


def tng_state_audit_load_curves(pilot_dir: Path) -> tuple[list[dict], list[dict], list[dict]]:
    profile_rows = read_csv_rows(pilot_dir / "mts_tng_pilot_profiles.csv")
    state_rows = read_csv_rows(pilot_dir / "mts_tng_pilot_state_ledger.csv")
    state_by_name = {row.get("name", ""): row for row in state_rows}
    grouped: dict[str, list[dict]] = {}
    for row in profile_rows:
        sim = row.get("sim", "")
        subhalo = row.get("subhaloId", "")
        name = f"{sim}_subhalo_{subhalo}"
        grouped.setdefault(name, []).append(row)
    curves = []
    missing = []
    for name, rows in sorted(grouped.items()):
        state = state_by_name.get(name, {"name": name, "sim": rows[0].get("sim", ""), "subhaloId": rows[0].get("subhaloId", "")})
        curve = tng_state_audit_curve_from_profile(name, rows, state)
        if curve:
            curves.append(curve)
        else:
            missing.append({"name": name, "reason": "could not reconstruct scoreable curve from pilot profile rows"})
    return curves, state_rows, missing


def tng_support_shape_metrics(curve: dict, leff_value: float, variant_id: str) -> dict:
    rows = []
    for point in curve["points"]:
        support2 = GAMMA0 * leff_value * (1.0 - math.exp(-((point["r"] / max(leff_value, 1e-9)) ** Q_DEFAULT)))
        v_support = math.sqrt(max(0.0, support2))
        v_dm = parse_float(point.get("vDm"))
        if not math.isfinite(v_dm):
            continue
        band = "inner" if point["x"] < 0.33 else ("mid" if point["x"] < 0.66 else "outer")
        rows.append(
            {
                "band": band,
                "support2": support2,
                "dm2": v_dm * v_dm,
                "supportV": v_support,
                "dmV": v_dm,
                "velocityDiff": v_support - v_dm,
            }
        )
    if not rows:
        return {
            "variantId": variant_id,
            "supportVelocityRmse": math.nan,
            "supportSquaredRmse": math.nan,
            "supportShapeRmse": math.nan,
            "innerSupportBias": math.nan,
            "midSupportBias": math.nan,
            "outerSupportBias": math.nan,
        }
    max_support2 = max(row["support2"] for row in rows) or 1.0
    max_dm2 = max(row["dm2"] for row in rows) or 1.0
    return {
        "variantId": variant_id,
        "supportVelocityRmse": math.sqrt(safe_mean((row["supportV"] - row["dmV"]) ** 2 for row in rows)),
        "supportSquaredRmse": math.sqrt(safe_mean((row["support2"] - row["dm2"]) ** 2 for row in rows)),
        "supportShapeRmse": math.sqrt(safe_mean(((row["support2"] / max_support2) - (row["dm2"] / max_dm2)) ** 2 for row in rows)),
        "innerSupportBias": safe_mean(row["velocityDiff"] for row in rows if row["band"] == "inner"),
        "midSupportBias": safe_mean(row["velocityDiff"] for row in rows if row["band"] == "mid"),
        "outerSupportBias": safe_mean(row["velocityDiff"] for row in rows if row["band"] == "outer"),
    }


def tng_best_leff_oracle(curve: dict) -> tuple[float, dict]:
    candidates = sorted(
        set(
            [curve["leff"]]
            + [0.5 + 0.5 * index for index in range(1, 81)]
            + [curve["h"] * ratio for ratio in [1.8, 2.5, 3.5, 5.0, 7.5, 10.0, 14.0]]
        )
    )
    best_leff = curve["leff"]
    best_score = score_curve_with_leff_value(curve, curve["leff"])
    for leff in candidates:
        score = score_curve_with_leff_value(curve, leff)
        if score["rmse"] < best_score["rmse"]:
            best_leff = leff
            best_score = score
    return best_leff, best_score


def tng_nearest_source(curve: dict, curves: list[dict], features: list[str]) -> dict:
    others = [item for item in curves if item["name"] != curve["name"]]
    if not others:
        return curve
    stats = {}
    for feature in features:
        values = [parse_float(item.get(feature)) for item in curves if math.isfinite(parse_float(item.get(feature)))]
        if values:
            stats[feature] = (safe_mean(values), max(1e-9, max(values) - min(values)))
    def distance(other: dict) -> float:
        total = 0.0
        used = 0
        for feature, (mean, span) in stats.items():
            a = parse_float(curve.get(feature))
            b = parse_float(other.get(feature))
            if math.isfinite(a) and math.isfinite(b):
                total += ((a - b) / span) ** 2
                used += 1
        return math.sqrt(total) if used else math.inf
    return min(others, key=lambda item: (distance(item), item["name"]))


def tng_state_audit_leff_maps(curves: list[dict]) -> tuple[dict[str, dict[str, float]], list[dict]]:
    sorted_curves = sorted(curves, key=lambda item: (str(item.get("sim", "")), int(parse_float(item.get("subhaloId"), 0))))
    median_leff = safe_median(curve["leff"] for curve in sorted_curves)
    median_leff_over_h = safe_median(curve["leff"] / curve["h"] for curve in sorted_curves if curve["h"] > 0)
    maps: dict[str, dict[str, float]] = {
        "canonical-locked-mts": {curve["name"]: curve["leff"] for curve in sorted_curves},
        "fixed-median-leff": {curve["name"]: median_leff for curve in sorted_curves},
        "h-only-median-leff-over-h": {curve["name"]: curve["h"] * median_leff_over_h for curve in sorted_curves},
    }
    ledger = []
    shifted = {}
    gas_matched = {}
    size_matched = {}
    oracle = {}
    for index, curve in enumerate(sorted_curves):
        shuffled_source = sorted_curves[(index + 1) % len(sorted_curves)]
        gas_source = tng_nearest_source(curve, sorted_curves, ["fGasOut"])
        size_source = tng_nearest_source(curve, sorted_curves, ["h", "memoryLoad"])
        oracle_leff, _score = tng_best_leff_oracle(curve)
        shifted[curve["name"]] = shuffled_source["leff"]
        gas_matched[curve["name"]] = gas_source["leff"]
        size_matched[curve["name"]] = size_source["leff"]
        oracle[curve["name"]] = oracle_leff
        ledger.append(
            {
                "name": curve["name"],
                "subhaloId": curve.get("subhaloId", ""),
                "canonicalLeff": curve["leff"],
                "fixedMedianLeff": median_leff,
                "hOnlyLeff": curve["h"] * median_leff_over_h,
                "shuffledLeff": shifted[curve["name"]],
                "shuffledSource": shuffled_source["name"],
                "gasMatchedLeff": gas_matched[curve["name"]],
                "gasMatchedSource": gas_source["name"],
                "sizeMatchedLeff": size_matched[curve["name"]],
                "sizeMatchedSource": size_source["name"],
                "oracleLeff": oracle_leff,
                "oracleStatus": "non-promotable per-galaxy best L_eff ceiling",
            }
        )
    maps["shuffled-leff-null"] = shifted
    maps["gas-fraction-matched-leff-null"] = gas_matched
    maps["mass-size-matched-leff-null"] = size_matched
    maps["per-galaxy-best-leff-oracle"] = oracle
    return maps, ledger


def tng_state_audit_evaluate_variants(curves: list[dict]) -> tuple[list[dict], list[dict], list[dict], list[dict]]:
    leff_maps, leff_rows = tng_state_audit_leff_maps(curves)
    case_rows = []
    shape_rows = []
    baryon_scores = {curve["name"]: score_curve_baryon_only(curve) for curve in curves}
    canonical_scores = {curve["name"]: score_curve_with_params(curve, 1.0, Q_DEFAULT) for curve in curves}
    for curve in curves:
        baryon_shape = tng_support_shape_metrics(curve, 0.0, "baryon-only")
        shape_rows.append({"name": curve["name"], "subhaloId": curve.get("subhaloId", ""), **baryon_shape})
        case_rows.append(
            {
                "variantId": "baryon-only",
                "name": curve["name"],
                "subhaloId": curve.get("subhaloId", ""),
                "rmse": baryon_scores[curve["name"]]["rmse"],
                "gainPctVsBaryonOnly": 0.0,
                "route": curve["route"],
                "candidateRoute": "",
                "leffUsed": 0.0,
                "promotionEligible": False,
            }
        )
        for variant_id, leff_map in leff_maps.items():
            leff = leff_map[curve["name"]]
            score = score_curve_with_leff_value(curve, leff)
            shape = tng_support_shape_metrics(curve, leff, variant_id)
            shape_rows.append({"name": curve["name"], "subhaloId": curve.get("subhaloId", ""), **shape})
            case_rows.append(
                {
                    "variantId": variant_id,
                    "name": curve["name"],
                    "subhaloId": curve.get("subhaloId", ""),
                    "rmse": score["rmse"],
                    "gainPctVsBaryonOnly": pct_improvement(baryon_scores[curve["name"]]["rmse"], score["rmse"]),
                    "route": curve["route"],
                    "candidateRoute": score["candidateRoute"],
                    "leffUsed": leff,
                    "promotionEligible": False,
                }
            )
    variant_rows = []
    for variant_id in ["baryon-only"] + sorted(leff_maps):
        rows = [row for row in case_rows if row["variantId"] == variant_id]
        shapes = [row for row in shape_rows if row["variantId"] == variant_id]
        baryon_mean = safe_mean(baryon_scores[row["name"]]["rmse"] for row in rows if row["name"] in baryon_scores)
        mean_rmse = safe_mean(parse_float(row.get("rmse")) for row in rows)
        variant_rows.append(
            {
                "variantId": variant_id,
                "evidenceTier": "simulation-only mechanism audit",
                "galaxyCount": len(rows),
                "meanRmse": mean_rmse,
                "meanGainPctVsBaryonOnly": pct_improvement(baryon_mean, mean_rmse),
                "meanSupportVelocityRmse": safe_mean(parse_float(row.get("supportVelocityRmse")) for row in shapes),
                "meanSupportSquaredRmse": safe_mean(parse_float(row.get("supportSquaredRmse")) for row in shapes),
                "meanSupportShapeRmse": safe_mean(parse_float(row.get("supportShapeRmse")) for row in shapes),
                "meanInnerSupportBias": safe_mean(parse_float(row.get("innerSupportBias")) for row in shapes),
                "meanMidSupportBias": safe_mean(parse_float(row.get("midSupportBias")) for row in shapes),
                "meanOuterSupportBias": safe_mean(parse_float(row.get("outerSupportBias")) for row in shapes),
                "promotionEligible": False,
            }
        )
    return variant_rows, case_rows, shape_rows, leff_rows


def tng_state_audit_route_sensitivity(curves: list[dict], profile_rows: list[dict], state_rows: list[dict]) -> list[dict]:
    grouped: dict[str, list[dict]] = {}
    for row in profile_rows:
        name = f"{row.get('sim', '')}_subhalo_{row.get('subhaloId', '')}"
        grouped.setdefault(name, []).append(row)
    state_by_name = {row.get("name", ""): row for row in state_rows}
    out = []
    for curve in curves:
        source_rows = grouped.get(curve["name"], [])
        state = state_by_name.get(curve["name"], {})
        for mode in ["current", "trimmed-8h-20kpc", "conservative-5h-15kpc"]:
            for h_scale in [0.75, 1.0, 1.25, 1.5]:
                h_value = curve["h"] * h_scale
                if mode == "current":
                    limit = curve["rOut"]
                elif mode == "trimmed-8h-20kpc":
                    limit = min(curve["rOut"], 8.0 * h_value, 20.0)
                else:
                    limit = min(curve["rOut"], 5.0 * h_value, 15.0)
                variant = tng_state_audit_curve_from_profile(curve["name"], source_rows, state, h_scale=h_scale, r_limit=limit)
                if not variant:
                    out.append(
                        {
                            "name": curve["name"],
                            "subhaloId": curve.get("subhaloId", ""),
                            "rOutMode": mode,
                            "hScale": h_scale,
                            "status": "not-scoreable",
                            "pointCount": 0,
                            "rOut": math.nan,
                            "hProxy": h_value,
                            "route": "",
                            "lockedRoute": "",
                            "lowLoadObserved": False,
                            "lowLoadLocked": False,
                        }
                    )
                    continue
                out.append(
                    {
                        "name": curve["name"],
                        "subhaloId": curve.get("subhaloId", ""),
                        "rOutMode": mode,
                        "hScale": h_scale,
                        "status": "scoreable",
                        "pointCount": len(variant["points"]),
                        "rOut": variant["rOut"],
                        "hProxy": variant["h"],
                        "fGasOut": variant["fGasOut"],
                        "memoryLoad": variant["memoryLoad"],
                        "leff": variant["leff"],
                        "u075": variant["u075"],
                        "uOut": variant["uOut"],
                        "uMax": variant["uMax"],
                        "route": variant["route"],
                        "lockedRoute": variant["lockedModelRoute"],
                        "lowLoadObserved": variant["route"] == "low-load",
                        "lowLoadLocked": variant["lockedModelRoute"] == "low-load",
                    }
                )
    return out


def tng_state_audit_verdict(variant_rows: list[dict], route_rows: list[dict]) -> tuple[str, list[str], dict]:
    by_id = {row["variantId"]: row for row in variant_rows}
    canonical = by_id.get("canonical-locked-mts", {})
    control_ids = [
        "fixed-median-leff",
        "h-only-median-leff-over-h",
        "shuffled-leff-null",
        "gas-fraction-matched-leff-null",
        "mass-size-matched-leff-null",
    ]
    rmse_margins = []
    shape_margins = []
    failures = []
    for control_id in control_ids:
        control = by_id.get(control_id, {})
        control_rmse = parse_float(control.get("meanRmse"))
        canonical_rmse = parse_float(canonical.get("meanRmse"))
        control_shape = parse_float(control.get("meanSupportShapeRmse"))
        canonical_shape = parse_float(canonical.get("meanSupportShapeRmse"))
        rmse_margin = pct_improvement(control_rmse, canonical_rmse)
        shape_margin = pct_improvement(control_shape, canonical_shape)
        rmse_margins.append(rmse_margin)
        shape_margins.append(shape_margin)
        if not math.isfinite(rmse_margin) or rmse_margin < 10.0:
            failures.append(f"canonical does not beat {control_id} by 10% on RMSE")
        if not math.isfinite(shape_margin) or shape_margin < 10.0:
            failures.append(f"canonical does not beat {control_id} by 10% on support-shape error")
    lowload_rows = [row for row in route_rows if parse_bool(row.get("lowLoadObserved")) or parse_bool(row.get("lowLoadLocked"))]
    metrics = {
        "minRmseMarginPctVsControls": min(rmse_margins) if rmse_margins else math.nan,
        "minShapeMarginPctVsControls": min(shape_margins) if shape_margins else math.nan,
        "lowLoadVariantRows": len(lowload_rows),
        "lowLoadGalaxies": len({row["name"] for row in lowload_rows}),
    }
    if not lowload_rows:
        return "route construction blocks v21 test", failures + ["low-load remains absent across radius/scale variants"], metrics
    if failures:
        return "support-scale effect, not state-specific yet", failures, metrics
    return "MTS state-specific simulation signal", [], metrics


def tng_state_audit_next_targets(route_rows: list[dict], verdict: str) -> list[dict]:
    lowload_names = sorted({row["name"] for row in route_rows if parse_bool(row.get("lowLoadObserved")) or parse_bool(row.get("lowLoadLocked"))})
    if lowload_names:
        return [
            {
                "rank": index,
                "name": name,
                "nextMode": "tnglowloadsample",
                "reason": "low-load appears under cached route/radius sensitivity; worth targeted sample",
                "promotionEligible": False,
            }
            for index, name in enumerate(lowload_names, start=1)
        ]
    return [
        {
            "rank": 1,
            "name": "",
            "nextMode": "tngbroadsampleselector",
            "reason": "low-load absent across current cached variants; broaden TNG sample selection before v21 testing",
            "promotionEligible": False,
        },
        {
            "rank": 2,
            "name": "",
            "nextMode": "no-v21-tuning",
            "reason": "frozen v21 cannot activate without low-load cases; do not tune v21 on buffered single-crossing sample",
            "promotionEligible": False,
        },
    ]


def write_tng_state_audit_artifacts(out_dir: Path, pilot_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    curves, state_rows, missing_rows = tng_state_audit_load_curves(pilot_dir)
    profile_rows = read_csv_rows(pilot_dir / "mts_tng_pilot_profiles.csv")
    variant_rows, case_rows, shape_rows, leff_rows = tng_state_audit_evaluate_variants(curves)
    route_rows = tng_state_audit_route_sensitivity(curves, profile_rows, state_rows)
    verdict, failures, decision_metrics = tng_state_audit_verdict(variant_rows, route_rows)
    next_rows = tng_state_audit_next_targets(route_rows, verdict)
    baseline = baseline_summary(build_curves())
    capsule = {
        "mode": "tngstateaudit",
        "createdUtc": "deterministic",
        "verdict": verdict,
        "guardrailFailures": failures,
        "decisionMetrics": {
            **decision_metrics,
            "scoreableTngCount": len(curves),
            "baselineMean": baseline["baselineMean"],
            "apiKeyRequired": False,
            "apiKeySerialized": False,
            "networkFetchAllowed": False,
            "canonicalMtsPromoted": False,
            "v21Promoted": False,
        },
        "source": {
            "pilotDir": str(pilot_dir.resolve()),
            "profileRows": len(profile_rows),
            "stateRows": len(state_rows),
            "missingCurves": len(missing_rows),
        },
        "rules": {
            "evidenceTier": "simulation-only mechanism evidence",
            "observationalValidation": False,
            "noFrameworkPromotion": True,
        },
    }
    write_csv(out_dir / "mts_tng_state_audit_variant_scores.csv", variant_rows)
    write_csv(out_dir / "mts_tng_state_audit_case_ledger.csv", case_rows)
    write_csv(out_dir / "mts_tng_state_audit_support_shape.csv", shape_rows)
    write_csv(out_dir / "mts_tng_state_audit_leff_nulls.csv", leff_rows)
    write_csv(out_dir / "mts_tng_state_audit_route_sensitivity.csv", route_rows)
    write_csv(out_dir / "mts_tng_state_audit_next_targets.csv", next_rows)
    if missing_rows:
        write_csv(out_dir / "mts_tng_state_audit_missing_curves.csv", missing_rows)
    lines = [
        "# MTS v22.1 TNG State-Specificity Audit",
        "",
        f"Verdict: **{verdict}**",
        "",
        "This is cached simulation-only mechanism evidence. No network fetch occurred, no API key is required, and no canonical MTS or v21 promotion is allowed.",
        "",
        "## Baseline Facts",
        "",
        f"- TNG scoreable curves: `{len(curves)}`",
        f"- SPARC locked baseline mean: `{fmt(baseline['baselineMean'])}`",
        f"- Low-load variant galaxies: `{decision_metrics['lowLoadGalaxies']}`",
        f"- Minimum RMSE margin vs controls: `{fmt(decision_metrics['minRmseMarginPctVsControls'])}%`",
        f"- Minimum support-shape margin vs controls: `{fmt(decision_metrics['minShapeMarginPctVsControls'])}%`",
        "",
        "## Variant Scores",
        "",
        "| Variant | Mean RMSE | Gain vs baryon-only | Shape RMSE |",
        "| --- | ---: | ---: | ---: |",
    ]
    for row in variant_rows:
        lines.append(
            f"| {row['variantId']} | {fmt(row['meanRmse'])} | {fmt(row['meanGainPctVsBaryonOnly'])}% | {fmt(row['meanSupportShapeRmse'], 4)} |"
        )
    lines.extend(["", "## Guardrail Failures", ""])
    lines.extend([f"- {failure}" for failure in failures] or ["- none"])
    lines.extend(
        [
            "",
            "## Next Action",
            "",
            f"- `{next_rows[0]['nextMode']}`: {next_rows[0]['reason']}",
        ]
    )
    (out_dir / "mts_tng_state_audit_report.md").write_text("\n".join(lines), encoding="utf-8")
    (out_dir / "mts_tng_state_audit_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_tngstateaudit(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_TNG_STATE_AUDIT_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    pilot_dir = output_pack_dir("mts-tng-mechanism-pilot-v1")
    capsule = write_tng_state_audit_artifacts(out_dir, pilot_dir)
    metrics = capsule["decisionMetrics"]
    print("MTS TNG state-specificity audit v2: cached simulation-only")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"scoreable={metrics['scoreableTngCount']}",
                f"lowload_galaxies={metrics['lowLoadGalaxies']}",
                f"min_rmse_margin={fmt(metrics['minRmseMarginPctVsControls'])}%",
                f"min_shape_margin={fmt(metrics['minShapeMarginPctVsControls'])}%",
                f"v21_promoted={metrics['v21Promoted']}",
            ]
        )
    )
    print(f"Wrote TNG state audit to {out_dir.resolve()}")


