def tng_detail_sim_name(detail: dict) -> str:
    for source in [
        str(detail.get("_sim", "")),
        str(detail.get("meta", {}).get("simulation", "")) if isinstance(detail.get("meta"), dict) else "",
        str(detail.get("meta", {}).get("url", "")) if isinstance(detail.get("meta"), dict) else "",
        str(detail.get("_apiUrl", "")),
    ]:
        match = re.search(r"/api/([^/]+)/", source)
        if match:
            return match.group(1)
        if source in TNG_SIM_CANDIDATES:
            return source
    return ""


def tng_is_subhalo_detail(data: object) -> bool:
    return isinstance(data, dict) and "id" in data and "mass_stars" in data and "len_stars" in data and (
        isinstance(data.get("meta"), dict) or "halfmassrad_stars" in data
    )


def tng_cached_subhalo_details(source_cache: Path) -> list[dict]:
    rows = []
    for path in sorted((source_cache / "api-json").glob("*.json")):
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            continue
        if not tng_is_subhalo_detail(data):
            continue
        row = dict(data)
        row["_cachePath"] = str(path)
        row["_cacheSha256"] = file_sha256(path)
        sim_name = tng_detail_sim_name(row)
        if sim_name:
            row["_sim"] = sim_name
        rows.append(row)
    return rows


def tng_broad_fetch_metadata(source_cache: Path, api_key: str, offline: bool) -> tuple[list[dict], list[dict]]:
    inventory = []
    detail_rows: dict[tuple[str, int], dict] = {}
    if not offline and api_key:
        for sim_name in TNG_SIM_CANDIDATES:
            subhalos_url = tng_endpoint(TNG_BASE_URL, sim_name, "snapshots", "z=0", "subhalos")
            for band in TNG_BROAD_QUERY_BANDS:
                data, row = tng_api_get_json(
                    subhalos_url,
                    source_cache,
                    api_key,
                    params=band["params"],
                    offline=False,
                    reason=f"broad-selector-{band['band']}",
                )
                results = tng_results(data)
                inventory.append({**row, "sim": sim_name, "queryBand": band["band"], "endpoint": "subhalos", "resultCount": len(results)})
                for item in results[:TNG_BROAD_QUERY_LIMIT]:
                    sub_id = tng_subhalo_id(item)
                    if sub_id < 0:
                        continue
                    full_url = tng_full_subhalo_url(item)
                    full_data, full_row = tng_api_get_json(
                        full_url,
                        source_cache,
                        api_key,
                        offline=False,
                        reason=f"broad-selector-detail-{band['band']}",
                    )
                    inventory.append({**full_row, "sim": sim_name, "queryBand": band["band"], "endpoint": "subhalo-detail", "resultCount": 1 if isinstance(full_data, dict) else 0})
                    if isinstance(full_data, dict):
                        full_data["_apiUrl"] = full_url
                        full_data["_sim"] = sim_name
                        full_data["_queryBand"] = band["band"]
                        cache_path = tng_json_cache_path(source_cache, full_url)
                        if cache_path.exists():
                            full_data["_cachePath"] = str(cache_path)
                            full_data["_cacheSha256"] = file_sha256(cache_path)
                        detail_rows[(sim_name, tng_subhalo_id(full_data))] = full_data
    else:
        inventory.append(
            {
                "kind": "api-json",
                "reason": "broad-selector-cache-only",
                "url": "",
                "params": "",
                "cachePath": str(source_cache),
                "cacheStatus": "cache-scan",
                "status": "ok",
                "sizeBytes": 0,
                "sha256": "",
                "sim": "",
                "queryBand": "cached-details",
                "endpoint": "cache",
                "resultCount": 0,
            }
        )
    for cached in tng_cached_subhalo_details(source_cache):
        sim_name = tng_detail_sim_name(cached)
        if sim_name not in TNG_SIM_CANDIDATES:
            continue
        key = (sim_name, tng_subhalo_id(cached))
        merged = dict(cached)
        merged["_sim"] = sim_name
        merged["_queryBand"] = merged.get("_queryBand", "cached-detail")
        detail_rows.setdefault(key, merged)
    return inventory, list(detail_rows.values())


def tng_broad_canonical_api_inventory(details: list[dict]) -> list[dict]:
    rows = []
    for detail in details:
        sim_name = tng_detail_sim_name(detail)
        sub_id = tng_subhalo_id(detail)
        cache_path = detail.get("_cachePath", "")
        rows.append(
            {
                "kind": "api-json",
                "endpoint": "subhalo-detail",
                "sim": sim_name,
                "subhaloId": sub_id,
                "queryBand": detail.get("_queryBand", "cached-detail"),
                "url": detail.get("_apiUrl") or detail.get("url", ""),
                "cachePath": cache_path,
                "cacheOnDDrive": str(cache_path).lower().startswith("d:"),
                "cacheStatus": "available" if cache_path and Path(cache_path).exists() else "metadata-row-only",
                "sizeBytes": Path(cache_path).stat().st_size if cache_path and Path(cache_path).exists() else 0,
                "sha256": detail.get("_cacheSha256", file_sha256(Path(cache_path)) if cache_path and Path(cache_path).exists() else ""),
            }
        )
    return sorted(rows, key=lambda row: (row["sim"], row["subhaloId"], row["queryBand"], row["cachePath"]))


def tng_broad_candidate_row(detail: dict, existing_pilot_ids: set[tuple[str, str]]) -> dict:
    sim_name = tng_detail_sim_name(detail)
    sub_id = tng_subhalo_id(detail)
    mass_stars = tng_float(detail, "mass_stars", default=0.0)
    mass_gas = tng_float(detail, "mass_gas", default=0.0)
    gas_fraction = mass_gas / (mass_gas + mass_stars) if mass_gas + mass_stars > 0 else math.nan
    half_stars = tng_float(detail, "halfmassrad_stars", "halfmassrad_star")
    half_gas = tng_float(detail, "halfmassrad_gas")
    h_proxy = half_stars / 1.678 if math.isfinite(half_stars) and half_stars > 0 else math.nan
    gas_extent_ratio = half_gas / half_stars if math.isfinite(half_gas) and math.isfinite(half_stars) and half_stars > 0 else math.nan
    r_proxy = math.nan
    if math.isfinite(h_proxy) and h_proxy > 0:
        terms = [5.0 * h_proxy]
        if math.isfinite(half_gas) and half_gas > 0:
            terms.append(0.5 * half_gas)
        r_proxy = min(30.0, max(terms))
    r_over_h = r_proxy / h_proxy if math.isfinite(r_proxy) and math.isfinite(h_proxy) and h_proxy > 0 else math.nan
    memory_load = (1.0 - gas_fraction) * r_over_h if math.isfinite(gas_fraction) and math.isfinite(r_over_h) else math.nan
    estimated = tng_estimated_cutout_bytes(detail)
    size_ok = estimated <= TNG_MAX_CUTOUT_BYTES
    stellar_mass_score = clamp(1.0 - math.log10(max(mass_stars, 1e-5) / 0.02 + 1.0) / 3.0, 0.0, 1.0)
    gas_score = clamp(gas_fraction if math.isfinite(gas_fraction) else 0.0, 0.0, 1.0)
    memory_score = 1.0 / (1.0 + max(0.0, memory_load if math.isfinite(memory_load) else 12.0) / 6.0)
    extent_score = clamp((gas_extent_ratio if math.isfinite(gas_extent_ratio) else 1.0) / 8.0, 0.0, 1.0)
    lowload_score = 100.0 * (0.45 * gas_score + 0.25 * stellar_mass_score + 0.20 * memory_score + 0.10 * extent_score)
    if lowload_score >= 55.0 and size_ok:
        lowload_bucket = "plausible low-load candidate"
    elif gas_score >= 0.35 and size_ok:
        lowload_bucket = "gas-rich extended candidate"
    elif size_ok:
        lowload_bucket = "buffered/control candidate"
    else:
        lowload_bucket = "oversize metadata-only"
    if lowload_bucket == "plausible low-load candidate":
        target_bucket = "low-load candidates"
    elif lowload_bucket == "gas-rich extended candidate":
        target_bucket = "gas-rich/extended candidates"
    elif sim_name == "TNG100-1":
        target_bucket = "fallback TNG100 candidates"
    else:
        target_bucket = "buffered/control candidates"
    return {
        "sim": sim_name,
        "subhaloId": sub_id,
        "candidateKey": f"{sim_name}:{sub_id}",
        "queryBand": detail.get("_queryBand", "cached-detail"),
        "sourceMetadataPath": detail.get("_cachePath", ""),
        "sourceMetadataSha256": detail.get("_cacheSha256", ""),
        "massStarsCode": mass_stars,
        "massGasCode": mass_gas,
        "gasFractionProxy": gas_fraction,
        "sfr": tng_float(detail, "sfr"),
        "stellarHalfMassRadiusCode": half_stars,
        "gasHalfMassRadiusCode": half_gas,
        "hProxyCode": h_proxy,
        "gasExtentRatio": gas_extent_ratio,
        "rOutProxyCode": r_proxy,
        "rOutOverHProxy": r_over_h,
        "memoryLoadProxy": memory_load,
        "lenStars": tng_int(detail, "len_stars"),
        "lenGas": tng_int(detail, "len_gas"),
        "lenDm": tng_int(detail, "len_dm"),
        "estimatedCutoutBytes": estimated,
        "estimatedCutoutMB": estimated / (1024 * 1024),
        "manageableCutout": size_ok,
        "alreadyInPilot": (sim_name, str(sub_id)) in existing_pilot_ids,
        "lowLoadLikelihoodScore": lowload_score,
        "lowLoadLikelihoodBucket": lowload_bucket,
        "routeDiversityTargetBucket": target_bucket,
        "usedForMtsScoringNow": False,
        "usedForV21PromotionNow": False,
    }


def tng_broad_existing_pilot_ids() -> set[tuple[str, str]]:
    rows = read_csv_rows(output_pack_dir("mts-tng-mechanism-pilot-v1") / "mts_tng_pilot_inventory.csv")
    return {(row.get("sim", ""), str(row.get("subhaloId", ""))) for row in rows if row.get("status") == "accepted"}


def tng_broad_select_manifest(candidate_rows: list[dict]) -> list[dict]:
    selected: list[dict] = []
    seen = set()

    def add(bucket: str, limit: int, *, sim: str | None = None) -> None:
        rows = [
            row
            for row in candidate_rows
            if row["routeDiversityTargetBucket"] == bucket
            and row["manageableCutout"]
            and (sim is None or row["sim"] == sim)
            and row["candidateKey"] not in seen
        ]
        rows.sort(
            key=lambda row: (
                parse_bool(row.get("alreadyInPilot")),
                -parse_float(row.get("lowLoadLikelihoodScore"), 0.0),
                parse_float(row.get("estimatedCutoutBytes"), math.inf),
                row["candidateKey"],
            )
        )
        for row in rows[:limit]:
            seen.add(row["candidateKey"])
            selected.append({**row, "manifestRank": len(selected) + 1, "selectionReason": f"quota:{bucket}"})

    add("low-load candidates", 20, sim="TNG50-1")
    add("gas-rich/extended candidates", 15, sim="TNG50-1")
    add("buffered/control candidates", 15, sim="TNG50-1")
    if sum(1 for row in selected if row["routeDiversityTargetBucket"] == "low-load candidates") < 20:
        add("fallback TNG100 candidates", 10, sim="TNG100-1")
        add("low-load candidates", 10, sim="TNG100-1")
    return selected[:60]


def tng_broad_group_summary(candidate_rows: list[dict], manifest_rows: list[dict]) -> list[dict]:
    groups = sorted({row["routeDiversityTargetBucket"] for row in candidate_rows} | {row["routeDiversityTargetBucket"] for row in manifest_rows})
    rows = []
    for group in groups:
        candidates = [row for row in candidate_rows if row["routeDiversityTargetBucket"] == group]
        selected = [row for row in manifest_rows if row["routeDiversityTargetBucket"] == group]
        rows.append(
            {
                "routeDiversityTargetBucket": group,
                "candidateCount": len(candidates),
                "manageableCandidateCount": sum(1 for row in candidates if parse_bool(row.get("manageableCutout"))),
                "selectedCount": len(selected),
                "meanLowLoadLikelihoodScore": safe_mean(parse_float(row.get("lowLoadLikelihoodScore")) for row in candidates),
                "meanEstimatedCutoutMB": safe_mean(parse_float(row.get("estimatedCutoutMB")) for row in candidates),
            }
        )
    return rows


def tng_broad_next_actions(manifest_rows: list[dict], group_rows: list[dict]) -> list[dict]:
    low_count = sum(1 for row in manifest_rows if row["routeDiversityTargetBucket"] == "low-load candidates")
    tng100_count = sum(1 for row in manifest_rows if row["sim"] == "TNG100-1")
    if low_count >= 20:
        verdict = "tngroutesamplepilot"
        reason = "at least 20 plausible low-load/extended candidates with manageable cutouts were selected"
    elif tng100_count > 0:
        verdict = "tngroutesamplepilot-tng100"
        reason = "TNG50 low-load diversity is thin; include TNG100 fallback candidates"
    else:
        verdict = "stop-v21-in-tng-for-now"
        reason = "TNG route diversity not accessible from cheap metadata"
    return [
        {
            "rank": 1,
            "nextMode": verdict,
            "reason": reason,
            "selectedManifestCount": len(manifest_rows),
            "selectedLowLoadCandidateCount": low_count,
            "selectedTng100Count": tng100_count,
            "promotionEligible": False,
        }
    ]


def write_tng_broad_selector_artifacts(out_dir: Path, source_cache: Path, offline: bool) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    source_cache.mkdir(parents=True, exist_ok=True)
    api_key, key_status = tng_api_key_status()
    inventory_rows, details = tng_broad_fetch_metadata(source_cache, api_key, offline)
    api_inventory_rows = tng_broad_canonical_api_inventory(details)
    existing_ids = tng_broad_existing_pilot_ids()
    candidates_by_key = {}
    for detail in details:
        row = tng_broad_candidate_row(detail, existing_ids)
        if not row["sim"] or tng_int(row, "subhaloId", default=-1) < 0:
            continue
        candidates_by_key[row["candidateKey"]] = row
    candidate_rows = sorted(candidates_by_key.values(), key=lambda row: (row["sim"], -parse_float(row.get("lowLoadLikelihoodScore"), 0.0), row["subhaloId"]))
    manifest_rows = tng_broad_select_manifest(candidate_rows)
    group_rows = tng_broad_group_summary(candidate_rows, manifest_rows)
    next_rows = tng_broad_next_actions(manifest_rows, group_rows)
    low_count = sum(1 for row in manifest_rows if row["routeDiversityTargetBucket"] == "low-load candidates")
    verdict = next_rows[0]["nextMode"]
    capsule = {
        "mode": "tngbroadsampleselector",
        "createdUtc": "deterministic",
        "verdict": verdict,
        "metrics": {
            "apiKeyStatus": key_status,
            "apiKeySerialized": False,
            "cutoutDownloadsAllowed": False,
            "sourceCache": str(source_cache.resolve()),
            "sourceCacheOnDDrive": str(source_cache).lower().startswith("d:"),
            "apiMetadataRows": len(api_inventory_rows),
            "rawApiQueryRowsObserved": len(inventory_rows),
            "candidateCount": len(candidate_rows),
            "manifestCount": len(manifest_rows),
            "selectedLowLoadCandidateCount": low_count,
            "selectedTng100Count": sum(1 for row in manifest_rows if row["sim"] == "TNG100-1"),
            "baselineMean": baseline_summary(build_curves())["baselineMean"],
            "v21Promoted": False,
            "canonicalMtsPromoted": False,
        },
        "rules": {
            "metadataOnly": True,
            "noHdf5Cutouts": True,
            "noMtsScoring": True,
            "simulationOnly": True,
            "noFrameworkPromotion": True,
        },
    }
    write_csv(out_dir / "mts_tng_broad_selector_api_inventory.csv", api_inventory_rows)
    write_csv(out_dir / "mts_tng_broad_selector_candidates.csv", candidate_rows)
    write_csv(out_dir / "mts_tng_broad_selector_target_manifest.csv", manifest_rows)
    write_csv(out_dir / "mts_tng_broad_selector_group_summary.csv", group_rows)
    write_csv(out_dir / "mts_tng_broad_selector_next_actions.csv", next_rows)
    lines = [
        "# MTS v22.2 TNG Broad Route-Diverse Sample Selector",
        "",
        f"Verdict: **{verdict}**",
        "",
        "This is a metadata-only TNG target selector. It does not download cutouts, does not score MTS, and does not promote v21.",
        "",
        "## Facts",
        "",
        f"- Candidate metadata rows: `{len(candidate_rows)}`",
        f"- Target manifest rows: `{len(manifest_rows)}`",
        f"- Selected low-load candidates: `{low_count}`",
        f"- Selected TNG100 fallback candidates: `{capsule['metrics']['selectedTng100Count']}`",
        f"- Source cache on D: `{capsule['metrics']['sourceCacheOnDDrive']}`",
        f"- API key serialized: `False`",
        "",
        "## Group Summary",
        "",
        "| Bucket | Candidates | Manageable | Selected | Mean low-load score |",
        "| --- | ---: | ---: | ---: | ---: |",
    ]
    for row in group_rows:
        lines.append(
            f"| {row['routeDiversityTargetBucket']} | {row['candidateCount']} | {row['manageableCandidateCount']} | {row['selectedCount']} | {fmt(row['meanLowLoadLikelihoodScore'])} |"
        )
    lines.extend(
        [
            "",
            "## Next Action",
            "",
            f"- `{next_rows[0]['nextMode']}`: {next_rows[0]['reason']}",
        ]
    )
    (out_dir / "mts_tng_broad_selector_report.md").write_text("\n".join(lines), encoding="utf-8")
    (out_dir / "mts_tng_broad_selector_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_tngbroadsampleselector(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_TNG_BROAD_SELECTOR_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    source_cache = Path(args.source_cache) if args.source_cache else DEFAULT_TNG_SOURCE_CACHE
    capsule = write_tng_broad_selector_artifacts(out_dir, source_cache, args.offline)
    metrics = capsule["metrics"]
    print("MTS TNG broad route-diverse sample selector v3: metadata-only")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"candidates={metrics['candidateCount']}",
                f"manifest={metrics['manifestCount']}",
                f"lowload={metrics['selectedLowLoadCandidateCount']}",
                f"tng100={metrics['selectedTng100Count']}",
                f"cutouts_downloaded=false",
                f"v21_promoted={metrics['v21Promoted']}",
            ]
        )
    )
    print(f"Wrote TNG broad selector to {out_dir.resolve()}")


def tng_route_sample_manifest_path(args: argparse.Namespace) -> Path:
    return Path(args.tng_target_manifest) if args.tng_target_manifest else DEFAULT_TNG_ROUTE_SAMPLE_MANIFEST


def tng_route_sample_load_manifest(path: Path) -> list[dict]:
    rows = read_csv_rows(path)
    out = []
    for index, row in enumerate(rows, start=1):
        sim_name = row.get("sim", "")
        sub_id = tng_int(row, "subhaloId", default=-1)
        if not sim_name or sub_id < 0:
            continue
        out.append(
            {
                **row,
                "manifestRank": tng_int(row, "manifestRank", default=index),
                "sim": sim_name,
                "subhaloId": sub_id,
                "candidateKey": row.get("candidateKey") or f"{sim_name}:{sub_id}",
                "routeDiversityTargetBucket": row.get("routeDiversityTargetBucket", ""),
                "alreadyInPilot": parse_bool(row.get("alreadyInPilot")),
                "estimatedCutoutBytes": tng_int(row, "estimatedCutoutBytes", default=0),
                "estimatedCutoutMB": parse_float(row.get("estimatedCutoutMB"), math.nan),
            }
        )
    return sorted(out, key=lambda row: (row["manifestRank"], row["sim"], row["subhaloId"]))


def tng_route_sample_detail_url(full: dict, sim_name: str, subhalo_id: int) -> str:
    meta = full.get("meta") if isinstance(full.get("meta"), dict) else {}
    url = str(full.get("_apiUrl") or full.get("url") or meta.get("url") or "")
    if not url:
        url = tng_endpoint(TNG_BASE_URL, sim_name, "snapshots", "99", "subhalos", str(subhalo_id))
    return url if url.endswith("/") else url + "/"


def tng_route_sample_cutout_url(full: dict, sim_name: str, subhalo_id: int) -> str:
    cutouts = full.get("cutouts") if isinstance(full.get("cutouts"), dict) else {}
    url = str(cutouts.get("subhalo") or "")
    return url or (tng_route_sample_detail_url(full, sim_name, subhalo_id) + "cutout.hdf5")


def tng_route_sample_load_detail(row: dict) -> tuple[dict | None, str]:
    path_text = row.get("sourceMetadataPath", "")
    if not path_text:
        return None, "missing source metadata path"
    path = Path(path_text)
    if not path.exists():
        return None, "source metadata path missing"
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        return None, f"source metadata unreadable: {exc}"
    if not isinstance(data, dict):
        return None, "source metadata is not a JSON object"
    data["_sim"] = row["sim"]
    data["_cachePath"] = str(path)
    data["_cacheSha256"] = file_sha256(path)
    data["_apiUrl"] = tng_route_sample_detail_url(data, row["sim"], row["subhaloId"])
    return data, "ok"


def tng_route_sample_normalize_fetch_row(row: dict) -> dict:
    out = dict(row)
    path_text = str(out.get("cachePath", ""))
    path = Path(path_text) if path_text else None
    if out.get("status") == "ok" and path and path.exists():
        out["cacheStatus"] = "available"
        out["status"] = "ok"
        out["sizeBytes"] = path.stat().st_size
        out["sha256"] = file_sha256(path)
    elif out.get("status") in {"missing-api-key", "missing-offline"} or str(out.get("status", "")).startswith("download-error:"):
        out["status"] = "missing-not-fetched"
        out["cacheStatus"] = "missing"
        out["sha256"] = ""
    return out


def tng_route_sample_state_row(curve: dict, manifest_row: dict, meta: dict) -> dict:
    terms = v19_curve_memory_terms(curve)
    return {
        "name": curve["name"],
        "sim": manifest_row["sim"],
        "subhaloId": manifest_row["subhaloId"],
        "manifestRank": manifest_row["manifestRank"],
        "routeDiversityTargetBucket": manifest_row["routeDiversityTargetBucket"],
        "alreadyInPilot": manifest_row["alreadyInPilot"],
        "rOut": curve["rOut"],
        "hProxy": curve["h"],
        "hProxySource": curve.get("hProxySource", ""),
        "fGasOut": curve["fGasOut"],
        "S_mem": terms["sMem"],
        "memoryLoad": terms["memoryLoad"],
        "L_exact": terms["lExact"],
        "L_sat": terms["lSat"],
        "L_gap": terms["lGap"],
        "u075": curve["u075"],
        "uOut": curve["uOut"],
        "uMax": curve["uMax"],
        "route": curve["route"],
        "lockedRoute": curve["lockedModelRoute"],
        "boundaryScore": terms["boundaryScore"],
        "routeMargin": curve.get("routeMargin", math.nan),
        "routeBreakRisk": curve.get("routeBreakRisk", math.nan),
        "stellarHalfMassRadiusKpc": curve.get("stellarHalfMassRadiusKpc", math.nan),
        "gasCellCount": meta.get("gasCellCount", math.nan),
        "starParticleCount": meta.get("starParticleCount", math.nan),
        "dmParticleCount": meta.get("dmParticleCount", math.nan),
        "sourceCutout": curve.get("sourceCutout", ""),
        "evidenceTier": "simulation-only mechanism evidence",
    }


def tng_route_sample_wide_case_ledger(curves: list[dict], manifest_by_name: dict[str, dict], v21_candidate: dict | None, v21_safety: dict | None) -> list[dict]:
    rows = []
    for curve in sorted(curves, key=lambda item: (item.get("sim", ""), int(parse_float(item.get("subhaloId"), 0)))):
        manifest = manifest_by_name.get(curve["name"], {})
        baryon = score_curve_baryon_only(curve)
        canonical = score_curve_with_params(curve, 1.0, Q_DEFAULT)
        v21_score, activation = tng_score_v21(curve, v21_candidate, v21_safety)
        rows.append(
            {
                "name": curve["name"],
                "sim": curve.get("sim", ""),
                "subhaloId": curve.get("subhaloId", ""),
                "manifestRank": manifest.get("manifestRank", ""),
                "routeDiversityTargetBucket": manifest.get("routeDiversityTargetBucket", ""),
                "alreadyInPilot": manifest.get("alreadyInPilot", ""),
                "evidenceTier": "simulation-only mechanism evidence",
                "baryonOnlyRmse": baryon["rmse"],
                "canonicalRmse": canonical["rmse"],
                "canonicalGainPctVsBaryonOnly": pct_improvement(baryon["rmse"], canonical["rmse"]),
                "v21Rmse": v21_score["rmse"] if v21_candidate else math.nan,
                "v21Activation": activation if v21_candidate else math.nan,
                "v21GainPctVsCanonical": pct_improvement(canonical["rmse"], v21_score["rmse"]) if v21_candidate else math.nan,
                "route": curve["route"],
                "lockedRoute": canonical["candidateRoute"],
                "lowLoadObserved": curve["route"] == "low-load",
                "lowLoadLocked": canonical["candidateRoute"] == "low-load",
                "v21CandidateRoute": v21_score["candidateRoute"] if v21_candidate else "",
                "rOut": curve["rOut"],
                "hProxy": curve["h"],
                "fGasOut": curve["fGasOut"],
                "memoryLoad": curve["memoryLoad"],
                "u075": curve["u075"],
                "uOut": curve["uOut"],
                "uMax": curve["uMax"],
                "sourceCutout": curve.get("sourceCutout", ""),
                "promotionEligible": False,
            }
        )
    return rows


def tng_route_sample_route_summary(curves: list[dict], manifest_rows: list[dict], accepted_rows: list[dict]) -> list[dict]:
    out = []
    for bucket in sorted({row.get("routeDiversityTargetBucket", "") for row in manifest_rows}):
        bucket_curves = [curve for curve in curves if any(row.get("subhaloId") == curve.get("subhaloId") and row.get("sim") == curve.get("sim") and row.get("routeDiversityTargetBucket") == bucket for row in accepted_rows)]
        out.append(
            {
                "summaryType": "manifest-bucket",
                "group": bucket,
                "manifestCount": sum(1 for row in manifest_rows if row.get("routeDiversityTargetBucket") == bucket),
                "scoreableCount": len(bucket_curves),
                "lockedLowLoadCount": sum(1 for curve in bucket_curves if score_curve_with_params(curve, 1.0, Q_DEFAULT)["candidateRoute"] == "low-load"),
                "observedLowLoadCount": sum(1 for curve in bucket_curves if curve["route"] == "low-load"),
            }
        )
    for route_kind, accessor in [
        ("observed-route", lambda curve: curve["route"]),
        ("locked-route", lambda curve: score_curve_with_params(curve, 1.0, Q_DEFAULT)["candidateRoute"]),
    ]:
        counts: dict[str, int] = {}
        for curve in curves:
            route = accessor(curve)
            counts[route] = counts.get(route, 0) + 1
        for route, count in sorted(counts.items()):
            out.append(
                {
                    "summaryType": route_kind,
                    "group": route,
                    "manifestCount": len(manifest_rows),
                    "scoreableCount": count,
                    "lockedLowLoadCount": count if route_kind == "locked-route" and route == "low-load" else "",
                    "observedLowLoadCount": count if route_kind == "observed-route" and route == "low-load" else "",
                }
            )
    return out


def tng_route_sample_split_scores(variant_rows: list[dict], v21_score_row: dict | None) -> tuple[list[dict], list[dict]]:
    candidate_ids = {"baryon-only", "canonical-locked-mts"}
    candidate_rows = []
    null_rows = []
    for row in variant_rows:
        record = {
            **row,
            "evidenceTier": "simulation-only mechanism evidence",
            "meanGainPctVsCanonical": row.get("meanGainPctVsCanonical", math.nan),
            "activeCount": row.get("activeCount", ""),
            "sourceFormulaStatus": row.get("sourceFormulaStatus", ""),
            "promotionEligible": False,
        }
        if row["variantId"] in candidate_ids:
            candidate_rows.append(record)
        else:
            null_rows.append(record)
    if v21_score_row:
        candidate_rows.append(v21_score_row)
    candidate_rows.sort(key=lambda row: row.get("variantId", row.get("candidateId", "")))
    null_rows.sort(key=lambda row: row["variantId"])
    return candidate_rows, null_rows


def tng_route_sample_v21_score(curves: list[dict], v21_candidate: dict | None, v21_safety: dict | None) -> dict | None:
    if not v21_candidate or not curves:
        return None
    baryon_scores = [score_curve_baryon_only(curve)["rmse"] for curve in curves]
    canonical_scores = [score_curve_with_params(curve, 1.0, Q_DEFAULT)["rmse"] for curve in curves]
    v21_scores = []
    activations = []
    for curve in curves:
        score, activation = tng_score_v21(curve, v21_candidate, v21_safety)
        v21_scores.append(score["rmse"])
        activations.append(activation)
    canonical_mean = safe_mean(canonical_scores)
    v21_mean = safe_mean(v21_scores)
    return {
        "variantId": "frozen-v21-memory-stretch",
        "evidenceTier": "simulation-only mechanism evidence",
        "galaxyCount": len(curves),
        "meanRmse": v21_mean,
        "meanGainPctVsBaryonOnly": pct_improvement(safe_mean(baryon_scores), v21_mean),
        "meanGainPctVsCanonical": pct_improvement(canonical_mean, v21_mean),
        "meanSupportVelocityRmse": math.nan,
        "meanSupportSquaredRmse": math.nan,
        "meanSupportShapeRmse": math.nan,
        "meanInnerSupportBias": math.nan,
        "meanMidSupportBias": math.nan,
        "meanOuterSupportBias": math.nan,
        "activeCount": sum(1 for value in activations if value > 0),
        "sourceFormulaStatus": "loaded",
        "promotionEligible": False,
    }


def tng_route_sample_support_specificity(variant_rows: list[dict]) -> tuple[str, list[str], dict]:
    by_id = {row["variantId"]: row for row in variant_rows}
    canonical = by_id.get("canonical-locked-mts", {})
    control_ids = [
        "fixed-median-leff",
        "h-only-median-leff-over-h",
        "shuffled-leff-null",
        "gas-fraction-matched-leff-null",
        "mass-size-matched-leff-null",
    ]
    rmse_margins = []
    shape_margins = []
    failures = []
    for control_id in control_ids:
        control = by_id.get(control_id, {})
        rmse_margin = pct_improvement(parse_float(control.get("meanRmse")), parse_float(canonical.get("meanRmse")))
        shape_margin = pct_improvement(parse_float(control.get("meanSupportShapeRmse")), parse_float(canonical.get("meanSupportShapeRmse")))
        rmse_margins.append(rmse_margin)
        shape_margins.append(shape_margin)
        if not math.isfinite(rmse_margin) or rmse_margin < 10.0:
            failures.append(f"canonical does not beat {control_id} by 10% on RMSE")
        if not math.isfinite(shape_margin) or shape_margin < 10.0:
            failures.append(f"canonical does not beat {control_id} by 10% on support-shape error")
    metrics = {
        "minRmseMarginPctVsControls": min([value for value in rmse_margins if math.isfinite(value)] or [math.nan]),
        "minShapeMarginPctVsControls": min([value for value in shape_margins if math.isfinite(value)] or [math.nan]),
    }
    if failures:
        return "support-scale effect, not state-specific", failures, metrics
    return "simulation state-specific signal", [], metrics


def tng_route_sample_verdict(curves: list[dict], variant_rows: list[dict]) -> tuple[str, list[str], dict, list[dict]]:
    locked_lowload = [curve for curve in curves if score_curve_with_params(curve, 1.0, Q_DEFAULT)["candidateRoute"] == "low-load"]
    observed_lowload = [curve for curve in curves if curve["route"] == "low-load"]
    support_verdict, support_failures, support_metrics = tng_route_sample_support_specificity(variant_rows)
    lowload_count = len({curve["name"] for curve in locked_lowload + observed_lowload})
    failures = list(support_failures)
    if len(curves) < 10:
        verdict = "insufficient route-sample scoreable data"
        next_mode = "rerun-online-with-api-key"
        reason = "fewer than 10 manifest targets became scoreable"
    elif lowload_count >= 5:
        verdict = "low-load route sample ready"
        next_mode = "tnglowloadmechanismaudit"
        reason = "at least 5 full-profile TNG galaxies landed as low-load"
    elif 1 <= lowload_count <= 4:
        verdict = "low-load scarce; stricter selector needed"
        next_mode = "tngbroadsampleselector-strict-lowload"
        reason = "only 1-4 low-load cases appeared after full profile construction"
    else:
        verdict = "cheap metadata does not access TNG low-load route diversity"
        next_mode = "stop-v21-in-tng-for-now"
        reason = "zero low-load cases appeared after full profile construction"
        failures.append("low-load count is 0")
    metrics = {
        **support_metrics,
        "scoreableTngCount": len(curves),
        "lockedLowLoadCount": len(locked_lowload),
        "observedLowLoadCount": len(observed_lowload),
        "anyLowLoadCount": lowload_count,
        "supportSpecificityVerdict": support_verdict,
    }
    next_rows = [
        {
            "rank": 1,
            "nextMode": next_mode,
            "reason": reason,
            "lowLoadCount": lowload_count,
            "scoreableTngCount": len(curves),
            "supportSpecificityVerdict": support_verdict,
            "promotionEligible": False,
        }
    ]
    return verdict, failures, metrics, next_rows


def write_tng_route_sample_artifacts(out_dir: Path, source_cache: Path, manifest_path: Path, offline: bool) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    source_cache.mkdir(parents=True, exist_ok=True)
    api_key, key_status = tng_api_key_status()
    manifest_rows = tng_route_sample_load_manifest(manifest_path)
    inventory_rows = []
    fetch_rows = []
    profile_rows = []
    state_rows = []
    curves = []
    accepted_manifest_rows = []
    h5py = None
    np = None
    deps_status = "not-required-yet"
    for manifest_row in manifest_rows:
        full, detail_status = tng_route_sample_load_detail(manifest_row)
        inventory = {
            "manifestRank": manifest_row["manifestRank"],
            "sim": manifest_row["sim"],
            "subhaloId": manifest_row["subhaloId"],
            "candidateKey": manifest_row["candidateKey"],
            "routeDiversityTargetBucket": manifest_row["routeDiversityTargetBucket"],
            "alreadyInPilot": manifest_row["alreadyInPilot"],
            "manifestEstimatedCutoutMB": manifest_row["estimatedCutoutMB"],
            "sourceMetadataPath": manifest_row.get("sourceMetadataPath", ""),
            "status": "skipped",
            "reason": detail_status,
            "cutoutCachePath": "",
            "cutoutStatus": "",
            "parserStatus": "",
            "route": "",
            "lockedRoute": "",
        }
        if full is None:
            inventory_rows.append(inventory)
            continue
        selected, reason = tng_candidate_passes(full)
        if not selected:
            inventory["reason"] = reason
            inventory_rows.append(inventory)
            continue
        sub_id = manifest_row["subhaloId"]
        cutout_path = tng_cutout_cache_path(source_cache, manifest_row["sim"], sub_id)
        params = {"gas": "Coordinates,Masses", "stars": "Coordinates,Masses", "dm": "Coordinates"}
        cutout_row = tng_api_download_file(
            tng_route_sample_cutout_url(full, manifest_row["sim"], sub_id),
            cutout_path,
            api_key,
            params=params,
            offline=offline,
            max_bytes=TNG_MAX_CUTOUT_BYTES,
        )
        cutout_row = tng_route_sample_normalize_fetch_row({**cutout_row, "sim": manifest_row["sim"], "endpoint": "cutout", "subhaloId": sub_id, "manifestRank": manifest_row["manifestRank"]})
        fetch_rows.append(cutout_row)
        inventory["cutoutCachePath"] = str(cutout_path)
        inventory["cutoutStatus"] = cutout_row["status"]
        if cutout_row["status"] != "ok":
            inventory["reason"] = f"cutout {cutout_row['status']}"
            inventory_rows.append(inventory)
            continue
        if h5py is None or np is None:
            h5py, np, deps_status = tng_ensure_hdf5_deps(offline)
        if h5py is None or np is None:
            inventory["reason"] = f"hdf5 deps {deps_status}"
            inventory["parserStatus"] = deps_status
            inventory_rows.append(inventory)
            continue
        try:
            curve, per_point, meta = tng_parse_cutout_to_curve(cutout_path, full, manifest_row["sim"], h5py, np)
            for point, profile_point in zip(curve["points"], per_point):
                point["vDm"] = parse_float(profile_point.get("vDm"))
                point["vStars"] = parse_float(profile_point.get("vStars"))
                point["vBar"] = parse_float(profile_point.get("vBar"))
            for point_row in per_point:
                point_row["manifestRank"] = manifest_row["manifestRank"]
                point_row["routeDiversityTargetBucket"] = manifest_row["routeDiversityTargetBucket"]
                point_row["alreadyInPilot"] = manifest_row["alreadyInPilot"]
            profile_rows.extend(per_point)
            curves.append(curve)
            accepted_manifest_rows.append(manifest_row)
            state_row = tng_route_sample_state_row(curve, manifest_row, meta)
            state_rows.append(state_row)
            inventory["status"] = "accepted"
            inventory["reason"] = "scoreable route-sample target"
            inventory["parserStatus"] = "ok"
            inventory["route"] = curve["route"]
            inventory["lockedRoute"] = curve["lockedModelRoute"]
        except Exception as exc:  # noqa: BLE001 - source-product parser should preserve exact blocker
            inventory["reason"] = "cutout parse failed"
            inventory["parserStatus"] = f"parse-error:{exc}"
        inventory_rows.append(inventory)

    variant_rows, variant_case_rows, _shape_rows, _leff_rows = tng_state_audit_evaluate_variants(curves)
    v21_candidate, v21_safety, v21_status = tng_load_v21_candidate()
    v21_score_row = tng_route_sample_v21_score(curves, v21_candidate, v21_safety)
    candidate_rows, null_rows = tng_route_sample_split_scores(variant_rows, v21_score_row)
    manifest_by_name = {f"{row['sim']}_subhalo_{row['subhaloId']}": row for row in accepted_manifest_rows}
    case_rows = tng_route_sample_wide_case_ledger(curves, manifest_by_name, v21_candidate, v21_safety)
    route_rows = tng_route_sample_route_summary(curves, manifest_rows, accepted_manifest_rows)
    skipped_rows = [row for row in inventory_rows if row.get("status") != "accepted"]
    verdict, failures, decision_metrics, next_rows = tng_route_sample_verdict(curves, variant_rows)
    baseline = baseline_summary(build_curves())
    capsule = {
        "mode": "tngroutesamplepilot",
        "createdUtc": "deterministic",
        "verdict": verdict,
        "guardrailFailures": failures,
        "decisionMetrics": {
            **decision_metrics,
            "baselineMean": baseline["baselineMean"],
            "manifestRows": len(manifest_rows),
            "acceptedScoreableGalaxies": len(curves),
            "skippedTargets": len(skipped_rows),
            "apiKeyStatus": "not-serialized",
            "apiKeySerialized": False,
            "sourceCache": str(source_cache.resolve()),
            "sourceCacheOnDDrive": str(source_cache).lower().startswith("d:"),
            "manifestPath": str(manifest_path.resolve()),
            "cutoutSizeCapBytes": TNG_MAX_CUTOUT_BYTES,
            "hdf5DependencyStatus": deps_status,
            "v21FormulaStatus": v21_status,
            "canonicalMtsPromoted": False,
            "v21Promoted": False,
        },
        "rules": {
            "evidenceTier": "simulation-only mechanism evidence",
            "observationalValidation": False,
            "noFrameworkPromotion": True,
            "noV21Promotion": True,
            "manifestOnlyCutouts": True,
            "apiKeyStoredInArtifacts": False,
        },
    }
    write_csv(out_dir / "mts_tng_route_sample_inventory.csv", inventory_rows)
    write_csv(out_dir / "mts_tng_route_sample_fetch_inventory.csv", fetch_rows)
    write_csv(out_dir / "mts_tng_route_sample_profiles.csv", profile_rows)
    write_csv(out_dir / "mts_tng_route_sample_state_ledger.csv", state_rows)
    write_csv(out_dir / "mts_tng_route_sample_route_summary.csv", route_rows)
    write_csv(out_dir / "mts_tng_route_sample_candidate_scores.csv", candidate_rows)
    write_csv(out_dir / "mts_tng_route_sample_null_controls.csv", null_rows)
    write_csv(out_dir / "mts_tng_route_sample_case_ledger.csv", case_rows)
    write_csv(out_dir / "mts_tng_route_sample_skipped_targets.csv", skipped_rows)
    lines = [
        "# MTS v22.3 TNG Route-Sample Pilot",
        "",
        f"Verdict: **{verdict}**",
        "",
        "This is simulation-only mechanism evidence. It is not observational validation and cannot promote canonical MTS or v21.",
        "",
        "## Facts",
        "",
        f"- Manifest rows: `{len(manifest_rows)}`",
        f"- Accepted scoreable simulated galaxies: `{len(curves)}`",
        f"- Locked low-load count: `{decision_metrics['lockedLowLoadCount']}`",
        f"- Observed low-load count: `{decision_metrics['observedLowLoadCount']}`",
        f"- Support-specificity verdict: `{decision_metrics['supportSpecificityVerdict']}`",
        f"- SPARC locked baseline mean: `{fmt(baseline['baselineMean'])}`",
        f"- Source cache on D: `{capsule['decisionMetrics']['sourceCacheOnDDrive']}`",
        f"- API key serialized: `False`",
        "",
        "## Candidate Scores",
        "",
        "| Candidate | Count | Mean RMSE | Gain vs baryon-only | Shape RMSE |",
        "| --- | ---: | ---: | ---: | ---: |",
    ]
    for row in candidate_rows:
        lines.append(
            f"| {row['variantId']} | {row['galaxyCount']} | {fmt(row['meanRmse'])} | {fmt(row.get('meanGainPctVsBaryonOnly'))}% | {fmt(row.get('meanSupportShapeRmse'), 4)} |"
        )
    lines.extend(["", "## Null Controls", "", "| Null | Count | Mean RMSE | Gain vs baryon-only | Shape RMSE |", "| --- | ---: | ---: | ---: | ---: |"])
    for row in null_rows:
        lines.append(
            f"| {row['variantId']} | {row['galaxyCount']} | {fmt(row['meanRmse'])} | {fmt(row.get('meanGainPctVsBaryonOnly'))}% | {fmt(row.get('meanSupportShapeRmse'), 4)} |"
        )
    lines.extend(["", "## Route Summary", "", "| Group | Scoreable | Locked low-load | Observed low-load |", "| --- | ---: | ---: | ---: |"])
    for row in route_rows:
        if row["summaryType"] == "manifest-bucket":
            lines.append(f"| {row['group']} | {row['scoreableCount']} | {row['lockedLowLoadCount']} | {row['observedLowLoadCount']} |")
    lines.extend(["", "## Guardrail Notes", ""])
    lines.extend([f"- {failure}" for failure in failures] or ["- none"])
    lines.extend(["", "## Next Action", "", f"- `{next_rows[0]['nextMode']}`: {next_rows[0]['reason']}"])
    (out_dir / "mts_tng_route_sample_report.md").write_text("\n".join(lines), encoding="utf-8")
    (out_dir / "mts_tng_route_sample_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_tngroutesamplepilot(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_TNG_ROUTE_SAMPLE_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    source_cache = Path(args.source_cache) if args.source_cache else DEFAULT_TNG_SOURCE_CACHE
    manifest_path = tng_route_sample_manifest_path(args)
    capsule = write_tng_route_sample_artifacts(out_dir, source_cache, manifest_path, args.offline)
    metrics = capsule["decisionMetrics"]
    print("MTS TNG route-sample pilot v4: simulation-only")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"manifest={metrics['manifestRows']}",
                f"scoreable={metrics['acceptedScoreableGalaxies']}",
                f"lowload={metrics['anyLowLoadCount']}",
                f"support={metrics['supportSpecificityVerdict']}",
                f"v21_promoted={metrics['v21Promoted']}",
            ]
        )
    )
    print(f"Wrote TNG route-sample pilot to {out_dir.resolve()}")


