def observed_file_type(path: Path) -> str:
    suffix = path.suffix.lower().lstrip(".")
    return suffix or "unknown"


def observed_row_count(path: Path) -> str:
    if not path.exists():
        return ""
    if path.suffix.lower() == ".csv":
        return str(len(read_csv_rows(path)))
    if path.suffix.lower() == ".json":
        data = read_json_if_exists(path)
        if isinstance(data, list):
            return str(len(data))
        if isinstance(data, dict):
            return str(len(data))
    return ""


def observed_text_headline(path: Path) -> str:
    if not path.exists() or path.suffix.lower() not in {".md", ".txt"}:
        return ""
    text = path.read_text(encoding="utf-8", errors="replace")
    for pattern in [
        r"(?im)^\s*(?:final\s+)?verdict\s*[:=]\s*`?([^`\n]+)`?",
        r"(?im)^\s*-\s*verdict\s*[:=]\s*`?([^`\n]+)`?",
        r"(?im)^#\s+(.+)$",
    ]:
        match = re.search(pattern, text)
        if match:
            return match.group(1).strip().strip(".")
    return ""


def observed_source_ledger(specs: list[dict]) -> list[dict]:
    rows = []
    for spec in specs:
        path = Path(spec["path"])
        headline = spec.get("headlineOverride") or observed_text_headline(path)
        rows.append(
            {
                "stage": spec["stage"],
                "path": str(path.resolve()) if path.exists() else str(path),
                "fileType": observed_file_type(path),
                "exists": path.exists(),
                "rowCount": observed_row_count(path),
                "sha256": file_sha256(path) if path.exists() else "",
                "headlineOrVerdict": headline,
                "reasonIncluded": spec["reason"],
            }
        )
    return rows


def observed_finish_baseline_facts(curves: list[dict]) -> dict:
    baseline = baseline_summary(curves)
    clean_capsule = read_json_if_exists(OUTPUT_PACK_ROOT / "mts-clean-set-validation" / "mts_clean_set_validation_capsule.json")
    decision_capsule = read_json_if_exists(
        OUTPUT_PACK_ROOT / "mts-clean-framework-decision-pack-v1" / "mts_clean_framework_decision_capsule.json"
    )
    summary = clean_capsule.get("summary", {})
    decision_facts = decision_capsule.get("baselineFacts", {})
    weak_count = int(summary.get("weakHoldoutCount") or decision_facts.get("weakSystematicsHoldoutCount") or 0)
    anatomy_rows = read_csv_rows(OUTPUT_PACK_ROOT / "mts-clean-failure-anatomy" / "mts_clean_failure_anatomy.csv")
    return {
        "allGalaxyLockedMtsMeanRmse": float(summary.get("allMeanMtsRmse") or baseline.get("baselineMean") or 0.0),
        "cleanSetLockedMtsMeanRmse": float(summary.get("cleanMeanMtsRmse") or decision_facts.get("cleanSetLockedMtsMeanRmse") or 0.0),
        "cleanSetLockedBaryonMeanRmse": float(summary.get("cleanMeanBaryonRmse") or 0.0),
        "cleanCount": int(summary.get("cleanValidationCount") or decision_facts.get("cleanCount") or 0),
        "weakSystematicsHoldoutCount": weak_count,
        "cleanAnatomySetCount": len(anatomy_rows) or int(decision_facts.get("cleanAnatomyCount") or 0),
        "promotedClosureCandidates": int(decision_capsule.get("promotedClosureCandidates") or 0),
        "weakSystematicsLeakage": int(decision_facts.get("weakSystematicsLeakage") or 0),
        "sourceCleanCapsule": str((OUTPUT_PACK_ROOT / "mts-clean-set-validation" / "mts_clean_set_validation_capsule.json").resolve()),
        "sourceDecisionCapsule": str(
            (OUTPUT_PACK_ROOT / "mts-clean-framework-decision-pack-v1" / "mts_clean_framework_decision_capsule.json").resolve()
        ),
    }


