def observed_markdown_table(rows: list[dict], columns: list[str]) -> list[str]:
    lines = ["| " + " | ".join(columns) + " |", "| " + " | ".join("---" for _ in columns) + " |"]
    for row in rows:
        cells = []
        for column in columns:
            value = str(row.get(column, ""))
            value = value.replace("\n", " ").replace("|", "\\|")
            cells.append(value)
        lines.append("| " + " | ".join(cells) + " |")
    return lines


def write_observed_finish_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    curves = build_curves()
    facts = observed_finish_baseline_facts(curves)
    source_rows = observed_source_ledger(observed_finish_source_specs())
    claims = observed_claims_rows(facts)
    evidence = observed_evidence_chain_rows(facts)
    candidates = observed_candidate_status_rows()
    limitations = observed_limitations_rows()
    figures = observed_figures_tables_rows()
    next_actions = observed_next_actions_rows()
    missing_sources = [row for row in source_rows if not row["exists"]]
    verdict = "framework ready for cautious write-up"
    clean_mean_ok = round(facts["cleanSetLockedMtsMeanRmse"], 2) == 19.33
    all_mean_ok = round(facts["allGalaxyLockedMtsMeanRmse"], 2) == 21.90
    if missing_sources or not clean_mean_ok or not all_mean_ok:
        verdict = "framework needs one more observed validation pass"
    if facts["promotedClosureCandidates"] != 0:
        verdict = "evidence chain inconsistent"

    write_csv(out_dir / "mts_observed_claims_ledger.csv", claims)
    write_csv(out_dir / "mts_observed_evidence_chain.csv", evidence)
    write_csv(out_dir / "mts_observed_candidate_status.csv", candidates)
    write_csv(out_dir / "mts_observed_limitations.csv", limitations)
    write_csv(out_dir / "mts_observed_figures_tables_manifest.csv", figures)
    write_csv(out_dir / "mts_observed_next_actions.csv", next_actions)

    report_lines = [
        "# MTS Observed Framework Finish Pack v1",
        "",
        "## Purpose",
        "",
        "This is an observed-data synthesis pack. It does not run a new fit, does not promote v21, and does not change canonical MTS.",
        "",
        "Canonical MTS remains locked at the current framework baseline.",
        "",
        "## Locked Baseline Facts",
        "",
        f"- All-galaxy locked-MTS mean RMSE: `{fmt(facts['allGalaxyLockedMtsMeanRmse'])}`.",
        f"- Clean-set locked-MTS mean RMSE: `{fmt(facts['cleanSetLockedMtsMeanRmse'])}`.",
        f"- Clean validation count: `{facts['cleanCount']}`.",
        f"- Weak/systematics holdout count: `{facts['weakSystematicsHoldoutCount']}`.",
        f"- Clean high-RMSE anatomy count: `{facts['cleanAnatomySetCount']}`.",
        f"- Promoted closure candidates: `{facts['promotedClosureCandidates']}`.",
        "",
        "## Framework Position",
        "",
        "The claim-safe position is to write canonical MTS as the locked observed-data framework result, with weak/systematics galaxies held out and clean high-RMSE cases presented as residual anatomy.",
        "",
        "The v21 memory-stretch branch remains useful anatomy, but it is not a canonical update because the hardening chain left protected-case and null-control failures.",
        "",
        "External LITTLE THINGS work remains proxy/manual sensitivity evidence, not SPARC-equivalent validation. TNG remains simulation-only mechanism context, not observed validation.",
        "",
        "## Paper-Ready Findings",
        "",
        "- Canonical MTS reproduces the locked all-galaxy baseline and clean-set baseline from prior outputs.",
        "- The clean/weak split is part of the framework evidence: 15 weak/systematics galaxies stay excluded from transport-law fitting.",
        "- The remaining clean high-RMSE cases have structured diagnostic anatomy, but the tested closure branches did not pass promotion guardrails.",
        "- v21 memory-boundary stretch is a serious future-work clue, not a current law.",
        "- External observed follow-up needs real radial baryonic component tables before it can become full MTS validation.",
        "",
        "## Do Not Overclaim",
        "",
        "- Do not claim q, amplitude, scalar, residual-mode, or v21 threshold branches are canonical.",
        "- Do not use weak/systematics cases as transport-law fitting evidence.",
        "- Do not treat LITTLE THINGS proxy/manual component rows as SPARC-equivalent.",
        "- Do not treat TNG as observational validation.",
        "- Do not make broad cosmology claims from this pack.",
        "",
        "## Evidence Chain",
        "",
    ]
    report_lines.extend(observed_markdown_table(evidence, ["stage", "status", "keyFact", "claimUse"]))
    report_lines.extend(["", "## Candidate Status", ""])
    report_lines.extend(observed_markdown_table(candidates, ["candidate", "mechanismType", "status", "result", "canBeUsedAsTransportLaw"]))
    report_lines.extend(["", "## Limitations", ""])
    report_lines.extend(observed_markdown_table(limitations, ["limitation", "status", "reason"]))
    report_lines.extend(["", "## Source Provenance", ""])
    report_lines.extend(observed_markdown_table(source_rows, ["stage", "path", "fileType", "rowCount", "exists", "sha256", "reasonIncluded"]))
    report_lines.extend(["", f"Final verdict: **{verdict}**."])
    (out_dir / "mts_observed_finish_report.md").write_text("\n".join(report_lines), encoding="utf-8")

    paper_lines = [
        "# MTS Observed Paper Sections",
        "",
        "## Current Framework Result",
        "",
        f"Canonical MTS is retained as the locked baseline. Across the full SPARC set the locked mean RMSE is {fmt(facts['allGalaxyLockedMtsMeanRmse'])} km/s; on the 160-galaxy clean validation subset the locked mean RMSE is {fmt(facts['cleanSetLockedMtsMeanRmse'])} km/s.",
        "",
        "## Clean / Weak Split",
        "",
        f"The analysis separates {facts['weakSystematicsHoldoutCount']} weak/systematics galaxies from transport-law fitting. These cases remain protected because their residuals may be dominated by observational or modelling systematics rather than framework behavior.",
        "",
        "## Residual Anatomy",
        "",
        f"The clean high-RMSE anatomy set contains {facts['cleanAnatomySetCount']} galaxies. Diagnostic repairs show structure in these failures, but the local oracles and threshold branches are not promoted as laws.",
        "",
        "## Candidate Branches",
        "",
        "The q, amplitude, scalar, residual-mode, boundary-release, and v21 memory-stretch searches are retained as diagnostic evidence. None becomes canonical because promotion guardrails were not passed.",
        "",
        "## External and Simulation Checks",
        "",
        "LITTLE THINGS proxy/manual reconstructions and TNG sandbox runs are useful side evidence. They are not SPARC-equivalent observed validation and do not promote v21.",
        "",
        "## Limitations",
        "",
        "The unresolved framework-facing question is route/boundary behavior in the clean high-RMSE subset. External validation requires real radial baryonic component data rather than proxy or manual reconstruction.",
        "",
    ]
    (out_dir / "mts_observed_paper_sections.md").write_text("\n".join(paper_lines), encoding="utf-8")

    capsule = {
        "analysisName": "mts-observed-framework-finish-pack-v1",
        "canonicalMtsChanged": False,
        "diagnosticOnly": True,
        "networkFetch": False,
        "verdict": verdict,
        "baselineFacts": facts,
        "guardrails": {
            "v21CanonicalOrPromoted": False,
            "tngSimulationOnly": True,
            "littleThingsSparcEquivalent": False,
            "weakSystematicsExcludedFromTransportFitting": True,
            "qAmplitudeResidualRmseNameFormulaInput": False,
        },
        "missingSources": missing_sources,
        "sourceFiles": source_rows,
        "outputFiles": [
            "mts_observed_finish_report.md",
            "mts_observed_paper_sections.md",
            "mts_observed_claims_ledger.csv",
            "mts_observed_evidence_chain.csv",
            "mts_observed_candidate_status.csv",
            "mts_observed_limitations.csv",
            "mts_observed_figures_tables_manifest.csv",
            "mts_observed_next_actions.csv",
            "mts_observed_finish_capsule.json",
        ],
    }
    (out_dir / "mts_observed_finish_capsule.json").write_text(
        json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8"
    )
    return capsule


def cmd_observedfinishpack(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_OBSERVED_FINISH_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_observed_finish_artifacts(out_dir)
    facts = capsule["baselineFacts"]
    print("MTS observed framework finish pack v1")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"baseline={fmt(facts['allGalaxyLockedMtsMeanRmse'])}",
                f"clean={fmt(facts['cleanSetLockedMtsMeanRmse'])}",
                f"weak={facts['weakSystematicsHoldoutCount']}",
                f"anatomy={facts['cleanAnatomySetCount']}",
                f"promoted_closure={facts['promotedClosureCandidates']}",
            ]
        )
    )
    print(f"Wrote observed finish pack to {out_dir.resolve()}")


