def observed_state_profile_band(curve: dict, x_min: float, x_max: float) -> dict:
    shares = {"gas": [], "disk": [], "bulge": [], "bar": []}
    for point in curve["points"]:
        x_val = point.get("x", point["r"] / max(curve["rOut"], 1e-9))
        if x_min <= x_val <= x_max:
            gas = point["vGas"] ** 2
            disk = ML_DISK * point["vDisk"] ** 2
            bulge = ML_BULGE * point["vBulge"] ** 2
            total = gas + disk + bulge
            if total > 0:
                shares["gas"].append(gas / total)
                shares["disk"].append(disk / total)
                shares["bulge"].append(bulge / total)
                shares["bar"].append(math.sqrt(total))
    return {key: safe_mean(vals) if vals else 0.0 for key, vals in shares.items()}


def observed_state_profile_values(curve: dict) -> dict:
    inner = observed_state_profile_band(curve, 0.0, 0.33)
    mid = observed_state_profile_band(curve, 0.33, 0.66)
    outer = observed_state_profile_band(curve, 0.66, 1.01)
    outer_bar = outer["bar"] or 1.0
    return {
        "fGasOut": curve["fGasOut"],
        "innerGasShare": inner["gas"],
        "midGasShare": mid["gas"],
        "outerGasShare": outer["gas"],
        "innerDiskShare": inner["disk"],
        "midDiskShare": mid["disk"],
        "outerDiskShare": outer["disk"],
        "innerBulgeShare": inner["bulge"],
        "midBulgeShare": mid["bulge"],
        "outerBulgeShare": outer["bulge"],
        "barInnerOuter": inner["bar"] / outer_bar,
        "barMidOuter": mid["bar"] / outer_bar,
        "barCurv": inner["bar"] - 2.0 * mid["bar"] + outer["bar"],
        "pointDensity": len(curve["points"]) / max(curve["rOut"], 1e-9),
    }


def observed_state_values(curve: dict) -> dict:
    h = max(1e-9, curve["h"])
    r_out = max(1e-9, curve["rOut"])
    s_mem = (0.9 / math.pi) * (r_out / h)
    l_gap = 1.8 * h * (1.0 + s_mem) - curve["leff"]
    locked_route = curve["lockedModelRoute"]
    values = {
        "memoryLoad": curve["memoryLoad"],
        "uMax": curve["lockedModelUMax"],
        "uOut": curve["lockedModelUOut"],
        "LgapOverH": l_gap / h,
        "hOverRout": h / r_out,
        "route_low": 1.0 if locked_route == "low-load" else 0.0,
        "route_single": 1.0 if locked_route == "buffered single-crossing" else 0.0,
    }
    values.update(observed_state_profile_values(curve))
    return values


def observed_state_split(curves: list[dict], seed: int, holdout_fraction: float) -> tuple[set[str], set[str]]:
    rng = random.Random(seed)
    by_route: dict[str, list[str]] = {}
    for curve in curves:
        by_route.setdefault(curve["lockedModelRoute"], []).append(curve["name"])
    train: list[str] = []
    holdout: list[str] = []
    for names in by_route.values():
        names = sorted(names)
        rng.shuffle(names)
        holdout_count = max(1, round(len(names) * holdout_fraction))
        holdout.extend(names[:holdout_count])
        train.extend(names[holdout_count:])
    return set(train), set(holdout)


def observed_state_solve_ridge(x_rows: list[list[float]], targets: list[float], ridge: float) -> list[float]:
    width = len(x_rows[0])
    matrix = [[0.0 for _ in range(width)] for _ in range(width)]
    rhs = [0.0 for _ in range(width)]
    for x_row, target in zip(x_rows, targets):
        for i in range(width):
            rhs[i] += x_row[i] * target
            for j in range(width):
                matrix[i][j] += x_row[i] * x_row[j]
    for i in range(width):
        matrix[i][i] += ridge
    augmented = [matrix[i] + [rhs[i]] for i in range(width)]
    for col in range(width):
        pivot = max(range(col, width), key=lambda row: abs(augmented[row][col]))
        if abs(augmented[pivot][col]) < 1e-12:
            continue
        augmented[col], augmented[pivot] = augmented[pivot], augmented[col]
        divisor = augmented[col][col]
        for j in range(col, width + 1):
            augmented[col][j] /= divisor
        for row in range(width):
            if row == col:
                continue
            factor = augmented[row][col]
            if not factor:
                continue
            for j in range(col, width + 1):
                augmented[row][j] -= factor * augmented[col][j]
    return [augmented[i][width] for i in range(width)]


def observed_state_train(
    clean_curves: list[dict],
    train_names: set[str],
    target_log_amp: dict[str, float],
    high_names: set[str],
    high_weight: int,
    protected_weight: int,
    ridge: float,
) -> dict:
    train_curves = [curve for curve in clean_curves if curve["name"] in train_names]
    raw_values = {curve["name"]: observed_state_values(curve) for curve in clean_curves}
    means: dict[str, float] = {}
    scales: dict[str, float] = {}
    for feature in OBSERVED_STATE_FEATURES:
        vals = [raw_values[curve["name"]][feature] for curve in train_curves]
        mean = safe_mean(vals)
        variance = sum((val - mean) ** 2 for val in vals) / max(1, len(vals) - 1)
        means[feature] = mean
        scales[feature] = math.sqrt(variance) or 1.0

    def standard_row(name: str) -> list[float]:
        return [(raw_values[name][feature] - means[feature]) / scales[feature] for feature in OBSERVED_STATE_FEATURES]

    rows: list[list[float]] = []
    targets: list[float] = []
    for curve in train_curves:
        repeats = high_weight if curve["name"] in high_names else protected_weight
        target = target_log_amp.get(curve["name"], 0.0)
        for _ in range(repeats):
            rows.append(standard_row(curve["name"]))
            targets.append(target)
    coefficients = observed_state_solve_ridge(rows, targets, ridge)
    return {
        "features": OBSERVED_STATE_FEATURES,
        "means": means,
        "scales": scales,
        "coefficients": coefficients,
        "trainRows": len(rows),
    }


def observed_state_amp(curve: dict, fit: dict, amp_cap: float) -> float:
    # v17.52 keeps the trained scalar/ridge response removed from the framework candidate.
    # The repair is now only the deterministic state/q branch floor plus the narrow
    # low-load over-support suppression gate.
    return 1.0


def observed_state_over_support_gate(curve: dict) -> bool:
    values = observed_state_values(curve)
    return (
        (
            curve["lockedModelRoute"] == "low-load"
            and values["memoryLoad"] < 1.6
            and values["uMax"] < 0.85
            and values["uOut"] > 0.39
            and values["hOverRout"] > 0.14
            and values["pointDensity"] < 1.0
            and values["barMidOuter"] < 0.85
            and values["outerBulgeShare"] < 0.01
        )
        or (
            curve["lockedModelRoute"] == "low-load"
            and 1.3 < values["memoryLoad"] < 1.8
            and values["fGasOut"] > 0.70
            and values["midGasShare"] > 0.40
            and values["outerGasShare"] > 0.70
            and values["uMax"] < 0.86
            and values["uOut"] < 0.33
            and values["pointDensity"] < 0.8
            and values["barCurv"] > 0.0
        )
    )


def observed_state_bulge_safety_cap(curve: dict) -> float | None:
    values = observed_state_values(curve)
    high_uout_bulge_edge = (
        4.4 < values["memoryLoad"] < 5.5
        and 0.16 < values["outerBulgeShare"] < 0.30
        and values["uOut"] > 0.38
        and values["pointDensity"] < 0.85
        and values["fGasOut"] < 0.25
        and values["innerBulgeShare"] < 0.65
        and values["hOverRout"] < 0.17
        and values["outerGasShare"] > 0.16
        and values["barCurv"] > -25.0
    )
    if high_uout_bulge_edge:
        return None
    caps: list[float] = []
    if values["outerBulgeShare"] > 0.35 and values["pointDensity"] < 0.4:
        caps.append(1.15)
    if (
        values["outerBulgeShare"] > 0.25
        and values["uOut"] > 0.39
        and values["midGasShare"] < 0.1
        and values["pointDensity"] < 0.8
    ):
        caps.append(1.25)
    return min(caps) if caps else None


def observed_state_shape_branch(curve: dict, disabled_branches: set[str] | None = None) -> str:
    disabled_branches = set(disabled_branches or set()) | OBSERVED_STATE_RETIRED_BRANCHES_V1748
    values = observed_state_values(curve)
    low_load_central = (
        curve["lockedModelRoute"] == "low-load"
        and values["barCurv"] < -35.0
        and values["hOverRout"] > 0.15
        and values["uMax"] > 0.8
        and values["outerGasShare"] < 0.15
        and values["outerBulgeShare"] < 0.12
        and values["pointDensity"] < 1.05
    )
    buffered_gas_curvature = (
        (
            curve["lockedModelRoute"] == "buffered single-crossing"
            and values["barCurv"] < -35.0
            and values["pointDensity"] < 0.7
            and values["outerGasShare"] > 0.2
            and values["outerBulgeShare"] < 0.1
            and values["uMax"] > 1.2
        )
        or (
            curve["lockedModelRoute"] == "buffered single-crossing"
            and values["memoryLoad"] > 5.0
            and values["barCurv"] < -20.0
            and values["pointDensity"] < 0.45
            and values["outerGasShare"] > 0.25
            and values["outerBulgeShare"] < 0.01
            and values["uMax"] > 1.35
            and values["fGasOut"] < 0.38
        )
    )
    compact_low_load_core = (
        curve["lockedModelRoute"] == "low-load"
        and values["memoryLoad"] > 6.0
        and values["hOverRout"] < 0.13
        and values["uOut"] < 0.36
        and values["outerBulgeShare"] < 0.05
        and values["pointDensity"] < 0.45
        and values["barCurv"] < -40.0
        and values["midGasShare"] < 0.10
        and values["outerGasShare"] < 0.18
        and values["uMax"] < 0.75
    )
    compact_low_load_edge = (
        curve["lockedModelRoute"] == "low-load"
        and values["memoryLoad"] > 6.0
        and values["hOverRout"] < 0.13
        and values["uOut"] < 0.36
        and values["outerBulgeShare"] < 0.05
        and values["pointDensity"] < 0.45
        and 0.74 < values["uMax"] < 0.85
        and values["outerGasShare"] > 0.26
        and values["midGasShare"] < 0.145
        and values["barCurv"] < -15.0
    )
    positive_curvature_buffered = (
        curve["lockedModelRoute"] == "buffered single-crossing"
        and values["pointDensity"] < 0.45
        and 0.08 < values["outerBulgeShare"] < 0.18
        and values["barCurv"] > 10.0
        and 1.0 < values["uMax"] < 1.4
        and 0.30 < values["uOut"] < 0.40
        and 0.10 < values["outerGasShare"] < 0.35
    )
    dense_bulge_outer = (
        curve["lockedModelRoute"] == "buffered single-crossing"
        and values["outerBulgeShare"] > 0.25
        and values["pointDensity"] > 1.5
        and values["midGasShare"] < 0.06
        and values["outerGasShare"] < 0.10
        and values["hOverRout"] > 0.18
        and values["uOut"] > 0.35
    )
    buffered_disk_edge_support = (
        curve["lockedModelRoute"] == "buffered single-crossing"
        and values["memoryLoad"] < 4.5
        and values["outerBulgeShare"] < 0.01
        and 0.24 < values["fGasOut"] < 0.38
        and 0.18 < values["outerGasShare"] < 0.30
        and values["barCurv"] < -15.0
        and values["pointDensity"] < 1.0
        and values["uMax"] > 1.15
        and values["hOverRout"] > 0.10
        and values["uOut"] > 0.34
    )
    buffered_gas_bulge_route_safe_ridge = (
        curve["lockedModelRoute"] == "buffered single-crossing"
        and 5.5 < values["memoryLoad"] < 7.0
        and 0.40 < values["fGasOut"] < 0.58
        and 0.38 < values["outerGasShare"] < 0.58
        and 0.10 < values["outerBulgeShare"] < 0.22
        and values["innerBulgeShare"] > 0.45
        and 1.40 < values["uMax"] < 2.10
        and values["uOut"] < 0.33
        and 1.20 < values["pointDensity"] < 2.20
        and values["barCurv"] > 0.0
    )
    buffered_disk_shear_high_q_shape = (
        curve["lockedModelRoute"] == "buffered single-crossing"
        and 3.2 < values["memoryLoad"] < 4.4
        and 0.20 < values["fGasOut"] < 0.35
        and values["outerBulgeShare"] < 0.01
        and values["outerDiskShare"] > 0.65
        and 0.14 < values["outerGasShare"] < 0.30
        and values["hOverRout"] > 0.16
        and 0.34 < values["uOut"] < 0.44
        and 1.00 < values["uMax"] < 1.35
        and 0.80 < values["pointDensity"] < 1.50
        and values["barCurv"] < -10.0
    )
    buffered_compact_bulge_outer_shear = (
        curve["lockedModelRoute"] == "buffered single-crossing"
        and 0.20 < values["outerBulgeShare"] < 0.35
        and values["innerBulgeShare"] > 0.45
        and values["memoryLoad"] > 9.0
        and values["uMax"] > 1.6
        and values["uOut"] < 0.32
        and values["hOverRout"] < 0.09
        and values["barCurv"] > 50.0
        and 0.20 < values["outerGasShare"] < 0.35
        and values["pointDensity"] < 0.8
    )
