def observed_state_app_formula_variables(curve: dict, point: dict) -> dict:
    h = curve["h"] if math.isfinite(curve.get("h", math.nan)) else max(0.1, curve["rOut"] / 3.9)
    r_out = max(1e-9, curve["rOut"])
    leff = curve["leff"] if math.isfinite(curve.get("leff", math.nan)) else r_out
    s_mem = (0.9 / math.pi) * (r_out / max(h, 1e-9))
    l_sat = 1.8 * h * (1.0 + s_mem)
    l_gap_over_h = (l_sat - leff) / h if h else 0.0
    profile = observed_state_profile_values(curve)
    route_id = curve.get("route", "")
    locked_route_id = curve.get("lockedModelRoute", "")

    def finite(value: float | int | None, fallback: float = 0.0) -> float:
        try:
            val = float(value)
        except (TypeError, ValueError):
            return fallback
        return val if math.isfinite(val) else fallback

    values = {
        "r": point["r"],
        "x": point["r"] / r_out,
        "h": h,
        "rOut": curve["rOut"],
        "fGas": curve.get("fGasOut", 0.0),
        "fGasOut": curve.get("fGasOut", 0.0),
        "leff": leff,
        "memory": curve.get("memoryLoad", r_out / max(h, 1e-9)),
        "q": Q_DEFAULT,
        "gamma0": GAMMA0,
        "rMax": R_MAX,
        "mlDisk": curve.get("mlDisk", ML_DISK),
        "mlBulge": curve.get("mlBulge", ML_BULGE),
        "vGas": point.get("vGas", 0.0),
        "vDisk": point.get("vDisk", 0.0),
        "vBulge": point.get("vBulge", 0.0),
        "vBar": math.sqrt(max(0.0, point.get("bar2", 0.0))),
        "vObs": point.get("vObs", 0.0),
        "uObs": point.get("u", 0.0),
        "u0": curve.get("u0", 0.0),
        "uOut": curve.get("uOut", 0.0),
        "uMax": curve.get("uMax", 0.0),
        "u075": curve.get("u075", 0.0),
        "xCross": curve.get("xCross", 0.0),
        "lockedU0": curve.get("lockedModelU0", 0.0),
        "lockedUOut": curve.get("lockedModelUOut", 0.0),
        "lockedUMax": curve.get("lockedModelUMax", 0.0),
        "lockedU075": curve.get("lockedModelU075", 0.0),
        "lockedXCross": curve.get("lockedModelXCross", 0.0),
        "hOverRout": h / r_out,
        "lGapOverH": l_gap_over_h,
        "leffOverH": leff / h if h else 0.0,
        "routeLow": 1.0 if route_id == "low-load" else 0.0,
        "routeCdc": 1.0 if route_id == "CDC-low-load" else 0.0,
        "routeUpward": 1.0 if route_id == "buffered upward-crossing" else 0.0,
        "routeSingle": 1.0 if route_id == "buffered single-crossing" else 0.0,
        "routeOuterInfeasible": 1.0 if route_id == "outer-infeasible" else 0.0,
        "routeHard": 1.0 if route_id in {"buffered single-crossing", "outer-infeasible"} else 0.0,
        "routeNonLow": 0.0 if route_id in {"low-load", "CDC-low-load"} else 1.0,
        "lockedRouteLow": 1.0 if locked_route_id == "low-load" else 0.0,
        "lockedRouteCdc": 1.0 if locked_route_id == "CDC-low-load" else 0.0,
        "lockedRouteUpward": 1.0 if locked_route_id == "buffered upward-crossing" else 0.0,
        "lockedRouteSingle": 1.0 if locked_route_id == "buffered single-crossing" else 0.0,
        "lockedRouteOuterInfeasible": 1.0 if locked_route_id == "outer-infeasible" else 0.0,
        "lockedRouteHard": 1.0 if locked_route_id in {"buffered single-crossing", "outer-infeasible"} else 0.0,
        "lockedRouteNonLow": 0.0 if locked_route_id in {"low-load", "CDC-low-load"} else 1.0,
        "outerViable": 0.0 if route_id == "outer-infeasible" else 1.0,
        "outerHeadroom": curve.get("outerHeadroom", 0.0),
        "routeMargin": curve.get("routeMargin", 0.0),
        "routeBreakRisk": curve.get("routeBreakRisk", 0.0),
        "pi": math.pi,
        "e": math.e,
    }
    values.update(profile)
    return {key: finite(value) for key, value in values.items()}


def observed_state_browser_formula_supports(curves: list[dict], expression: str) -> dict[tuple[str, int], float]:
    rows: list[dict] = []
    metadata: list[tuple[str, int]] = []
    for curve in curves:
        for index, point in enumerate(curve["points"]):
            rows.append(observed_state_app_formula_variables(curve, point))
            metadata.append((curve["name"], index))
    if not rows:
        return {}
    var_names = sorted({key for row in rows for key in row})
    payload = {"expression": expression, "varNames": var_names, "rows": rows}
    node_script = r"""
const fs = require('fs');
const payload = JSON.parse(fs.readFileSync(0, 'utf8'));
const fns = {
  abs: Math.abs,
  min: Math.min,
  max: Math.max,
  pow: Math.pow,
  exp: Math.exp,
  sqrt: Math.sqrt,
  log: Math.log,
  floor: Math.floor,
  ceil: Math.ceil
};
const varLines = payload.varNames.map((name) => `var ${name} = Number.isFinite(vars.${name}) ? vars.${name} : 0;`).join('\n');
const fnLines = Object.keys(fns).map((name) => `var ${name} = fns.${name};`).join('\n');
const fn = new Function('vars', 'fns', `"use strict";\n${varLines}\n${fnLines}\nreturn (${payload.expression});`);
const out = payload.rows.map((vars) => {
  const value = fn(vars, fns);
  return Number.isFinite(value) ? value : null;
});
process.stdout.write(JSON.stringify(out));
"""
    result = subprocess.run(
        ["node", "-e", node_script],
        input=json.dumps(json_clean(payload)),
        text=True,
        capture_output=True,
        cwd=str(ROOT),
        check=False,
    )
    if result.returncode != 0:
        raise RuntimeError(f"Node formula evaluation failed: {result.stderr.strip()}")
    values = json.loads(result.stdout)
    if len(values) != len(metadata):
        raise RuntimeError("Node formula evaluation returned the wrong number of support values.")
    return {meta: float(value or 0.0) for meta, value in zip(metadata, values)}


def observed_state_score_curve_from_supports(curve: dict, supports: list[float]) -> dict:
    ml_disk = curve.get("mlDisk", ML_DISK)
    ml_bulge = curve.get("mlBulge", ML_BULGE)
    sse = 0.0
    band = {
        "inner": {"sse": 0.0, "n": 0, "bias": 0.0},
        "mid": {"sse": 0.0, "n": 0, "bias": 0.0},
        "outer": {"sse": 0.0, "n": 0, "bias": 0.0},
    }
    worst = {"r": math.nan, "x": math.nan, "residual": 0.0}
    custom_points = []
    for point, support2 in zip(curve["points"], supports):
        support2 = max(0.0, support2)
        model2 = point["bar2"] + support2
        model = math.sqrt(max(0.0, model2))
        residual = model - point["vObs"]
        u = (model2 - ml_disk * point["vDisk"] ** 2 - ml_bulge * point["vBulge"] ** 2) / (
            GAMMA0 * point["r"] * R_MAX
        )
        custom_points.append({**point, "u": u})
        sse += residual * residual
        key = "inner" if point["x"] < 0.33 else ("mid" if point["x"] < 0.66 else "outer")
        band[key]["sse"] += residual * residual
        band[key]["bias"] += residual
        band[key]["n"] += 1
        if abs(residual) > abs(worst["residual"]):
            worst = {"r": point["r"], "x": point["x"], "residual": residual}

    def rmse(key: str) -> float:
        return math.sqrt(band[key]["sse"] / band[key]["n"]) if band[key]["n"] else math.nan

    def bias(key: str) -> float:
        return band[key]["bias"] / band[key]["n"] if band[key]["n"] else math.nan

    candidate_route = route_state(custom_points, curve["rOut"])
    return {
        "rmse": math.sqrt(sse / len(curve["points"])),
        "innerRmse": rmse("inner"),
        "midRmse": rmse("mid"),
        "outerRmse": rmse("outer"),
        "innerBias": bias("inner"),
        "midBias": bias("mid"),
        "outerBias": bias("outer"),
        "worstR": worst["r"],
        "worstX": worst["x"],
        "worstResidual": worst["residual"],
        "candidateRoute": candidate_route["route"],
        "candidateU0": candidate_route["u0"],
        "candidateUOut": candidate_route["uOut"],
        "candidateUMax": candidate_route["uMax"],
        "candidateU075": candidate_route["u075"],
        "candidateXCross": candidate_route["xCross"],
        "candidateDownCrossings": candidate_route["downCrossings"],
        "candidateUpCrossings": candidate_route["upCrossings"],
    }


def observed_state_freeze_audit_rows(
    curves: list[dict],
    weak_names: set[str],
    high_names: set[str],
    fit: dict,
    amp_cap: float,
    expression: str,
) -> tuple[list[dict], list[dict], dict]:
    support_lookup = observed_state_browser_formula_supports(curves, expression)
    rows: list[dict] = []
    for curve in curves:
        supports = [support_lookup[(curve["name"], index)] for index in range(len(curve["points"]))]
        baseline = score_curve(curve)
        python_score = observed_state_score_curve(curve, fit, amp_cap)
        browser_score = observed_state_score_curve_from_supports(curve, supports)
        if curve["name"] in weak_names:
            set_name = "weak/systematics"
        elif curve["name"] in high_names:
            set_name = "clean-anatomy"
        else:
            set_name = "clean-protected"
        python_delta = python_score["rmse"] - baseline["rmse"]
        browser_delta = browser_score["rmse"] - baseline["rmse"]
        app_diff = browser_score["rmse"] - python_score["rmse"]
        route_match = browser_score["candidateRoute"] == python_score["candidateRoute"]
        rows.append(
            {
                "name": curve["name"],
                "set": set_name,
                "lockedRoute": baseline["candidateRoute"],
                "observedRoute": curve["route"],
                "pythonCandidateRoute": python_score["candidateRoute"],
                "browserFormulaRoute": browser_score["candidateRoute"],
                "routeMatch": route_match,
                "baselineRmse": baseline["rmse"],
                "pythonCandidateRmse": python_score["rmse"],
                "browserFormulaRmse": browser_score["rmse"],
                "pythonGainKmS": baseline["rmse"] - python_score["rmse"],
                "browserGainKmS": baseline["rmse"] - browser_score["rmse"],
                "pythonGainPct": pct_improvement(baseline["rmse"], python_score["rmse"]),
                "browserGainPct": pct_improvement(baseline["rmse"], browser_score["rmse"]),
                "pythonRegressionKmS": max(0.0, python_delta),
                "browserRegressionKmS": max(0.0, browser_delta),
                "browserMinusPythonRmse": app_diff,
                "absBrowserMinusPythonRmse": abs(app_diff),
                "formulaMismatch": abs(app_diff) > 1e-6 or not route_match,
                "shapeBranchType": python_score.get("observedStateBranch", ""),
                "amp": python_score.get("observedStateAmp", ""),
                "qValue": python_score.get("observedStateQ", ""),
            }
        )
    regression_rows = [
        row
        for row in rows
        if parse_float(row["pythonRegressionKmS"]) > 1e-9
        or parse_float(row["browserRegressionKmS"]) > 1e-9
        or row["formulaMismatch"]
    ]
    high_rows = [row for row in rows if row["set"] == "clean-anatomy"]
    protected_rows = [row for row in rows if row["set"] != "clean-anatomy"]
    summary = {
        "totalGalaxyCount": len(rows),
        "weakSystematicsCount": sum(1 for row in rows if row["set"] == "weak/systematics"),
        "cleanAnatomyCount": len(high_rows),
        "cleanProtectedCount": sum(1 for row in rows if row["set"] == "clean-protected"),
        "formulaMismatchCount": sum(1 for row in rows if row["formulaMismatch"]),
        "maxAbsBrowserMinusPythonRmse": max((row["absBrowserMinusPythonRmse"] for row in rows), default=0.0),
        "highImprovedCount": sum(1 for row in high_rows if row["pythonGainKmS"] > 0.0),
        "highWorsenedCount": sum(1 for row in high_rows if row["pythonRegressionKmS"] > 1e-9),
        "highStillAbove20Count": sum(1 for row in high_rows if row["pythonCandidateRmse"] >= 20.0),
        "protectedRegressionCount": sum(1 for row in protected_rows if row["pythonRegressionKmS"] > 1e-9),
        "maxProtectedRegressionKmS": max((row["pythonRegressionKmS"] for row in protected_rows), default=0.0),
        "weakRegressionCount": sum(1 for row in rows if row["set"] == "weak/systematics" and row["pythonRegressionKmS"] > 1e-9),
    }
    return rows, regression_rows, summary


def observed_state_seed_result(
    clean_curves: list[dict],
    train_names: set[str],
    holdout_names: set[str],
    target_log_amp: dict[str, float],
    high_names: set[str],
    seed: int,
    mode: str,
    high_weight: int,
    protected_weight: int,
    ridge: float,
    amp_cap: float,
    disabled_branches: set[str] | None = None,
) -> tuple[dict, dict]:
    disabled_branches = disabled_branches or set()
    shuffled_targets = target_log_amp.copy()
    if mode == "shuffled-target-null":
        rng = random.Random(seed + 77)
        values = [shuffled_targets.get(curve["name"], 0.0) for curve in clean_curves if curve["name"] in train_names]
        rng.shuffle(values)
        for curve, value in zip([curve for curve in clean_curves if curve["name"] in train_names], values):
            shuffled_targets[curve["name"]] = value
    fit = observed_state_train(clean_curves, train_names, shuffled_targets, high_names, high_weight, protected_weight, ridge)
    holdout = [curve for curve in clean_curves if curve["name"] in holdout_names]
    amp_by_name = {curve["name"]: observed_state_multiplier(curve, fit, amp_cap, disabled_branches) for curve in holdout}
    if mode == "random-amp-null":
        rng = random.Random(seed + 123)
        amps = list(amp_by_name.values())
        rng.shuffle(amps)
        amp_by_name = {curve["name"]: amp for curve, amp in zip(holdout, amps)}
    forced_branch_by_name: dict[str, str] = {}
    actual_branch_hits = [
        (curve, observed_state_shape_branch(curve, disabled_branches))
        for curve in holdout
        if observed_state_shape_branch(curve, disabled_branches)
    ]
    if mode == "branch-label-shuffle-null" and actual_branch_hits:
        rng = random.Random(seed + 211)
        labels = [branch for _curve, branch in actual_branch_hits]
        rng.shuffle(labels)
        forced_branch_by_name = {curve["name"]: branch for (curve, _old_branch), branch in zip(actual_branch_hits, labels)}
    if mode == "same-active-count-branch-random-null" and actual_branch_hits:
        rng = random.Random(seed + 313)
        available = {curve["name"]: curve for curve in holdout}
        for branch in OBSERVED_STATE_BRANCHES:
            count = sum(1 for _curve, hit in actual_branch_hits if hit == branch)
            if count <= 0:
                continue
            route = observed_state_branch_locked_route(branch)
            eligible = [
                curve
                for curve in available.values()
                if curve["lockedModelRoute"] == route and curve["name"] not in forced_branch_by_name
            ]
            if len(eligible) < count:
                eligible = [curve for curve in available.values() if curve["name"] not in forced_branch_by_name]
            rng.shuffle(eligible)
            for curve in eligible[:count]:
                forced_branch_by_name[curve["name"]] = branch
    high_holdout = [curve for curve in holdout if curve["name"] in high_names]
    protected_holdout = [curve for curve in holdout if curve["name"] not in high_names]

    def mean_rmse(rows: list[dict], scorer: Callable[[dict], dict]) -> float:
        return safe_mean(scorer(curve)["rmse"] for curve in rows)

    def candidate_score(curve: dict) -> dict:
        forced_branch = forced_branch_by_name.get(curve["name"], "")
        if forced_branch:
            return observed_state_score_curve(curve, fit, amp_cap, disabled_branches, forced_branch)
        if mode == "random-amp-null":
            q_value = observed_state_shape_q(curve, disabled_branches)
            score = score_curve_with_params(curve, amp_by_name[curve["name"]], q_value)
            score["observedStateAmp"] = amp_by_name[curve["name"]]
            score["observedStateQ"] = q_value
            score["observedStateBranch"] = observed_state_shape_branch(curve, disabled_branches)
            return score
        return observed_state_score_curve(curve, fit, amp_cap, disabled_branches)

    base_high = mean_rmse(high_holdout, score_curve)
    cand_high = mean_rmse(high_holdout, candidate_score)
    base_clean = mean_rmse(holdout, score_curve)
    cand_clean = mean_rmse(holdout, candidate_score)
    regressions = []
    route_preserved = []
    active_count = 0
    branch_hit_count = 0
    for curve in holdout:
        base = score_curve(curve)
        cand = candidate_score(curve)
        active_count += 1 if cand["observedStateAmp"] > 1.01 else 0
        branch_hit_count += 1 if cand.get("observedStateBranch") else 0
        route_preserved.append(cand["candidateRoute"] == base["candidateRoute"])
        if curve["name"] not in high_names:
            regressions.append(cand["rmse"] - base["rmse"])
    result = {
        "seed": seed,
        "track": mode,
        "trainCount": len(train_names),
        "holdoutCount": len(holdout_names),
        "highHoldoutCount": len(high_holdout),
        "activeHoldoutCount": active_count,
        "branchHitHoldoutCount": branch_hit_count,
        "baselineHighRmse": base_high,
        "candidateHighRmse": cand_high,
        "highGainPct": 100.0 * (base_high - cand_high) / base_high if base_high else math.nan,
        "baselineCleanRmse": base_clean,
        "candidateCleanRmse": cand_clean,
        "cleanGainPct": 100.0 * (base_clean - cand_clean) / base_clean if base_clean else math.nan,
        "maxProtectedRegression": max(regressions) if regressions else 0.0,
        "meanProtectedPositiveRegression": safe_mean(max(0.0, val) for val in regressions) if regressions else 0.0,
        "routePreservation": safe_mean(1.0 if val else 0.0 for val in route_preserved),
    }
    return result, fit


def observed_state_branch_ablation_rows(
    clean_curves: list[dict],
    target_log_amp: dict[str, float],
    high_names: set[str],
    high_weight: int,
    protected_weight: int,
    ridge: float,
    amp_cap: float,
    holdout_fraction: float,
) -> list[dict]:
    rows = []
    full_names = {curve["name"] for curve in clean_curves}
    full_fit = observed_state_train(clean_curves, full_names, target_log_amp, high_names, high_weight, protected_weight, ridge)
    for branch in OBSERVED_STATE_BRANCHES:
        disabled = {branch}
        seed_results = []
        for seed in range(SPLIT_SEED, SPLIT_SEED + 9):
            train_names, holdout_names = observed_state_split(clean_curves, seed, holdout_fraction)
            result, _fit = observed_state_seed_result(
                clean_curves,
                train_names,
                holdout_names,
                target_log_amp,
                high_names,
                seed,
                f"ablation-without-{branch}",
                high_weight,
                protected_weight,
                ridge,
                amp_cap,
                disabled,
            )
            seed_results.append(result)
        branch_curves = [curve for curve in clean_curves if observed_state_shape_branch(curve) == branch]
        high_branch = [curve for curve in branch_curves if curve["name"] in high_names]
        protected_branch = [curve for curve in branch_curves if curve["name"] not in high_names]
        high_gains = []
        protected_gains = []
        protected_regressions = []
        for curve in branch_curves:
            base = score_curve(curve)
            cand = observed_state_score_curve(curve, full_fit, amp_cap)
            if curve["name"] in high_names:
                high_gains.append(base["rmse"] - cand["rmse"])
            else:
                protected_gains.append(base["rmse"] - cand["rmse"])
                protected_regressions.append(cand["rmse"] - base["rmse"])
        rows.append(
            {
                "branch": branch,
                "activeCleanCount": len(branch_curves),
                "activeHighCount": len(high_branch),
                "activeProtectedCount": len(protected_branch),
                "fullActiveHighMeanGainKmS": safe_mean(high_gains),
                "fullActiveProtectedMeanGainKmS": safe_mean(protected_gains),
                "fullProtectedBranchMaxRegression": max(protected_regressions) if protected_regressions else 0.0,
                "ablationMedianHighGainPct": statistics.median(row["highGainPct"] for row in seed_results),
                "ablationMedianCleanGainPct": statistics.median(row["cleanGainPct"] for row in seed_results),
                "ablationMedianRoutePreservation": statistics.median(row["routePreservation"] for row in seed_results),
                "ablationMaxProtectedRegression": max(row["maxProtectedRegression"] for row in seed_results),
                "activeHighNames": "; ".join(curve["name"] for curve in high_branch),
                "activeProtectedNames": "; ".join(curve["name"] for curve in protected_branch),
            }
        )
    return rows


def observed_state_branch_null_rows(
    clean_curves: list[dict],
    target_log_amp: dict[str, float],
    high_names: set[str],
    high_weight: int,
    protected_weight: int,
    ridge: float,
    amp_cap: float,
    holdout_fraction: float,
) -> list[dict]:
    rows = []
    for seed in range(SPLIT_SEED, SPLIT_SEED + 9):
        train_names, holdout_names = observed_state_split(clean_curves, seed, holdout_fraction)
        fit = observed_state_train(clean_curves, train_names, target_log_amp, high_names, high_weight, protected_weight, ridge)
        holdout = [curve for curve in clean_curves if curve["name"] in holdout_names]
        for branch in OBSERVED_STATE_BRANCHES:
            actual = [curve for curve in holdout if observed_state_shape_branch(curve) == branch]
            actual_high = [curve for curve in actual if curve["name"] in high_names]
            actual_protected = [curve for curve in actual if curve["name"] not in high_names]

            def branch_gain(curve: dict, forced: bool = False) -> float:
                base = score_curve(curve)
                cand = (
                    observed_state_score_curve(curve, fit, amp_cap, forced_branch=branch)
                    if forced
                    else observed_state_score_curve(curve, fit, amp_cap)
                )
                return base["rmse"] - cand["rmse"]

            actual_high_gains = [branch_gain(curve) for curve in actual_high]
            actual_protected_regressions = [-branch_gain(curve) for curve in actual_protected]
            route = observed_state_branch_locked_route(branch)
            rng = random.Random(seed + sum(ord(char) for char in branch))
            random_pool = [
                curve
                for curve in holdout
                if curve["lockedModelRoute"] == route and observed_state_shape_branch(curve) != branch
            ]
            rng.shuffle(random_pool)
            random_high = [curve for curve in random_pool if curve["name"] in high_names][: len(actual_high)]
            random_protected = [curve for curve in random_pool if curve["name"] not in high_names][: len(actual_protected)]
            random_high_gains = [branch_gain(curve, forced=True) for curve in random_high]
            random_protected_regressions = [-branch_gain(curve, forced=True) for curve in random_protected]
            actual_pct = pct_improvement(
                safe_mean(score_curve(curve)["rmse"] for curve in actual_high),
                safe_mean(observed_state_score_curve(curve, fit, amp_cap)["rmse"] for curve in actual_high),
            )
            random_pct = pct_improvement(
                safe_mean(score_curve(curve)["rmse"] for curve in random_high),
                safe_mean(observed_state_score_curve(curve, fit, amp_cap, forced_branch=branch)["rmse"] for curve in random_high),
            )
            rows.append(
                {
                    "seed": seed,
                    "branch": branch,
                    "nullType": "same-route-same-active-count",
                    "actualHighCount": len(actual_high),
                    "randomHighCount": len(random_high),
                    "actualProtectedCount": len(actual_protected),
                    "randomProtectedCount": len(random_protected),
                    "actualHighMeanGainKmS": safe_mean(actual_high_gains),
                    "randomHighMeanGainKmS": safe_mean(random_high_gains),
                    "actualHighGainPct": actual_pct,
                    "randomHighGainPct": random_pct,
                    "branchNullMarginPct": actual_pct - random_pct
                    if math.isfinite(actual_pct) and math.isfinite(random_pct)
                    else math.nan,
                    "actualProtectedMaxRegression": max(actual_protected_regressions) if actual_protected_regressions else 0.0,
                    "randomProtectedMaxRegression": max(random_protected_regressions) if random_protected_regressions else 0.0,
                    "actualHighNames": "; ".join(curve["name"] for curve in actual_high),
                    "randomHighNames": "; ".join(curve["name"] for curve in random_high),
                    "randomProtectedNames": "; ".join(curve["name"] for curve in random_protected),
                }
            )
    full_fit = observed_state_train(
        clean_curves,
        {curve["name"] for curve in clean_curves},
        target_log_amp,
        high_names,
        high_weight,
        protected_weight,
        ridge,
    )
    for branch in OBSERVED_STATE_BRANCHES:
        route = observed_state_branch_locked_route(branch)
        protected_pool = [
            curve
            for curve in clean_curves
            if curve["name"] not in high_names
            and curve["lockedModelRoute"] == route
            and observed_state_shape_branch(curve) != branch
        ]
        regressions = []
        for curve in protected_pool:
            base = score_curve(curve)
            forced = observed_state_score_curve(curve, full_fit, amp_cap, forced_branch=branch)
            regressions.append((curve, forced["rmse"] - base["rmse"]))
        regressions.sort(key=lambda item: item[1], reverse=True)
        rows.append(
            {
                "seed": "full",
                "branch": branch,
                "nullType": "protected-lookalike-stress",
                "actualHighCount": "",
                "randomHighCount": "",
                "actualProtectedCount": "",
                "randomProtectedCount": len(protected_pool),
                "actualHighMeanGainKmS": "",
                "randomHighMeanGainKmS": "",
                "actualHighGainPct": "",
                "randomHighGainPct": "",
                "branchNullMarginPct": "",
                "actualProtectedMaxRegression": "",
                "randomProtectedMaxRegression": regressions[0][1] if regressions else 0.0,
                "actualHighNames": "",
                "randomHighNames": "",
                "randomProtectedNames": "; ".join(curve["name"] for curve, regression in regressions[:8] if regression > 0),
            }
        )
    return rows


def observed_state_route_transition_hardening_rows(
    case_rows: list[dict],
    branch_ablation_rows: list[dict],
    branch_null_rows: list[dict],
) -> tuple[list[dict], list[dict]]:
    ledger_rows = []
    null_rows = []
    ablation_by_branch = {row["branch"]: row for row in branch_ablation_rows}
    for branch in sorted(OBSERVED_STATE_ROUTE_TRANSITION_BRANCHES):
        active_rows = [row for row in case_rows if row.get("shapeBranchType") == branch]
        active_high = [row for row in active_rows if row.get("set") in {"clean-anatomy", "clean-high-rmse"}]
        active_protected = [row for row in active_rows if row.get("set") == "clean-protected"]
        transition_high = [row for row in active_high if not parse_bool(row.get("routePreserved"))]
        protected_regressions = [
            -parse_float(row.get("gain"), 0.0)
            for row in active_protected
            if math.isfinite(parse_float(row.get("gain"), math.nan)) and parse_float(row.get("gain"), 0.0) < 0
        ]
        same_route_nulls = [
            row
            for row in branch_null_rows
            if row.get("branch") == branch and row.get("nullType") == "same-route-same-active-count"
        ]
        stress_rows = [
            row
            for row in branch_null_rows
            if row.get("branch") == branch and row.get("nullType") == "protected-lookalike-stress"
        ]
        median_actual_pct = safe_median(parse_float(row.get("actualHighGainPct")) for row in same_route_nulls)
        median_random_pct = safe_median(parse_float(row.get("randomHighGainPct")) for row in same_route_nulls)
        median_margin_pct = safe_median(parse_float(row.get("branchNullMarginPct")) for row in same_route_nulls)
        protected_stress = max(
            [parse_float(row.get("randomProtectedMaxRegression"), 0.0) for row in stress_rows] or [0.0]
        )
        actual_high_mean_gain = safe_mean(parse_float(row.get("gain")) for row in active_high)
        actual_protected_max_regression = max(protected_regressions) if protected_regressions else 0.0
        route_safe_under20 = sum(1 for row in transition_high if parse_bool(row.get("routeSafeCanRepairUnder20")))
        route_safe_unrepairable = sum(
            1 for row in transition_high if parse_bool(row.get("singleQFloorRouteTransitionNeeded"))
        )
        boundary_polish_count = sum(
            1
            for row in transition_high
            if parse_bool(row.get("routeSafeCanRepairUnder20"))
            and parse_float(row.get("bestRouteSafeGain"), math.inf) < 5.0
            and parse_float(row.get("gain"), 0.0) >= 5.0
            and parse_float(row.get("candidateRmse"), math.inf) < 20.0
        )
        boundary_polish_branch = bool(transition_high) and boundary_polish_count == len(transition_high)
        failures = []
        warnings = []
        if not active_high:
            failures.append("no active high-RMSE target")
        if actual_high_mean_gain < (5.0 if boundary_polish_branch else 10.0):
            failures.append(
                "active high gain below 5 km/s"
                if boundary_polish_branch
                else "active high gain below 10 km/s"
            )
        if actual_protected_max_regression > 3.0:
            failures.append("actual protected branch-hit regression above 3 km/s")
        if median_margin_pct < 10.0:
            failures.append("same-route transition null margin below 10 points")
        if protected_stress > 3.0:
            warnings.append("forced protected-lookalike stress above 3 km/s")
        ablation = ablation_by_branch.get(branch, {})
        branch_accepted = parse_bool(ablation.get("branchAccepted"))
        if not branch_accepted:
            failures.append("base branch acceptance failed")
        transition_accepted = not failures
        ledger_rows.append(
            {
                "branch": branch,
                "activeHighCount": len(active_high),
                "transitionHighCount": len(transition_high),
                "activeProtectedCount": len(active_protected),
                "activeHighNames": "; ".join(row["name"] for row in active_high),
                "transitionHighNames": "; ".join(row["name"] for row in transition_high),
                "activeProtectedNames": "; ".join(row["name"] for row in active_protected),
                "actualHighMeanGainKmS": actual_high_mean_gain,
                "actualProtectedMaxRegressionKmS": actual_protected_max_regression,
                "medianSameRouteActualGainPct": median_actual_pct,
                "medianSameRouteRandomGainPct": median_random_pct,
                "medianSameRouteMarginPct": median_margin_pct,
                "protectedLookalikeStressMaxRegressionKmS": protected_stress,
                "routeSafeRepairUnder20Count": route_safe_under20,
                "routeSafeUnrepairableCount": route_safe_unrepairable,
                "boundaryPolishTransitionCount": boundary_polish_count,
                "boundaryPolishBranch": boundary_polish_branch,
                "transitionAccepted": transition_accepted,
                "transitionFailures": "; ".join(failures),
                "transitionWarnings": "; ".join(warnings),
            }
        )
        for row in same_route_nulls:
            null_rows.append(
                {
                    "seed": row["seed"],
                    "branch": branch,
                    "nullType": "same-route-same-active-count",
                    "actualHighGainPct": row["actualHighGainPct"],
                    "randomHighGainPct": row["randomHighGainPct"],
                    "branchNullMarginPct": row["branchNullMarginPct"],
                    "actualHighMeanGainKmS": row["actualHighMeanGainKmS"],
                    "randomHighMeanGainKmS": row["randomHighMeanGainKmS"],
                    "actualHighNames": row["actualHighNames"],
                    "randomHighNames": row["randomHighNames"],
                    "protectedLookalikeStressMaxRegressionKmS": "",
                }
            )
        for row in stress_rows:
            null_rows.append(
                {
                    "seed": row["seed"],
                    "branch": branch,
                    "nullType": "protected-lookalike-stress",
                    "actualHighGainPct": "",
                    "randomHighGainPct": "",
                    "branchNullMarginPct": "",
                    "actualHighMeanGainKmS": "",
                    "randomHighMeanGainKmS": "",
                    "actualHighNames": "",
                    "randomHighNames": row["randomProtectedNames"],
                    "protectedLookalikeStressMaxRegressionKmS": row["randomProtectedMaxRegression"],
                }
            )
    return ledger_rows, null_rows


def observed_state_route_extension_rows(
    case_rows: list[dict],
    route_transition_rows: list[dict],
) -> tuple[list[dict], list[dict]]:
    transition_by_branch = {row["branch"]: row for row in route_transition_rows}
    extension_rows = []
    null_rows = []
    release_rows = [
        row
        for row in case_rows
        if row.get("routeTransition")
        and observed_state_route_extension_label(row.get("shapeBranchType", ""))
    ]
    for row in release_rows:
        branch = row.get("shapeBranchType", "")
        transition = transition_by_branch.get(branch, {})
        failures = []
        if row.get("set") != "clean-anatomy":
            failures.append("not clean-anatomy")
        if not parse_bool(row.get("singleQFloorRouteTransitionNeeded")):
            failures.append("route-safe alternative can repair below 20")
        if not parse_bool(transition.get("transitionAccepted")):
            failures.append("route-transition branch failed hardening")
        if int(transition.get("activeProtectedCount", 0) or 0) > 0:
            failures.append("protected analogue branch hit")
        if parse_float(transition.get("protectedLookalikeStressMaxRegressionKmS"), 0.0) > 3.0:
            failures.append("protected lookalike stress above 3 km/s")
        accepted = not failures
        extension_rows.append(
            {
                "name": row["name"],
                "branch": branch,
                "routeStateExtension": observed_state_route_extension_label(branch),
                "routeTransition": row["routeTransition"],
                "baselineRmse": row["baselineRmse"],
                "candidateRmse": row["candidateRmse"],
                "gain": row["gain"],
                "bestRouteSafeRmse": row.get("bestRouteSafeRmse", ""),
                "bestRouteSafeGain": row.get("bestRouteSafeGain", ""),
                "routeSafeCanRepairUnder20": row.get("routeSafeCanRepairUnder20", ""),
                "singleQFloorRouteTransitionNeeded": row.get("singleQFloorRouteTransitionNeeded", ""),
                "branchTransitionAccepted": transition.get("transitionAccepted", False),
                "branchActiveProtectedCount": transition.get("activeProtectedCount", 0),
                "protectedLookalikeStressMaxRegressionKmS": transition.get(
                    "protectedLookalikeStressMaxRegressionKmS",
                    0.0,
                ),
                "routeStateExtensionAccepted": accepted,
                "routeStateExtensionFailures": "; ".join(failures),
            }
        )

    extension_by_name = {row["name"]: row for row in extension_rows}
    for row in case_rows:
        extension = extension_by_name.get(row["name"])
        row["routeStateExtension"] = extension["routeStateExtension"] if extension else ""
        row["routeStateExtensionAccepted"] = extension["routeStateExtensionAccepted"] if extension else False
        row["routeStateExtensionFailures"] = extension["routeStateExtensionFailures"] if extension else ""

    for branch, label in sorted(OBSERVED_STATE_ROUTE_EXTENSION_LABELS.items()):
        actual = [row for row in extension_rows if row["branch"] == branch and parse_bool(row["routeStateExtensionAccepted"])]
        if not actual:
            continue
        actual_names = {row["name"] for row in actual}
        locked_route = actual[0]["routeTransition"].split(" -> ")[0] if actual[0].get("routeTransition") else ""
        actual_pct = pct_improvement(
            safe_mean(parse_float(row["baselineRmse"]) for row in actual),
            safe_mean(parse_float(row["candidateRmse"]) for row in actual),
        )
        actual_mean_gain = safe_mean(parse_float(row["gain"]) for row in actual)
        same_route_pool = [
            row
            for row in case_rows
            if row.get("set") == "clean-anatomy"
            and row.get("lockedRoute") == locked_route
            and row["name"] not in actual_names
            and not row.get("routeTransition")
        ]
        family = observed_state_branch_family(branch)
        family_pool = [
            row
            for row in same_route_pool
            if observed_state_branch_family(row.get("shapeBranchType", "")) == family
        ]
        pools = [
            ("same-route-random-release-target", same_route_pool),
            ("branch-family-random-release-target", family_pool),
        ]
        for seed in range(SPLIT_SEED, SPLIT_SEED + 9):
            for null_type, pool in pools:
                rng = random.Random(seed + sum(ord(char) for char in branch + null_type))
                shuffled = pool[:]
                rng.shuffle(shuffled)
                selected = shuffled[: len(actual)]
                random_pct = pct_improvement(
                    safe_mean(parse_float(row["baselineRmse"]) for row in selected),
                    safe_mean(parse_float(row["candidateRmse"]) for row in selected),
                )
                random_mean_gain = safe_mean(parse_float(row["gain"]) for row in selected)
                null_rows.append(
                    {
                        "seed": seed,
                        "branch": branch,
                        "routeStateExtension": label,
                        "nullType": null_type,
                        "actualReleaseCount": len(actual),
                        "randomReleaseCount": len(selected),
                        "actualReleaseGainPct": actual_pct,
                        "randomReleaseGainPct": random_pct,
                        "releaseNullMarginPct": actual_pct - random_pct
                        if math.isfinite(actual_pct) and math.isfinite(random_pct)
                        else math.nan,
                        "actualReleaseMeanGainKmS": actual_mean_gain,
                        "randomReleaseMeanGainKmS": random_mean_gain,
                        "actualReleaseNames": "; ".join(row["name"] for row in actual),
                        "randomReleaseNames": "; ".join(row["name"] for row in selected),
                    }
                )
        transition = transition_by_branch.get(branch, {})
        null_rows.append(
            {
                "seed": "full",
                "branch": branch,
                "routeStateExtension": label,
                "nullType": "protected-lookalike-release-stress",
                "actualReleaseCount": len(actual),
                "randomReleaseCount": transition.get("activeProtectedCount", 0),
                "actualReleaseGainPct": "",
                "randomReleaseGainPct": "",
                "releaseNullMarginPct": "",
                "actualReleaseMeanGainKmS": "",
                "randomReleaseMeanGainKmS": "",
                "actualReleaseNames": "; ".join(row["name"] for row in actual),
                "randomReleaseNames": transition.get("activeProtectedNames", ""),
                "protectedLookalikeStressMaxRegressionKmS": transition.get(
                    "protectedLookalikeStressMaxRegressionKmS",
                    0.0,
                ),
            }
        )
    return extension_rows, null_rows


def observed_state_route_legitimacy_rows(
    case_rows: list[dict],
    route_transition_rows: list[dict],
) -> list[dict]:
    transition_by_branch = {row["branch"]: row for row in route_transition_rows}
    rows = []
    for row in case_rows:
        if not row.get("routeTransition"):
            continue
        branch = row.get("shapeBranchType", "")
        transition = transition_by_branch.get(branch, {})
        baseline_route, candidate_route = "", ""
        if " -> " in row.get("routeTransition", ""):
            baseline_route, candidate_route = row["routeTransition"].split(" -> ", 1)
        best_route_safe_rmse = parse_float(row.get("bestRouteSafeRmse"), math.nan)
        candidate_rmse = parse_float(row.get("candidateRmse"), math.nan)
        failures = []
        warnings = []
        if row.get("set") not in {"clean-anatomy", "clean-high-rmse"}:
            failures.append("not clean high-RMSE target")
        if branch not in OBSERVED_STATE_ROUTE_TRANSITION_BRANCHES:
            failures.append("not an explicit route-transition branch")
        if candidate_rmse >= 20.0:
            failures.append("candidate remains above 20 km/s")
        transition_gain_over_same_route = (
            best_route_safe_rmse - candidate_rmse
            if math.isfinite(best_route_safe_rmse) and math.isfinite(candidate_rmse)
            else math.nan
        )
        branch_transition_accepted = parse_bool(transition.get("transitionAccepted"))
        protected_branch_hits = int(transition.get("activeProtectedCount", 0) or 0)
        actual_protected_regression = parse_float(transition.get("actualProtectedMaxRegressionKmS"), 0.0)
        branch_same_route_margin = parse_float(transition.get("medianSameRouteMarginPct"), math.nan)
        best_same_route_gain = parse_float(row.get("bestRouteSafeGain"), math.nan)
        boundary_polish_transition = (
            branch in OBSERVED_STATE_ROUTE_TRANSITION_BRANCHES
            and row.get("set") in {"clean-anatomy", "clean-high-rmse"}
            and parse_bool(row.get("routeSafeCanRepairUnder20"))
            and math.isfinite(best_same_route_gain)
            and best_same_route_gain < 5.0
            and parse_float(row.get("gain"), 0.0) >= 5.0
            and candidate_rmse < 20.0
            and branch_transition_accepted
            and protected_branch_hits == 0
            and actual_protected_regression <= 0.0
            and math.isfinite(branch_same_route_margin)
            and branch_same_route_margin >= 10.0
        )
        if (
            not boundary_polish_transition
            and (not math.isfinite(transition_gain_over_same_route) or transition_gain_over_same_route < 5.0)
        ):
            failures.append("route-transition gain over best same-route counterfactual below 5 km/s")
        if parse_bool(row.get("routeSafeCanRepairUnder20")) and not boundary_polish_transition:
            failures.append("same-route alternative can repair below 20")
        if not parse_bool(row.get("singleQFloorRouteTransitionNeeded")) and not boundary_polish_transition:
            failures.append("route transition not required by same-route counterfactual")
        if not branch_transition_accepted:
            failures.append("branch transition hardening failed")
        if protected_branch_hits > 0:
            failures.append("protected analogue branch hit")
        if actual_protected_regression > 0.0:
            failures.append("actual protected branch regression")
        if branch_same_route_margin < 10.0:
            failures.append("same-route transition null margin below 10 points")
        if parse_float(transition.get("protectedLookalikeStressMaxRegressionKmS"), 0.0) > 3.0:
            warnings.append("forced protected-lookalike stress above 3 km/s")
        legitimacy = (
            "route-transition accepted"
            if not failures and not warnings
            else "route-transition accepted with stress warning"
            if not failures
            else "route-transition rejected"
        )
        rows.append(
            {
                "name": row["name"],
                "branch": branch,
                "set": row.get("set", ""),
                "baselineRoute": baseline_route,
                "candidateRoute": candidate_route,
                "baselineRmse": row.get("baselineRmse", ""),
                "candidateRmse": row.get("candidateRmse", ""),
                "gain": row.get("gain", ""),
                "bestSameRouteRmse": row.get("bestRouteSafeRmse", ""),
                "bestSameRouteGain": row.get("bestRouteSafeGain", ""),
                "routeTransitionGainOverBestSameRoute": transition_gain_over_same_route if math.isfinite(transition_gain_over_same_route) else "",
                "routeSafeCanRepairUnder20": row.get("routeSafeCanRepairUnder20", ""),
                "singleQFloorRouteTransitionNeeded": row.get("singleQFloorRouteTransitionNeeded", ""),
                "branchTransitionAccepted": transition.get("transitionAccepted", False),
                "branchActiveHighCount": transition.get("activeHighCount", 0),
                "branchActiveProtectedCount": transition.get("activeProtectedCount", 0),
                "branchMedianSameRouteMarginPct": transition.get("medianSameRouteMarginPct", ""),
                "branchProtectedLookalikeStressMaxRegressionKmS": transition.get(
                    "protectedLookalikeStressMaxRegressionKmS",
                    0.0,
                ),
                "routeBoundaryPolishAccepted": boundary_polish_transition,
                "routeStateExtension": row.get("routeStateExtension", ""),
                "routeStateExtensionAccepted": row.get("routeStateExtensionAccepted", ""),
                "legitimacy": legitimacy,
                "legitimacyFailures": "; ".join(failures),
                "legitimacyWarnings": "; ".join(warnings),
            }
        )
    return sorted(rows, key=lambda item: (item["legitimacy"], item["name"]))


def observed_state_family_hardening_rows(
    clean_curves: list[dict],
    target_log_amp: dict[str, float],
    high_names: set[str],
    high_weight: int,
    protected_weight: int,
    ridge: float,
    amp_cap: float,
    holdout_fraction: float,
    candidate_median_high_gain: float,
    branch_ablation_rows: list[dict],
) -> list[dict]:
    rows = []
    branch_rows = {row["branch"]: row for row in branch_ablation_rows}
    for family, branches in sorted(OBSERVED_STATE_BRANCH_FAMILIES.items()):
        disabled = set(branches)
        seed_results = []
        for seed in range(SPLIT_SEED, SPLIT_SEED + 9):
            train_names, holdout_names = observed_state_split(clean_curves, seed, holdout_fraction)
            result, _fit = observed_state_seed_result(
                clean_curves,
                train_names,
                holdout_names,
                target_log_amp,
                high_names,
                seed,
                f"family-ablation-without-{family}",
                high_weight,
                protected_weight,
                ridge,
                amp_cap,
                disabled,
            )
            seed_results.append(result)
        family_branch_rows = [branch_rows[branch] for branch in sorted(branches) if branch in branch_rows]
        active_rows = [row for row in family_branch_rows if int(row.get("activeHighCount", 0) or 0) > 0]
        active_high_count = sum(int(row.get("activeHighCount", 0) or 0) for row in family_branch_rows)
        active_protected_count = sum(int(row.get("activeProtectedCount", 0) or 0) for row in family_branch_rows)
        weighted_gain_numer = sum(
            parse_float(row.get("fullActiveHighMeanGainKmS"), 0.0) * int(row.get("activeHighCount", 0) or 0)
            for row in family_branch_rows
        )
        active_high_mean_gain = weighted_gain_numer / active_high_count if active_high_count else math.nan
        branch_margins = [
            parse_float(row.get("medianBranchNullMarginPct"))
            for row in family_branch_rows
            if math.isfinite(parse_float(row.get("medianBranchNullMarginPct")))
        ]
        protected_stress = max(
            [parse_float(row.get("protectedLookalikeStressMaxRegression"), 0.0) for row in family_branch_rows] or [0.0]
        )
        actual_protected_max = max(
            [parse_float(row.get("fullProtectedBranchMaxRegression"), 0.0) for row in family_branch_rows] or [0.0]
        )
        ablation_median_high = statistics.median(row["highGainPct"] for row in seed_results)
        ablation_median_clean = statistics.median(row["cleanGainPct"] for row in seed_results)
        ablation_loss = candidate_median_high_gain - ablation_median_high
        accepted_branch_count = sum(1 for row in family_branch_rows if parse_bool(row.get("branchAccepted")))
        failures = []
        warnings = []
        if active_high_count <= 0:
            warnings.append("no active high-RMSE family hit")
        if active_high_count > 0 and active_high_mean_gain < 5.0:
            failures.append("family active high gain below 5 km/s")
        if actual_protected_max > 3.0:
            failures.append("actual protected family branch-hit regression above 3 km/s")
        if branch_margins and min(branch_margins) < 10.0:
            failures.append("at least one active family branch below 10-point null margin")
        if protected_stress > 3.0:
            warnings.append("forced protected-lookalike stress above 3 km/s")
        rows.append(
            {
                "family": family,
                "branchCount": len(branches),
                "acceptedBranchCount": accepted_branch_count,
                "activeHighCount": active_high_count,
                "activeProtectedCount": active_protected_count,
                "activeBranches": "; ".join(row["branch"] for row in active_rows),
                "activeHighNames": "; ".join(
                    name
                    for row in active_rows
                    for name in str(row.get("activeHighNames", "")).split("; ")
                    if name
                ),
                "activeHighMeanGainKmS": active_high_mean_gain,
                "actualProtectedMaxRegressionKmS": actual_protected_max,
                "medianBranchNullMarginPct": safe_median(branch_margins),
                "minBranchNullMarginPct": min(branch_margins) if branch_margins else math.nan,
                "protectedLookalikeStressMaxRegressionKmS": protected_stress,
                "ablationMedianHighGainPct": ablation_median_high,
                "ablationMedianCleanGainPct": ablation_median_clean,
                "ablationHighGainLossPct": ablation_loss,
                "familyAccepted": not failures,
                "familyFailures": "; ".join(failures),
                "familyWarnings": "; ".join(warnings),
            }
        )
    return rows


def observed_state_score_curve_with_family_q_overrides(curve: dict, family_q_overrides: dict[str, float]) -> dict:
    if observed_state_over_support_gate(curve):
        amp = OBSERVED_STATE_OVER_SUPPORT_AMP
        q_value = Q_DEFAULT
    else:
        amp = 1.0
        q_value = Q_DEFAULT
        branch = observed_state_shape_branch(curve)
        if branch:
            family = observed_state_branch_family(branch)
            q_value = family_q_overrides.get(family, observed_state_branch_q_for_curve(branch, curve))
            floor = observed_state_branch_amp_floor_for_curve(branch, curve)
            if floor is not None:
                amp = max(amp, floor)
        if observed_state_lowload_route_hardening_gate(curve):
            amp = min(amp, 1.0)
        safety_cap = observed_state_bulge_safety_cap(curve)
        if safety_cap is not None:
            amp = min(amp, safety_cap)
    score = score_curve_with_params(curve, amp, q_value)
    score["observedStateAmp"] = amp
    score["observedStateQ"] = q_value
    score["observedStateBranch"] = observed_state_shape_branch(curve)
    return score


def observed_state_full_metrics_for_scorer(
    clean_curves: list[dict],
    high_names: set[str],
    scorer: Callable[[dict], dict],
) -> dict:
    rows = []
    for curve in clean_curves:
        base = score_curve(curve)
        cand = scorer(curve)
        rows.append((curve, base, cand))
    high_rows = [row for row in rows if row[0]["name"] in high_names]
    protected_rows = [row for row in rows if row[0]["name"] not in high_names]
    base_high = safe_mean(row[1]["rmse"] for row in high_rows)
    cand_high = safe_mean(row[2]["rmse"] for row in high_rows)
    base_clean = safe_mean(row[1]["rmse"] for row in rows)
    cand_clean = safe_mean(row[2]["rmse"] for row in rows)
    protected_regressions = [row[2]["rmse"] - row[1]["rmse"] for row in protected_rows]
    return {
        "highGainPct": pct_improvement(base_high, cand_high),
        "cleanGainPct": pct_improvement(base_clean, cand_clean),
        "highStillAbove20": sum(1 for row in high_rows if row[2]["rmse"] >= 20.0),
        "highWorsened": sum(1 for row in high_rows if row[2]["rmse"] > row[1]["rmse"]),
        "maxProtectedRegression": max(protected_regressions) if protected_regressions else 0.0,
        "routePreservation": safe_mean(1.0 if row[2]["candidateRoute"] == row[1]["candidateRoute"] else 0.0 for row in rows),
        "routeChangeCount": sum(1 for row in rows if row[2]["candidateRoute"] != row[1]["candidateRoute"]),
    }


def observed_state_score_curve_with_strength_jitter(
    curve: dict,
    fit: dict,
    amp_cap: float,
    floor_scale: float,
    q_scale: float,
) -> dict:
    if observed_state_over_support_gate(curve):
        amp = OBSERVED_STATE_OVER_SUPPORT_AMP
        q_value = Q_DEFAULT
    else:
        branch = observed_state_shape_branch(curve)
        amp = observed_state_amp(curve, fit, amp_cap)
        if branch:
            floor = observed_state_branch_amp_floor_for_curve(branch, curve)
            if floor is not None:
                amp = max(amp, 1.0 + floor_scale * (floor - 1.0))
            q_base = observed_state_branch_q_for_curve(branch, curve)
            q_value = Q_DEFAULT + q_scale * (q_base - Q_DEFAULT)
        else:
            q_value = Q_DEFAULT
        branch_cap = observed_state_branch_amp_cap(branch)
        if branch_cap is not None:
            amp = min(amp, branch_cap)
        if observed_state_lowload_route_hardening_gate(curve):
            amp = min(amp, 1.0)
        safety_cap = observed_state_bulge_safety_cap(curve)
        if safety_cap is not None:
            amp = min(amp, safety_cap)
    score = score_curve_with_params(curve, amp, q_value)
    score["observedStateAmp"] = amp
    score["observedStateQ"] = q_value
    score["observedStateBranch"] = observed_state_shape_branch(curve)
    return score


def observed_state_candidate_stress_rows(
    clean_curves: list[dict],
    high_names: set[str],
    full_fit: dict,
    amp_cap: float,
    case_rows: list[dict],
    branch_ablation_rows: list[dict],
    family_rows: list[dict],
) -> list[dict]:
    rows = []
    curve_by_name = {curve["name"]: curve for curve in clean_curves}
    case_by_name = {row["name"]: row for row in case_rows}

    def add_metric_row(stress_type: str, target: str, metrics: dict, pass_rule: str) -> None:
        failures = []
        if metrics["highGainPct"] < 60.0:
            failures.append("high gain below 60%")
        if metrics["cleanGainPct"] < 38.0:
            failures.append("clean gain below 38%")
        if metrics["maxProtectedRegression"] > 0.0:
            failures.append("protected regression above 0")
        if metrics["highStillAbove20"] > 0:
            failures.append("high-RMSE case returned above 20")
        rows.append(
            {
                "stressType": stress_type,
                "target": target,
                "passRule": pass_rule,
                "highGainPct": metrics["highGainPct"],
                "cleanGainPct": metrics["cleanGainPct"],
                "maxProtectedRegression": metrics["maxProtectedRegression"],
                "highStillAbove20": metrics["highStillAbove20"],
                "highWorsened": metrics["highWorsened"],
                "routePreservation": metrics["routePreservation"],
                "routeChangeCount": metrics["routeChangeCount"],
                "stressPassed": not failures,
                "stressFailures": "; ".join(failures),
            }
        )

    raw_metrics = observed_state_full_metrics_for_scorer(
        clean_curves,
        high_names,
        lambda curve: observed_state_score_curve(curve, full_fit, amp_cap),
    )
    add_metric_row("frozen-formula", "v17.52 law frozen inside v17.52 stress pass", raw_metrics, "baseline frozen candidate")

    for row in branch_ablation_rows:
        if parse_float(row.get("ablationMedianHighGainPct")) < 60.0 or parse_float(row.get("ablationMedianCleanGainPct")) < 38.0:
            failures = []
            if parse_float(row.get("ablationMedianHighGainPct")) < 60.0:
                failures.append("branch ablation high gain below 60%")
            if parse_float(row.get("ablationMedianCleanGainPct")) < 38.0:
                failures.append("branch ablation clean gain below 38%")
            if parse_float(row.get("ablationMaxProtectedRegression")) > 0.0:
                failures.append("branch ablation protected regression above 0")
            rows.append(
                {
                    "stressType": "leave-one-branch-out",
                    "target": row["branch"],
                    "passRule": "branch removal should not collapse below review floor",
                    "highGainPct": row.get("ablationMedianHighGainPct"),
                    "cleanGainPct": row.get("ablationMedianCleanGainPct"),
                    "maxProtectedRegression": row.get("ablationMaxProtectedRegression"),
                    "highStillAbove20": "",
                    "highWorsened": "",
                    "routePreservation": row.get("ablationMedianRoutePreservation"),
                    "routeChangeCount": "",
                    "stressPassed": not failures,
                    "stressFailures": "; ".join(failures),
                }
            )

    for row in family_rows:
        failures = []
        if parse_float(row.get("ablationMedianHighGainPct")) < 60.0:
            failures.append("family ablation high gain below 60%")
        if parse_float(row.get("ablationMedianCleanGainPct")) < 38.0:
            failures.append("family ablation clean gain below 38%")
        if parse_float(row.get("actualProtectedMaxRegressionKmS")) > 0.0:
            failures.append("family protected regression above 0")
        rows.append(
            {
                "stressType": "leave-one-family-out",
                "target": row["family"],
                "passRule": "family removal should not collapse below review floor",
                "highGainPct": row.get("ablationMedianHighGainPct"),
                "cleanGainPct": row.get("ablationMedianCleanGainPct"),
                "maxProtectedRegression": row.get("actualProtectedMaxRegressionKmS"),
                "highStillAbove20": "",
                "highWorsened": "",
                "routePreservation": "",
                "routeChangeCount": "",
                "stressPassed": not failures,
                "stressFailures": "; ".join(failures),
            }
        )

    high_case_rows = [row for row in case_rows if row["set"] == "clean-anatomy"]
    protected_high_like = [
        row
        for row in case_rows
        if row["set"] == "clean-protected" and parse_float(row.get("baselineRmse")) >= 18.0
    ]
    for branch in sorted({row["shapeBranchType"] for row in high_case_rows if row.get("shapeBranchType")}):
        actual = [row for row in high_case_rows if row.get("shapeBranchType") == branch]
        if not actual:
            continue
        family = observed_state_branch_family(branch)
        locked_routes = {row["lockedRoute"] for row in actual}
        actual_base = safe_mean(parse_float(row["baselineRmse"]) for row in actual)
        actual_cand = safe_mean(parse_float(row["candidateRmse"]) for row in actual)
        actual_pct = pct_improvement(actual_base, actual_cand)

        def forced_score(row: dict) -> dict:
            return observed_state_score_curve(curve_by_name[row["name"]], full_fit, amp_cap, forced_branch=branch)

        pools = {
            "same-family-same-active-count-null": [
                row
                for row in high_case_rows
                if row["name"] not in {item["name"] for item in actual}
                and observed_state_branch_family(row.get("shapeBranchType", "")) == family
                and row["lockedRoute"] in locked_routes
            ],
            "same-route-same-rmse-band-null": [
                row
                for row in high_case_rows
                if row["name"] not in {item["name"] for item in actual}
                and row["lockedRoute"] in locked_routes
                and min(parse_float(item["baselineRmse"]) for item in actual) - 10.0
                <= parse_float(row["baselineRmse"])
                <= max(parse_float(item["baselineRmse"]) for item in actual) + 10.0
            ],
        }
        for stress_type, pool in pools.items():
            margins = []
            for seed in range(SPLIT_SEED, SPLIT_SEED + 9):
                rng = random.Random(seed + sum(ord(char) for char in branch + stress_type))
                shuffled = pool[:]
                rng.shuffle(shuffled)
                selected = shuffled[: len(actual)]
                random_base = safe_mean(parse_float(row["baselineRmse"]) for row in selected)
                random_cand = safe_mean(forced_score(row)["rmse"] for row in selected)
                random_pct = pct_improvement(random_base, random_cand)
                if math.isfinite(actual_pct) and math.isfinite(random_pct):
                    margins.append(actual_pct - random_pct)
            median_margin = safe_median(margins)
            failures = []
            if math.isfinite(median_margin) and median_margin < 10.0:
                failures.append("median null margin below 10 points")
            rows.append(
                {
                    "stressType": stress_type,
                    "target": branch,
                    "passRule": "actual branch should beat matched random targets by 10 points",
                    "actualGainPct": actual_pct,
                    "medianRandomMarginPct": median_margin,
                    "randomPoolCount": len(pool),
                    "stressPassed": not failures,
                    "stressFailures": "; ".join(failures),
                }
            )

        protected_pool = [
            row
            for row in protected_high_like
            if row["lockedRoute"] in locked_routes and row.get("shapeBranchType") != branch
        ]
        regressions = []
        for row in protected_pool:
            base = score_curve(curve_by_name[row["name"]])
            forced = forced_score(row)
            regressions.append(forced["rmse"] - base["rmse"])
        max_regression = max(regressions) if regressions else 0.0
        rows.append(
            {
                "stressType": "protected-high-rmse-lookalike-stress",
                "target": branch,
                "passRule": "forcing branch on protected high-RMSE lookalikes must not regress",
                "protectedPoolCount": len(protected_pool),
                "maxProtectedRegression": max_regression,
                "stressPassed": max_regression <= 0.0,
                "stressFailures": "" if max_regression <= 0.0 else "protected high-RMSE lookalike regression above 0",
            }
        )

    for scale in [0.90, 0.95, 1.05, 1.10]:
        metrics = observed_state_full_metrics_for_scorer(
            clean_curves,
            high_names,
            lambda curve, scale=scale: observed_state_score_curve_with_strength_jitter(
                curve,
                full_fit,
                amp_cap,
                scale,
                scale,
            ),
        )
        add_metric_row(
            "branch-strength-jitter",
            f"{scale:.2f}x floor/q displacement",
            metrics,
            "jittered law should remain above review floor",
        )
    headers: list[str] = []
    for row in rows:
        for key in row:
            if key not in headers:
                headers.append(key)
    return [{key: row.get(key, "") for key in headers} for row in rows]


def observed_state_compression_ledger_rows(clean_curves: list[dict], high_names: set[str]) -> list[dict]:
    raw_metrics = observed_state_full_metrics_for_scorer(
        clean_curves,
        high_names,
        lambda curve: observed_state_score_curve_with_family_q_overrides(curve, {}),
    )
    rows = []
    for family, trial_q in sorted(OBSERVED_STATE_FAMILY_Q_COMPRESSION_TRIALS.items()):
        metrics = observed_state_full_metrics_for_scorer(
            clean_curves,
            high_names,
            lambda curve, family=family, trial_q=trial_q: observed_state_score_curve_with_family_q_overrides(
                curve, {family: trial_q}
            ),
        )
        failures = []
        if metrics["highStillAbove20"] > raw_metrics["highStillAbove20"]:
            failures.append("leaves additional high-RMSE cases above 20 km/s")
        if metrics["highWorsened"] > 0:
            failures.append("worsens at least one high-RMSE case")
        if metrics["maxProtectedRegression"] > 0.0:
            failures.append("protected regression introduced")
        if metrics["routeChangeCount"] > raw_metrics["routeChangeCount"]:
            failures.append("adds route changes")
        if metrics["highGainPct"] < raw_metrics["highGainPct"] - 0.5:
            failures.append("high-RMSE gain drops by more than 0.5 points")
        accepted = family in OBSERVED_STATE_COMPRESSED_Q_FAMILIES and not failures
        if family in OBSERVED_STATE_CONTINUOUS_Q_FAMILIES:
            failures.append("fixed-q compression superseded by continuous compact-boundary q response")
        if family not in OBSERVED_STATE_COMPRESSED_Q_FAMILIES and not failures:
            failures.append("not selected for v17.52 despite passing automatic gates")
        rows.append(
            {
                "family": family,
                "trialQ": trial_q,
                "rawHighGainPct": raw_metrics["highGainPct"],
                "compressedHighGainPct": metrics["highGainPct"],
                "deltaHighGainPct": metrics["highGainPct"] - raw_metrics["highGainPct"],
                "compressedCleanGainPct": metrics["cleanGainPct"],
                "rawRouteChangeCount": raw_metrics["routeChangeCount"],
                "compressedRouteChangeCount": metrics["routeChangeCount"],
                "routeChangeDelta": metrics["routeChangeCount"] - raw_metrics["routeChangeCount"],
                "highStillAbove20": metrics["highStillAbove20"],
                "highWorsened": metrics["highWorsened"],
                "maxProtectedRegression": metrics["maxProtectedRegression"],
                "compressionAccepted": accepted,
                "compressionFailures": "; ".join(failures),
            }
        )
    return rows


def write_observed_state_candidate_artifacts(out_dir: Path, holdout_fraction: float) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    curves = build_curves()
    weak_names = observed_state_weak_names()
    clean_curves = [curve for curve in curves if curve["name"] not in weak_names]
    anatomy_rows = observed_state_anatomy_rows()
    anatomy_high_names = {row["name"] for row in anatomy_rows}
    baseline_high_names = {curve["name"] for curve in clean_curves if score_curve(curve)["rmse"] >= 20.0}
    high_names = anatomy_high_names | baseline_high_names
    target_log_amp = {
        row["name"]: math.log(clamp(parse_float(row.get("scalarAmp"), 1.0), 1.0, 4.5)) for row in anatomy_rows
    }
    high_weight = 3
    protected_weight = 2
    ridge = 200.0
    amp_cap = 4.5
    seed_rows: list[dict] = []
    null_rows: list[dict] = []
    fits: list[dict] = []
    for seed in range(SPLIT_SEED, SPLIT_SEED + 9):
        train_names, holdout_names = observed_state_split(clean_curves, seed, holdout_fraction)
        for track in [
            "candidate",
            "shuffled-target-null",
            "random-amp-null",
            "branch-label-shuffle-null",
            "same-active-count-branch-random-null",
        ]:
            result, fit = observed_state_seed_result(
                clean_curves,
                train_names,
                holdout_names,
                target_log_amp,
                high_names,
                seed,
                track,
                high_weight,
                protected_weight,
                ridge,
                amp_cap,
            )
            if track == "candidate":
                seed_rows.append(result)
                fits.append(fit)
            else:
                null_rows.append(result)

    branch_ablation_rows = observed_state_branch_ablation_rows(
        clean_curves,
        target_log_amp,
        high_names,
        high_weight,
        protected_weight,
        ridge,
        amp_cap,
        holdout_fraction,
    )
    branch_null_rows = observed_state_branch_null_rows(
        clean_curves,
        target_log_amp,
        high_names,
        high_weight,
        protected_weight,
        ridge,
        amp_cap,
        holdout_fraction,
    )

    all_names = {curve["name"] for curve in clean_curves}
    full_fit = observed_state_train(clean_curves, all_names, target_log_amp, high_names, high_weight, protected_weight, ridge)
    case_rows = []
    for curve in clean_curves:
        base = score_curve(curve)
        cand = observed_state_score_curve(curve, full_fit, amp_cap)
        amp = cand["observedStateAmp"]
        q_value = cand["observedStateQ"]
        branch = cand["observedStateBranch"]
        route_preserved = cand["candidateRoute"] == base["candidateRoute"]
        route_transition_class = ""
        route_safe_alt = {}
        if not route_preserved:
            is_explicit_transition = branch in OBSERVED_STATE_ROUTE_TRANSITION_BRANCHES
            route_transition_class = (
                "explicit framework route-transition branch"
                if curve["name"] in high_names and is_explicit_transition
                else "allowed framework route transition"
                if curve["name"] in high_names and branch
                else "rejected route break"
            )
            if curve["name"] in high_names:
                route_safe = observed_state_best_route_safe_alternative(curve)
                route_safe_alt = {
                    "bestRouteSafeRmse": route_safe["rmse"],
                    "bestRouteSafeGain": route_safe["gain"],
                    "bestRouteSafeAmp": route_safe["amp"],
                    "bestRouteSafeQ": route_safe["q"],
                    "bestRouteSafeUOut": route_safe["uOut"],
                    "bestRouteSafeUMax": route_safe["uMax"],
                    "routeSafeCanRepairUnder20": route_safe["canRepairUnder20"],
                    "singleQFloorRouteTransitionNeeded": not route_safe["canRepairUnder20"],
                    "explicitRouteTransitionBranch": is_explicit_transition,
                }
        case_rows.append(
            {
                "name": curve["name"],
                "set": "clean-anatomy"
                if curve["name"] in anatomy_high_names
                else "clean-high-rmse"
                if curve["name"] in high_names
                else "clean-protected",
                "lockedRoute": curve["lockedModelRoute"],
                "baselineRmse": base["rmse"],
                "candidateRmse": cand["rmse"],
                "gain": base["rmse"] - cand["rmse"],
                "gainPct": 100.0 * (base["rmse"] - cand["rmse"]) / base["rmse"] if base["rmse"] else math.nan,
                "amp": amp,
                "qValue": q_value,
                "shapeBranch": q_value != Q_DEFAULT,
                "shapeBranchType": branch,
                "shapeAmpFloor": observed_state_shape_amp_floor(curve) or "",
                "routeHardeningCap": observed_state_lowload_route_hardening_gate(curve),
                "overSupportGate": observed_state_over_support_gate(curve),
                "bulgeSafetyCap": observed_state_bulge_safety_cap(curve) or "",
                "routePreserved": route_preserved,
                "candidateRoute": cand["candidateRoute"],
                "routeTransition": "" if route_preserved else f"{base['candidateRoute']} -> {cand['candidateRoute']}",
                "routeTransitionClass": route_transition_class,
                "bestRouteSafeRmse": route_safe_alt.get("bestRouteSafeRmse", ""),
                "bestRouteSafeGain": route_safe_alt.get("bestRouteSafeGain", ""),
                "bestRouteSafeAmp": route_safe_alt.get("bestRouteSafeAmp", ""),
                "bestRouteSafeQ": route_safe_alt.get("bestRouteSafeQ", ""),
                "bestRouteSafeUOut": route_safe_alt.get("bestRouteSafeUOut", ""),
                "bestRouteSafeUMax": route_safe_alt.get("bestRouteSafeUMax", ""),
                "routeSafeCanRepairUnder20": route_safe_alt.get("routeSafeCanRepairUnder20", ""),
                "singleQFloorRouteTransitionNeeded": route_safe_alt.get("singleQFloorRouteTransitionNeeded", ""),
                "explicitRouteTransitionBranch": route_safe_alt.get("explicitRouteTransitionBranch", branch in OBSERVED_STATE_ROUTE_TRANSITION_BRANCHES),
                "weakExcluded": False,
            }
        )
    route_transition_rows, route_transition_null_rows = observed_state_route_transition_hardening_rows(
        case_rows,
        branch_ablation_rows,
        branch_null_rows,
    )
    med = lambda rows, key: statistics.median([row[key] for row in rows]) if rows else math.nan
    candidate_summary = {
        "medianHighGainPct": med(seed_rows, "highGainPct"),
        "medianCleanGainPct": med(seed_rows, "cleanGainPct"),
        "medianMaxProtectedRegression": med(seed_rows, "maxProtectedRegression"),
        "maxProtectedRegressionAcrossSeeds": max(row["maxProtectedRegression"] for row in seed_rows),
        "medianRoutePreservation": med(seed_rows, "routePreservation"),
        "minHighGainPct": min(row["highGainPct"] for row in seed_rows),
    }
    explicit_transition_count = sum(
        1
        for row in case_rows
        if row["set"] in {"clean-anatomy", "clean-high-rmse"}
        and row["routeTransitionClass"] == "explicit framework route-transition branch"
    )
    rejected_route_break_count = sum(1 for row in case_rows if row["routeTransitionClass"] == "rejected route break")
    route_safe_unrepairable_count = sum(
        1
        for row in case_rows
        if row["set"] in {"clean-anatomy", "clean-high-rmse"} and row["singleQFloorRouteTransitionNeeded"] is True
    )
    candidate_summary["explicitRouteTransitionCount"] = explicit_transition_count
    candidate_summary["rejectedRouteBreakCount"] = rejected_route_break_count
    candidate_summary["routeSafeUnrepairableTransitionCount"] = route_safe_unrepairable_count
    candidate_summary["acceptedRouteTransitionBranchCount"] = sum(
        1 for row in route_transition_rows if row.get("transitionAccepted")
    )
    candidate_summary["routeTransitionBranchCount"] = len(route_transition_rows)
    candidate_summary["routeTransitionBranchesWithLookalikeStressWarning"] = sum(
        1 for row in route_transition_rows if row.get("transitionWarnings")
    )
    null_summary = {
        "medianShuffledHighGainPct": med([row for row in null_rows if row["track"] == "shuffled-target-null"], "highGainPct"),
        "medianRandomHighGainPct": med([row for row in null_rows if row["track"] == "random-amp-null"], "highGainPct"),
        "medianBranchLabelShuffleHighGainPct": med(
            [row for row in null_rows if row["track"] == "branch-label-shuffle-null"], "highGainPct"
        ),
        "medianSameActiveCountBranchRandomHighGainPct": med(
            [row for row in null_rows if row["track"] == "same-active-count-branch-random-null"], "highGainPct"
        ),
    }
    finite_branch_margins = [
        parse_float(row.get("branchNullMarginPct"))
        for row in branch_null_rows
        if row.get("nullType") == "same-route-same-active-count"
        and math.isfinite(parse_float(row.get("branchNullMarginPct")))
    ]
    for row in branch_ablation_rows:
        branch = row["branch"]
        margins = [
            parse_float(null_row.get("branchNullMarginPct"))
            for null_row in branch_null_rows
            if null_row.get("branch") == branch
            and null_row.get("nullType") == "same-route-same-active-count"
            and math.isfinite(parse_float(null_row.get("branchNullMarginPct")))
        ]
        stress = [
            parse_float(null_row.get("randomProtectedMaxRegression"))
            for null_row in branch_null_rows
            if null_row.get("branch") == branch
            and null_row.get("nullType") == "protected-lookalike-stress"
            and math.isfinite(parse_float(null_row.get("randomProtectedMaxRegression")))
        ]
        row["medianBranchNullMarginPct"] = statistics.median(margins) if margins else math.nan
        row["protectedLookalikeStressMaxRegression"] = max(stress) if stress else 0.0
        protected_polish_branch = (
            row["activeHighCount"] <= 0
            and row["activeProtectedCount"] > 0
            and math.isfinite(parse_float(row.get("fullActiveProtectedMeanGainKmS")))
            and parse_float(row.get("fullActiveProtectedMeanGainKmS")) >= 4.0
            and row["fullProtectedBranchMaxRegression"] <= 0.0
        )
        row["branchAccepted"] = (
            ((
                row["activeHighCount"] > 0
                and row["fullActiveHighMeanGainKmS"] >= 5.0
            ) or protected_polish_branch)
            and row["fullProtectedBranchMaxRegression"] <= 3.0
            and (not margins or row["medianBranchNullMarginPct"] >= 10.0)
        )
        failures = []
        if row["activeHighCount"] <= 0 and not protected_polish_branch:
            failures.append("no active high-RMSE hit")
        if row["activeHighCount"] > 0 and row["fullActiveHighMeanGainKmS"] < 5.0:
            failures.append("active high gain below 5 km/s")
        if row["activeHighCount"] <= 0 and row["activeProtectedCount"] > 0 and not protected_polish_branch:
            failures.append("protected-only branch does not meet safe polish criteria")
        if row["fullProtectedBranchMaxRegression"] > 3.0:
            failures.append("protected branch-hit regression above 3 km/s")
        if margins and row["medianBranchNullMarginPct"] < 10.0:
            failures.append("branch null margin below 10 points")
        row["branchAcceptanceFailures"] = "; ".join(failures)
    route_transition_rows, route_transition_null_rows = observed_state_route_transition_hardening_rows(
        case_rows,
        branch_ablation_rows,
        branch_null_rows,
    )
    route_extension_rows, route_extension_null_rows = observed_state_route_extension_rows(
        case_rows,
        route_transition_rows,
    )
    route_legitimacy_rows = observed_state_route_legitimacy_rows(
        case_rows,
        route_transition_rows,
    )
    candidate_summary["acceptedRouteTransitionBranchCount"] = sum(
        1 for row in route_transition_rows if row.get("transitionAccepted")
    )
    candidate_summary["routeTransitionBranchCount"] = len(route_transition_rows)
    candidate_summary["routeTransitionBranchesWithLookalikeStressWarning"] = sum(
        1 for row in route_transition_rows if row.get("transitionWarnings")
    )
    candidate_summary["routeStateExtensionCount"] = len(route_extension_rows)
    candidate_summary["acceptedRouteStateExtensionCount"] = sum(
        1 for row in route_extension_rows if parse_bool(row.get("routeStateExtensionAccepted"))
    )
    candidate_summary["rejectedRouteStateExtensionCount"] = sum(
        1 for row in route_extension_rows if not parse_bool(row.get("routeStateExtensionAccepted"))
    )
    candidate_summary["routeStateExtensionProtectedHitCount"] = sum(
        int(row.get("branchActiveProtectedCount", 0) or 0) for row in route_extension_rows
    )
    candidate_summary["routeLegitimacyCount"] = len(route_legitimacy_rows)
    candidate_summary["routeLegitimacyAcceptedCount"] = sum(
        1 for row in route_legitimacy_rows if row.get("legitimacy") == "route-transition accepted"
    )
    candidate_summary["routeLegitimacyAcceptedWithWarningCount"] = sum(
        1 for row in route_legitimacy_rows if row.get("legitimacy") == "route-transition accepted with stress warning"
    )
    candidate_summary["routeLegitimacyRejectedCount"] = sum(
        1 for row in route_legitimacy_rows if row.get("legitimacy") == "route-transition rejected"
    )
    candidate_summary["routeLegitimacyProtectedHitCount"] = sum(
        int(row.get("branchActiveProtectedCount", 0) or 0) for row in route_legitimacy_rows
    )
    route_legitimacy_margins = [
        parse_float(row.get("routeTransitionGainOverBestSameRoute"))
        for row in route_legitimacy_rows
        if math.isfinite(parse_float(row.get("routeTransitionGainOverBestSameRoute")))
    ]
    candidate_summary["medianRouteTransitionGainOverBestSameRouteKmS"] = safe_median(route_legitimacy_margins)
    family_rows = observed_state_family_hardening_rows(
        clean_curves,
        target_log_amp,
        high_names,
        high_weight,
        protected_weight,
        ridge,
        amp_cap,
        holdout_fraction,
        candidate_summary["medianHighGainPct"],
        branch_ablation_rows,
    )
    stress_rows = observed_state_candidate_stress_rows(
        clean_curves,
        high_names,
        full_fit,
        amp_cap,
        case_rows,
        branch_ablation_rows,
        family_rows,
    )
    candidate_summary["branchFamilyCount"] = len(family_rows)
    candidate_summary["acceptedBranchFamilyCount"] = sum(1 for row in family_rows if row.get("familyAccepted"))
    candidate_summary["branchFamiliesWithLookalikeStressWarning"] = sum(1 for row in family_rows if row.get("familyWarnings"))
    candidate_summary["stressTestCount"] = len(stress_rows)
    candidate_summary["stressTestFailureCount"] = sum(1 for row in stress_rows if not parse_bool(row.get("stressPassed")))
    candidate_summary["criticalStressFailureCount"] = sum(
        1
        for row in stress_rows
        if not parse_bool(row.get("stressPassed"))
        and row.get("stressType")
        in {
            "branch-strength-jitter",
            "same-family-same-active-count-null",
            "same-route-same-rmse-band-null",
            "protected-high-rmse-lookalike-stress",
        }
    )
    compression_rows = observed_state_compression_ledger_rows(clean_curves, high_names)
    candidate_summary["compressedQFamilyCount"] = sum(1 for row in compression_rows if row.get("compressionAccepted"))
    candidate_summary["distilledFloorBranchGroupCount"] = len(OBSERVED_STATE_DISTILLED_FLOOR_BRANCH_GROUPS)
    null_summary["medianPerBranchActiveCountMarginPct"] = statistics.median(finite_branch_margins) if finite_branch_margins else math.nan
    null_summary["sameActiveCountMarginPct"] = (
        candidate_summary["medianHighGainPct"] - null_summary["medianSameActiveCountBranchRandomHighGainPct"]
    )
    null_summary["branchLabelShuffleMarginPct"] = (
        candidate_summary["medianHighGainPct"] - null_summary["medianBranchLabelShuffleHighGainPct"]
    )
    finite_release_margins = [
        parse_float(row.get("releaseNullMarginPct"))
        for row in route_extension_null_rows
        if row.get("nullType") in {"same-route-random-release-target", "branch-family-random-release-target"}
        and math.isfinite(parse_float(row.get("releaseNullMarginPct")))
    ]
    same_route_release_margins = [
        parse_float(row.get("releaseNullMarginPct"))
        for row in route_extension_null_rows
        if row.get("nullType") == "same-route-random-release-target"
        and math.isfinite(parse_float(row.get("releaseNullMarginPct")))
    ]
    family_release_margins = [
        parse_float(row.get("releaseNullMarginPct"))
        for row in route_extension_null_rows
        if row.get("nullType") == "branch-family-random-release-target"
        and math.isfinite(parse_float(row.get("releaseNullMarginPct")))
    ]
    null_summary["medianRouteStateExtensionNullMarginPct"] = safe_median(finite_release_margins)
    null_summary["medianSameRouteReleaseNullMarginPct"] = safe_median(same_route_release_margins)
    null_summary["medianBranchFamilyReleaseNullMarginPct"] = safe_median(family_release_margins)
    verdict = "promising predictive closure candidate; needs hardening"
    if candidate_summary["maxProtectedRegressionAcrossSeeds"] > 8.0 or candidate_summary["medianHighGainPct"] < 10.0:
        verdict = "state-response candidate not safe enough yet"
    if (
        candidate_summary["medianHighGainPct"] >= 30.0
        and candidate_summary["medianCleanGainPct"] >= 18.0
        and candidate_summary["maxProtectedRegressionAcrossSeeds"] < 4.0
        and null_summary["sameActiveCountMarginPct"] >= 10.0
        and null_summary["branchLabelShuffleMarginPct"] >= 10.0
    ):
        verdict = "null-hardened predictive closure candidate"
    if candidate_summary["routeLegitimacyRejectedCount"] > 0:
        verdict = "state-response candidate needs route-transition hardening"
    elif (
        verdict == "null-hardened predictive closure candidate"
        and candidate_summary["routeLegitimacyCount"] > 0
        and candidate_summary["routeLegitimacyAcceptedCount"] == candidate_summary["routeLegitimacyCount"]
        and candidate_summary["criticalStressFailureCount"] == 0
    ):
        verdict = "route-legitimate predictive closure candidate"
    app_expression = observed_state_app_expression(full_fit, amp_cap)
    freeze_rows, freeze_regression_rows, freeze_summary = observed_state_freeze_audit_rows(
        curves,
        weak_names,
        high_names,
        full_fit,
        amp_cap,
        app_expression,
    )
    candidate_summary["freezeFormulaMismatchCount"] = freeze_summary["formulaMismatchCount"]
    candidate_summary["freezeMaxAbsBrowserMinusPythonRmse"] = freeze_summary["maxAbsBrowserMinusPythonRmse"]
    candidate_summary["freezeProtectedRegressionCount"] = freeze_summary["protectedRegressionCount"]
    candidate_summary["freezeMaxProtectedRegressionKmS"] = freeze_summary["maxProtectedRegressionKmS"]
    candidate_summary["freezeHighImprovedCount"] = freeze_summary["highImprovedCount"]
    candidate_summary["freezeHighStillAbove20Count"] = freeze_summary["highStillAbove20Count"]
    if freeze_summary["formulaMismatchCount"] > 0:
        verdict = "state-response candidate blocked by browser formula drift"
    write_csv(out_dir / "mts_observed_state_candidate_seed_replay.csv", seed_rows)
    write_csv(out_dir / "mts_observed_state_candidate_null_controls.csv", null_rows)
    write_csv(out_dir / "mts_observed_state_candidate_case_ledger.csv", case_rows)
    write_csv(out_dir / "mts_observed_state_candidate_branch_ablation.csv", branch_ablation_rows)
    write_csv(out_dir / "mts_observed_state_candidate_branch_nulls.csv", branch_null_rows)
