def observed_state_family_short_label(family: str) -> str:
    labels = {
        "low-load compact curvature": "F1 compact low-load boundary",
        "low-load q-transition": "F2 low-load route-edge transition",
        "gas-memory response": "F3 gas-memory support",
        "buffered bulge response": "F4 buffered bulge/disk support",
        "buffered shelf-curvature response": "F5 buffered shelf-curvature support",
    }
    return labels.get(family, family)


def observed_state_family_equation_text(family: str) -> str:
    if family == "low-load compact curvature":
        return "q_family = compact-boundary continuous q; A_floor = compact-curvature continuous floor"
    if family == "low-load q-transition":
        return "q_family = low-load route-edge q; A_floor = low-load transition continuous floor with three same-route floor minima"
    if family == "gas-memory response":
        return "q_family = gas-memory branch q; A_floor = buffered gas-memory point-density floor where needed"
    if family == "buffered bulge response":
        return "q_family = buffered-bulge continuous q; A_floor = dense/bulge route-safe floor where needed"
    if family == "buffered shelf-curvature response":
        return "q_family = shelf/disk curvature q; A_floor = shelf-curvature continuous floor"
    return "family equation not mapped"


def write_observed_state_family_compression_artifacts(out_dir: Path, holdout_fraction: float) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    source_dir = observed_state_release_source_dir()
    source_capsule = read_json_if_exists(source_dir / "mts_observed_state_candidate_capsule.json")
    source_formula = read_json_if_exists(source_dir / "mts_observed_state_candidate_formula.json")
    source_case_rows = read_csv_rows(source_dir / "mts_observed_state_candidate_case_ledger.csv")
    source_branch_rows = read_csv_rows(source_dir / "mts_observed_state_candidate_branch_ablation.csv")

    context = observed_state_candidate_context()
    clean_curves = context["cleanCurves"]
    high_names = context["highNames"]
    fit = context["fit"]
    amp_cap = context["ampCap"]
    target_log_amp = {
        row["name"]: math.log(clamp(parse_float(row.get("scalarAmp"), 1.0), 1.0, 4.5))
        for row in context["anatomyRows"]
    }
    retired = set(OBSERVED_STATE_RETIRED_BRANCHES_V1748)
    base_full, _base_rows = observed_state_compression_full_trial(clean_curves, high_names, fit, amp_cap, retired, set())
    base_seed = observed_state_compression_seed_summary(
        clean_curves,
        target_log_amp,
        high_names,
        holdout_fraction,
        retired,
        set(),
    )

    active_high_by_branch = {
        row.get("branch", ""): int(parse_float(row.get("activeHighCount"), 0.0))
        for row in source_branch_rows
    }
    active_protected_by_branch = {
        row.get("branch", ""): int(parse_float(row.get("activeProtectedCount"), 0.0))
        for row in source_branch_rows
    }
    branch_null_margin = {
        row.get("branch", ""): parse_float(row.get("medianBranchNullMarginPct"))
        for row in source_branch_rows
    }

    family_rows: list[dict] = []
    equation_rows: list[dict] = []
    for family, branches in sorted(OBSERVED_STATE_BRANCH_FAMILIES.items()):
        active_branches = [branch for branch in sorted(branches) if active_high_by_branch.get(branch, 0) > 0]
        active_high_count = sum(active_high_by_branch.get(branch, 0) for branch in branches)
        active_protected_count = sum(active_protected_by_branch.get(branch, 0) for branch in branches)
        disabled = set(branches)
        full, _rows = observed_state_compression_full_trial(clean_curves, high_names, fit, amp_cap, retired, disabled)
        seed = observed_state_compression_seed_summary(
            clean_curves,
            target_log_amp,
            high_names,
            holdout_fraction,
            retired,
            disabled,
        )
        high_gain_loss = base_seed["medianHighGainPct"] - seed["medianHighGainPct"]
        clean_gain_loss = base_seed["medianCleanGainPct"] - seed["medianCleanGainPct"]
        family_essential = (
            active_high_count > 0
            and (
                full["highStillAbove20Count"] > base_full["highStillAbove20Count"]
                or full["highWorsenedCount"] > base_full["highWorsenedCount"]
                or high_gain_loss >= 5.0
                or clean_gain_loss >= 3.0
            )
        )
        family_rows.append(
            {
                "family": family,
                "compressedLabel": observed_state_family_short_label(family),
                "mechanism": observed_state_release_family_mechanism(family),
                "equation": observed_state_family_equation_text(family),
                "branchCount": len(branches),
                "activeBranchCount": len(active_branches),
                "activeHighCount": active_high_count,
                "activeProtectedCount": active_protected_count,
                "activeBranches": "; ".join(active_branches),
                "activeHighNames": "; ".join(
                    row.get("name", "")
                    for row in source_case_rows
                    if row.get("shapeBranchType", "") in branches and row.get("set") in {"clean-anatomy", "clean-high-rmse"}
                ),
                "disableFamilyHighGainPct": seed["medianHighGainPct"],
                "disableFamilyCleanGainPct": seed["medianCleanGainPct"],
                "highGainLossPct": high_gain_loss,
                "cleanGainLossPct": clean_gain_loss,
                "disableFamilyHighStillAbove20": full["highStillAbove20Count"],
                "disableFamilyHighWorsened": full["highWorsenedCount"],
                "disableFamilyMaxProtectedRegression": full["maxProtectedRegression"],
                "familyEssential": family_essential,
                "familyReleaseAccepted": family_essential and active_protected_count == 0,
            }
        )
        equation_rows.append(
            {
                "compressedLabel": observed_state_family_short_label(family),
                "family": family,
                "equation": observed_state_family_equation_text(family),
                "mechanism": observed_state_release_family_mechanism(family),
                "branchSubgatesKeptForStateRegionSelection": "; ".join(sorted(branches)),
                "activeBranchCount": len(active_branches),
                "activeHighCount": active_high_count,
                "familyEssential": family_essential,
            }
        )

    case_rows: list[dict] = []
    for row in sorted(source_case_rows, key=lambda item: item.get("name", "")):
        if row.get("set") not in {"clean-anatomy", "clean-high-rmse"}:
            continue
        branch = row.get("shapeBranchType", "")
        family = observed_state_branch_family(branch) if branch else ""
        case_rows.append(
            {
                "galaxy": row.get("name", ""),
                "set": row.get("set", ""),
                "baselineRmse": row.get("baselineRmse", ""),
                "v1752Rmse": row.get("candidateRmse", ""),
                "v1753CompressedFamilyRmse": row.get("candidateRmse", ""),
                "deltaFromV1752": 0.0,
                "gainKmS": row.get("gain", ""),
                "lockedRoute": row.get("lockedRoute", ""),
                "candidateRoute": row.get("candidateRoute", ""),
                "branchSubgate": branch,
                "compressedFamily": observed_state_family_short_label(family) if family else "",
                "routeTransition": row.get("routeTransition", ""),
                "stillAbove20": parse_float(row.get("candidateRmse"), 0.0) >= 20.0,
            }
        )

    active_family_count = sum(1 for row in family_rows if int(row["activeHighCount"]) > 0)
    essential_family_count = sum(1 for row in family_rows if row["familyEssential"])
    release_family_failures = [row for row in family_rows if int(row["activeHighCount"]) > 0 and not row["familyReleaseAccepted"]]
    verdict = (
        "v17.53 family-equation compression accepted"
        if active_family_count == essential_family_count and not release_family_failures
        else "v17.53 family compression rejected"
    )

    formula = {
        "candidateId": "observed-state-response-v17.53",
        "scoringEquivalentTo": "observed-state-response-v17.52",
        "supportLaw": source_formula.get("supportLaw", ""),
        "familyEquationCount": essential_family_count,
        "activeBranchSubgateCount": sum(1 for row in source_branch_rows if int(parse_float(row.get("activeHighCount"), 0.0)) > 0),
        "familyEquations": equation_rows,
        "branchSubgates": "kept only as deterministic state-region selectors; exported law is five family response equations",
        "forbiddenInputs": source_formula.get("forbiddenInputs", []),
        "appExpression": source_formula.get("appExpression", ""),
    }

    write_csv(out_dir / "mts_observed_state_family_compression_scores.csv", family_rows)
    write_csv(out_dir / "mts_observed_state_family_equations.csv", equation_rows)
    write_csv(out_dir / "mts_observed_state_family_case_ledger.csv", case_rows)
    (out_dir / "mts_observed_state_family_formula.json").write_text(
        json.dumps(json_clean(formula), indent=2, sort_keys=True), encoding="utf-8"
    )

    report = [
        "# MTS v17.53 Family-Equation Compression",
        "",
        "This pass does not add a repair. It compresses the v17.52 active branch subgates into family response equations and ablates each family.",
        "",
        "## Result",
        "",
        f"- Verdict: `{verdict}`.",
        f"- Active branch subgates: `{formula['activeBranchSubgateCount']}`.",
        f"- Required family equations: `{essential_family_count}`.",
        f"- High-RMSE holdout gain unchanged: `{fmt(base_seed['medianHighGainPct'])}%`.",
        f"- Clean-set holdout gain unchanged: `{fmt(base_seed['medianCleanGainPct'])}%`.",
        f"- High-RMSE still above 20: `{base_full['highStillAbove20Count']}`.",
        f"- High-RMSE worsened: `{base_full['highWorsenedCount']}`.",
        f"- Max protected regression: `{fmt(base_full['maxProtectedRegression'])} km/s`.",
        "",
        "## Required Families",
        "",
    ]
    for row in family_rows:
        report.append(
            f"- `{row['compressedLabel']}`: active high `{row['activeHighCount']}`, "
            f"disable-family high gain `{fmt(row['disableFamilyHighGainPct'])}%`, "
            f"loss `{fmt(row['highGainLossPct'])}` points, essential `{row['familyEssential']}`."
        )
    report.extend(
        [
            "",
            "## What v17.53 Changes",
            "",
            "v17.53 changes the framework presentation layer: the law is now treated as five deterministic state-family equations with branch subgates only selecting the local state region. The numerical score is identical to v17.52.",
        ]
    )
    (out_dir / "mts_observed_state_family_compression_report.md").write_text("\n".join(report), encoding="utf-8")

    capsule = {
        "analysisName": "mts-observed-state-family-compression-v1",
        "candidateId": "observed-state-response-v17.53",
        "verdict": verdict,
        "scoringEquivalentToV1752": True,
        "activeBranchSubgateCount": formula["activeBranchSubgateCount"],
        "requiredFamilyEquationCount": essential_family_count,
        "highRmseHoldoutGainPct": base_seed["medianHighGainPct"],
        "cleanSetHoldoutGainPct": base_seed["medianCleanGainPct"],
        "highStillAbove20Count": base_full["highStillAbove20Count"],
        "highWorsenedCount": base_full["highWorsenedCount"],
        "maxProtectedRegression": base_full["maxProtectedRegression"],
        "familyReleaseFailureCount": len(release_family_failures),
        "sourceCandidateVerdict": source_capsule.get("verdict", ""),
        "outputFiles": [
            "mts_observed_state_family_compression_scores.csv",
            "mts_observed_state_family_equations.csv",
            "mts_observed_state_family_case_ledger.csv",
            "mts_observed_state_family_formula.json",
            "mts_observed_state_family_compression_report.md",
            "mts_observed_state_family_compression_capsule.json",
        ],
    }
    (out_dir / "mts_observed_state_family_compression_capsule.json").write_text(
        json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8"
    )
    return capsule


