    out_dir = DEFAULT_OBSERVED_STATE_FAMILY_COMPRESS_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_observed_state_family_compression_artifacts(out_dir, args.holdout_fraction)
