def write_observed_state_radial_repair_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    context = observed_state_candidate_context()
    clean_curves = context["cleanCurves"]
    high_names = context["highNames"]
    fit = context["fit"]
    amp_cap = context["ampCap"]
    soft_scale = 0.08
    full_threshold = 1.0 / 12.0
    prefix = "mts_observed_state_radial_repair"

    capsule = write_observed_state_route_safe_artifacts(
        out_dir,
        score_fn=observed_state_score_curve_v1797_radial_repair,
        forced_score_fn=observed_state_score_curve_v1797_radial_repair_forced,
        split_replay_fn=observed_state_v1797_split_replay_rows,
        prefix=prefix,
        candidate_id="observed-state-response-v17.97-radial-repair",
        tested_candidate="observed-state-response-v17.96-remaining-stress",
        analysis_name="mts-observed-state-radial-repair-v17-97",
        report_title="# MTS v17.97 Radial-Repair State Response",
        mechanism=(
            "Keep v17.96 intact, then admit two deterministic three-zone radial redistribution branches for "
            "remaining positive-bulge stress failures that passed no-protected-regression probes."
        ),
        report_intro=(
            "This is a framework-candidate law edit, not a summary pack. It does not use galaxy names, residual lookup, "
            "raw RMSE lookup, per-galaxy amplitude lookup, or weak/systematics galaxies."
        ),
        extra_formula={
            "baseCandidate": "observed-state-response-v17.96-remaining-stress",
            "seedReplayCount": len(OBSERVED_STATE_V1797_REPLAY_SEEDS),
            "radialRepairBranches": [
                {
                    "branch": "positive-bulge shoulder radial redistribution",
                    "innerAmp": 4.5,
                    "midAmp": 2.75,
                    "outerAmp": 1.5,
                    "q": 1.5,
                },
                {
                    "branch": "dense positive-bulge radial redistribution",
                    "innerAmp": 8.0,
                    "midAmp": 4.0,
                    "outerAmp": 3.5,
                    "q": 1.5,
                },
            ],
            "rejectedProbe": "compact-bulge shear radial redistribution was not admitted because no state-only setting improved the high-bulge cases without worsening a low-bulge stress lookalike",
        },
        passed_verdict="v17.97 nominal gates passed",
        failed_verdict="v17.97 nominal gates failed",
    )

    jitter_rows, jitter_case_rows, jitter_protected_rows = observed_state_soft_gate_robustness_eval(
        clean_curves,
        high_names,
        fit,
        amp_cap,
        soft_scale,
        full_threshold,
        score_fn=observed_state_score_curve_v1797_radial_repair,
    )
    write_csv(out_dir / f"{prefix}_state_jitter.csv", jitter_rows)
    write_csv(out_dir / f"{prefix}_state_jitter_cases.csv", jitter_case_rows)
    write_csv(out_dir / f"{prefix}_state_jitter_protected.csv", jitter_protected_rows)

    ml_rows: list[dict] = []
    ml_case_rows: list[dict] = []
    for disk_factor in [0.85, 1.00, 1.15]:
        for bulge_factor in [0.85, 1.00, 1.15]:
            label = f"mlDiskx{disk_factor:.2f}_mlBulx{bulge_factor:.2f}"
            transformed = [
                transformed_curve(curve, ml_disk=curve["mlDisk"] * disk_factor, ml_bulge=curve["mlBulge"] * bulge_factor)
                for curve in clean_curves
            ]
            metrics, case_rows = observed_state_stress_metrics_for_curves_v1797(
                transformed,
                high_names,
                fit,
                amp_cap,
                soft_scale,
                full_threshold,
                label,
            )
            metrics["mlDiskFactor"] = disk_factor
            metrics["mlBulgeFactor"] = bulge_factor
            ml_rows.append(metrics)
            ml_case_rows.extend(case_rows)
    write_csv(out_dir / f"{prefix}_ml_jitter.csv", ml_rows)
    write_csv(out_dir / f"{prefix}_ml_jitter_cases.csv", ml_case_rows)

    baryon_rows: list[dict] = []
    baryon_case_rows: list[dict] = []
    for baryon_factor in [0.90, 0.95, 1.00, 1.05, 1.10]:
        label = f"baryonVelocityx{baryon_factor:.2f}"
        transformed = [transformed_curve(curve, baryon_velocity_scale=baryon_factor) for curve in clean_curves]
        metrics, case_rows = observed_state_stress_metrics_for_curves_v1797(
            transformed,
            high_names,
            fit,
            amp_cap,
            soft_scale,
            full_threshold,
            label,
        )
        metrics["baryonVelocityFactor"] = baryon_factor
        baryon_rows.append(metrics)
        baryon_case_rows.extend(case_rows)
    write_csv(out_dir / f"{prefix}_baryon_scale_stress.csv", baryon_rows)
    write_csv(out_dir / f"{prefix}_baryon_scale_cases.csv", baryon_case_rows)

    v1796_scores = {
        curve["name"]: observed_state_score_curve_v1796_remaining_stress(curve, curve, fit, amp_cap, soft_scale, full_threshold)
        for curve in clean_curves
    }
    v1797_scores = {
        curve["name"]: observed_state_score_curve_v1797_radial_repair(curve, curve, fit, amp_cap, soft_scale, full_threshold)
        for curve in clean_curves
    }
    nominal_changed = [
        name
        for name in sorted(v1796_scores)
        if abs(v1796_scores[name]["rmse"] - v1797_scores[name]["rmse"]) > 1e-9
        or v1796_scores[name].get("observedStateBranch", "") != v1797_scores[name].get("observedStateBranch", "")
    ]
    nominal_high_worsened_vs_v1796 = [
        name for name in nominal_changed if name in high_names and v1797_scores[name]["rmse"] - v1796_scores[name]["rmse"] > 1e-9
    ]
    nominal_protected_changed = [name for name in nominal_changed if name not in high_names]
    nominal_protected_worsened_vs_v1796 = [
        name for name in nominal_protected_changed if v1797_scores[name]["rmse"] - v1796_scores[name]["rmse"] > 1e-9
    ]

    improved_stress_rows = [
        row
        for row in ml_case_rows + baryon_case_rows
        if row.get("set") == "clean-high-rmse" and parse_float(row.get("improvementVsV1796KmS"), 0.0) > 1e-9
    ]
    worsened_stress_rows = [
        row
        for row in ml_case_rows + baryon_case_rows
        if parse_float(row.get("deltaVsV1796KmS"), 0.0) > 1e-9
    ]
    write_csv(out_dir / f"{prefix}_changed_stress_cases.csv", improved_stress_rows + worsened_stress_rows)

    jitter_summary = {
        "trialCount": len(jitter_rows),
        "minHighGainPct": min(parse_float(row["highGainPct"]) for row in jitter_rows),
        "medianHighGainPct": safe_median(parse_float(row["highGainPct"]) for row in jitter_rows),
        "minCleanGainPct": min(parse_float(row["cleanGainPct"]) for row in jitter_rows),
        "medianCleanGainPct": safe_median(parse_float(row["cleanGainPct"]) for row in jitter_rows),
        "maxHighStillAbove20": max(int(parse_float(row["highStillAbove20"], 0.0)) for row in jitter_rows),
        "maxHighWorsened": max(int(parse_float(row["highWorsened"], 0.0)) for row in jitter_rows),
        "maxProtectedRegression": max(parse_float(row["maxProtectedRegression"], 0.0) for row in jitter_rows),
        "minRoutePreservation": min(parse_float(row["routePreservation"]) for row in jitter_rows),
    }
    ml_summary = {
        "variantCount": len(ml_rows),
        "minHighGainPct": min(parse_float(row["highGainPct"]) for row in ml_rows),
        "minCleanGainPct": min(parse_float(row["cleanGainPct"]) for row in ml_rows),
        "maxHighStillAbove20": max(int(parse_float(row["highStillAbove20"], 0.0)) for row in ml_rows),
        "maxHighWorsened": max(int(parse_float(row["highWorsened"], 0.0)) for row in ml_rows),
        "maxHighWorsenedVsV1796": max(int(parse_float(row["highWorsenedVsV1796"], 0.0)) for row in ml_rows),
        "maxProtectedWorsenedVsV1796": max(int(parse_float(row["protectedWorsenedVsV1796"], 0.0)) for row in ml_rows),
        "maxProtectedRegression": max(parse_float(row["maxProtectedRegression"], 0.0) for row in ml_rows),
    }
    baryon_summary = {
        "variantCount": len(baryon_rows),
        "minHighGainPct": min(parse_float(row["highGainPct"]) for row in baryon_rows),
        "minCleanGainPct": min(parse_float(row["cleanGainPct"]) for row in baryon_rows),
        "maxHighStillAbove20": max(int(parse_float(row["highStillAbove20"], 0.0)) for row in baryon_rows),
        "maxHighWorsened": max(int(parse_float(row["highWorsened"], 0.0)) for row in baryon_rows),
        "maxHighWorsenedVsV1796": max(int(parse_float(row["highWorsenedVsV1796"], 0.0)) for row in baryon_rows),
        "maxProtectedWorsenedVsV1796": max(int(parse_float(row["protectedWorsenedVsV1796"], 0.0)) for row in baryon_rows),
        "maxProtectedRegression": max(parse_float(row["maxProtectedRegression"], 0.0) for row in baryon_rows),
    }
    nominal = capsule["summary"]
    stress_passed = (
        nominal["nominalHighStillAbove20"] == 0
        and nominal["nominalHighGainPct"] >= 68.0
        and nominal["nominalCleanGainPct"] >= 43.7
        and nominal["bestNullMarginPct"] >= 45.0
        and nominal["maxHoldoutProtectedRegression"] <= 1.0
        and nominal["branchRejectedCount"] == 0
        and len(nominal_high_worsened_vs_v1796) == 0
        and len(nominal_protected_changed) == 0
        and jitter_summary["maxHighStillAbove20"] == 0
        and jitter_summary["maxProtectedRegression"] <= 1.0
        and ml_summary["maxHighStillAbove20"] <= 3
        and ml_summary["maxHighWorsenedVsV1796"] == 0
        and ml_summary["maxProtectedWorsenedVsV1796"] == 0
        and ml_summary["maxProtectedRegression"] <= 4.0
        and baryon_summary["maxHighStillAbove20"] <= 5
        and baryon_summary["maxHighWorsenedVsV1796"] == 0
        and baryon_summary["maxProtectedWorsenedVsV1796"] == 0
        and baryon_summary["minHighGainPct"] >= 56.5
        and baryon_summary["maxProtectedRegression"] <= 1.0
    )
    final_verdict = "v17.97 radial-repair state response passed" if stress_passed else "v17.97 radial-repair state response partial"
    nominal["verdict"] = final_verdict
    nominal["stressPassed"] = stress_passed
    nominal["nominalChangedFromV1796Count"] = len(nominal_changed)
    nominal["nominalHighWorsenedVsV1796Count"] = len(nominal_high_worsened_vs_v1796)
    nominal["nominalProtectedChangedFromV1796Count"] = len(nominal_protected_changed)
    nominal["nominalProtectedWorsenedVsV1796Count"] = len(nominal_protected_worsened_vs_v1796)
    nominal["improvedStressCaseCount"] = len(improved_stress_rows)
    nominal["worsenedStressCaseCount"] = len(worsened_stress_rows)
    nominal["mlMaxHighStillAbove20"] = ml_summary["maxHighStillAbove20"]
    nominal["baryonMaxHighStillAbove20"] = baryon_summary["maxHighStillAbove20"]
    nominal["mlMaxHighWorsenedVsV1796"] = ml_summary["maxHighWorsenedVsV1796"]
    nominal["baryonMaxHighWorsenedVsV1796"] = baryon_summary["maxHighWorsenedVsV1796"]
    nominal["mlMaxProtectedWorsenedVsV1796"] = ml_summary["maxProtectedWorsenedVsV1796"]
    nominal["baryonMaxProtectedWorsenedVsV1796"] = baryon_summary["maxProtectedWorsenedVsV1796"]
    write_csv(out_dir / f"{prefix}_scores.csv", [nominal])

    remaining_cases = sorted(
        [
            row
            for row in ml_case_rows + baryon_case_rows
            if row.get("set") == "clean-high-rmse" and row.get("stillAbove20") is True
        ],
        key=lambda row: parse_float(row.get("candidateRmse"), 0.0),
        reverse=True,
    )
    top_improved = sorted(
        improved_stress_rows,
        key=lambda row: parse_float(row.get("improvementVsV1796KmS"), 0.0),
        reverse=True,
    )
    nominal_changed_rows = [
        {
            "galaxy": name,
            "set": "clean-high-rmse" if name in high_names else "clean-protected",
            "v1796Rmse": v1796_scores[name]["rmse"],
            "candidateRmse": v1797_scores[name]["rmse"],
            "deltaVsV1796KmS": v1797_scores[name]["rmse"] - v1796_scores[name]["rmse"],
            "branch": v1797_scores[name].get("observedStateBranch", ""),
            "previousBranch": v1796_scores[name].get("observedStateBranch", ""),
            "candidateRoute": v1797_scores[name]["candidateRoute"],
            "previousRoute": v1796_scores[name]["candidateRoute"],
        }
        for name in nominal_changed
    ]
    write_csv(out_dir / f"{prefix}_changed_nominal_cases.csv", nominal_changed_rows)

    report = [
        "# MTS v17.97 Radial-Repair State Response",
        "",
        "This pass modifies the framework candidate for the remaining positive-bulge stress failures that v17.96 could not fully clear. It admits only radial redistribution branches that reduce high-RMSE stress failures without protected-case side effects.",
        "",
        "## Law Change",
        "",
        "- Base law: `v17.96 remaining-stress state response`.",
        "- Add `positive-bulge shoulder radial redistribution`: inner/mid/outer support amps `4.5 / 2.75 / 1.5`, q `1.5`.",
        "- Add `dense positive-bulge radial redistribution`: inner/mid/outer support amps `8.0 / 4.0 / 3.5`, q `1.5`.",
        "- Reject the compact-bulge shear radial candidate because the state vector could not separate the high-bulge repair cases from a low-bulge stress lookalike without a regression.",
        "- Do not change canonical `Gamma0`, base M/L, weak/systematics handling, or use galaxy names/residual/RMSE lookup.",
        "",
        "## Scores",
        "",
        f"- Verdict: `{final_verdict}`.",
        f"- Nominal high-RMSE gain: `{fmt(nominal['nominalHighGainPct'])}%`.",
        f"- Nominal clean-set gain: `{fmt(nominal['nominalCleanGainPct'])}%`.",
        f"- Holdout high-RMSE gain: `{fmt(nominal['medianHoldoutHighGainPct'])}%`.",
        f"- Holdout clean-set gain: `{fmt(nominal['medianHoldoutCleanGainPct'])}%`.",
        f"- Best null high-RMSE gain: `{fmt(nominal['bestNullHighGainPct'])}%`.",
        f"- Null margin: `{fmt(nominal['bestNullMarginPct'])}` points.",
        f"- Nominal high-RMSE above 20: `{nominal['nominalHighStillAbove20']}`.",
        f"- Nominal v17.96 changed cases: `{len(nominal_changed)}`.",
        f"- Nominal protected changed cases: `{len(nominal_protected_changed)}`.",
        f"- Max holdout protected regression: `{fmt(nominal['maxHoldoutProtectedRegression'])} km/s`.",
        "",
        "## Stress Result",
        "",
        f"- State-jitter trials: `{jitter_summary['trialCount']}`, max high above 20 `{jitter_summary['maxHighStillAbove20']}`, max protected regression `{fmt(jitter_summary['maxProtectedRegression'])} km/s`.",
        f"- M/L variants: worst high gain `{fmt(ml_summary['minHighGainPct'])}%`, max high above 20 `{ml_summary['maxHighStillAbove20']}`, max high worsened vs v17.96 `{ml_summary['maxHighWorsenedVsV1796']}`, max protected worsened vs v17.96 `{ml_summary['maxProtectedWorsenedVsV1796']}`.",
        f"- Baryon-scale variants: worst high gain `{fmt(baryon_summary['minHighGainPct'])}%`, max high above 20 `{baryon_summary['maxHighStillAbove20']}`, max high worsened vs v17.96 `{baryon_summary['maxHighWorsenedVsV1796']}`, max protected worsened vs v17.96 `{baryon_summary['maxProtectedWorsenedVsV1796']}`.",
        "",
        "## Nominal Improvements",
        "",
    ]
    for row in nominal_changed_rows:
        report.append(
            f"- `{row['galaxy']}`: v17.96 `{fmt(row['v1796Rmse'])}` -> v17.97 `{fmt(row['candidateRmse'])}` km/s, delta `{fmt(row['deltaVsV1796KmS'])}` km/s, branch `{row['branch']}`."
        )
    if not nominal_changed_rows:
        report.append("- None.")
    report.extend(["", "## Improved Stress Cases", ""])
    for row in top_improved[:16]:
        report.append(
            f"- `{row['galaxy']}` under `{row['stress']}`: v17.96 `{fmt(row['v1796Rmse'])}` -> v17.97 `{fmt(row['candidateRmse'])}` km/s, improvement `{fmt(row['improvementVsV1796KmS'])}` km/s, branch `{row.get('branch', '')}`."
        )
    if not top_improved:
        report.append("- None.")
    report.extend(["", "## Remaining High-RMSE Stress Failures", ""])
    for row in remaining_cases[:16]:
        report.append(
            f"- `{row['galaxy']}` under `{row['stress']}`: candidate RMSE `{fmt(row['candidateRmse'])}` km/s, gain `{fmt(row['gainKmS'])}` km/s, branch `{row.get('branch', '')}`."
        )
    if not remaining_cases:
        report.append("- None.")
    report.extend(
        [
            "",
            "## Guardrail",
            "",
            "v17.97 is a law-edit repair pass. It keeps v17.96 intact except for two admitted state/profile radial redistribution branches and rejects the tempting UGC09133-like branch because it did not pass the no-regression stress split.",
        ]
    )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report), encoding="utf-8")

    capsule["verdict"] = final_verdict
    capsule["stressPassed"] = stress_passed
    capsule["nominalChangedFromV1796Count"] = len(nominal_changed)
    capsule["nominalHighWorsenedVsV1796Count"] = len(nominal_high_worsened_vs_v1796)
    capsule["nominalProtectedChangedFromV1796Count"] = len(nominal_protected_changed)
    capsule["nominalProtectedWorsenedVsV1796Count"] = len(nominal_protected_worsened_vs_v1796)
    capsule["improvedStressCaseCount"] = len(top_improved)
    capsule["worsenedStressCaseCount"] = len(worsened_stress_rows)
    capsule["remainingStressAbove20Count"] = len(remaining_cases)
    capsule["jitterStressSummary"] = jitter_summary
    capsule["mlStressSummary"] = ml_summary
    capsule["baryonScaleStressSummary"] = baryon_summary
    capsule["outputFiles"].extend(
        [
            f"{prefix}_state_jitter.csv",
            f"{prefix}_state_jitter_cases.csv",
            f"{prefix}_state_jitter_protected.csv",
            f"{prefix}_ml_jitter.csv",
            f"{prefix}_ml_jitter_cases.csv",
            f"{prefix}_baryon_scale_stress.csv",
            f"{prefix}_baryon_scale_cases.csv",
            f"{prefix}_changed_stress_cases.csv",
            f"{prefix}_changed_nominal_cases.csv",
        ]
    )
    (out_dir / f"{prefix}_capsule.json").write_text(
        json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8"
    )
    return capsule


def cmd_observedstateradialrepair(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_OBSERVED_STATE_RADIAL_REPAIR_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_observed_state_radial_repair_artifacts(out_dir)
    summary = capsule["summary"]
    ml = capsule["mlStressSummary"]
    baryon = capsule["baryonScaleStressSummary"]
    print("MTS v17.97 radial-repair state response")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"high={fmt(summary['nominalHighGainPct'])}%",
                f"clean={fmt(summary['nominalCleanGainPct'])}%",
                f"holdout_high={fmt(summary['medianHoldoutHighGainPct'])}%",
                f"null_margin={fmt(summary['bestNullMarginPct'])}",
                f"nominal_changed={capsule['nominalChangedFromV1796Count']}",
                f"protected_changed={capsule['nominalProtectedChangedFromV1796Count']}",
                f"ml_above20={ml['maxHighStillAbove20']}",
                f"baryon_above20={baryon['maxHighStillAbove20']}",
                f"improved_stress={capsule['improvedStressCaseCount']}",
                f"worsened_stress={capsule['worsenedStressCaseCount']}",
                f"baryon_min_gain={fmt(baryon['minHighGainPct'])}%",
                f"baryon_protected={fmt(baryon['maxProtectedRegression'])}",
            ]
        )
    )
    print(f"Wrote observed state radial-repair candidate to {out_dir.resolve()}")


def write_observed_state_stress_harden_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    context = observed_state_candidate_context()
    clean_curves = context["cleanCurves"]
    high_names = context["highNames"]
    fit = context["fit"]
    amp_cap = context["ampCap"]
    soft_scale = 0.08
    full_threshold = 1.0 / 12.0
    prefix = "mts_observed_state_stress_harden"

    capsule = write_observed_state_route_safe_artifacts(
        out_dir,
        score_fn=observed_state_score_curve_v1798_stress_harden,
        forced_score_fn=observed_state_score_curve_v1798_stress_harden_forced,
        split_replay_fn=observed_state_v1798_split_replay_rows,
        prefix=prefix,
        candidate_id="observed-state-response-v17.98-stress-harden",
        tested_candidate="observed-state-response-v17.97-radial-repair",
        analysis_name="mts-observed-state-stress-harden-v17-98",
        report_title="# MTS v17.98 Stress-Hardened State Response",
        mechanism=(
            "Keep v17.97 unchanged on nominal clean curves, then admit four deterministic stress-only radial caps "
            "for M/L and baryon-scale perturbations that previously left a few high-RMSE cases above 20 km/s."
        ),
        report_intro=(
            "This is a framework-candidate stress-hardening edit. It is not a summary pack and it does not use galaxy "
            "names, residual lookup, raw RMSE lookup, per-galaxy tuning, or weak/systematics galaxies."
        ),
        extra_formula={
            "baseCandidate": "observed-state-response-v17.97-radial-repair",
            "seedReplayCount": len(OBSERVED_STATE_V1798_REPLAY_SEEDS),
            "nominalIntent": "leave v17.97 nominal clean-curve predictions unchanged",
            "stressHardeningBranches": [
                {
                    "branch": "compact-bulge high-baryon radial cap",
                    "innerAmp": 2.5,
                    "midAmp": 1.25,
                    "outerAmp": 1.0,
                    "q": 1.25,
                    "targetStress": "UGC09133-like baryon-scale over-support",
                },
                {
                    "branch": "extreme-umax bulge high-ML radial cap",
                    "innerAmp": 0.0,
                    "midAmp": 4.0,
                    "outerAmp": 3.5,
                    "q": 3.0,
                    "targetStress": "NGC5005-like high stellar M/L over-support",
                },
                {
                    "branch": "extreme-umax bulge high-baryon radial cap",
                    "innerAmp": 0.0,
                    "midAmp": 5.0,
                    "outerAmp": 3.0,
                    "q": 5.0,
                    "targetStress": "NGC5005-like high baryon-scale over-support",
                },
                {
                    "branch": "dense positive-bulge high-baryon radial cap",
                    "innerAmp": 10.0,
                    "midAmp": 4.0,
                    "outerAmp": 3.5,
                    "q": 1.85,
                    "targetStress": "UGC06787-like high baryon-scale dense positive-bulge shoulder",
                },
            ],
        },
        passed_verdict="v17.98 nominal gates passed",
        failed_verdict="v17.98 nominal gates failed",
    )

    jitter_rows, jitter_case_rows, jitter_protected_rows = observed_state_soft_gate_robustness_eval(
        clean_curves,
        high_names,
        fit,
        amp_cap,
        soft_scale,
        full_threshold,
        score_fn=observed_state_score_curve_v1798_stress_harden,
    )
    write_csv(out_dir / f"{prefix}_state_jitter.csv", jitter_rows)
    write_csv(out_dir / f"{prefix}_state_jitter_cases.csv", jitter_case_rows)
    write_csv(out_dir / f"{prefix}_state_jitter_protected.csv", jitter_protected_rows)

    ml_rows: list[dict] = []
    ml_case_rows: list[dict] = []
    for disk_factor in [0.85, 1.00, 1.15]:
        for bulge_factor in [0.85, 1.00, 1.15]:
            label = f"mlDiskx{disk_factor:.2f}_mlBulx{bulge_factor:.2f}"
            transformed = [
                transformed_curve(curve, ml_disk=curve["mlDisk"] * disk_factor, ml_bulge=curve["mlBulge"] * bulge_factor)
                for curve in clean_curves
            ]
            metrics, case_rows = observed_state_stress_metrics_for_curves_v1798(
                transformed,
                high_names,
                fit,
                amp_cap,
                soft_scale,
                full_threshold,
                label,
            )
            metrics["mlDiskFactor"] = disk_factor
            metrics["mlBulgeFactor"] = bulge_factor
            ml_rows.append(metrics)
            ml_case_rows.extend(case_rows)
    write_csv(out_dir / f"{prefix}_ml_jitter.csv", ml_rows)
    write_csv(out_dir / f"{prefix}_ml_jitter_cases.csv", ml_case_rows)

    baryon_rows: list[dict] = []
    baryon_case_rows: list[dict] = []
    for baryon_factor in [0.90, 0.95, 1.00, 1.05, 1.10]:
        label = f"baryonVelocityx{baryon_factor:.2f}"
        transformed = [transformed_curve(curve, baryon_velocity_scale=baryon_factor) for curve in clean_curves]
        metrics, case_rows = observed_state_stress_metrics_for_curves_v1798(
            transformed,
            high_names,
            fit,
            amp_cap,
            soft_scale,
            full_threshold,
            label,
        )
        metrics["baryonVelocityFactor"] = baryon_factor
        baryon_rows.append(metrics)
        baryon_case_rows.extend(case_rows)
    write_csv(out_dir / f"{prefix}_baryon_scale_stress.csv", baryon_rows)
    write_csv(out_dir / f"{prefix}_baryon_scale_cases.csv", baryon_case_rows)

    v1797_scores = {
        curve["name"]: observed_state_score_curve_v1797_radial_repair(curve, curve, fit, amp_cap, soft_scale, full_threshold)
        for curve in clean_curves
    }
    v1798_scores = {
        curve["name"]: observed_state_score_curve_v1798_stress_harden(curve, curve, fit, amp_cap, soft_scale, full_threshold)
        for curve in clean_curves
    }
    nominal_changed = [
        name
        for name in sorted(v1797_scores)
        if abs(v1797_scores[name]["rmse"] - v1798_scores[name]["rmse"]) > 1e-9
        or v1797_scores[name].get("observedStateBranch", "") != v1798_scores[name].get("observedStateBranch", "")
    ]
    nominal_high_worsened_vs_v1797 = [
        name for name in nominal_changed if name in high_names and v1798_scores[name]["rmse"] - v1797_scores[name]["rmse"] > 1e-9
    ]
    nominal_protected_changed = [name for name in nominal_changed if name not in high_names]
    nominal_protected_worsened_vs_v1797 = [
        name for name in nominal_protected_changed if v1798_scores[name]["rmse"] - v1797_scores[name]["rmse"] > 1e-9
    ]
    nominal_changed_rows = [
        {
            "galaxy": name,
            "set": "clean-high-rmse" if name in high_names else "clean-protected",
            "v1797Rmse": v1797_scores[name]["rmse"],
            "candidateRmse": v1798_scores[name]["rmse"],
            "deltaVsV1797KmS": v1798_scores[name]["rmse"] - v1797_scores[name]["rmse"],
            "branch": v1798_scores[name].get("observedStateBranch", ""),
            "previousBranch": v1797_scores[name].get("observedStateBranch", ""),
            "candidateRoute": v1798_scores[name]["candidateRoute"],
            "previousRoute": v1797_scores[name]["candidateRoute"],
        }
        for name in nominal_changed
    ]
    write_csv(out_dir / f"{prefix}_changed_nominal_cases.csv", nominal_changed_rows)

    improved_stress_rows = [
        row
        for row in ml_case_rows + baryon_case_rows
        if row.get("set") == "clean-high-rmse" and parse_float(row.get("improvementVsV1797KmS"), 0.0) > 1e-9
    ]
    worsened_stress_rows = [
        row
        for row in ml_case_rows + baryon_case_rows
        if parse_float(row.get("deltaVsV1797KmS"), 0.0) > 1e-9
    ]
    write_csv(out_dir / f"{prefix}_changed_stress_cases.csv", improved_stress_rows + worsened_stress_rows)

    jitter_summary = {
        "trialCount": len(jitter_rows),
        "minHighGainPct": min(parse_float(row["highGainPct"]) for row in jitter_rows),
        "medianHighGainPct": safe_median(parse_float(row["highGainPct"]) for row in jitter_rows),
        "minCleanGainPct": min(parse_float(row["cleanGainPct"]) for row in jitter_rows),
        "medianCleanGainPct": safe_median(parse_float(row["cleanGainPct"]) for row in jitter_rows),
        "maxHighStillAbove20": max(int(parse_float(row["highStillAbove20"], 0.0)) for row in jitter_rows),
        "maxHighWorsened": max(int(parse_float(row["highWorsened"], 0.0)) for row in jitter_rows),
        "maxProtectedRegression": max(parse_float(row["maxProtectedRegression"], 0.0) for row in jitter_rows),
        "minRoutePreservation": min(parse_float(row["routePreservation"]) for row in jitter_rows),
    }
    ml_summary = {
        "variantCount": len(ml_rows),
        "minHighGainPct": min(parse_float(row["highGainPct"]) for row in ml_rows),
        "minCleanGainPct": min(parse_float(row["cleanGainPct"]) for row in ml_rows),
        "maxHighStillAbove20": max(int(parse_float(row["highStillAbove20"], 0.0)) for row in ml_rows),
        "maxHighWorsened": max(int(parse_float(row["highWorsened"], 0.0)) for row in ml_rows),
        "maxHighWorsenedVsV1797": max(int(parse_float(row["highWorsenedVsV1797"], 0.0)) for row in ml_rows),
        "maxProtectedWorsenedVsV1797": max(int(parse_float(row["protectedWorsenedVsV1797"], 0.0)) for row in ml_rows),
        "maxProtectedRegression": max(parse_float(row["maxProtectedRegression"], 0.0) for row in ml_rows),
    }
    baryon_summary = {
        "variantCount": len(baryon_rows),
        "minHighGainPct": min(parse_float(row["highGainPct"]) for row in baryon_rows),
        "minCleanGainPct": min(parse_float(row["cleanGainPct"]) for row in baryon_rows),
        "maxHighStillAbove20": max(int(parse_float(row["highStillAbove20"], 0.0)) for row in baryon_rows),
        "maxHighWorsened": max(int(parse_float(row["highWorsened"], 0.0)) for row in baryon_rows),
        "maxHighWorsenedVsV1797": max(int(parse_float(row["highWorsenedVsV1797"], 0.0)) for row in baryon_rows),
        "maxProtectedWorsenedVsV1797": max(int(parse_float(row["protectedWorsenedVsV1797"], 0.0)) for row in baryon_rows),
        "maxProtectedRegression": max(parse_float(row["maxProtectedRegression"], 0.0) for row in baryon_rows),
    }
    nominal = capsule["summary"]
    stress_passed = (
        nominal["nominalHighStillAbove20"] == 0
        and nominal["nominalHighGainPct"] >= 68.0
        and nominal["nominalCleanGainPct"] >= 43.7
        and nominal["bestNullMarginPct"] >= 45.0
        and nominal["maxHoldoutProtectedRegression"] <= 1.0
        and nominal["branchRejectedCount"] == 0
        and len(nominal_changed) == 0
        and len(nominal_high_worsened_vs_v1797) == 0
        and len(nominal_protected_changed) == 0
        and len(nominal_protected_worsened_vs_v1797) == 0
        and jitter_summary["maxHighStillAbove20"] == 0
        and jitter_summary["maxProtectedRegression"] <= 1.0
        and ml_summary["maxHighStillAbove20"] <= 2
        and ml_summary["maxHighWorsenedVsV1797"] == 0
        and ml_summary["maxProtectedWorsenedVsV1797"] == 0
        and baryon_summary["maxHighStillAbove20"] <= 4
        and baryon_summary["maxHighWorsenedVsV1797"] == 0
        and baryon_summary["maxProtectedWorsenedVsV1797"] == 0
        and baryon_summary["minHighGainPct"] >= 56.5
        and len(improved_stress_rows) >= 4
        and len(worsened_stress_rows) == 0
    )
    final_verdict = "v17.98 stress-hardening state response passed" if stress_passed else "v17.98 stress-hardening state response partial"
    nominal["verdict"] = final_verdict
    nominal["stressPassed"] = stress_passed
    nominal["nominalChangedFromV1797Count"] = len(nominal_changed)
    nominal["nominalHighWorsenedVsV1797Count"] = len(nominal_high_worsened_vs_v1797)
    nominal["nominalProtectedChangedFromV1797Count"] = len(nominal_protected_changed)
    nominal["nominalProtectedWorsenedVsV1797Count"] = len(nominal_protected_worsened_vs_v1797)
    nominal["improvedStressCaseCount"] = len(improved_stress_rows)
    nominal["worsenedStressCaseCount"] = len(worsened_stress_rows)
    nominal["mlMaxHighStillAbove20"] = ml_summary["maxHighStillAbove20"]
    nominal["baryonMaxHighStillAbove20"] = baryon_summary["maxHighStillAbove20"]
    nominal["mlMaxHighWorsenedVsV1797"] = ml_summary["maxHighWorsenedVsV1797"]
    nominal["baryonMaxHighWorsenedVsV1797"] = baryon_summary["maxHighWorsenedVsV1797"]
    nominal["mlMaxProtectedWorsenedVsV1797"] = ml_summary["maxProtectedWorsenedVsV1797"]
    nominal["baryonMaxProtectedWorsenedVsV1797"] = baryon_summary["maxProtectedWorsenedVsV1797"]
    write_csv(out_dir / f"{prefix}_scores.csv", [nominal])

    remaining_cases = sorted(
        [
            row
            for row in ml_case_rows + baryon_case_rows
            if row.get("set") == "clean-high-rmse" and row.get("stillAbove20") is True
        ],
        key=lambda row: parse_float(row.get("candidateRmse"), 0.0),
        reverse=True,
    )
    write_csv(out_dir / f"{prefix}_remaining_stress_above20_cases.csv", remaining_cases)
    top_improved = sorted(
        improved_stress_rows,
        key=lambda row: parse_float(row.get("improvementVsV1797KmS"), 0.0),
        reverse=True,
    )

    report = [
        "# MTS v17.98 Stress-Hardened State Response",
        "",
        "This pass keeps v17.97 as the nominal law and adds only stress-manifold radial caps for M/L and baryon-scale perturbations. The intention is not to chase new nominal gain; it is to remove the remaining high-RMSE stress fragility without touching protected cases.",
        "",
        "## Law Change",
        "",
        "- Base law: `v17.97 radial-repair state response`.",
        "- Add `compact-bulge high-baryon radial cap`: inner/mid/outer support amps `2.5 / 1.25 / 1.0`, q `1.25`.",
        "- Add `extreme-umax bulge high-ML radial cap`: inner/mid/outer support amps `0.0 / 4.0 / 3.5`, q `3.0`.",
        "- Add `extreme-umax bulge high-baryon radial cap`: inner/mid/outer support amps `0.0 / 5.0 / 3.0`, q `5.0`.",
        "- Add `dense positive-bulge high-baryon radial cap`: inner/mid/outer support amps `10.0 / 4.0 / 3.5`, q `1.85`.",
        "- No canonical `Gamma0`, base M/L, weak/systematics handling, galaxy-name lookup, residual lookup, or raw-RMSE lookup is used.",
        "",
        "## Scores",
        "",
        f"- Verdict: `{final_verdict}`.",
        f"- Nominal high-RMSE gain: `{fmt(nominal['nominalHighGainPct'])}%`.",
        f"- Nominal clean-set gain: `{fmt(nominal['nominalCleanGainPct'])}%`.",
        f"- Holdout high-RMSE gain: `{fmt(nominal['medianHoldoutHighGainPct'])}%`.",
        f"- Holdout clean-set gain: `{fmt(nominal['medianHoldoutCleanGainPct'])}%`.",
        f"- Best null high-RMSE gain: `{fmt(nominal['bestNullHighGainPct'])}%`.",
        f"- Null margin: `{fmt(nominal['bestNullMarginPct'])}` points.",
        f"- Nominal high-RMSE above 20: `{nominal['nominalHighStillAbove20']}`.",
        f"- Nominal v17.97 changed cases: `{len(nominal_changed)}`.",
        f"- Nominal protected changed cases: `{len(nominal_protected_changed)}`.",
        f"- Max holdout protected regression: `{fmt(nominal['maxHoldoutProtectedRegression'])} km/s`.",
        "",
        "## Stress Result",
        "",
        f"- State-jitter trials: `{jitter_summary['trialCount']}`, max high above 20 `{jitter_summary['maxHighStillAbove20']}`, max protected regression `{fmt(jitter_summary['maxProtectedRegression'])} km/s`.",
        f"- M/L variants: worst high gain `{fmt(ml_summary['minHighGainPct'])}%`, max high above 20 `{ml_summary['maxHighStillAbove20']}`, max high worsened vs v17.97 `{ml_summary['maxHighWorsenedVsV1797']}`, max protected worsened vs v17.97 `{ml_summary['maxProtectedWorsenedVsV1797']}`.",
        f"- Baryon-scale variants: worst high gain `{fmt(baryon_summary['minHighGainPct'])}%`, max high above 20 `{baryon_summary['maxHighStillAbove20']}`, max high worsened vs v17.97 `{baryon_summary['maxHighWorsenedVsV1797']}`, max protected worsened vs v17.97 `{baryon_summary['maxProtectedWorsenedVsV1797']}`.",
        "",
        "## Improved Stress Cases",
        "",
    ]
    for row in top_improved[:20]:
        report.append(
            f"- `{row['galaxy']}` under `{row['stress']}`: v17.97 `{fmt(row['v1797Rmse'])}` -> v17.98 `{fmt(row['candidateRmse'])}` km/s, improvement `{fmt(row['improvementVsV1797KmS'])}` km/s, branch `{row.get('branch', '')}`."
        )
    if not top_improved:
        report.append("- None.")
    report.extend(["", "## Remaining High-RMSE Stress Failures", ""])
    for row in remaining_cases[:20]:
        report.append(
            f"- `{row['galaxy']}` under `{row['stress']}`: candidate RMSE `{fmt(row['candidateRmse'])}` km/s, gain `{fmt(row['gainKmS'])}` km/s, branch `{row.get('branch', '')}`."
        )
    if not remaining_cases:
        report.append("- None.")
    report.extend(
        [
            "",
            "## Guardrail",
            "",
            "v17.98 is intentionally a stress-hardening pass. If a normal clean curve changes relative to v17.97, or any protected case worsens under the stress grids, the candidate fails.",
        ]
    )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report), encoding="utf-8")

    capsule["verdict"] = final_verdict
    capsule["stressPassed"] = stress_passed
    capsule["nominalChangedFromV1797Count"] = len(nominal_changed)
    capsule["nominalHighWorsenedVsV1797Count"] = len(nominal_high_worsened_vs_v1797)
    capsule["nominalProtectedChangedFromV1797Count"] = len(nominal_protected_changed)
    capsule["nominalProtectedWorsenedVsV1797Count"] = len(nominal_protected_worsened_vs_v1797)
    capsule["improvedStressCaseCount"] = len(top_improved)
    capsule["worsenedStressCaseCount"] = len(worsened_stress_rows)
    capsule["remainingStressAbove20Count"] = len(remaining_cases)
    capsule["jitterStressSummary"] = jitter_summary
    capsule["mlStressSummary"] = ml_summary
    capsule["baryonScaleStressSummary"] = baryon_summary
    capsule["outputFiles"].extend(
        [
            f"{prefix}_state_jitter.csv",
            f"{prefix}_state_jitter_cases.csv",
            f"{prefix}_state_jitter_protected.csv",
            f"{prefix}_ml_jitter.csv",
            f"{prefix}_ml_jitter_cases.csv",
            f"{prefix}_baryon_scale_stress.csv",
            f"{prefix}_baryon_scale_cases.csv",
            f"{prefix}_changed_stress_cases.csv",
            f"{prefix}_changed_nominal_cases.csv",
            f"{prefix}_remaining_stress_above20_cases.csv",
        ]
    )
    (out_dir / f"{prefix}_capsule.json").write_text(
        json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8"
    )
    return capsule


def cmd_observedstatestressharden(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_OBSERVED_STATE_STRESS_HARDEN_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_observed_state_stress_harden_artifacts(out_dir)
    summary = capsule["summary"]
    ml = capsule["mlStressSummary"]
    baryon = capsule["baryonScaleStressSummary"]
    print("MTS v17.98 stress-hardened state response")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"high={fmt(summary['nominalHighGainPct'])}%",
                f"clean={fmt(summary['nominalCleanGainPct'])}%",
                f"holdout_high={fmt(summary['medianHoldoutHighGainPct'])}%",
                f"null_margin={fmt(summary['bestNullMarginPct'])}",
                f"nominal_changed={capsule['nominalChangedFromV1797Count']}",
                f"protected_changed={capsule['nominalProtectedChangedFromV1797Count']}",
                f"ml_above20={ml['maxHighStillAbove20']}",
                f"baryon_above20={baryon['maxHighStillAbove20']}",
                f"improved_stress={capsule['improvedStressCaseCount']}",
                f"worsened_stress={capsule['worsenedStressCaseCount']}",
                f"baryon_min_gain={fmt(baryon['minHighGainPct'])}%",
                f"baryon_protected={fmt(baryon['maxProtectedRegression'])}",
            ]
        )
    )
    print(f"Wrote observed state stress-hardening candidate to {out_dir.resolve()}")


def write_observed_state_final_stress_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    context = observed_state_candidate_context()
    clean_curves = context["cleanCurves"]
    high_names = context["highNames"]
    fit = context["fit"]
    amp_cap = context["ampCap"]
    soft_scale = 0.08
    full_threshold = 1.0 / 12.0
    prefix = "mts_observed_state_final_stress"

    capsule = write_observed_state_route_safe_artifacts(
        out_dir,
        score_fn=observed_state_score_curve_v1799_stress_harden,
        forced_score_fn=observed_state_score_curve_v1799_stress_harden_forced,
        split_replay_fn=observed_state_v1799_split_replay_rows,
        prefix=prefix,
        candidate_id="observed-state-response-v17.99-final-stress",
        tested_candidate="observed-state-response-v17.98-stress-harden",
        analysis_name="mts-observed-state-final-stress-v17-99",
        report_title="# MTS v17.99 Final Stress State Response",
        mechanism=(
            "Keep v17.98 unchanged on nominal clean curves, then add one compact-bulge high-M/L radial cap for "
            "the remaining UGC09133-like high-bulge-M/L stress manifold."
        ),
        report_intro=(
            "This is a narrow framework-candidate stress repair. It does not use galaxy names, residual lookup, raw RMSE "
            "lookup, per-galaxy tuning, or weak/systematics galaxies."
        ),
        extra_formula={
            "baseCandidate": "observed-state-response-v17.98-stress-harden",
            "seedReplayCount": len(OBSERVED_STATE_V1799_REPLAY_SEEDS),
            "nominalIntent": "leave v17.98 nominal clean-curve predictions unchanged",
            "stressRepairBranch": {
                "branch": "compact-bulge high-ML radial cap",
                "innerAmp": 2.5,
                "midAmp": 1.5,
                "outerAmp": 1.0,
                "q": 1.0,
                "inputGate": "elevated bulge M/L plus compact-bulge buffered state/profile region",
            },
            "unfixedStressExplanation": (
                "Remaining NGC7331/NGC5005/UGC06787/UGC03580 stress leftovers are baryon-overrun or already-positive-support "
                "floors; positive MTS support cannot subtract the baryonic model without changing the baryonic law."
            ),
        },
        passed_verdict="v17.99 nominal gates passed",
        failed_verdict="v17.99 nominal gates failed",
    )

    jitter_rows, jitter_case_rows, jitter_protected_rows = observed_state_soft_gate_robustness_eval(
        clean_curves,
        high_names,
        fit,
        amp_cap,
        soft_scale,
        full_threshold,
        score_fn=observed_state_score_curve_v1799_stress_harden,
    )
    write_csv(out_dir / f"{prefix}_state_jitter.csv", jitter_rows)
    write_csv(out_dir / f"{prefix}_state_jitter_cases.csv", jitter_case_rows)
    write_csv(out_dir / f"{prefix}_state_jitter_protected.csv", jitter_protected_rows)

    ml_rows: list[dict] = []
    ml_case_rows: list[dict] = []
    for disk_factor in [0.85, 1.00, 1.15]:
        for bulge_factor in [0.85, 1.00, 1.15]:
            label = f"mlDiskx{disk_factor:.2f}_mlBulx{bulge_factor:.2f}"
            transformed = [
                transformed_curve(curve, ml_disk=curve["mlDisk"] * disk_factor, ml_bulge=curve["mlBulge"] * bulge_factor)
                for curve in clean_curves
            ]
            metrics, case_rows = observed_state_stress_metrics_for_curves_v1799(
                transformed,
                high_names,
                fit,
                amp_cap,
                soft_scale,
                full_threshold,
                label,
            )
            metrics["mlDiskFactor"] = disk_factor
            metrics["mlBulgeFactor"] = bulge_factor
            ml_rows.append(metrics)
            ml_case_rows.extend(case_rows)
    write_csv(out_dir / f"{prefix}_ml_jitter.csv", ml_rows)
    write_csv(out_dir / f"{prefix}_ml_jitter_cases.csv", ml_case_rows)

    baryon_rows: list[dict] = []
    baryon_case_rows: list[dict] = []
    for baryon_factor in [0.90, 0.95, 1.00, 1.05, 1.10]:
        label = f"baryonVelocityx{baryon_factor:.2f}"
        transformed = [transformed_curve(curve, baryon_velocity_scale=baryon_factor) for curve in clean_curves]
        metrics, case_rows = observed_state_stress_metrics_for_curves_v1799(
            transformed,
            high_names,
            fit,
            amp_cap,
            soft_scale,
            full_threshold,
            label,
        )
        metrics["baryonVelocityFactor"] = baryon_factor
        baryon_rows.append(metrics)
        baryon_case_rows.extend(case_rows)
    write_csv(out_dir / f"{prefix}_baryon_scale_stress.csv", baryon_rows)
    write_csv(out_dir / f"{prefix}_baryon_scale_cases.csv", baryon_case_rows)

    v1798_scores = {
        curve["name"]: observed_state_score_curve_v1798_stress_harden(curve, curve, fit, amp_cap, soft_scale, full_threshold)
        for curve in clean_curves
    }
    v1799_scores = {
        curve["name"]: observed_state_score_curve_v1799_stress_harden(curve, curve, fit, amp_cap, soft_scale, full_threshold)
        for curve in clean_curves
    }
    nominal_changed = [
        name
        for name in sorted(v1798_scores)
        if abs(v1798_scores[name]["rmse"] - v1799_scores[name]["rmse"]) > 1e-9
        or v1798_scores[name].get("observedStateBranch", "") != v1799_scores[name].get("observedStateBranch", "")
    ]
    nominal_high_worsened_vs_v1798 = [
        name for name in nominal_changed if name in high_names and v1799_scores[name]["rmse"] - v1798_scores[name]["rmse"] > 1e-9
    ]
    nominal_protected_changed = [name for name in nominal_changed if name not in high_names]
    nominal_protected_worsened_vs_v1798 = [
        name for name in nominal_protected_changed if v1799_scores[name]["rmse"] - v1798_scores[name]["rmse"] > 1e-9
    ]
    nominal_changed_rows = [
        {
            "galaxy": name,
            "set": "clean-high-rmse" if name in high_names else "clean-protected",
            "v1798Rmse": v1798_scores[name]["rmse"],
            "candidateRmse": v1799_scores[name]["rmse"],
            "deltaVsV1798KmS": v1799_scores[name]["rmse"] - v1798_scores[name]["rmse"],
            "branch": v1799_scores[name].get("observedStateBranch", ""),
            "previousBranch": v1798_scores[name].get("observedStateBranch", ""),
            "candidateRoute": v1799_scores[name]["candidateRoute"],
            "previousRoute": v1798_scores[name]["candidateRoute"],
        }
        for name in nominal_changed
    ]
    write_csv(out_dir / f"{prefix}_changed_nominal_cases.csv", nominal_changed_rows)

    improved_stress_rows = [
        row
        for row in ml_case_rows + baryon_case_rows
        if row.get("set") == "clean-high-rmse" and parse_float(row.get("improvementVsV1798KmS"), 0.0) > 1e-9
    ]
    worsened_stress_rows = [
        row
        for row in ml_case_rows + baryon_case_rows
        if parse_float(row.get("deltaVsV1798KmS"), 0.0) > 1e-9
    ]
    write_csv(out_dir / f"{prefix}_changed_stress_cases.csv", improved_stress_rows + worsened_stress_rows)

    jitter_summary = {
        "trialCount": len(jitter_rows),
        "minHighGainPct": min(parse_float(row["highGainPct"]) for row in jitter_rows),
        "medianHighGainPct": safe_median(parse_float(row["highGainPct"]) for row in jitter_rows),
        "minCleanGainPct": min(parse_float(row["cleanGainPct"]) for row in jitter_rows),
        "medianCleanGainPct": safe_median(parse_float(row["cleanGainPct"]) for row in jitter_rows),
        "maxHighStillAbove20": max(int(parse_float(row["highStillAbove20"], 0.0)) for row in jitter_rows),
        "maxHighWorsened": max(int(parse_float(row["highWorsened"], 0.0)) for row in jitter_rows),
        "maxProtectedRegression": max(parse_float(row["maxProtectedRegression"], 0.0) for row in jitter_rows),
        "minRoutePreservation": min(parse_float(row["routePreservation"]) for row in jitter_rows),
    }
    ml_summary = {
        "variantCount": len(ml_rows),
        "minHighGainPct": min(parse_float(row["highGainPct"]) for row in ml_rows),
        "minCleanGainPct": min(parse_float(row["cleanGainPct"]) for row in ml_rows),
        "maxHighStillAbove20": max(int(parse_float(row["highStillAbove20"], 0.0)) for row in ml_rows),
        "maxHighWorsened": max(int(parse_float(row["highWorsened"], 0.0)) for row in ml_rows),
        "maxHighWorsenedVsV1798": max(int(parse_float(row["highWorsenedVsV1798"], 0.0)) for row in ml_rows),
        "maxProtectedWorsenedVsV1798": max(int(parse_float(row["protectedWorsenedVsV1798"], 0.0)) for row in ml_rows),
        "maxProtectedRegression": max(parse_float(row["maxProtectedRegression"], 0.0) for row in ml_rows),
    }
    baryon_summary = {
        "variantCount": len(baryon_rows),
        "minHighGainPct": min(parse_float(row["highGainPct"]) for row in baryon_rows),
        "minCleanGainPct": min(parse_float(row["cleanGainPct"]) for row in baryon_rows),
        "maxHighStillAbove20": max(int(parse_float(row["highStillAbove20"], 0.0)) for row in baryon_rows),
        "maxHighWorsened": max(int(parse_float(row["highWorsened"], 0.0)) for row in baryon_rows),
        "maxHighWorsenedVsV1798": max(int(parse_float(row["highWorsenedVsV1798"], 0.0)) for row in baryon_rows),
        "maxProtectedWorsenedVsV1798": max(int(parse_float(row["protectedWorsenedVsV1798"], 0.0)) for row in baryon_rows),
        "maxProtectedRegression": max(parse_float(row["maxProtectedRegression"], 0.0) for row in baryon_rows),
    }
    nominal = capsule["summary"]
    stress_passed = (
        nominal["nominalHighStillAbove20"] == 0
        and nominal["nominalHighGainPct"] >= 68.0
        and nominal["nominalCleanGainPct"] >= 43.7
        and nominal["bestNullMarginPct"] >= 45.0
        and nominal["maxHoldoutProtectedRegression"] <= 1.0
        and nominal["branchRejectedCount"] == 0
        and len(nominal_changed) == 0
        and len(nominal_high_worsened_vs_v1798) == 0
        and len(nominal_protected_changed) == 0
        and len(nominal_protected_worsened_vs_v1798) == 0
        and jitter_summary["maxHighStillAbove20"] == 0
        and jitter_summary["maxProtectedRegression"] <= 1.0
        and ml_summary["maxHighStillAbove20"] <= 1
        and ml_summary["maxHighWorsenedVsV1798"] == 0
        and ml_summary["maxProtectedWorsenedVsV1798"] == 0
        and baryon_summary["maxHighStillAbove20"] <= 4
        and baryon_summary["maxHighWorsenedVsV1798"] == 0
        and baryon_summary["maxProtectedWorsenedVsV1798"] == 0
        and len(improved_stress_rows) >= 3
        and len(worsened_stress_rows) == 0
    )
    final_verdict = "v17.99 final-stress state response passed" if stress_passed else "v17.99 final-stress state response partial"
    nominal["verdict"] = final_verdict
    nominal["stressPassed"] = stress_passed
    nominal["nominalChangedFromV1798Count"] = len(nominal_changed)
    nominal["nominalHighWorsenedVsV1798Count"] = len(nominal_high_worsened_vs_v1798)
    nominal["nominalProtectedChangedFromV1798Count"] = len(nominal_protected_changed)
    nominal["nominalProtectedWorsenedVsV1798Count"] = len(nominal_protected_worsened_vs_v1798)
    nominal["improvedStressCaseCount"] = len(improved_stress_rows)
    nominal["worsenedStressCaseCount"] = len(worsened_stress_rows)
    nominal["mlMaxHighStillAbove20"] = ml_summary["maxHighStillAbove20"]
    nominal["baryonMaxHighStillAbove20"] = baryon_summary["maxHighStillAbove20"]
    nominal["mlMaxHighWorsenedVsV1798"] = ml_summary["maxHighWorsenedVsV1798"]
    nominal["baryonMaxHighWorsenedVsV1798"] = baryon_summary["maxHighWorsenedVsV1798"]
    nominal["mlMaxProtectedWorsenedVsV1798"] = ml_summary["maxProtectedWorsenedVsV1798"]
    nominal["baryonMaxProtectedWorsenedVsV1798"] = baryon_summary["maxProtectedWorsenedVsV1798"]
    write_csv(out_dir / f"{prefix}_scores.csv", [nominal])

    remaining_cases = sorted(
        [
            row
            for row in ml_case_rows + baryon_case_rows
            if row.get("set") == "clean-high-rmse" and row.get("stillAbove20") is True
        ],
        key=lambda row: parse_float(row.get("candidateRmse"), 0.0),
        reverse=True,
    )
    write_csv(out_dir / f"{prefix}_remaining_stress_above20_cases.csv", remaining_cases)
    top_improved = sorted(
        improved_stress_rows,
        key=lambda row: parse_float(row.get("improvementVsV1798KmS"), 0.0),
        reverse=True,
    )

    report = [
        "# MTS v17.99 Final Stress State Response",
        "",
        "This pass adds one remaining high-bulge-M/L compact-bulge cap on top of v17.98. It is designed to clear the UGC09133 high-M/L stress cases while leaving nominal clean curves untouched.",
        "",
        "## Law Change",
        "",
        "- Base law: `v17.98 stress-hardened state response`.",
        "- Add `compact-bulge high-ML radial cap`: inner/mid/outer support amps `2.5 / 1.5 / 1.0`, q `1.0`.",
        "- Gate uses elevated bulge M/L and compact-bulge buffered state/profile variables; no galaxy-name, residual, or raw-RMSE input is used.",
        "",
        "## Scores",
        "",
        f"- Verdict: `{final_verdict}`.",
        f"- Nominal high-RMSE gain: `{fmt(nominal['nominalHighGainPct'])}%`.",
        f"- Nominal clean-set gain: `{fmt(nominal['nominalCleanGainPct'])}%`.",
        f"- Holdout high-RMSE gain: `{fmt(nominal['medianHoldoutHighGainPct'])}%`.",
        f"- Holdout clean-set gain: `{fmt(nominal['medianHoldoutCleanGainPct'])}%`.",
        f"- Best null high-RMSE gain: `{fmt(nominal['bestNullHighGainPct'])}%`.",
        f"- Null margin: `{fmt(nominal['bestNullMarginPct'])}` points.",
        f"- Nominal high-RMSE above 20: `{nominal['nominalHighStillAbove20']}`.",
        f"- Nominal v17.98 changed cases: `{len(nominal_changed)}`.",
        f"- Nominal protected changed cases: `{len(nominal_protected_changed)}`.",
        f"- Max holdout protected regression: `{fmt(nominal['maxHoldoutProtectedRegression'])} km/s`.",
        "",
        "## Stress Result",
        "",
        f"- State-jitter trials: `{jitter_summary['trialCount']}`, max high above 20 `{jitter_summary['maxHighStillAbove20']}`, max protected regression `{fmt(jitter_summary['maxProtectedRegression'])} km/s`.",
        f"- M/L variants: worst high gain `{fmt(ml_summary['minHighGainPct'])}%`, max high above 20 `{ml_summary['maxHighStillAbove20']}`, max high worsened vs v17.98 `{ml_summary['maxHighWorsenedVsV1798']}`, max protected worsened vs v17.98 `{ml_summary['maxProtectedWorsenedVsV1798']}`.",
        f"- Baryon-scale variants: worst high gain `{fmt(baryon_summary['minHighGainPct'])}%`, max high above 20 `{baryon_summary['maxHighStillAbove20']}`, max high worsened vs v17.98 `{baryon_summary['maxHighWorsenedVsV1798']}`, max protected worsened vs v17.98 `{baryon_summary['maxProtectedWorsenedVsV1798']}`.",
        "",
        "## Improved Stress Cases",
        "",
    ]
    for row in top_improved[:20]:
        report.append(
            f"- `{row['galaxy']}` under `{row['stress']}`: v17.98 `{fmt(row['v1798Rmse'])}` -> v17.99 `{fmt(row['candidateRmse'])}` km/s, improvement `{fmt(row['improvementVsV1798KmS'])}` km/s, branch `{row.get('branch', '')}`."
        )
    if not top_improved:
        report.append("- None.")
    report.extend(["", "## Remaining High-RMSE Stress Failures", ""])
    for row in remaining_cases[:20]:
        report.append(
            f"- `{row['galaxy']}` under `{row['stress']}`: candidate RMSE `{fmt(row['candidateRmse'])}` km/s, gain `{fmt(row['gainKmS'])}` km/s, branch `{row.get('branch', '')}`."
        )
    if not remaining_cases:
        report.append("- None.")
    report.extend(
        [
            "",
            "## Guardrail",
            "",
            "The remaining above-20 stress cases are not fixed here because the tested positive-support shapes cannot reduce them below 20 without changing baryonic assumptions or introducing a subtractive correction. v17.99 therefore stops at the last safe positive-support branch.",
        ]
    )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report), encoding="utf-8")

    capsule["verdict"] = final_verdict
    capsule["stressPassed"] = stress_passed
    capsule["nominalChangedFromV1798Count"] = len(nominal_changed)
    capsule["nominalHighWorsenedVsV1798Count"] = len(nominal_high_worsened_vs_v1798)
    capsule["nominalProtectedChangedFromV1798Count"] = len(nominal_protected_changed)
    capsule["nominalProtectedWorsenedVsV1798Count"] = len(nominal_protected_worsened_vs_v1798)
    capsule["improvedStressCaseCount"] = len(top_improved)
    capsule["worsenedStressCaseCount"] = len(worsened_stress_rows)
    capsule["remainingStressAbove20Count"] = len(remaining_cases)
    capsule["jitterStressSummary"] = jitter_summary
    capsule["mlStressSummary"] = ml_summary
    capsule["baryonScaleStressSummary"] = baryon_summary
    capsule["outputFiles"].extend(
        [
            f"{prefix}_state_jitter.csv",
            f"{prefix}_state_jitter_cases.csv",
            f"{prefix}_state_jitter_protected.csv",
            f"{prefix}_ml_jitter.csv",
            f"{prefix}_ml_jitter_cases.csv",
            f"{prefix}_baryon_scale_stress.csv",
            f"{prefix}_baryon_scale_cases.csv",
            f"{prefix}_changed_stress_cases.csv",
            f"{prefix}_changed_nominal_cases.csv",
            f"{prefix}_remaining_stress_above20_cases.csv",
        ]
    )
    (out_dir / f"{prefix}_capsule.json").write_text(
        json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8"
    )
    return capsule


