def observed_state_v18_prune_metric(case_rows: list[dict], high_names: set[str], drop_fn: Callable[[dict], bool]) -> dict:
    clean_rows = [row for row in case_rows if row["set"] != "weak/systematics"]
    high_rows = [row for row in clean_rows if row["galaxy"] in high_names]
    protected_rows = [row for row in clean_rows if row["set"] == "clean-protected"]

    def candidate_rmse(row: dict) -> float:
        return parse_float(row["baselineRmse"]) if drop_fn(row) else parse_float(row["lawNativeRmse"])

    protected_regressions = [candidate_rmse(row) - parse_float(row["baselineRmse"]) for row in protected_rows]
    return {
        "cleanGainPct": pct_improvement(
            safe_mean(parse_float(row["baselineRmse"]) for row in clean_rows),
            safe_mean(candidate_rmse(row) for row in clean_rows),
        ),
        "highGainPct": pct_improvement(
            safe_mean(parse_float(row["baselineRmse"]) for row in high_rows),
            safe_mean(candidate_rmse(row) for row in high_rows),
        ),
        "highAbove20": sum(1 for row in high_rows if candidate_rmse(row) >= 20.0),
        "maxProtectedRegressionKmS": max(protected_regressions or [0.0]),
        "protectedRegressionCount": sum(1 for value in protected_regressions if value > 1e-9),
    }


def write_observed_state_v18_branch_prune_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_observed_v18_branch_prune"
    context = observed_state_candidate_context()
    high_names = context["highNames"]
    artifact_payload = read_window_json_assignment(V18_BROWSER_ARTIFACT_PATH, "MTS_V18_01_REVIEW_CANDIDATE")
    case_rows, parity_rows, law_summary = observed_state_v18_law_native_audit_rows(context, artifact_payload)
    branch_rows = observed_state_v18_branch_summary_rows(case_rows)
    full_metric = observed_state_v18_prune_metric(case_rows, high_names, lambda _row: False)
    full_high_above20 = int(full_metric["highAbove20"])

    active_branches = sorted(
        row["branch"]
        for row in branch_rows
        if row["branch"] != "unbranched canonical" and int(parse_float(row["highHitCount"], 0.0)) > 0
    )
    branch_ablation_rows: list[dict] = []
    for branch in active_branches:
        active_rows = [row for row in case_rows if row["branch"] == branch and row["set"] != "weak/systematics"]
        active_high_rows = [row for row in active_rows if row["galaxy"] in high_names]
        active_protected_rows = [row for row in active_rows if row["set"] == "clean-protected"]
        metric = observed_state_v18_prune_metric(case_rows, high_names, lambda row, item=branch: row["branch"] == item)
        high_above20_delta = int(metric["highAbove20"]) - full_high_above20
        high_gain_loss = parse_float(full_metric["highGainPct"]) - parse_float(metric["highGainPct"])
        zero_gate_break = high_above20_delta > 0
        branch_status = "essential-zero-above20" if zero_gate_break else ("essential-gain-margin" if high_gain_loss >= 5.0 else "prunable")
        branch_ablation_rows.append(
            {
                "branch": branch,
                "family": active_rows[0].get("family", "") if active_rows else "",
                "activeCleanHitCount": len(active_rows),
                "activeHighHitCount": len(active_high_rows),
                "activeProtectedHitCount": len(active_protected_rows),
                "activeHighMeanGainKmS": safe_mean(parse_float(row["lawGainKmS"]) for row in active_high_rows),
                "ablationHighGainPct": metric["highGainPct"],
                "ablationCleanGainPct": metric["cleanGainPct"],
                "ablationHighAbove20": metric["highAbove20"],
                "highAbove20Delta": high_above20_delta,
                "highGainLossPct": high_gain_loss,
                "maxProtectedRegressionKmS": metric["maxProtectedRegressionKmS"],
                "protectedRegressionCount": metric["protectedRegressionCount"],
                "branchStatus": branch_status,
            }
        )

    families = sorted(
        {
            row["family"] or "unfamilied"
            for row in branch_ablation_rows
            if int(parse_float(row["activeHighHitCount"], 0.0)) > 0
        }
    )
    family_ablation_rows: list[dict] = []
    for family in families:
        active_rows = [
            row
            for row in case_rows
            if row["set"] != "weak/systematics"
            and row["branch"]
            and ((row["family"] or "unfamilied") == family)
        ]
        active_high_rows = [row for row in active_rows if row["galaxy"] in high_names]
        active_protected_rows = [row for row in active_rows if row["set"] == "clean-protected"]
        metric = observed_state_v18_prune_metric(
            case_rows,
            high_names,
            lambda row, item=family: bool(row["branch"]) and ((row["family"] or "unfamilied") == item),
        )
        high_above20_delta = int(metric["highAbove20"]) - full_high_above20
        high_gain_loss = parse_float(full_metric["highGainPct"]) - parse_float(metric["highGainPct"])
        family_status = "essential-zero-above20" if high_above20_delta > 0 else ("essential-gain-margin" if high_gain_loss >= 5.0 else "prunable")
        family_ablation_rows.append(
            {
                "family": family,
                "branchCount": len({row["branch"] for row in active_rows}),
                "activeCleanHitCount": len(active_rows),
                "activeHighHitCount": len(active_high_rows),
                "activeProtectedHitCount": len(active_protected_rows),
                "activeHighMeanGainKmS": safe_mean(parse_float(row["lawGainKmS"]) for row in active_high_rows),
                "ablationHighGainPct": metric["highGainPct"],
                "ablationCleanGainPct": metric["cleanGainPct"],
                "ablationHighAbove20": metric["highAbove20"],
                "highAbove20Delta": high_above20_delta,
                "highGainLossPct": high_gain_loss,
                "maxProtectedRegressionKmS": metric["maxProtectedRegressionKmS"],
                "protectedRegressionCount": metric["protectedRegressionCount"],
                "familyStatus": family_status,
            }
        )

    kept_branches = [row["branch"] for row in branch_ablation_rows if row["branchStatus"] != "prunable"]
    dropped_branches = [row["branch"] for row in branch_ablation_rows if row["branchStatus"] == "prunable"]
    minimal_metric = observed_state_v18_prune_metric(
        case_rows,
        high_names,
        lambda row: bool(row["branch"]) and row["branch"] in set(dropped_branches),
    )
    minimal_case_rows = []
    for row in case_rows:
        drop = bool(row["branch"]) and row["branch"] in set(dropped_branches)
        minimal_rmse = parse_float(row["baselineRmse"]) if drop else parse_float(row["lawNativeRmse"])
        minimal_case_rows.append(
            {
                "galaxy": row["galaxy"],
                "set": row["set"],
                "branch": row["branch"],
                "family": row["family"],
                "baselineRmse": row["baselineRmse"],
                "fullV18Rmse": row["lawNativeRmse"],
                "minimalRmse": minimal_rmse,
                "minimalMinusFullKmS": minimal_rmse - parse_float(row["lawNativeRmse"]),
                "droppedByPrune": drop,
                "stillAbove20": minimal_rmse >= 20.0 if row["galaxy"] in high_names else "",
            }
        )

    prunable_count = len(dropped_branches)
    essential_count = len(kept_branches)
    minimal_passes = (
        int(minimal_metric["highAbove20"]) == 0
        and parse_float(minimal_metric["highGainPct"]) >= 60.0
        and parse_float(minimal_metric["maxProtectedRegressionKmS"]) <= 4.0
        and int(law_summary["cleanParityMismatchCount"]) == 0
        and int(law_summary["weakSystematicsLeakage"]) == 0
    )
    if prunable_count == 0 and minimal_passes:
        verdict = "v18 branch set irreducible under zero-above20 gate"
    elif minimal_passes:
        verdict = "minimal v18 candidate passes"
    else:
        verdict = "minimal pruning blocked"

    summary = {
        "candidateId": "observed-state-response-v18.01-branch-prune",
        "verdict": verdict,
        "fullHighGainPct": full_metric["highGainPct"],
        "fullCleanGainPct": full_metric["cleanGainPct"],
        "fullHighAbove20": full_metric["highAbove20"],
        "fullMaxProtectedRegressionKmS": full_metric["maxProtectedRegressionKmS"],
        "activeBranchCount": len(active_branches),
        "essentialBranchCount": essential_count,
        "prunableBranchCount": prunable_count,
        "droppedBranches": "; ".join(dropped_branches),
        "minimalHighGainPct": minimal_metric["highGainPct"],
        "minimalCleanGainPct": minimal_metric["cleanGainPct"],
        "minimalHighAbove20": minimal_metric["highAbove20"],
        "minimalMaxProtectedRegressionKmS": minimal_metric["maxProtectedRegressionKmS"],
        "minimalEqualsFull": prunable_count == 0,
        "cleanParityMismatchCount": law_summary["cleanParityMismatchCount"],
        "weakSystematicsLeakage": law_summary["weakSystematicsLeakage"],
        "nullMarginKmS": artifact_payload.get("metadata", {}).get("lawNativeVerification", {}).get("nullMarginKmS", math.nan),
    }

    artifact_payload.setdefault("metadata", {})["branchPrune"] = {
        "verdict": verdict,
        "activeBranchCount": len(active_branches),
        "essentialBranchCount": essential_count,
        "prunableBranchCount": prunable_count,
        "minimalEqualsFull": prunable_count == 0,
        "minimalHighGainPct": minimal_metric["highGainPct"],
        "minimalHighAbove20": minimal_metric["highAbove20"],
        "minimalMaxProtectedRegressionKmS": minimal_metric["maxProtectedRegressionKmS"],
    }
    write_window_json_assignment(V18_BROWSER_ARTIFACT_PATH, "MTS_V18_01_REVIEW_CANDIDATE", artifact_payload)
    write_window_json_assignment(out_dir / f"{prefix}_browser_artifact.js", "MTS_V18_01_REVIEW_CANDIDATE", artifact_payload)

    write_csv(out_dir / f"{prefix}_scores.csv", [summary])
    write_csv(out_dir / f"{prefix}_branch_ablation.csv", branch_ablation_rows)
    write_csv(out_dir / f"{prefix}_family_ablation.csv", family_ablation_rows)
    write_csv(out_dir / f"{prefix}_minimal_candidate_scores.csv", [minimal_metric])
    write_csv(out_dir / f"{prefix}_minimal_case_ledger.csv", minimal_case_rows)
    write_csv(out_dir / f"{prefix}_case_ledger.csv", case_rows)

    report = [
        "# MTS v18.01 Branch Pruning Audit",
        "",
        "This audit removes each active v18 branch or branch family in turn. An ablated branch falls back to the locked canonical score for the cases it alone repairs, so the test asks whether that branch is genuinely carrying high-RMSE repair weight.",
        "",
        "## Result",
        "",
        f"- Verdict: `{verdict}`.",
        f"- Full v18 high-RMSE gain: `{fmt(full_metric['highGainPct'])}%`.",
        f"- Full v18 clean gain: `{fmt(full_metric['cleanGainPct'])}%`.",
        f"- Full v18 high-RMSE above 20: `{full_metric['highAbove20']}`.",
        f"- Active branches: `{len(active_branches)}`.",
        f"- Essential branches: `{essential_count}`.",
        f"- Prunable branches: `{prunable_count}`.",
        f"- Minimal high-RMSE gain: `{fmt(minimal_metric['highGainPct'])}%`.",
        f"- Minimal high-RMSE above 20: `{minimal_metric['highAbove20']}`.",
        f"- Minimal max protected regression: `{fmt(minimal_metric['maxProtectedRegressionKmS'])}` km/s.",
        f"- Weak/systematics leakage: `{law_summary['weakSystematicsLeakage']}`.",
        "",
        "## Essential Families",
        "",
    ]
    for row in family_ablation_rows:
        report.append(
            f"- `{row['family']}`: `{row['familyStatus']}`, high hits `{row['activeHighHitCount']}`, ablation above-20 `{row['ablationHighAbove20']}`, high-gain loss `{fmt(row['highGainLossPct'])}` points."
        )
    report.extend(["", "## Interpretation", ""])
    if prunable_count == 0:
        report.append(
            "No active branch can be removed while preserving the zero-above-20 high-RMSE gate. The apparent branch count is therefore not currently decorative; the compact defence is by branch family rather than by deleting individual high-only repair branches."
        )
    else:
        report.append(
            "The minimal candidate drops only branches whose removal preserves the zero-above-20 gate, protected safety, weak exclusion, and parity checks."
        )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report), encoding="utf-8")

    capsule = {
        "analysisName": "mts-observed-v18-branch-prune-v1",
        "candidateId": summary["candidateId"],
        "verdict": verdict,
        "summary": summary,
        "outputFiles": [
            f"{prefix}_scores.csv",
            f"{prefix}_branch_ablation.csv",
            f"{prefix}_family_ablation.csv",
            f"{prefix}_minimal_candidate_scores.csv",
            f"{prefix}_minimal_case_ledger.csv",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_browser_artifact.js",
            f"{prefix}_report.md",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_observedstatev18branchprune(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_OBSERVED_STATE_V18_BRANCH_PRUNE_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_observed_state_v18_branch_prune_artifacts(out_dir)
    summary = capsule["summary"]
    print("MTS v18.01 branch pruning audit")
    print(f"verdict={summary['verdict']}")
    print(
        "\t".join(
            [
                f"full_high={fmt(summary['fullHighGainPct'])}%",
                f"minimal_high={fmt(summary['minimalHighGainPct'])}%",
                f"above20={summary['minimalHighAbove20']}",
                f"essential={summary['essentialBranchCount']}",
                f"prunable={summary['prunableBranchCount']}",
                f"protected={fmt(summary['minimalMaxProtectedRegressionKmS'])}",
                f"weak_leakage={summary['weakSystematicsLeakage']}",
            ]
        )
    )
    print(f"Wrote v18 branch pruning audit to {out_dir.resolve()}")


OBSERVED_STATE_V18_FAMILY_AUDIT_SEEDS = OBSERVED_STATE_V1800_REPLAY_SEEDS
OBSERVED_STATE_V18_FAMILY_BOUNDARY_FEATURES = [
    "memoryLoad",
    "u075",
    "uOut",
    "uMax",
    "LgapOverH",
    "hOverRout",
    "fGasOut",
    "innerGasShare",
    "midGasShare",
    "outerGasShare",
    "innerDiskShare",
    "midDiskShare",
    "outerDiskShare",
    "innerBulgeShare",
    "midBulgeShare",
    "outerBulgeShare",
    "barInnerOuter",
    "barMidOuter",
    "barCurv",
    "pointDensity",
]


def observed_state_v18_family_name(row: dict) -> str:
    return row.get("family") or "unfamilied"


def observed_state_v18_state_values(curve: dict) -> dict:
    values = observed_state_values(curve)
    values.update(
        {
            "u075": curve.get("lockedModelU075", math.nan),
            "uOut": curve.get("lockedModelUOut", values.get("uOut", math.nan)),
            "uMax": curve.get("lockedModelUMax", values.get("uMax", math.nan)),
            "fGasOut": curve.get("fGasOut", values.get("fGasOut", math.nan)),
            "leffOverH": curve["leff"] / max(curve["h"], 1e-9),
            "rOutOverH": curve["rOut"] / max(curve["h"], 1e-9),
        }
    )
    return values


def observed_state_v18_row_gain_pct(rows: list[dict]) -> float:
    return pct_improvement(
        safe_mean(parse_float(row["baselineRmse"]) for row in rows),
        safe_mean(parse_float(row["lawNativeRmse"]) for row in rows),
    )


def observed_state_v18_family_null_rows(
    case_rows: list[dict],
    family: str,
    seeds: list[int],
) -> tuple[list[dict], dict]:
    high_rows = [row for row in case_rows if row["set"] == "clean-high-rmse"]
    family_high_rows = [
        row
        for row in high_rows
        if row.get("branch") and observed_state_v18_family_name(row) == family
    ]
    if not family_high_rows:
        return [], {
            "family": family,
            "actualHighGainPct": math.nan,
            "medianSameCountNullGainPct": math.nan,
            "sameCountNullMarginPct": math.nan,
            "sameCountNullBeat": False,
        }

    actual_gain_pct = observed_state_v18_row_gain_pct(family_high_rows)
    family_names = {row["galaxy"] for row in family_high_rows}
    route_counts: dict[str, int] = {}
    for row in family_high_rows:
        route_counts[row["lockedRoute"]] = route_counts.get(row["lockedRoute"], 0) + 1
    fallback_pool = [row for row in high_rows if row["galaxy"] not in family_names]
    rows: list[dict] = []
    for seed in seeds:
        rng = random.Random(f"v18-family-null:{family}:{seed}")
        selected: list[dict] = []
        used: set[str] = set()
        for route, count in sorted(route_counts.items()):
            pool = [row for row in fallback_pool if row["lockedRoute"] == route and row["galaxy"] not in used]
            rng.shuffle(pool)
            selected.extend(pool[:count])
            used.update(row["galaxy"] for row in pool[:count])
        if len(selected) < len(family_high_rows):
            remaining = [row for row in fallback_pool if row["galaxy"] not in used]
            rng.shuffle(remaining)
            selected.extend(remaining[: len(family_high_rows) - len(selected)])
        null_gain_pct = observed_state_v18_row_gain_pct(selected)
        rows.append(
            {
                "family": family,
                "seed": seed,
                "activeHighHitCount": len(family_high_rows),
                "actualHighGainPct": actual_gain_pct,
                "sameCountNullHighGainPct": null_gain_pct,
                "sameCountNullMarginPct": actual_gain_pct - null_gain_pct,
                "selectedGalaxies": "; ".join(sorted(row["galaxy"] for row in selected)),
            }
        )
    margins = [parse_float(row["sameCountNullMarginPct"]) for row in rows]
    summary = {
        "family": family,
        "actualHighGainPct": actual_gain_pct,
        "medianSameCountNullGainPct": safe_median(row["sameCountNullHighGainPct"] for row in rows),
        "sameCountNullMarginPct": safe_median(margins),
        "sameCountNullBeat": safe_median(margins) >= 10.0,
    }
    return rows, summary


def observed_state_v18_family_holdout_rows(case_rows: list[dict], family: str, clean_curves: list[dict], seeds: list[int]) -> tuple[list[dict], dict]:
    family_high_by_name = {
        row["galaxy"]: row
        for row in case_rows
        if row["set"] == "clean-high-rmse"
        and row.get("branch")
        and observed_state_v18_family_name(row) == family
    }
    rows: list[dict] = []
    for seed in seeds:
        _train_names, holdout_names = observed_state_split(clean_curves, seed, HOLDOUT_FRACTION)
        holdout_family_rows = [row for name, row in family_high_by_name.items() if name in holdout_names]
        rows.append(
            {
                "family": family,
                "seed": seed,
                "holdoutFamilyHighHitCount": len(holdout_family_rows),
                "holdoutFamilyHighGainPct": observed_state_v18_row_gain_pct(holdout_family_rows),
                "holdoutFamilyAbove20": sum(1 for row in holdout_family_rows if parse_float(row["lawNativeRmse"]) >= 20.0),
                "holdoutFamilyGalaxies": "; ".join(sorted(row["galaxy"] for row in holdout_family_rows)),
            }
        )
    summary = {
        "family": family,
        "holdoutPresenceRate": safe_mean(1.0 if row["holdoutFamilyHighHitCount"] > 0 else 0.0 for row in rows),
        "medianHoldoutHighGainPct": safe_median(row["holdoutFamilyHighGainPct"] for row in rows if row["holdoutFamilyHighHitCount"] > 0),
        "maxHoldoutAbove20": max([row["holdoutFamilyAbove20"] for row in rows] or [0]),
    }
    return rows, summary


def observed_state_v18_family_boundary_rows(case_rows: list[dict], curves_by_name: dict[str, dict], families: list[str]) -> list[dict]:
    rows: list[dict] = []
    for family in families:
        family_names = [
            row["galaxy"]
            for row in case_rows
            if row["set"] != "weak/systematics"
            and row.get("branch")
            and observed_state_v18_family_name(row) == family
        ]
        for feature in OBSERVED_STATE_V18_FAMILY_BOUNDARY_FEATURES:
            values = []
            for name in family_names:
                curve = curves_by_name.get(name)
                if not curve:
                    continue
                value = observed_state_v18_state_values(curve).get(feature, math.nan)
                if math.isfinite(parse_float(value, math.nan)):
                    values.append(float(value))
            if not values:
                continue
            rows.append(
                {
                    "family": family,
                    "feature": feature,
                    "hitCount": len(values),
                    "min": min(values),
                    "median": safe_median(values),
                    "max": max(values),
                }
            )
    return rows


def write_observed_state_v18_family_audit_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_observed_v18_family_audit"
    context = observed_state_candidate_context()
    high_names = context["highNames"]
    clean_curves = context["cleanCurves"]
    curves_by_name = {curve["name"]: curve for curve in context["curves"]}
    artifact_payload = read_window_json_assignment(V18_BROWSER_ARTIFACT_PATH, "MTS_V18_01_REVIEW_CANDIDATE")
    case_rows, _parity_rows, law_summary = observed_state_v18_law_native_audit_rows(context, artifact_payload)
    full_metric = observed_state_v18_prune_metric(case_rows, high_names, lambda _row: False)
    full_high_above20 = int(full_metric["highAbove20"])
    branch_rows = observed_state_v18_branch_summary_rows(case_rows)
    active_families = sorted(
        {
            observed_state_v18_family_name(row)
            for row in case_rows
            if row["set"] != "weak/systematics"
            and row.get("branch")
            and row["galaxy"] in high_names
        }
    )

    family_null_rows: list[dict] = []
    family_null_summary_by_name: dict[str, dict] = {}
    holdout_rows: list[dict] = []
    holdout_summary_by_name: dict[str, dict] = {}
    family_ledger_rows: list[dict] = []
    for family in active_families:
        null_rows, null_summary = observed_state_v18_family_null_rows(case_rows, family, OBSERVED_STATE_V18_FAMILY_AUDIT_SEEDS)
        family_null_rows.extend(null_rows)
        family_null_summary_by_name[family] = null_summary
        rows, holdout_summary = observed_state_v18_family_holdout_rows(case_rows, family, clean_curves, OBSERVED_STATE_V18_FAMILY_AUDIT_SEEDS)
        holdout_rows.extend(rows)
        holdout_summary_by_name[family] = holdout_summary

        active_rows = [
            row
            for row in case_rows
            if row["set"] != "weak/systematics"
            and row.get("branch")
            and observed_state_v18_family_name(row) == family
        ]
        active_high_rows = [row for row in active_rows if row["galaxy"] in high_names]
        active_protected_rows = [row for row in active_rows if row["set"] == "clean-protected"]
        active_protected_regressions = [parse_float(row["lawNativeRmse"]) - parse_float(row["baselineRmse"]) for row in active_protected_rows]
        metric = observed_state_v18_prune_metric(
            case_rows,
            high_names,
            lambda row, item=family: bool(row.get("branch")) and observed_state_v18_family_name(row) == item,
        )
        high_above20_delta = int(metric["highAbove20"]) - full_high_above20
        high_gain_loss = parse_float(full_metric["highGainPct"]) - parse_float(metric["highGainPct"])
        null_margin = parse_float(null_summary.get("sameCountNullMarginPct"), math.nan)
        holdout_presence = parse_float(holdout_summary.get("holdoutPresenceRate"), math.nan)
        protected_max = max(active_protected_regressions or [0.0])
        one_galaxy_patch = len(active_high_rows) <= 1
        if one_galaxy_patch:
            verdict = "too narrow"
        elif protected_max > 3.0:
            verdict = "protected-risk family"
        elif null_margin < 10.0:
            verdict = "fails null"
        elif len(active_high_rows) < 3:
            verdict = "edge-case family"
        elif high_gain_loss >= 5.0 and high_above20_delta > 0 and holdout_presence >= 0.5:
            verdict = "stable family"
        elif high_gain_loss >= 5.0 or high_above20_delta > 0:
            verdict = "edge-case family"
        else:
            verdict = "too narrow"
        family_ledger_rows.append(
            {
                "family": family,
                "verdict": verdict,
                "branchCount": len({row["branch"] for row in active_rows}),
                "activeCleanHitCount": len(active_rows),
                "activeHighHitCount": len(active_high_rows),
                "activeProtectedHitCount": len(active_protected_rows),
                "activeHighMeanGainKmS": safe_mean(parse_float(row["lawGainKmS"]) for row in active_high_rows),
                "activeHighGainPct": observed_state_v18_row_gain_pct(active_high_rows),
                "ablationHighGainPct": metric["highGainPct"],
                "highGainLossPct": high_gain_loss,
                "ablationHighAbove20": metric["highAbove20"],
                "highAbove20Delta": high_above20_delta,
                "sameCountNullMarginPct": null_margin,
                "sameCountNullBeat": null_margin >= 10.0,
                "holdoutPresenceRate": holdout_presence,
                "medianHoldoutHighGainPct": holdout_summary.get("medianHoldoutHighGainPct", math.nan),
                "maxProtectedRegressionKmS": protected_max,
                "protectedWorseCount": sum(1 for value in active_protected_regressions if value > 1e-9),
                "oneGalaxyPatchFlag": one_galaxy_patch,
                "branches": "; ".join(sorted({row["branch"] for row in active_rows})),
                "highGalaxies": "; ".join(sorted(row["galaxy"] for row in active_high_rows)),
                "protectedGalaxies": "; ".join(sorted(row["galaxy"] for row in active_protected_rows)),
            }
        )

    boundary_rows = observed_state_v18_family_boundary_rows(case_rows, curves_by_name, active_families)
    family_ledger_rows.sort(
        key=lambda row: (
            {"stable family": 0, "edge-case family": 1, "fails null": 2, "protected-risk family": 3, "too narrow": 4}.get(row["verdict"], 9),
            -parse_float(row["activeHighHitCount"]),
            row["family"],
        )
    )
    stable_count = sum(1 for row in family_ledger_rows if row["verdict"] == "stable family")
    edge_count = sum(1 for row in family_ledger_rows if row["verdict"] == "edge-case family")
    fail_null_count = sum(1 for row in family_ledger_rows if row["verdict"] == "fails null")
    too_narrow_count = sum(1 for row in family_ledger_rows if row["verdict"] == "too narrow")
    protected_risk_count = sum(1 for row in family_ledger_rows if row["verdict"] == "protected-risk family")
    active_high_hit_count = sum(int(parse_float(row["activeHighHitCount"], 0.0)) for row in family_ledger_rows)
    high_rows = [row for row in case_rows if row["set"] == "clean-high-rmse"]
    unbranched_high_count = sum(1 for row in high_rows if not row.get("branch"))
    if stable_count >= 5 and fail_null_count == 0 and protected_risk_count == 0:
        verdict = "v18 family structure defensible with edge-case tail" if edge_count or too_narrow_count else "v18 family structure defensible"
    elif stable_count >= 4 and protected_risk_count == 0:
        verdict = "v18 family structure partially defensible"
    else:
        verdict = "v18 family structure blocked"
    summary = {
        "candidateId": "observed-state-response-v18.01-family-audit",
        "verdict": verdict,
        "fullHighGainPct": full_metric["highGainPct"],
        "fullCleanGainPct": full_metric["cleanGainPct"],
        "fullHighAbove20": full_metric["highAbove20"],
        "familyCount": len(active_families),
        "stableFamilyCount": stable_count,
        "edgeCaseFamilyCount": edge_count,
        "failNullFamilyCount": fail_null_count,
        "tooNarrowFamilyCount": too_narrow_count,
        "protectedRiskFamilyCount": protected_risk_count,
        "activeHighHitCount": active_high_hit_count,
        "unbranchedHighCount": unbranched_high_count,
        "activeBranchCount": sum(1 for row in branch_rows if row["branch"] != "unbranched canonical" and int(parse_float(row["highHitCount"], 0.0)) > 0),
        "maxFamilyProtectedRegressionKmS": max([parse_float(row["maxProtectedRegressionKmS"], 0.0) for row in family_ledger_rows] or [0.0]),
        "minFamilyNullMarginPct": min([parse_float(row["sameCountNullMarginPct"], math.nan) for row in family_ledger_rows] or [math.nan]),
        "weakSystematicsLeakage": law_summary["weakSystematicsLeakage"],
        "cleanParityMismatchCount": law_summary["cleanParityMismatchCount"],
    }

    artifact_payload.setdefault("metadata", {})["familyAudit"] = {
        "verdict": verdict,
        "familyCount": len(active_families),
        "stableFamilyCount": stable_count,
        "edgeCaseFamilyCount": edge_count,
        "failNullFamilyCount": fail_null_count,
        "tooNarrowFamilyCount": too_narrow_count,
        "protectedRiskFamilyCount": protected_risk_count,
        "activeHighHitCount": active_high_hit_count,
        "unbranchedHighCount": unbranched_high_count,
        "weakSystematicsLeakage": law_summary["weakSystematicsLeakage"],
        "cleanParityMismatchCount": law_summary["cleanParityMismatchCount"],
    }
    write_window_json_assignment(V18_BROWSER_ARTIFACT_PATH, "MTS_V18_01_REVIEW_CANDIDATE", artifact_payload)
    write_window_json_assignment(out_dir / f"{prefix}_browser_artifact.js", "MTS_V18_01_REVIEW_CANDIDATE", artifact_payload)

    write_csv(out_dir / f"{prefix}_scores.csv", [summary])
    write_csv(out_dir / f"{prefix}_family_ledger.csv", family_ledger_rows)
    write_csv(out_dir / f"{prefix}_family_nulls.csv", family_null_rows)
    write_csv(out_dir / f"{prefix}_holdout_stability.csv", holdout_rows)
    write_csv(out_dir / f"{prefix}_state_boundaries.csv", boundary_rows)
    write_csv(out_dir / f"{prefix}_case_ledger.csv", case_rows)

    report = [
        "# MTS v18.01 Family Audit",
        "",
        "This audit keeps the v18.01 law frozen and asks whether its essential high-RMSE repairs form repeatable state families rather than one-galaxy patches.",
        "",
        "## Result",
        "",
        f"- Verdict: `{verdict}`.",
        f"- Full high-RMSE gain: `{fmt(summary['fullHighGainPct'])}%`.",
        f"- Full clean-set gain: `{fmt(summary['fullCleanGainPct'])}%`.",
        f"- High-RMSE cases still above 20 km/s: `{summary['fullHighAbove20']}`.",
        f"- Active families: `{summary['familyCount']}`.",
        f"- Stable families: `{stable_count}`.",
        f"- Edge-case families: `{edge_count}`.",
        f"- Families failing same-count null: `{fail_null_count}`.",
        f"- Too-narrow families: `{too_narrow_count}`.",
        f"- Active high-RMSE branch hits: `{active_high_hit_count}`.",
        f"- Unbranched high-RMSE cases: `{unbranched_high_count}`.",
        f"- Max family protected regression: `{fmt(summary['maxFamilyProtectedRegressionKmS'])}` km/s.",
        f"- Weak/systematics leakage: `{summary['weakSystematicsLeakage']}`.",
        "",
        "## Family Ledger",
        "",
        "| Family | Verdict | Branches | High hits | Gain loss | Null margin | Holdout presence | Protected max |",
        "| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: |",
    ]
    for row in family_ledger_rows:
        report.append(
            f"| {row['family']} | {row['verdict']} | {row['branchCount']} | {row['activeHighHitCount']} | "
            f"{fmt(row['highGainLossPct'])} | {fmt(row['sameCountNullMarginPct'])} | {fmt(row['holdoutPresenceRate'], 3)} | {fmt(row['maxProtectedRegressionKmS'])} |"
        )
    report.extend(
        [
            "",
            "## Interpretation",
            "",
            "A family is treated as stable only when ablating it reopens high-RMSE failures, it beats same-active-count branch-target nulls by at least 10 percentage points, it appears in route-stratified holdouts, and it does not introduce protected regressions.",
            "The audit does not change the v18 law. It strengthens or weakens the case that the existing branches are framework structure rather than target lookup.",
        ]
    )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report), encoding="utf-8")

    capsule = {
        "analysisName": "mts-observed-v18-family-audit-v1",
        "candidateId": summary["candidateId"],
        "verdict": verdict,
        "summary": summary,
        "outputFiles": [
            f"{prefix}_scores.csv",
            f"{prefix}_family_ledger.csv",
            f"{prefix}_family_nulls.csv",
            f"{prefix}_holdout_stability.csv",
            f"{prefix}_state_boundaries.csv",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_browser_artifact.js",
            f"{prefix}_report.md",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_observedstatev18familyaudit(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_OBSERVED_STATE_V18_FAMILY_AUDIT_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_observed_state_v18_family_audit_artifacts(out_dir)
    summary = capsule["summary"]
    print("MTS v18.01 family audit")
    print(f"verdict={summary['verdict']}")
    print(
        "\t".join(
            [
                f"high={fmt(summary['fullHighGainPct'])}%",
                f"clean={fmt(summary['fullCleanGainPct'])}%",
                f"above20={summary['fullHighAbove20']}",
                f"families={summary['familyCount']}",
                f"stable={summary['stableFamilyCount']}",
                f"edge={summary['edgeCaseFamilyCount']}",
                f"fails_null={summary['failNullFamilyCount']}",
                f"protected={fmt(summary['maxFamilyProtectedRegressionKmS'])}",
                f"weak_leakage={summary['weakSystematicsLeakage']}",
            ]
        )
    )
    print(f"Wrote v18 family audit to {out_dir.resolve()}")


OBSERVED_STATE_V18_BRANCH_IDENTITY_SEEDS = OBSERVED_STATE_V1800_REPLAY_SEEDS
OBSERVED_STATE_V18_BRANCH_IDENTITY_ANALOG_COUNT = 5


def observed_state_v18_branch_identity_scaler(clean_curves: list[dict]) -> dict:
    raw = {curve["name"]: observed_state_v18_state_values(curve) for curve in clean_curves}
    means: dict[str, float] = {}
    scales: dict[str, float] = {}
    for feature in OBSERVED_STATE_V18_FAMILY_BOUNDARY_FEATURES:
        values = [parse_float(values.get(feature), math.nan) for values in raw.values()]
        values = [value for value in values if math.isfinite(value)]
        means[feature] = safe_mean(values)
        variance = sum((value - means[feature]) ** 2 for value in values) / max(1, len(values) - 1)
        scales[feature] = math.sqrt(variance) or 1.0
    return {"raw": raw, "means": means, "scales": scales}


def observed_state_v18_branch_identity_vector(name: str, scaler: dict) -> list[float]:
    raw_values = scaler["raw"].get(name, {})
    return [
        (parse_float(raw_values.get(feature), scaler["means"][feature]) - scaler["means"][feature]) / scaler["scales"][feature]
        for feature in OBSERVED_STATE_V18_FAMILY_BOUNDARY_FEATURES
    ]


def observed_state_v18_branch_identity_distance(name_a: str, name_b: str, scaler: dict) -> float:
    a = observed_state_v18_branch_identity_vector(name_a, scaler)
    b = observed_state_v18_branch_identity_vector(name_b, scaler)
    return math.sqrt(sum((left - right) ** 2 for left, right in zip(a, b)) / max(1, len(a)))


def observed_state_v18_forced_branch_score(curve: dict, branch: str) -> dict:
    return observed_state_score_curve_v1800_baryon_guard_forced(curve, curve, branch, 1.0)


def observed_state_v18_branch_identity_null_rows(
    branch: str,
    active_high_rows: list[dict],
    high_rows: list[dict],
    curves_by_name: dict[str, dict],
    seeds: list[int],
) -> tuple[list[dict], dict]:
    if not active_high_rows:
        return [], {
            "branch": branch,
            "actualHighGainPct": math.nan,
            "medianSameRouteForcedNullGainPct": math.nan,
            "sameRouteForcedNullMarginPct": math.nan,
            "branchNullBeat": False,
        }
    actual_gain_pct = observed_state_v18_row_gain_pct(active_high_rows)
    active_names = {row["galaxy"] for row in active_high_rows}
    route_counts: dict[str, int] = {}
    for row in active_high_rows:
        route_counts[row["lockedRoute"]] = route_counts.get(row["lockedRoute"], 0) + 1
    pool = [row for row in high_rows if row["galaxy"] not in active_names]
    rows: list[dict] = []
    for seed in seeds:
        rng = random.Random(f"v18-branch-identity-null:{branch}:{seed}")
        selected: list[dict] = []
        used: set[str] = set()
        for route, count in sorted(route_counts.items()):
            route_pool = [row for row in pool if row["lockedRoute"] == route and row["galaxy"] not in used]
            rng.shuffle(route_pool)
            selected.extend(route_pool[:count])
            used.update(row["galaxy"] for row in route_pool[:count])
        if len(selected) < len(active_high_rows):
            fallback = [row for row in pool if row["galaxy"] not in used]
            rng.shuffle(fallback)
            selected.extend(fallback[: len(active_high_rows) - len(selected)])
        forced_pairs = []
        for row in selected:
            curve = curves_by_name[row["galaxy"]]
            baseline = score_curve(curve)
            forced = observed_state_v18_forced_branch_score(curve, branch)
            forced_pairs.append((row, baseline, forced))
        null_gain_pct = pct_improvement(
            safe_mean(pair[1]["rmse"] for pair in forced_pairs),
            safe_mean(pair[2]["rmse"] for pair in forced_pairs),
        )
        max_regression = max([pair[2]["rmse"] - pair[1]["rmse"] for pair in forced_pairs] or [0.0])
        rows.append(
            {
                "branch": branch,
                "seed": seed,
                "activeHighHitCount": len(active_high_rows),
                "actualHighGainPct": actual_gain_pct,
                "sameRouteForcedNullGainPct": null_gain_pct,
                "sameRouteForcedNullMarginPct": actual_gain_pct - null_gain_pct,
                "sameRouteForcedNullMaxRegressionKmS": max_regression,
                "selectedGalaxies": "; ".join(sorted(row["galaxy"] for row in selected)),
            }
        )
    margin = safe_median(row["sameRouteForcedNullMarginPct"] for row in rows)
    summary = {
        "branch": branch,
        "actualHighGainPct": actual_gain_pct,
        "medianSameRouteForcedNullGainPct": safe_median(row["sameRouteForcedNullGainPct"] for row in rows),
        "sameRouteForcedNullMarginPct": margin,
        "branchNullBeat": margin >= 10.0,
    }
    return rows, summary


def observed_state_v18_branch_identity_protected_analogues(
    branch: str,
    active_high_rows: list[dict],
    protected_rows: list[dict],
    curves_by_name: dict[str, dict],
    scaler: dict,
    analog_count: int,
) -> tuple[list[dict], dict]:
    if not active_high_rows:
        return [], {"branch": branch, "maxProtectedAnalogueRegressionKmS": 0.0, "protectedAnalogueWorseCount": 0}
    active_names = [row["galaxy"] for row in active_high_rows]
    branch_route = observed_state_branch_locked_route(branch)
    candidates = []
    for row in protected_rows:
        if branch_route and row["lockedRoute"] != branch_route:
            continue
        distance = min(observed_state_v18_branch_identity_distance(row["galaxy"], active, scaler) for active in active_names)
        candidates.append((distance, row))
    candidates.sort(key=lambda item: (item[0], item[1]["galaxy"]))
    rows: list[dict] = []
    for rank, (distance, row) in enumerate(candidates[:analog_count], start=1):
        curve = curves_by_name[row["galaxy"]]
        baseline = score_curve(curve)
        forced = observed_state_v18_forced_branch_score(curve, branch)
        rows.append(
            {
                "branch": branch,
                "family": observed_state_branch_family(branch),
                "rank": rank,
                "protectedGalaxy": row["galaxy"],
                "lockedRoute": row["lockedRoute"],
                "nearestHighBranchGalaxy": min(
                    active_names,
                    key=lambda name: observed_state_v18_branch_identity_distance(row["galaxy"], name, scaler),
                ),
                "stateDistance": distance,
                "baselineRmse": baseline["rmse"],
                "forcedRmse": forced["rmse"],
                "forcedRegressionKmS": forced["rmse"] - baseline["rmse"],
                "forcedCandidateRoute": forced.get("candidateRoute", ""),
                "forcedBranchReported": forced.get("observedStateBranch", ""),
                "forcedFamilyReported": forced.get("observedStateFamily", ""),
            }
        )
    summary = {
        "branch": branch,
        "maxProtectedAnalogueRegressionKmS": max([row["forcedRegressionKmS"] for row in rows] or [0.0]),
        "protectedAnalogueWorseCount": sum(1 for row in rows if row["forcedRegressionKmS"] > 1e-9),
        "protectedAnalogueStressCount": sum(1 for row in rows if row["forcedRegressionKmS"] > 3.0),
    }
    return rows, summary


def observed_state_v18_branch_identity_holdout_rows(
    branch: str,
    active_high_rows: list[dict],
    clean_curves: list[dict],
    seeds: list[int],
) -> tuple[list[dict], dict]:
    active_high_by_name = {row["galaxy"]: row for row in active_high_rows}
    rows: list[dict] = []
    for seed in seeds:
        _train_names, holdout_names = observed_state_split(clean_curves, seed, HOLDOUT_FRACTION)
        holdout_rows = [row for name, row in active_high_by_name.items() if name in holdout_names]
        rows.append(
            {
                "branch": branch,
                "seed": seed,
                "holdoutBranchHighHitCount": len(holdout_rows),
                "holdoutBranchHighGainPct": observed_state_v18_row_gain_pct(holdout_rows),
                "holdoutBranchAbove20": sum(1 for row in holdout_rows if parse_float(row["lawNativeRmse"]) >= 20.0),
                "holdoutBranchGalaxies": "; ".join(sorted(row["galaxy"] for row in holdout_rows)),
            }
        )
    summary = {
        "branch": branch,
        "holdoutPresenceRate": safe_mean(1.0 if row["holdoutBranchHighHitCount"] > 0 else 0.0 for row in rows),
        "medianHoldoutHighGainPct": safe_median(row["holdoutBranchHighGainPct"] for row in rows if row["holdoutBranchHighHitCount"] > 0),
        "maxHoldoutAbove20": max([row["holdoutBranchAbove20"] for row in rows] or [0]),
    }
    return rows, summary


def observed_state_v18_branch_identity_surface_rows(
    branch: str,
    active_rows: list[dict],
    curves_by_name: dict[str, dict],
) -> list[dict]:
    rows: list[dict] = []
    for feature in OBSERVED_STATE_V18_FAMILY_BOUNDARY_FEATURES:
        values = []
        for row in active_rows:
            curve = curves_by_name[row["galaxy"]]
            value = observed_state_v18_state_values(curve).get(feature, math.nan)
            value = parse_float(value, math.nan)
            if math.isfinite(value):
                values.append(value)
        if not values:
            continue
        rows.append(
            {
                "branch": branch,
                "family": observed_state_branch_family(branch),
                "feature": feature,
                "hitCount": len(values),
                "min": min(values),
                "median": safe_median(values),
                "max": max(values),
                "span": max(values) - min(values),
            }
        )
    return rows


def write_observed_state_v18_branch_identity_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_observed_v18_branch_identity"
    context = observed_state_candidate_context()
    clean_curves = context["cleanCurves"]
    high_names = context["highNames"]
    curves_by_name = {curve["name"]: curve for curve in context["curves"]}
    scaler = observed_state_v18_branch_identity_scaler(clean_curves)
    artifact_payload = read_window_json_assignment(V18_BROWSER_ARTIFACT_PATH, "MTS_V18_01_REVIEW_CANDIDATE")
    case_rows, _parity_rows, law_summary = observed_state_v18_law_native_audit_rows(context, artifact_payload)
    full_metric = observed_state_v18_prune_metric(case_rows, high_names, lambda _row: False)
    full_high_above20 = int(full_metric["highAbove20"])
    clean_rows = [row for row in case_rows if row["set"] != "weak/systematics"]
    high_rows = [row for row in clean_rows if row["set"] == "clean-high-rmse"]
    protected_rows = [row for row in clean_rows if row["set"] == "clean-protected"]
    branches = sorted(
        {
            row["branch"]
            for row in high_rows
            if row.get("branch")
        }
    )

    branch_ledger_rows: list[dict] = []
    null_rows_all: list[dict] = []
    protected_analogue_rows_all: list[dict] = []
    holdout_rows_all: list[dict] = []
    forced_parity_rows: list[dict] = []
    state_surface_rows: list[dict] = []

    for branch in branches:
        active_rows = [row for row in clean_rows if row.get("branch") == branch]
        active_high_rows = [row for row in active_rows if row["set"] == "clean-high-rmse"]
        active_protected_rows = [row for row in active_rows if row["set"] == "clean-protected"]
        metric = observed_state_v18_prune_metric(case_rows, high_names, lambda row, item=branch: row.get("branch") == item)
        high_above20_delta = int(metric["highAbove20"]) - full_high_above20
        high_gain_loss = parse_float(full_metric["highGainPct"]) - parse_float(metric["highGainPct"])

        max_forced_diff = 0.0
        forced_route_mismatch_count = 0
        for row in active_rows:
            curve = curves_by_name[row["galaxy"]]
            forced = observed_state_v18_forced_branch_score(curve, branch)
            diff = forced["rmse"] - parse_float(row["lawNativeRmse"])
            max_forced_diff = max(max_forced_diff, abs(diff))
            if forced.get("candidateRoute", "") != row["lawCandidateRoute"]:
                forced_route_mismatch_count += 1
            forced_parity_rows.append(
                {
                    "branch": branch,
                    "family": row.get("family", observed_state_branch_family(branch)),
                    "galaxy": row["galaxy"],
                    "set": row["set"],
                    "lawNativeRmse": row["lawNativeRmse"],
                    "forcedRmse": forced["rmse"],
                    "forcedMinusLawRmse": diff,
                    "lawRoute": row["lawCandidateRoute"],
                    "forcedRoute": forced.get("candidateRoute", ""),
                    "forcedBranchReported": forced.get("observedStateBranch", ""),
                    "forcedResponseSource": forced.get("observedStateResponseSource", ""),
                }
            )

        branch_null_rows, branch_null_summary = observed_state_v18_branch_identity_null_rows(
            branch,
            active_high_rows,
            high_rows,
            curves_by_name,
            OBSERVED_STATE_V18_BRANCH_IDENTITY_SEEDS,
        )
        null_rows_all.extend(branch_null_rows)
        analogue_rows, analogue_summary = observed_state_v18_branch_identity_protected_analogues(
            branch,
            active_high_rows,
            protected_rows,
            curves_by_name,
            scaler,
            OBSERVED_STATE_V18_BRANCH_IDENTITY_ANALOG_COUNT,
        )
        protected_analogue_rows_all.extend(analogue_rows)
        branch_holdout_rows, branch_holdout_summary = observed_state_v18_branch_identity_holdout_rows(
            branch,
            active_high_rows,
            clean_curves,
            OBSERVED_STATE_V18_BRANCH_IDENTITY_SEEDS,
        )
        holdout_rows_all.extend(branch_holdout_rows)
        state_surface_rows.extend(observed_state_v18_branch_identity_surface_rows(branch, active_rows, curves_by_name))

        active_protected_regressions = [parse_float(row["lawNativeRmse"]) - parse_float(row["baselineRmse"]) for row in active_protected_rows]
        branch_null_margin = parse_float(branch_null_summary.get("sameRouteForcedNullMarginPct"), math.nan)
        max_protected_analogue_regression = parse_float(analogue_summary.get("maxProtectedAnalogueRegressionKmS"), 0.0)
        if max_forced_diff > 1e-7 or forced_route_mismatch_count:
            verdict = "identity mismatch"
        elif max_protected_analogue_regression > 3.0:
            verdict = "protected-stress branch"
        elif branch_null_margin < 10.0:
            verdict = "fails branch null"
        elif len(active_high_rows) <= 1:
            verdict = "edge branch"
        elif high_gain_loss >= 5.0 and high_above20_delta > 0 and parse_float(branch_holdout_summary["holdoutPresenceRate"], 0.0) >= 0.25:
            verdict = "law-like branch"
        elif high_above20_delta > 0 or high_gain_loss >= 2.0:
            verdict = "edge branch"
        else:
            verdict = "weak branch identity"

        branch_ledger_rows.append(
            {
                "branch": branch,
                "family": active_rows[0].get("family", observed_state_branch_family(branch)) if active_rows else observed_state_branch_family(branch),
                "verdict": verdict,
                "activeCleanHitCount": len(active_rows),
                "activeHighHitCount": len(active_high_rows),
                "activeProtectedHitCount": len(active_protected_rows),
                "activeHighMeanGainKmS": safe_mean(parse_float(row["lawGainKmS"]) for row in active_high_rows),
                "activeHighGainPct": observed_state_v18_row_gain_pct(active_high_rows),
                "ablationHighGainPct": metric["highGainPct"],
                "highGainLossPct": high_gain_loss,
                "ablationHighAbove20": metric["highAbove20"],
                "highAbove20Delta": high_above20_delta,
                "sameRouteForcedNullMarginPct": branch_null_margin,
                "sameRouteForcedNullGainPct": branch_null_summary.get("medianSameRouteForcedNullGainPct", math.nan),
                "holdoutPresenceRate": branch_holdout_summary["holdoutPresenceRate"],
                "medianHoldoutHighGainPct": branch_holdout_summary["medianHoldoutHighGainPct"],
                "maxForcedParityDiffKmS": max_forced_diff,
                "forcedRouteMismatchCount": forced_route_mismatch_count,
                "maxActiveProtectedRegressionKmS": max(active_protected_regressions or [0.0]),
                "activeProtectedWorseCount": sum(1 for value in active_protected_regressions if value > 1e-9),
                "maxProtectedAnalogueRegressionKmS": max_protected_analogue_regression,
                "protectedAnalogueWorseCount": analogue_summary["protectedAnalogueWorseCount"],
                "protectedAnalogueStressCount": analogue_summary["protectedAnalogueStressCount"],
                "highGalaxies": "; ".join(sorted(row["galaxy"] for row in active_high_rows)),
                "protectedGalaxies": "; ".join(sorted(row["galaxy"] for row in active_protected_rows)),
            }
        )

    order = {
        "law-like branch": 0,
        "edge branch": 1,
        "weak branch identity": 2,
        "fails branch null": 3,
        "protected-stress branch": 4,
        "identity mismatch": 5,
    }
    branch_ledger_rows.sort(key=lambda row: (order.get(row["verdict"], 99), row["family"], row["branch"]))
    law_like_count = sum(1 for row in branch_ledger_rows if row["verdict"] == "law-like branch")
    edge_count = sum(1 for row in branch_ledger_rows if row["verdict"] == "edge branch")
    fail_null_count = sum(1 for row in branch_ledger_rows if row["verdict"] == "fails branch null")
    protected_stress_count = sum(1 for row in branch_ledger_rows if row["verdict"] == "protected-stress branch")
    identity_mismatch_count = sum(1 for row in branch_ledger_rows if row["verdict"] == "identity mismatch")
    weak_identity_count = sum(1 for row in branch_ledger_rows if row["verdict"] == "weak branch identity")
    if identity_mismatch_count or protected_stress_count:
        verdict = "v18 branch identity blocked by safety/parity"
    elif law_like_count >= 5 and fail_null_count <= len(branch_ledger_rows) // 2:
        verdict = "v18 branch identity partially defensible"
    elif law_like_count >= 3:
        verdict = "v18 branch identity mixed"
    else:
        verdict = "v18 branch identity mostly null-like"

    summary = {
        "candidateId": "observed-state-response-v18.02-branch-identity",
        "verdict": verdict,
        "fullHighGainPct": full_metric["highGainPct"],
        "fullCleanGainPct": full_metric["cleanGainPct"],
        "fullHighAbove20": full_metric["highAbove20"],
        "branchCount": len(branch_ledger_rows),
        "lawLikeBranchCount": law_like_count,
        "edgeBranchCount": edge_count,
        "weakIdentityBranchCount": weak_identity_count,
        "failNullBranchCount": fail_null_count,
        "protectedStressBranchCount": protected_stress_count,
        "identityMismatchBranchCount": identity_mismatch_count,
        "maxProtectedAnalogueRegressionKmS": max([parse_float(row["maxProtectedAnalogueRegressionKmS"], 0.0) for row in branch_ledger_rows] or [0.0]),
        "maxForcedParityDiffKmS": max([parse_float(row["maxForcedParityDiffKmS"], 0.0) for row in branch_ledger_rows] or [0.0]),
        "activeHighHitCount": sum(int(parse_float(row["activeHighHitCount"], 0.0)) for row in branch_ledger_rows),
        "weakSystematicsLeakage": law_summary["weakSystematicsLeakage"],
        "cleanParityMismatchCount": law_summary["cleanParityMismatchCount"],
    }

    artifact_payload.setdefault("metadata", {})["branchIdentity"] = {
        "verdict": verdict,
        "branchCount": summary["branchCount"],
        "lawLikeBranchCount": law_like_count,
        "edgeBranchCount": edge_count,
        "failNullBranchCount": fail_null_count,
        "protectedStressBranchCount": protected_stress_count,
        "identityMismatchBranchCount": identity_mismatch_count,
        "weakSystematicsLeakage": law_summary["weakSystematicsLeakage"],
        "maxProtectedAnalogueRegressionKmS": summary["maxProtectedAnalogueRegressionKmS"],
    }
    write_window_json_assignment(V18_BROWSER_ARTIFACT_PATH, "MTS_V18_01_REVIEW_CANDIDATE", artifact_payload)
    write_window_json_assignment(out_dir / f"{prefix}_browser_artifact.js", "MTS_V18_01_REVIEW_CANDIDATE", artifact_payload)

    write_csv(out_dir / f"{prefix}_scores.csv", [summary])
    write_csv(out_dir / f"{prefix}_branch_ledger.csv", branch_ledger_rows)
    write_csv(out_dir / f"{prefix}_branch_nulls.csv", null_rows_all)
    write_csv(out_dir / f"{prefix}_protected_analogues.csv", protected_analogue_rows_all)
    write_csv(out_dir / f"{prefix}_holdout_stability.csv", holdout_rows_all)
    write_csv(out_dir / f"{prefix}_forced_parity.csv", forced_parity_rows)
    write_csv(out_dir / f"{prefix}_state_surface.csv", state_surface_rows)
    write_csv(out_dir / f"{prefix}_case_ledger.csv", case_rows)

    report = [
        "# MTS v18.02 Branch Identity Audit",
        "",
        "This audit keeps v18.01 frozen and tests whether each essential branch has its own defensible state identity.",
        "",
        "## Result",
        "",
        f"- Verdict: `{verdict}`.",
        f"- Full high-RMSE gain: `{fmt(summary['fullHighGainPct'])}%`.",
        f"- Full clean-set gain: `{fmt(summary['fullCleanGainPct'])}%`.",
        f"- High-RMSE cases still above 20 km/s: `{summary['fullHighAbove20']}`.",
        f"- Branches tested: `{summary['branchCount']}`.",
        f"- Law-like branches: `{law_like_count}`.",
        f"- Edge branches: `{edge_count}`.",
        f"- Branches failing same-route forced null: `{fail_null_count}`.",
        f"- Protected-stress branches: `{protected_stress_count}`.",
        f"- Identity mismatches: `{identity_mismatch_count}`.",
        f"- Max protected analogue regression: `{fmt(summary['maxProtectedAnalogueRegressionKmS'])}` km/s.",
        f"- Max forced/law parity difference: `{fmt(summary['maxForcedParityDiffKmS'], 9)}` km/s.",
        f"- Weak/systematics leakage: `{summary['weakSystematicsLeakage']}`.",
        "",
        "## Branch Ledger",
        "",
        "| Branch | Family | Verdict | High hits | Gain loss | Null margin | Protected analogue max |",
        "| --- | --- | --- | ---: | ---: | ---: | ---: |",
    ]
    for row in branch_ledger_rows:
        report.append(
            f"| {row['branch']} | {row['family']} | {row['verdict']} | {row['activeHighHitCount']} | "
            f"{fmt(row['highGainLossPct'])} | {fmt(row['sameRouteForcedNullMarginPct'])} | {fmt(row['maxProtectedAnalogueRegressionKmS'])} |"
        )
    report.extend(
        [
            "",
            "## Interpretation",
            "",
            "A branch is law-like only if forcing that branch reproduces the frozen v18 score, protected nearest analogues remain safe, and same-route forced random targets do not explain the branch's high-RMSE gain.",
            "This is not a new formula. It is a branch-by-branch identity test for the existing v18 law.",
        ]
    )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report), encoding="utf-8")

    capsule = {
        "analysisName": "mts-observed-v18-branch-identity-v1",
        "candidateId": summary["candidateId"],
        "verdict": verdict,
        "summary": summary,
        "outputFiles": [
            f"{prefix}_scores.csv",
            f"{prefix}_branch_ledger.csv",
            f"{prefix}_branch_nulls.csv",
            f"{prefix}_protected_analogues.csv",
            f"{prefix}_holdout_stability.csv",
            f"{prefix}_forced_parity.csv",
            f"{prefix}_state_surface.csv",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_browser_artifact.js",
            f"{prefix}_report.md",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_observedstatev18branchidentity(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_OBSERVED_STATE_V18_BRANCH_IDENTITY_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_observed_state_v18_branch_identity_artifacts(out_dir)
    summary = capsule["summary"]
    print("MTS v18.02 branch identity audit")
    print(f"verdict={summary['verdict']}")
    print(
        "\t".join(
            [
                f"high={fmt(summary['fullHighGainPct'])}%",
                f"clean={fmt(summary['fullCleanGainPct'])}%",
                f"above20={summary['fullHighAbove20']}",
                f"branches={summary['branchCount']}",
                f"law_like={summary['lawLikeBranchCount']}",
                f"edge={summary['edgeBranchCount']}",
                f"fails_null={summary['failNullBranchCount']}",
                f"protected_stress={summary['protectedStressBranchCount']}",
                f"weak_leakage={summary['weakSystematicsLeakage']}",
            ]
        )
    )
    print(f"Wrote v18 branch identity audit to {out_dir.resolve()}")


