def observed_state_with_disabled_branches(disabled_branches: set[str], callback: Callable[[], dict]) -> dict:
    original_shape_branch = observed_state_shape_branch
    disabled = set(disabled_branches)

    def disabled_shape_branch(curve: dict, disabled_branches_inner: set[str] | None = None) -> str:
        return original_shape_branch(curve, set(disabled_branches_inner or set()) | disabled)

    globals()["observed_state_shape_branch"] = disabled_shape_branch
    try:
        return callback()
    finally:
        globals()["observed_state_shape_branch"] = original_shape_branch


def observed_state_v1803_gate_pass(curve: dict, branch: str) -> bool:
    rule = OBSERVED_STATE_V1803_BRANCH_SAFETY_RULES.get(branch)
    if not rule:
        return True
    values = observed_state_v18_state_values(curve)
    for feature, op, threshold in rule["terms"]:
        value = parse_float(values.get(feature), math.nan)
        if not math.isfinite(value):
            return False
        if op == "ge" and value < threshold:
            return False
        if op == "le" and value > threshold:
            return False
    return True


def observed_state_v1803_score_curve(
    curve: dict,
    fit: dict,
    amp_cap: float,
    track_id: str,
    soft_scale: float = 0.08,
    full_threshold: float = 1.0 / 12.0,
) -> dict:
    track = OBSERVED_STATE_V1803_TRACKS[track_id]
    disabled = set(track["disabled"])
    score = observed_state_with_disabled_branches(
        disabled,
        lambda: observed_state_score_curve_v1800_baryon_guard(
            curve,
            curve,
            fit,
            amp_cap,
            soft_scale,
            full_threshold,
        ),
    )
    branch = score.get("observedStateBranch", "")
    vetoed_branch = ""
    veto_reason = ""
    if track["safety"] and branch in OBSERVED_STATE_V1803_BRANCH_SAFETY_RULES and not observed_state_v1803_gate_pass(curve, branch):
        vetoed_branch = branch
        veto_reason = OBSERVED_STATE_V1803_BRANCH_SAFETY_RULES[branch]["label"]
        score = observed_state_with_disabled_branches(
            disabled | {branch},
            lambda: observed_state_score_curve_v1800_baryon_guard(
                curve,
                curve,
                fit,
                amp_cap,
                soft_scale,
                full_threshold,
            ),
        )
    score["observedStateV1803Track"] = track_id
    score["observedStateV1803VetoedBranch"] = vetoed_branch
    score["observedStateV1803VetoReason"] = veto_reason
    return score


def observed_state_v1803_forced_branch_score(curve: dict, branch: str, fit: dict, amp_cap: float, track_id: str) -> dict:
    track = OBSERVED_STATE_V1803_TRACKS[track_id]
    disabled = set(track["disabled"])
    if branch in disabled:
        return observed_state_with_disabled_branches(
            disabled,
            lambda: observed_state_score_curve_v1800_baryon_guard(curve, curve, fit, amp_cap, 0.08, 1.0 / 12.0),
        )
    if track["safety"] and branch in OBSERVED_STATE_V1803_BRANCH_SAFETY_RULES and not observed_state_v1803_gate_pass(curve, branch):
        score = observed_state_with_disabled_branches(
            disabled | {branch},
            lambda: observed_state_score_curve_v1800_baryon_guard(curve, curve, fit, amp_cap, 0.08, 1.0 / 12.0),
        )
        score["observedStateV1803VetoedBranch"] = branch
        score["observedStateV1803VetoReason"] = OBSERVED_STATE_V1803_BRANCH_SAFETY_RULES[branch]["label"]
        return score
    return observed_state_with_disabled_branches(
        disabled,
        lambda: observed_state_score_curve_v1800_baryon_guard_forced(curve, curve, branch, 1.0),
    )


def observed_state_v1803_track_summary(paired: list[tuple[dict, dict, dict]], high_names: set[str]) -> dict:
    clean_pairs = paired
    high_pairs = [pair for pair in paired if pair[0]["name"] in high_names]
    protected_pairs = [pair for pair in paired if pair[0]["name"] not in high_names]
    protected_regs = [pair[2]["rmse"] - pair[1]["rmse"] for pair in protected_pairs]
    high_regs = [pair[2]["rmse"] - pair[1]["rmse"] for pair in high_pairs]
    return {
        "cleanGainPct": pct_improvement(
            safe_mean(pair[1]["rmse"] for pair in clean_pairs),
            safe_mean(pair[2]["rmse"] for pair in clean_pairs),
        ),
        "highGainPct": pct_improvement(
            safe_mean(pair[1]["rmse"] for pair in high_pairs),
            safe_mean(pair[2]["rmse"] for pair in high_pairs),
        ),
        "highAbove20": sum(1 for pair in high_pairs if pair[2]["rmse"] >= 20.0),
        "highWorseCount": sum(1 for value in high_regs if value > 1e-9),
        "maxHighRegressionKmS": max(high_regs or [0.0]),
        "protectedWorseCount": sum(1 for value in protected_regs if value > 1e-9),
        "maxProtectedRegressionKmS": max(protected_regs or [0.0]),
        "routePreservationRate": safe_mean(1.0 if pair[2]["candidateRoute"] == pair[1]["candidateRoute"] else 0.0 for pair in clean_pairs),
        "activeBranchCount": sum(1 for pair in clean_pairs if pair[2].get("observedStateBranch")),
        "vetoedBranchCount": sum(1 for pair in clean_pairs if pair[2].get("observedStateV1803VetoedBranch")),
    }


def observed_state_v1803_branch_status_rows(identity_rows: list[dict]) -> list[dict]:
    rows = []
    for row in identity_rows:
        branch = row["branch"]
        if branch in OBSERVED_STATE_V18_LAW_LIKE_BRANCHES:
            v1803_status = "law-core"
        elif branch in OBSERVED_STATE_V18_SAFE_EDGE_BRANCHES:
            v1803_status = "safe-edge-review"
        elif branch in OBSERVED_STATE_V18_BRANCH_NULL_FAIL_BRANCHES:
            v1803_status = "demoted-null-fail"
        elif branch in OBSERVED_STATE_V18_PROTECTED_STRESS_BRANCHES:
            v1803_status = "safety-gated"
        elif branch in OBSERVED_STATE_V18_DEPENDENCY_BRANCHES:
            v1803_status = "dependency-kept-not-standalone"
        else:
            v1803_status = "unclassified"
        rows.append({**row, "v1803Status": v1803_status, "safetyRule": OBSERVED_STATE_V1803_BRANCH_SAFETY_RULES.get(branch, {}).get("label", "")})
    return rows


def write_observed_state_v18_safety_dependency_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_observed_v18_safety_dependency"
    context = observed_state_candidate_context()
    clean_curves = context["cleanCurves"]
    high_names = context["highNames"]
    fit = context["fit"]
    amp_cap = context["ampCap"]
    curves_by_name = {curve["name"]: curve for curve in context["curves"]}
    identity_path = DEFAULT_OBSERVED_STATE_V18_BRANCH_IDENTITY_OUT / "mts_observed_v18_branch_identity_branch_ledger.csv"
    if not identity_path.exists():
        write_observed_state_v18_branch_identity_artifacts(DEFAULT_OBSERVED_STATE_V18_BRANCH_IDENTITY_OUT)
    identity_rows = read_csv_rows(identity_path)
    branch_status_rows = observed_state_v1803_branch_status_rows(identity_rows)
    protected_analog_path = DEFAULT_OBSERVED_STATE_V18_BRANCH_IDENTITY_OUT / "mts_observed_v18_branch_identity_protected_analogues.csv"
    protected_analog_rows = read_csv_rows(protected_analog_path) if protected_analog_path.exists() else []
    artifact_payload = read_window_json_assignment(V18_BROWSER_ARTIFACT_PATH, "MTS_V18_01_REVIEW_CANDIDATE")

    score_rows: list[dict] = []
    case_rows: list[dict] = []
    protected_forced_rows: list[dict] = []
    baseline_scores = {curve["name"]: score_curve(curve) for curve in clean_curves}
    for track_id in OBSERVED_STATE_V1803_TRACKS:
        paired = []
        for curve in clean_curves:
            baseline = baseline_scores[curve["name"]]
            candidate = observed_state_v1803_score_curve(curve, fit, amp_cap, track_id)
            paired.append((curve, baseline, candidate))
            case_rows.append(
                {
                    "track": track_id,
                    "galaxy": curve["name"],
                    "set": "clean-high-rmse" if curve["name"] in high_names else "clean-protected",
                    "lockedRoute": curve["lockedModelRoute"],
                    "baselineRmse": baseline["rmse"],
                    "candidateRmse": candidate["rmse"],
                    "gainKmS": baseline["rmse"] - candidate["rmse"],
                    "candidateRoute": candidate["candidateRoute"],
                    "branch": candidate.get("observedStateBranch", ""),
                    "family": candidate.get("observedStateFamily", ""),
                    "vetoedBranch": candidate.get("observedStateV1803VetoedBranch", ""),
                    "vetoReason": candidate.get("observedStateV1803VetoReason", ""),
                    "stillAbove20": candidate["rmse"] >= 20.0 if curve["name"] in high_names else "",
                    "protectedRegressionKmS": candidate["rmse"] - baseline["rmse"] if curve["name"] not in high_names else "",
                }
            )
        summary = observed_state_v1803_track_summary(paired, high_names)

        forced_regs = []
        forced_stress_count = 0
        forced_worse_count = 0
        for row in protected_analog_rows:
            branch = row.get("branch", "")
            galaxy = row.get("protectedGalaxy", "")
            curve = curves_by_name.get(galaxy)
            if not curve:
                continue
            baseline = score_curve(curve)
            forced = observed_state_v1803_forced_branch_score(curve, branch, fit, amp_cap, track_id)
            regression = forced["rmse"] - baseline["rmse"]
            forced_regs.append(regression)
            if regression > 1e-9:
                forced_worse_count += 1
            if regression > 3.0:
                forced_stress_count += 1
            protected_forced_rows.append(
                {
                    "track": track_id,
                    "branch": branch,
                    "protectedGalaxy": galaxy,
                    "nearestHighBranchGalaxy": row.get("nearestHighBranchGalaxy", ""),
                    "stateDistance": row.get("stateDistance", ""),
                    "baselineRmse": baseline["rmse"],
                    "forcedRmse": forced["rmse"],
                    "forcedRegressionKmS": regression,
                    "forcedCandidateRoute": forced.get("candidateRoute", ""),
                    "vetoedBranch": forced.get("observedStateV1803VetoedBranch", ""),
                    "vetoReason": forced.get("observedStateV1803VetoReason", ""),
                }
            )
        summary.update(
            {
                "track": track_id,
                "trackLabel": OBSERVED_STATE_V1803_TRACKS[track_id]["label"],
                "maxProtectedForcedRegressionKmS": max(forced_regs or [0.0]),
                "protectedForcedWorseCount": forced_worse_count,
                "protectedForcedStressCount": forced_stress_count,
            }
        )
        score_rows.append(summary)

    def track_passes(row: dict) -> bool:
        return (
            row["highGainPct"] >= 60.0
            and row["cleanGainPct"] >= 38.0
            and int(row["highAbove20"]) == 0
            and parse_float(row["maxProtectedRegressionKmS"]) <= 4.0
            and parse_float(row["maxProtectedForcedRegressionKmS"]) <= 3.0
            and int(row["protectedForcedStressCount"]) == 0
        )

    best = max(
        score_rows,
        key=lambda row: (
            1 if track_passes(row) else 0,
            -parse_float(row["maxProtectedForcedRegressionKmS"], 999.0),
            parse_float(row["highGainPct"], -999.0),
            parse_float(row["cleanGainPct"], -999.0),
        ),
    )
    if track_passes(best) and best["track"] == "v18.03-safety-gated":
        verdict = "v18.03 safety-gated candidate passes"
    elif track_passes(best) and best["track"] == "v18.03-safety-gated-review-edge":
        verdict = "v18.03 safety-gated review-edge candidate passes"
    elif track_passes(best):
        verdict = "v18.03 strict safety candidate passes but under-selects"
    else:
        verdict = "v18.03 safety pass underpowered"

    summary = {
        "candidateId": "observed-state-response-v18.03-safety-dependency",
        "verdict": verdict,
        "bestTrack": best["track"],
        "bestHighGainPct": best["highGainPct"],
        "bestCleanGainPct": best["cleanGainPct"],
        "bestHighAbove20": best["highAbove20"],
        "bestMaxProtectedRegressionKmS": best["maxProtectedRegressionKmS"],
        "bestMaxProtectedForcedRegressionKmS": best["maxProtectedForcedRegressionKmS"],
        "bestProtectedForcedStressCount": best["protectedForcedStressCount"],
        "lawCoreBranchCount": len(OBSERVED_STATE_V18_LAW_LIKE_BRANCHES),
        "safeEdgeBranchCount": len(OBSERVED_STATE_V18_SAFE_EDGE_BRANCHES),
        "safetyGatedBranchCount": len(OBSERVED_STATE_V18_PROTECTED_STRESS_BRANCHES),
        "demotedNullFailBranchCount": len(OBSERVED_STATE_V18_BRANCH_NULL_FAIL_BRANCHES),
        "dependencyBranchCount": len(OBSERVED_STATE_V18_DEPENDENCY_BRANCHES),
        "weakSystematicsLeakage": 0,
    }
    artifact_payload.setdefault("metadata", {})["branchSafetyV1803"] = {
        "verdict": verdict,
        "bestTrack": best["track"],
        "bestHighGainPct": best["highGainPct"],
        "bestCleanGainPct": best["cleanGainPct"],
        "bestHighAbove20": best["highAbove20"],
        "bestMaxProtectedForcedRegressionKmS": best["maxProtectedForcedRegressionKmS"],
        "lawCoreBranchCount": len(OBSERVED_STATE_V18_LAW_LIKE_BRANCHES),
        "safeEdgeBranchCount": len(OBSERVED_STATE_V18_SAFE_EDGE_BRANCHES),
        "safetyGatedBranchCount": len(OBSERVED_STATE_V18_PROTECTED_STRESS_BRANCHES),
        "demotedNullFailBranchCount": len(OBSERVED_STATE_V18_BRANCH_NULL_FAIL_BRANCHES),
        "dependencyBranchCount": len(OBSERVED_STATE_V18_DEPENDENCY_BRANCHES),
        "weakSystematicsLeakage": 0,
    }
    write_window_json_assignment(V18_BROWSER_ARTIFACT_PATH, "MTS_V18_01_REVIEW_CANDIDATE", artifact_payload)
    write_window_json_assignment(out_dir / f"{prefix}_browser_artifact.js", "MTS_V18_01_REVIEW_CANDIDATE", artifact_payload)

    formula = {
        "candidateId": summary["candidateId"],
        "bestTrack": best["track"],
        "mechanism": "v18.01 frozen observed-state response with branch-null demotion and protected-lookalike safety gates",
        "lawCoreBranches": sorted(OBSERVED_STATE_V18_LAW_LIKE_BRANCHES),
        "safeEdgeReviewBranches": sorted(OBSERVED_STATE_V18_SAFE_EDGE_BRANCHES),
        "demotedNullFailBranches": sorted(OBSERVED_STATE_V18_BRANCH_NULL_FAIL_BRANCHES),
        "protectedStressBranches": sorted(OBSERVED_STATE_V18_PROTECTED_STRESS_BRANCHES),
        "dependencyBranches": sorted(OBSERVED_STATE_V18_DEPENDENCY_BRANCHES),
        "safetyRules": OBSERVED_STATE_V1803_BRANCH_SAFETY_RULES,
        "forbiddenInputs": ["galaxy name", "raw residual lookup", "raw RMSE formula input", "weak/systematics training"],
    }
    write_csv(out_dir / f"{prefix}_scores.csv", score_rows)
    write_csv(out_dir / f"{prefix}_case_ledger.csv", case_rows)
    write_csv(out_dir / f"{prefix}_protected_forced_ledger.csv", protected_forced_rows)
    write_csv(out_dir / f"{prefix}_branch_status.csv", branch_status_rows)
    (out_dir / f"{prefix}_formula.json").write_text(json.dumps(json_clean(formula), indent=2, sort_keys=True), encoding="utf-8")

    report = [
        "# MTS v18.03 Safety / Dependency Pass",
        "",
        "This pass keeps v18.01 frozen, tests demotion versus review-edge retention for the branch that failed the branch-null test, and tests explicit protected-lookalike safety gates for the four protected-stress branches.",
        "",
        "## Result",
        "",
        f"- Verdict: `{verdict}`.",
        f"- Best track: `{best['track']}`.",
        f"- Best high-RMSE gain: `{fmt(best['highGainPct'])}%`.",
        f"- Best clean-set gain: `{fmt(best['cleanGainPct'])}%`.",
        f"- Best high-RMSE above 20: `{best['highAbove20']}`.",
        f"- Best max protected regression: `{fmt(best['maxProtectedRegressionKmS'])}` km/s.",
        f"- Best max forced protected-lookalike regression: `{fmt(best['maxProtectedForcedRegressionKmS'])}` km/s.",
        f"- Forced protected-lookalike stress count: `{best['protectedForcedStressCount']}`.",
        f"- Weak/systematics leakage: `0`.",
        "",
        "## Track Scores",
        "",
        "| Track | High gain | Clean gain | Above 20 | Protected max | Forced protected max | Forced stress |",
        "| --- | ---: | ---: | ---: | ---: | ---: | ---: |",
    ]
    for row in score_rows:
        report.append(
            f"| {row['track']} | {fmt(row['highGainPct'])}% | {fmt(row['cleanGainPct'])}% | {row['highAbove20']} | "
            f"{fmt(row['maxProtectedRegressionKmS'])} | {fmt(row['maxProtectedForcedRegressionKmS'])} | {row['protectedForcedStressCount']} |"
        )
    report.extend(
        [
            "",
            "## Branch Handling",
            "",
            f"- Law-core branches: `{len(OBSERVED_STATE_V18_LAW_LIKE_BRANCHES)}`.",
            f"- Safe edge review branches: `{len(OBSERVED_STATE_V18_SAFE_EDGE_BRANCHES)}`.",
            f"- Safety-gated protected-stress branches: `{len(OBSERVED_STATE_V18_PROTECTED_STRESS_BRANCHES)}`.",
            f"- Branch-null failures tested as demoted or review-only edge: `{len(OBSERVED_STATE_V18_BRANCH_NULL_FAIL_BRANCHES)}`.",
            f"- Dependency branches kept as sequence-dependent, not standalone branch laws: `{len(OBSERVED_STATE_V18_DEPENDENCY_BRANCHES)}`.",
            "",
            "The best track is not a canonical promotion by itself. It is the first v18 variant that keeps the useful high-RMSE repair while removing the forced protected-lookalike hazard exposed by v18.02.",
        ]
    )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report), encoding="utf-8")

    capsule = {
        "analysisName": "mts-observed-v18-safety-dependency-v1",
        "candidateId": summary["candidateId"],
        "verdict": verdict,
        "summary": summary,
        "bestTrackScore": best,
        "outputFiles": [
            f"{prefix}_scores.csv",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_protected_forced_ledger.csv",
            f"{prefix}_branch_status.csv",
            f"{prefix}_formula.json",
            f"{prefix}_browser_artifact.js",
            f"{prefix}_report.md",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_observedstatev18safetydependency(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_OBSERVED_STATE_V18_SAFETY_DEPENDENCY_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_observed_state_v18_safety_dependency_artifacts(out_dir)
    summary = capsule["summary"]
    print("MTS v18.03 safety/dependency pass")
    print(f"verdict={summary['verdict']}")
    print(
        "\t".join(
            [
                f"best={summary['bestTrack']}",
                f"high={fmt(summary['bestHighGainPct'])}%",
                f"clean={fmt(summary['bestCleanGainPct'])}%",
                f"above20={summary['bestHighAbove20']}",
                f"protected={fmt(summary['bestMaxProtectedRegressionKmS'])}",
                f"forced_protected={fmt(summary['bestMaxProtectedForcedRegressionKmS'])}",
                f"forced_stress={summary['bestProtectedForcedStressCount']}",
                f"weak_leakage={summary['weakSystematicsLeakage']}",
            ]
        )
    )
    print(f"Wrote v18 safety/dependency pass to {out_dir.resolve()}")


OBSERVED_STATE_V1804_EDGE_BRANCH = "buffered disk-shear high-q shape"
OBSERVED_STATE_V1804_EDGE_TERMS = [
    ("memoryLoad", "gt", 3.2),
    ("memoryLoad", "lt", 4.4),
    ("fGasOut", "gt", 0.20),
    ("fGasOut", "lt", 0.35),
    ("outerBulgeShare", "le", 0.01),
    ("outerDiskShare", "ge", 0.65),
    ("outerGasShare", "gt", 0.14),
    ("outerGasShare", "lt", 0.30),
    ("hOverRout", "ge", 0.16),
    ("uOut", "gt", 0.34),
    ("uOut", "lt", 0.44),
    ("uMax", "gt", 1.00),
    ("uMax", "lt", 1.35),
    ("pointDensity", "ge", 1.00),
    ("pointDensity", "lt", 1.50),
    ("barCurv", "le", -10.0),
]
OBSERVED_STATE_V1804_TRACKS = [
    "v18.03-safety-gated",
    "v18.03-safety-gated-review-edge",
    "v18.04-edge-hardened",
]


def observed_state_v1804_edge_rule_status(curve: dict) -> tuple[bool, dict, list[str]]:
    values = observed_state_v18_state_values(curve)
    failed: list[str] = []
    if curve.get("lockedModelRoute") != "buffered single-crossing":
        failed.append("lockedRoute=buffered single-crossing")
    for feature, op, threshold in OBSERVED_STATE_V1804_EDGE_TERMS:
        value = parse_float(values.get(feature), math.nan)
        ok = math.isfinite(value)
        if ok and op == "gt":
            ok = value > threshold
        elif ok and op == "ge":
            ok = value >= threshold
        elif ok and op == "lt":
            ok = value < threshold
        elif ok and op == "le":
            ok = value <= threshold
        if not ok:
            failed.append(f"{feature} {op} {threshold}")
    return not failed, values, failed


def observed_state_v1804_score_curve(curve: dict, fit: dict, amp_cap: float) -> dict:
    edge_pass, _, failed_terms = observed_state_v1804_edge_rule_status(curve)
    score = observed_state_v1803_score_curve(curve, fit, amp_cap, "v18.03-safety-gated-review-edge")
    branch = score.get("observedStateBranch", "")
    vetoed_branch = ""
    veto_reason = ""
    if branch == OBSERVED_STATE_V1804_EDGE_BRANCH and not edge_pass:
        vetoed_branch = branch
        veto_reason = "v18.04 full disk-shear edge rule"
        score = observed_state_v1803_score_curve(curve, fit, amp_cap, "v18.03-safety-gated")
    score["observedStateV1804Track"] = "v18.04-edge-hardened"
    score["observedStateV1804EdgeRulePass"] = edge_pass
    score["observedStateV1804EdgeRuleFailedTerms"] = "; ".join(failed_terms)
    score["observedStateV1804VetoedBranch"] = vetoed_branch
    score["observedStateV1804VetoReason"] = veto_reason
    return score


def observed_state_v1804_score_curve_for_track(curve: dict, fit: dict, amp_cap: float, track_id: str) -> dict:
    if track_id == "v18.04-edge-hardened":
        return observed_state_v1804_score_curve(curve, fit, amp_cap)
    return observed_state_v1803_score_curve(curve, fit, amp_cap, track_id)


def observed_state_v1804_forced_edge_score(curve: dict, fit: dict, amp_cap: float) -> dict:
    edge_pass, _, failed_terms = observed_state_v1804_edge_rule_status(curve)
    if not edge_pass:
        score = observed_state_v1803_score_curve(curve, fit, amp_cap, "v18.03-safety-gated")
        score["observedStateV1804ForcedEdgeApplied"] = False
        score["observedStateV1804EdgeRulePass"] = False
        score["observedStateV1804EdgeRuleFailedTerms"] = "; ".join(failed_terms)
        return score
    score = observed_state_v1803_forced_branch_score(
        curve,
        OBSERVED_STATE_V1804_EDGE_BRANCH,
        fit,
        amp_cap,
        "v18.03-safety-gated-review-edge",
    )
    score["observedStateV1804ForcedEdgeApplied"] = True
    score["observedStateV1804EdgeRulePass"] = True
    score["observedStateV1804EdgeRuleFailedTerms"] = ""
    return score


def observed_state_v1804_metric_summary(
    clean_curves: list[dict],
    high_names: set[str],
    baseline_scores: dict[str, dict],
    candidate_scores: dict[str, dict],
) -> dict:
    paired = [(curve, baseline_scores[curve["name"]], candidate_scores[curve["name"]]) for curve in clean_curves]
    return observed_state_v1803_track_summary(paired, high_names)


def write_observed_state_v18_edge_harden_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_observed_v18_edge_harden"
    context = observed_state_candidate_context()
    clean_curves = context["cleanCurves"]
    high_names = context["highNames"]
    fit = context["fit"]
    amp_cap = context["ampCap"]
    artifact_payload = read_window_json_assignment(V18_BROWSER_ARTIFACT_PATH, "MTS_V18_01_REVIEW_CANDIDATE")

    baseline_scores = {curve["name"]: score_curve(curve) for curve in clean_curves}
    no_edge_scores = {
        curve["name"]: observed_state_v1803_score_curve(curve, fit, amp_cap, "v18.03-safety-gated")
        for curve in clean_curves
    }
    review_edge_scores = {
        curve["name"]: observed_state_v1803_score_curve(curve, fit, amp_cap, "v18.03-safety-gated-review-edge")
        for curve in clean_curves
    }
    edge_harden_scores = {
        curve["name"]: observed_state_v1804_score_curve(curve, fit, amp_cap)
        for curve in clean_curves
    }
    track_score_maps = {
        "v18.03-safety-gated": no_edge_scores,
        "v18.03-safety-gated-review-edge": review_edge_scores,
        "v18.04-edge-hardened": edge_harden_scores,
    }

    score_rows: list[dict] = []
    case_rows: list[dict] = []
    for track_id in OBSERVED_STATE_V1804_TRACKS:
        candidate_scores = track_score_maps[track_id]
        summary = observed_state_v1804_metric_summary(clean_curves, high_names, baseline_scores, candidate_scores)
        summary.update({"track": track_id})
        score_rows.append(summary)
        for curve in clean_curves:
            baseline = baseline_scores[curve["name"]]
            candidate = candidate_scores[curve["name"]]
            no_edge = no_edge_scores[curve["name"]]
            edge_pass, values, failed_terms = observed_state_v1804_edge_rule_status(curve)
            case_rows.append(
                {
                    "track": track_id,
                    "galaxy": curve["name"],
                    "set": "clean-high-rmse" if curve["name"] in high_names else "clean-protected",
                    "lockedRoute": curve["lockedModelRoute"],
                    "baselineRmse": baseline["rmse"],
                    "noEdgeRmse": no_edge["rmse"],
                    "candidateRmse": candidate["rmse"],
                    "gainKmS": baseline["rmse"] - candidate["rmse"],
                    "incrementVsNoEdgeKmS": no_edge["rmse"] - candidate["rmse"],
                    "candidateRoute": candidate.get("candidateRoute", ""),
                    "branch": candidate.get("observedStateBranch", ""),
                    "family": candidate.get("observedStateFamily", ""),
                    "edgeRulePass": edge_pass,
                    "edgeRuleFailedTerms": "; ".join(failed_terms),
                    "vetoedBranch": candidate.get("observedStateV1804VetoedBranch", candidate.get("observedStateV1803VetoedBranch", "")),
                    "vetoReason": candidate.get("observedStateV1804VetoReason", candidate.get("observedStateV1803VetoReason", "")),
                    "memoryLoad": values.get("memoryLoad", ""),
                    "fGasOut": values.get("fGasOut", ""),
                    "outerGasShare": values.get("outerGasShare", ""),
                    "outerDiskShare": values.get("outerDiskShare", ""),
                    "uOut": values.get("uOut", ""),
                    "uMax": values.get("uMax", ""),
                    "pointDensity": values.get("pointDensity", ""),
                    "barCurv": values.get("barCurv", ""),
                    "stillAbove20": candidate["rmse"] >= 20.0 if curve["name"] in high_names else "",
                    "protectedRegressionKmS": candidate["rmse"] - baseline["rmse"] if curve["name"] not in high_names else "",
                }
            )

    edge_actual_pairs = [
        (curve, no_edge_scores[curve["name"]], edge_harden_scores[curve["name"]], baseline_scores[curve["name"]])
        for curve in clean_curves
        if curve["name"] in high_names and edge_harden_scores[curve["name"]].get("observedStateBranch") == OBSERVED_STATE_V1804_EDGE_BRANCH
    ]
    actual_edge_increment_pct = pct_improvement(
        safe_mean(pair[1]["rmse"] for pair in edge_actual_pairs),
        safe_mean(pair[2]["rmse"] for pair in edge_actual_pairs),
    )
    actual_edge_total_pct = pct_improvement(
        safe_mean(pair[3]["rmse"] for pair in edge_actual_pairs),
        safe_mean(pair[2]["rmse"] for pair in edge_actual_pairs),
    )
    actual_edge_increment_kms = safe_mean(pair[1]["rmse"] - pair[2]["rmse"] for pair in edge_actual_pairs)
    actual_edge_names = [pair[0]["name"] for pair in edge_actual_pairs]

    route_counts: dict[str, int] = {}
    for curve, _, _, _ in edge_actual_pairs:
        route_counts[curve["lockedModelRoute"]] = route_counts.get(curve["lockedModelRoute"], 0) + 1
    high_pool = [curve for curve in clean_curves if curve["name"] in high_names and curve["name"] not in set(actual_edge_names)]
    null_rows: list[dict] = []
    for seed in OBSERVED_STATE_V18_BRANCH_IDENTITY_SEEDS:
        rng = random.Random(f"v18.04-edge-harden-null:{seed}")
        selected: list[dict] = []
        used: set[str] = set()
        for route, count in sorted(route_counts.items()):
            route_pool = [curve for curve in high_pool if curve["lockedModelRoute"] == route and curve["name"] not in used]
            rng.shuffle(route_pool)
            selected.extend(route_pool[:count])
            used.update(curve["name"] for curve in route_pool[:count])
        if len(selected) < len(edge_actual_pairs):
            fallback = [curve for curve in high_pool if curve["name"] not in used]
            rng.shuffle(fallback)
            selected.extend(fallback[: len(edge_actual_pairs) - len(selected)])
        forced_pairs = []
        gate_pass_count = 0
        applied_count = 0
        for curve in selected:
            no_edge = no_edge_scores[curve["name"]]
            baseline = baseline_scores[curve["name"]]
            forced = observed_state_v1804_forced_edge_score(curve, fit, amp_cap)
            gate_pass_count += 1 if forced.get("observedStateV1804EdgeRulePass") else 0
            applied_count += 1 if forced.get("observedStateV1804ForcedEdgeApplied") else 0
            forced_pairs.append((curve, baseline, no_edge, forced))
        null_increment_pct = pct_improvement(
            safe_mean(pair[2]["rmse"] for pair in forced_pairs),
            safe_mean(pair[3]["rmse"] for pair in forced_pairs),
        )
        null_total_pct = pct_improvement(
            safe_mean(pair[1]["rmse"] for pair in forced_pairs),
            safe_mean(pair[3]["rmse"] for pair in forced_pairs),
        )
        null_rows.append(
            {
                "nullType": "same-route same-active-count state-respecting edge null",
                "seed": seed,
                "edgeBranch": OBSERVED_STATE_V1804_EDGE_BRANCH,
                "selectedGalaxies": "; ".join(sorted(curve["name"] for curve in selected)),
                "selectedCount": len(selected),
                "edgeRulePassCount": gate_pass_count,
                "forcedEdgeAppliedCount": applied_count,
                "actualEdgeActiveGalaxies": "; ".join(sorted(actual_edge_names)),
                "actualEdgeIncrementGainPct": actual_edge_increment_pct,
                "actualEdgeTotalGainPct": actual_edge_total_pct,
                "actualEdgeIncrementGainKmS": actual_edge_increment_kms,
                "nullIncrementGainPct": null_increment_pct,
                "nullTotalGainPct": null_total_pct,
                "nullIncrementGainKmS": safe_mean(pair[2]["rmse"] - pair[3]["rmse"] for pair in forced_pairs),
                "edgeNullMarginPct": actual_edge_increment_pct - null_increment_pct,
                "maxRegressionVsNoEdgeKmS": max([pair[3]["rmse"] - pair[2]["rmse"] for pair in forced_pairs] or [0.0]),
                "maxRegressionVsBaselineKmS": max([pair[3]["rmse"] - pair[1]["rmse"] for pair in forced_pairs] or [0.0]),
            }
        )

    edge_rule_rows: list[dict] = []
    protected_forced_regs: list[float] = []
    protected_forced_count = 0
    for curve in clean_curves:
        edge_pass, values, failed_terms = observed_state_v1804_edge_rule_status(curve)
        branch = edge_harden_scores[curve["name"]].get("observedStateBranch", "")
        include = edge_pass or branch == OBSERVED_STATE_V1804_EDGE_BRANCH
        if not include:
            continue
        baseline = baseline_scores[curve["name"]]
        no_edge = no_edge_scores[curve["name"]]
        forced = observed_state_v1804_forced_edge_score(curve, fit, amp_cap)
        if curve["name"] not in high_names and edge_pass:
            protected_forced_count += 1
            protected_forced_regs.append(forced["rmse"] - baseline["rmse"])
        edge_rule_rows.append(
            {
                "galaxy": curve["name"],
                "set": "clean-high-rmse" if curve["name"] in high_names else "clean-protected",
                "lockedRoute": curve["lockedModelRoute"],
                "edgeRulePass": edge_pass,
                "edgeRuleFailedTerms": "; ".join(failed_terms),
                "branch": branch,
                "baselineRmse": baseline["rmse"],
                "noEdgeRmse": no_edge["rmse"],
                "edgeHardenRmse": edge_harden_scores[curve["name"]]["rmse"],
                "forcedEdgeRmse": forced["rmse"],
                "incrementVsNoEdgeKmS": no_edge["rmse"] - edge_harden_scores[curve["name"]]["rmse"],
                "forcedRegressionVsBaselineKmS": forced["rmse"] - baseline["rmse"],
                "forcedRegressionVsNoEdgeKmS": forced["rmse"] - no_edge["rmse"],
                "memoryLoad": values.get("memoryLoad", ""),
                "fGasOut": values.get("fGasOut", ""),
                "outerBulgeShare": values.get("outerBulgeShare", ""),
                "outerDiskShare": values.get("outerDiskShare", ""),
                "outerGasShare": values.get("outerGasShare", ""),
                "hOverRout": values.get("hOverRout", ""),
                "uOut": values.get("uOut", ""),
                "uMax": values.get("uMax", ""),
                "pointDensity": values.get("pointDensity", ""),
                "barCurv": values.get("barCurv", ""),
            }
        )

    best = next(row for row in score_rows if row["track"] == "v18.04-edge-hardened")
    median_null_increment = safe_median(row["nullIncrementGainPct"] for row in null_rows)
    edge_null_margin = safe_median(row["edgeNullMarginPct"] for row in null_rows)
    protected_forced_max = max(protected_forced_regs or [0.0])
    protected_forced_stress_count = sum(1 for value in protected_forced_regs if value > 3.0)
    edge_rule_high_hits = sum(1 for row in edge_rule_rows if row["set"] == "clean-high-rmse" and row["edgeRulePass"])
    edge_rule_protected_hits = sum(1 for row in edge_rule_rows if row["set"] == "clean-protected" and row["edgeRulePass"])
    passes = (
        best["highGainPct"] >= 68.0
        and best["cleanGainPct"] >= 43.0
        and int(best["highAbove20"]) == 0
        and parse_float(best["maxProtectedRegressionKmS"]) <= 4.0
        and protected_forced_max <= 3.0
        and protected_forced_stress_count == 0
        and edge_null_margin >= 10.0
        and edge_rule_high_hits >= 1
        and edge_rule_protected_hits == 0
    )
    verdict = "v18.04 edge hardened review candidate passes" if passes else "v18.04 edge hardening blocked"
    summary = {
        "candidateId": "observed-state-response-v18.04-edge-hardened",
        "verdict": verdict,
        "bestTrack": "v18.04-edge-hardened",
        "bestHighGainPct": best["highGainPct"],
        "bestCleanGainPct": best["cleanGainPct"],
        "bestHighAbove20": best["highAbove20"],
        "bestMaxProtectedRegressionKmS": best["maxProtectedRegressionKmS"],
        "edgeBranch": OBSERVED_STATE_V1804_EDGE_BRANCH,
        "edgeActiveHighGalaxies": sorted(actual_edge_names),
        "edgeActualIncrementGainPct": actual_edge_increment_pct,
        "edgeActualTotalGainPct": actual_edge_total_pct,
        "edgeActualIncrementGainKmS": actual_edge_increment_kms,
        "edgeMedianStateRespectingNullGainPct": median_null_increment,
        "edgeNullMarginPct": edge_null_margin,
        "edgeRuleHighHits": edge_rule_high_hits,
        "edgeRuleProtectedHits": edge_rule_protected_hits,
        "protectedForcedEdgeHitCount": protected_forced_count,
        "maxProtectedForcedEdgeRegressionKmS": protected_forced_max,
        "protectedForcedEdgeStressCount": protected_forced_stress_count,
        "weakSystematicsLeakage": 0,
    }

    artifact_payload.setdefault("metadata", {})["edgeHardenV1804"] = {
        "verdict": verdict,
        "bestTrack": summary["bestTrack"],
        "bestHighGainPct": summary["bestHighGainPct"],
        "bestCleanGainPct": summary["bestCleanGainPct"],
        "bestHighAbove20": summary["bestHighAbove20"],
        "edgeBranch": summary["edgeBranch"],
        "edgeActiveHighGalaxies": summary["edgeActiveHighGalaxies"],
        "edgeActualIncrementGainPct": summary["edgeActualIncrementGainPct"],
        "edgeMedianStateRespectingNullGainPct": summary["edgeMedianStateRespectingNullGainPct"],
        "edgeNullMarginPct": summary["edgeNullMarginPct"],
        "edgeRuleHighHits": summary["edgeRuleHighHits"],
        "edgeRuleProtectedHits": summary["edgeRuleProtectedHits"],
        "maxProtectedForcedEdgeRegressionKmS": summary["maxProtectedForcedEdgeRegressionKmS"],
        "weakSystematicsLeakage": 0,
    }
    write_window_json_assignment(V18_BROWSER_ARTIFACT_PATH, "MTS_V18_01_REVIEW_CANDIDATE", artifact_payload)
    write_window_json_assignment(out_dir / f"{prefix}_browser_artifact.js", "MTS_V18_01_REVIEW_CANDIDATE", artifact_payload)

    formula = {
        "candidateId": summary["candidateId"],
        "mechanism": "v18.03 review-edge retained only when the full buffered disk-shear state fingerprint is present",
        "baseTrack": "v18.03-safety-gated-review-edge",
        "fallbackTrackWhenEdgeRuleFails": "v18.03-safety-gated",
        "edgeBranch": OBSERVED_STATE_V1804_EDGE_BRANCH,
        "edgeRuleTerms": OBSERVED_STATE_V1804_EDGE_TERMS,
        "forbiddenInputs": ["galaxy name", "raw residual lookup", "raw RMSE formula input", "weak/systematics training"],
    }
    write_csv(out_dir / f"{prefix}_scores.csv", score_rows)
    write_csv(out_dir / f"{prefix}_case_ledger.csv", case_rows)
    write_csv(out_dir / f"{prefix}_edge_rule_hits.csv", edge_rule_rows)
    write_csv(out_dir / f"{prefix}_nulls.csv", null_rows)
    (out_dir / f"{prefix}_formula.json").write_text(json.dumps(json_clean(formula), indent=2, sort_keys=True), encoding="utf-8")

    report = [
        "# MTS v18.04 Edge Hardening Pass",
        "",
        "This pass does not add a new repair. It keeps the v18.03 safety-gated review-edge candidate and makes the single buffered disk-shear high-q branch state-respecting in its null tests.",
        "",
        "## Result",
        "",
        f"- Verdict: `{verdict}`.",
        f"- Best track: `{summary['bestTrack']}`.",
        f"- High-RMSE gain: `{fmt(summary['bestHighGainPct'])}%`.",
        f"- Clean-set gain: `{fmt(summary['bestCleanGainPct'])}%`.",
        f"- High-RMSE above 20: `{summary['bestHighAbove20']}`.",
        f"- Edge branch: `{summary['edgeBranch']}`.",
        f"- Edge active high galaxies: `{'; '.join(summary['edgeActiveHighGalaxies'])}`.",
        f"- Edge incremental gain over no-edge v18.03: `{fmt(summary['edgeActualIncrementGainPct'])}%` / `{fmt(summary['edgeActualIncrementGainKmS'])}` km/s.",
        f"- Median state-respecting null increment: `{fmt(summary['edgeMedianStateRespectingNullGainPct'])}%`.",
        f"- Edge null margin: `{fmt(summary['edgeNullMarginPct'])}` percentage points.",
        f"- Edge rule high hits: `{summary['edgeRuleHighHits']}`.",
        f"- Edge rule protected hits: `{summary['edgeRuleProtectedHits']}`.",
        f"- Max protected forced-edge regression: `{fmt(summary['maxProtectedForcedEdgeRegressionKmS'])}` km/s.",
        f"- Weak/systematics leakage: `0`.",
        "",
        "## Track Scores",
        "",
        "| Track | High gain | Clean gain | Above 20 | Protected max | Active branches |",
        "| --- | ---: | ---: | ---: | ---: | ---: |",
    ]
    for row in score_rows:
        report.append(
            f"| {row['track']} | {fmt(row['highGainPct'])}% | {fmt(row['cleanGainPct'])}% | {row['highAbove20']} | "
            f"{fmt(row['maxProtectedRegressionKmS'])} | {row['activeBranchCount']} |"
        )
    report.extend(
        [
            "",
            "## What Changed",
            "",
            "- The branch `buffered disk-shear high-q shape` is retained only when the full buffered disk-shear edge rule is satisfied.",
            "- State-respecting same-active-count nulls must pass that same rule before the branch can be forced.",
            "- This is still a review candidate, not canonical MTS.",
        ]
    )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report), encoding="utf-8")

    capsule = {
        "analysisName": "mts-observed-v18-edge-harden-v1",
        "candidateId": summary["candidateId"],
        "verdict": verdict,
        "summary": summary,
        "bestTrackScore": best,
        "outputFiles": [
            f"{prefix}_scores.csv",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_edge_rule_hits.csv",
            f"{prefix}_nulls.csv",
            f"{prefix}_formula.json",
            f"{prefix}_browser_artifact.js",
            f"{prefix}_report.md",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_observedstatev18edgeharden(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_OBSERVED_STATE_V18_EDGE_HARDEN_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_observed_state_v18_edge_harden_artifacts(out_dir)
    summary = capsule["summary"]
    print("MTS v18.04 edge hardening pass")
    print(f"verdict={summary['verdict']}")
    print(
        "\t".join(
            [
                f"best={summary['bestTrack']}",
                f"high={fmt(summary['bestHighGainPct'])}%",
                f"clean={fmt(summary['bestCleanGainPct'])}%",
                f"above20={summary['bestHighAbove20']}",
                f"edge={summary['edgeBranch']}",
                f"edge_hits={summary['edgeRuleHighHits']}",
                f"protected_edge_hits={summary['edgeRuleProtectedHits']}",
                f"edge_null_margin={fmt(summary['edgeNullMarginPct'])}",
                f"weak_leakage={summary['weakSystematicsLeakage']}",
            ]
        )
    )
    print(f"Wrote v18 edge hardening pass to {out_dir.resolve()}")


def observed_state_v1805_score_curve(curve: dict, fit: dict, amp_cap: float) -> dict:
    score = observed_state_v1804_score_curve(curve, fit, amp_cap)
    score["observedStateV1805Track"] = "v18.05-release-stress"
    return score


def observed_state_v1805_forced_branch_score(curve: dict, branch: str, fit: dict, amp_cap: float) -> dict:
    if branch == OBSERVED_STATE_V1804_EDGE_BRANCH:
        return observed_state_v1804_forced_edge_score(curve, fit, amp_cap)
    return observed_state_v1803_forced_branch_score(curve, branch, fit, amp_cap, "v18.03-safety-gated-review-edge")


def observed_state_v1805_score_with_disabled_branch(curve: dict, fit: dict, amp_cap: float, branch: str) -> dict:
    return observed_state_with_disabled_branches(
        {branch},
        lambda: observed_state_v1805_score_curve(curve, fit, amp_cap),
    )


def observed_state_v1805_browser_parity_rows(
    clean_curves: list[dict],
    weak_names: set[str],
    fit: dict,
    amp_cap: float,
    artifact_payload: dict,
) -> tuple[list[dict], dict]:
    artifact_curves = artifact_payload.get("curves", {})
    rows: list[dict] = []
    for curve in clean_curves:
        name = curve["name"]
        candidate = observed_state_v1805_score_curve(curve, fit, amp_cap)
        artifact = artifact_curves.get(name, {})
        artifact_rmse = parse_float(artifact.get("v18Rmse", artifact.get("rmse", math.nan)))
        artifact_route = str(artifact.get("v18CandidateRoute", artifact.get("candidateRoute", "")))
        rmse_diff = artifact_rmse - candidate["rmse"] if math.isfinite(artifact_rmse) else math.nan
        route_match = artifact_route == candidate["candidateRoute"]
        parity_claimed = name not in weak_names
        parity_pass = (not parity_claimed) or (math.isfinite(rmse_diff) and abs(rmse_diff) <= 1e-8 and route_match)
        rows.append(
            {
                "galaxy": name,
                "set": "clean-protected",
                "candidateRmse": candidate["rmse"],
                "artifactRmse": artifact_rmse,
                "artifactMinusCandidateRmse": rmse_diff,
                "candidateRoute": candidate["candidateRoute"],
                "artifactRoute": artifact_route,
                "routeMatch": route_match,
                "branch": candidate.get("observedStateBranch", ""),
                "parityClaimed": parity_claimed,
                "parityPass": parity_pass,
            }
        )
    claimed = [row for row in rows if row["parityClaimed"]]
    summary = {
        "cleanParityMismatchCount": sum(1 for row in claimed if not row["parityPass"]),
        "maxCleanArtifactMinusCandidateRmseAbs": max([abs(parse_float(row["artifactMinusCandidateRmse"], 0.0)) for row in claimed] or [0.0]),
    }
    return rows, summary


def observed_state_v1805_seed_replay_rows(clean_curves: list[dict], high_names: set[str], fit: dict, amp_cap: float) -> list[dict]:
    rows: list[dict] = []
    for seed in OBSERVED_STATE_V1800_REPLAY_SEEDS:
        _train_names, holdout_names = observed_state_split(clean_curves, seed, HOLDOUT_FRACTION)
        holdout = [curve for curve in clean_curves if curve["name"] in holdout_names]
        base_scores = {curve["name"]: score_curve(curve) for curve in holdout}
        candidate_scores = {curve["name"]: observed_state_v1805_score_curve(curve, fit, amp_cap) for curve in holdout}
        paired = [(curve, base_scores[curve["name"]], candidate_scores[curve["name"]]) for curve in holdout]
        rows.append(observed_state_law_freeze_summary(seed, "v18.05-release-stress", paired, high_names))
    return rows


def observed_state_v1805_branch_ablation_rows(
    clean_curves: list[dict],
    high_names: set[str],
    fit: dict,
    amp_cap: float,
    baseline_scores: dict[str, dict],
    candidate_scores: dict[str, dict],
    candidate_summary: dict,
) -> list[dict]:
    active_branches = sorted(
        {
            score.get("observedStateBranch", "")
            for curve in clean_curves
            for score in [candidate_scores[curve["name"]]]
            if score.get("observedStateBranch") and parse_float(score.get("observedStateSoftActivation"), 0.0) > 0.0
        }
    )
    rows: list[dict] = []
    for branch in active_branches:
        ablated_scores = {
            curve["name"]: observed_state_v1805_score_with_disabled_branch(curve, fit, amp_cap, branch)
            for curve in clean_curves
        }
        paired = [(curve, baseline_scores[curve["name"]], ablated_scores[curve["name"]]) for curve in clean_curves]
        metric = observed_state_v1803_track_summary(paired, high_names)
        active_high = [
            curve["name"]
            for curve in clean_curves
            if curve["name"] in high_names and candidate_scores[curve["name"]].get("observedStateBranch") == branch
        ]
        active_protected = [
            curve["name"]
            for curve in clean_curves
            if curve["name"] not in high_names and candidate_scores[curve["name"]].get("observedStateBranch") == branch
        ]
        rows.append(
            {
                "branch": branch,
                "activeHighCount": len(active_high),
                "activeProtectedCount": len(active_protected),
                "activeHighGalaxies": "; ".join(active_high),
                "activeProtectedGalaxies": "; ".join(active_protected),
                "candidateHighGainPct": candidate_summary["highGainPct"],
                "ablationHighGainPct": metric["highGainPct"],
                "highGainLossPct": candidate_summary["highGainPct"] - metric["highGainPct"],
                "candidateCleanGainPct": candidate_summary["cleanGainPct"],
                "ablationCleanGainPct": metric["cleanGainPct"],
                "cleanGainLossPct": candidate_summary["cleanGainPct"] - metric["cleanGainPct"],
                "ablationHighAbove20": metric["highAbove20"],
                "ablationMaxProtectedRegressionKmS": metric["maxProtectedRegressionKmS"],
                "ablationProtectedWorseCount": metric["protectedWorseCount"],
                "branchEssentialForZeroAbove20": metric["highAbove20"] > 0,
                "branchReleaseStatus": "essential" if metric["highAbove20"] > 0 or (candidate_summary["highGainPct"] - metric["highGainPct"]) >= 1.0 else "small-effect",
            }
        )
    return rows


def observed_state_v1805_protected_stress_rows(
    clean_curves: list[dict],
    fit: dict,
    amp_cap: float,
) -> tuple[list[dict], dict]:
    curves_by_name = {curve["name"]: curve for curve in clean_curves}
    protected_analog_path = DEFAULT_OBSERVED_STATE_V18_BRANCH_IDENTITY_OUT / "mts_observed_v18_branch_identity_protected_analogues.csv"
    if not protected_analog_path.exists():
        write_observed_state_v18_branch_identity_artifacts(DEFAULT_OBSERVED_STATE_V18_BRANCH_IDENTITY_OUT)
    protected_analog_rows = read_csv_rows(protected_analog_path)
    rows: list[dict] = []
    regressions: list[float] = []
    for row in protected_analog_rows:
        branch = row.get("branch", "")
        galaxy = row.get("protectedGalaxy", "")
        curve = curves_by_name.get(galaxy)
        if not curve:
            continue
        baseline = score_curve(curve)
        forced = observed_state_v1805_forced_branch_score(curve, branch, fit, amp_cap)
        regression = forced["rmse"] - baseline["rmse"]
        regressions.append(regression)
        rows.append(
            {
                "branch": branch,
                "protectedGalaxy": galaxy,
                "nearestHighBranchGalaxy": row.get("nearestHighBranchGalaxy", ""),
                "stateDistance": row.get("stateDistance", ""),
                "baselineRmse": baseline["rmse"],
                "forcedRmse": forced["rmse"],
                "forcedRegressionKmS": regression,
                "forcedCandidateRoute": forced.get("candidateRoute", ""),
                "vetoedBranch": forced.get("observedStateV1804VetoedBranch", forced.get("observedStateV1803VetoedBranch", "")),
                "vetoReason": forced.get("observedStateV1804VetoReason", forced.get("observedStateV1803VetoReason", "")),
                "edgeRulePass": forced.get("observedStateV1804EdgeRulePass", ""),
                "forcedEdgeApplied": forced.get("observedStateV1804ForcedEdgeApplied", ""),
            }
        )
    summary = {
        "protectedStressRows": len(rows),
        "maxProtectedForcedRegressionKmS": max(regressions or [0.0]),
        "protectedForcedWorseCount": sum(1 for value in regressions if value > 1e-9),
        "protectedForcedStressCount": sum(1 for value in regressions if value > 3.0),
    }
    return rows, summary


def observed_state_v1805_null_control_rows(
    clean_curves: list[dict],
    high_names: set[str],
    fit: dict,
    amp_cap: float,
    baseline_scores: dict[str, dict],
    candidate_scores: dict[str, dict],
    candidate_summary: dict,
) -> tuple[list[dict], dict]:
    high_curves = [curve for curve in clean_curves if curve["name"] in high_names]
    active_high = [
        curve
        for curve in high_curves
        if candidate_scores[curve["name"]].get("observedStateBranch")
        and parse_float(candidate_scores[curve["name"]].get("observedStateSoftActivation"), 0.0) > 0.0
    ]
    active_by_route: dict[str, int] = {}
    active_branches = [candidate_scores[curve["name"]].get("observedStateBranch", "") for curve in active_high]
    for curve in active_high:
        active_by_route[curve["lockedModelRoute"]] = active_by_route.get(curve["lockedModelRoute"], 0) + 1
    rows: list[dict] = []
    for seed in OBSERVED_STATE_V1800_REPLAY_SEEDS:
        rng = random.Random(f"v18.05-release-null:{seed}")
        selected: list[dict] = []
        used: set[str] = set()
        for route, count in sorted(active_by_route.items()):
            route_pool = [curve for curve in high_curves if curve["lockedModelRoute"] == route and curve["name"] not in used]
            rng.shuffle(route_pool)
            selected.extend(route_pool[:count])
            used.update(curve["name"] for curve in route_pool[:count])
        if len(selected) < len(active_high):
            fallback = [curve for curve in high_curves if curve["name"] not in used]
            rng.shuffle(fallback)
            selected.extend(fallback[: len(active_high) - len(selected)])
        shuffled_branches = list(active_branches)
        rng.shuffle(shuffled_branches)
        forced_pairs = []
        for curve, branch in zip(selected, shuffled_branches):
            forced = observed_state_v1805_forced_branch_score(curve, branch, fit, amp_cap)
            forced_pairs.append((curve, baseline_scores[curve["name"]], forced, branch))
        null_gain = pct_improvement(
            safe_mean(pair[1]["rmse"] for pair in forced_pairs),
            safe_mean(pair[2]["rmse"] for pair in forced_pairs),
        )
        rows.append(
            {
                "nullType": "same-route same-active-count branch-label shuffle",
                "seed": seed,
                "selectedCount": len(selected),
                "candidateHighGainPct": candidate_summary["highGainPct"],
                "nullHighGainPct": null_gain,
                "nullMarginPct": candidate_summary["highGainPct"] - null_gain,
                "maxNullRegressionKmS": max([pair[2]["rmse"] - pair[1]["rmse"] for pair in forced_pairs] or [0.0]),
                "selectedGalaxies": "; ".join(curve["name"] for curve in selected),
                "forcedBranches": "; ".join(branch for _curve, _base, _forced, branch in forced_pairs),
            }
        )
    edge_dir = DEFAULT_OBSERVED_STATE_V18_EDGE_HARDEN_OUT
    edge_null_path = edge_dir / "mts_observed_v18_edge_harden_nulls.csv"
    if not edge_null_path.exists():
        write_observed_state_v18_edge_harden_artifacts(edge_dir)
    for row in read_csv_rows(edge_null_path):
        rows.append(
            {
                "nullType": "state-respecting edge null",
                "seed": row.get("seed", ""),
                "selectedCount": row.get("selectedCount", ""),
                "candidateHighGainPct": candidate_summary["highGainPct"],
                "nullHighGainPct": row.get("nullIncrementGainPct", ""),
                "nullMarginPct": row.get("edgeNullMarginPct", ""),
                "maxNullRegressionKmS": row.get("maxRegressionVsBaselineKmS", ""),
                "selectedGalaxies": row.get("selectedGalaxies", ""),
                "forcedBranches": OBSERVED_STATE_V1804_EDGE_BRANCH,
            }
        )
    branch_shuffle_rows = [row for row in rows if row["nullType"] == "same-route same-active-count branch-label shuffle"]
    edge_rows = [row for row in rows if row["nullType"] == "state-respecting edge null"]
    summary = {
        "medianBranchShuffleNullHighGainPct": safe_median(parse_float(row["nullHighGainPct"]) for row in branch_shuffle_rows),
        "medianBranchShuffleNullMarginPct": safe_median(parse_float(row["nullMarginPct"]) for row in branch_shuffle_rows),
        "minBranchShuffleNullMarginPct": min([parse_float(row["nullMarginPct"], math.inf) for row in branch_shuffle_rows] or [math.nan]),
        "medianEdgeNullMarginPct": safe_median(parse_float(row["nullMarginPct"]) for row in edge_rows),
        "maxNullRegressionKmS": max([parse_float(row["maxNullRegressionKmS"], 0.0) for row in rows] or [0.0]),
    }
    return rows, summary


def write_observed_state_v18_release_stress_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_observed_v18_release_stress"
    context = observed_state_candidate_context()
    clean_curves = context["cleanCurves"]
    high_names = context["highNames"]
    weak_names = context["weakNames"]
    fit = context["fit"]
    amp_cap = context["ampCap"]
    artifact_payload = read_window_json_assignment(V18_BROWSER_ARTIFACT_PATH, "MTS_V18_01_REVIEW_CANDIDATE")

    baseline_scores = {curve["name"]: score_curve(curve) for curve in clean_curves}
    candidate_scores = {curve["name"]: observed_state_v1805_score_curve(curve, fit, amp_cap) for curve in clean_curves}
    paired = [(curve, baseline_scores[curve["name"]], candidate_scores[curve["name"]]) for curve in clean_curves]
    candidate_summary = observed_state_v1803_track_summary(paired, high_names)

    case_rows: list[dict] = []
    for curve, baseline, candidate in paired:
        case_rows.append(
            {
                "galaxy": curve["name"],
                "set": "clean-high-rmse" if curve["name"] in high_names else "clean-protected",
                "lockedRoute": curve.get("lockedModelRoute", ""),
                "baselineRmse": baseline["rmse"],
                "candidateRmse": candidate["rmse"],
                "gainKmS": baseline["rmse"] - candidate["rmse"],
                "candidateRoute": candidate["candidateRoute"],
                "branch": candidate.get("observedStateBranch", ""),
                "family": candidate.get("observedStateFamily", ""),
                "softActivation": candidate.get("observedStateSoftActivation", ""),
                "edgeRulePass": candidate.get("observedStateV1804EdgeRulePass", ""),
                "stillAbove20": candidate["rmse"] >= 20.0 if curve["name"] in high_names else "",
                "protectedRegressionKmS": candidate["rmse"] - baseline["rmse"] if curve["name"] not in high_names else "",
            }
        )

    seed_rows = observed_state_v1805_seed_replay_rows(clean_curves, high_names, fit, amp_cap)
    branch_rows = observed_state_v1805_branch_ablation_rows(
        clean_curves,
        high_names,
        fit,
        amp_cap,
        baseline_scores,
        candidate_scores,
        candidate_summary,
    )
    protected_rows, protected_summary = observed_state_v1805_protected_stress_rows(clean_curves, fit, amp_cap)
    null_rows, null_summary = observed_state_v1805_null_control_rows(
        clean_curves,
        high_names,
        fit,
        amp_cap,
        baseline_scores,
        candidate_scores,
        candidate_summary,
    )
    parity_rows, parity_summary = observed_state_v1805_browser_parity_rows(clean_curves, weak_names, fit, amp_cap, artifact_payload)

    median_holdout_high = safe_median(row["highGainPct"] for row in seed_rows)
    median_holdout_clean = safe_median(row["cleanGainPct"] for row in seed_rows)
    max_holdout_above20 = max([parse_float(row["highStillAbove20"], 0.0) for row in seed_rows] or [0.0])
    max_holdout_protected = max([parse_float(row["maxProtectedRegression"], 0.0) for row in seed_rows] or [0.0])
    min_holdout_high = min([parse_float(row["highGainPct"], math.inf) for row in seed_rows] or [math.nan])
    worst_ablation_above20 = max([parse_float(row["ablationHighAbove20"], 0.0) for row in branch_rows] or [0.0])
    essential_branch_count = sum(1 for row in branch_rows if row["branchReleaseStatus"] == "essential")

    passes = (
        candidate_summary["highGainPct"] >= 68.0
        and candidate_summary["cleanGainPct"] >= 43.0
        and int(candidate_summary["highAbove20"]) == 0
        and parse_float(candidate_summary["maxProtectedRegressionKmS"]) <= 4.0
        and median_holdout_high >= 60.0
        and median_holdout_clean >= 38.0
        and max_holdout_above20 <= 4
        and max_holdout_protected <= 4.0
        and protected_summary["maxProtectedForcedRegressionKmS"] <= 3.0
        and protected_summary["protectedForcedStressCount"] == 0
        and null_summary["medianBranchShuffleNullMarginPct"] >= 10.0
        and null_summary["medianEdgeNullMarginPct"] >= 10.0
        and parity_summary["cleanParityMismatchCount"] == 0
    )
    verdict = "v18.05 release candidate passes stress gate" if passes else "v18.05 release stress blocked"
    summary = {
        "candidateId": "observed-state-response-v18.05-release-stress",
        "verdict": verdict,
        "nominalHighGainPct": candidate_summary["highGainPct"],
        "nominalCleanGainPct": candidate_summary["cleanGainPct"],
        "nominalHighAbove20": candidate_summary["highAbove20"],
        "nominalMaxProtectedRegressionKmS": candidate_summary["maxProtectedRegressionKmS"],
        "medianHoldoutHighGainPct": median_holdout_high,
        "medianHoldoutCleanGainPct": median_holdout_clean,
        "minHoldoutHighGainPct": min_holdout_high,
        "maxHoldoutHighAbove20": max_holdout_above20,
        "maxHoldoutProtectedRegressionKmS": max_holdout_protected,
        "branchCount": len(branch_rows),
        "essentialBranchCount": essential_branch_count,
        "worstAblationHighAbove20": worst_ablation_above20,
        "medianBranchShuffleNullHighGainPct": null_summary["medianBranchShuffleNullHighGainPct"],
        "medianBranchShuffleNullMarginPct": null_summary["medianBranchShuffleNullMarginPct"],
        "medianEdgeNullMarginPct": null_summary["medianEdgeNullMarginPct"],
        "maxProtectedForcedRegressionKmS": protected_summary["maxProtectedForcedRegressionKmS"],
        "protectedForcedStressCount": protected_summary["protectedForcedStressCount"],
        "cleanParityMismatchCount": parity_summary["cleanParityMismatchCount"],
        "maxCleanArtifactMinusCandidateRmseAbs": parity_summary["maxCleanArtifactMinusCandidateRmseAbs"],
        "weakSystematicsLeakage": 0,
    }

    artifact_payload.setdefault("metadata", {})["releaseStressV1805"] = {
        "verdict": verdict,
        "candidateId": summary["candidateId"],
        "nominalHighGainPct": summary["nominalHighGainPct"],
        "nominalCleanGainPct": summary["nominalCleanGainPct"],
        "nominalHighAbove20": summary["nominalHighAbove20"],
        "medianHoldoutHighGainPct": summary["medianHoldoutHighGainPct"],
        "medianHoldoutCleanGainPct": summary["medianHoldoutCleanGainPct"],
        "medianBranchShuffleNullMarginPct": summary["medianBranchShuffleNullMarginPct"],
        "medianEdgeNullMarginPct": summary["medianEdgeNullMarginPct"],
        "maxProtectedForcedRegressionKmS": summary["maxProtectedForcedRegressionKmS"],
        "cleanParityMismatchCount": summary["cleanParityMismatchCount"],
        "weakSystematicsLeakage": 0,
    }
    artifact_payload = write_observed_state_v1805_release_artifact_files(artifact_payload, out_dir, prefix)
    write_window_json_assignment(out_dir / f"{prefix}_browser_artifact.js", "MTS_V18_01_REVIEW_CANDIDATE", artifact_payload)

    formula = {
        "candidateId": summary["candidateId"],
        "baseCandidate": "observed-state-response-v18.04-edge-hardened",
        "mechanism": "frozen v18.04 observed-state response; no new branches, q changes, amplitude patch search, residual lookup, RMSE lookup, or weak/systematics fitting",
        "edgeHardenedBranch": OBSERVED_STATE_V1804_EDGE_BRANCH,
        "edgeRuleTerms": OBSERVED_STATE_V1804_EDGE_TERMS,
        "forbiddenInputs": ["galaxy name", "raw residual lookup", "raw RMSE formula input", "weak/systematics training"],
    }
    write_csv(out_dir / f"{prefix}_scores.csv", [summary])
    write_csv(out_dir / f"{prefix}_seed_replay.csv", seed_rows)
    write_csv(out_dir / f"{prefix}_case_ledger.csv", case_rows)
    write_csv(out_dir / f"{prefix}_branch_ablation.csv", branch_rows)
    write_csv(out_dir / f"{prefix}_protected_stress.csv", protected_rows)
    write_csv(out_dir / f"{prefix}_null_controls.csv", null_rows)
    write_csv(out_dir / f"{prefix}_browser_parity.csv", parity_rows)
    (out_dir / f"{prefix}_formula.json").write_text(json.dumps(json_clean(formula), indent=2, sort_keys=True), encoding="utf-8")

    improved_high = sorted(
        [row for row in case_rows if row["set"] == "clean-high-rmse"],
        key=lambda row: parse_float(row["gainKmS"], 0.0),
        reverse=True,
    )
    worsened = [row for row in case_rows if parse_float(row["gainKmS"], 0.0) < -1e-9]
    report = [
        "# MTS v18.05 Release Stress Gate",
        "",
        "This pass freezes v18.04 and tries to break it. It does not add new repair branches.",
        "",
        "## Result",
        "",
        f"- Verdict: `{verdict}`.",
        f"- Nominal high-RMSE gain: `{fmt(summary['nominalHighGainPct'])}%`.",
        f"- Nominal clean-set gain: `{fmt(summary['nominalCleanGainPct'])}%`.",
        f"- Nominal high-RMSE above 20: `{summary['nominalHighAbove20']}`.",
        f"- Median holdout high-RMSE gain: `{fmt(summary['medianHoldoutHighGainPct'])}%`.",
        f"- Median holdout clean-set gain: `{fmt(summary['medianHoldoutCleanGainPct'])}%`.",
        f"- Branch-shuffle null margin: `{fmt(summary['medianBranchShuffleNullMarginPct'])}` percentage points.",
        f"- State-respecting edge null margin: `{fmt(summary['medianEdgeNullMarginPct'])}` percentage points.",
        f"- Max forced protected-lookalike regression: `{fmt(summary['maxProtectedForcedRegressionKmS'])}` km/s.",
        f"- Browser parity mismatches: `{summary['cleanParityMismatchCount']}`.",
        f"- Weak/systematics leakage: `0`.",
        "",
        "## Largest High-RMSE Repairs",
        "",
        "| Galaxy | Baseline | v18.05 | Gain | Branch |",
        "| --- | ---: | ---: | ---: | --- |",
    ]
    for row in improved_high[:15]:
        report.append(
            f"| {row['galaxy']} | {fmt(row['baselineRmse'])} | {fmt(row['candidateRmse'])} | {fmt(row['gainKmS'])} | {row['branch']} |"
        )
    report.extend(
        [
            "",
            "## Regressions",
            "",
        ]
    )
    if worsened:
        for row in worsened:
            report.append(f"- `{row['galaxy']}` worsened by `{fmt(-parse_float(row['gainKmS']))}` km/s.")
    else:
        report.append("- No clean case worsened under the frozen v18.04 candidate.")
    report.extend(
        [
            "",
            "## Stress Tests",
            "",
            f"- Seed replays: `{len(seed_rows)}`.",
            f"- Branch ablations: `{len(branch_rows)}` branches, `{essential_branch_count}` essential under the zero-above-20 gate.",
            f"- Protected-lookalike forced stress rows: `{protected_summary['protectedStressRows']}`.",
            f"- Null controls: `{len(null_rows)}`.",
        ]
    )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report), encoding="utf-8")

    capsule = {
        "analysisName": "mts-observed-v18-release-stress-v1",
        "candidateId": summary["candidateId"],
        "verdict": verdict,
        "summary": summary,
        "outputFiles": [
            f"{prefix}_scores.csv",
            f"{prefix}_seed_replay.csv",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_branch_ablation.csv",
            f"{prefix}_protected_stress.csv",
            f"{prefix}_null_controls.csv",
            f"{prefix}_browser_parity.csv",
            f"{prefix}_formula.json",
            f"{prefix}_browser_artifact.js",
            f"{prefix}_release_candidate_artifact.js",
            f"{prefix}_report.md",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_observedstatev18releasestress(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_OBSERVED_STATE_V18_RELEASE_STRESS_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_observed_state_v18_release_stress_artifacts(out_dir)
    summary = capsule["summary"]
    print("MTS v18.05 release stress gate")
    print(f"verdict={summary['verdict']}")
    print(
        "\t".join(
            [
                f"high={fmt(summary['nominalHighGainPct'])}%",
                f"clean={fmt(summary['nominalCleanGainPct'])}%",
                f"above20={summary['nominalHighAbove20']}",
                f"holdout_high={fmt(summary['medianHoldoutHighGainPct'])}%",
                f"branch_null_margin={fmt(summary['medianBranchShuffleNullMarginPct'])}",
                f"edge_null_margin={fmt(summary['medianEdgeNullMarginPct'])}",
                f"protected_forced={fmt(summary['maxProtectedForcedRegressionKmS'])}",
                f"parity_mismatch={summary['cleanParityMismatchCount']}",
                f"weak_leakage={summary['weakSystematicsLeakage']}",
            ]
        )
    )
    print(f"Wrote v18 release stress gate to {out_dir.resolve()}")


def observed_state_v1805_svg_bar_chart(
    title: str,
    rows: list[dict],
    label_key: str,
    series: list[tuple[str, str, str]],
    max_value: float | None = None,
    width: int = 1160,
    row_height: int = 24,
) -> str:
    margin_left = 210
    margin_right = 120
    margin_top = 76
    margin_bottom = 48
    plot_width = width - margin_left - margin_right
    height = margin_top + margin_bottom + max(1, len(rows)) * row_height
    values = [
        parse_float(row.get(key), 0.0)
        for row in rows
        for _label, key, _color in series
    ]
    xmax = max_value if max_value and max_value > 0 else max(values or [1.0])
    xmax = max(xmax, 1.0)
    parts = [
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}">',
        '<rect width="100%" height="100%" fill="#fbfaf7"/>',
        f'<text x="{margin_left}" y="32" font-family="Arial, sans-serif" font-size="22" font-weight="700" fill="#111">{html.escape(title)}</text>',
    ]
    for tick in range(0, 6):
        value = xmax * tick / 5.0
        x = margin_left + plot_width * tick / 5.0
        parts.append(f'<line x1="{x:.2f}" y1="{margin_top - 16}" x2="{x:.2f}" y2="{height - margin_bottom + 8}" stroke="#e2ded6" stroke-width="1"/>')
        parts.append(f'<text x="{x:.2f}" y="{height - 18}" font-family="Arial, sans-serif" font-size="11" text-anchor="middle" fill="#555">{fmt(value, 0)}</text>')
    legend_x = margin_left
    for label, _key, color in series:
        parts.append(f'<rect x="{legend_x}" y="46" width="12" height="12" fill="{color}"/>')
        parts.append(f'<text x="{legend_x + 18}" y="56" font-family="Arial, sans-serif" font-size="12" fill="#333">{html.escape(label)}</text>')
        legend_x += 150
    band_height = max(4, row_height / max(1, len(series)) - 3)
    for idx, row in enumerate(rows):
        y_base = margin_top + idx * row_height
        label = str(row.get(label_key, ""))
        parts.append(f'<text x="{margin_left - 10}" y="{y_base + row_height * 0.67:.2f}" font-family="Arial, sans-serif" font-size="12" text-anchor="end" fill="#222">{html.escape(label)}</text>')
        for sidx, (_label, key, color) in enumerate(series):
            value = max(0.0, parse_float(row.get(key), 0.0))
            bar_w = plot_width * value / xmax
            y = y_base + 2 + sidx * (band_height + 2)
            parts.append(f'<rect x="{margin_left}" y="{y:.2f}" width="{bar_w:.2f}" height="{band_height:.2f}" fill="{color}" rx="2"/>')
            if sidx == len(series) - 1:
                parts.append(f'<text x="{margin_left + bar_w + 5:.2f}" y="{y + band_height:.2f}" font-family="Arial, sans-serif" font-size="10" fill="#444">{fmt(value)}</text>')
    parts.append("</svg>")
    return "\n".join(parts)


def observed_state_v1805_svg_null_chart(rows: list[dict], width: int = 900, height: int = 460) -> str:
    margin_left = 80
    margin_right = 40
    margin_top = 70
    margin_bottom = 100
    plot_width = width - margin_left - margin_right
    plot_height = height - margin_top - margin_bottom
    max_value = max([parse_float(row.get("gainPct"), 0.0) for row in rows] + [1.0])
    parts = [
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}">',
        '<rect width="100%" height="100%" fill="#fbfaf7"/>',
        f'<text x="{margin_left}" y="34" font-family="Arial, sans-serif" font-size="22" font-weight="700" fill="#111">v18.05 null comparison</text>',
    ]
    for tick in range(0, 6):
        value = max_value * tick / 5.0
        y = margin_top + plot_height - plot_height * tick / 5.0
        parts.append(f'<line x1="{margin_left}" y1="{y:.2f}" x2="{width - margin_right}" y2="{y:.2f}" stroke="#e2ded6" stroke-width="1"/>')
        parts.append(f'<text x="{margin_left - 8}" y="{y + 4:.2f}" font-family="Arial, sans-serif" font-size="11" text-anchor="end" fill="#555">{fmt(value, 0)}%</text>')
    slot = plot_width / max(1, len(rows))
    for idx, row in enumerate(rows):
        value = parse_float(row.get("gainPct"), 0.0)
        bar_h = plot_height * value / max_value
        x = margin_left + idx * slot + slot * 0.18
        y = margin_top + plot_height - bar_h
        color = row.get("color", "#2f7fbf")
        label = str(row.get("label", ""))
        parts.append(f'<rect x="{x:.2f}" y="{y:.2f}" width="{slot * 0.64:.2f}" height="{bar_h:.2f}" fill="{color}" rx="4"/>')
        parts.append(f'<text x="{x + slot * 0.32:.2f}" y="{y - 6:.2f}" font-family="Arial, sans-serif" font-size="12" text-anchor="middle" fill="#222">{fmt(value)}%</text>')
        parts.append(f'<text x="{x + slot * 0.32:.2f}" y="{height - 62}" font-family="Arial, sans-serif" font-size="12" text-anchor="middle" fill="#333">{html.escape(label)}</text>')
    parts.append(f'<text x="{margin_left}" y="{height - 26}" font-family="Arial, sans-serif" font-size="12" fill="#555">Higher is better. Nulls are controls, not framework candidates.</text>')
    parts.append("</svg>")
    return "\n".join(parts)


def write_observed_state_v18_evidence_export_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_v18_05_evidence"
    source_dir = DEFAULT_OBSERVED_STATE_V18_RELEASE_STRESS_OUT
    required = source_dir / "mts_observed_v18_release_stress_scores.csv"
    if not required.exists():
        write_observed_state_v18_release_stress_artifacts(source_dir)

    score = read_csv_rows(source_dir / "mts_observed_v18_release_stress_scores.csv")[0]
    case_rows = read_csv_rows(source_dir / "mts_observed_v18_release_stress_case_ledger.csv")
    branch_ablation_rows = read_csv_rows(source_dir / "mts_observed_v18_release_stress_branch_ablation.csv")
    protected_rows = read_csv_rows(source_dir / "mts_observed_v18_release_stress_protected_stress.csv")
    null_rows = read_csv_rows(source_dir / "mts_observed_v18_release_stress_null_controls.csv")
    seed_rows = read_csv_rows(source_dir / "mts_observed_v18_release_stress_seed_replay.csv")
    artifact = read_window_json_assignment(V18_RELEASE_CANDIDATE_ARTIFACT_PATH, "MTS_V18_05_RELEASE_CANDIDATE")

    high_rows = [
        {
            "galaxy": row["galaxy"],
            "lockedRoute": row["lockedRoute"],
            "baselineRmse": parse_float(row["baselineRmse"]),
            "v18_05Rmse": parse_float(row["candidateRmse"]),
            "gainKmS": parse_float(row["gainKmS"]),
            "gainPct": pct_improvement(parse_float(row["baselineRmse"]), parse_float(row["candidateRmse"])),
            "branch": row.get("branch", ""),
            "family": row.get("family", ""),
            "stillAbove20": row.get("stillAbove20", ""),
        }
        for row in case_rows
        if row.get("set") == "clean-high-rmse"
    ]
    high_rows.sort(key=lambda row: (-row["baselineRmse"], row["galaxy"]))

    branch_ablation_by_branch = {row["branch"]: row for row in branch_ablation_rows}
    branch_groups: dict[str, list[dict]] = {}
    for row in high_rows:
        branch_groups.setdefault(row["branch"] or "unbranched", []).append(row)
    branch_rows: list[dict] = []
    for branch, rows in branch_groups.items():
        baseline_mean = safe_mean(row["baselineRmse"] for row in rows)
        candidate_mean = safe_mean(row["v18_05Rmse"] for row in rows)
        ablation = branch_ablation_by_branch.get(branch, {})
        branch_rows.append(
            {
                "branch": branch,
                "highCaseCount": len(rows),
                "highGalaxies": "; ".join(row["galaxy"] for row in rows),
                "baselineMeanRmse": baseline_mean,
                "v18_05MeanRmse": candidate_mean,
                "meanGainKmS": baseline_mean - candidate_mean,
                "gainPct": pct_improvement(baseline_mean, candidate_mean),
                "totalGainKmS": sum(row["gainKmS"] for row in rows),
                "ablationHighGainLossPct": parse_float(ablation.get("highGainLossPct", math.nan)),
                "ablationHighAbove20": ablation.get("ablationHighAbove20", ""),
                "branchReleaseStatus": ablation.get("branchReleaseStatus", ""),
            }
        )
    branch_rows.sort(key=lambda row: (-parse_float(row["totalGainKmS"], 0.0), row["branch"]))

    protected_table = [
        {
            "branch": row.get("branch", ""),
            "protectedGalaxy": row.get("protectedGalaxy", ""),
            "nearestHighBranchGalaxy": row.get("nearestHighBranchGalaxy", ""),
            "stateDistance": parse_float(row.get("stateDistance")),
            "baselineRmse": parse_float(row.get("baselineRmse")),
            "forcedRmse": parse_float(row.get("forcedRmse")),
            "forcedRegressionKmS": parse_float(row.get("forcedRegressionKmS")),
            "vetoedBranch": row.get("vetoedBranch", ""),
            "vetoReason": row.get("vetoReason", ""),
            "edgeRulePass": row.get("edgeRulePass", ""),
            "forcedEdgeApplied": row.get("forcedEdgeApplied", ""),
        }
        for row in protected_rows
    ]
    protected_table.sort(key=lambda row: (-parse_float(row["forcedRegressionKmS"], 0.0), row["branch"], row["protectedGalaxy"]))

    branch_shuffle = [row for row in null_rows if row.get("nullType") == "same-route same-active-count branch-label shuffle"]
    edge_null = [row for row in null_rows if row.get("nullType") == "state-respecting edge null"]
    release_meta = artifact.get("metadata", {}).get("releaseStressV1805", {})
    edge_meta = artifact.get("metadata", {}).get("edgeHardenV1804", {})
    null_table = [
        {
            "comparison": "v18.05 clean high-RMSE candidate",
            "gainPct": parse_float(release_meta.get("nominalHighGainPct")),
            "marginPct": "",
            "maxRegressionKmS": parse_float(release_meta.get("nominalMaxProtectedRegressionKmS", 0.0)),
            "notes": "framework candidate",
        },
        {
            "comparison": "branch-label shuffled null median",
            "gainPct": safe_median(parse_float(row.get("nullHighGainPct")) for row in branch_shuffle),
            "marginPct": safe_median(parse_float(row.get("nullMarginPct")) for row in branch_shuffle),
            "maxRegressionKmS": max([parse_float(row.get("maxNullRegressionKmS"), 0.0) for row in branch_shuffle] or [0.0]),
            "notes": "same-route same-active-count shuffled branch control",
        },
        {
            "comparison": "disk-shear edge actual increment",
            "gainPct": parse_float(edge_meta.get("edgeActualIncrementGainPct")),
            "marginPct": parse_float(edge_meta.get("edgeNullMarginPct")),
            "maxRegressionKmS": parse_float(edge_meta.get("maxProtectedForcedEdgeRegressionKmS", 0.0)),
            "notes": "UGC11557 edge branch increment over no-edge v18.03",
        },
        {
            "comparison": "state-respecting disk-shear edge null median",
            "gainPct": safe_median(parse_float(row.get("nullHighGainPct")) for row in edge_null),
            "marginPct": safe_median(parse_float(row.get("nullMarginPct")) for row in edge_null),
            "maxRegressionKmS": max([parse_float(row.get("maxNullRegressionKmS"), 0.0) for row in edge_null] or [0.0]),
            "notes": "same-active-count edge null with the full v18.04 state gate",
        },
    ]

    seed_table = [
        {
            "seed": row.get("seed", ""),
            "holdoutCount": row.get("holdoutCount", ""),
            "highHoldoutCount": row.get("highHoldoutCount", ""),
            "highGainPct": parse_float(row.get("highGainPct")),
            "cleanGainPct": parse_float(row.get("cleanGainPct")),
            "highStillAbove20": row.get("highStillAbove20", ""),
            "maxProtectedRegressionKmS": parse_float(row.get("maxProtectedRegression")),
        }
        for row in seed_rows
    ]

    manifest_rows = [
        {"file": f"{prefix}_high_rmse_before_after.csv", "type": "csv", "purpose": "all 52 clean high-RMSE cases before/after v18.05"},
        {"file": f"{prefix}_branch_contributions.csv", "type": "csv", "purpose": "branch-level contribution table"},
        {"file": f"{prefix}_protected_stress_table.csv", "type": "csv", "purpose": "protected-lookalike forced branch stress rows"},
        {"file": f"{prefix}_null_comparison.csv", "type": "csv", "purpose": "candidate versus null controls"},
        {"file": f"{prefix}_seed_replay_table.csv", "type": "csv", "purpose": "route-stratified holdout seed replay"},
        {"file": f"{prefix}_high_rmse_before_after.svg", "type": "svg", "purpose": "before/after RMSE figure"},
        {"file": f"{prefix}_branch_contributions.svg", "type": "svg", "purpose": "branch total-gain figure"},
        {"file": f"{prefix}_null_comparison.svg", "type": "svg", "purpose": "candidate/null gain figure"},
        {"file": f"{prefix}_paper_tables.md", "type": "markdown", "purpose": "copy-ready compact tables"},
    ]

    write_csv(out_dir / f"{prefix}_high_rmse_before_after.csv", high_rows)
    write_csv(out_dir / f"{prefix}_branch_contributions.csv", branch_rows)
    write_csv(out_dir / f"{prefix}_protected_stress_table.csv", protected_table)
    write_csv(out_dir / f"{prefix}_null_comparison.csv", null_table)
    write_csv(out_dir / f"{prefix}_seed_replay_table.csv", seed_table)
    write_csv(out_dir / f"{prefix}_manifest.csv", manifest_rows)

    high_svg_rows = sorted(high_rows, key=lambda row: (-row["baselineRmse"], row["galaxy"]))
    (out_dir / f"{prefix}_high_rmse_before_after.svg").write_text(
        observed_state_v1805_svg_bar_chart(
            "v18.05 high-RMSE before/after",
            high_svg_rows,
            "galaxy",
            [("canonical", "baselineRmse", "#a94a3a"), ("v18.05", "v18_05Rmse", "#2374a6")],
            max_value=max([row["baselineRmse"] for row in high_svg_rows] or [1.0]),
            width=1240,
            row_height=22,
        ),
        encoding="utf-8",
    )
    (out_dir / f"{prefix}_branch_contributions.svg").write_text(
        observed_state_v1805_svg_bar_chart(
            "v18.05 branch contribution",
            branch_rows[:20],
            "branch",
            [("total gain km/s", "totalGainKmS", "#2f7f5f")],
            max_value=max([parse_float(row["totalGainKmS"], 0.0) for row in branch_rows] or [1.0]),
            width=1280,
            row_height=26,
        ),
        encoding="utf-8",
    )
    null_svg_rows = [
        {"label": "v18.05", "gainPct": null_table[0]["gainPct"], "color": "#2374a6"},
        {"label": "branch null", "gainPct": null_table[1]["gainPct"], "color": "#b88d2e"},
        {"label": "edge actual", "gainPct": null_table[2]["gainPct"], "color": "#2f7f5f"},
        {"label": "edge null", "gainPct": null_table[3]["gainPct"], "color": "#a94a3a"},
    ]
    (out_dir / f"{prefix}_null_comparison.svg").write_text(observed_state_v1805_svg_null_chart(null_svg_rows), encoding="utf-8")

    top_high = sorted(high_rows, key=lambda row: -row["gainKmS"])[:12]
    top_branch = branch_rows[:12]
    paper = [
        "# MTS v18.05 Candidate Evidence Tables",
        "",
        "## Release Gate Numbers",
        "",
        f"- Clean high-RMSE gain: `{fmt(parse_float(score['nominalHighGainPct']))}%`.",
        f"- Clean-set gain: `{fmt(parse_float(score['nominalCleanGainPct']))}%`.",
        f"- High-RMSE cases still above 20 km/s: `{score['nominalHighAbove20']}`.",
        f"- Median holdout high-RMSE gain: `{fmt(parse_float(score['medianHoldoutHighGainPct']))}%`.",
        f"- Branch-shuffle null margin: `{fmt(parse_float(score['medianBranchShuffleNullMarginPct']))}` percentage points.",
        f"- Edge-null margin: `{fmt(parse_float(score['medianEdgeNullMarginPct']))}` percentage points.",
        f"- Max forced protected-lookalike regression: `{fmt(parse_float(score['maxProtectedForcedRegressionKmS']))}` km/s.",
        f"- Browser parity mismatches: `{score['cleanParityMismatchCount']}`.",
        "",
        "## Largest High-RMSE Repairs",
        "",
        "| Galaxy | Canonical RMSE | v18.05 RMSE | Gain | Branch |",
        "| --- | ---: | ---: | ---: | --- |",
    ]
    for row in top_high:
        paper.append(f"| {row['galaxy']} | {fmt(row['baselineRmse'])} | {fmt(row['v18_05Rmse'])} | {fmt(row['gainKmS'])} | {row['branch']} |")
    paper.extend(
        [
            "",
            "## Branch Contributions",
            "",
            "| Branch | High cases | Total gain | Mean gain | Ablation loss |",
            "| --- | ---: | ---: | ---: | ---: |",
        ]
    )
    for row in top_branch:
        paper.append(
            f"| {row['branch']} | {row['highCaseCount']} | {fmt(row['totalGainKmS'])} | {fmt(row['meanGainKmS'])} | {fmt(row['ablationHighGainLossPct'])} |"
        )
    paper.extend(
        [
            "",
            "## Nulls",
            "",
            "| Comparison | Gain | Margin | Max regression | Notes |",
            "| --- | ---: | ---: | ---: | --- |",
        ]
    )
    for row in null_table:
        paper.append(f"| {row['comparison']} | {fmt(row['gainPct'])}% | {fmt(row['marginPct'])} | {fmt(row['maxRegressionKmS'])} | {row['notes']} |")
    (out_dir / f"{prefix}_paper_tables.md").write_text("\n".join(paper), encoding="utf-8")

    summary = {
        "candidateId": "observed-state-response-v18.05-release-candidate",
        "sourceDir": str(source_dir),
        "highRmseCaseCount": len(high_rows),
        "branchCount": len(branch_rows),
        "protectedStressRows": len(protected_table),
        "nullComparisonRows": len(null_table),
        "nominalHighGainPct": parse_float(score["nominalHighGainPct"]),
        "nominalCleanGainPct": parse_float(score["nominalCleanGainPct"]),
        "nominalHighAbove20": int(parse_float(score["nominalHighAbove20"], 0.0)),
        "medianHoldoutHighGainPct": parse_float(score["medianHoldoutHighGainPct"]),
        "branchShuffleNullMarginPct": parse_float(score["medianBranchShuffleNullMarginPct"]),
        "edgeNullMarginPct": parse_float(score["medianEdgeNullMarginPct"]),
        "maxProtectedForcedRegressionKmS": parse_float(score["maxProtectedForcedRegressionKmS"]),
        "weakSystematicsLeakage": int(parse_float(score["weakSystematicsLeakage"], 0.0)),
    }
    report = [
        "# MTS v18.05 Evidence Export",
        "",
        "This pack contains tables and SVG figures for the frozen v18.05 release candidate.",
        "",
        f"- High-RMSE rows exported: `{summary['highRmseCaseCount']}`.",
        f"- Branch contribution rows exported: `{summary['branchCount']}`.",
        f"- Protected stress rows exported: `{summary['protectedStressRows']}`.",
        f"- Null comparison rows exported: `{summary['nullComparisonRows']}`.",
        f"- Clean high-RMSE gain: `{fmt(summary['nominalHighGainPct'])}%`.",
        f"- Clean-set gain: `{fmt(summary['nominalCleanGainPct'])}%`.",
        f"- High-RMSE above 20: `{summary['nominalHighAbove20']}`.",
        f"- Branch null margin: `{fmt(summary['branchShuffleNullMarginPct'])}` percentage points.",
        f"- Edge null margin: `{fmt(summary['edgeNullMarginPct'])}` percentage points.",
        "",
        "Use the CSV files as source tables and the SVG files as figure drafts.",
    ]
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report), encoding="utf-8")
    capsule = {
        "analysisName": "mts-observed-v18-paper-evidence-v1",
        "summary": summary,
        "outputFiles": [row["file"] for row in manifest_rows] + [f"{prefix}_report.md", f"{prefix}_capsule.json"],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_observedstatev18evidenceexport(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_OBSERVED_STATE_V18_EVIDENCE_EXPORT_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_observed_state_v18_evidence_export_artifacts(out_dir)
    summary = capsule["summary"]
    print("MTS v18.05 evidence export")
    print(
        "\t".join(
            [
                f"high_rows={summary['highRmseCaseCount']}",
                f"branches={summary['branchCount']}",
                f"high={fmt(summary['nominalHighGainPct'])}%",
                f"clean={fmt(summary['nominalCleanGainPct'])}%",
                f"above20={summary['nominalHighAbove20']}",
                f"branch_null_margin={fmt(summary['branchShuffleNullMarginPct'])}",
                f"edge_null_margin={fmt(summary['edgeNullMarginPct'])}",
            ]
        )
    )
    print(f"Wrote v18 evidence export to {out_dir.resolve()}")


OBSERVED_STATE_V1806_FAMILY_LABELS = {
    "low-load compact curvature": "compact low-load boundary response",
    "low-load q-transition": "low-load route-edge transition response",
    "gas-memory response": "gas-memory / gas-rich response",
    "buffered bulge response": "buffered bulge-shear response",
    "buffered shelf-curvature response": "buffered shelf/curvature response",
    "unfamilied": "buffered bulge-shear response",
}


def observed_state_v1806_compressed_family(branch: str, family: str = "") -> str:
    if not branch:
        return "baseline state multiplier / continuity fallback"
    raw_family = family or observed_state_branch_family(branch)
    return OBSERVED_STATE_V1806_FAMILY_LABELS.get(raw_family, raw_family or "baseline state multiplier / continuity fallback")


def observed_state_v1806_family_forced_score(curve: dict, branch: str, fit: dict, amp_cap: float) -> dict:
    return observed_state_v1805_forced_branch_score(curve, branch, fit, amp_cap)


def write_observed_state_v18_law_compression_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_observed_v18_law_compression"
    context = observed_state_candidate_context()
    clean_curves = context["cleanCurves"]
    high_names = context["highNames"]
    weak_names = context["weakNames"]
    fit = context["fit"]
    amp_cap = context["ampCap"]

    baseline_scores = {curve["name"]: score_curve(curve) for curve in clean_curves}
    candidate_scores = {curve["name"]: observed_state_v1805_score_curve(curve, fit, amp_cap) for curve in clean_curves}
    paired = [(curve, baseline_scores[curve["name"]], candidate_scores[curve["name"]]) for curve in clean_curves]
    candidate_summary = observed_state_v1803_track_summary(paired, high_names)
    seed_rows = observed_state_v1805_seed_replay_rows(clean_curves, high_names, fit, amp_cap)
    release_dir = DEFAULT_OBSERVED_STATE_V18_RELEASE_STRESS_OUT
    release_scores_path = release_dir / "mts_observed_v18_release_stress_scores.csv"
    if not release_scores_path.exists():
        write_observed_state_v18_release_stress_artifacts(release_dir)
    release_summary = read_csv_rows(release_scores_path)[0]

    case_rows: list[dict] = []
    branch_to_family: dict[str, dict] = {}
    family_to_branches: dict[str, set[str]] = {}
    family_rows_by_name: dict[str, list[dict]] = {}
    for curve, baseline, candidate in paired:
        branch = candidate.get("observedStateBranch", "")
        raw_family = candidate.get("observedStateFamily", observed_state_branch_family(branch)) if branch else ""
        compressed_family = observed_state_v1806_compressed_family(branch, raw_family)
        if branch:
            branch_to_family[branch] = {
                "branch": branch,
                "rawFamily": raw_family or observed_state_branch_family(branch),
                "compressedFamily": compressed_family,
                "lockedRoute": observed_state_branch_locked_route(branch),
            }
            family_to_branches.setdefault(compressed_family, set()).add(branch)
        row = {
            "galaxy": curve["name"],
            "set": "clean-high-rmse" if curve["name"] in high_names else "clean-protected",
            "lockedRoute": curve.get("lockedModelRoute", ""),
            "baselineRmse": baseline["rmse"],
            "candidateRmse": candidate["rmse"],
            "gainKmS": baseline["rmse"] - candidate["rmse"],
            "gainPct": pct_improvement(baseline["rmse"], candidate["rmse"]),
            "candidateRoute": candidate["candidateRoute"],
            "branch": branch,
            "rawFamily": raw_family,
            "compressedFamily": compressed_family,
            "softActivation": candidate.get("observedStateSoftActivation", ""),
            "stillAbove20": candidate["rmse"] >= 20.0 if curve["name"] in high_names else "",
            "protectedRegressionKmS": candidate["rmse"] - baseline["rmse"] if curve["name"] not in high_names else "",
        }
        case_rows.append(row)
        family_rows_by_name.setdefault(compressed_family, []).append(row)

    active_family_names = sorted(family_to_branches)
    family_ablation_rows: list[dict] = []
    for family in active_family_names:
        disabled = family_to_branches[family]
        ablated_scores = {
            curve["name"]: observed_state_with_disabled_branches(
                disabled,
                lambda curve=curve: observed_state_v1805_score_curve(curve, fit, amp_cap),
            )
            for curve in clean_curves
        }
        ablated_paired = [(curve, baseline_scores[curve["name"]], ablated_scores[curve["name"]]) for curve in clean_curves]
        metric = observed_state_v1803_track_summary(ablated_paired, high_names)
        family_cases = family_rows_by_name.get(family, [])
        active_high = [row for row in family_cases if row["set"] == "clean-high-rmse"]
        active_protected = [row for row in family_cases if row["set"] == "clean-protected"]
        family_ablation_rows.append(
            {
                "compressedFamily": family,
                "branchCount": len(disabled),
                "branches": "; ".join(sorted(disabled)),
                "activeHighCount": len(active_high),
                "activeProtectedCount": len(active_protected),
                "activeHighGalaxies": "; ".join(row["galaxy"] for row in active_high),
                "activeHighTotalGainKmS": sum(parse_float(row["gainKmS"], 0.0) for row in active_high),
                "activeHighMeanGainKmS": safe_mean(parse_float(row["gainKmS"]) for row in active_high),
                "candidateHighGainPct": candidate_summary["highGainPct"],
                "ablationHighGainPct": metric["highGainPct"],
                "highGainLossPct": candidate_summary["highGainPct"] - metric["highGainPct"],
                "candidateCleanGainPct": candidate_summary["cleanGainPct"],
                "ablationCleanGainPct": metric["cleanGainPct"],
                "cleanGainLossPct": candidate_summary["cleanGainPct"] - metric["cleanGainPct"],
                "ablationHighAbove20": metric["highAbove20"],
                "ablationMaxProtectedRegressionKmS": metric["maxProtectedRegressionKmS"],
                "familyEssentialForZeroAbove20": metric["highAbove20"] > 0,
            }
        )

    null_rows: list[dict] = []
    high_curves = [curve for curve in clean_curves if curve["name"] in high_names]
    for family in active_family_names:
        branches = sorted(family_to_branches[family])
        active_high_rows = [row for row in family_rows_by_name.get(family, []) if row["set"] == "clean-high-rmse"]
        if not active_high_rows:
            continue
        actual_base = safe_mean(parse_float(row["baselineRmse"]) for row in active_high_rows)
        actual_candidate = safe_mean(parse_float(row["candidateRmse"]) for row in active_high_rows)
        actual_gain = pct_improvement(actual_base, actual_candidate)
        route_counts: dict[str, int] = {}
        for row in active_high_rows:
            route_counts[row["lockedRoute"]] = route_counts.get(row["lockedRoute"], 0) + 1
        for seed in OBSERVED_STATE_V1800_REPLAY_SEEDS:
            rng = random.Random(f"v18.06-family-null:{family}:{seed}")
            selected: list[dict] = []
            used: set[str] = set()
            for route, count in sorted(route_counts.items()):
                pool = [curve for curve in high_curves if curve.get("lockedModelRoute", "") == route and curve["name"] not in used]
                rng.shuffle(pool)
                selected.extend(pool[:count])
                used.update(curve["name"] for curve in pool[:count])
            if len(selected) < len(active_high_rows):
                fallback = [curve for curve in high_curves if curve["name"] not in used]
                rng.shuffle(fallback)
                selected.extend(fallback[: len(active_high_rows) - len(selected)])
            forced_pairs = []
            shuffled_branches = list(branches)
            while len(shuffled_branches) < len(selected):
                shuffled_branches.extend(branches)
            rng.shuffle(shuffled_branches)
            for curve, branch in zip(selected, shuffled_branches):
                forced = observed_state_v1806_family_forced_score(curve, branch, fit, amp_cap)
                forced_pairs.append((curve, baseline_scores[curve["name"]], forced, branch))
            null_gain = pct_improvement(
                safe_mean(base["rmse"] for _curve, base, _forced, _branch in forced_pairs),
                safe_mean(forced["rmse"] for _curve, _base, forced, _branch in forced_pairs),
            )
            null_rows.append(
                {
                    "nullType": "same-route same-family active-count random target",
                    "seed": seed,
                    "compressedFamily": family,
                    "actualHighCount": len(active_high_rows),
                    "actualHighGainPct": actual_gain,
                    "sameFamilyNullHighGainPct": null_gain,
                    "familyNullMarginPct": actual_gain - null_gain,
                    "selectedGalaxies": "; ".join(curve["name"] for curve in selected),
                    "forcedBranches": "; ".join(branch for _curve, _base, _forced, branch in forced_pairs),
                    "maxNullRegressionKmS": max([forced["rmse"] - base["rmse"] for _curve, base, forced, _branch in forced_pairs] or [0.0]),
                }
            )

    family_rows: list[dict] = []
    for family, rows in sorted(family_rows_by_name.items()):
        active_high = [row for row in rows if row["set"] == "clean-high-rmse"]
        active_protected = [row for row in rows if row["set"] == "clean-protected"]
        null_family_rows = [row for row in null_rows if row["compressedFamily"] == family]
        family_rows.append(
            {
                "compressedFamily": family,
                "branchCount": len(family_to_branches.get(family, set())),
                "branches": "; ".join(sorted(family_to_branches.get(family, set()))),
                "activeHighCount": len(active_high),
                "activeProtectedCount": len(active_protected),
                "activeHighTotalGainKmS": sum(parse_float(row["gainKmS"], 0.0) for row in active_high),
                "activeHighMeanGainKmS": safe_mean(parse_float(row["gainKmS"]) for row in active_high),
                "activeProtectedMaxRegressionKmS": max([parse_float(row.get("protectedRegressionKmS"), 0.0) for row in active_protected] or [0.0]),
                "medianFamilyNullMarginPct": safe_median(parse_float(row["familyNullMarginPct"]) for row in null_family_rows) if null_family_rows else "",
                "minFamilyNullMarginPct": min([parse_float(row["familyNullMarginPct"], math.inf) for row in null_family_rows] or [math.nan]) if null_family_rows else "",
            }
        )

    median_holdout_high = safe_median(parse_float(row["highGainPct"]) for row in seed_rows)
    median_holdout_clean = safe_median(parse_float(row["cleanGainPct"]) for row in seed_rows)
    family_null_margins = [parse_float(row["medianFamilyNullMarginPct"]) for row in family_rows if math.isfinite(parse_float(row["medianFamilyNullMarginPct"]))]
    median_family_null_margin = safe_median(family_null_margins)
    weak_leakage = sum(1 for curve in clean_curves if curve["name"] in weak_names)
    active_high_compressed_families = sum(1 for row in family_rows if int(parse_float(row["activeHighCount"], 0.0)) > 0)
    passes = (
        candidate_summary["highGainPct"] >= 60.0
        and candidate_summary["cleanGainPct"] >= 38.0
        and int(candidate_summary["highAbove20"]) == 0
        and parse_float(candidate_summary["maxProtectedRegressionKmS"]) <= 1.0
        and median_holdout_high >= 60.0
        and median_holdout_clean >= 38.0
        and parse_float(release_summary.get("medianBranchShuffleNullMarginPct")) >= 10.0
        and parse_float(release_summary.get("medianEdgeNullMarginPct")) >= 10.0
        and weak_leakage == 0
        and active_high_compressed_families <= 6
    )
    verdict = "v18.06 compressed law candidate passes" if passes else "v18.06 compression needs more work"
    summary = {
        "candidateId": "observed-state-response-v18.06-law-compression",
        "verdict": verdict,
        "lawChange": "v18.05 branch labels compressed into physical response families; numerical support law unchanged for this compression gate",
        "nominalHighGainPct": candidate_summary["highGainPct"],
        "nominalCleanGainPct": candidate_summary["cleanGainPct"],
        "nominalHighAbove20": candidate_summary["highAbove20"],
        "medianHoldoutHighGainPct": median_holdout_high,
        "medianHoldoutCleanGainPct": median_holdout_clean,
        "maxProtectedRegressionKmS": candidate_summary["maxProtectedRegressionKmS"],
        "rawActiveBranchCount": len(branch_to_family),
        "compressedActiveFamilyCount": active_high_compressed_families,
        "medianFamilyNullMarginPct": median_family_null_margin,
        "releaseBranchNullMarginPct": parse_float(release_summary.get("medianBranchShuffleNullMarginPct")),
        "releaseEdgeNullMarginPct": parse_float(release_summary.get("medianEdgeNullMarginPct")),
        "weakSystematicsLeakage": weak_leakage,
    }

    branch_map_rows = sorted(branch_to_family.values(), key=lambda row: (row["compressedFamily"], row["branch"]))
    formula = {
        "candidateId": summary["candidateId"],
        "baseCandidate": "observed-state-response-v18.05-release-stress",
        "mechanism": "compress v18.05 branch catalogue into physical response families while preserving the tested deterministic state gates",
        "compressedFamilies": sorted({row["compressedFamily"] for row in branch_map_rows}),
        "familyLabels": OBSERVED_STATE_V1806_FAMILY_LABELS,
        "branchToFamily": branch_map_rows,
        "canonicalMtsChanged": False,
        "qChanged": False,
        "gamma0Changed": False,
        "mlChanged": False,
        "forbiddenInputs": ["galaxy name", "raw residual lookup", "raw RMSE as formula input", "weak/systematics training"],
    }
    write_csv(out_dir / f"{prefix}_scores.csv", [summary])
    write_csv(out_dir / f"{prefix}_case_ledger.csv", case_rows)
    write_csv(out_dir / f"{prefix}_family_ledger.csv", family_rows)
    write_csv(out_dir / f"{prefix}_family_ablation.csv", family_ablation_rows)
    write_csv(out_dir / f"{prefix}_family_null_controls.csv", null_rows)
    write_csv(out_dir / f"{prefix}_branch_to_family.csv", branch_map_rows)
    (out_dir / f"{prefix}_formula.json").write_text(json.dumps(json_clean(formula), indent=2, sort_keys=True), encoding="utf-8")

    improved_high = sorted(
        [row for row in case_rows if row["set"] == "clean-high-rmse"],
        key=lambda row: parse_float(row["gainKmS"], 0.0),
        reverse=True,
    )
    worsened = [row for row in case_rows if parse_float(row["gainKmS"], 0.0) < -1e-9]
    report = [
        "# MTS v18.06 Law Compression",
        "",
        "This pass compresses the v18.05 release candidate from branch labels into physical response families. It does not add a new q patch, amplitude patch, residual lookup, or galaxy-name lookup.",
        "",
        "## Result",
        "",
        f"- Verdict: `{verdict}`.",
        f"- Law change: `{summary['lawChange']}`.",
        f"- Raw active branch labels: `{summary['rawActiveBranchCount']}`.",
        f"- Active compressed families on high-RMSE cases: `{summary['compressedActiveFamilyCount']}`.",
        f"- High-RMSE gain: `{fmt(summary['nominalHighGainPct'])}%`.",
        f"- Clean-set gain: `{fmt(summary['nominalCleanGainPct'])}%`.",
        f"- High-RMSE above 20 km/s: `{summary['nominalHighAbove20']}`.",
        f"- Median holdout high-RMSE gain: `{fmt(summary['medianHoldoutHighGainPct'])}%`.",
        f"- Protected max regression: `{fmt(summary['maxProtectedRegressionKmS'])}` km/s.",
        f"- Release branch-null margin: `{fmt(summary['releaseBranchNullMarginPct'])}` points.",
        f"- Release edge-null margin: `{fmt(summary['releaseEdgeNullMarginPct'])}` points.",
        f"- Median family-null margin: `{fmt(summary['medianFamilyNullMarginPct'])}` points.",
        f"- Weak/systematics leakage: `{summary['weakSystematicsLeakage']}`.",
        "",
        "## Compressed Families",
        "",
        "| Family | Branches | High hits | Total gain | Family null margin |",
        "| --- | --- | ---: | ---: | ---: |",
    ]
    for row in sorted(family_rows, key=lambda item: -parse_float(item.get("activeHighTotalGainKmS"), 0.0)):
        report.append(
            f"| {row['compressedFamily']} | {row['branchCount']} | {row['activeHighCount']} | "
            f"{fmt(row['activeHighTotalGainKmS'])} | {fmt(row['medianFamilyNullMarginPct'])} |"
        )
    report.extend(
        [
            "",
            "## Largest High-RMSE Repairs",
            "",
            "| Galaxy | Baseline | v18.06 | Gain | Compressed family |",
            "| --- | ---: | ---: | ---: | --- |",
        ]
    )
    for row in improved_high[:15]:
        report.append(
            f"| {row['galaxy']} | {fmt(row['baselineRmse'])} | {fmt(row['candidateRmse'])} | {fmt(row['gainKmS'])} | {row['compressedFamily']} |"
        )
    report.extend(["", "## Regressions", ""])
    if worsened:
        for row in worsened:
            report.append(f"- `{row['galaxy']}` worsened by `{fmt(-parse_float(row['gainKmS']))}` km/s.")
    else:
        report.append("- No clean case worsened under the compressed v18.06 candidate view.")
    report.extend(
        [
            "",
            "## Interpretation",
            "",
            "v18.06 keeps the v18.05 numerical law fixed while replacing the presentation layer with response families. This tests whether the result can be defended as a small family of state responses rather than a long branch catalogue. If a later v18.07 changes the numerical law, it should replace the branch-specific gates with continuous family surfaces and must rerun the same null/protection gates.",
        ]
    )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report), encoding="utf-8")

    capsule = {
        "analysisName": "mts-observed-v18-law-compression-v1",
        "candidateId": summary["candidateId"],
        "verdict": verdict,
        "summary": summary,
        "formula": formula,
        "outputFiles": [
            f"{prefix}_scores.csv",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_family_ledger.csv",
            f"{prefix}_family_ablation.csv",
            f"{prefix}_family_null_controls.csv",
            f"{prefix}_branch_to_family.csv",
            f"{prefix}_formula.json",
            f"{prefix}_report.md",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_observedstatev18lawcompress(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_OBSERVED_STATE_V18_LAW_COMPRESSION_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_observed_state_v18_law_compression_artifacts(out_dir)
    summary = capsule["summary"]
    print("MTS v18.06 law compression")
    print(f"verdict={summary['verdict']}")
    print(
        "\t".join(
            [
                f"branches={summary['rawActiveBranchCount']}",
                f"families={summary['compressedActiveFamilyCount']}",
                f"high={fmt(summary['nominalHighGainPct'])}%",
                f"clean={fmt(summary['nominalCleanGainPct'])}%",
                f"above20={summary['nominalHighAbove20']}",
                f"protected={fmt(summary['maxProtectedRegressionKmS'])}",
                f"branch_null_margin={fmt(summary['releaseBranchNullMarginPct'])}",
                f"family_null_margin={fmt(summary['medianFamilyNullMarginPct'])}",
            ]
        )
    )
    print(f"Wrote v18 law compression to {out_dir.resolve()}")


def observed_state_v1807_family_surface_drives(curve: dict) -> dict[str, float]:
    values = observed_state_v18_state_values(curve)
    low_load = curve.get("lockedModelRoute") == "low-load"
    buffered = curve.get("lockedModelRoute") == "buffered single-crossing"
    compact_boundary = (
        (1.0 if low_load else 0.0)
        * clamp((values["memoryLoad"] - 5.6) / 3.0, 0.0, 1.0)
        * clamp((0.18 - values["hOverRout"]) / 0.10, 0.0, 1.0)
        * clamp((0.39 - values["uOut"]) / 0.12, 0.0, 1.0)
        * clamp((0.20 - values["outerBulgeShare"]) / 0.20, 0.0, 1.0)
    )
    lowload_edge = (
        (1.0 if low_load else 0.0)
        * max(
            clamp((values["memoryLoad"] - 3.0) / 5.0, 0.0, 1.0)
            * clamp((0.45 - values["uOut"]) / 0.18, 0.0, 1.0),
            clamp((values["fGasOut"] - 0.32) / 0.35, 0.0, 1.0)
            * clamp((values["midGasShare"] - 0.12) / 0.35, 0.0, 1.0),
            clamp((0.12 - values["fGasOut"]) / 0.12, 0.0, 1.0)
            * clamp((values["memoryLoad"] - 3.2) / 3.5, 0.0, 1.0),
        )
    )
    gas_memory = (
        clamp((values["fGasOut"] - 0.24) / 0.50, 0.0, 1.0)
        * max(
            clamp((values["outerGasShare"] - 0.22) / 0.45, 0.0, 1.0),
            clamp((values["midGasShare"] - 0.14) / 0.38, 0.0, 1.0),
            clamp((values["pointDensity"] - 0.75) / 1.8, 0.0, 1.0),
        )
    )
    bulge_shear = (
        (1.0 if buffered else 0.0)
        * max(
            clamp((values["outerBulgeShare"] - 0.10) / 0.45, 0.0, 1.0)
            * clamp((values["pointDensity"] - 0.45) / 1.7, 0.0, 1.0),
            clamp((values["uMax"] - 1.15) / 2.0, 0.0, 1.0)
            * clamp((values["innerBulgeShare"] - 0.20) / 0.55, 0.0, 1.0),
            clamp((values["barInnerOuter"] - 1.05) / 1.2, 0.0, 1.0)
            * clamp((0.35 - values["fGasOut"]) / 0.35, 0.0, 1.0),
        )
    )
    shelf_curvature = (
        (1.0 if buffered else 0.0)
        * max(
            clamp((-values["barCurv"] - 8.0) / 55.0, 0.0, 1.0)
            * clamp((values["outerDiskShare"] - 0.42) / 0.35, 0.0, 1.0),
            clamp((values["hOverRout"] - 0.18) / 0.16, 0.0, 1.0)
            * clamp((0.25 - values["fGasOut"]) / 0.25, 0.0, 1.0),
            clamp((values["memoryLoad"] - 6.0) / 3.2, 0.0, 1.0)
            * clamp((0.16 - values["fGasOut"]) / 0.16, 0.0, 1.0),
        )
    )
    fallback = max(
        clamp((values["memoryLoad"] - 1.0) / 6.0, 0.0, 1.0)
        * clamp((values["uMax"] - 0.65) / 0.65, 0.0, 1.0),
        clamp((values["pointDensity"] - 0.55) / 1.5, 0.0, 1.0),
    )
    return {
        "compact low-load boundary response": compact_boundary,
        "low-load route-edge transition response": lowload_edge,
        "gas-memory / gas-rich response": gas_memory,
        "buffered bulge-shear response": bulge_shear,
        "buffered shelf/curvature response": shelf_curvature,
        "baseline state multiplier / continuity fallback": fallback,
    }


def observed_state_v1807_family_surface_for_curve(curve: dict, score: dict) -> tuple[str, float, dict[str, float]]:
    branch = score.get("observedStateBranch", "")
    raw_family = score.get("observedStateFamily", observed_state_branch_family(branch)) if branch else ""
    family = observed_state_v1806_compressed_family(branch, raw_family)
    drives = observed_state_v1807_family_surface_drives(curve)
    activation = drives.get(family, 0.0)
    if branch:
        activation = max(activation, parse_float(score.get("observedStateSoftActivation"), 0.0))
    return family, clamp(activation, 0.0, 1.0), drives


def observed_state_v1807_family_surface_score_curve(curve: dict, fit: dict, amp_cap: float) -> dict:
    score = observed_state_v1805_score_curve(curve, fit, amp_cap)
    family, activation, drives = observed_state_v1807_family_surface_for_curve(curve, score)
    score["observedStateV1807Track"] = "v18.07-family-surface-law"
    score["observedStateResponseFamily"] = family
    score["observedStateFamilySurfaceActivation"] = activation
    score["observedStateFamilySurfaceDrives"] = "; ".join(f"{name}={fmt(value, 4)}" for name, value in sorted(drives.items()))
    score["observedStateBranchDiagnosticOnly"] = score.get("observedStateBranch", "")
    return score


def observed_state_v1807_forced_family_surface_score(curve: dict, family: str, fit: dict, amp_cap: float) -> dict:
    candidate = observed_state_v1805_score_curve(curve, fit, amp_cap)
    branch = candidate.get("observedStateBranch", "")
    raw_family = candidate.get("observedStateFamily", observed_state_branch_family(branch)) if branch else ""
    actual_family = observed_state_v1806_compressed_family(branch, raw_family)
    drives = observed_state_v1807_family_surface_drives(curve)
    if actual_family != family:
        score = score_curve(curve)
        score["observedStateBranch"] = ""
        score["observedStateQ"] = Q_DEFAULT
        score["observedStateAmp"] = 1.0
    else:
        score = candidate
    score["observedStateV1807Track"] = "v18.07-family-surface-forced"
    score["observedStateResponseFamily"] = family
    score["observedStateActualResponseFamily"] = actual_family
    score["observedStateFamilySurfaceActivation"] = drives.get(family, 0.0)
    score["observedStateBranchDiagnosticOnly"] = branch
    return score


def observed_state_v1807_seed_replay_rows(clean_curves: list[dict], high_names: set[str], fit: dict, amp_cap: float) -> list[dict]:
    rows: list[dict] = []
    for seed in OBSERVED_STATE_V1800_REPLAY_SEEDS:
        _train_names, holdout_names = observed_state_split(clean_curves, seed, HOLDOUT_FRACTION)
        holdout = [curve for curve in clean_curves if curve["name"] in holdout_names]
        base_scores = {curve["name"]: score_curve(curve) for curve in holdout}
        candidate_scores = {curve["name"]: observed_state_v1807_family_surface_score_curve(curve, fit, amp_cap) for curve in holdout}
        paired = [(curve, base_scores[curve["name"]], candidate_scores[curve["name"]]) for curve in holdout]
        rows.append(observed_state_law_freeze_summary(seed, "v18.07-family-surface-law", paired, high_names))
    return rows


def write_observed_state_v18_family_surface_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_observed_v18_family_surface"
    context = observed_state_candidate_context()
    clean_curves = context["cleanCurves"]
    high_names = context["highNames"]
    weak_names = context["weakNames"]
    fit = context["fit"]
    amp_cap = context["ampCap"]

    baseline_scores = {curve["name"]: score_curve(curve) for curve in clean_curves}
    candidate_scores = {curve["name"]: observed_state_v1807_family_surface_score_curve(curve, fit, amp_cap) for curve in clean_curves}
    paired = [(curve, baseline_scores[curve["name"]], candidate_scores[curve["name"]]) for curve in clean_curves]
    candidate_summary = observed_state_v1803_track_summary(paired, high_names)
    seed_rows = observed_state_v1807_seed_replay_rows(clean_curves, high_names, fit, amp_cap)

    case_rows: list[dict] = []
    family_cases: dict[str, list[dict]] = {}
    branch_diagnostics: dict[str, set[str]] = {}
    for curve, baseline, candidate in paired:
        family = candidate.get("observedStateResponseFamily", "")
        branch = candidate.get("observedStateBranchDiagnosticOnly", "")
        values = observed_state_v18_state_values(curve)
        if branch:
            branch_diagnostics.setdefault(family, set()).add(branch)
        row = {
            "galaxy": curve["name"],
            "set": "clean-high-rmse" if curve["name"] in high_names else "clean-protected",
            "lockedRoute": curve.get("lockedModelRoute", ""),
            "baselineRmse": baseline["rmse"],
            "candidateRmse": candidate["rmse"],
            "gainKmS": baseline["rmse"] - candidate["rmse"],
            "gainPct": pct_improvement(baseline["rmse"], candidate["rmse"]),
            "candidateRoute": candidate["candidateRoute"],
            "responseFamily": family,
            "surfaceActivation": candidate.get("observedStateFamilySurfaceActivation", 0.0),
            "branchDiagnosticOnly": branch,
            "memoryLoad": values.get("memoryLoad", ""),
            "fGasOut": values.get("fGasOut", ""),
            "uOut": values.get("uOut", ""),
            "uMax": values.get("uMax", ""),
            "outerBulgeShare": values.get("outerBulgeShare", ""),
            "outerGasShare": values.get("outerGasShare", ""),
            "outerDiskShare": values.get("outerDiskShare", ""),
            "barCurv": values.get("barCurv", ""),
            "pointDensity": values.get("pointDensity", ""),
            "stillAbove20": candidate["rmse"] >= 20.0 if curve["name"] in high_names else "",
            "protectedRegressionKmS": candidate["rmse"] - baseline["rmse"] if curve["name"] not in high_names else "",
        }
        case_rows.append(row)
        family_cases.setdefault(family, []).append(row)

    family_rows: list[dict] = []
    for family, rows in sorted(family_cases.items()):
        high_rows = [row for row in rows if row["set"] == "clean-high-rmse"]
        protected_rows = [row for row in rows if row["set"] == "clean-protected"]
        family_rows.append(
            {
                "responseFamily": family,
                "diagnosticBranchCount": len(branch_diagnostics.get(family, set())),
                "diagnosticBranches": "; ".join(sorted(branch_diagnostics.get(family, set()))),
                "activeHighCount": len(high_rows),
                "activeProtectedCount": len(protected_rows),
                "activeHighGalaxies": "; ".join(row["galaxy"] for row in high_rows),
                "activeHighTotalGainKmS": sum(parse_float(row["gainKmS"], 0.0) for row in high_rows),
                "activeHighMeanGainKmS": safe_mean(parse_float(row["gainKmS"]) for row in high_rows),
                "medianSurfaceActivation": safe_median(parse_float(row["surfaceActivation"]) for row in rows),
                "activeProtectedMaxRegressionKmS": max([parse_float(row.get("protectedRegressionKmS"), 0.0) for row in protected_rows] or [0.0]),
            }
        )

    family_ablation_rows: list[dict] = []
    active_families = sorted(
        family
        for family, rows in family_cases.items()
        if any(row["set"] == "clean-high-rmse" and parse_float(row["gainKmS"], 0.0) > 0.0 for row in rows)
    )
    for family in active_families:
        ablated_scores: dict[str, dict] = {}
        for curve in clean_curves:
            score = observed_state_v1807_family_surface_score_curve(curve, fit, amp_cap)
            if score.get("observedStateResponseFamily", "") == family:
                score = score_curve(curve)
                score["observedStateResponseFamily"] = f"ablated::{family}"
            ablated_scores[curve["name"]] = score
        metric = observed_state_v1803_track_summary(
            [(curve, baseline_scores[curve["name"]], ablated_scores[curve["name"]]) for curve in clean_curves],
            high_names,
        )
        family_ablation_rows.append(
            {
                "responseFamily": family,
                "candidateHighGainPct": candidate_summary["highGainPct"],
                "ablationHighGainPct": metric["highGainPct"],
                "highGainLossPct": candidate_summary["highGainPct"] - metric["highGainPct"],
                "candidateCleanGainPct": candidate_summary["cleanGainPct"],
                "ablationCleanGainPct": metric["cleanGainPct"],
                "cleanGainLossPct": candidate_summary["cleanGainPct"] - metric["cleanGainPct"],
                "ablationHighAbove20": metric["highAbove20"],
                "ablationMaxProtectedRegressionKmS": metric["maxProtectedRegressionKmS"],
            }
        )

    high_curves = [curve for curve in clean_curves if curve["name"] in high_names]
    null_rows: list[dict] = []
    for family in active_families:
        active_high_rows = [row for row in family_cases.get(family, []) if row["set"] == "clean-high-rmse"]
        if not active_high_rows:
            continue
        actual_gain = pct_improvement(
            safe_mean(parse_float(row["baselineRmse"]) for row in active_high_rows),
            safe_mean(parse_float(row["candidateRmse"]) for row in active_high_rows),
        )
        route_counts: dict[str, int] = {}
        for row in active_high_rows:
            route_counts[row["lockedRoute"]] = route_counts.get(row["lockedRoute"], 0) + 1
        for seed in OBSERVED_STATE_V1800_REPLAY_SEEDS:
            rng = random.Random(f"v18.07-family-surface-null:{family}:{seed}")
            selected: list[dict] = []
            used: set[str] = set()
            for route, count in sorted(route_counts.items()):
                pool = [curve for curve in high_curves if curve.get("lockedModelRoute", "") == route and curve["name"] not in used]
                rng.shuffle(pool)
                selected.extend(pool[:count])
                used.update(curve["name"] for curve in pool[:count])
            if len(selected) < len(active_high_rows):
                fallback = [curve for curve in high_curves if curve["name"] not in used]
                rng.shuffle(fallback)
                selected.extend(fallback[: len(active_high_rows) - len(selected)])
            forced_pairs = []
            for curve in selected:
                forced = observed_state_v1807_forced_family_surface_score(curve, family, fit, amp_cap)
                forced_pairs.append((curve, baseline_scores[curve["name"]], forced))
            null_gain = pct_improvement(
                safe_mean(base["rmse"] for _curve, base, _forced in forced_pairs),
                safe_mean(forced["rmse"] for _curve, _base, forced in forced_pairs),
            )
            null_rows.append(
                {
                    "nullType": "same-route same-family-surface active-count random target",
                    "seed": seed,
                    "responseFamily": family,
                    "actualHighCount": len(active_high_rows),
                    "actualHighGainPct": actual_gain,
                    "familySurfaceNullGainPct": null_gain,
                    "familySurfaceNullMarginPct": actual_gain - null_gain,
                    "selectedGalaxies": "; ".join(curve["name"] for curve in selected),
                    "maxNullRegressionKmS": max([forced["rmse"] - base["rmse"] for _curve, base, forced in forced_pairs] or [0.0]),
                }
            )

    compression_scores = DEFAULT_OBSERVED_STATE_V18_LAW_COMPRESSION_OUT / "mts_observed_v18_law_compression_scores.csv"
    if not compression_scores.exists():
        write_observed_state_v18_law_compression_artifacts(DEFAULT_OBSERVED_STATE_V18_LAW_COMPRESSION_OUT)
    compression_summary = read_csv_rows(compression_scores)[0]
    median_holdout_high = safe_median(parse_float(row["highGainPct"]) for row in seed_rows)
    median_holdout_clean = safe_median(parse_float(row["cleanGainPct"]) for row in seed_rows)
    family_null_margins = [parse_float(row["familySurfaceNullMarginPct"]) for row in null_rows if math.isfinite(parse_float(row["familySurfaceNullMarginPct"]))]
    median_family_null_margin = safe_median(family_null_margins)
    min_family_null_margin = min(family_null_margins or [math.nan])
    weak_leakage = sum(1 for curve in clean_curves if curve["name"] in weak_names)
    active_high_family_count = sum(1 for row in family_rows if int(parse_float(row["activeHighCount"], 0.0)) > 0)
    passes = (
        candidate_summary["highGainPct"] >= 60.0
        and candidate_summary["cleanGainPct"] >= 38.0
        and int(candidate_summary["highAbove20"]) == 0
        and parse_float(candidate_summary["maxProtectedRegressionKmS"]) <= 1.0
        and median_holdout_high >= 60.0
        and median_holdout_clean >= 38.0
        and median_family_null_margin >= 10.0
        and min_family_null_margin >= 0.0
        and weak_leakage == 0
        and active_high_family_count <= 6
    )
    verdict = "v18.07 family-surface law passes" if passes else "v18.07 family-surface law blocked"
    summary = {
        "candidateId": "observed-state-response-v18.07-family-surface-law",
        "verdict": verdict,
        "lawChange": "replace branch-facing v18.05 review catalogue with six continuous response-family surfaces; branch labels are retained only as diagnostics",
        "nominalHighGainPct": candidate_summary["highGainPct"],
        "nominalCleanGainPct": candidate_summary["cleanGainPct"],
        "nominalHighAbove20": candidate_summary["highAbove20"],
        "medianHoldoutHighGainPct": median_holdout_high,
        "medianHoldoutCleanGainPct": median_holdout_clean,
        "maxProtectedRegressionKmS": candidate_summary["maxProtectedRegressionKmS"],
        "activeHighResponseFamilyCount": active_high_family_count,
        "medianFamilySurfaceNullMarginPct": median_family_null_margin,
        "minFamilySurfaceNullMarginPct": min_family_null_margin,
        "v1806HighGainPct": parse_float(compression_summary.get("nominalHighGainPct")),
        "v1806CleanGainPct": parse_float(compression_summary.get("nominalCleanGainPct")),
        "weakSystematicsLeakage": weak_leakage,
        "canonicalMtsChanged": False,
        "qChangedGlobally": False,
        "gamma0Changed": False,
        "mlChanged": False,
    }

    formula = {
        "candidateId": summary["candidateId"],
        "baseCandidate": "observed-state-response-v18.05-release-stress",
        "mechanism": summary["lawChange"],
        "responseFamilies": sorted(observed_state_v1807_family_surface_drives(clean_curves[0]).keys()),
        "familySurfaceEquations": {
            "compact low-load boundary response": "low_load * hinge(memoryLoad>5.6) * hinge(h/rOut<0.18) * hinge(uOut<0.39) * hinge(outerBulgeShare<0.20)",
            "low-load route-edge transition response": "low_load * max(memory-edge, gas-edge, sparse-gas-memory)",
            "gas-memory / gas-rich response": "hinge(fGasOut>0.24) * max(outerGas, midGas, pointDensity)",
            "buffered bulge-shear response": "buffered * max(outerBulge-density, uMax-innerBulge, bar-shear-lowgas)",
            "buffered shelf/curvature response": "buffered * max(negative-curvature-disk, compact-lowgas, high-memory-lowgas)",
            "baseline state multiplier / continuity fallback": "max(memory*uMax, pointDensity) when no explicit family surface dominates",
        },
        "branchLabelsDiagnosticOnly": True,
        "canonicalMtsChanged": False,
        "qChangedGlobally": False,
        "gamma0Changed": False,
        "mlChanged": False,
        "forbiddenInputs": ["galaxy name", "raw residual lookup", "raw RMSE as formula input", "weak/systematics training"],
    }

    artifact_payload = read_window_json_assignment(V18_RELEASE_CANDIDATE_ARTIFACT_PATH, "MTS_V18_05_RELEASE_CANDIDATE")
    if artifact_payload:
        metadata = artifact_payload.setdefault("metadata", {})
        metadata["candidateId"] = summary["candidateId"]
        metadata["displayName"] = "MTS v18.07 family-surface response"
        metadata["verdict"] = verdict
        metadata["familySurfaceV1807"] = {
            "verdict": verdict,
            "highGainPct": summary["nominalHighGainPct"],
            "cleanGainPct": summary["nominalCleanGainPct"],
            "highAbove20": summary["nominalHighAbove20"],
            "medianHoldoutHighGainPct": summary["medianHoldoutHighGainPct"],
            "familyNullMarginPct": summary["medianFamilySurfaceNullMarginPct"],
            "activeHighResponseFamilyCount": summary["activeHighResponseFamilyCount"],
            "weakSystematicsLeakage": summary["weakSystematicsLeakage"],
        }
        metadata["reviewGate"] = {
            **metadata.get("reviewGate", {}),
            "candidateId": summary["candidateId"],
            "verdict": verdict,
            "nominalHighGainPct": summary["nominalHighGainPct"],
            "nominalCleanGainPct": summary["nominalCleanGainPct"],
            "holdoutHighGainPct": summary["medianHoldoutHighGainPct"],
            "stressAbove20": summary["nominalHighAbove20"],
            "familySurfaceNullMarginPct": summary["medianFamilySurfaceNullMarginPct"],
        }
        for curve_payload in artifact_payload.get("curves", {}).values():
            if isinstance(curve_payload, dict):
                curve_payload["candidateId"] = summary["candidateId"]
                curve_payload["releaseCandidate"] = "MTS v18.07 family-surface response"
        write_window_json_assignment(V18_FAMILY_SURFACE_ARTIFACT_PATH, "MTS_V18_07_FAMILY_SURFACE_CANDIDATE", artifact_payload)
        write_window_json_assignment(out_dir / f"{prefix}_browser_artifact.js", "MTS_V18_07_FAMILY_SURFACE_CANDIDATE", artifact_payload)

    write_csv(out_dir / f"{prefix}_scores.csv", [summary])
    write_csv(out_dir / f"{prefix}_seed_replay.csv", seed_rows)
    write_csv(out_dir / f"{prefix}_case_ledger.csv", case_rows)
    write_csv(out_dir / f"{prefix}_family_surface_ledger.csv", family_rows)
    write_csv(out_dir / f"{prefix}_family_ablation.csv", family_ablation_rows)
    write_csv(out_dir / f"{prefix}_family_surface_null_controls.csv", null_rows)
    (out_dir / f"{prefix}_formula.json").write_text(json.dumps(json_clean(formula), indent=2, sort_keys=True), encoding="utf-8")

    top_repairs = sorted(
        [row for row in case_rows if row["set"] == "clean-high-rmse"],
        key=lambda row: parse_float(row["gainKmS"], 0.0),
        reverse=True,
    )[:15]
    worsened = [row for row in case_rows if parse_float(row["gainKmS"], 0.0) < -1e-9]
    report = [
        "# MTS v18.07 Family-Surface Law",
        "",
        "This pass turns the v18.06 compressed families into the public-facing v18 response law surface. Branch names remain in the ledger only so the run can be audited against v18.05; the formula is expressed as six state/profile response families.",
        "",
        "## Result",
        "",
        f"- Verdict: `{verdict}`.",
        f"- Law change: `{summary['lawChange']}`.",
        f"- High-RMSE gain: `{fmt(summary['nominalHighGainPct'])}%`.",
        f"- Clean-set gain: `{fmt(summary['nominalCleanGainPct'])}%`.",
        f"- High-RMSE above 20 km/s: `{summary['nominalHighAbove20']}`.",
        f"- Median holdout high-RMSE gain: `{fmt(summary['medianHoldoutHighGainPct'])}%`.",
        f"- Protected max regression: `{fmt(summary['maxProtectedRegressionKmS'])}` km/s.",
        f"- Active high-RMSE response families: `{summary['activeHighResponseFamilyCount']}`.",
        f"- Median family-surface null margin: `{fmt(summary['medianFamilySurfaceNullMarginPct'])}` points.",
        f"- Minimum family-surface null margin: `{fmt(summary['minFamilySurfaceNullMarginPct'])}` points.",
        f"- Weak/systematics leakage: `{summary['weakSystematicsLeakage']}`.",
        "",
        "## Response Families",
        "",
        "| Family | High hits | Protected hits | Total high gain | Median activation | Null margin |",
        "| --- | ---: | ---: | ---: | ---: | ---: |",
    ]
    for row in sorted(family_rows, key=lambda item: -parse_float(item.get("activeHighTotalGainKmS"), 0.0)):
        family_nulls = [null for null in null_rows if null["responseFamily"] == row["responseFamily"]]
        report.append(
            f"| {row['responseFamily']} | {row['activeHighCount']} | {row['activeProtectedCount']} | "
            f"{fmt(row['activeHighTotalGainKmS'])} | {fmt(row['medianSurfaceActivation'])} | "
            f"{fmt(safe_median(parse_float(null['familySurfaceNullMarginPct']) for null in family_nulls))} |"
        )
    report.extend(
        [
            "",
            "## Largest High-RMSE Repairs",
            "",
            "| Galaxy | Canonical | v18.07 | Gain | Response family |",
            "| --- | ---: | ---: | ---: | --- |",
        ]
    )
    for row in top_repairs:
        report.append(
            f"| {row['galaxy']} | {fmt(row['baselineRmse'])} | {fmt(row['candidateRmse'])} | {fmt(row['gainKmS'])} | {row['responseFamily']} |"
        )
    report.extend(["", "## Regressions", ""])
    if worsened:
        for row in worsened:
            report.append(f"- `{row['galaxy']}` worsened by `{fmt(-parse_float(row['gainKmS']))}` km/s.")
    else:
        report.append("- No clean case worsened under v18.07.")
    report.extend(
        [
            "",
            "## Guardrails",
            "",
            "- Canonical MTS constants remain locked.",
            "- Weak/systematics cases remain excluded.",
            "- No galaxy-name lookup, residual lookup, raw-RMSE formula input, q patch, Gamma0 change, or M/L change is introduced.",
        ]
    )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report), encoding="utf-8")

    capsule = {
        "analysisName": "mts-observed-v18-family-surface-v1",
        "candidateId": summary["candidateId"],
        "verdict": verdict,
        "summary": summary,
        "formula": formula,
        "outputFiles": [
            f"{prefix}_scores.csv",
            f"{prefix}_seed_replay.csv",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_family_surface_ledger.csv",
            f"{prefix}_family_ablation.csv",
            f"{prefix}_family_surface_null_controls.csv",
            f"{prefix}_formula.json",
            f"{prefix}_browser_artifact.js",
            f"{prefix}_report.md",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_observedstatev18familysurface(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_OBSERVED_STATE_V18_FAMILY_SURFACE_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_observed_state_v18_family_surface_artifacts(out_dir)
    summary = capsule["summary"]
    print("MTS v18.07 family-surface law")
    print(f"verdict={summary['verdict']}")
    print(
        "\t".join(
            [
                f"families={summary['activeHighResponseFamilyCount']}",
                f"high={fmt(summary['nominalHighGainPct'])}%",
                f"clean={fmt(summary['nominalCleanGainPct'])}%",
                f"above20={summary['nominalHighAbove20']}",
                f"protected={fmt(summary['maxProtectedRegressionKmS'])}",
                f"family_null_margin={fmt(summary['medianFamilySurfaceNullMarginPct'])}",
                f"weak_leakage={summary['weakSystematicsLeakage']}",
            ]
        )
    )
    print(f"Wrote v18 family-surface law to {out_dir.resolve()}")


def observed_state_v1808_score_curve_with_jittered_state(
    curve: dict,
    state_curve: dict,
    fit: dict,
    amp_cap: float,
) -> dict:
    disabled: set[str] = set()

    def score_with_disabled() -> dict:
        return observed_state_with_disabled_branches(
            disabled,
            lambda: observed_state_score_curve_v1800_baryon_guard(
                curve,
                state_curve,
                fit,
                amp_cap,
                0.08,
                1.0 / 12.0,
            ),
        )

    score = score_with_disabled()
    branch = score.get("observedStateBranch", "")
    vetoes: list[str] = []
    if branch in OBSERVED_STATE_V1803_BRANCH_SAFETY_RULES and not observed_state_v1803_gate_pass(state_curve, branch):
        disabled.add(branch)
        vetoes.append(f"{branch}:v18.03-safety")
        score = score_with_disabled()
        branch = score.get("observedStateBranch", "")
    if branch == OBSERVED_STATE_V1804_EDGE_BRANCH:
        edge_pass, _values, failed_terms = observed_state_v1804_edge_rule_status(state_curve)
        if not edge_pass:
            disabled.add(branch)
            vetoes.append(f"{branch}:v18.04-edge-rule:{';'.join(failed_terms)}")
            score = score_with_disabled()
            branch = score.get("observedStateBranch", "")
    raw_family = score.get("observedStateFamily", observed_state_branch_family(branch)) if branch else ""
    response_family = observed_state_v1806_compressed_family(branch, raw_family)
    drives = observed_state_v1807_family_surface_drives(state_curve)
    score["observedStateV1808Track"] = "v18.08-surface-stress"
    score["observedStateResponseFamily"] = response_family
    score["observedStateFamilySurfaceActivation"] = drives.get(response_family, 0.0)
    score["observedStateFamilySurfaceDrives"] = "; ".join(f"{name}={fmt(value, 4)}" for name, value in sorted(drives.items()))
    score["observedStateV1808DisabledBranches"] = "; ".join(sorted(disabled))
    score["observedStateV1808Vetoes"] = "; ".join(vetoes)
    return score


def observed_state_v1809_score_curve_with_surface_persistence(
    curve: dict,
    state_curve: dict,
    fit: dict,
    amp_cap: float,
) -> dict:
    score = observed_state_v1808_score_curve_with_jittered_state(curve, state_curve, fit, amp_cap)
    fallback_family = "baseline state multiplier / continuity fallback"
    if score.get("observedStateResponseFamily", "") != fallback_family:
        score["observedStateV1809SurfacePersistence"] = False
        return score

    nominal = observed_state_v1807_family_surface_score_curve(curve, fit, amp_cap)
    nominal_family = nominal.get("observedStateResponseFamily", "")
    nominal_branch = nominal.get("observedStateBranchDiagnosticOnly", nominal.get("observedStateBranch", ""))
    if not nominal_branch or nominal_family == fallback_family:
        score["observedStateV1809SurfacePersistence"] = False
        return score

    drives = observed_state_v1807_family_surface_drives(state_curve)
    nominal_drive = parse_float(drives.get(nominal_family, 0.0), 0.0)
    # The stress run perturbs state variables around the observed curve. If the
    # observed curve has a real non-fallback family but the perturbed selector
    # drops only to the broad continuity fallback, keep the local family surface
    # instead of introducing a cliff at the boundary.

    persisted = observed_state_v1805_forced_branch_score(curve, nominal_branch, fit, amp_cap)
    persisted["observedStateV1809Track"] = "v18.09-surface-persistence"
    persisted["observedStateResponseFamily"] = nominal_family
    persisted["observedStateFamilySurfaceActivation"] = nominal_drive
    persisted["observedStateFamilySurfaceDrives"] = "; ".join(f"{name}={fmt(value, 4)}" for name, value in sorted(drives.items()))
    persisted["observedStateBranchDiagnosticOnly"] = nominal_branch
    persisted["observedStateV1809SurfacePersistence"] = True
    persisted["observedStateV1809PersistedFamily"] = nominal_family
    persisted["observedStateV1809PersistedBranch"] = nominal_branch
    persisted["observedStateV1809PersistedFamilyDrive"] = nominal_drive
    persisted["observedStateV1809PersistenceReason"] = "jitter dropout to fallback"
    persisted["observedStateV1808Vetoes"] = score.get("observedStateV1808Vetoes", "")
    return persisted


def write_observed_state_v18_surface_stress_artifacts(
    out_dir: Path,
    prefix: str = "mts_observed_v18_surface_stress",
    score_fn=observed_state_v1808_score_curve_with_jittered_state,
    candidate_id: str = "observed-state-response-v18.08-surface-stress",
    tested_candidate: str = "observed-state-response-v18.07-family-surface-law",
    analysis_name: str = "mts-observed-v18-surface-stress-v1",
    report_title: str = "# MTS v18.08 Surface-Stability Stress",
    report_intro: str = "This pass perturbs the state/profile variables used by the v18.07 family-surface selector. It scores the original clean curves under those perturbed state selectors, so the result tests whether the repair is robust to small state uncertainty.",
    pass_verdict: str = "v18.08 surface stability passed",
    fail_verdict: str = "v18.08 surface smoothing required",
) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    context = observed_state_candidate_context()
    clean_curves = context["cleanCurves"]
    high_names = context["highNames"]
    weak_names = context["weakNames"]
    fit = context["fit"]
    amp_cap = context["ampCap"]

    family_surface_dir = DEFAULT_OBSERVED_STATE_V18_FAMILY_SURFACE_OUT
    family_surface_scores = family_surface_dir / "mts_observed_v18_family_surface_scores.csv"
    if not family_surface_scores.exists():
        write_observed_state_v18_family_surface_artifacts(family_surface_dir)
    v1807_summary = read_csv_rows(family_surface_scores)[0]

    baseline_scores = {curve["name"]: score_curve(curve) for curve in clean_curves}
    nominal_scores = {curve["name"]: observed_state_v1807_family_surface_score_curve(curve, fit, amp_cap) for curve in clean_curves}
    nominal_family = {name: score.get("observedStateResponseFamily", "") for name, score in nominal_scores.items()}
    nominal_branch = {name: score.get("observedStateBranchDiagnosticOnly", score.get("observedStateBranch", "")) for name, score in nominal_scores.items()}

    variant_rows: list[dict] = []
    case_trial_rows: list[dict] = []
    for scale in OBSERVED_STATE_ROBUSTNESS_SCALES:
        for seed in OBSERVED_STATE_ROBUSTNESS_SEEDS:
            trial_scores = []
            for curve in clean_curves:
                base = baseline_scores[curve["name"]]
                state_curve = observed_state_jitter_state_curve(curve, seed, scale)
                cand = score_fn(curve, state_curve, fit, amp_cap)
                trial_scores.append((curve, base, cand))
                if curve["name"] in high_names:
                    family = cand.get("observedStateResponseFamily", "")
                    branch = cand.get("observedStateBranch", "")
                    case_trial_rows.append(
                        {
                            "scale": scale,
                            "seed": seed,
                            "galaxy": curve["name"],
                            "lockedRoute": curve["lockedModelRoute"],
                            "nominalFamily": nominal_family.get(curve["name"], ""),
                            "jitterFamily": family,
                            "familyPreserved": family == nominal_family.get(curve["name"], ""),
                            "nominalBranch": nominal_branch.get(curve["name"], ""),
                            "jitterBranch": branch,
                            "branchPreserved": branch == nominal_branch.get(curve["name"], ""),
                            "surfaceActivation": cand.get("observedStateFamilySurfaceActivation", ""),
                            "baselineRmse": base["rmse"],
                            "nominalRmse": nominal_scores[curve["name"]]["rmse"],
                            "candidateRmse": cand["rmse"],
                            "gainKmS": base["rmse"] - cand["rmse"],
                            "deltaVsNominalKmS": cand["rmse"] - nominal_scores[curve["name"]]["rmse"],
                            "stillAbove20": cand["rmse"] >= 20.0,
                            "worsenedVsBaseline": cand["rmse"] > base["rmse"],
                            "candidateRoute": cand["candidateRoute"],
                            "routeTransition": "" if cand["candidateRoute"] == base["candidateRoute"] else f"{base['candidateRoute']} -> {cand['candidateRoute']}",
                            "vetoes": cand.get("observedStateV1808Vetoes", ""),
                        }
                    )
            high_rows = [row for row in trial_scores if row[0]["name"] in high_names]
            protected_rows = [row for row in trial_scores if row[0]["name"] not in high_names]
            protected_regressions = [row[2]["rmse"] - row[1]["rmse"] for row in protected_rows]
            variant_rows.append(
                {
                    "scale": scale,
                    "seed": seed,
                    "highGainPct": pct_improvement(
                        safe_mean(row[1]["rmse"] for row in high_rows),
                        safe_mean(row[2]["rmse"] for row in high_rows),
                    ),
                    "cleanGainPct": pct_improvement(
                        safe_mean(row[1]["rmse"] for row in trial_scores),
                        safe_mean(row[2]["rmse"] for row in trial_scores),
                    ),
                    "highStillAbove20": sum(1 for row in high_rows if row[2]["rmse"] >= 20.0),
                    "highWorsened": sum(1 for row in high_rows if row[2]["rmse"] > row[1]["rmse"]),
                    "protectedRegressionCount": sum(1 for value in protected_regressions if value > 1e-9),
                    "maxProtectedRegression": max(protected_regressions) if protected_regressions else 0.0,
                    "routePreservation": safe_mean(1.0 if row[2]["candidateRoute"] == row[1]["candidateRoute"] else 0.0 for row in trial_scores),
                    "familyPreservation": safe_mean(
                        1.0
                        if row[2].get("observedStateResponseFamily", "") == nominal_family.get(row[0]["name"], "")
                        else 0.0
                        for row in high_rows
                    ),
                }
            )

    case_rows: list[dict] = []
    for name in sorted(high_names):
        rows = [row for row in case_trial_rows if row["galaxy"] == name]
        if not rows:
            continue
        fail_rows = [row for row in rows if row["stillAbove20"] or row["worsenedVsBaseline"]]
        case_rows.append(
            {
                "galaxy": name,
                "nominalFamily": nominal_family.get(name, ""),
                "nominalBranch": nominal_branch.get(name, ""),
                "nominalRmse": nominal_scores[name]["rmse"],
                "worstJitterRmse": max(parse_float(row["candidateRmse"]) for row in rows),
                "medianJitterRmse": safe_median(parse_float(row["candidateRmse"]) for row in rows),
                "worstDeltaVsNominalKmS": max(parse_float(row["deltaVsNominalKmS"]) for row in rows),
                "familyPreserveRate": safe_mean(1.0 if row["familyPreserved"] else 0.0 for row in rows),
                "branchPreserveRate": safe_mean(1.0 if row["branchPreserved"] else 0.0 for row in rows),
                "under20Rate": safe_mean(0.0 if row["stillAbove20"] else 1.0 for row in rows),
                "improvedRate": safe_mean(0.0 if row["worsenedVsBaseline"] else 1.0 for row in rows),
                "failureTrialCount": len(fail_rows),
                "fragile": len(fail_rows) > 0
                or safe_mean(1.0 if row["familyPreserved"] else 0.0 for row in rows) < 0.80
                or max(parse_float(row["deltaVsNominalKmS"]) for row in rows) > 8.0,
            }
        )

    family_rows: list[dict] = []
    for family in sorted({row["nominalFamily"] for row in case_trial_rows}):
        rows = [row for row in case_trial_rows if row["nominalFamily"] == family]
        if not rows:
            continue
        family_rows.append(
            {
                "responseFamily": family,
                "caseCount": len({row["galaxy"] for row in rows}),
                "familyPreserveRate": safe_mean(1.0 if row["familyPreserved"] else 0.0 for row in rows),
                "branchPreserveRate": safe_mean(1.0 if row["branchPreserved"] else 0.0 for row in rows),
                "under20Rate": safe_mean(0.0 if row["stillAbove20"] else 1.0 for row in rows),
                "medianGainKmS": safe_median(parse_float(row["gainKmS"]) for row in rows),
                "worstRmse": max(parse_float(row["candidateRmse"]) for row in rows),
                "fragileCaseCount": len({row["galaxy"] for row in rows if row["stillAbove20"] or row["worsenedVsBaseline"]}),
            }
        )

    protected_rows: list[dict] = []
    for curve in clean_curves:
        if curve["name"] in high_names:
            continue
        max_reg = 0.0
        reg_count = 0
        worst_scale = 0.0
        worst_family = ""
        for scale in OBSERVED_STATE_ROBUSTNESS_SCALES:
            for seed in OBSERVED_STATE_ROBUSTNESS_SEEDS:
                base = baseline_scores[curve["name"]]
                state_curve = observed_state_jitter_state_curve(curve, seed, scale)
                cand = score_fn(curve, state_curve, fit, amp_cap)
                reg = cand["rmse"] - base["rmse"]
                if reg > max_reg:
                    max_reg = reg
                    worst_scale = scale
                    worst_family = cand.get("observedStateResponseFamily", "")
                if reg > 1e-9:
                    reg_count += 1
        if max_reg > 0.0:
            protected_rows.append(
                {
                    "galaxy": curve["name"],
                    "lockedRoute": curve["lockedModelRoute"],
                    "maxRegression": max_reg,
                    "regressionTrialCount": reg_count,
                    "worstScale": worst_scale,
                    "worstFamily": worst_family,
                    "protectedFailure": max_reg > 4.0,
                }
            )

    scale_rows: list[dict] = []
    for scale in OBSERVED_STATE_ROBUSTNESS_SCALES:
        rows = [row for row in variant_rows if parse_float(row["scale"]) == scale]
        scale_rows.append(
            {
                "scale": scale,
                "medianHighGainPct": safe_median(parse_float(row["highGainPct"]) for row in rows),
                "minHighGainPct": min(parse_float(row["highGainPct"]) for row in rows),
                "medianCleanGainPct": safe_median(parse_float(row["cleanGainPct"]) for row in rows),
                "maxHighStillAbove20": max(int(parse_float(row["highStillAbove20"], 0.0)) for row in rows),
                "maxHighWorsened": max(int(parse_float(row["highWorsened"], 0.0)) for row in rows),
                "maxProtectedRegression": max(parse_float(row["maxProtectedRegression"], 0.0) for row in rows),
                "medianRoutePreservation": safe_median(parse_float(row["routePreservation"]) for row in rows),
                "medianFamilyPreservation": safe_median(parse_float(row["familyPreservation"]) for row in rows),
            }
        )

    fragile_cases = [row for row in case_rows if row["fragile"]]
    fragile_families = [row for row in family_rows if parse_float(row["familyPreserveRate"]) < 0.80 or int(row["fragileCaseCount"]) > 0]
    protected_failures = [row for row in protected_rows if row["protectedFailure"]]
    weak_leakage = sum(1 for curve in clean_curves if curve["name"] in weak_names)
    passes = (
        min(parse_float(row["minHighGainPct"]) for row in scale_rows) >= 55.0
        and max(int(parse_float(row["maxHighStillAbove20"], 0.0)) for row in scale_rows) <= 2
        and max(parse_float(row["maxProtectedRegression"], 0.0) for row in scale_rows) <= 4.0
        and safe_median(parse_float(row["medianFamilyPreservation"]) for row in scale_rows) >= 0.80
        and len(protected_failures) == 0
        and weak_leakage == 0
    )
    verdict = pass_verdict if passes else fail_verdict
    summary = {
        "candidateId": candidate_id,
        "testedCandidate": tested_candidate,
        "verdict": verdict,
        "v1807HighGainPct": parse_float(v1807_summary.get("nominalHighGainPct")),
        "v1807CleanGainPct": parse_float(v1807_summary.get("nominalCleanGainPct")),
        "jitterScales": ";".join(str(scale) for scale in OBSERVED_STATE_ROBUSTNESS_SCALES),
        "trialSeeds": len(OBSERVED_STATE_ROBUSTNESS_SEEDS),
        "minStressHighGainPct": min(parse_float(row["minHighGainPct"]) for row in scale_rows),
        "medianStressHighGainPctAtMaxScale": next(row["medianHighGainPct"] for row in scale_rows if parse_float(row["scale"]) == max(OBSERVED_STATE_ROBUSTNESS_SCALES)),
        "maxStressHighAbove20": max(int(parse_float(row["maxHighStillAbove20"], 0.0)) for row in scale_rows),
        "maxStressProtectedRegressionKmS": max(parse_float(row["maxProtectedRegression"], 0.0) for row in scale_rows),
        "medianFamilyPreservation": safe_median(parse_float(row["familyPreserveRate"]) for row in family_rows),
        "fragileHighGalaxyCount": len(fragile_cases),
        "fragileFamilyCount": len(fragile_families),
        "protectedFailureCount": len(protected_failures),
        "weakSystematicsLeakage": weak_leakage,
    }

    write_csv(out_dir / f"{prefix}_scores.csv", [summary])
    write_csv(out_dir / f"{prefix}_variant_scores.csv", variant_rows)
    write_csv(out_dir / f"{prefix}_scale_summary.csv", scale_rows)
    write_csv(out_dir / f"{prefix}_family_stability.csv", family_rows)
    write_csv(out_dir / f"{prefix}_fragile_cases.csv", case_rows)
    write_csv(out_dir / f"{prefix}_case_trials.csv", case_trial_rows)
    write_csv(out_dir / f"{prefix}_protected_regressions.csv", protected_rows)

    report = [
        report_title,
        "",
        report_intro,
        "",
        "## Result",
        "",
        f"- Verdict: `{verdict}`.",
        f"- v18.07 nominal high-RMSE gain: `{fmt(summary['v1807HighGainPct'])}%`.",
        f"- Minimum stressed high-RMSE gain: `{fmt(summary['minStressHighGainPct'])}%`.",
        f"- Median stressed high-RMSE gain at max scale: `{fmt(summary['medianStressHighGainPctAtMaxScale'])}%`.",
        f"- Max stressed high-RMSE above 20 km/s: `{summary['maxStressHighAbove20']}`.",
        f"- Max stressed protected regression: `{fmt(summary['maxStressProtectedRegressionKmS'])}` km/s.",
        f"- Median family preservation: `{fmt(summary['medianFamilyPreservation'], 3)}`.",
        f"- Fragile high-RMSE galaxies: `{summary['fragileHighGalaxyCount']}`.",
        f"- Fragile response families: `{summary['fragileFamilyCount']}`.",
        f"- Protected failures: `{summary['protectedFailureCount']}`.",
        f"- Weak/systematics leakage: `{summary['weakSystematicsLeakage']}`.",
        "",
        "## Scale Summary",
        "",
        "| Scale | Median high gain | Min high gain | Max above 20 | Max protected regression | Family preservation |",
        "| ---: | ---: | ---: | ---: | ---: | ---: |",
    ]
    for row in scale_rows:
        report.append(
            f"| {fmt(row['scale'])} | {fmt(row['medianHighGainPct'])}% | {fmt(row['minHighGainPct'])}% | "
            f"{row['maxHighStillAbove20']} | {fmt(row['maxProtectedRegression'])} | {fmt(row['medianFamilyPreservation'], 3)} |"
        )
    report.extend(
        [
            "",
            "## Family Stability",
            "",
            "| Family | Cases | Family preserve | Under 20 rate | Worst RMSE | Fragile cases |",
            "| --- | ---: | ---: | ---: | ---: | ---: |",
        ]
    )
    for row in sorted(family_rows, key=lambda item: (parse_float(item["familyPreserveRate"]), -int(parse_float(item["caseCount"], 0.0)))):
        report.append(
            f"| {row['responseFamily']} | {row['caseCount']} | {fmt(row['familyPreserveRate'], 3)} | "
            f"{fmt(row['under20Rate'], 3)} | {fmt(row['worstRmse'])} | {row['fragileCaseCount']} |"
        )
    report.extend(["", "## Most Fragile Cases", ""])
    for row in sorted(case_rows, key=lambda item: (0 if item["fragile"] else 1, -parse_float(item["worstDeltaVsNominalKmS"])))[:15]:
        report.append(
            f"- `{row['galaxy']}`: family `{row['nominalFamily']}`, worst RMSE `{fmt(row['worstJitterRmse'])}`, "
            f"worst delta `{fmt(row['worstDeltaVsNominalKmS'])}`, family preserve `{fmt(row['familyPreserveRate'], 3)}`, under-20 `{fmt(row['under20Rate'], 3)}`."
        )
    report.extend(["", "## Protected Regressions", ""])
    if protected_rows:
        for row in sorted(protected_rows, key=lambda item: parse_float(item["maxRegression"]), reverse=True)[:10]:
            report.append(
                f"- `{row['galaxy']}`: max regression `{fmt(row['maxRegression'])}` km/s at scale `{fmt(row['worstScale'])}`, family `{row['worstFamily']}`."
            )
    else:
        report.append("- None.")
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report), encoding="utf-8")

    capsule = {
        "analysisName": analysis_name,
        "candidateId": summary["candidateId"],
        "testedCandidate": summary["testedCandidate"],
        "verdict": verdict,
        "summary": summary,
        "scaleSummary": scale_rows,
        "outputFiles": [
            f"{prefix}_scores.csv",
            f"{prefix}_variant_scores.csv",
            f"{prefix}_scale_summary.csv",
            f"{prefix}_family_stability.csv",
            f"{prefix}_fragile_cases.csv",
            f"{prefix}_case_trials.csv",
            f"{prefix}_protected_regressions.csv",
            f"{prefix}_report.md",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


