def observed_state_v1814_branch_acceptance_rows(case_rows: list[dict], summary: dict) -> list[dict]:
    high_rows = [row for row in case_rows if row.get("set") == "clean-high-rmse"]
    protected_rows = [row for row in case_rows if row.get("set") == "clean-protected"]
    branch_keys = sorted(
        {
            (
                row.get("responseFamily") or "baseline/continuity fallback",
                row.get("diagnosticBranch") or "native continuity/fallback",
            )
            for row in high_rows
        }
    )
    rows = []
    for family, branch in branch_keys:
        active_high = [
            row
            for row in high_rows
            if (row.get("responseFamily") or "baseline/continuity fallback") == family
            and (row.get("diagnosticBranch") or "native continuity/fallback") == branch
        ]
        active_protected = [
            row
            for row in protected_rows
            if (row.get("responseFamily") or "baseline/continuity fallback") == family
            and (row.get("diagnosticBranch") or "native continuity/fallback") == branch
        ]
        protected_reg = max([parse_float(row.get("protectedRegressionKmS"), 0.0) for row in active_protected] or [0.0])
        rows.append(
            {
                "responseFamily": family,
                "diagnosticBranch": branch,
                "activeHighCount": len(active_high),
                "activeHighGalaxies": "; ".join(row.get("galaxy", "") for row in active_high),
                "activeHighMeanCanonicalRmse": safe_mean(parse_float(row.get("baselineRmse")) for row in active_high),
                "activeHighMeanV18_10Rmse": safe_mean(parse_float(row.get("nativeRmse")) for row in active_high),
                "activeHighTotalGainKmS": sum(parse_float(row.get("nativeGainKmS"), 0.0) for row in active_high),
                "activeHighMeanGainPct": safe_mean(parse_float(row.get("nativeGainPct")) for row in active_high),
                "activeProtectedCount": len(active_protected),
                "activeProtectedMaxRegressionKmS": protected_reg,
                "acceptanceStatus": "release-law accepted" if protected_reg <= 1e-9 else "blocked",
                "acceptanceReason": (
                    "part of v18.10 native-gated release candidate; red-team passed; native/cache/Python parity is zero; protected regression is zero"
                    if protected_reg <= 1e-9
                    else "protected regression exceeds release lock"
                ),
                "source": "mts_v18_redteam_case_ledger.csv",
            }
        )
    return rows


def observed_state_v1814_rejected_compression_rows() -> list[dict]:
    rows: list[dict] = []
    compression_dir = DEFAULT_OBSERVED_STATE_V18_RELEASE_COMPRESSION_OUT
    family_native_dir = DEFAULT_OBSERVED_STATE_V18_FAMILY_NATIVE_OUT
    discriminator_dir = DEFAULT_OBSERVED_STATE_V18_FAMILY_DISCRIMINATOR_OUT
    if not (compression_dir / "mts_v18_11_compression_scores.csv").exists():
        write_observed_state_v18_release_compression_artifacts(compression_dir)
    if not (family_native_dir / "mts_v18_12_family_native_scores.csv").exists():
        write_observed_state_v18_family_native_artifacts(family_native_dir)
    if not (discriminator_dir / "mts_v18_13_family_discriminator_scores.csv").exists():
        write_observed_state_v18_family_discriminator_artifacts(discriminator_dir)

    v18_11 = observed_state_v1814_read_first_csv(compression_dir / "mts_v18_11_compression_scores.csv")
    rows.append(
        {
            "candidate": "v18.11 compressed family release view",
            "status": "kept as explanation layer",
            "highGainPct": v18_11.get("compressedHighGainPct", ""),
            "cleanGainPct": v18_11.get("compressedCleanGainPct", ""),
            "above20": v18_11.get("highAbove20", ""),
            "protectedRegressionKmS": v18_11.get("protectedRegressionKmS", ""),
            "reason": "matches v18.10 scores as a paper/review family view but is not a shorter native browser expression",
            "transportLawStatus": "not replacing v18.10 native expression",
            "source": str(compression_dir / "mts_v18_11_compression_scores.csv"),
        }
    )
    v18_12_scores = read_csv_rows(family_native_dir / "mts_v18_12_family_native_scores.csv")
    best_v18_12 = next((row for row in v18_12_scores if row.get("track") == "safe-drive-threshold"), v18_12_scores[0] if v18_12_scores else {})
    rows.append(
        {
            "candidate": "v18.12 family-native compression",
            "status": "rejected compression",
            "highGainPct": best_v18_12.get("highGainPct", ""),
            "cleanGainPct": best_v18_12.get("cleanGainPct", ""),
            "above20": best_v18_12.get("highAbove20", ""),
            "protectedRegressionKmS": best_v18_12.get("maxProtectedRegressionKmS", ""),
            "reason": "safe drive threshold protects lookalikes but retains only 8.85% of v18.10 high-RMSE gain and leaves 56 high cases above 20",
            "transportLawStatus": "blocked; cannot replace v18.10",
            "source": str(family_native_dir / "mts_v18_12_family_native_scores.csv"),
        }
    )
    v18_13_scores = read_csv_rows(discriminator_dir / "mts_v18_13_family_discriminator_scores.csv")
    promotable_v18_13 = [row for row in v18_13_scores if observed_state_v1814_bool(row.get("promotableTrack"))]
    best_v18_13 = max(promotable_v18_13, key=lambda row: parse_float(row.get("medianHoldoutHighGainPct"), -1e9)) if promotable_v18_13 else (v18_13_scores[0] if v18_13_scores else {})
    rows.append(
        {
            "candidate": "v18.13 one-feature family-overlap discriminator",
            "status": "rejected compression",
            "highGainPct": best_v18_13.get("highGainPct", ""),
            "cleanGainPct": best_v18_13.get("cleanGainPct", ""),
            "above20": best_v18_13.get("highAbove20", ""),
            "protectedRegressionKmS": best_v18_13.get("maxSeedProtectedRegressionKmS", ""),
            "reason": "one-feature discriminator reaches only 15.50% full high gain, 8.08% median holdout high gain, and protected holdout regressions recur",
            "transportLawStatus": "blocked; cannot replace v18.10",
            "source": str(discriminator_dir / "mts_v18_13_family_discriminator_scores.csv"),
        }
    )
    return rows


def observed_state_v1814_browser_qa_rows(summary: dict) -> list[dict]:
    app_text = (ROOT / "app.js").read_text(encoding="utf-8")
    index_text = (ROOT / "index.html").read_text(encoding="utf-8")
    return [
        {
            "check": "browser label",
            "expected": "MTS v18.10 release candidate (native gated)",
            "value": "present" if "MTS v18.10 release candidate (native gated)" in app_text + index_text else "missing",
            "pass": "MTS v18.10 release candidate (native gated)" in app_text + index_text,
            "source": "app.js; index.html",
        },
        {
            "check": "runtime source",
            "expected": "native expression",
            "value": "native expression" if observed_state_v1814_bool(summary.get("nativeFormulaCanReplaceCache")) else "exact cache locked",
            "pass": observed_state_v1814_bool(summary.get("nativeFormulaCanReplaceCache")),
            "source": "data/v18-09-surface-persistence-candidate.js metadata.nativeFormulaV1809",
        },
        {
            "check": "cache mismatch",
            "expected": "0",
            "value": summary.get("cacheVsPythonMismatchCount", ""),
            "pass": int(parse_float(summary.get("cacheVsPythonMismatchCount"), 999.0)) == 0,
            "source": "mts_v18_redteam_scores.csv",
        },
        {
            "check": "native mismatch",
            "expected": "0",
            "value": summary.get("nativeVsPythonMismatchCount", ""),
            "pass": int(parse_float(summary.get("nativeVsPythonMismatchCount"), 999.0)) == 0,
            "source": "mts_v18_redteam_scores.csv",
        },
        {
            "check": "native/cache mismatch",
            "expected": "0",
            "value": summary.get("nativeVsCacheMismatchCount", ""),
            "pass": int(parse_float(summary.get("nativeVsCacheMismatchCount"), 999.0)) == 0,
            "source": "mts_v18_redteam_scores.csv",
        },
        {
            "check": "route mismatch",
            "expected": "0",
            "value": summary.get("routeMismatchCount", ""),
            "pass": int(parse_float(summary.get("routeMismatchCount"), 999.0)) == 0,
            "source": "mts_v18_redteam_scores.csv",
        },
        {
            "check": "browser does not advertise v18.12/v18.13 as release law",
            "expected": "no v18.12/v18.13 browser preset",
            "value": "clean" if "v18.12" not in app_text + index_text and "v18.13" not in app_text + index_text else "mentions v18.12/v18.13",
            "pass": "v18.12" not in app_text + index_text and "v18.13" not in app_text + index_text,
            "source": "app.js; index.html",
        },
    ]


def write_observed_state_v18_release_lock_final_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_v18_release_lock_final"
    redteam_dir = DEFAULT_OBSERVED_STATE_V18_REDTEAM_OUT
    materials_dir = DEFAULT_OBSERVED_STATE_V18_RELEASE_MATERIALS_OUT
    if not (redteam_dir / "mts_v18_redteam_scores.csv").exists():
        write_observed_state_v18_redteam_artifacts(redteam_dir)
    if not (materials_dir / "mts_v18_10_release_materials_capsule.json").exists():
        write_observed_state_v18_release_materials_artifacts(materials_dir)

    redteam_summary = observed_state_v1814_read_first_csv(redteam_dir / "mts_v18_redteam_scores.csv")
    case_rows = read_csv_rows(redteam_dir / "mts_v18_redteam_case_ledger.csv")
    high_rows = [row for row in case_rows if row.get("set") == "clean-high-rmse"]
    protected_rows = [row for row in case_rows if row.get("set") == "clean-protected"]
    weak_rows = [row for row in case_rows if row.get("set") == "weak-systematics-excluded"]
    branch_rows = observed_state_v1814_branch_acceptance_rows(case_rows, redteam_summary)
    rejected_rows = observed_state_v1814_rejected_compression_rows()
    browser_rows = observed_state_v1814_browser_qa_rows(redteam_summary)
    guard_rows = observed_state_v1814_guard_rows(redteam_summary)
    protected_regressions = [
        row for row in protected_rows if parse_float(row.get("protectedRegressionKmS"), 0.0) > 1e-9
    ]
    passes = observed_state_v1814_release_pass(redteam_summary) and all(observed_state_v1814_bool(row["pass"]) for row in browser_rows)
    verdict = "v18.10 release candidate locked" if passes else "release lock blocked"

    score_row = {
        "candidateId": "observed-state-response-v18.14-release-lock-final",
        "lockedCandidate": "observed-state-response-v18.10-native-gated-release",
        "sourceOfTruth": "v18.10 native expression; exact cache retained as QA fallback",
        "verdict": verdict,
        "allGalaxyLockedMtsMeanRmse": redteam_summary.get("allGalaxyLockedMtsMeanRmse", ""),
        "cleanSetLockedMtsMeanRmse": redteam_summary.get("cleanSetLockedMtsMeanRmse", ""),
        "cleanHighGainPct": redteam_summary.get("cleanHighGainPct", ""),
        "cleanGainPct": redteam_summary.get("cleanGainPct", ""),
        "cleanHighAbove20Native": redteam_summary.get("cleanHighAbove20Native", ""),
        "protectedRegressionCount": len(protected_regressions),
        "maxProtectedRegressionKmS": redteam_summary.get("maxProtectedRegressionKmS", ""),
        "medianHoldoutHighGainPct": redteam_summary.get("medianHoldoutHighGainPct", ""),
        "medianHoldoutCleanGainPct": redteam_summary.get("medianHoldoutCleanGainPct", ""),
        "weakSystematicsExcludedCount": redteam_summary.get("weakSystematicsExcludedCount", ""),
        "weakSystematicsLeakage": redteam_summary.get("weakSystematicsLeakage", ""),
        "cacheVsPythonMismatchCount": redteam_summary.get("cacheVsPythonMismatchCount", ""),
        "nativeVsPythonMismatchCount": redteam_summary.get("nativeVsPythonMismatchCount", ""),
        "nativeVsCacheMismatchCount": redteam_summary.get("nativeVsCacheMismatchCount", ""),
        "routeMismatchCount": redteam_summary.get("routeMismatchCount", ""),
        "nativeFormulaCanReplaceCache": redteam_summary.get("nativeFormulaCanReplaceCache", ""),
        "familySurfaceNullMarginPct": redteam_summary.get("familySurfaceNullMarginPct", ""),
        "branchShuffleNullMarginPct": redteam_summary.get("branchShuffleNullMarginPct", ""),
        "edgeNullMarginPct": redteam_summary.get("edgeNullMarginPct", ""),
        "v18_12Status": "rejected compression; not a release law",
        "v18_13Status": "rejected compression; not a release law",
        "browserUpdated": False,
    }

    high_repair_rows = [
        {
            "galaxy": row.get("galaxy", ""),
            "lockedRoute": row.get("lockedRoute", ""),
            "canonicalRmse": row.get("baselineRmse", ""),
            "v18_10Rmse": row.get("nativeRmse", ""),
            "gainKmS": row.get("nativeGainKmS", ""),
            "gainPct": row.get("nativeGainPct", ""),
            "stillAbove20": row.get("nativeStillAbove20", ""),
            "routeTransition": row.get("routeTransition", ""),
            "responseFamily": row.get("responseFamily") or "baseline/continuity fallback",
            "diagnosticBranch": row.get("diagnosticBranch") or "native continuity/fallback",
            "source": "mts_v18_redteam_case_ledger.csv",
        }
        for row in sorted(high_rows, key=lambda item: parse_float(item.get("nativeGainKmS"), 0.0), reverse=True)
    ]
    protected_ledger_rows = [
        {
            "galaxy": row.get("galaxy", ""),
            "lockedRoute": row.get("lockedRoute", ""),
            "canonicalRmse": row.get("baselineRmse", ""),
            "v18_10Rmse": row.get("nativeRmse", ""),
            "gainKmS": row.get("nativeGainKmS", ""),
            "protectedRegressionKmS": row.get("protectedRegressionKmS", ""),
            "branchHit": bool(row.get("diagnosticBranch")),
            "responseFamily": row.get("responseFamily", ""),
            "diagnosticBranch": row.get("diagnosticBranch", ""),
            "status": "protected; no regression allowed",
            "source": "mts_v18_redteam_case_ledger.csv",
        }
        for row in sorted(protected_rows, key=lambda item: item.get("galaxy", ""))
    ]
    weak_ledger_rows = [
        {
            "galaxy": row.get("galaxy", ""),
            "lockedRoute": row.get("lockedRoute", ""),
            "canonicalRmse": row.get("baselineRmse", ""),
            "diagnosticV18_10Rmse": row.get("nativeRmse", ""),
            "reason": "weak/systematics holdout from clean validation chain",
            "status": "excluded from transport-law fitting",
            "source": "mts_v18_redteam_case_ledger.csv",
        }
        for row in sorted(weak_rows, key=lambda item: item.get("galaxy", ""))
    ]

    write_csv(out_dir / f"{prefix}_scores.csv", [score_row])
    write_csv(out_dir / f"{prefix}_high_rmse_repairs.csv", high_repair_rows)
    write_csv(out_dir / f"{prefix}_protected_ledger.csv", protected_ledger_rows)
    write_csv(out_dir / f"{prefix}_weak_systematics_ledger.csv", weak_ledger_rows)
    write_csv(out_dir / f"{prefix}_branch_acceptance.csv", branch_rows)
    write_csv(out_dir / f"{prefix}_rejected_compressions.csv", rejected_rows)
    write_csv(out_dir / f"{prefix}_browser_qa.csv", browser_rows)
    write_csv(out_dir / f"{prefix}_guardrails.csv", guard_rows)

    formula = {
        "candidateId": score_row["candidateId"],
        "lockedCandidate": score_row["lockedCandidate"],
        "status": "locked" if passes else "blocked",
        "sourceOfTruth": score_row["sourceOfTruth"],
        "browserLabel": "MTS v18.10 release candidate (native gated)",
        "nativeFormulaCanReplaceCache": observed_state_v1814_bool(redteam_summary.get("nativeFormulaCanReplaceCache")),
        "exactCacheFallback": "retained as QA fallback only",
        "canonicalConstants": {"q": Q_DEFAULT, "Gamma0": GAMMA0, "ML_disk": ML_DISK, "ML_bulge": ML_BULGE},
        "forbiddenInputsUsed": False,
        "forbiddenInputs": ["galaxy name", "raw residual lookup", "raw RMSE formula input", "weak/systematics training"],
        "rejectedCompressionCandidates": ["v18.12 family-native compression", "v18.13 one-feature family-overlap discriminator"],
        "browserUpdated": False,
    }
    (out_dir / f"{prefix}_formula.json").write_text(json.dumps(json_clean(formula), indent=2, sort_keys=True), encoding="utf-8")

    top_repairs = high_repair_rows[:15]
    report = [
        "# MTS v18.14 Release Candidate Lock",
        "",
        "This mode locks v18.10 as the framework-forward release candidate and stops treating v18.12/v18.13 compression attempts as replacement laws.",
        "",
        "## Result",
        "",
        f"- Verdict: `{verdict}`.",
        f"- Source of truth: `{score_row['sourceOfTruth']}`.",
        f"- All-galaxy locked-MTS mean RMSE: `{fmt(parse_float(score_row['allGalaxyLockedMtsMeanRmse']))}`.",
        f"- Clean locked-MTS mean RMSE: `{fmt(parse_float(score_row['cleanSetLockedMtsMeanRmse']))}`.",
        f"- Clean high-RMSE gain: `{fmt(parse_float(score_row['cleanHighGainPct']))}%`.",
        f"- Clean-set gain: `{fmt(parse_float(score_row['cleanGainPct']))}%`.",
        f"- Clean high-RMSE above 20: `{score_row['cleanHighAbove20Native']}`.",
        f"- Protected regressions: `{score_row['protectedRegressionCount']}`; max `{fmt(parse_float(score_row['maxProtectedRegressionKmS']))}` km/s.",
        f"- Native/cache/Python mismatches: `{score_row['nativeVsPythonMismatchCount']}` / `{score_row['nativeVsCacheMismatchCount']}` / `{score_row['cacheVsPythonMismatchCount']}`.",
        f"- Weak/systematics excluded: `{score_row['weakSystematicsExcludedCount']}`.",
        "",
        "## Largest Clean High-RMSE Repairs",
        "",
        "| Galaxy | Canonical | v18.10 | Gain | Family | Branch |",
        "| --- | ---: | ---: | ---: | --- | --- |",
    ]
    for row in top_repairs:
        report.append(
            f"| {row['galaxy']} | {fmt(parse_float(row['canonicalRmse']))} | {fmt(parse_float(row['v18_10Rmse']))} | {fmt(parse_float(row['gainKmS']))} | {row['responseFamily']} | {row['diagnosticBranch']} |"
        )
    report.extend(
        [
            "",
            "## Rejected Compression Attempts",
            "",
            "| Candidate | Status | High gain | Above20 | Reason |",
            "| --- | --- | ---: | ---: | --- |",
        ]
    )
    for row in rejected_rows:
        report.append(
            f"| {row['candidate']} | {row['status']} | {fmt(parse_float(row['highGainPct']))} | {row.get('above20', '')} | {row['reason']} |"
        )
    report.extend(
        [
            "",
            "## Browser Lock",
            "",
            "The browser already presents `MTS v18.10 release candidate (native gated)`. Runtime should report `native expression`; the exact cache remains a QA fallback, not the release source of truth.",
            "",
            verdict,
        ]
    )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report), encoding="utf-8")

    capsule = {
        "analysisName": "mts-observed-v18-release-lock-final-v1",
        "candidateId": score_row["candidateId"],
        "verdict": verdict,
        "summary": score_row,
        "outputFiles": [
            f"{prefix}_scores.csv",
            f"{prefix}_high_rmse_repairs.csv",
            f"{prefix}_protected_ledger.csv",
            f"{prefix}_weak_systematics_ledger.csv",
            f"{prefix}_branch_acceptance.csv",
            f"{prefix}_rejected_compressions.csv",
            f"{prefix}_browser_qa.csv",
            f"{prefix}_guardrails.csv",
            f"{prefix}_formula.json",
            f"{prefix}_report.md",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_v18releaselockfinal(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_OBSERVED_STATE_V18_RELEASE_LOCK_FINAL_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_observed_state_v18_release_lock_final_artifacts(out_dir)
    summary = capsule["summary"]
    print("MTS v18.14 release candidate lock")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"baseline={fmt(parse_float(summary['allGalaxyLockedMtsMeanRmse']))}",
                f"clean={fmt(parse_float(summary['cleanSetLockedMtsMeanRmse']))}",
                f"high_gain={fmt(parse_float(summary['cleanHighGainPct']))}%",
                f"clean_gain={fmt(parse_float(summary['cleanGainPct']))}%",
                f"above20={summary['cleanHighAbove20Native']}",
                f"protected={fmt(parse_float(summary['maxProtectedRegressionKmS']))}",
                f"native_py_mismatch={summary['nativeVsPythonMismatchCount']}",
                f"native_cache_mismatch={summary['nativeVsCacheMismatchCount']}",
                f"weak_excluded={summary['weakSystematicsExcludedCount']}",
                f"browser_updated={summary['browserUpdated']}",
            ]
        )
    )
    print(f"Wrote v18.14 release lock to {out_dir.resolve()}")


V18_COMPETITOR_A0_FIXED = 1.2e-10
V18_COMPETITOR_KPC_M = 3.0856775814913673e19
V18_COMPETITOR_H0 = 70.0


def v18_competitor_logspace(low: float, high: float, count: int) -> list[float]:
    if count <= 1:
        return [low]
    log_low = math.log(low)
    log_high = math.log(high)
    return [math.exp(log_low + (log_high - log_low) * index / (count - 1)) for index in range(count)]


def v18_competitor_support_score(curve: dict, supports: list[float]) -> dict:
    score = observed_state_score_curve_from_supports(curve, supports)
    sse = 0.0
    chi2 = 0.0
    for point, support2 in zip(curve["points"], supports):
        model = math.sqrt(max(0.0, point["bar2"] + max(0.0, support2)))
        residual = model - point["vObs"]
        sigma = max(ERR_FLOOR, abs(point.get("err", ERR_FLOOR)))
        sse += residual * residual
        chi2 += (residual / sigma) ** 2
    score.update({"sse": sse, "chi2": chi2, "pointCount": len(curve["points"])})
    return score


def v18_competitor_canonical_supports(curve: dict) -> list[float]:
    return [
        GAMMA0 * curve["leff"] * (1.0 - math.exp(-((point["r"] / curve["leff"]) ** Q_DEFAULT)))
        for point in curve["points"]
    ]


def v18_competitor_mond_supports(curve: dict, a0_si: float) -> list[float]:
    supports: list[float] = []
    for point in curve["points"]:
        r_m = max(1e-12, point["r"] * V18_COMPETITOR_KPC_M)
        g_newton = max(0.0, point["bar2"]) * 1.0e6 / r_m
        if g_newton <= 0.0:
            v2_mond = 0.0
        else:
            # Simple MOND interpolation: nu(y)=1/2+sqrt(1/4+1/y).
            nu = 0.5 + math.sqrt(0.25 + a0_si / g_newton)
            v2_mond = g_newton * nu * r_m / 1.0e6
        supports.append(max(0.0, v2_mond - point["bar2"]))
    return supports


def v18_competitor_nfw_f(c: float) -> float:
    return math.log1p(c) - c / (1.0 + c)


def v18_competitor_nfw_halo_v2(r_kpc: float, v200: float, c: float) -> float:
    r200 = max(1e-9, 100.0 * v200 / V18_COMPETITOR_H0)
    x = max(1e-9, r_kpc / r200)
    cx = c * x
    denom = max(1e-12, x * v18_competitor_nfw_f(c))
    numer = math.log1p(cx) - cx / (1.0 + cx)
    return max(0.0, v200 * v200 * numer / denom)


def v18_competitor_nfw_expected_c(v200: float) -> float:
    return 10.0 * ((max(v200, 1e-9) / 100.0) ** -0.10)


def v18_competitor_nfw_supports(curve: dict, v200: float, c: float) -> list[float]:
    return [v18_competitor_nfw_halo_v2(point["r"], v200, c) for point in curve["points"]]


def v18_competitor_objective(curve: dict, supports: list[float]) -> tuple[float, float, float]:
    sse = 0.0
    chi2 = 0.0
    for point, support2 in zip(curve["points"], supports):
        model = math.sqrt(max(0.0, point["bar2"] + max(0.0, support2)))
        residual = model - point["vObs"]
        sigma = max(ERR_FLOOR, abs(point.get("err", ERR_FLOOR)))
        sse += residual * residual
        chi2 += (residual / sigma) ** 2
    return sse, chi2, math.sqrt(sse / len(curve["points"]))


def v18_competitor_fit_mond_a0(curves: list[dict], train_names: set[str]) -> tuple[float, list[dict]]:
    grid = v18_competitor_logspace(0.2e-10, 5.0e-10, 81)
    rows: list[dict] = []
    best_a0 = V18_COMPETITOR_A0_FIXED
    best_sse = math.inf
    train_curves = [curve for curve in curves if curve["name"] in train_names]
    for a0_si in grid:
        sse = 0.0
        n = 0
        for curve in train_curves:
            curve_sse, _chi2, _rmse = v18_competitor_objective(curve, v18_competitor_mond_supports(curve, a0_si))
            sse += curve_sse
            n += len(curve["points"])
        mean_rmse = math.sqrt(sse / n) if n else math.nan
        rows.append(
            {
                "track": "mond-global-a0-train-grid",
                "a0SI": a0_si,
                "trainPointCount": n,
                "trainSse": sse,
                "trainRmse": mean_rmse,
            }
        )
        if sse < best_sse:
            best_sse = sse
            best_a0 = a0_si
    return best_a0, rows


def v18_competitor_fit_mond_oracle(curve: dict) -> tuple[float, dict]:
    best_a0 = V18_COMPETITOR_A0_FIXED
    best_score: dict | None = None
    for a0_si in v18_competitor_logspace(0.1e-10, 10.0e-10, 101):
        score = v18_competitor_support_score(curve, v18_competitor_mond_supports(curve, a0_si))
        if best_score is None or score["rmse"] < best_score["rmse"]:
            best_score = score
            best_a0 = a0_si
    assert best_score is not None
    return best_a0, best_score


def v18_competitor_fit_nfw(curve: dict, concentration_prior: bool) -> tuple[float, float, dict, dict]:
    coarse_v200 = v18_competitor_logspace(20.0, 500.0, 36)
    coarse_c = v18_competitor_logspace(2.0, 40.0, 30)
    best = {"objective": math.inf, "v200": math.nan, "c": math.nan, "score": {}}

    def objective(v200: float, c: float) -> tuple[float, dict, float]:
        supports = v18_competitor_nfw_supports(curve, v200, c)
        score = v18_competitor_support_score(curve, supports)
        prior_penalty = 0.0
        if concentration_prior:
            expected = v18_competitor_nfw_expected_c(v200)
            sigma_ln_c = math.log(10.0) * 0.15
            prior_penalty = ((math.log(max(c, 1e-9)) - math.log(expected)) / sigma_ln_c) ** 2
        return score["chi2"] + prior_penalty, score, prior_penalty

    for v200 in coarse_v200:
        for c in coarse_c:
            obj, score, prior_penalty = objective(v200, c)
            if obj < best["objective"]:
                best = {"objective": obj, "v200": v200, "c": c, "score": score, "priorPenalty": prior_penalty}

    refine_v200 = [best["v200"] * factor for factor in [0.72, 0.80, 0.88, 0.94, 1.0, 1.06, 1.14, 1.25, 1.38]]
    refine_c = [best["c"] * factor for factor in [0.72, 0.80, 0.88, 0.94, 1.0, 1.06, 1.14, 1.25, 1.38]]
    for v200 in refine_v200:
        if not (10.0 <= v200 <= 800.0):
            continue
        for c in refine_c:
            if not (1.0 <= c <= 80.0):
                continue
            obj, score, prior_penalty = objective(v200, c)
            if obj < best["objective"]:
                best = {"objective": obj, "v200": v200, "c": c, "score": score, "priorPenalty": prior_penalty}

    params = {
        "v200KmS": best["v200"],
        "concentration": best["c"],
        "r200Kpc": 100.0 * best["v200"] / V18_COMPETITOR_H0,
        "expectedConcentration": v18_competitor_nfw_expected_c(best["v200"]),
        "priorPenalty": best.get("priorPenalty", 0.0),
        "objectiveChi2PlusPrior": best["objective"],
    }
    return best["v200"], best["c"], best["score"], params


def v18_competitor_aic_bic(sse: float, point_count: int, fitted_param_count: int) -> tuple[float, float]:
    if point_count <= 0:
        return math.nan, math.nan
    safe_sse = max(1e-12, sse)
    aic = point_count * math.log(safe_sse / point_count) + 2 * fitted_param_count
    bic = point_count * math.log(safe_sse / point_count) + fitted_param_count * math.log(point_count)
    return aic, bic


def v18_competitor_set_label(name: str, weak_names: set[str], high_names: set[str]) -> str:
    if name in weak_names:
        return "weak-systematics-excluded"
    if name in high_names:
        return "clean-high-rmse"
    return "clean-protected"


def v18_competitor_summary_row(
    model_id: str,
    rows: list[dict],
    set_name: str,
    fitted_global_params: int,
    fitted_per_galaxy_params: int,
    law_param_count: int,
    model_class: str,
) -> dict:
    selected = [row for row in rows if row["set"] == set_name] if set_name != "all" else rows[:]
    clean_selected = [row for row in selected if row["set"] != "weak-systematics-excluded"]
    high_selected = [row for row in selected if row["set"] == "clean-high-rmse"]
    protected_selected = [row for row in selected if row["set"] == "clean-protected"]
    sse = sum(parse_float(row[f"{model_id}Sse"], 0.0) for row in selected)
    point_count = sum(int(parse_float(row["pointCount"], 0.0)) for row in selected)
    fitted_params = fitted_global_params + fitted_per_galaxy_params * len({row["galaxy"] for row in selected})
    aic, bic = v18_competitor_aic_bic(sse, point_count, fitted_params)
    mean_rmse = safe_mean(parse_float(row[f"{model_id}Rmse"]) for row in selected)
    baseline_mean = safe_mean(parse_float(row["canonical_mtsRmse"]) for row in selected)
    return {
        "modelId": model_id,
        "set": set_name,
        "modelClass": model_class,
        "galaxyCount": len(selected),
        "cleanGalaxyCount": len(clean_selected),
        "pointCount": point_count,
        "meanRmse": mean_rmse,
        "medianRmse": safe_median(parse_float(row[f"{model_id}Rmse"]) for row in selected),
        "meanGainVsCanonicalPct": pct_improvement(baseline_mean, mean_rmse),
        "highRmseCount": len(high_selected),
        "highMeanRmse": safe_mean(parse_float(row[f"{model_id}Rmse"]) for row in high_selected),
        "highGainVsCanonicalPct": pct_improvement(
            safe_mean(parse_float(row["canonical_mtsRmse"]) for row in high_selected),
            safe_mean(parse_float(row[f"{model_id}Rmse"]) for row in high_selected),
        ),
        "highAbove20Count": sum(1 for row in high_selected if parse_float(row[f"{model_id}Rmse"]) >= 20.0),
        "protectedCount": len(protected_selected),
        "protectedRegressionCount": sum(
            1
            for row in protected_selected
            if parse_float(row[f"{model_id}Rmse"]) - parse_float(row["canonical_mtsRmse"]) > 1e-9
        ),
        "maxProtectedRegressionKmS": max(
            [parse_float(row[f"{model_id}Rmse"]) - parse_float(row["canonical_mtsRmse"]) for row in protected_selected]
            or [0.0]
        ),
        "sse": sse,
        "aic": aic,
        "bic": bic,
        "benchmarkFittedGlobalParams": fitted_global_params,
        "benchmarkFittedPerGalaxyParams": fitted_per_galaxy_params,
        "benchmarkFittedTotalParamsOnSet": fitted_params,
        "declaredLawParamCount": law_param_count,
    }


def write_v18_competitor_benchmark_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_v18_competitor"
    lock_capsule = write_observed_state_v18_release_lock_final_artifacts(DEFAULT_OBSERVED_STATE_V18_RELEASE_LOCK_FINAL_OUT)
    context = observed_state_candidate_context()
    curves = context["curves"]
    clean_curves = context["cleanCurves"]
    weak_names = context["weakNames"]
    high_names = context["highNames"]
    fit = context["fit"]
    amp_cap = context["ampCap"]
    train_names, holdout_names = observed_state_split(clean_curves, SPLIT_SEED, HOLDOUT_FRACTION)

    expression = observed_state_app_expression(fit, amp_cap)
    native_support_lookup = observed_state_browser_formula_supports(curves, expression)
    mond_global_a0, mond_grid_rows = v18_competitor_fit_mond_a0(clean_curves, train_names)

    case_rows: list[dict] = []
    mond_param_rows: list[dict] = []
    nfw_param_rows: list[dict] = []
    for curve in curves:
        name = curve["name"]
        set_label = v18_competitor_set_label(name, weak_names, high_names)
        split = "weak-excluded" if name in weak_names else ("train" if name in train_names else "holdout")

        baryon = v18_competitor_support_score(curve, [0.0 for _ in curve["points"]])
        canonical = v18_competitor_support_score(curve, v18_competitor_canonical_supports(curve))
        v18_supports = [native_support_lookup[(name, index)] for index in range(len(curve["points"]))]
        v18_score = v18_competitor_support_score(curve, v18_supports)
        mond_fixed = v18_competitor_support_score(curve, v18_competitor_mond_supports(curve, V18_COMPETITOR_A0_FIXED))
        mond_global = v18_competitor_support_score(curve, v18_competitor_mond_supports(curve, mond_global_a0))
        mond_oracle_a0, mond_oracle = v18_competitor_fit_mond_oracle(curve)
        _v200_free, _c_free, nfw_free, nfw_free_params = v18_competitor_fit_nfw(curve, concentration_prior=False)
        _v200_prior, _c_prior, nfw_prior, nfw_prior_params = v18_competitor_fit_nfw(curve, concentration_prior=True)

        scores = {
            "baryon_fixed_ml": baryon,
            "canonical_mts": canonical,
            "v18_10_release": v18_score,
            "mond_fixed_a0": mond_fixed,
            "mond_global_a0": mond_global,
            "mond_per_galaxy_a0_oracle": mond_oracle,
            "nfw_free": nfw_free,
            "nfw_concentration_prior": nfw_prior,
        }
        rmse_items = sorted((score["rmse"], model_id) for model_id, score in scores.items())
        winner_rmse, winner_model = rmse_items[0]
        second_rmse, second_model = rmse_items[1] if len(rmse_items) > 1 else (math.nan, "")
        row = {
            "galaxy": name,
            "set": set_label,
            "split": split,
            "pointCount": len(curve["points"]),
            "lockedRoute": curve.get("lockedModelRoute", ""),
            "rOut": curve.get("rOut", math.nan),
            "h": curve.get("h", math.nan),
            "fGasOut": curve.get("fGasOut", math.nan),
            "memoryLoad": curve.get("memoryLoad", math.nan),
            "winnerRawRmse": winner_model,
            "winnerRmse": winner_rmse,
            "secondRawRmse": second_model,
            "secondRmse": second_rmse,
            "v18BeatsMondFixed": v18_score["rmse"] < mond_fixed["rmse"],
            "v18BeatsMondGlobal": v18_score["rmse"] < mond_global["rmse"],
            "v18BeatsNfwPrior": v18_score["rmse"] < nfw_prior["rmse"],
            "v18BeatsNfwFree": v18_score["rmse"] < nfw_free["rmse"],
        }
        for model_id, score in scores.items():
            row[f"{model_id}Rmse"] = score["rmse"]
            row[f"{model_id}Sse"] = score["sse"]
            row[f"{model_id}Chi2"] = score["chi2"]
            row[f"{model_id}Route"] = score.get("candidateRoute", "")
        row.update(
            {
                "v18GainVsCanonicalKmS": canonical["rmse"] - v18_score["rmse"],
                "v18GainVsCanonicalPct": pct_improvement(canonical["rmse"], v18_score["rmse"]),
                "v18MinusMondFixedKmS": v18_score["rmse"] - mond_fixed["rmse"],
                "v18MinusMondGlobalKmS": v18_score["rmse"] - mond_global["rmse"],
                "v18MinusNfwPriorKmS": v18_score["rmse"] - nfw_prior["rmse"],
                "v18MinusNfwFreeKmS": v18_score["rmse"] - nfw_free["rmse"],
                "protectedV18RegressionKmS": max(0.0, v18_score["rmse"] - canonical["rmse"]) if set_label == "clean-protected" else "",
            }
        )
        case_rows.append(row)
        mond_param_rows.extend(
            [
                {
                    "track": "fixed-a0",
                    "galaxy": name,
                    "set": set_label,
                    "a0SI": V18_COMPETITOR_A0_FIXED,
                    "rmse": mond_fixed["rmse"],
                    "fittedScope": "fixed literature value",
                    "promotable": True,
                },
                {
                    "track": "global-a0-train",
                    "galaxy": name,
                    "set": set_label,
                    "a0SI": mond_global_a0,
                    "rmse": mond_global["rmse"],
                    "fittedScope": "one global parameter fitted on clean train split only",
                    "promotable": True,
                },
                {
                    "track": "per-galaxy-a0-oracle",
                    "galaxy": name,
                    "set": set_label,
                    "a0SI": mond_oracle_a0,
                    "rmse": mond_oracle["rmse"],
                    "fittedScope": "per-galaxy oracle",
                    "promotable": False,
                },
            ]
        )
        for track, score, params, promotable in [
            ("nfw-free", nfw_free, nfw_free_params, False),
            ("nfw-concentration-prior", nfw_prior, nfw_prior_params, False),
        ]:
            nfw_param_rows.append(
                {
                    "track": track,
                    "galaxy": name,
                    "set": set_label,
                    "v200KmS": params["v200KmS"],
                    "concentration": params["concentration"],
                    "r200Kpc": params["r200Kpc"],
                    "expectedConcentration": params["expectedConcentration"],
                    "priorPenalty": params["priorPenalty"],
                    "objectiveChi2PlusPrior": params["objectiveChi2PlusPrior"],
                    "rmse": score["rmse"],
                    "fittedScope": "two per-galaxy halo parameters",
                    "promotableAsMtsLaw": promotable,
                }
            )

    model_specs = [
        ("baryon_fixed_ml", 0, 0, 2, "fixed baryonic baseline"),
        ("canonical_mts", 0, 0, 4, "locked MTS law"),
        ("v18_10_release", 0, 0, 4, "locked MTS v18.10 state law"),
        ("mond_fixed_a0", 0, 0, 1, "fixed MOND simple-interpolation law"),
        ("mond_global_a0", 1, 0, 1, "MOND one global train-fit parameter"),
        ("mond_per_galaxy_a0_oracle", 0, 1, 1, "per-galaxy MOND oracle"),
        ("nfw_free", 0, 2, 2, "per-galaxy NFW high-flexibility ceiling"),
        ("nfw_concentration_prior", 0, 2, 2, "per-galaxy NFW with concentration prior"),
    ]
    set_names = ["all", "clean-high-rmse", "clean-protected", "weak-systematics-excluded"]
    score_rows: list[dict] = []
    cost_rows: list[dict] = []
    for model_id, global_params, per_galaxy_params, law_params, model_class in model_specs:
        for set_name in set_names:
            row = v18_competitor_summary_row(
                model_id,
                case_rows,
                set_name,
                global_params,
                per_galaxy_params,
                law_params,
                model_class,
            )
            score_rows.append(row)
            cost_rows.append(row.copy())

    high_rows = [row for row in case_rows if row["set"] == "clean-high-rmse"]
    protected_rows = [row for row in case_rows if row["set"] == "clean-protected"]
    high_win_rows = [
        {
            "galaxy": row["galaxy"],
            "lockedRoute": row["lockedRoute"],
            "winnerRawRmse": row["winnerRawRmse"],
            "canonicalRmse": row["canonical_mtsRmse"],
            "v18_10Rmse": row["v18_10_releaseRmse"],
            "mondFixedRmse": row["mond_fixed_a0Rmse"],
            "mondGlobalRmse": row["mond_global_a0Rmse"],
            "nfwPriorRmse": row["nfw_concentration_priorRmse"],
            "nfwFreeRmse": row["nfw_freeRmse"],
            "v18GainVsCanonicalPct": row["v18GainVsCanonicalPct"],
            "v18MinusMondGlobalKmS": row["v18MinusMondGlobalKmS"],
            "v18MinusNfwPriorKmS": row["v18MinusNfwPriorKmS"],
        }
        for row in high_rows
    ]
    protected_ledger = [
        {
            "galaxy": row["galaxy"],
            "lockedRoute": row["lockedRoute"],
            "canonicalRmse": row["canonical_mtsRmse"],
            "v18_10Rmse": row["v18_10_releaseRmse"],
            "v18ProtectedRegressionKmS": row["protectedV18RegressionKmS"],
            "mondGlobalRmse": row["mond_global_a0Rmse"],
            "nfwPriorRmse": row["nfw_concentration_priorRmse"],
            "winnerRawRmse": row["winnerRawRmse"],
        }
        for row in protected_rows
    ]
    score_by_model_clean = {row["modelId"]: row for row in score_rows if row["set"] == "all"}
    v18_all = score_by_model_clean["v18_10_release"]
    mond_global_all = score_by_model_clean["mond_global_a0"]
    nfw_prior_all = score_by_model_clean["nfw_concentration_prior"]
    verdict = (
        "v18.10 competitor benchmark ready"
        if lock_capsule["verdict"] == "v18.10 release candidate locked"
        and int(parse_float(lock_capsule["summary"]["weakSystematicsLeakage"], 1.0)) == 0
        else "v18.10 competitor benchmark blocked"
    )
    summary = {
        "analysisName": "mts-v18-competitor-benchmark-v1",
        "verdict": verdict,
        "lockedCandidate": "observed-state-response-v18.10-native-gated-release",
        "allGalaxyBaselineMean": lock_capsule["summary"]["allGalaxyLockedMtsMeanRmse"],
        "cleanBaselineMean": lock_capsule["summary"]["cleanSetLockedMtsMeanRmse"],
        "weakSystematicsLeakage": lock_capsule["summary"]["weakSystematicsLeakage"],
        "cleanHighGainPct": lock_capsule["summary"]["cleanHighGainPct"],
        "cleanGainPct": lock_capsule["summary"]["cleanGainPct"],
        "mondGlobalA0SI": mond_global_a0,
        "v18AllMeanRmse": v18_all["meanRmse"],
        "mondGlobalAllMeanRmse": mond_global_all["meanRmse"],
        "nfwPriorAllMeanRmse": nfw_prior_all["meanRmse"],
        "v18MinusMondGlobalAllMeanRmse": v18_all["meanRmse"] - mond_global_all["meanRmse"],
        "v18MinusNfwPriorAllMeanRmse": v18_all["meanRmse"] - nfw_prior_all["meanRmse"],
        "nfwFreeIsFlexibilityCeiling": True,
    }

    write_csv(out_dir / f"{prefix}_scores.csv", score_rows)
    write_csv(out_dir / f"{prefix}_case_ledger.csv", case_rows)
    write_csv(out_dir / f"{prefix}_model_costs.csv", cost_rows)
    write_csv(out_dir / f"{prefix}_high_rmse_wins.csv", high_win_rows)
    write_csv(out_dir / f"{prefix}_protected_ledger.csv", protected_ledger)
    write_csv(out_dir / f"{prefix}_mond_params.csv", mond_grid_rows + mond_param_rows)
    write_csv(out_dir / f"{prefix}_nfw_params.csv", nfw_param_rows)

    report = [
        "# MTS v18.15 Competitor Benchmark",
        "",
        "This benchmark keeps v18.10 locked and compares it against fixed and fitted MOND-style tracks plus per-galaxy NFW halo ceilings. It does not alter MTS.",
        "",
        "## Result",
        "",
        f"- Verdict: `{verdict}`.",
        f"- Locked v18.10 high-RMSE gain: `{fmt(parse_float(summary['cleanHighGainPct']))}%`.",
        f"- Locked v18.10 clean-set gain: `{fmt(parse_float(summary['cleanGainPct']))}%`.",
        f"- MOND train-only global a0: `{summary['mondGlobalA0SI']:.6e}` m/s^2.",
        f"- All-galaxy mean RMSE, v18.10: `{fmt(summary['v18AllMeanRmse'])}`.",
        f"- All-galaxy mean RMSE, MOND global a0: `{fmt(summary['mondGlobalAllMeanRmse'])}`.",
        f"- All-galaxy mean RMSE, NFW concentration prior: `{fmt(summary['nfwPriorAllMeanRmse'])}`.",
        "",
        "## Model Score Table",
        "",
        "| Model | Set | Mean RMSE | High gain vs canonical | High above 20 | AIC | BIC | Fitted params |",
        "| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: |",
    ]
    for row in score_rows:
        if row["set"] in {"all", "clean-high-rmse"}:
            report.append(
                f"| {row['modelId']} | {row['set']} | {fmt(row['meanRmse'])} | {fmt(row['highGainVsCanonicalPct'])}% | {row['highAbove20Count']} | {fmt(row['aic'])} | {fmt(row['bic'])} | {row['benchmarkFittedTotalParamsOnSet']} |"
            )
    report.extend(
        [
            "",
            "## Labels",
            "",
            "- `mond_per_galaxy_a0_oracle` is non-promotable because it fits one acceleration scale per galaxy.",
            "- `nfw_free` is a high-flexibility ΛCDM ceiling because it fits two halo parameters per galaxy.",
            "- `nfw_concentration_prior` is still a fitted halo comparison, but with a concentration prior included in the objective.",
            "- v18.10 uses no benchmark fitting in this mode; it is the locked native-gated expression.",
        ]
    )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report), encoding="utf-8")

    capsule = {
        "analysisName": summary["analysisName"],
        "verdict": verdict,
        "summary": summary,
        "outputFiles": [
            f"{prefix}_scores.csv",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_model_costs.csv",
            f"{prefix}_high_rmse_wins.csv",
            f"{prefix}_protected_ledger.csv",
            f"{prefix}_mond_params.csv",
            f"{prefix}_nfw_params.csv",
            f"{prefix}_report.md",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_v18competitorbenchmark(args: argparse.Namespace) -> None:
    if str(args.candidate_id or "").lower() in {"v18.35", "v18_35", "v1835", "v18lowvbarpolarity"}:
        out_dir = DEFAULT_OBSERVED_STATE_V18_35_COMPETITOR_BENCHMARK_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
        capsule = write_v18_35_competitor_benchmark_artifacts(out_dir)
        summary = capsule["summary"]
        print("MTS v18.35 competitor benchmark")
        print(f"verdict={capsule['verdict']}")
        print(
            "\t".join(
                [
                    f"v18_35_all={fmt(summary['v18_35AllMeanRmse'])}",
                    f"mond_global_all={fmt(summary['mondGlobalAllMeanRmse'])}",
                    f"nfw_prior_all={fmt(summary['nfwPriorAllMeanRmse'])}",
                    f"high_gain={fmt(parse_float(summary['v18_35HighGainPct']))}%",
                    f"protected={fmt(summary['protectedMaxRegressionVsV18_30KmS'])}",
                    f"release_successor={summary['releaseSuccessor']}",
                ]
            )
        )
        print(f"Wrote v18.35 competitor benchmark to {out_dir.resolve()}")
        return
    out_dir = DEFAULT_OBSERVED_STATE_V18_COMPETITOR_BENCHMARK_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_v18_competitor_benchmark_artifacts(out_dir)
    summary = capsule["summary"]
    print("MTS v18.15 competitor benchmark")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"v18_all={fmt(summary['v18AllMeanRmse'])}",
                f"mond_global_all={fmt(summary['mondGlobalAllMeanRmse'])}",
                f"nfw_prior_all={fmt(summary['nfwPriorAllMeanRmse'])}",
                f"a0_global={summary['mondGlobalA0SI']:.6e}",
                f"weak_leakage={summary['weakSystematicsLeakage']}",
            ]
        )
    )
    print(f"Wrote v18 competitor benchmark to {out_dir.resolve()}")


def v18_competitor_benchmark_v2_inputs() -> tuple[dict, list[dict], list[dict], list[dict], list[dict]]:
    gate_dir = DEFAULT_OBSERVED_STATE_V18_RELEASE_REPLACEMENT_GATE_OUT
    gate_capsule_path = gate_dir / "mts_v18_release_replacement_gate_capsule.json"
    gate_case_path = gate_dir / "mts_v18_release_replacement_gate_case_ledger.csv"
    if not gate_capsule_path.exists() or not gate_case_path.exists():
        gate_capsule = write_v18_release_replacement_gate_artifacts(gate_dir)
    else:
        gate_capsule = read_json_if_exists(gate_capsule_path)

    v1_dir = DEFAULT_OBSERVED_STATE_V18_COMPETITOR_BENCHMARK_OUT
    v1_case_path = v1_dir / "mts_v18_competitor_case_ledger.csv"
    if not v1_case_path.exists():
        write_v18_competitor_benchmark_artifacts(v1_dir)

    gate_rows = read_csv_rows(gate_case_path)
    competitor_rows = read_csv_rows(v1_case_path)
    mond_rows = read_csv_rows(v1_dir / "mts_v18_competitor_mond_params.csv")
    nfw_rows = read_csv_rows(v1_dir / "mts_v18_competitor_nfw_params.csv")
    return gate_capsule, gate_rows, competitor_rows, mond_rows, nfw_rows


def write_v18_competitor_benchmark_v2_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_v18_competitor_v2"
    gate_capsule, gate_rows, competitor_rows, mond_param_rows, nfw_param_rows = v18_competitor_benchmark_v2_inputs()
    gate_by_name = {row["galaxy"]: row for row in gate_rows}

    case_rows: list[dict] = []
    model_ids = [
        "baryon_fixed_ml",
        "canonical_mts",
        "v18_26_release",
        "v18_30_release",
        "mond_fixed_a0",
        "mond_global_a0",
        "mond_per_galaxy_a0_oracle",
        "nfw_free",
        "nfw_concentration_prior",
    ]
    for comp in competitor_rows:
        name = comp["galaxy"]
        gate = gate_by_name.get(name)
        if not gate:
            continue
        point_count = int(parse_float(comp.get("pointCount"), 0.0))
        v1826_rmse = parse_float(gate.get("v18_26Rmse"))
        v1830_rmse = parse_float(gate.get("v18_30Rmse"))
        scores_for_winner = []
        row = {
            "galaxy": name,
            "set": gate.get("set") or comp.get("set", ""),
            "split": gate.get("split") or comp.get("split", ""),
            "pointCount": point_count,
            "lockedRoute": gate.get("lockedRoute") or comp.get("lockedRoute", ""),
            "rOut": comp.get("rOut", ""),
            "h": comp.get("h", ""),
            "fGasOut": comp.get("fGasOut", ""),
            "memoryLoad": comp.get("memoryLoad", ""),
            "pocketTarget": gate.get("pocketTarget", ""),
            "branchHits": gate.get("branchHits", ""),
        }
        for model_id in model_ids:
            if model_id == "v18_26_release":
                rmse = v1826_rmse
                sse = rmse * rmse * point_count if math.isfinite(rmse) else math.nan
                chi2 = sse
                route = gate.get("lockedRoute", "")
            elif model_id == "v18_30_release":
                rmse = v1830_rmse
                sse = rmse * rmse * point_count if math.isfinite(rmse) else math.nan
                chi2 = sse
                route = gate.get("lockedRoute", "")
            else:
                rmse = parse_float(comp.get(f"{model_id}Rmse"))
                sse = parse_float(comp.get(f"{model_id}Sse"))
                chi2 = parse_float(comp.get(f"{model_id}Chi2"))
                route = comp.get(f"{model_id}Route", "")
            row[f"{model_id}Rmse"] = rmse
            row[f"{model_id}Sse"] = sse
            row[f"{model_id}Chi2"] = chi2
            row[f"{model_id}Route"] = route
            if math.isfinite(rmse):
                scores_for_winner.append((rmse, model_id))

        scores_for_winner.sort()
        winner_rmse, winner_model = scores_for_winner[0] if scores_for_winner else (math.nan, "")
        second_rmse, second_model = scores_for_winner[1] if len(scores_for_winner) > 1 else (math.nan, "")
        canonical_rmse = parse_float(row["canonical_mtsRmse"])
        mond_fixed = parse_float(row["mond_fixed_a0Rmse"])
        mond_global = parse_float(row["mond_global_a0Rmse"])
        nfw_prior = parse_float(row["nfw_concentration_priorRmse"])
        nfw_free = parse_float(row["nfw_freeRmse"])
        row.update(
            {
                "winnerRawRmse": winner_model,
                "winnerRmse": winner_rmse,
                "secondRawRmse": second_model,
                "secondRmse": second_rmse,
                "v18_30BeatsMondFixed": v1830_rmse < mond_fixed if math.isfinite(mond_fixed) else "",
                "v18_30BeatsMondGlobal": v1830_rmse < mond_global if math.isfinite(mond_global) else "",
                "v18_30BeatsNfwPrior": v1830_rmse < nfw_prior if math.isfinite(nfw_prior) else "",
                "v18_30BeatsNfwFree": v1830_rmse < nfw_free if math.isfinite(nfw_free) else "",
                "v18_30GainVsCanonicalKmS": canonical_rmse - v1830_rmse,
                "v18_30GainVsCanonicalPct": pct_improvement(canonical_rmse, v1830_rmse),
                "v18_30GainVsV18_26KmS": v1826_rmse - v1830_rmse,
                "v18_30GainVsV18_26Pct": pct_improvement(v1826_rmse, v1830_rmse),
                "v18_30MinusMondFixedKmS": v1830_rmse - mond_fixed if math.isfinite(mond_fixed) else math.nan,
                "v18_30MinusMondGlobalKmS": v1830_rmse - mond_global if math.isfinite(mond_global) else math.nan,
                "v18_30MinusNfwPriorKmS": v1830_rmse - nfw_prior if math.isfinite(nfw_prior) else math.nan,
                "v18_30MinusNfwFreeKmS": v1830_rmse - nfw_free if math.isfinite(nfw_free) else math.nan,
                "v18_30ProtectedRegressionVsCanonicalKmS": max(0.0, v1830_rmse - canonical_rmse) if row["set"] == "clean-protected" else "",
                "v18_30ProtectedRegressionVsV18_26KmS": parse_float(gate.get("protectedRegressionVsV18_26KmS"), 0.0) if row["set"] == "clean-protected" else "",
                "routeChangedVsV18_26": gate.get("routeChangedVsV18_26", ""),
                "weakSystematicsExcluded": gate.get("weakSystematicsExcluded", ""),
            }
        )
        case_rows.append(row)

    model_specs = [
        ("baryon_fixed_ml", 0, 0, 2, "fixed baryonic baseline"),
        ("canonical_mts", 0, 0, 4, "locked MTS law"),
        ("v18_26_release", 0, 0, 4, "locked MTS v18.26 release law"),
        ("v18_30_release", 0, 0, 4, "locked MTS v18.30 release law"),
        ("mond_fixed_a0", 0, 0, 1, "fixed MOND simple-interpolation law"),
        ("mond_global_a0", 1, 0, 1, "MOND one global train-fit parameter"),
        ("mond_per_galaxy_a0_oracle", 0, 1, 1, "per-galaxy MOND oracle"),
        ("nfw_free", 0, 2, 2, "per-galaxy NFW high-flexibility ceiling"),
        ("nfw_concentration_prior", 0, 2, 2, "per-galaxy NFW with concentration prior"),
    ]
    set_names = ["all", "clean-high-rmse", "clean-protected", "weak-systematics-excluded"]
    score_rows: list[dict] = []
    cost_rows: list[dict] = []
    for model_id, global_params, per_galaxy_params, law_params, model_class in model_specs:
        for set_name in set_names:
            row = v18_competitor_summary_row(
                model_id,
                case_rows,
                set_name,
                global_params,
                per_galaxy_params,
                law_params,
                model_class,
            )
            score_rows.append(row)
            cost_rows.append(row.copy())

    high_rows = [row for row in case_rows if row["set"] == "clean-high-rmse"]
    protected_rows = [row for row in case_rows if row["set"] == "clean-protected"]
    score_lookup = {(row["modelId"], row["set"]): row for row in score_rows}
    v1830_all = score_lookup[("v18_30_release", "all")]
    v1826_all = score_lookup[("v18_26_release", "all")]
    mond_global_all = score_lookup[("mond_global_a0", "all")]
    nfw_prior_all = score_lookup[("nfw_concentration_prior", "all")]
    v1830_high = score_lookup[("v18_30_release", "clean-high-rmse")]
    v1826_high = score_lookup[("v18_26_release", "clean-high-rmse")]
    v1830_clean_protected = score_lookup[("v18_30_release", "clean-protected")]

    high_win_rows = [
        {
            "galaxy": row["galaxy"],
            "lockedRoute": row["lockedRoute"],
            "winnerRawRmse": row["winnerRawRmse"],
            "canonicalRmse": row["canonical_mtsRmse"],
            "v18_26Rmse": row["v18_26_releaseRmse"],
            "v18_30Rmse": row["v18_30_releaseRmse"],
            "mondFixedRmse": row["mond_fixed_a0Rmse"],
            "mondGlobalRmse": row["mond_global_a0Rmse"],
            "nfwPriorRmse": row["nfw_concentration_priorRmse"],
            "nfwFreeRmse": row["nfw_freeRmse"],
            "v18_30GainVsCanonicalPct": row["v18_30GainVsCanonicalPct"],
            "v18_30GainVsV18_26KmS": row["v18_30GainVsV18_26KmS"],
            "v18_30MinusMondGlobalKmS": row["v18_30MinusMondGlobalKmS"],
            "v18_30MinusNfwPriorKmS": row["v18_30MinusNfwPriorKmS"],
        }
        for row in sorted(high_rows, key=lambda item: parse_float(item["v18_30_releaseRmse"], 0.0), reverse=True)
    ]
    protected_ledger = [
        {
            "galaxy": row["galaxy"],
            "lockedRoute": row["lockedRoute"],
            "canonicalRmse": row["canonical_mtsRmse"],
            "v18_26Rmse": row["v18_26_releaseRmse"],
            "v18_30Rmse": row["v18_30_releaseRmse"],
            "v18_30ProtectedRegressionVsCanonicalKmS": row["v18_30ProtectedRegressionVsCanonicalKmS"],
            "v18_30ProtectedRegressionVsV18_26KmS": row["v18_30ProtectedRegressionVsV18_26KmS"],
            "mondGlobalRmse": row["mond_global_a0Rmse"],
            "nfwPriorRmse": row["nfw_concentration_priorRmse"],
            "winnerRawRmse": row["winnerRawRmse"],
        }
        for row in protected_rows
    ]
    release_delta_rows = [
        {
            "galaxy": row["galaxy"],
            "set": row["set"],
            "split": row["split"],
            "lockedRoute": row["lockedRoute"],
            "v18_26Rmse": row["v18_26_releaseRmse"],
            "v18_30Rmse": row["v18_30_releaseRmse"],
            "gainVsV18_26KmS": row["v18_30GainVsV18_26KmS"],
            "gainVsV18_26Pct": row["v18_30GainVsV18_26Pct"],
            "pocketTarget": row["pocketTarget"],
            "branchHits": row["branchHits"],
            "routeChangedVsV18_26": row["routeChangedVsV18_26"],
        }
        for row in sorted(case_rows, key=lambda item: -parse_float(item["v18_30GainVsV18_26KmS"], 0.0))
        if abs(parse_float(row["v18_30GainVsV18_26KmS"], 0.0)) > 1e-9
    ]
    failure_delta_rows = [
        {
            "galaxy": row["galaxy"],
            "lockedRoute": row["lockedRoute"],
            "v18_30Rmse": row["v18_30_releaseRmse"],
            "mondGlobalRmse": row["mond_global_a0Rmse"],
            "nfwPriorRmse": row["nfw_concentration_priorRmse"],
            "nfwFreeRmse": row["nfw_freeRmse"],
            "v18_30MinusMondGlobalKmS": row["v18_30MinusMondGlobalKmS"],
            "v18_30MinusNfwPriorKmS": row["v18_30MinusNfwPriorKmS"],
            "winnerRawRmse": row["winnerRawRmse"],
            "pocketTarget": row["pocketTarget"],
            "branchHits": row["branchHits"],
        }
        for row in sorted(high_rows, key=lambda item: parse_float(item["v18_30MinusNfwPriorKmS"], -999.0), reverse=True)
    ]

    gate_summary = gate_capsule.get("summary", {})
    release_successor = parse_bool(gate_summary.get("releaseSuccessor"))
    weak_leakage = int(parse_float(gate_summary.get("weakSystematicsLeakage"), 1.0))
    protected_max = parse_float(gate_summary.get("protectedMaxRegressionVsV18_26KmS"), math.nan)
    high_above20 = int(parse_float(gate_summary.get("highAbove20"), 999.0))
    null_margin = parse_float(gate_summary.get("nullMarginTargetPct"), math.nan)
    verdict = (
        "v18.30 competitor benchmark ready"
        if gate_capsule.get("verdict") == "v18.30 replaces v18.26 as release candidate"
        and release_successor
        and weak_leakage == 0
        and protected_max == 0.0
        and high_above20 == 0
        and math.isfinite(null_margin)
        and null_margin >= 10.0
        else "v18.30 competitor benchmark blocked"
    )
    summary = {
        "analysisName": "mts-v18-competitor-benchmark-v2",
        "verdict": verdict,
        "lockedCandidate": "observed-state-response-v18.30-release-candidate",
        "allGalaxyBaselineMean": gate_summary.get("allGalaxyLockedMtsMeanRmse"),
        "cleanBaselineMean": gate_summary.get("cleanSetLockedMtsMeanRmse"),
        "weakSystematicsLeakage": weak_leakage,
        "v18_30HighGainPct": gate_summary.get("v18_30HighGainPct"),
        "v18_30CleanGainPct": gate_summary.get("v18_30CleanGainPct"),
        "v18_30HoldoutHighGainPct": gate_summary.get("v18_30HoldoutHighGainPct"),
        "v18_30HoldoutCleanGainPct": gate_summary.get("v18_30HoldoutCleanGainPct"),
        "targetGainVsV18_26Pct": gate_summary.get("targetGainVsV18_26Pct"),
        "targetGainVsV18_26KmS": gate_summary.get("targetGainVsV18_26KmS"),
        "nullMarginTargetPct": null_margin,
        "protectedMaxRegressionVsV18_26KmS": protected_max,
        "v18_30AllMeanRmse": v1830_all["meanRmse"],
        "v18_26AllMeanRmse": v1826_all["meanRmse"],
        "mondGlobalAllMeanRmse": mond_global_all["meanRmse"],
        "nfwPriorAllMeanRmse": nfw_prior_all["meanRmse"],
        "v18_30MinusV18_26AllMeanRmse": v1830_all["meanRmse"] - v1826_all["meanRmse"],
        "v18_30MinusMondGlobalAllMeanRmse": v1830_all["meanRmse"] - mond_global_all["meanRmse"],
        "v18_30MinusNfwPriorAllMeanRmse": v1830_all["meanRmse"] - nfw_prior_all["meanRmse"],
        "v18_30HighMeanRmse": v1830_high["highMeanRmse"],
        "v18_26HighMeanRmse": v1826_high["highMeanRmse"],
        "v18_30ProtectedMaxRegressionVsCanonicalKmS": v1830_clean_protected["maxProtectedRegressionKmS"],
        "nfwFreeIsFlexibilityCeiling": True,
    }

    write_csv(out_dir / f"{prefix}_scores.csv", score_rows)
    write_csv(out_dir / f"{prefix}_case_ledger.csv", case_rows)
    write_csv(out_dir / f"{prefix}_model_costs.csv", cost_rows)
    write_csv(out_dir / f"{prefix}_high_rmse_wins.csv", high_win_rows)
    write_csv(out_dir / f"{prefix}_protected_ledger.csv", protected_ledger)
    write_csv(out_dir / f"{prefix}_release_delta.csv", release_delta_rows)
    write_csv(out_dir / f"{prefix}_failure_delta.csv", failure_delta_rows)
    write_csv(out_dir / f"{prefix}_mond_params.csv", mond_param_rows)
    write_csv(out_dir / f"{prefix}_nfw_params.csv", nfw_param_rows)

    report = [
        "# MTS v18.30 Competitor Benchmark",
        "",
        "This benchmark keeps v18.30 locked and compares it against fixed/fitted MOND tracks plus per-galaxy NFW halo ceilings. It does not alter MTS.",
        "",
        "## Result",
        "",
        f"- Verdict: `{verdict}`.",
        f"- v18.30 high-RMSE gain: `{fmt(parse_float(summary['v18_30HighGainPct']))}%`.",
        f"- v18.30 clean-set gain: `{fmt(parse_float(summary['v18_30CleanGainPct']))}%`.",
        f"- v18.30 all-galaxy mean RMSE: `{fmt(summary['v18_30AllMeanRmse'])}`.",
        f"- v18.26 all-galaxy mean RMSE: `{fmt(summary['v18_26AllMeanRmse'])}`.",
        f"- MOND global-a0 all-galaxy mean RMSE: `{fmt(summary['mondGlobalAllMeanRmse'])}`.",
        f"- NFW concentration-prior all-galaxy mean RMSE: `{fmt(summary['nfwPriorAllMeanRmse'])}`.",
        f"- Target pocket gain over v18.26: `{fmt(parse_float(summary['targetGainVsV18_26Pct']))}%` / `{fmt(parse_float(summary['targetGainVsV18_26KmS']))}` km/s.",
        f"- Protected max regression vs v18.26: `{fmt(protected_max)}` km/s.",
        "",
        "## Model Score Table",
        "",
        "| Model | Set | Mean RMSE | High gain vs canonical | High above 20 | AIC | BIC | Fitted params |",
        "| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: |",
    ]
    for row in score_rows:
        if row["set"] in {"all", "clean-high-rmse"}:
            report.append(
                f"| {row['modelId']} | {row['set']} | {fmt(row['meanRmse'])} | {fmt(row['highGainVsCanonicalPct'])}% | {row['highAbove20Count']} | {fmt(row['aic'])} | {fmt(row['bic'])} | {row['benchmarkFittedTotalParamsOnSet']} |"
            )
    report.extend(
        [
            "",
            "## v18.30 Delta From v18.26",
            "",
            "| Galaxy | Set | v18.26 | v18.30 | Gain | Branch |",
            "| --- | --- | ---: | ---: | ---: | --- |",
        ]
    )
    for row in release_delta_rows[:20]:
        report.append(
            f"| {row['galaxy']} | {row['set']} | {fmt(row['v18_26Rmse'])} | {fmt(row['v18_30Rmse'])} | {fmt(row['gainVsV18_26KmS'])} | {row['branchHits']} |"
        )
    report.extend(
        [
            "",
            "## Labels",
            "",
            "- `mond_per_galaxy_a0_oracle` is non-promotable because it fits one acceleration scale per galaxy.",
            "- `nfw_free` is a high-flexibility halo ceiling because it fits two halo parameters per galaxy.",
            "- `nfw_concentration_prior` is still a fitted halo comparison, but with a concentration prior included in the objective.",
            "- v18.30 uses no benchmark fitting in this mode; it is the locked exact-cache/browser-gated release candidate.",
        ]
    )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report) + "\n", encoding="utf-8")

    capsule = {
        "analysisName": summary["analysisName"],
        "verdict": verdict,
        "summary": summary,
        "outputFiles": [
            f"{prefix}_scores.csv",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_model_costs.csv",
            f"{prefix}_high_rmse_wins.csv",
            f"{prefix}_protected_ledger.csv",
            f"{prefix}_release_delta.csv",
            f"{prefix}_failure_delta.csv",
            f"{prefix}_mond_params.csv",
            f"{prefix}_nfw_params.csv",
            f"{prefix}_report.md",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


