def v18_43_source_wide_ml_prior_rows() -> list[dict]:
    context = observed_state_candidate_context()
    supports_by_name = v18_39_remaining_nfw_gap_artifact_supports()
    benchmark_dir = DEFAULT_OBSERVED_STATE_V18_38_COMPETITOR_BENCHMARK_OUT
    benchmark_path = benchmark_dir / "mts_v18_38_competitor_case_ledger.csv"
    if not benchmark_path.exists():
        write_v18_38_competitor_benchmark_artifacts(benchmark_dir)
    benchmark_by_name = {row["galaxy"]: row for row in read_csv_rows(benchmark_path)}
    holdout_names = v18_36_nfw_gap_split_names()[1]
    rows: list[dict] = []
    for curve in context["curves"]:
        name = curve["name"]
        supports = supports_by_name.get(name, [])
        if not supports:
            continue
        base_score = v18_competitor_support_score(curve, supports)
        canonical = v18_competitor_support_score(curve, v18_competitor_canonical_supports(curve))
        set_label = v18_competitor_set_label(name, context["weakNames"], context["highNames"])
        split = "weak-excluded" if name in context["weakNames"] else "holdout" if name in holdout_names else "train"
        bench = benchmark_by_name.get(name, {})
        nfw_prior = parse_float(bench.get("nfw_concentration_priorRmse"), math.nan)
        for prior in V18_43_SOURCE_WIDE_ML_PRIORS:
            source_curve = transformed_curve(curve, ml_disk=prior["mlDisk"], ml_bulge=prior["mlBulge"])
            candidate = v18_competitor_support_score(source_curve, supports)
            regression = max(0.0, candidate["rmse"] - base_score["rmse"])
            rows.append(
                {
                    "galaxy": name,
                    "variantId": prior["variantId"],
                    "priorFamily": prior["priorFamily"],
                    "sourceBasis": prior["sourceBasis"],
                    "formulaRole": prior["formulaRole"],
                    "set": set_label,
                    "split": split,
                    "lockedRoute": curve.get("lockedModelRoute", ""),
                    "candidateRoute": candidate.get("candidateRoute", ""),
                    "routeChangedVsV18_38": candidate.get("candidateRoute", "") != base_score.get("candidateRoute", ""),
                    "remainingGapClassTarget": name in V18_40_REMAINING_GAP_CLASS_TARGETS,
                    "remainingGapTargetClass": v18_40_remaining_gap_class_target_label(name),
                    "canonicalRmse": canonical["rmse"],
                    "v18_38Rmse": base_score["rmse"],
                    "candidateRmse": candidate["rmse"],
                    "candidateGainVsV18_38KmS": base_score["rmse"] - candidate["rmse"],
                    "candidateGainVsV18_38Pct": pct_improvement(base_score["rmse"], candidate["rmse"]),
                    "candidateRegressionVsV18_38KmS": regression,
                    "nfwPriorRmse": nfw_prior,
                    "candidateMinusNfwPriorKmS": candidate["rmse"] - nfw_prior if math.isfinite(nfw_prior) else math.nan,
                    "mlDisk": prior["mlDisk"],
                    "mlBulge": prior["mlBulge"],
                    "perGalaxyMlInput": False,
                    "li2020HaloFitMlUsed": False,
                    "usableAsTransportLaw": False,
                    "above20Candidate": candidate["rmse"] >= 20.0 if set_label == "clean-high-rmse" else "",
                    "protectedRegressionVsV18_38KmS": regression if set_label == "clean-protected" else "",
                    "highRegressionVsV18_38KmS": regression if set_label == "clean-high-rmse" else "",
                }
            )
    rows.sort(key=lambda row: (row["variantId"], row["galaxy"]))
    return rows


def v18_43_source_wide_ml_prior_metric(rows: list[dict], variant_id: str, split: str = "all") -> dict:
    selected = [row for row in rows if row["variantId"] == variant_id and row["set"] != "weak-systematics-excluded"]
    if split != "all":
        selected = [row for row in selected if row.get("split") == split]
    high = [row for row in selected if row["set"] == "clean-high-rmse"]
    protected = [row for row in selected if row["set"] == "clean-protected"]
    targets = [row for row in high if parse_bool(row.get("remainingGapClassTarget"))]
    base_clean = safe_mean(parse_float(row["v18_38Rmse"]) for row in selected)
    cand_clean = safe_mean(parse_float(row["candidateRmse"]) for row in selected)
    base_high = safe_mean(parse_float(row["v18_38Rmse"]) for row in high)
    cand_high = safe_mean(parse_float(row["candidateRmse"]) for row in high)
    base_target = safe_mean(parse_float(row["v18_38Rmse"]) for row in targets)
    cand_target = safe_mean(parse_float(row["candidateRmse"]) for row in targets)
    protected_regs = [parse_float(row.get("protectedRegressionVsV18_38KmS"), 0.0) for row in protected]
    high_regs = [parse_float(row.get("highRegressionVsV18_38KmS"), 0.0) for row in high]
    return {
        "variantId": variant_id,
        "split": split,
        "cleanCount": len(selected),
        "highCount": len(high),
        "targetCount": len(targets),
        "protectedCount": len(protected),
        "cleanGainVsV18_38Pct": pct_improvement(base_clean, cand_clean),
        "highGainVsV18_38Pct": pct_improvement(base_high, cand_high),
        "targetGainVsV18_38Pct": pct_improvement(base_target, cand_target),
        "targetGainVsV18_38KmS": base_target - cand_target if math.isfinite(base_target) and math.isfinite(cand_target) else math.nan,
        "protectedMaxRegressionVsV18_38KmS": max(protected_regs or [0.0]),
        "protectedWorseOver3Count": sum(1 for value in protected_regs if value > 3.0),
        "highMaxRegressionVsV18_38KmS": max(high_regs or [0.0]),
        "highAbove20Count": sum(1 for row in high if parse_bool(row.get("above20Candidate"))),
        "routeChangedCount": sum(1 for row in selected if parse_bool(row.get("routeChangedVsV18_38"))),
    }


def v18_43_source_wide_ml_prior_target_best(rows: list[dict]) -> list[dict]:
    output: list[dict] = []
    target_names = sorted({row["galaxy"] for row in rows if parse_bool(row.get("remainingGapClassTarget"))})
    for name in target_names:
        case_rows = [row for row in rows if row["galaxy"] == name]
        if not case_rows:
            continue
        base = next((row for row in case_rows if row["variantId"] == "fixed-sparc-ml"), case_rows[0])
        best = min(case_rows, key=lambda row: parse_float(row["candidateRmse"], math.inf))
        output.append(
            {
                "galaxy": name,
                "targetClass": base.get("remainingGapTargetClass", ""),
                "split": base.get("split", ""),
                "lockedRoute": base.get("lockedRoute", ""),
                "v18_38Rmse": base["v18_38Rmse"],
                "bestVariantId": best["variantId"],
                "bestPriorFamily": best["priorFamily"],
                "bestMlDisk": best["mlDisk"],
                "bestMlBulge": best["mlBulge"],
                "bestRmse": best["candidateRmse"],
                "bestGainVsV18_38KmS": parse_float(base["v18_38Rmse"]) - parse_float(best["candidateRmse"]),
                "bestGainVsV18_38Pct": pct_improvement(parse_float(base["v18_38Rmse"]), parse_float(best["candidateRmse"])),
                "nfwPriorRmse": base["nfwPriorRmse"],
                "perGalaxyMlInput": False,
            }
        )
    return output


def v18_43_source_wide_ml_prior_null_controls() -> list[dict]:
    rows: list[dict] = []
    base_priors = [prior for prior in V18_43_SOURCE_WIDE_ML_PRIORS if prior["variantId"] != "fixed-sparc-ml"]
    for seed in V18_43_SOURCE_WIDE_ML_NULL_SEEDS:
        rng = random.Random(seed)
        null_prior = {
            "variantId": f"random-sourcewide-ml-{seed}",
            "mlDisk": rng.uniform(0.45, 0.60),
            "mlBulge": rng.uniform(0.60, 0.84),
            "priorFamily": "random bounded source-wide M/L null",
            "sourceBasis": "same source-wide bounded M/L box as v18.43 candidate priors",
            "formulaRole": "null control",
        }
        original = V18_43_SOURCE_WIDE_ML_PRIORS[:]
        try:
            V18_43_SOURCE_WIDE_ML_PRIORS[:] = [original[0], null_prior]
            null_rows = v18_43_source_wide_ml_prior_rows()
        finally:
            V18_43_SOURCE_WIDE_ML_PRIORS[:] = original
        metric = v18_43_source_wide_ml_prior_metric(null_rows, null_prior["variantId"], "all")
        rows.append(
            {
                "nullType": "random-source-wide-ml-prior",
                "seed": seed,
                "mlDisk": null_prior["mlDisk"],
                "mlBulge": null_prior["mlBulge"],
                **metric,
            }
        )
    for prior in base_priors:
        coherent_peer = {
            "variantId": f"axis-swapped-{prior['variantId']}",
            "mlDisk": min(0.60, max(0.45, ML_DISK - (prior["mlDisk"] - ML_DISK))),
            "mlBulge": min(0.84, max(0.60, ML_BULGE - (prior["mlBulge"] - ML_BULGE))),
            "priorFamily": "axis-swapped source-wide M/L null",
            "sourceBasis": "opposite bounded direction from a tested source-wide prior",
            "formulaRole": "null control",
        }
        original = V18_43_SOURCE_WIDE_ML_PRIORS[:]
        try:
            V18_43_SOURCE_WIDE_ML_PRIORS[:] = [original[0], coherent_peer]
            null_rows = v18_43_source_wide_ml_prior_rows()
        finally:
            V18_43_SOURCE_WIDE_ML_PRIORS[:] = original
        metric = v18_43_source_wide_ml_prior_metric(null_rows, coherent_peer["variantId"], "all")
        rows.append(
            {
                "nullType": "axis-swapped-source-wide-ml-prior",
                "seed": "",
                "mlDisk": coherent_peer["mlDisk"],
                "mlBulge": coherent_peer["mlBulge"],
                **metric,
            }
        )
    rows.sort(key=lambda row: (row["nullType"], str(row["seed"]), row["variantId"]))
    return rows


def write_v18_source_wide_ml_prior_stress_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_v18_43_source_wide_ml_prior_stress"
    rows = v18_43_source_wide_ml_prior_rows()
    variant_ids = [prior["variantId"] for prior in V18_43_SOURCE_WIDE_ML_PRIORS]
    score_rows: list[dict] = []
    for variant_id in variant_ids:
        for split in ["all", "train", "holdout"]:
            score_rows.append(v18_43_source_wide_ml_prior_metric(rows, variant_id, split))
    candidate_scores = [row for row in score_rows if row["variantId"] != "fixed-sparc-ml" and row["split"] == "all"]
    best_score = max(
        candidate_scores,
        key=lambda row: (
            parse_float(row["targetGainVsV18_38Pct"], -999.0)
            - 3.0 * max(0.0, parse_float(row["protectedMaxRegressionVsV18_38KmS"], 0.0) - 3.0)
            - 0.5 * parse_float(row["highAbove20Count"], 0.0)
        ),
    )
    best_variant_id = best_score["variantId"]
    best_variant = next(prior for prior in V18_43_SOURCE_WIDE_ML_PRIORS if prior["variantId"] == best_variant_id)
    best_holdout = v18_43_source_wide_ml_prior_metric(rows, best_variant_id, "holdout")
    target_rows = [row for row in rows if row["variantId"] == best_variant_id and parse_bool(row.get("remainingGapClassTarget"))]
    target_best_rows = v18_43_source_wide_ml_prior_target_best(rows)
    protected_rows = [
        row
        for row in rows
        if row["variantId"] == best_variant_id and row["set"] == "clean-protected" and parse_float(row.get("protectedRegressionVsV18_38KmS"), 0.0) > 0.0
    ]
    null_rows = v18_43_source_wide_ml_prior_null_controls()
    best_null_target_gain = max((parse_float(row.get("targetGainVsV18_38Pct"), -999.0) for row in null_rows), default=math.nan)
    null_margin = parse_float(best_score["targetGainVsV18_38Pct"]) - best_null_target_gain if math.isfinite(best_null_target_gain) else math.nan
    if parse_float(best_score["targetGainVsV18_38Pct"]) >= 5.0 and parse_float(best_score["protectedMaxRegressionVsV18_38KmS"]) <= 3.0 and parse_float(best_score["highGainVsV18_38Pct"]) >= 0.0 and parse_float(best_score["highAbove20Count"]) == 0:
        verdict = "source-wide M/L prior explains remaining gap safely"
    elif parse_float(best_score["targetGainVsV18_38Pct"]) > 0.0 and parse_float(best_score["protectedMaxRegressionVsV18_38KmS"]) <= 3.0:
        verdict = "source-wide M/L prior helps individual cases only"
    elif parse_float(best_score["targetGainVsV18_38Pct"]) > 0.0:
        verdict = "source-wide M/L prior unsafe"
    else:
        verdict = "source-wide M/L prior not explanatory"
    summary = {
        "analysisName": "mts-v18-43-source-wide-ml-prior-stress-v1",
        "verdict": verdict,
        "baseLaw": "locked v18.38 support field",
        "formulaChanged": False,
        "browserChanged": False,
        "perGalaxyMlInputsUsed": False,
        "li2020HaloFitMlUsed": False,
        "variantCount": len(V18_43_SOURCE_WIDE_ML_PRIORS),
        "bestVariantId": best_variant_id,
        "bestMlDisk": best_variant["mlDisk"],
        "bestMlBulge": best_variant["mlBulge"],
        "bestTargetGainPct": best_score["targetGainVsV18_38Pct"],
        "bestTargetGainKmS": best_score["targetGainVsV18_38KmS"],
        "bestHighGainPct": best_score["highGainVsV18_38Pct"],
        "bestCleanGainPct": best_score["cleanGainVsV18_38Pct"],
        "bestProtectedMaxRegressionKmS": best_score["protectedMaxRegressionVsV18_38KmS"],
        "bestProtectedWorseOver3Count": best_score["protectedWorseOver3Count"],
        "bestHighAbove20Count": best_score["highAbove20Count"],
        "bestRouteChangedCount": best_score["routeChangedCount"],
        "holdoutTargetGainPct": best_holdout["targetGainVsV18_38Pct"],
        "holdoutTargetGainKmS": best_holdout["targetGainVsV18_38KmS"],
        "bestNullTargetGainPct": best_null_target_gain,
        "nullMarginPct": null_margin,
        "weakSystematicsLeakage": 0,
    }
    formula = {
        "candidate": "v18.43 source-wide M/L prior stress",
        "baseLaw": "v18.38 remains locked",
        "lawChange": "none",
        "testedOperation": "recompute baryonic curve with source-wide mlDisk/mlBulge prior, then reuse locked v18.38 support field",
        "bestVariant": best_variant,
        "priors": V18_43_SOURCE_WIDE_ML_PRIORS,
        "forbiddenInputs": ["galaxy name", "raw RMSE", "residual lookup", "NFW parameters", "Li+ per-galaxy halo-fit M/L", "weak/systematics training"],
    }
    write_csv(out_dir / f"{prefix}_scores.csv", score_rows)
    write_csv(out_dir / f"{prefix}_case_ledger.csv", rows)
    write_csv(out_dir / f"{prefix}_target_ledger.csv", target_rows)
    write_csv(out_dir / f"{prefix}_target_best.csv", target_best_rows)
    write_csv(out_dir / f"{prefix}_protected_ledger.csv", protected_rows)
    write_csv(out_dir / f"{prefix}_null_controls.csv", null_rows)
    write_csv(out_dir / f"{prefix}_variant_grid.csv", V18_43_SOURCE_WIDE_ML_PRIORS)
    (out_dir / f"{prefix}_formula.json").write_text(json.dumps(json_clean(formula), indent=2, sort_keys=True), encoding="utf-8")
    report = [
        "# MTS v18.43 Source-Wide M/L Prior Stress",
        "",
        "This is a bounded M/L provenance stress test, not a framework law change. It uses only source-wide stellar M/L priors and rejects per-galaxy halo-fit M/L values as formula inputs.",
        "",
        f"- Verdict: `{verdict}`.",
        f"- Best source-wide prior: `{best_variant_id}` (`mlDisk={fmt(best_variant['mlDisk'])}`, `mlBulge={fmt(best_variant['mlBulge'])}`).",
        f"- Remaining target gain: `{fmt(parse_float(best_score['targetGainVsV18_38Pct']))}%` / `{fmt(parse_float(best_score['targetGainVsV18_38KmS']))}` km/s.",
        f"- Holdout remaining target gain: `{fmt(parse_float(best_holdout['targetGainVsV18_38Pct']))}%` / `{fmt(parse_float(best_holdout['targetGainVsV18_38KmS']))}` km/s.",
        f"- Clean high-RMSE gain: `{fmt(parse_float(best_score['highGainVsV18_38Pct']))}%`.",
        f"- Clean-set gain: `{fmt(parse_float(best_score['cleanGainVsV18_38Pct']))}%`.",
        f"- Protected max regression: `{fmt(parse_float(best_score['protectedMaxRegressionVsV18_38KmS']))}` km/s.",
        f"- Protected cases worse by more than 3 km/s: `{best_score['protectedWorseOver3Count']}`.",
        f"- High-RMSE cases above 20 km/s: `{best_score['highAbove20Count']}`.",
        f"- Best bounded random/null target gain: `{fmt(best_null_target_gain)}%`; margin `{fmt(null_margin)}` points.",
        "",
        "## Target Cases",
        "",
        "| Galaxy | class | v18.38 | best source-wide prior | M/L disk | M/L bulge | best RMSE | gain |",
        "| --- | --- | ---: | --- | ---: | ---: | ---: | ---: |",
    ]
    for row in target_best_rows:
        report.append(
            f"| {row['galaxy']} | {row['targetClass']} | {fmt(row['v18_38Rmse'])} | {row['bestVariantId']} | {fmt(row['bestMlDisk'])} | {fmt(row['bestMlBulge'])} | {fmt(row['bestRmse'])} | {fmt(row['bestGainVsV18_38KmS'])} |"
        )
    report.extend(
        [
            "",
            "## Guard",
            "",
            "A source-wide M/L prior can diagnose whether the remaining gap is sensitive to normal stellar-population assumptions. It cannot become a per-galaxy fitting law, and it does not replace the locked v18.38/v18 release candidate unless a later framework test explicitly passes protected/null gates.",
            "",
            verdict,
        ]
    )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report) + "\n", encoding="utf-8")
    capsule = {
        "analysisName": summary["analysisName"],
        "verdict": verdict,
        "summary": summary,
        "outputFiles": [
            f"{prefix}_scores.csv",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_target_ledger.csv",
            f"{prefix}_target_best.csv",
            f"{prefix}_protected_ledger.csv",
            f"{prefix}_null_controls.csv",
            f"{prefix}_variant_grid.csv",
            f"{prefix}_formula.json",
            f"{prefix}_report.md",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_v18sourcewidemlpriorstress(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_OBSERVED_STATE_V18_SOURCE_WIDE_ML_PRIOR_STRESS_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_v18_source_wide_ml_prior_stress_artifacts(out_dir)
    summary = capsule["summary"]
    print("MTS v18.43 source-wide M/L prior stress")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"best={summary['bestVariantId']}",
                f"target_gain={fmt(parse_float(summary['bestTargetGainPct']))}%",
                f"target_gain_kms={fmt(parse_float(summary['bestTargetGainKmS']))}",
                f"high_gain={fmt(parse_float(summary['bestHighGainPct']))}%",
                f"protected={fmt(parse_float(summary['bestProtectedMaxRegressionKmS']))}",
                f"null_margin={fmt(parse_float(summary['nullMarginPct']))}",
                f"above20={summary['bestHighAbove20Count']}",
            ]
        )
    )
    print(f"Wrote v18.43 source-wide M/L prior stress to {out_dir.resolve()}")


def v18_48_ml_provenance_closure_rows(
    li_best_rows: list[dict],
    independent_case_rows: list[dict],
    sourcewide_best_rows: list[dict],
    v47_target_rows: list[dict],
) -> tuple[list[dict], list[dict]]:
    li_by_name = {row["galaxy"]: row for row in li_best_rows}
    independent_by_name = {row["galaxy"]: row for row in independent_case_rows}
    sourcewide_by_name = {row["galaxy"]: row for row in sourcewide_best_rows}
    v47_by_name = {row["galaxy"]: row for row in v47_target_rows}
    case_rows: list[dict] = []
    next_rows: list[dict] = []
    for name in V18_42_INDEPENDENT_ML_TARGETS:
        li = li_by_name.get(name, {})
        independent = independent_by_name.get(name, {})
        sourcewide = sourcewide_by_name.get(name, {})
        v47 = v47_by_name.get(name, {})
        li_gain = parse_float(li.get("bestGainVsV18_38KmS"), 0.0)
        sourcewide_gain = parse_float(sourcewide.get("bestGainVsV18_38KmS"), 0.0)
        usable_independent = int(parse_float(independent.get("usableIndependentCandidateCount"), 0.0))
        sourcewide_method = int(parse_float(independent.get("sourceWideMethodCount"), 0.0))
        fitted_count = int(parse_float(independent.get("rejectedFittedMlCount"), 0.0))
        v47_gain = parse_float(v47.get("candidateGainVsV18_38KmS"), 0.0)
        best_available_gain = max(li_gain, sourcewide_gain, v47_gain)
        if usable_independent > 0:
            verdict = "independent numeric M/L rescore candidate"
            driver = "independent per-galaxy M/L table"
            next_action = "manual-confirm source context, then run fixed-value M/L rescore outside the transport formula"
            framework_class = "mass-model convention test ready"
        elif li_gain >= 1.0 and sourcewide_gain < 1.0:
            verdict = "halo-fit M/L explains gap only"
            driver = "Li+ halo-fit Ydisk/Ybul"
            next_action = "do not put fitted M/L into MTS; classify as competitor/provenance gap"
            framework_class = "mass-model/provenance driven"
        elif v47_gain >= 1.0 and v47_gain >= sourcewide_gain + 0.5 and v47_gain >= li_gain + 0.5:
            verdict = "state/anatomy branch stronger than M/L"
            driver = "v18.47 compact bulge anatomy"
            next_action = "keep branch as named NFW-gap anatomy; seek provenance for protected analogues"
            framework_class = "framework-anatomy facing"
        elif sourcewide_gain >= 1.0:
            verdict = "source-wide M/L prior moves gap"
            driver = "source-wide stellar population prior"
            next_action = "test only as global observational prior, not per-galaxy repair"
            framework_class = "source-wide mass-model sensitivity"
        elif best_available_gain >= 0.5:
            verdict = "weak M/L/provenance sensitivity"
            driver = "mixed weak evidence"
            next_action = "do not tune formula; carry as low-priority provenance note"
            framework_class = "weak provenance sensitivity"
        else:
            verdict = "not explained by current M/L evidence"
            driver = "none"
            next_action = "treat remaining gap as fitted-halo flexibility or missing state/provenance"
            framework_class = "not M/L driven"
        case_rows.append(
            {
                "galaxy": name,
                "targetClass": li.get("targetClass", sourcewide.get("targetClass", v18_40_remaining_gap_class_target_label(name))),
                "lockedRoute": sourcewide.get("lockedRoute", ""),
                "v18_38Rmse": li.get("v18_38Rmse", sourcewide.get("v18_38Rmse", "")),
                "li2020BestVariant": li.get("bestVariantId", ""),
                "li2020BestYdisk": parse_float(li.get("bestYdisk"), math.nan),
                "li2020BestYbul": parse_float(li.get("bestYbul"), math.nan),
                "li2020BestGainKmS": li_gain,
                "sourceWideBestVariant": sourcewide.get("bestVariantId", ""),
                "sourceWideBestMlDisk": parse_float(sourcewide.get("bestMlDisk"), math.nan),
                "sourceWideBestMlBulge": parse_float(sourcewide.get("bestMlBulge"), math.nan),
                "sourceWideBestGainKmS": sourcewide_gain,
                "independentUsableMlCount": usable_independent,
                "independentSourceWideMethodCount": sourcewide_method,
                "independentRejectedFittedMlCount": fitted_count,
                "independentVerdict": independent.get("verdict", ""),
                "v18_47GainKmS": v47_gain,
                "bestAvailableGainKmS": best_available_gain,
                "primaryDriver": driver,
                "closureVerdict": verdict,
                "frameworkClass": framework_class,
                "nextAction": next_action,
            }
        )
        next_rows.append(
            {
                "galaxy": name,
                "priority": "high" if verdict in {"independent numeric M/L rescore candidate", "source-wide M/L prior moves gap", "state/anatomy branch stronger than M/L"} else "medium" if best_available_gain >= 0.5 else "low",
                "testType": framework_class,
                "specificNextStep": next_action,
                "doNotDo": "do not use fitted halo M/L, NFW parameters, raw residuals, or galaxy-name branches as MTS formula inputs",
            }
        )
    return case_rows, next_rows


def write_v18_ml_provenance_closure_artifacts(out_dir: Path, source_cache: Path, offline: bool) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    source_cache.mkdir(parents=True, exist_ok=True)
    prefix = "mts_v18_48_ml_provenance_closure"

    v41_dir = DEFAULT_OBSERVED_STATE_V18_REMAINING_ML_GAP_TEST_OUT
    v42_dir = DEFAULT_OBSERVED_STATE_V18_INDEPENDENT_ML_SOURCE_HUNT_OUT
    v43_dir = DEFAULT_OBSERVED_STATE_V18_SOURCE_WIDE_ML_PRIOR_STRESS_OUT
    v47_dir = DEFAULT_OBSERVED_STATE_V18_BULGE_COUPLING_DISCRIMINATOR_OUT
    if not (v41_dir / "mts_v18_41_remaining_ml_gap_target_best_oracle.csv").exists():
        write_v18_remaining_ml_gap_test_artifacts(v41_dir, DEFAULT_OBSERVED_STATE_V18_ML_CATALOG_BENCHMARK_CACHE, offline)
    if not (v42_dir / "mts_v18_42_independent_ml_source_hunt_case_verdicts.csv").exists():
        write_v18_independent_ml_source_hunt_artifacts(v42_dir, source_cache, offline)
    if not (v43_dir / "mts_v18_43_source_wide_ml_prior_stress_target_best.csv").exists():
        write_v18_source_wide_ml_prior_stress_artifacts(v43_dir)
    if not (v47_dir / "mts_v18_47_bulge_coupling_discriminator_target_ledger.csv").exists():
        write_v18_bulge_coupling_discriminator_artifacts(v47_dir)

    li_best_rows = read_csv_rows(v41_dir / "mts_v18_41_remaining_ml_gap_target_best_oracle.csv")
    li_source_value_rows = read_csv_rows(v41_dir / "mts_v18_41_remaining_ml_gap_source_values.csv")
    independent_case_rows = read_csv_rows(v42_dir / "mts_v18_42_independent_ml_source_hunt_case_verdicts.csv")
    independent_evidence_rows = read_csv_rows(v42_dir / "mts_v18_42_independent_ml_source_hunt_evidence_table.csv")
    sourcewide_best_rows = read_csv_rows(v43_dir / "mts_v18_43_source_wide_ml_prior_stress_target_best.csv")
    sourcewide_scores = read_csv_rows(v43_dir / "mts_v18_43_source_wide_ml_prior_stress_scores.csv")
    v47_target_rows = read_csv_rows(v47_dir / "mts_v18_47_bulge_coupling_discriminator_target_ledger.csv")

    case_rows, next_rows = v18_48_ml_provenance_closure_rows(li_best_rows, independent_case_rows, sourcewide_best_rows, v47_target_rows)
    source_values = [row for row in li_source_value_rows if row.get("galaxy") in set(V18_42_INDEPENDENT_ML_TARGETS)]
    evidence_rows = [row for row in independent_evidence_rows if row.get("galaxy") in set(V18_42_INDEPENDENT_ML_TARGETS)]
    sourcewide_best_score = max(
        [row for row in sourcewide_scores if row.get("split") == "all" and row.get("variantId") != "fixed-sparc-ml"],
        key=lambda row: parse_float(row.get("targetGainVsV18_38Pct"), -999.0),
        default={},
    )
    verdict_counts: dict[str, int] = {}
    for row in case_rows:
        verdict_counts[row["closureVerdict"]] = verdict_counts.get(row["closureVerdict"], 0) + 1
    if verdict_counts.get("independent numeric M/L rescore candidate", 0) > 0:
        verdict = "external M/L rescore ready for subset"
    elif verdict_counts.get("source-wide M/L prior moves gap", 0) >= 3:
        verdict = "remaining gap partly source-wide M/L sensitive"
    elif verdict_counts.get("halo-fit M/L explains gap only", 0) >= 3:
        verdict = "remaining gap mostly halo-fit provenance sensitivity"
    else:
        verdict = "remaining gap not closed by numeric M/L evidence"
    scores = [
        {"metric": "targetCount", "value": len(case_rows)},
        {"metric": "independentUsableCaseCount", "value": sum(1 for row in case_rows if int(row["independentUsableMlCount"]) > 0)},
        {"metric": "haloFitMlOnlyCaseCount", "value": verdict_counts.get("halo-fit M/L explains gap only", 0)},
        {"metric": "sourceWideMlSensitiveCaseCount", "value": verdict_counts.get("source-wide M/L prior moves gap", 0)},
        {"metric": "stateAnatomyStrongerThanMlCount", "value": verdict_counts.get("state/anatomy branch stronger than M/L", 0)},
        {"metric": "notMlDrivenCaseCount", "value": verdict_counts.get("not explained by current M/L evidence", 0)},
        {"metric": "bestSourceWideVariant", "value": sourcewide_best_score.get("variantId", "")},
        {"metric": "bestSourceWideTargetGainPct", "value": sourcewide_best_score.get("targetGainVsV18_38Pct", "")},
        {"metric": "weakSystematicsLeakage", "value": 0},
        {"metric": "lawChanged", "value": False},
    ]
    source_files = [
        {
            "stage": "v18.41 remaining M/L provenance gap test",
            "path": str((v41_dir / "mts_v18_41_remaining_ml_gap_target_best_oracle.csv").resolve()),
            "sha256": file_sha256(v41_dir / "mts_v18_41_remaining_ml_gap_target_best_oracle.csv"),
        },
        {
            "stage": "v18.41 numeric Li+ source values",
            "path": str((v41_dir / "mts_v18_41_remaining_ml_gap_source_values.csv").resolve()),
            "sha256": file_sha256(v41_dir / "mts_v18_41_remaining_ml_gap_source_values.csv"),
        },
        {
            "stage": "v18.42 independent M/L source hunt",
            "path": str((v42_dir / "mts_v18_42_independent_ml_source_hunt_case_verdicts.csv").resolve()),
            "sha256": file_sha256(v42_dir / "mts_v18_42_independent_ml_source_hunt_case_verdicts.csv"),
        },
        {
            "stage": "v18.43 source-wide M/L prior stress",
            "path": str((v43_dir / "mts_v18_43_source_wide_ml_prior_stress_target_best.csv").resolve()),
            "sha256": file_sha256(v43_dir / "mts_v18_43_source_wide_ml_prior_stress_target_best.csv"),
        },
        {
            "stage": "v18.47 named NFW-gap anatomy branch",
            "path": str((v47_dir / "mts_v18_47_bulge_coupling_discriminator_target_ledger.csv").resolve()),
            "sha256": file_sha256(v47_dir / "mts_v18_47_bulge_coupling_discriminator_target_ledger.csv"),
        },
    ]

    write_csv(out_dir / f"{prefix}_scores.csv", scores)
    write_csv(out_dir / f"{prefix}_case_ledger.csv", case_rows)
    write_csv(out_dir / f"{prefix}_source_value_ledger.csv", source_values)
    write_csv(out_dir / f"{prefix}_source_evidence_ledger.csv", evidence_rows)
    write_csv(out_dir / f"{prefix}_next_tests.csv", next_rows)
    write_csv(out_dir / f"{prefix}_source_files.csv", source_files)
    capsule = {
        "analysisName": "mts-v18-48-ml-provenance-closure-v1",
        "verdict": verdict,
        "targetCount": len(case_rows),
        "verdictCounts": verdict_counts,
        "lawChanged": False,
        "browserChanged": False,
        "weakSystematicsLeakage": 0,
        "outputFiles": [
            f"{prefix}_scores.csv",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_source_value_ledger.csv",
            f"{prefix}_source_evidence_ledger.csv",
            f"{prefix}_next_tests.csv",
            f"{prefix}_source_files.csv",
            f"{prefix}_report.md",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    report = [
        "# MTS v18.48 M/L Provenance Closure",
        "",
        "This pass closes the numeric M/L question for the current remaining NFW-gap cases. It does not change MTS, v18.38, v18.47, q, Gamma0, browser code, or any transport formula.",
        "",
        f"- Verdict: `{verdict}`.",
        f"- Targets: `{len(case_rows)}`.",
        f"- Independent usable per-galaxy M/L cases: `{sum(1 for row in case_rows if int(row['independentUsableMlCount']) > 0)}`.",
        f"- Halo-fit M/L only cases: `{verdict_counts.get('halo-fit M/L explains gap only', 0)}`.",
        f"- Source-wide M/L sensitive cases: `{verdict_counts.get('source-wide M/L prior moves gap', 0)}`.",
        f"- State/anatomy stronger than M/L cases: `{verdict_counts.get('state/anatomy branch stronger than M/L', 0)}`.",
        f"- Not M/L driven cases: `{verdict_counts.get('not explained by current M/L evidence', 0)}`.",
        "",
        "## Case Decisions",
        "",
        "| Galaxy | class | Li+ gain | Li+ Ydisk/Ybul | source-wide gain | v18.47 gain | closure verdict | next action |",
        "| --- | --- | ---: | --- | ---: | ---: | --- | --- |",
    ]
    for row in case_rows:
        report.append(
            f"| {row['galaxy']} | {row['targetClass']} | {fmt(row['li2020BestGainKmS'])} | {fmt(row['li2020BestYdisk'])}/{fmt(row['li2020BestYbul'])} | {fmt(row['sourceWideBestGainKmS'])} | {fmt(row['v18_47GainKmS'])} | {row['closureVerdict']} | {row['nextAction']} |"
        )
    report.extend(
        [
            "",
            "## Rule",
            "",
            "Numeric Li+ Ydisk/Ybul values are real per-galaxy values, but they come from halo-model fitting and remain provenance/competitor evidence, not MTS formula inputs. Independent case-specific photometric/population M/L values would be eligible for a fixed-value rescore, but the current source hunt found none for these targets.",
            "",
            verdict,
        ]
    )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report) + "\n", encoding="utf-8")
    return capsule


def cmd_v18mlprovenanceclosure(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_OBSERVED_STATE_V18_ML_PROVENANCE_CLOSURE_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    source_cache = Path(args.source_cache) if args.source_cache else DEFAULT_OBSERVED_STATE_V18_INDEPENDENT_ML_SOURCE_HUNT_CACHE
    capsule = write_v18_ml_provenance_closure_artifacts(out_dir, source_cache, args.offline)
    print("MTS v18.48 M/L provenance closure")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"targets={capsule['targetCount']}",
                f"independent={capsule['verdictCounts'].get('independent numeric M/L rescore candidate', 0)}",
                f"halo_fit_only={capsule['verdictCounts'].get('halo-fit M/L explains gap only', 0)}",
                f"source_wide={capsule['verdictCounts'].get('source-wide M/L prior moves gap', 0)}",
                f"anatomy={capsule['verdictCounts'].get('state/anatomy branch stronger than M/L', 0)}",
                f"not_ml={capsule['verdictCounts'].get('not explained by current M/L evidence', 0)}",
            ]
        )
    )
    print(f"Wrote v18.48 M/L provenance closure to {out_dir.resolve()}")


V18_49_NON_ML_GAP_TARGETS = {"NGC4100", "F568-1", "ESO116-G012", "UGC04325", "UGC06983", "NGC5985"}
V18_49_BRANCHES = ["gasRichLowloadOuterLift", "massiveLowgasLowloadShelf", "bufferedGasrichCompactLift"]
V18_49_BETA_GRID = [-0.24, -0.16, -0.08, 0.0, 0.08, 0.16, 0.24]
V18_49_NULL_SEEDS = [20260691, 20260692, 20260693, 20260694, 20260695, 20260696, 20260697, 20260698, 20260699]


def v18_49_non_ml_gap_activations(curve: dict, values: dict, mass: dict) -> dict[str, float]:
    route = curve.get("lockedModelRoute", "")
    memory = parse_float(curve.get("memoryLoad"), 0.0)
    u_out = parse_float(curve.get("lockedModelUOut"), 0.0)
    u_max = parse_float(curve.get("lockedModelUMax"), 0.0)
    f_gas = parse_float(mass.get("tableGasFraction"), 0.0)
    mbar = parse_float(mass.get("mBar_1e9Msun"), 0.0)
    h_over = parse_float(values.get("hOverRout"), 0.0)
    point_density = parse_float(values.get("pointDensity"), 0.0)
    bar_curv_abs = abs(parse_float(values.get("barCurv"), 0.0))
    outer_gas = parse_float(values.get("outerGasShare"), 0.0)
    lowload = 1.0 if route == "low-load" else 0.0
    buffered = 1.0 if route == "buffered single-crossing" else 0.0
    gas_rich_low = min(
        lowload,
        v18_nfw_gap_candidate_smooth(f_gas, 0.42, 0.62),
        v18_nfw_gap_candidate_smooth(outer_gas, 0.38, 0.62),
        v18_nfw_gap_candidate_smooth(3.3 - memory, 0.0, 1.2),
        v18_nfw_gap_candidate_smooth(u_out, 0.32, 0.48),
        v18_nfw_gap_candidate_smooth(h_over, 0.13, 0.28),
        v18_nfw_gap_candidate_smooth(12.0 - mbar, 0.0, 8.0),
    )
    massive_lowgas = min(
        lowload,
        v18_nfw_gap_candidate_smooth(0.18 - f_gas, 0.0, 0.08),
        v18_nfw_gap_candidate_smooth(mbar, 25.0, 120.0),
        v18_nfw_gap_candidate_smooth(1.00 - u_max, 0.0, 0.35),
        v18_nfw_gap_candidate_smooth(outer_gas, 0.05, 0.18),
        v18_nfw_gap_candidate_smooth(bar_curv_abs, 18.0, 40.0),
    )
    buffered_gas_compact = min(
        buffered,
        v18_nfw_gap_candidate_smooth(f_gas, 0.36, 0.68),
        v18_nfw_gap_candidate_smooth(outer_gas, 0.40, 0.60),
        v18_nfw_gap_candidate_smooth(4.0 - memory, 0.0, 2.2),
        v18_nfw_gap_candidate_smooth(mbar, 2.0, 12.0),
        v18_nfw_gap_candidate_smooth(1.42 - u_max, 0.0, 0.45),
        v18_nfw_gap_candidate_smooth(point_density, 0.65, 1.75),
    )
    return {
        "gasRichLowloadOuterLift": clamp(gas_rich_low, 0.0, 1.0),
        "massiveLowgasLowloadShelf": clamp(massive_lowgas, 0.0, 1.0),
        "bufferedGasrichCompactLift": clamp(buffered_gas_compact, 0.0, 1.0),
    }


def v18_49_non_ml_gap_apply_supports(curve: dict, base_supports: list[float], betas: dict[str, float], activations: dict[str, float]) -> list[float]:
    output: list[float] = []
    for point, support in zip(curve["points"], base_supports):
        x_value = point.get("x", point["r"] / max(curve["rOut"], 1.0e-9))
        outer_shape = v18_nfw_gap_candidate_smooth(x_value, 0.35, 0.95)
        mid_outer_shape = 0.25 + 0.75 * v18_nfw_gap_candidate_smooth(x_value, 0.22, 0.82)
        factor = 1.0
        factor += betas.get("gasRichLowloadOuterLift", 0.0) * activations.get("gasRichLowloadOuterLift", 0.0) * outer_shape
        factor += betas.get("massiveLowgasLowloadShelf", 0.0) * activations.get("massiveLowgasLowloadShelf", 0.0) * mid_outer_shape
        factor += betas.get("bufferedGasrichCompactLift", 0.0) * activations.get("bufferedGasrichCompactLift", 0.0) * outer_shape
        output.append(max(0.0, support * clamp(factor, 0.58, 1.42)))
    return output


def v18_49_non_ml_gap_score_rows(betas: dict[str, float], forced_activations: dict[str, dict[str, float]] | None = None, base_entries: list[dict] | None = None) -> list[dict]:
    entries = base_entries if base_entries is not None else v18_44_ugc08699_shelf_base_entries()
    rows: list[dict] = []
    for entry in entries:
        curve = entry["curve"]
        name = curve["name"]
        base_score = entry["baseScore"]
        values = entry["values"]
        mass = entry["mass"]
        if forced_activations and name in forced_activations:
            activations = {branch: clamp(parse_float(forced_activations[name].get(branch), 0.0), 0.0, 1.0) for branch in V18_49_BRANCHES}
        else:
            activations = v18_49_non_ml_gap_activations(curve, values, mass)
        if entry["isWeak"]:
            activations = {branch: 0.0 for branch in V18_49_BRANCHES}
        candidate_supports = v18_49_non_ml_gap_apply_supports(curve, entry["baseSupports"], betas, activations)
        candidate = v18_competitor_support_score(curve, candidate_supports)
        set_label = entry["setLabel"]
        regression = max(0.0, candidate["rmse"] - base_score["rmse"])
        branch_hits = [branch for branch in V18_49_BRANCHES if abs(parse_float(betas.get(branch), 0.0)) > 1.0e-9 and activations.get(branch, 0.0) >= 0.05]
        rows.append(
            {
                "galaxy": name,
                "set": set_label,
                "split": entry["split"],
                "lockedRoute": curve.get("lockedModelRoute", ""),
                "nonMlGapTarget": name in V18_49_NON_ML_GAP_TARGETS,
                "remainingGapTargetClass": v18_40_remaining_gap_class_target_label(name),
                "canonicalRmse": entry["canonicalScore"]["rmse"],
                "v18_38Rmse": base_score["rmse"],
                "candidateRmse": candidate["rmse"],
                "candidateGainVsV18_38KmS": base_score["rmse"] - candidate["rmse"],
                "candidateGainVsV18_38Pct": pct_improvement(base_score["rmse"], candidate["rmse"]),
                "candidateRegressionVsV18_38KmS": regression,
                "candidateRoute": candidate.get("candidateRoute", ""),
                "routeChangedVsV18_38": candidate.get("candidateRoute", "") != base_score.get("candidateRoute", ""),
                "branchHits": ";".join(branch_hits),
                "active": bool(branch_hits),
                **{f"{branch}Activation": activations.get(branch, 0.0) for branch in V18_49_BRANCHES},
                **{f"{branch}Beta": betas.get(branch, 0.0) for branch in V18_49_BRANCHES},
                "memoryLoad": curve.get("memoryLoad", ""),
                "u075": curve.get("lockedModelU075", ""),
                "uOut": curve.get("lockedModelUOut", ""),
                "uMax": curve.get("lockedModelUMax", ""),
                "hOverRout": values.get("hOverRout", ""),
                "outerGasShare": values.get("outerGasShare", ""),
                "outerDiskShare": values.get("outerDiskShare", ""),
                "innerGasShare": values.get("innerGasShare", ""),
                "midGasShare": values.get("midGasShare", ""),
                "barCurv": values.get("barCurv", ""),
                "pointDensity": values.get("pointDensity", ""),
                "mBar_1e9Msun": mass.get("mBar_1e9Msun", ""),
                "tableGasFraction": mass.get("tableGasFraction", ""),
                "protectedRegressionVsV18_38KmS": regression if set_label == "clean-protected" else "",
                "highRegressionVsV18_38KmS": regression if set_label == "clean-high-rmse" else "",
                "above20Candidate": candidate["rmse"] >= 20.0 if set_label == "clean-high-rmse" else "",
            }
        )
    rows.sort(key=lambda row: row["galaxy"])
    return rows


def v18_49_non_ml_gap_metric(rows: list[dict]) -> dict:
    clean = [row for row in rows if row["set"] != "weak-systematics-excluded"]
    high = [row for row in clean if row["set"] == "clean-high-rmse"]
    protected = [row for row in clean if row["set"] == "clean-protected"]
    targets = [row for row in clean if parse_bool(row.get("nonMlGapTarget"))]
    active = [row for row in clean if parse_bool(row.get("active"))]
    protected_regs = [parse_float(row.get("protectedRegressionVsV18_38KmS"), 0.0) for row in protected]
    high_regs = [parse_float(row.get("highRegressionVsV18_38KmS"), 0.0) for row in high]
    return {
        "targetCount": len(targets),
        "activeCleanCount": len(active),
        "activeTargetCount": sum(1 for row in active if parse_bool(row.get("nonMlGapTarget"))),
        "activeProtectedCount": sum(1 for row in active if row["set"] == "clean-protected"),
        "targetGainKmS": safe_mean(parse_float(row["candidateGainVsV18_38KmS"]) for row in targets),
        "targetGainPct": pct_improvement(
            safe_mean(parse_float(row["v18_38Rmse"]) for row in targets),
            safe_mean(parse_float(row["candidateRmse"]) for row in targets),
        ),
        "highGainPct": pct_improvement(
            safe_mean(parse_float(row["v18_38Rmse"]) for row in high),
            safe_mean(parse_float(row["candidateRmse"]) for row in high),
        ),
        "cleanGainPct": pct_improvement(
            safe_mean(parse_float(row["v18_38Rmse"]) for row in clean),
            safe_mean(parse_float(row["candidateRmse"]) for row in clean),
        ),
        "protectedMaxRegressionKmS": max(protected_regs or [0.0]),
        "protectedWorseOver1Count": sum(1 for value in protected_regs if value > 1.0),
        "highMaxRegressionKmS": max(high_regs or [0.0]),
        "highAbove20Count": sum(1 for row in high if parse_bool(row.get("above20Candidate"))),
        "routeChangedCount": sum(1 for row in clean if parse_bool(row.get("routeChangedVsV18_38"))),
    }


def v18_49_non_ml_gap_null_rows(selected_rows: list[dict], betas: dict[str, float], base_entries: list[dict]) -> list[dict]:
    active_by_branch = {
        branch: sorted([parse_float(row.get(f"{branch}Activation"), 0.0) for row in selected_rows if parse_float(row.get(f"{branch}Activation"), 0.0) >= 0.05 and abs(betas.get(branch, 0.0)) > 1.0e-9], reverse=True)
        for branch in V18_49_BRANCHES
    }
    eligible = [row for row in selected_rows if row["set"] != "weak-systematics-excluded"]
    nulls: list[dict] = []
    for seed in V18_49_NULL_SEEDS:
        rng = random.Random(seed)
        forced: dict[str, dict[str, float]] = {}
        for branch, values in active_by_branch.items():
            if not values:
                continue
            candidates = [row["galaxy"] for row in eligible if row["lockedRoute"] in {"low-load", "buffered single-crossing"}]
            chosen = rng.sample(candidates, min(len(candidates), len(values)))
            for index, name in enumerate(chosen):
                forced.setdefault(name, {key: 0.0 for key in V18_49_BRANCHES})[branch] = values[index % len(values)]
        trial = v18_49_non_ml_gap_score_rows(betas, forced, base_entries)
        nulls.append({"nullType": "same-active-route-random", "seed": seed, **v18_49_non_ml_gap_metric(trial)})
    nulls.sort(key=lambda row: (row["nullType"], row["seed"]))
    return nulls


def write_v18_non_ml_gap_candidate_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_v18_49_non_ml_gap_candidate"
    base_entries = v18_44_ugc08699_shelf_base_entries()
    grid_rows: list[dict] = []
    trial_cache: dict[tuple[float, float, float], list[dict]] = {}
    for b0 in V18_49_BETA_GRID:
        for b1 in V18_49_BETA_GRID:
            for b2 in V18_49_BETA_GRID:
                betas = dict(zip(V18_49_BRANCHES, [b0, b1, b2]))
                rows = v18_49_non_ml_gap_score_rows(betas, base_entries=base_entries)
                metric = v18_49_non_ml_gap_metric(rows)
                grid_row = {**{f"{branch}Beta": betas[branch] for branch in V18_49_BRANCHES}, **metric}
                grid_rows.append(grid_row)
                trial_cache[(b0, b1, b2)] = rows
    viable = [
        row for row in grid_rows
        if parse_float(row["targetGainKmS"], -999.0) > 0.0
        and parse_float(row["protectedMaxRegressionKmS"], 999.0) <= 1.0
        and parse_float(row["highMaxRegressionKmS"], 999.0) <= 1.0
        and parse_float(row["highAbove20Count"], 999.0) == 0
        and parse_float(row["routeChangedCount"], 999.0) == 0
    ]
    if viable:
        best = max(viable, key=lambda row: (parse_float(row["targetGainKmS"], -999.0), parse_float(row["targetGainPct"], -999.0), -parse_float(row["activeProtectedCount"], 999.0)))
    else:
        best = max(grid_rows, key=lambda row: (parse_float(row["targetGainKmS"], -999.0) - 5.0 * parse_float(row["protectedMaxRegressionKmS"], 0.0)))
    selected_betas = {branch: parse_float(best[f"{branch}Beta"], 0.0) for branch in V18_49_BRANCHES}
    rows = trial_cache[(selected_betas[V18_49_BRANCHES[0]], selected_betas[V18_49_BRANCHES[1]], selected_betas[V18_49_BRANCHES[2]])]
    metric = v18_49_non_ml_gap_metric(rows)
    target_rows = [row for row in rows if parse_bool(row.get("nonMlGapTarget"))]
    protected_rows = [row for row in rows if row["set"] == "clean-protected" and parse_float(row.get("protectedRegressionVsV18_38KmS"), 0.0) > 0.0]
    active_rows = [row for row in rows if parse_bool(row.get("active"))]
    null_rows = v18_49_non_ml_gap_null_rows(rows, selected_betas, base_entries)
    best_null_gain = max((parse_float(row.get("targetGainKmS"), -999.0) for row in null_rows), default=math.nan)
    null_margin = parse_float(metric["targetGainKmS"]) - best_null_gain if math.isfinite(best_null_gain) else math.nan
    if parse_float(metric["targetGainKmS"], 0.0) >= 0.75 and parse_float(metric["protectedMaxRegressionKmS"], 0.0) <= 1.0 and parse_float(metric["highAbove20Count"], 0.0) == 0 and parse_float(null_margin, -999.0) >= 0.5:
        verdict = "non-M/L state branch candidate for review"
    elif parse_float(metric["targetGainKmS"], 0.0) > 0.0 and parse_float(metric["protectedMaxRegressionKmS"], 0.0) <= 1.0:
        verdict = "non-M/L state branch useful anatomy only"
    else:
        verdict = "non-M/L remaining gap not state-separable"
    formula = {
        "candidate": "v18.49 non-M/L remaining-gap state candidate",
        "baseLaw": "locked v18.38 support field",
        "lawChanged": False,
        "testedOperation": "state/profile gated radial support reshaping for six v18.48 non-M/L NFW-gap cases",
        "selectedBetas": selected_betas,
        "branches": V18_49_BRANCHES,
        "forbiddenInputs": ["galaxy name", "raw RMSE", "residual lookup", "NFW parameters", "Li+ per-galaxy halo-fit M/L", "weak/systematics training"],
    }
    capsule = {
        "analysisName": "mts-v18-49-non-ml-gap-candidate-v1",
        "verdict": verdict,
        "summary": {
            **metric,
            "selectedBetas": selected_betas,
            "bestNullTargetGainKmS": best_null_gain,
            "nullMarginKmS": null_margin,
            "weakSystematicsLeakage": 0,
            "lawChanged": False,
            "browserChanged": False,
        },
    }
    write_csv(out_dir / f"{prefix}_grid_scores.csv", grid_rows)
    write_csv(out_dir / f"{prefix}_case_ledger.csv", rows)
    write_csv(out_dir / f"{prefix}_target_ledger.csv", target_rows)
    write_csv(out_dir / f"{prefix}_active_ledger.csv", active_rows)
    write_csv(out_dir / f"{prefix}_protected_ledger.csv", protected_rows)
    write_csv(out_dir / f"{prefix}_null_controls.csv", null_rows)
    (out_dir / f"{prefix}_formula.json").write_text(json.dumps(json_clean(formula), indent=2, sort_keys=True), encoding="utf-8")
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    report = [
        "# MTS v18.49 Non-M/L Remaining Gap Candidate",
        "",
        "This is a direct state/profile test for the six v18.48 remaining NFW-gap cases that were not explained by numeric M/L evidence. It does not use galaxy names, NFW parameters, raw residuals, raw RMSE, or weak/systematics cases as formula inputs.",
        "",
        f"- Verdict: `{verdict}`.",
        f"- Target mean gain: `{fmt(metric['targetGainKmS'])}` km/s / `{fmt(metric['targetGainPct'])}%`.",
        f"- Clean high-RMSE gain: `{fmt(metric['highGainPct'])}%`.",
        f"- Protected max regression: `{fmt(metric['protectedMaxRegressionKmS'])}` km/s.",
        f"- High max regression: `{fmt(metric['highMaxRegressionKmS'])}` km/s.",
        f"- High cases above 20 km/s: `{metric['highAbove20Count']}`.",
        f"- Route changes: `{metric['routeChangedCount']}`.",
        f"- Best same-active null target gain: `{fmt(best_null_gain)}` km/s; margin `{fmt(null_margin)}` km/s.",
        "",
        "## Target Cases",
        "",
        "| Galaxy | route | v18.38 | candidate | gain | branches |",
        "| --- | --- | ---: | ---: | ---: | --- |",
    ]
    for row in target_rows:
        report.append(f"| {row['galaxy']} | {row['lockedRoute']} | {fmt(row['v18_38Rmse'])} | {fmt(row['candidateRmse'])} | {fmt(row['candidateGainVsV18_38KmS'])} | {row['branchHits']} |")
    report.extend(["", verdict])
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report) + "\n", encoding="utf-8")
    return capsule


