OBSERVED_STATE_SOFT_NEIGHBOR_SEEDS = list(range(SPLIT_SEED + 1000, SPLIT_SEED + 1011))
OBSERVED_STATE_SOFT_SCALE_GRID = [0.03, 0.05, 0.08, 0.10]
OBSERVED_STATE_SOFT_FULL_THRESHOLD_GRID = [1.0 / 12.0, 0.12, 0.16, 0.20, 0.30, 0.40]
OBSERVED_STATE_ROUTE_TRANSITION_PERSISTENCE_ACTIVATION = 1.0


def observed_state_soft_branch_probability(
    state_curve: dict,
    soft_scale: float,
    neighbor_seeds: list[int] | None = None,
) -> tuple[str, float, dict[str, int]]:
    neighbor_seeds = neighbor_seeds or OBSERVED_STATE_SOFT_NEIGHBOR_SEEDS
    branches = [observed_state_shape_branch(state_curve)]
    for seed in neighbor_seeds:
        branches.append(observed_state_shape_branch(observed_state_jitter_state_curve(state_curve, seed, soft_scale)))
    counts: dict[str, int] = {}
    for branch in branches:
        counts[branch] = counts.get(branch, 0) + 1
    non_empty = {branch: count for branch, count in counts.items() if branch}
    if not non_empty:
        return "", 0.0, counts
    branch, count = max(sorted(non_empty.items()), key=lambda item: item[1])
    return branch, count / len(branches), counts


def observed_state_soft_activation(probability: float, full_threshold: float) -> float:
    if probability <= 0.0:
        return 0.0
    if probability >= full_threshold:
        return 1.0
    return clamp(probability / max(1e-9, full_threshold), 0.0, 1.0)


def observed_state_soft_branch_safety(branch: str, state_curve: dict) -> bool:
    """Protect clean lookalikes when the state-neighborhood gate is near a branch edge."""
    if not branch:
        return True
    values = observed_state_values(state_curve)
    if branch == "buffered gas-curvature":
        strict_curvature = (
            values["fGasOut"] > 0.28
            and values["outerGasShare"] > 0.25
            and values["barCurv"] < -33.0
        )
        gas_rich_curvature_margin = (
            values["fGasOut"] > 0.45
            and values["outerGasShare"] > 0.34
            and values["pointDensity"] < 0.75
            and values["uMax"] > 1.25
            and values["barCurv"] < -20.0
            and values["outerBulgeShare"] < 0.01
        )
        return strict_curvature or gas_rich_curvature_margin
    if branch == "buffered bulge-disk shoulder":
        return (
            values["memoryLoad"] > 6.0
            and values["uOut"] < 0.36
            and values["barCurv"] > -25.0
            and values["uMax"] < 1.95
            and values["outerBulgeShare"] < 0.33
            and values["barCurv"] < 35.0
        )
    if branch == "compact low-load transition":
        return (
            values["uOut"] < 0.405
            and not (0.22 < values["outerGasShare"] < 0.25)
            and (values["outerGasShare"] <= 0.25 or values["fGasOut"] > 0.30)
            and (
                values["pointDensity"] < 1.0
                or values["innerBulgeShare"] > 0.05
                or values["barMidOuter"] > 1.18
                or values["outerGasShare"] > 0.25
            )
        )
    if branch == "gas-rich buffered disk":
        strict_gas_rich = values["LgapOverH"] > 0.42 and values["fGasOut"] > 0.62
        extended_outer_gas_margin = (
            values["LgapOverH"] > 0.42
            and values["fGasOut"] > 0.55
            and values["outerGasShare"] > 0.55
            and values["hOverRout"] > 0.25
            and values["outerBulgeShare"] < 0.01
            and values["pointDensity"] < 1.0
        )
        return strict_gas_rich or extended_outer_gas_margin
    if branch == "low-load gas-disk edge v2":
        return values["pointDensity"] > 0.75 and values["midGasShare"] < 0.33
    if branch == "low-load gas-rich high-shear transition":
        return values["LgapOverH"] > 0.42 and values["midGasShare"] > 0.35
    if branch == "low-load disk-shelf transition":
        return values["uMax"] > 0.88 and values["outerGasShare"] < 0.21
    if branch == "buffered disk-shear high-q shape":
        return values["memoryLoad"] > 3.4 and values["pointDensity"] > 1.0
    return True


def observed_state_continuity_fallback_floor(state_curve: dict) -> float | None:
    """Conservative support continuity when a nearby state branch drops out under uncertainty."""
    values = observed_state_values(state_curve)
    route = state_curve["lockedModelRoute"]
    if route == "low-load":
        high_memory_lowload_edge = (
            values["memoryLoad"] > 5.0
            and values["hOverRout"] < 0.17
            and values["fGasOut"] < 0.42
            and values["uOut"] < 0.43
            and values["uMax"] < 1.05
            and values["outerBulgeShare"] < 0.12
            and 0.06 < values["outerGasShare"] < 0.36
            and values["pointDensity"] < 1.25
            and values["barCurv"] < 5.0
        )
        if high_memory_lowload_edge:
            return 1.65
        gas_disk_edge_margin = (
            1.7 < values["memoryLoad"] < 2.8
            and 0.36 < values["fGasOut"] < 0.72
            and values["outerGasShare"] > 0.35
            and values["uOut"] > 0.36
            and values["pointDensity"] > 1.35
            and values["LgapOverH"] < 0.75
        )
        if gas_disk_edge_margin:
            return 1.18
    if route == "buffered single-crossing":
        dense_buffered_margin = (
            values["memoryLoad"] > 4.0
            and values["uMax"] > 1.10
            and values["pointDensity"] > 0.40
            and values["fGasOut"] < 0.45
            and values["uOut"] > 0.24
            and values["outerBulgeShare"] < 0.42
        )
        if dense_buffered_margin:
            return 1.50
        gas_rich_buffered_margin = (
            values["memoryLoad"] < 2.1
            and values["fGasOut"] > 0.50
            and values["outerGasShare"] > 0.45
            and values["hOverRout"] > 0.20
            and values["pointDensity"] < 1.20
            and values["outerBulgeShare"] < 0.02
        )
        if gas_rich_buffered_margin:
            return 1.18
    return None


def observed_state_route_transition_persistence_branch(curve: dict, state_curve: dict) -> str:
    """Keep a real route-state branch alive when only a nearby jittered state drops it."""
    branch = observed_state_shape_branch(curve)
    if not branch:
        return ""
    if observed_state_branch_locked_route(branch) != state_curve["lockedModelRoute"]:
        return ""
    if observed_state_over_support_gate_soft_safe(state_curve):
        return ""
    return branch


def observed_state_route_transition_support_score(
    curve: dict,
    state_curve: dict,
    fit: dict,
    amp_cap: float,
    branch: str,
    activation: float,
    fallback_floor: float | None,
    continuity_fallback: bool,
) -> dict:
    amp = observed_state_amp(state_curve, fit, amp_cap)
    floor = observed_state_branch_amp_floor_for_curve(branch, state_curve)
    if floor is not None:
        amp = max(amp, 1.0 + activation * (floor - 1.0))
    q_target = observed_state_branch_q_for_curve(branch, state_curve)
    q_value = Q_DEFAULT + activation * (q_target - Q_DEFAULT)
    branch_cap = observed_state_branch_amp_cap(branch)
    if branch_cap is not None:
        amp = min(amp, 1.0 + activation * (branch_cap - 1.0))
    safety_cap = observed_state_bulge_safety_cap(state_curve)
    if safety_cap is not None:
        amp = min(amp, safety_cap)

    if branch == "low-load compact lowgas disk support":
        def support(point: dict) -> float:
            base = 1.0 - math.exp(-((point["r"] / curve["leff"]) ** q_value))
            return GAMMA0 * curve["leff"] * base * observed_state_lowload_lowgas_zone_amp(point, activation)
    else:
        def support(point: dict) -> float:
            return GAMMA0 * curve["leff"] * (1.0 - math.exp(-((point["r"] / curve["leff"]) ** q_value))) * amp

    score = score_curve_with_support(curve, support, amp, q_value)
    score["observedStateAmp"] = amp
    score["observedStateQ"] = q_value
    score["observedStateBranch"] = branch
    score["observedStateSoftProbability"] = 0.0
    score["observedStateSoftActivation"] = activation
    score["observedStateContinuityFallback"] = continuity_fallback
    score["observedStateFallbackFloor"] = fallback_floor if fallback_floor is not None else ""
    score["observedStateRouteTransitionFallback"] = branch
    return score


def observed_state_over_support_gate_soft_safe(curve: dict) -> bool:
    values = observed_state_values(curve)
    if observed_state_over_support_gate(curve):
        return values["fGasOut"] < 0.52 or values["midGasShare"] > 0.35 or values["pointDensity"] < 0.82
    low_load = curve["lockedModelRoute"] == "low-load"
    compact_low_u_support = (
        low_load
        and values["memoryLoad"] < 1.75
        and values["uMax"] < 0.92
        and values["uOut"] > 0.38
        and values["hOverRout"] > 0.28
        and values["pointDensity"] < 1.05
        and values["barMidOuter"] < 0.88
        and values["outerBulgeShare"] < 0.01
        and values["fGasOut"] < 0.66
    )
    gas_rich_low_u_support = (
        low_load
        and 1.15 < values["memoryLoad"] < 1.95
        and 0.70 < values["fGasOut"] < 0.84
        and values["midGasShare"] > 0.35
        and values["outerGasShare"] > 0.62
        and 0.80 < values["uMax"] < 0.92
        and values["uOut"] < 0.34
        and values["pointDensity"] < 0.82
        and values["barCurv"] > -1.0
        and values["barMidOuter"] < 0.88
        and 1.30 < values["LgapOverH"] < 2.20
        and values["outerBulgeShare"] < 0.01
    )
    return compact_low_u_support or gas_rich_low_u_support


def observed_state_score_curve_soft_gate(
    curve: dict,
    state_curve: dict,
    fit: dict,
    amp_cap: float,
    soft_scale: float,
    full_threshold: float,
) -> dict:
    if observed_state_over_support_gate(state_curve):
        amp = OBSERVED_STATE_OVER_SUPPORT_AMP
        q_value = Q_DEFAULT
        branch = ""
        activation = 0.0
        probability = 0.0
    else:
        branch, probability, _counts = observed_state_soft_branch_probability(state_curve, soft_scale)
        activation = observed_state_soft_activation(probability, full_threshold)
        amp = observed_state_amp(state_curve, fit, amp_cap)
        if branch and activation > 0.0:
            floor = observed_state_branch_amp_floor_for_curve(branch, state_curve)
            if floor is not None:
                amp = max(amp, 1.0 + activation * (floor - 1.0))
            q_target = observed_state_branch_q_for_curve(branch, state_curve)
            q_value = Q_DEFAULT + activation * (q_target - Q_DEFAULT)
            branch_cap = observed_state_branch_amp_cap(branch)
            if branch_cap is not None:
                amp = min(amp, 1.0 + activation * (branch_cap - 1.0))
        else:
            q_value = Q_DEFAULT
        if state_curve["lockedModelRoute"] == "low-load" and not branch and not observed_state_over_support_gate(state_curve):
            amp = min(amp, 1.0)
        safety_cap = observed_state_bulge_safety_cap(state_curve)
        if safety_cap is not None:
            amp = min(amp, safety_cap)

    if branch == "low-load compact lowgas disk support" and activation > 0.0:
        def support(point: dict) -> float:
            base = 1.0 - math.exp(-((point["r"] / curve["leff"]) ** q_value))
            return GAMMA0 * curve["leff"] * base * observed_state_lowload_lowgas_zone_amp(point, activation)
    else:
        def support(point: dict) -> float:
            return GAMMA0 * curve["leff"] * (1.0 - math.exp(-((point["r"] / curve["leff"]) ** q_value))) * amp

    score = score_curve_with_support(curve, support, amp, q_value)
    score["observedStateAmp"] = amp
    score["observedStateQ"] = q_value
    score["observedStateBranch"] = branch
    score["observedStateSoftProbability"] = probability
    score["observedStateSoftActivation"] = activation
    return score


def observed_state_score_curve_soft_safe(
    curve: dict,
    state_curve: dict,
    fit: dict,
    amp_cap: float,
    soft_scale: float,
    full_threshold: float,
) -> dict:
    fallback_floor: float | None = None
    continuity_fallback = False
    over_support_persistence = False
    if observed_state_over_support_gate_soft_safe(state_curve):
        amp = OBSERVED_STATE_OVER_SUPPORT_AMP
        q_value = Q_DEFAULT
        branch = ""
        activation = 0.0
        probability = 0.0
    else:
        branch, probability, _counts = observed_state_soft_branch_probability(state_curve, soft_scale)
        if branch and not observed_state_soft_branch_safety(branch, state_curve):
            branch = ""
            probability = 0.0
        activation = observed_state_soft_activation(probability, full_threshold)
        amp = observed_state_amp(state_curve, fit, amp_cap)
        if branch and activation > 0.0:
            floor = observed_state_branch_amp_floor_for_curve(branch, state_curve)
            if floor is not None:
                amp = max(amp, 1.0 + activation * (floor - 1.0))
            q_target = observed_state_branch_q_for_curve(branch, state_curve)
            q_value = Q_DEFAULT + activation * (q_target - Q_DEFAULT)
            branch_cap = observed_state_branch_amp_cap(branch)
            if branch_cap is not None:
                amp = min(amp, 1.0 + activation * (branch_cap - 1.0))
        else:
            q_value = Q_DEFAULT
        if not branch and activation <= 0.0:
            fallback_floor = observed_state_continuity_fallback_floor(state_curve)
            if fallback_floor is not None:
                amp = max(amp, fallback_floor)
                continuity_fallback = True
            transition_branch = observed_state_route_transition_persistence_branch(curve, state_curve)
            if transition_branch:
                return observed_state_route_transition_support_score(
                    curve,
                    state_curve,
                    fit,
                    amp_cap,
                    transition_branch,
                    OBSERVED_STATE_ROUTE_TRANSITION_PERSISTENCE_ACTIVATION,
                    fallback_floor,
                    continuity_fallback,
                )
            if (
                observed_state_over_support_gate_soft_safe(curve)
                and curve["lockedModelRoute"] == state_curve["lockedModelRoute"] == "low-load"
            ):
                amp = OBSERVED_STATE_OVER_SUPPORT_AMP
                q_value = Q_DEFAULT
                over_support_persistence = True
        if (
            state_curve["lockedModelRoute"] == "low-load"
            and not branch
            and fallback_floor is None
            and not observed_state_over_support_gate_soft_safe(state_curve)
            and not over_support_persistence
        ):
            amp = min(amp, 1.0)
        safety_cap = observed_state_bulge_safety_cap(state_curve)
        if safety_cap is not None:
            amp = min(amp, safety_cap)

    if branch == "low-load compact lowgas disk support" and activation > 0.0:
        def support(point: dict) -> float:
            base = 1.0 - math.exp(-((point["r"] / curve["leff"]) ** q_value))
            return GAMMA0 * curve["leff"] * base * observed_state_lowload_lowgas_zone_amp(point, activation)
    else:
        def support(point: dict) -> float:
            return GAMMA0 * curve["leff"] * (1.0 - math.exp(-((point["r"] / curve["leff"]) ** q_value))) * amp

    score = score_curve_with_support(curve, support, amp, q_value)
    score["observedStateAmp"] = amp
    score["observedStateQ"] = q_value
    score["observedStateBranch"] = branch
    score["observedStateSoftProbability"] = probability
    score["observedStateSoftActivation"] = activation
    score["observedStateContinuityFallback"] = continuity_fallback
    score["observedStateFallbackFloor"] = fallback_floor if fallback_floor is not None else ""
    score["observedStateRouteTransitionFallback"] = "over-support-persistence" if over_support_persistence else ""
    return score


def observed_state_soft_gate_eval(
    clean_curves: list[dict],
    high_names: set[str],
    fit: dict,
    amp_cap: float,
    soft_scale: float,
    full_threshold: float,
    score_fn: Callable[[dict, dict, dict, float, float, float], dict] = observed_state_score_curve_soft_gate,
) -> tuple[dict, list[dict]]:
    rows = []
    for curve in clean_curves:
        base = score_curve(curve)
        cand = score_fn(curve, curve, fit, amp_cap, soft_scale, full_threshold)
        rows.append((curve, base, cand))
    high_rows = [row for row in rows if row[0]["name"] in high_names]
    protected_rows = [row for row in rows if row[0]["name"] not in high_names]
    protected_regressions = [row[2]["rmse"] - row[1]["rmse"] for row in protected_rows]
    metrics = {
        "highGainPct": pct_improvement(safe_mean(row[1]["rmse"] for row in high_rows), safe_mean(row[2]["rmse"] for row in high_rows)),
        "cleanGainPct": pct_improvement(safe_mean(row[1]["rmse"] for row in rows), safe_mean(row[2]["rmse"] for row in rows)),
        "highStillAbove20": sum(1 for row in high_rows if row[2]["rmse"] >= 20.0),
        "highWorsened": sum(1 for row in high_rows if row[2]["rmse"] > row[1]["rmse"]),
        "protectedRegressionCount": sum(1 for reg in protected_regressions if reg > 1e-9),
        "maxProtectedRegression": max(protected_regressions) if protected_regressions else 0.0,
        "routePreservation": safe_mean(1.0 if row[2]["candidateRoute"] == row[1]["candidateRoute"] else 0.0 for row in rows),
    }
    case_rows = [
        {
            "galaxy": curve["name"],
            "set": "clean-high-rmse" if curve["name"] in high_names else "clean-protected",
            "lockedRoute": curve["lockedModelRoute"],
            "baselineRmse": base["rmse"],
            "candidateRmse": cand["rmse"],
            "gainKmS": base["rmse"] - cand["rmse"],
            "branch": cand.get("observedStateBranch", ""),
            "softProbability": cand.get("observedStateSoftProbability", 0.0),
            "softActivation": cand.get("observedStateSoftActivation", 0.0),
            "continuityFallback": cand.get("observedStateContinuityFallback", False),
            "fallbackFloor": cand.get("observedStateFallbackFloor", ""),
            "routeTransitionFallback": cand.get("observedStateRouteTransitionFallback", ""),
            "candidateRoute": cand["candidateRoute"],
            "stillAbove20": cand["rmse"] >= 20.0 if curve["name"] in high_names else "",
            "protectedRegression": cand["rmse"] - base["rmse"] if curve["name"] not in high_names else "",
        }
        for curve, base, cand in rows
    ]
    return metrics, case_rows


def observed_state_soft_gate_robustness_eval(
    clean_curves: list[dict],
    high_names: set[str],
    fit: dict,
    amp_cap: float,
    soft_scale: float,
    full_threshold: float,
    score_fn: Callable[[dict, dict, dict, float, float, float], dict] = observed_state_score_curve_soft_gate,
) -> tuple[list[dict], list[dict], list[dict]]:
    variant_rows: list[dict] = []
    high_trial_rows: list[dict] = []
    protected_rows: list[dict] = []
    protected_reg_by_name: dict[str, dict] = {}
    for jitter_scale in OBSERVED_STATE_ROBUSTNESS_SCALES:
        for seed in OBSERVED_STATE_ROBUSTNESS_SEEDS:
            trial_scores = []
            for curve in clean_curves:
                base = score_curve(curve)
                state_curve = observed_state_jitter_state_curve(curve, seed, jitter_scale)
                cand = score_fn(curve, state_curve, fit, amp_cap, soft_scale, full_threshold)
                trial_scores.append((curve, base, cand))
                if curve["name"] in high_names:
                    high_trial_rows.append(
                        {
                            "softScale": soft_scale,
                            "fullThreshold": full_threshold,
                            "jitterScale": jitter_scale,
                            "seed": seed,
                            "galaxy": curve["name"],
                            "branch": cand.get("observedStateBranch", ""),
                            "softProbability": cand.get("observedStateSoftProbability", 0.0),
                            "softActivation": cand.get("observedStateSoftActivation", 0.0),
                            "continuityFallback": cand.get("observedStateContinuityFallback", False),
                            "fallbackFloor": cand.get("observedStateFallbackFloor", ""),
                            "routeTransitionFallback": cand.get("observedStateRouteTransitionFallback", ""),
                            "candidateRmse": cand["rmse"],
                            "gainKmS": base["rmse"] - cand["rmse"],
                            "stillAbove20": cand["rmse"] >= 20.0,
                            "worsened": cand["rmse"] > base["rmse"],
                        }
                    )
                else:
                    reg = cand["rmse"] - base["rmse"]
                    rec = protected_reg_by_name.setdefault(
                        curve["name"],
                        {
                            "galaxy": curve["name"],
                            "lockedRoute": curve["lockedModelRoute"],
                            "maxRegression": 0.0,
                            "regressionTrialCount": 0,
                            "worstJitterScale": 0.0,
                            "worstSeed": "",
                        },
                    )
                    if reg > rec["maxRegression"]:
                        rec["maxRegression"] = reg
                        rec["worstJitterScale"] = jitter_scale
                        rec["worstSeed"] = seed
                    if reg > 1e-9:
                        rec["regressionTrialCount"] += 1
            high_rows = [row for row in trial_scores if row[0]["name"] in high_names]
            all_protected = [row for row in trial_scores if row[0]["name"] not in high_names]
            protected_regressions = [row[2]["rmse"] - row[1]["rmse"] for row in all_protected]
            variant_rows.append(
                {
                    "softScale": soft_scale,
                    "fullThreshold": full_threshold,
                    "jitterScale": jitter_scale,
                    "seed": seed,
                    "highGainPct": pct_improvement(
                        safe_mean(row[1]["rmse"] for row in high_rows),
                        safe_mean(row[2]["rmse"] for row in high_rows),
                    ),
                    "cleanGainPct": pct_improvement(
                        safe_mean(row[1]["rmse"] for row in trial_scores),
                        safe_mean(row[2]["rmse"] for row in trial_scores),
                    ),
                    "highStillAbove20": sum(1 for row in high_rows if row[2]["rmse"] >= 20.0),
                    "highWorsened": sum(1 for row in high_rows if row[2]["rmse"] > row[1]["rmse"]),
                    "protectedRegressionCount": sum(1 for val in protected_regressions if val > 1e-9),
                    "maxProtectedRegression": max(protected_regressions) if protected_regressions else 0.0,
                    "routePreservation": safe_mean(1.0 if row[2]["candidateRoute"] == row[1]["candidateRoute"] else 0.0 for row in trial_scores),
                }
            )
    for rec in protected_reg_by_name.values():
        if rec["maxRegression"] > 0.0:
            rec["protectedFailure"] = rec["maxRegression"] > 4.0
            protected_rows.append(rec)
    return variant_rows, high_trial_rows, protected_rows


def observed_state_score_curve_soft_safe_forced(
    curve: dict,
    state_curve: dict,
    branch: str,
    activation: float,
) -> dict:
    if observed_state_over_support_gate_soft_safe(state_curve):
        amp = OBSERVED_STATE_OVER_SUPPORT_AMP
        q_value = Q_DEFAULT
        branch = ""
        activation = 0.0
    else:
        if branch and not observed_state_soft_branch_safety(branch, state_curve):
            branch = ""
            activation = 0.0
        amp = 1.0
        if branch and activation > 0.0:
            floor = observed_state_branch_amp_floor_for_curve(branch, state_curve)
            if floor is not None:
                amp = max(amp, 1.0 + activation * (floor - 1.0))
            q_target = observed_state_branch_q_for_curve(branch, state_curve)
            q_value = Q_DEFAULT + activation * (q_target - Q_DEFAULT)
            branch_cap = observed_state_branch_amp_cap(branch)
            if branch_cap is not None:
                amp = min(amp, 1.0 + activation * (branch_cap - 1.0))
        else:
            q_value = Q_DEFAULT
        if state_curve["lockedModelRoute"] == "low-load" and not branch:
            amp = min(amp, 1.0)
        safety_cap = observed_state_bulge_safety_cap(state_curve)
        if safety_cap is not None:
            amp = min(amp, safety_cap)

    if branch == "low-load compact lowgas disk support" and activation > 0.0:
        def support(point: dict) -> float:
            base = 1.0 - math.exp(-((point["r"] / curve["leff"]) ** q_value))
            return GAMMA0 * curve["leff"] * base * observed_state_lowload_lowgas_zone_amp(point, activation)
    else:
        def support(point: dict) -> float:
            return GAMMA0 * curve["leff"] * (1.0 - math.exp(-((point["r"] / curve["leff"]) ** q_value))) * amp

    score = score_curve_with_support(curve, support, amp, q_value)
    score["observedStateAmp"] = amp
    score["observedStateQ"] = q_value
    score["observedStateBranch"] = branch
    score["observedStateSoftActivation"] = activation
    return score


def observed_state_soft_safe_null_rows(
    clean_curves: list[dict],
    high_names: set[str],
    fit: dict,
    amp_cap: float,
    soft_scale: float,
    full_threshold: float,
) -> list[dict]:
    rows: list[dict] = []

    def summarize(seed: int, track: str, holdout: list[dict], scorer: Callable[[dict], dict]) -> dict:
        high_holdout = [curve for curve in holdout if curve["name"] in high_names]
        protected = [curve for curve in holdout if curve["name"] not in high_names]
        paired = [(curve, score_curve(curve), scorer(curve)) for curve in holdout]
        high_paired = [row for row in paired if row[0]["name"] in high_names]
        protected_paired = [row for row in paired if row[0]["name"] not in high_names]
        protected_regressions = [cand["rmse"] - base["rmse"] for _curve, base, cand in protected_paired]
        return {
            "seed": seed,
            "track": track,
            "holdoutCount": len(holdout),
            "highHoldoutCount": len(high_holdout),
            "protectedHoldoutCount": len(protected),
            "baselineHighRmse": safe_mean(base["rmse"] for _curve, base, _cand in high_paired),
            "candidateHighRmse": safe_mean(cand["rmse"] for _curve, _base, cand in high_paired),
            "highGainPct": pct_improvement(
                safe_mean(base["rmse"] for _curve, base, _cand in high_paired),
                safe_mean(cand["rmse"] for _curve, _base, cand in high_paired),
            ),
            "baselineCleanRmse": safe_mean(base["rmse"] for _curve, base, _cand in paired),
            "candidateCleanRmse": safe_mean(cand["rmse"] for _curve, _base, cand in paired),
            "cleanGainPct": pct_improvement(
                safe_mean(base["rmse"] for _curve, base, _cand in paired),
                safe_mean(cand["rmse"] for _curve, _base, cand in paired),
            ),
            "highStillAbove20": sum(1 for _curve, _base, cand in high_paired if cand["rmse"] >= 20.0),
            "highWorsened": sum(1 for _curve, base, cand in high_paired if cand["rmse"] > base["rmse"]),
            "maxProtectedRegression": max(protected_regressions) if protected_regressions else 0.0,
            "protectedRegressionCount": sum(1 for reg in protected_regressions if reg > 1e-9),
            "routePreservation": safe_mean(1.0 if cand["candidateRoute"] == base["candidateRoute"] else 0.0 for _curve, base, cand in paired),
            "activeBranchCount": sum(1 for _curve, _base, cand in paired if cand.get("observedStateBranch")),
        }

    for seed in range(SPLIT_SEED, SPLIT_SEED + 9):
        _train_names, holdout_names = observed_state_split(clean_curves, seed, HOLDOUT_FRACTION)
        holdout = [curve for curve in clean_curves if curve["name"] in holdout_names]
        candidate_scores = {
            curve["name"]: observed_state_score_curve_soft_safe(curve, curve, fit, amp_cap, soft_scale, full_threshold)
            for curve in holdout
        }
        candidate_hits = [
            (
                curve,
                score["observedStateBranch"],
                parse_float(score.get("observedStateSoftActivation"), 0.0),
            )
            for curve in holdout
            for score in [candidate_scores[curve["name"]]]
            if score.get("observedStateBranch") and parse_float(score.get("observedStateSoftActivation"), 0.0) > 0.0
        ]
        rows.append(
            summarize(
                seed,
                "v17.66-candidate",
                holdout,
                lambda curve: candidate_scores[curve["name"]],
            )
        )

        rng = random.Random(seed + 17061)
        shuffled_pairs = [(branch, activation) for _curve, branch, activation in candidate_hits]
        rng.shuffle(shuffled_pairs)
        shuffled_assignments = {
            curve["name"]: pair for (curve, _branch, _activation), pair in zip(candidate_hits, shuffled_pairs)
        }
        rows.append(
            summarize(
                seed,
                "branch-label-shuffle-null",
                holdout,
                lambda curve, assignments=shuffled_assignments: observed_state_score_curve_soft_safe_forced(
                    curve,
                    curve,
                    assignments.get(curve["name"], ("", 0.0))[0],
                    assignments.get(curve["name"], ("", 0.0))[1],
                ),
            )
        )

        rng = random.Random(seed + 27061)
        random_assignments: dict[str, tuple[str, float]] = {}
        for branch in sorted({branch for _curve, branch, _activation in candidate_hits}):
            hits = [(curve, activation) for curve, hit_branch, activation in candidate_hits if hit_branch == branch]
            route = observed_state_branch_locked_route(branch)
            eligible = [
                curve
                for curve in holdout
                if curve["lockedModelRoute"] == route and curve["name"] not in random_assignments
            ]
            if len(eligible) < len(hits):
                eligible = [curve for curve in holdout if curve["name"] not in random_assignments]
            rng.shuffle(eligible)
            activations = [activation for _curve, activation in hits]
            rng.shuffle(activations)
            for curve, activation in zip(eligible[: len(hits)], activations):
                random_assignments[curve["name"]] = (branch, activation)
        rows.append(
            summarize(
                seed,
                "same-active-count-route-random-null",
                holdout,
                lambda curve, assignments=random_assignments: observed_state_score_curve_soft_safe_forced(
                    curve,
                    curve,
                    assignments.get(curve["name"], ("", 0.0))[0],
                    assignments.get(curve["name"], ("", 0.0))[1],
                ),
            )
        )

        rng = random.Random(seed + 37061)
        stress_assignments: dict[str, tuple[str, float]] = {}
        for branch in sorted({branch for _curve, branch, _activation in candidate_hits}):
            hits = [(curve, activation) for curve, hit_branch, activation in candidate_hits if hit_branch == branch]
            route = observed_state_branch_locked_route(branch)
            eligible = [
                curve
                for curve in holdout
                if curve["name"] not in high_names
                and curve["lockedModelRoute"] == route
                and curve["name"] not in stress_assignments
            ]
            if len(eligible) < len(hits):
                eligible = [
                    curve
                    for curve in holdout
                    if curve["name"] not in high_names and curve["name"] not in stress_assignments
                ]
            rng.shuffle(eligible)
            activations = [activation for _curve, activation in hits]
            rng.shuffle(activations)
            for curve, activation in zip(eligible[: len(hits)], activations):
                stress_assignments[curve["name"]] = (branch, activation)
        rows.append(
            summarize(
                seed,
                "protected-lookalike-stress-null",
                holdout,
                lambda curve, assignments=stress_assignments: observed_state_score_curve_soft_safe_forced(
                    curve,
                    curve,
                    assignments.get(curve["name"], ("", 0.0))[0],
                    assignments.get(curve["name"], ("", 0.0))[1],
                ),
            )
        )
    return rows


def observed_state_soft_safe_null_summary(null_rows: list[dict]) -> dict:
    tracks = sorted({row["track"] for row in null_rows})
    med_high = {track: safe_median(parse_float(row["highGainPct"]) for row in null_rows if row["track"] == track) for track in tracks}
    candidate = med_high.get("v17.66-candidate", math.nan)
    fair_nulls = [track for track in tracks if track != "v17.66-candidate"]
    best_null = max([med_high.get(track, math.nan) for track in fair_nulls if math.isfinite(med_high.get(track, math.nan))] or [math.nan])
    return {
        "medianCandidateHighGainPct": candidate,
        "medianBranchLabelShuffleHighGainPct": med_high.get("branch-label-shuffle-null", math.nan),
        "medianSameActiveRouteRandomHighGainPct": med_high.get("same-active-count-route-random-null", math.nan),
        "medianProtectedLookalikeStressHighGainPct": med_high.get("protected-lookalike-stress-null", math.nan),
        "bestNullHighGainPct": best_null,
        "bestNullMarginPct": candidate - best_null if math.isfinite(candidate) and math.isfinite(best_null) else math.nan,
        "maxCandidateProtectedRegression": max(
            parse_float(row["maxProtectedRegression"])
            for row in null_rows
            if row["track"] == "v17.66-candidate"
        ),
        "maxProtectedLookalikeStressRegression": max(
            parse_float(row["maxProtectedRegression"])
            for row in null_rows
            if row["track"] == "protected-lookalike-stress-null"
        ),
    }


def write_observed_state_soft_gate_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    context = observed_state_candidate_context()
    clean_curves = context["cleanCurves"]
    high_names = context["highNames"]
    fit = context["fit"]
    amp_cap = context["ampCap"]
    release_capsule = read_json_if_exists(DEFAULT_OBSERVED_STATE_RELEASE_STRESS_OUT / "mts_observed_state_release_capsule.json")

    candidate_rows: list[dict] = []
    all_case_rows: list[dict] = []
    all_variant_rows: list[dict] = []
    all_trial_rows: list[dict] = []
    all_protected_rows: list[dict] = []
    best_key: tuple[float, float, float, float] | None = None
    best_row: dict | None = None
    for soft_scale in OBSERVED_STATE_SOFT_SCALE_GRID:
        for full_threshold in OBSERVED_STATE_SOFT_FULL_THRESHOLD_GRID:
            metrics, case_rows = observed_state_soft_gate_eval(clean_curves, high_names, fit, amp_cap, soft_scale, full_threshold)
            variant_rows, trial_rows, protected_rows = observed_state_soft_gate_robustness_eval(
                clean_curves,
                high_names,
                fit,
                amp_cap,
                soft_scale,
                full_threshold,
            )
            max_above20 = max(int(parse_float(row["highStillAbove20"], 0.0)) for row in variant_rows)
            max_worsened = max(int(parse_float(row["highWorsened"], 0.0)) for row in variant_rows)
            max_protected_regression = max(parse_float(row["maxProtectedRegression"], 0.0) for row in variant_rows)
            median_robust_high = safe_median(parse_float(row["highGainPct"]) for row in variant_rows)
            min_robust_high = min(parse_float(row["highGainPct"]) for row in variant_rows)
            protected_failure_count = sum(1 for row in protected_rows if row["protectedFailure"])
            row = {
                "softScale": soft_scale,
                "fullThreshold": full_threshold,
                **metrics,
                "robustMedianHighGainPct": median_robust_high,
                "robustMinHighGainPct": min_robust_high,
                "robustMaxAbove20": max_above20,
                "robustMaxWorsened": max_worsened,
                "robustMaxProtectedRegression": max_protected_regression,
                "robustProtectedFailureCount": protected_failure_count,
                "candidateAccepted": (
                    metrics["highStillAbove20"] == 0
                    and metrics["highWorsened"] == 0
                    and metrics["maxProtectedRegression"] <= 4.0
                    and max_above20 <= 7
                    and max_worsened == 0
                    and max_protected_regression <= 8.0
                    and median_robust_high >= 55.0
                    and protected_failure_count <= 1
                ),
            }
            candidate_rows.append(row)
            for case in case_rows:
                all_case_rows.append({"softScale": soft_scale, "fullThreshold": full_threshold, **case})
            all_variant_rows.extend(variant_rows)
            all_trial_rows.extend(trial_rows)
            for protected in protected_rows:
                all_protected_rows.append({"softScale": soft_scale, "fullThreshold": full_threshold, **protected})
            score_key = (
                -protected_failure_count,
                -max_above20,
                median_robust_high,
                metrics["highGainPct"],
            )
            if best_key is None or score_key > best_key:
                best_key = score_key
                best_row = row

    assert best_row is not None
    verdict = "soft-gate candidate accepted" if best_row["candidateAccepted"] else "soft-gate improves robustness but needs smoothing"
    best_cases = [
        row
        for row in all_case_rows
        if parse_float(row["softScale"]) == parse_float(best_row["softScale"])
        and parse_float(row["fullThreshold"]) == parse_float(best_row["fullThreshold"])
    ]
    best_trials = [
        row
        for row in all_trial_rows
        if parse_float(row["softScale"]) == parse_float(best_row["softScale"])
        and parse_float(row["fullThreshold"]) == parse_float(best_row["fullThreshold"])
    ]
    best_protected = [
        row
        for row in all_protected_rows
        if parse_float(row["softScale"]) == parse_float(best_row["softScale"])
        and parse_float(row["fullThreshold"]) == parse_float(best_row["fullThreshold"])
    ]

    write_csv(out_dir / "mts_observed_state_soft_gate_candidate_scores.csv", candidate_rows)
    write_csv(out_dir / "mts_observed_state_soft_gate_case_ledger.csv", best_cases)
    write_csv(out_dir / "mts_observed_state_soft_gate_robustness_trials.csv", best_trials)
    write_csv(out_dir / "mts_observed_state_soft_gate_all_variant_scores.csv", all_variant_rows)
    write_csv(out_dir / "mts_observed_state_soft_gate_protected_regressions.csv", best_protected)

    formula = {
        "candidateId": "observed-state-response-v17.55-soft-gate",
        "mechanism": "v17.53 five-family state response with deterministic state-neighborhood soft branch activation",
        "softScale": best_row["softScale"],
        "fullActivationThreshold": best_row["fullThreshold"],
        "neighborSeedCount": len(OBSERVED_STATE_SOFT_NEIGHBOR_SEEDS) + 1,
        "supportLaw": "A_state and q_state are blended from canonical toward the selected family/branch response by activation=min(1, p_branch/fullThreshold)",
        "canonicalMtsChanged": False,
        "forbiddenInputs": ["galaxy name", "raw residual lookup", "raw RMSE as formula input", "weak/systematics galaxies"],
    }
    (out_dir / "mts_observed_state_soft_gate_formula.json").write_text(
        json.dumps(json_clean(formula), indent=2, sort_keys=True), encoding="utf-8"
    )
    report = [
        "# MTS v17.55 Soft-Gate Candidate",
        "",
        "This mode tests a real smoothing fix: branch activation is the local state-neighborhood probability, not a hard on/off threshold.",
        "",
        "## Result",
        "",
        f"- Verdict: `{verdict}`.",
        f"- Best soft scale: `{fmt(best_row['softScale'])}`.",
        f"- Best full-activation threshold: `{fmt(best_row['fullThreshold'])}`.",
        f"- Nominal high-RMSE gain: `{fmt(best_row['highGainPct'])}%`.",
        f"- Nominal clean gain: `{fmt(best_row['cleanGainPct'])}%`.",
        f"- Nominal high still above 20: `{best_row['highStillAbove20']}`.",
        f"- Robust median high gain: `{fmt(best_row['robustMedianHighGainPct'])}%`.",
        f"- Robust max above 20: `{best_row['robustMaxAbove20']}`.",
        f"- Robust max protected regression: `{fmt(best_row['robustMaxProtectedRegression'])} km/s`.",
        f"- Robust protected failure count: `{best_row['robustProtectedFailureCount']}`.",
        "",
        "## Compared With v17.54 Hard-Gate Robustness",
        "",
        "- Hard-gate v17.54 had `29` worst above-20 cases under jitter and `5` protected failures.",
        f"- Soft-gate best has `{best_row['robustMaxAbove20']}` worst above-20 cases and `{best_row['robustProtectedFailureCount']}` protected failures.",
        "",
        "## Worst Remaining Soft-Gate Failures",
        "",
    ]
    for row in sorted(best_trials, key=lambda item: (not bool(item["stillAbove20"]), -parse_float(item["candidateRmse"])))[:12]:
        if not row["stillAbove20"]:
            continue
        report.append(
            f"- `{row['galaxy']}`: RMSE `{fmt(row['candidateRmse'])}`, branch `{row['branch']}`, "
            f"activation `{fmt(row['softActivation'], 3)}`."
        )
    (out_dir / "mts_observed_state_soft_gate_report.md").write_text("\n".join(report), encoding="utf-8")

    capsule = {
        "analysisName": "mts-observed-state-soft-gate-v1",
        "candidateId": "observed-state-response-v17.55-soft-gate",
        "verdict": verdict,
        "bestCandidate": best_row,
        "hardGateReference": {
            "worstAbove20": 29,
            "protectedFailureCount": 5,
            "source": "mts-observed-state-robustness-v1",
        },
        "releaseStressReference": {
            "verdict": release_capsule.get("verdict", ""),
            "minNullMarginPct": release_capsule.get("nullMargins", {}).get("sameActiveCountBranchNullPct", ""),
        },
        "outputFiles": [
            "mts_observed_state_soft_gate_candidate_scores.csv",
            "mts_observed_state_soft_gate_case_ledger.csv",
            "mts_observed_state_soft_gate_robustness_trials.csv",
            "mts_observed_state_soft_gate_all_variant_scores.csv",
            "mts_observed_state_soft_gate_protected_regressions.csv",
            "mts_observed_state_soft_gate_formula.json",
            "mts_observed_state_soft_gate_report.md",
            "mts_observed_state_soft_gate_capsule.json",
        ],
    }
    (out_dir / "mts_observed_state_soft_gate_capsule.json").write_text(
        json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8"
    )
    return capsule


def cmd_observedstatesoftgate(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_OBSERVED_STATE_SOFT_GATE_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_observed_state_soft_gate_artifacts(out_dir)
    best = capsule["bestCandidate"]
    print("MTS observed state-response soft gate v17.55")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"soft_scale={fmt(best['softScale'])}",
                f"threshold={fmt(best['fullThreshold'])}",
                f"nominal_high={fmt(best['highGainPct'])}%",
                f"robust_high={fmt(best['robustMedianHighGainPct'])}%",
                f"robust_above20={best['robustMaxAbove20']}",
                f"protected_fail={best['robustProtectedFailureCount']}",
            ]
        )
    )
    print(f"Wrote observed state-response soft gate to {out_dir.resolve()}")


