def v19_source_second_derivative(values: list[float], radii: list[float]) -> list[float]:
    if len(values) < 3:
        return [0.0 for _ in values]
    out = [0.0 for _ in values]
    for index in range(1, len(values) - 1):
        dr1 = max(1.0e-9, radii[index] - radii[index - 1])
        dr2 = max(1.0e-9, radii[index + 1] - radii[index])
        left = (values[index] - values[index - 1]) / dr1
        right = (values[index + 1] - values[index]) / dr2
        out[index] = 2.0 * (right - left) / max(1.0e-9, dr1 + dr2)
    out[0] = out[1]
    out[-1] = out[-2]
    return out


def v19_source_smooth(values: list[float], radii: list[float], length: float) -> list[float]:
    if not values:
        return []
    safe_length = max(1.0e-6, length)
    smoothed = []
    for radius in radii:
        weights = [math.exp(-abs(radius - other) / safe_length) for other in radii]
        denom = sum(weights) or 1.0
        smoothed.append(sum(weight * value for weight, value in zip(weights, values)) / denom)
    return smoothed


def v19_source_normalize(values: list[float]) -> list[float]:
    finite = [abs(parse_float(value, 0.0)) for value in values]
    scale = max(finite or [1.0])
    if scale <= 0:
        return [0.0 for _ in values]
    return [parse_float(value, 0.0) / scale for value in values]


def v19_source_cumulative(values: list[float], radii: list[float]) -> list[float]:
    if not values:
        return []
    total = 0.0
    out = []
    prev_r = radii[0]
    for index, (radius, value) in enumerate(zip(radii, values)):
        dr = radius - prev_r if index else max(radius, 1.0e-6)
        total += max(0.0, value) * max(1.0e-6, dr)
        out.append(total)
        prev_r = radius
    norm = max(out[-1], 1.0e-9)
    return [value / norm for value in out]


def v19_source_raw_supports(curve: dict, equation_id: str) -> tuple[list[float], dict]:
    state = v19_theory_kernel_state(curve)
    radii = [max(1.0e-9, parse_float(point.get("r"), 0.0)) for point in curve["points"]]
    x_values = [clamp(parse_float(point.get("x"), 0.0), 0.0, 1.5) for point in curve["points"]]
    vbar = [math.sqrt(max(0.0, parse_float(point.get("bar2"), 0.0))) for point in curve["points"]]
    vgas = [abs(parse_float(point.get("vGas"), 0.0)) for point in curve["points"]]
    vdisk = [abs(parse_float(point.get("vDisk"), 0.0)) for point in curve["points"]]
    vbulge = [abs(parse_float(point.get("vBulge"), 0.0)) for point in curve["points"]]
    baryon_norm = v19_source_normalize(vbar)
    gas_norm = v19_source_normalize(vgas)
    disk_norm = v19_source_normalize(vdisk)
    bulge_norm = v19_source_normalize(vbulge)
    l_eff = max(1.0e-9, state["lExact"])
    r_out = max(1.0e-9, curve.get("rOut", radii[-1] if radii else 1.0))

    if equation_id == "stiffness-relaxation-equation":
        ell = max(0.18 * l_eff, 0.12 * curve.get("h", 1.0), 0.05 * r_out)
        source = [
            clamp(0.62 * b + 0.24 * d + 0.14 * g, 0.0, 2.0)
            for b, d, g in zip(baryon_norm, disk_norm, gas_norm)
        ]
        smooth = v19_source_smooth(source, radii, ell)
        cumulative = v19_source_cumulative(smooth, radii)
        raw = [
            GAMMA0 * l_eff * (1.0 - math.exp(-((max(1.0e-6, c * r_out) / l_eff) ** Q_DEFAULT)))
            for c in cumulative
        ]
        return raw, {
            "equation": "m - ell^2 nabla_r^2 m = m_baryon; S_raw = Gamma0*L_eff*(1-exp(-(u_m*r_out/L_eff)^q))",
            "lengthScale": ell,
        }

    if equation_id == "curvature-memory-growth-equation":
        grad_b = v19_source_normalize([abs(value) for value in v19_source_second_derivative(baryon_norm, radii)])
        memory_drive = clamp(state["memoryLoad"] / 8.0, 0.0, 1.0)
        sat_drive = clamp(state["satFraction"] * 4.0, 0.0, 1.0)
        local_drive = [
            clamp(
                0.38 * b
                + 0.22 * g
                + 0.16 * d
                + 0.14 * gb
                + 0.10 * memory_drive,
                0.0,
                2.0,
            )
            for b, g, d, gb in zip(baryon_norm, gas_norm, disk_norm, grad_b)
        ]
        gamma_memory = v19_source_smooth(local_drive, radii, max(0.22 * l_eff, 0.08 * r_out))
        leff_memory = l_eff * (1.0 + 0.22 * sat_drive)
        raw = []
        for point, drive in zip(curve["points"], gamma_memory):
            base = GAMMA0 * leff_memory * (1.0 - math.exp(-((point["r"] / leff_memory) ** Q_DEFAULT)))
            raw.append(base * (0.70 + 0.30 * clamp(drive, 0.0, 1.0)))
        return raw, {
            "equation": "Gamma_m(r) = Smooth_L[F(Sigma_b, dSigma_b/dr, memory_load)]; S_raw = Gamma0*L_m*K(r,L_m)*Gamma_m",
            "lengthScale": leff_memory,
        }

    if equation_id == "motion-field-response-equation":
        ell = max(0.30 * l_eff, 0.10 * r_out)
        profile_curv = v19_source_normalize([abs(value) for value in v19_source_second_derivative(vbar, radii)])
        psi_source = [
            clamp(
                0.44 * b
                + 0.20 * g * (0.45 + 0.55 * x)
                + 0.18 * d
                + 0.10 * bu * (1.0 - 0.55 * x)
                + 0.08 * c,
                0.0,
                2.0,
            )
            for b, g, d, bu, c, x in zip(baryon_norm, gas_norm, disk_norm, bulge_norm, profile_curv, x_values)
        ]
        psi = v19_source_smooth(psi_source, radii, ell)
        psi_cumulative = v19_source_cumulative(psi, radii)
        raw = []
        for point, psi_value, cumulative in zip(curve["points"], psi, psi_cumulative):
            boundary = 0.78 + 0.22 * clamp(cumulative + 0.35 * psi_value, 0.0, 1.2)
            raw.append(GAMMA0 * l_eff * (1.0 - math.exp(-((point["r"] / l_eff) ** Q_DEFAULT))) * boundary)
        return raw, {
            "equation": "div(K[psi,Sigma_b] grad psi)=rho_b; S_raw = Gamma0*L_eff*K(r,L_eff)*B_psi(r)",
            "lengthScale": ell,
        }

    raise ValueError(f"Unknown v19 source equation: {equation_id}")


def v19_source_equation_global_scales(curves: list[dict], weak_names: set[str], supports_by_name: dict[str, list[float]]) -> dict[str, float]:
    scales: dict[str, float] = {}
    for equation_id in V19_SOURCE_EQUATION_IDS:
        numerator = 0.0
        denominator = 0.0
        for curve in curves:
            if curve["name"] in weak_names:
                continue
            target = supports_by_name.get(curve["name"], [])
            if len(target) != len(curve["points"]):
                continue
            raw, _ = v19_source_raw_supports(curve, equation_id)
            for raw_value, target_value in zip(raw, target):
                numerator += max(0.0, raw_value) * max(0.0, target_value)
                denominator += max(0.0, raw_value) ** 2
        scales[equation_id] = numerator / denominator if denominator > 1.0e-12 else 1.0
    return scales


def v19_source_acceleration_shape_metrics(curve: dict, target_supports: list[float], candidate_supports: list[float]) -> dict:
    target_acc = []
    candidate_acc = []
    for point, target, candidate in zip(curve["points"], target_supports, candidate_supports):
        r = max(1.0e-9, parse_float(point.get("r"), 0.0))
        target_acc.append(max(0.0, target) / r)
        candidate_acc.append(max(0.0, candidate) / r)
    target_max = max([abs(value) for value in target_acc] or [1.0])
    candidate_max = max([abs(value) for value in candidate_acc] or [1.0])
    shape_diffs = []
    accel_diffs = []
    zone_bias = {"inner": [], "mid": [], "outer": []}
    for point, target, candidate in zip(curve["points"], target_acc, candidate_acc):
        shape_diffs.append(((candidate / candidate_max) - (target / target_max)) ** 2 if candidate_max > 0 and target_max > 0 else 0.0)
        accel_diffs.append((candidate - target) ** 2)
        zone_bias[v19_kernel_zone(point)].append(candidate - target)
    out = {
        "accelerationShapeRmse": math.sqrt(safe_mean(shape_diffs)) if shape_diffs else math.nan,
        "accelerationFieldRmse": math.sqrt(safe_mean(accel_diffs)) if accel_diffs else math.nan,
    }
    for zone, values in zone_bias.items():
        out[f"{zone}AccelerationBias"] = safe_mean(values)
    return out


def v19_source_equation_rows() -> tuple[list[dict], list[dict], list[dict], dict]:
    context = observed_state_candidate_context()
    curves = context["curves"]
    weak_names = set(context["weakNames"])
    high_names = set(context["highNames"])
    supports_by_name = v18_39_remaining_nfw_gap_artifact_supports()
    scales = v19_source_equation_global_scales(curves, weak_names, supports_by_name)
    case_rows: list[dict] = []
    shape_rows: list[dict] = []
    for curve in curves:
        name = curve["name"]
        target_supports = supports_by_name.get(name, [])
        if len(target_supports) != len(curve["points"]):
            continue
        set_name = "weak-systematics-excluded" if name in weak_names else ("clean-high-rmse" if name in high_names else "clean-protected")
        target_score = v18_competitor_support_score(curve, target_supports)
        canonical_score = v18_competitor_support_score(curve, v18_competitor_canonical_supports(curve))
        for equation_id in V19_SOURCE_EQUATION_IDS:
            raw, meta = v19_source_raw_supports(curve, equation_id)
            scale = scales[equation_id]
            candidate_supports = [max(0.0, scale * value) for value in raw]
            score = v18_competitor_support_score(curve, candidate_supports)
            shape = v19_source_acceleration_shape_metrics(curve, target_supports, candidate_supports)
            target_gain = pct_improvement(canonical_score["rmse"], target_score["rmse"])
            candidate_gain = pct_improvement(canonical_score["rmse"], score["rmse"])
            row = {
                "galaxy": name,
                "set": set_name,
                "equationId": equation_id,
                "lockedRoute": curve.get("lockedModelRoute", ""),
                "canonicalRmse": canonical_score["rmse"],
                "lockedV18Rmse": target_score["rmse"],
                "sourceEquationRmse": score["rmse"],
                "sourceMinusV18KmS": score["rmse"] - target_score["rmse"],
                "gainVsCanonicalPct": candidate_gain,
                "lockedV18GainVsCanonicalPct": target_gain,
                "v18RepairRetentionPct": candidate_gain / target_gain * 100.0 if abs(target_gain) > 1.0e-9 else math.nan,
                "globalScale": scale,
                "equation": meta["equation"],
                "equationLengthScale": meta["lengthScale"],
                "weakSystematicsExcluded": name in weak_names,
                **shape,
            }
            case_rows.append(row)
            for zone in ["inner", "mid", "outer"]:
                shape_rows.append(
                    {
                        "galaxy": name,
                        "set": set_name,
                        "equationId": equation_id,
                        "zone": zone,
                        "accelerationBiasCandidateMinusV18": shape[f"{zone}AccelerationBias"],
                        "accelerationShapeRmse": shape["accelerationShapeRmse"],
                        "accelerationFieldRmse": shape["accelerationFieldRmse"],
                    }
                )
    scale_rows = [{"equationId": equation_id, "globalScale": scale} for equation_id, scale in scales.items()]
    metadata = {
        "weakSystematicsExcludedCount": len(weak_names),
        "cleanHighCount": len(high_names),
        "scaleTraining": "one global scale per source equation, learned against locked v18 support on clean rows only",
    }
    return case_rows, shape_rows, scale_rows, metadata


def v19_source_equation_score_rows(case_rows: list[dict]) -> tuple[list[dict], str, dict]:
    score_rows = []
    clean_rows = [row for row in case_rows if row["set"] != "weak-systematics-excluded"]
    for equation_id in V19_SOURCE_EQUATION_IDS:
        rows = [row for row in clean_rows if row["equationId"] == equation_id]
        high = [row for row in rows if row["set"] == "clean-high-rmse"]
        protected = [row for row in rows if row["set"] == "clean-protected"]
        canonical_clean = safe_mean(parse_float(row["canonicalRmse"]) for row in rows)
        v18_clean = safe_mean(parse_float(row["lockedV18Rmse"]) for row in rows)
        source_clean = safe_mean(parse_float(row["sourceEquationRmse"]) for row in rows)
        canonical_high = safe_mean(parse_float(row["canonicalRmse"]) for row in high)
        v18_high = safe_mean(parse_float(row["lockedV18Rmse"]) for row in high)
        source_high = safe_mean(parse_float(row["sourceEquationRmse"]) for row in high)
        clean_retention = (canonical_clean - source_clean) / (canonical_clean - v18_clean) * 100.0 if abs(canonical_clean - v18_clean) > 1.0e-9 else math.nan
        high_retention = (canonical_high - source_high) / (canonical_high - v18_high) * 100.0 if abs(canonical_high - v18_high) > 1.0e-9 else math.nan
        score_rows.append(
            {
                "equationId": equation_id,
                "cleanCount": len(rows),
                "highCount": len(high),
                "protectedCount": len(protected),
                "cleanMeanRmse": source_clean,
                "cleanGainVsCanonicalPct": pct_improvement(canonical_clean, source_clean),
                "cleanLockedV18GainPct": pct_improvement(canonical_clean, v18_clean),
                "cleanV18RepairRetentionPct": clean_retention,
                "highMeanRmse": source_high,
                "highGainVsCanonicalPct": pct_improvement(canonical_high, source_high),
                "highLockedV18GainPct": pct_improvement(canonical_high, v18_high),
                "highV18RepairRetentionPct": high_retention,
                "meanAccelerationShapeRmse": safe_mean(parse_float(row["accelerationShapeRmse"]) for row in rows),
                "meanAccelerationFieldRmse": safe_mean(parse_float(row["accelerationFieldRmse"]) for row in rows),
                "protectedMaxRegressionVsV18KmS": max([parse_float(row["sourceMinusV18KmS"], 0.0) for row in protected] or [0.0]),
                "weakSystematicsLeakage": 0,
            }
        )
    best = min(score_rows, key=lambda row: (parse_float(row["meanAccelerationShapeRmse"], math.inf), -parse_float(row["highV18RepairRetentionPct"], -math.inf)))
    if parse_float(best["highV18RepairRetentionPct"], 0.0) >= 70.0 and parse_float(best["protectedMaxRegressionVsV18KmS"], math.inf) <= 0.25:
        verdict = "source equation bridge plausible"
    elif parse_float(best["highV18RepairRetentionPct"], 0.0) >= 45.0:
        verdict = "partial source equation bridge"
    else:
        verdict = "missing source variable"
    return score_rows, verdict, best


def write_v19_source_equation_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_v19_source_equation"
    if not V18_NFW_SHELF_ARTIFACT_PATH.exists():
        write_v18_nfw_gap_shelf_release_lock_artifacts(DEFAULT_OBSERVED_STATE_V18_38_NFW_SHELF_RELEASE_LOCK_OUT)
    case_rows, shape_rows, scale_rows, metadata = v19_source_equation_rows()
    score_rows, verdict, best = v19_source_equation_score_rows(case_rows)
    limit_rows = [
        {"check": "target", "status": "pass", "detail": "locked v18 motion-field acceleration is the target field; canonical/browser law unchanged"},
        {"check": "global normalization", "status": "pass", "detail": "one global scale per equation, trained on clean rows only; no per-galaxy fitting"},
        {"check": "forbidden inputs", "status": "pass", "detail": "no galaxy name, residual, raw RMSE, NFW parameter, MOND parameter, or branch label enters any source equation"},
        {"check": "weak/systematics leakage", "status": "pass", "detail": "weak/systematics rows excluded from normalization and framework-facing scores"},
        {"check": "Newtonian limit", "status": "candidate", "detail": "if the motion-field source tends to zero, a_total tends to a_bar"},
        {"check": "field-theory gap", "status": "open", "detail": "these are disk-limit radial source equations; a full covariant psi/Gamma action is still future work"},
    ]
    formula = {
        "candidateId": "mts-v19-source-equation-v1",
        "status": verdict,
        "target": "locked v18 motion-field acceleration a_MTS(r)",
        "canonicalMtsChanged": False,
        "browserChanged": False,
        "normalization": "single global scale per equation learned on clean rows only",
        "equations": {
            "stiffness-relaxation-equation": "m - ell^2 nabla_r^2 m = m_baryon",
            "curvature-memory-growth-equation": "Gamma_m(r)=Smooth_L[F(Sigma_b, dSigma_b/dr, memory_load)]",
            "motion-field-response-equation": "div(K[psi,Sigma_b] grad psi)=rho_b",
        },
        "forbiddenInputs": ["galaxy name", "raw residual", "raw RMSE", "NFW parameter", "MOND parameter", "branch labels", "weak/systematics fitting"],
    }
    write_csv(out_dir / f"{prefix}_scores.csv", score_rows)
    write_csv(out_dir / f"{prefix}_case_ledger.csv", case_rows)
    write_csv(out_dir / f"{prefix}_acceleration_shape.csv", shape_rows)
    write_csv(out_dir / f"{prefix}_global_scales.csv", scale_rows)
    write_csv(out_dir / f"{prefix}_limit_checks.csv", limit_rows)
    (out_dir / f"{prefix}_formula.json").write_text(json.dumps(json_clean(formula), indent=2, sort_keys=True), encoding="utf-8")

    equations_doc = [
        "# MTS v19.1 Source Equation Candidates",
        "",
        "The target field is the locked v18 disk-limit acceleration field:",
        "",
        "```text",
        "a_total(r) = a_bar(r) + a_MTS(r)",
        "a_MTS(r) = S_MTS(r) / r",
        "```",
        "",
        "This mode asks whether compact source equations can reproduce the shape of `a_MTS` without branch labels, galaxy names, residuals, RMSE, or competitor-fit parameters.",
        "",
        "## 1. Stiffness Relaxation Equation",
        "",
        "```text",
        "m(r) - ell^2 nabla_r^2 m(r) = m_baryon(r)",
        "u_m(r) = integral_0^r m(s) ds / integral_0^rout m(s) ds",
        "S_raw(r) = Gamma0 L_eff [1 - exp(-(u_m r_out / L_eff)^q)]",
        "```",
        "",
        "## 2. Curvature-Memory Growth Equation",
        "",
        "```text",
        "Gamma_m(r) = Smooth_L[F(Sigma_b, dSigma_b/dr, memory_load)]",
        "S_raw(r) = Gamma0 L_m [1 - exp(-(r/L_m)^q)] Gamma_m(r)",
        "```",
        "",
        "## 3. Motion-Field Response Equation",
        "",
        "```text",
        "div(K[psi,Sigma_b] grad psi) = rho_b",
        "S_raw(r) = Gamma0 L_eff [1 - exp(-(r/L_eff)^q)] B_psi(r)",
        "```",
        "",
        "Each equation receives one global normalization against the locked clean v18 acceleration field. There is no per-galaxy tuning.",
    ]
    (out_dir / f"{prefix}_equations.md").write_text("\n".join(equations_doc) + "\n", encoding="utf-8")

    report = [
        "# MTS v19.1 Source Equation Test",
        "",
        "This is a source-equation derivation test, not a new galaxy repair branch. Locked v18 remains unchanged.",
        "",
        f"Verdict: `{verdict}`.",
        f"Best equation: `{best['equationId']}`.",
        "",
        "## Scores",
        "",
        "| Equation | Shape RMSE | Clean retention | High retention | Protected regression vs v18 |",
        "| --- | ---: | ---: | ---: | ---: |",
    ]
    for row in score_rows:
        report.append(
            f"| {row['equationId']} | {fmt(row['meanAccelerationShapeRmse'])} | {fmt(row['cleanV18RepairRetentionPct'])}% | {fmt(row['highV18RepairRetentionPct'])}% | {fmt(row['protectedMaxRegressionVsV18KmS'])} |"
        )
    report.extend(
        [
            "",
            "## Interpretation",
            "",
            "A passing source equation would mean the locked MTS acceleration field is reproducible from a compact baryon-sourced motion-field equation. A failure means the galaxy law is still strong as a disk-limit law, but the current source variables are not enough to derive the v18 field structure.",
            "",
            "## Guardrails",
            "",
            "- No galaxy names enter any equation.",
            "- No raw residuals, raw RMSE, NFW, MOND, or branch labels enter any equation.",
            "- Weak/systematics cases are excluded from normalization.",
            "- No browser law is changed.",
            "",
            verdict,
        ]
    )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report) + "\n", encoding="utf-8")
    capsule = {
        "analysisName": "mts-v19-source-equation-v1",
        "verdict": verdict,
        "bestEquation": best,
        "summary": metadata,
        "canonicalMtsChanged": False,
        "browserChanged": False,
        "outputFiles": [
            f"{prefix}_report.md",
            f"{prefix}_equations.md",
            f"{prefix}_scores.csv",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_acceleration_shape.csv",
            f"{prefix}_global_scales.csv",
            f"{prefix}_limit_checks.csv",
            f"{prefix}_formula.json",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_v19sourceequation(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_V19_SOURCE_EQUATION_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_v19_source_equation_artifacts(out_dir)
    best = capsule["bestEquation"]
    print("MTS v19.1 source-equation test")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"best={best['equationId']}",
                f"shape_rmse={fmt(best['meanAccelerationShapeRmse'])}",
                f"clean_retention={fmt(best['cleanV18RepairRetentionPct'])}%",
                f"high_retention={fmt(best['highV18RepairRetentionPct'])}%",
                f"protected_reg={fmt(best['protectedMaxRegressionVsV18KmS'])}",
            ]
        )
    )
    print(f"Wrote v19 source-equation test to {out_dir.resolve()}")


V19_ADMISSIBILITY_FEATURES = [
    "memoryLoad",
    "u075",
    "uOut",
    "uMax",
    "fGasOut",
    "rOutOverH",
    "lGapOverH",
    "satFraction",
    "outerGasShare",
    "outerDiskShare",
    "outerBulgeShare",
    "barCurvAbs",
    "pointDensity",
]


def v19_admissibility_features(curve: dict) -> dict:
    state = v19_theory_kernel_state(curve)
    h = max(1.0e-9, curve.get("h", 0.0))
    return {
        "memoryLoad": parse_float(state.get("memoryLoad"), 0.0),
        "u075": parse_float(curve.get("lockedModelU075"), 0.0),
        "uOut": parse_float(curve.get("lockedModelUOut"), 0.0),
        "uMax": parse_float(curve.get("lockedModelUMax"), 0.0),
        "fGasOut": parse_float(curve.get("fGasOut"), 0.0),
        "rOutOverH": parse_float(curve.get("rOut"), 0.0) / h,
        "lGapOverH": parse_float(state.get("lGapOverH"), 0.0),
        "satFraction": parse_float(state.get("satFraction"), 0.0),
        "outerGasShare": parse_float(state.get("outerGasShare"), 0.0),
        "outerDiskShare": parse_float(state.get("outerDiskShare"), 0.0),
        "outerBulgeShare": parse_float(state.get("outerBulgeShare"), 0.0),
        "barCurvAbs": abs(parse_float(state.get("barCurv"), 0.0)),
        "pointDensity": parse_float(state.get("pointDensity"), 0.0),
    }


def v19_gate_value(features: dict, feature: str, threshold: float, direction: str) -> float:
    value = parse_float(features.get(feature), 0.0)
    span = max(1.0e-6, abs(threshold) * 0.20)
    if direction == "high":
        return clamp((value - (threshold - span)) / (2.0 * span), 0.0, 1.0)
    return clamp(((threshold + span) - value) / (2.0 * span), 0.0, 1.0)


def v19_admissibility_candidate_specs(curves: list[dict], weak_names: set[str]) -> list[dict]:
    rows = []
    clean_curves = [curve for curve in curves if curve["name"] not in weak_names]
    quantiles = [0.25, 0.33, 0.50, 0.66, 0.75]
    for feature in V19_ADMISSIBILITY_FEATURES:
        values = [v19_admissibility_features(curve)[feature] for curve in clean_curves]
        for q in quantiles:
            threshold = v19_quantile(values, q)
            for direction in ["high", "low"]:
                rows.append(
                    {
                        "gateId": f"{feature}-{direction}-q{int(q * 100)}",
                        "gateType": "single-feature-soft-gate",
                        "featureA": feature,
                        "directionA": direction,
                        "thresholdA": threshold,
                        "featureB": "",
                        "directionB": "",
                        "thresholdB": "",
                    }
                )
    # Small frozen pair set: enough to test source-side admissibility without broad threshold chasing.
    pair_features = [
        ("memoryLoad", "uOut"),
        ("memoryLoad", "outerGasShare"),
        ("uOut", "outerGasShare"),
        ("rOutOverH", "fGasOut"),
        ("lGapOverH", "barCurvAbs"),
        ("outerDiskShare", "pointDensity"),
    ]
    for feature_a, feature_b in pair_features:
        values_a = [v19_admissibility_features(curve)[feature_a] for curve in clean_curves]
        values_b = [v19_admissibility_features(curve)[feature_b] for curve in clean_curves]
        for qa, qb in [(0.50, 0.50), (0.66, 0.33), (0.33, 0.66)]:
            for direction_a, direction_b in [("high", "high"), ("high", "low"), ("low", "high")]:
                ta = v19_quantile(values_a, qa)
                tb = v19_quantile(values_b, qb)
                rows.append(
                    {
                        "gateId": f"{feature_a}-{direction_a}-q{int(qa*100)}__{feature_b}-{direction_b}-q{int(qb*100)}",
                        "gateType": "two-feature-soft-gate",
                        "featureA": feature_a,
                        "directionA": direction_a,
                        "thresholdA": ta,
                        "featureB": feature_b,
                        "directionB": direction_b,
                        "thresholdB": tb,
                    }
                )
    return rows


def v19_admissibility_gate(features: dict, spec: dict) -> float:
    gate_a = v19_gate_value(features, spec["featureA"], parse_float(spec["thresholdA"], 0.0), spec["directionA"])
    if spec["gateType"] == "single-feature-soft-gate":
        return gate_a
    gate_b = v19_gate_value(features, spec["featureB"], parse_float(spec["thresholdB"], 0.0), spec["directionB"])
    return gate_a * gate_b


def v19_admissibility_scale(curves: list[dict], weak_names: set[str], supports_by_name: dict[str, list[float]], spec: dict) -> float:
    numerator = 0.0
    denominator = 0.0
    for curve in curves:
        if curve["name"] in weak_names:
            continue
        target = supports_by_name.get(curve["name"], [])
        if len(target) != len(curve["points"]):
            continue
        raw, _ = v19_source_raw_supports(curve, "curvature-memory-growth-equation")
        gate = v19_admissibility_gate(v19_admissibility_features(curve), spec)
        for raw_value, target_value in zip(raw, target):
            candidate = max(0.0, raw_value) * gate
            numerator += candidate * max(0.0, target_value)
            denominator += candidate * candidate
    return numerator / denominator if denominator > 1.0e-12 else 0.0


def v19_admissibility_score_spec(curves: list[dict], weak_names: set[str], high_names: set[str], supports_by_name: dict[str, list[float]], spec: dict) -> tuple[dict, list[dict]]:
    scale = v19_admissibility_scale(curves, weak_names, supports_by_name, spec)
    case_rows = []
    for curve in curves:
        target = supports_by_name.get(curve["name"], [])
        if len(target) != len(curve["points"]):
            continue
        set_name = "weak-systematics-excluded" if curve["name"] in weak_names else ("clean-high-rmse" if curve["name"] in high_names else "clean-protected")
        raw, _ = v19_source_raw_supports(curve, "curvature-memory-growth-equation")
        features = v19_admissibility_features(curve)
        gate = v19_admissibility_gate(features, spec)
        supports = [max(0.0, scale * gate * value) for value in raw]
        score = v18_competitor_support_score(curve, supports)
        target_score = v18_competitor_support_score(curve, target)
        canonical = v18_competitor_support_score(curve, v18_competitor_canonical_supports(curve))
        target_gain = pct_improvement(canonical["rmse"], target_score["rmse"])
        candidate_gain = pct_improvement(canonical["rmse"], score["rmse"])
        shape = v19_source_acceleration_shape_metrics(curve, target, supports)
        case_rows.append(
            {
                "galaxy": curve["name"],
                "set": set_name,
                "gateId": spec["gateId"],
                "gateType": spec["gateType"],
                "gateValue": gate,
                "globalScale": scale,
                "canonicalRmse": canonical["rmse"],
                "lockedV18Rmse": target_score["rmse"],
                "admissibleSourceRmse": score["rmse"],
                "sourceMinusV18KmS": score["rmse"] - target_score["rmse"],
                "gainVsCanonicalPct": candidate_gain,
                "v18RepairRetentionPct": candidate_gain / target_gain * 100.0 if abs(target_gain) > 1.0e-9 else math.nan,
                **shape,
                **features,
            }
        )
    clean = [row for row in case_rows if row["set"] != "weak-systematics-excluded"]
    high = [row for row in clean if row["set"] == "clean-high-rmse"]
    protected = [row for row in clean if row["set"] == "clean-protected"]
    canonical_clean = safe_mean(parse_float(row["canonicalRmse"]) for row in clean)
    v18_clean = safe_mean(parse_float(row["lockedV18Rmse"]) for row in clean)
    candidate_clean = safe_mean(parse_float(row["admissibleSourceRmse"]) for row in clean)
    canonical_high = safe_mean(parse_float(row["canonicalRmse"]) for row in high)
    v18_high = safe_mean(parse_float(row["lockedV18Rmse"]) for row in high)
    candidate_high = safe_mean(parse_float(row["admissibleSourceRmse"]) for row in high)
    clean_retention = (canonical_clean - candidate_clean) / (canonical_clean - v18_clean) * 100.0 if abs(canonical_clean - v18_clean) > 1.0e-9 else math.nan
    high_retention = (canonical_high - candidate_high) / (canonical_high - v18_high) * 100.0 if abs(canonical_high - v18_high) > 1.0e-9 else math.nan
    metric = {
        **spec,
        "globalScale": scale,
        "cleanMeanRmse": candidate_clean,
        "cleanV18RepairRetentionPct": clean_retention,
        "highMeanRmse": candidate_high,
        "highV18RepairRetentionPct": high_retention,
        "meanAccelerationShapeRmse": safe_mean(parse_float(row["accelerationShapeRmse"]) for row in clean),
        "protectedMaxRegressionVsV18KmS": max([parse_float(row["sourceMinusV18KmS"], 0.0) for row in protected] or [0.0]),
        "protectedMeanRegressionVsV18KmS": safe_mean(max(0.0, parse_float(row["sourceMinusV18KmS"], 0.0)) for row in protected),
        "weakSystematicsLeakage": 0,
    }
    return metric, case_rows


def write_v19_source_admissibility_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_v19_source_admissibility"
    context = observed_state_candidate_context()
    curves = context["curves"]
    weak_names = set(context["weakNames"])
    high_names = set(context["highNames"])
    supports_by_name = v18_39_remaining_nfw_gap_artifact_supports()
    specs = v19_admissibility_candidate_specs(curves, weak_names)
    score_rows = []
    best_cases: list[dict] = []
    for spec in specs:
        metric, cases = v19_admissibility_score_spec(curves, weak_names, high_names, supports_by_name, spec)
        score_rows.append(metric)
    best = min(
        score_rows,
        key=lambda row: (
            parse_float(row["protectedMaxRegressionVsV18KmS"], math.inf),
            -parse_float(row["highV18RepairRetentionPct"], -math.inf),
            parse_float(row["meanAccelerationShapeRmse"], math.inf),
        ),
    )
    _, best_cases = v19_admissibility_score_spec(curves, weak_names, high_names, supports_by_name, best)
    protected_false = sorted(
        [row for row in best_cases if row["set"] == "clean-protected"],
        key=lambda row: parse_float(row["sourceMinusV18KmS"], 0.0),
        reverse=True,
    )[:25]
    high_hits = sorted(
        [row for row in best_cases if row["set"] == "clean-high-rmse"],
        key=lambda row: parse_float(row["v18RepairRetentionPct"], 0.0),
        reverse=True,
    )[:25]
    if parse_float(best["protectedMaxRegressionVsV18KmS"], math.inf) <= 0.25 and parse_float(best["highV18RepairRetentionPct"], 0.0) >= 50.0:
        verdict = "source admissibility variable found"
    elif parse_float(best["protectedMaxRegressionVsV18KmS"], math.inf) <= 3.0 and parse_float(best["highV18RepairRetentionPct"], 0.0) >= 35.0:
        verdict = "partial admissibility discriminator"
    else:
        verdict = "current source variables not sufficient"
    write_csv(out_dir / f"{prefix}_scores.csv", score_rows)
    write_csv(out_dir / f"{prefix}_case_ledger.csv", best_cases)
    write_csv(out_dir / f"{prefix}_protected_false_activation.csv", protected_false)
    write_csv(out_dir / f"{prefix}_high_retained_hits.csv", high_hits)
    formula = {
        "candidateId": "mts-v19-source-admissibility-v1",
        "status": verdict,
        "baseEquation": "curvature-memory-growth-equation",
        "bestGate": best,
        "canonicalMtsChanged": False,
        "browserChanged": False,
        "forbiddenInputs": ["galaxy name", "raw residual", "raw RMSE", "NFW parameter", "MOND parameter", "weak/systematics fitting"],
    }
    (out_dir / f"{prefix}_formula.json").write_text(json.dumps(json_clean(formula), indent=2, sort_keys=True), encoding="utf-8")
    report = [
        "# MTS v19.2 Source Admissibility Test",
        "",
        "The v19.1 source equations over-activated protected clean galaxies. This pass asks whether a pre-residual source variable can act as an admissibility factor for the curvature-memory equation.",
        "",
        f"Verdict: `{verdict}`.",
        f"Best gate: `{best['gateId']}`.",
        f"High v18 repair retention: `{fmt(best['highV18RepairRetentionPct'])}%`.",
        f"Clean v18 repair retention: `{fmt(best['cleanV18RepairRetentionPct'])}%`.",
        f"Protected max regression vs v18: `{fmt(best['protectedMaxRegressionVsV18KmS'])}` km/s.",
        f"Mean acceleration shape RMSE: `{fmt(best['meanAccelerationShapeRmse'])}`.",
        "",
        "## What This Means",
        "",
        "If the best gate is weak, the current local state/profile variables still do not contain the missing field-source admissibility condition. If it is strong, the next step is to turn that gate into a physical source term rather than a threshold branch.",
        "",
        verdict,
    ]
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report) + "\n", encoding="utf-8")
    capsule = {
        "analysisName": "mts-v19-source-admissibility-v1",
        "verdict": verdict,
        "bestGate": best,
        "canonicalMtsChanged": False,
        "browserChanged": False,
        "outputFiles": [
            f"{prefix}_report.md",
            f"{prefix}_scores.csv",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_protected_false_activation.csv",
            f"{prefix}_high_retained_hits.csv",
            f"{prefix}_formula.json",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_v19sourceadmissibility(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_V19_SOURCE_ADMISSIBILITY_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_v19_source_admissibility_artifacts(out_dir)
    best = capsule["bestGate"]
    print("MTS v19.2 source-admissibility test")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"best_gate={best['gateId']}",
                f"high_retention={fmt(best['highV18RepairRetentionPct'])}%",
                f"clean_retention={fmt(best['cleanV18RepairRetentionPct'])}%",
                f"protected_reg={fmt(best['protectedMaxRegressionVsV18KmS'])}",
            ]
        )
    )
    print(f"Wrote v19 source-admissibility test to {out_dir.resolve()}")


V19_PROVENANCE_FEATURES = [
    "qualityCode",
    "inclinationDeg",
    "inclinationUncertaintyDeg",
    "distanceUncertaintyFraction",
    "hubbleType",
    "luminosity36_1e9Lsun",
    "hiMass_1e9Msun",
    "hiRadiusOverRout",
    "vflatKmS",
    "vflatUncertaintyFraction",
]


def v19_source_provenance_features(curve: dict, table1_by_name: dict[str, dict]) -> dict:
    table = table1_by_name.get(curve["name"], {})
    r_out = max(1.0e-9, parse_float(curve.get("rOut"), 0.0))
    distance = parse_float(table.get("distanceMpc"), math.nan)
    distance_unc = parse_float(table.get("distanceUncertaintyMpc"), math.nan)
    vflat = parse_float(table.get("vflatKmS"), math.nan)
    vflat_unc = parse_float(table.get("vflatUncertaintyKmS"), math.nan)
    refs = str(table.get("rotationCurveRefCodes", ""))
    return {
        "qualityCode": parse_float(table.get("qualityCode"), math.nan),
        "qualityLabel": table.get("qualityLabel", ""),
        "inclinationDeg": parse_float(table.get("inclinationDeg"), math.nan),
        "inclinationUncertaintyDeg": parse_float(table.get("inclinationUncertaintyDeg"), math.nan),
        "distanceMpc": distance,
        "distanceUncertaintyMpc": distance_unc,
        "distanceUncertaintyFraction": distance_unc / distance if math.isfinite(distance) and distance > 0 else math.nan,
        "distanceMethod": table.get("distanceMethod", ""),
        "distanceMethodCode": table.get("distanceMethodCode", ""),
        "hubbleType": parse_float(table.get("hubbleType"), math.nan),
        "luminosity36_1e9Lsun": parse_float(table.get("luminosity36_1e9Lsun"), math.nan),
        "hiMass_1e9Msun": parse_float(table.get("hiMass_1e9Msun"), math.nan),
        "hiRadiusKpc": parse_float(table.get("hiRadiusKpc"), math.nan),
        "hiRadiusOverRout": parse_float(table.get("hiRadiusKpc"), math.nan) / r_out if r_out > 0 else math.nan,
        "vflatKmS": vflat,
        "vflatUncertaintyKmS": vflat_unc,
        "vflatUncertaintyFraction": vflat_unc / vflat if math.isfinite(vflat) and vflat > 0 else math.nan,
        "rotationCurveRefCodes": refs,
        "rotationCurveRefCount": len([item for item in refs.replace(",", ";").split(";") if item.strip()]),
    }


def v19_source_provenance_case_rows() -> list[dict]:
    context = observed_state_candidate_context()
    table1_by_name = v18_mass_scale_table1()[0]
    curves_by_name = {curve["name"]: curve for curve in context["curves"]}
    _, best_cases = v19_admissibility_score_spec(
        context["curves"],
        set(context["weakNames"]),
        set(context["highNames"]),
        v18_39_remaining_nfw_gap_artifact_supports(),
        min(
            [
                v19_admissibility_score_spec(
                    context["curves"],
                    set(context["weakNames"]),
                    set(context["highNames"]),
                    v18_39_remaining_nfw_gap_artifact_supports(),
                    spec,
                )[0]
                for spec in v19_admissibility_candidate_specs(context["curves"], set(context["weakNames"]))
            ],
            key=lambda row: (
                parse_float(row["protectedMaxRegressionVsV18KmS"], math.inf),
                -parse_float(row["highV18RepairRetentionPct"], -math.inf),
                parse_float(row["meanAccelerationShapeRmse"], math.inf),
            ),
        ),
    )
    rows = []
    for row in best_cases:
        curve = curves_by_name.get(row["galaxy"])
        if not curve:
            continue
        source_minus = parse_float(row.get("sourceMinusV18KmS"), 0.0)
        retention = parse_float(row.get("v18RepairRetentionPct"), math.nan)
        if row["set"] == "clean-protected" and source_minus > 3.0:
            class_label = "protected-false-activation"
        elif row["set"] == "clean-high-rmse" and retention >= 50.0 and source_minus <= 5.0:
            class_label = "true-high-retained"
        elif row["set"] == "clean-high-rmse":
            class_label = "high-not-retained"
        else:
            class_label = "other-clean"
        rows.append(
            {
                **row,
                **v19_source_provenance_features(curve, table1_by_name),
                "sourceClass": class_label,
            }
        )
    return rows


def v19_source_provenance_threshold_scores(rows: list[dict]) -> list[dict]:
    labeled = [row for row in rows if row["sourceClass"] in {"protected-false-activation", "true-high-retained"}]
    false_rows = [row for row in labeled if row["sourceClass"] == "protected-false-activation"]
    true_rows = [row for row in labeled if row["sourceClass"] == "true-high-retained"]
    out = []
    for feature in V19_PROVENANCE_FEATURES:
        values = [parse_float(row.get(feature), math.nan) for row in labeled]
        values = [value for value in values if math.isfinite(value)]
        if len(values) < 4:
            continue
        thresholds = sorted({v19_quantile(values, q) for q in [0.20, 0.33, 0.50, 0.66, 0.80]})
        for threshold in thresholds:
            for direction in ["high", "low"]:
                def hit(row: dict) -> bool:
                    value = parse_float(row.get(feature), math.nan)
                    if not math.isfinite(value):
                        return False
                    return value >= threshold if direction == "high" else value <= threshold
                false_recall = sum(1 for row in false_rows if hit(row)) / len(false_rows) if false_rows else 0.0
                true_hit = sum(1 for row in true_rows if hit(row)) / len(true_rows) if true_rows else 0.0
                utility = false_recall - true_hit
                out.append(
                    {
                        "feature": feature,
                        "direction": direction,
                        "threshold": threshold,
                        "falseActivationCount": len(false_rows),
                        "trueHighRetainedCount": len(true_rows),
                        "falseActivationRecall": false_recall,
                        "trueHighSuppressionRate": true_hit,
                        "utilityFalseRecallMinusTrueSuppression": utility,
                    }
                )
    return sorted(out, key=lambda row: parse_float(row["utilityFalseRecallMinusTrueSuppression"], -math.inf), reverse=True)


def write_v19_source_provenance_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_v19_source_provenance"
    rows = v19_source_provenance_case_rows()
    threshold_rows = v19_source_provenance_threshold_scores(rows)
    false_rows = [row for row in rows if row["sourceClass"] == "protected-false-activation"]
    true_rows = [row for row in rows if row["sourceClass"] == "true-high-retained"]
    top = threshold_rows[0] if threshold_rows else {}
    serious = (
        parse_float(top.get("falseActivationRecall"), 0.0) >= 0.70
        and parse_float(top.get("trueHighSuppressionRate"), 1.0) <= 0.30
        and parse_float(top.get("utilityFalseRecallMinusTrueSuppression"), 0.0) >= 0.40
    )
    verdict = "provenance admissibility candidate" if serious else "provenance alone not sufficient"
    group_rows = []
    for label, group in [("protected-false-activation", false_rows), ("true-high-retained", true_rows)]:
        group_rows.append(
            {
                "sourceClass": label,
                "count": len(group),
                **{f"median_{feature}": safe_median(parse_float(row.get(feature), math.nan) for row in group) for feature in V19_PROVENANCE_FEATURES},
            }
        )
    write_csv(out_dir / f"{prefix}_case_ledger.csv", rows)
    write_csv(out_dir / f"{prefix}_threshold_scores.csv", threshold_rows)
    write_csv(out_dir / f"{prefix}_group_contrast.csv", group_rows)
    write_csv(out_dir / f"{prefix}_false_activation_cases.csv", sorted(false_rows, key=lambda row: parse_float(row["sourceMinusV18KmS"], 0.0), reverse=True))
    formula = {
        "candidateId": "mts-v19-source-provenance-discriminator-v1",
        "status": verdict,
        "bestThreshold": top,
        "canonicalMtsChanged": False,
        "browserChanged": False,
        "inputFamily": "official SPARC Table1 provenance/quality metadata only",
        "forbiddenInputs": ["galaxy name", "raw residual", "raw RMSE", "NFW parameter", "MOND parameter", "weak/systematics fitting"],
    }
    (out_dir / f"{prefix}_formula.json").write_text(json.dumps(json_clean(formula), indent=2, sort_keys=True), encoding="utf-8")
    report = [
        "# MTS v19.3 Source Provenance Discriminator",
        "",
        "This mode tests whether official SPARC provenance/quality metadata separates source-equation false activations from true high-RMSE retained cases.",
        "",
        f"Verdict: `{verdict}`.",
        f"Protected false activations: `{len(false_rows)}`.",
        f"True high retained cases: `{len(true_rows)}`.",
        "",
        "## Best Threshold",
        "",
    ]
    if top:
        report.extend(
            [
                f"- Feature: `{top['feature']}`.",
                f"- Direction: `{top['direction']}`.",
                f"- Threshold: `{fmt(top['threshold'])}`.",
                f"- False activation recall: `{fmt(100*parse_float(top['falseActivationRecall']))}%`.",
                f"- True high suppression rate: `{fmt(100*parse_float(top['trueHighSuppressionRate']))}%`.",
                f"- Utility: `{fmt(top['utilityFalseRecallMinusTrueSuppression'])}`.",
            ]
        )
    report.extend(
        [
            "",
            "## Interpretation",
            "",
            "If this passes, provenance/quality can be carried as an observational admissibility gate for source-equation testing. If it fails, the missing variable is likely physical morphology/kinematics not present in SPARC Table1.",
            "",
            verdict,
        ]
    )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report) + "\n", encoding="utf-8")
    capsule = {
        "analysisName": "mts-v19-source-provenance-discriminator-v1",
        "verdict": verdict,
        "protectedFalseActivationCount": len(false_rows),
        "trueHighRetainedCount": len(true_rows),
        "bestThreshold": top,
        "canonicalMtsChanged": False,
        "browserChanged": False,
        "outputFiles": [
            f"{prefix}_report.md",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_threshold_scores.csv",
            f"{prefix}_group_contrast.csv",
            f"{prefix}_false_activation_cases.csv",
            f"{prefix}_formula.json",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_v19sourceprovenance(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_V19_SOURCE_PROVENANCE_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_v19_source_provenance_artifacts(out_dir)
    best = capsule["bestThreshold"]
    print("MTS v19.3 source-provenance discriminator")
    print(f"verdict={capsule['verdict']}")
    if best:
        print(
            "\t".join(
                [
                    f"best={best['feature']} {best['direction']} {fmt(best['threshold'])}",
                    f"false_recall={fmt(100*parse_float(best['falseActivationRecall']))}%",
                    f"true_suppression={fmt(100*parse_float(best['trueHighSuppressionRate']))}%",
                ]
            )
        )
    print(f"Wrote v19 source-provenance discriminator to {out_dir.resolve()}")


V19_SOURCE_REGIME_IDS = [
    "mass-coherence",
    "mass-coherence-route-loading",
    "mass-coherence-disk-regularity",
    "two-regime-dwarf-suppressed",
]


def v19_regime_sigmoid(value: float, center: float, width: float) -> float:
    if not math.isfinite(value):
        return 0.0
    safe_width = max(1.0e-6, width)
    arg = clamp((value - center) / safe_width, -40.0, 40.0)
    return 1.0 / (1.0 + math.exp(-arg))


def v19_source_regime_activation(curve: dict, regime_id: str, table1_by_name: dict[str, dict]) -> tuple[float, dict]:
    prov = v19_source_provenance_features(curve, table1_by_name)
    local = v19_admissibility_features(curve)
    lum = max(1.0e-9, parse_float(prov.get("luminosity36_1e9Lsun"), 0.0))
    log_lum = math.log10(lum)
    h_type = parse_float(prov.get("hubbleType"), math.nan)
    vflat = parse_float(prov.get("vflatKmS"), math.nan)
    hi_mass = max(1.0e-9, parse_float(prov.get("hiMass_1e9Msun"), 0.0))
    log_hi = math.log10(hi_mass)
    quality = parse_float(prov.get("qualityCode"), math.nan)
    inc_unc = parse_float(prov.get("inclinationUncertaintyDeg"), math.nan)
    route = curve.get("lockedModelRoute", "")

    mass_coherence = v19_regime_sigmoid(log_lum, math.log10(38.33462), 0.35)
    dwarf_suppression = 1.0 - clamp(
        0.45 * (1.0 - mass_coherence)
        + 0.25 * v19_regime_sigmoid(h_type, 8.5, 1.0)
        + 0.20 * (1.0 - v19_regime_sigmoid(log_hi, math.log10(1.291), 0.45))
        + 0.10 * v19_regime_sigmoid(2.0 - quality if math.isfinite(quality) else 0.0, 0.0, 1.0),
        0.0,
        0.95,
    )
    route_loading = clamp(
        0.38 * clamp(local["memoryLoad"] / 6.0, 0.0, 1.0)
        + 0.24 * clamp(local["uOut"] / 0.45, 0.0, 1.0)
        + 0.18 * clamp(local["lGapOverH"] / 1.4, 0.0, 1.0)
        + 0.20 * (1.0 if route == "low-load" else 0.65),
        0.0,
        1.0,
    )
    disk_regularity = clamp(
        0.34 * v19_regime_sigmoid(vflat, 120.0, 45.0)
        + 0.24 * (1.0 - clamp((inc_unc if math.isfinite(inc_unc) else 8.0) / 12.0, 0.0, 1.0))
        + 0.22 * clamp(local["pointDensity"] / 1.6, 0.0, 1.0)
        + 0.20 * clamp(local["outerDiskShare"] / 0.60, 0.0, 1.0),
        0.0,
        1.0,
    )

    if regime_id == "mass-coherence":
        activation = mass_coherence
    elif regime_id == "mass-coherence-route-loading":
        activation = mass_coherence * route_loading
    elif regime_id == "mass-coherence-disk-regularity":
        activation = mass_coherence * disk_regularity
    elif regime_id == "two-regime-dwarf-suppressed":
        activation = dwarf_suppression * clamp(0.55 * route_loading + 0.45 * disk_regularity, 0.0, 1.0)
    else:
        raise ValueError(f"Unknown source regime: {regime_id}")

    return clamp(activation, 0.0, 1.0), {
        **prov,
        **local,
        "massCoherence": mass_coherence,
        "dwarfSuppression": dwarf_suppression,
        "routeLoading": route_loading,
        "diskRegularity": disk_regularity,
    }


def v19_source_regime_scale(curves: list[dict], weak_names: set[str], supports_by_name: dict[str, list[float]], table1_by_name: dict[str, dict], regime_id: str) -> float:
    numerator = 0.0
    denominator = 0.0
    for curve in curves:
        if curve["name"] in weak_names:
            continue
        target = supports_by_name.get(curve["name"], [])
        if len(target) != len(curve["points"]):
            continue
        raw, _ = v19_source_raw_supports(curve, "curvature-memory-growth-equation")
        activation, _ = v19_source_regime_activation(curve, regime_id, table1_by_name)
        for raw_value, target_value in zip(raw, target):
            candidate = max(0.0, raw_value) * activation
            numerator += candidate * max(0.0, target_value)
            denominator += candidate * candidate
    return numerator / denominator if denominator > 1.0e-12 else 0.0


def v19_source_regime_case_rows(regime_id: str) -> tuple[list[dict], dict]:
    context = observed_state_candidate_context()
    curves = context["curves"]
    weak_names = set(context["weakNames"])
    high_names = set(context["highNames"])
    table1_by_name = v18_mass_scale_table1()[0]
    supports_by_name = v18_39_remaining_nfw_gap_artifact_supports()
    scale = v19_source_regime_scale(curves, weak_names, supports_by_name, table1_by_name, regime_id)
    rows = []
    for curve in curves:
        target = supports_by_name.get(curve["name"], [])
        if len(target) != len(curve["points"]):
            continue
        raw, _ = v19_source_raw_supports(curve, "curvature-memory-growth-equation")
        activation, features = v19_source_regime_activation(curve, regime_id, table1_by_name)
        supports = [max(0.0, scale * activation * value) for value in raw]
        score = v18_competitor_support_score(curve, supports)
        target_score = v18_competitor_support_score(curve, target)
        canonical = v18_competitor_support_score(curve, v18_competitor_canonical_supports(curve))
        target_gain = pct_improvement(canonical["rmse"], target_score["rmse"])
        candidate_gain = pct_improvement(canonical["rmse"], score["rmse"])
        set_name = "weak-systematics-excluded" if curve["name"] in weak_names else ("clean-high-rmse" if curve["name"] in high_names else "clean-protected")
        rows.append(
            {
                "galaxy": curve["name"],
                "set": set_name,
                "regimeId": regime_id,
                "activation": activation,
                "globalScale": scale,
                "canonicalRmse": canonical["rmse"],
                "lockedV18Rmse": target_score["rmse"],
                "regimeSourceRmse": score["rmse"],
                "sourceMinusV18KmS": score["rmse"] - target_score["rmse"],
                "gainVsCanonicalPct": candidate_gain,
                "v18RepairRetentionPct": candidate_gain / target_gain * 100.0 if abs(target_gain) > 1.0e-9 else math.nan,
                **v19_source_acceleration_shape_metrics(curve, target, supports),
                **features,
            }
        )
    return rows, {"globalScale": scale}


def v19_source_regime_score_rows() -> tuple[list[dict], list[dict], str, dict]:
    all_case_rows = []
    score_rows = []
    for regime_id in V19_SOURCE_REGIME_IDS:
        rows, meta = v19_source_regime_case_rows(regime_id)
        all_case_rows.extend(rows)
        clean = [row for row in rows if row["set"] != "weak-systematics-excluded"]
        high = [row for row in clean if row["set"] == "clean-high-rmse"]
        protected = [row for row in clean if row["set"] == "clean-protected"]
        canonical_clean = safe_mean(parse_float(row["canonicalRmse"]) for row in clean)
        v18_clean = safe_mean(parse_float(row["lockedV18Rmse"]) for row in clean)
        candidate_clean = safe_mean(parse_float(row["regimeSourceRmse"]) for row in clean)
        canonical_high = safe_mean(parse_float(row["canonicalRmse"]) for row in high)
        v18_high = safe_mean(parse_float(row["lockedV18Rmse"]) for row in high)
        candidate_high = safe_mean(parse_float(row["regimeSourceRmse"]) for row in high)
        score_rows.append(
            {
                "regimeId": regime_id,
                "globalScale": meta["globalScale"],
                "cleanMeanRmse": candidate_clean,
                "cleanGainVsCanonicalPct": pct_improvement(canonical_clean, candidate_clean),
                "cleanV18RepairRetentionPct": (canonical_clean - candidate_clean) / (canonical_clean - v18_clean) * 100.0 if abs(canonical_clean - v18_clean) > 1.0e-9 else math.nan,
                "highMeanRmse": candidate_high,
                "highGainVsCanonicalPct": pct_improvement(canonical_high, candidate_high),
                "highV18RepairRetentionPct": (canonical_high - candidate_high) / (canonical_high - v18_high) * 100.0 if abs(canonical_high - v18_high) > 1.0e-9 else math.nan,
                "protectedMaxRegressionVsV18KmS": max([parse_float(row["sourceMinusV18KmS"], 0.0) for row in protected] or [0.0]),
                "protectedMeanRegressionVsV18KmS": safe_mean(max(0.0, parse_float(row["sourceMinusV18KmS"], 0.0)) for row in protected),
                "meanAccelerationShapeRmse": safe_mean(parse_float(row["accelerationShapeRmse"]) for row in clean),
                "activeHighCount": sum(1 for row in high if parse_float(row["activation"], 0.0) >= 0.5),
                "activeProtectedCount": sum(1 for row in protected if parse_float(row["activation"], 0.0) >= 0.5),
                "weakSystematicsLeakage": 0,
            }
        )
    best = min(
        score_rows,
        key=lambda row: (
            parse_float(row["protectedMaxRegressionVsV18KmS"], math.inf),
            -parse_float(row["highV18RepairRetentionPct"], -math.inf),
            parse_float(row["meanAccelerationShapeRmse"], math.inf),
        ),
    )
    if parse_float(best["protectedMaxRegressionVsV18KmS"], math.inf) <= 3.0 and parse_float(best["highV18RepairRetentionPct"], 0.0) >= 45.0:
        verdict = "source-regime candidate for review"
    elif parse_float(best["highV18RepairRetentionPct"], 0.0) >= 25.0:
        verdict = "source-regime anatomy only"
    else:
        verdict = "mass/coherence gate insufficient"
    return score_rows, all_case_rows, verdict, best


def write_v19_source_regime_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_v19_source_regime"
    score_rows, case_rows, verdict, best = v19_source_regime_score_rows()
    best_cases = [row for row in case_rows if row["regimeId"] == best["regimeId"]]
    false_rows = sorted(
        [row for row in best_cases if row["set"] == "clean-protected" and parse_float(row["sourceMinusV18KmS"], 0.0) > 3.0],
        key=lambda row: parse_float(row["sourceMinusV18KmS"], 0.0),
        reverse=True,
    )
    hit_rows = sorted(
        [row for row in best_cases if row["set"] == "clean-high-rmse" and parse_float(row["v18RepairRetentionPct"], 0.0) >= 50.0],
        key=lambda row: parse_float(row["v18RepairRetentionPct"], 0.0),
        reverse=True,
    )
    write_csv(out_dir / f"{prefix}_scores.csv", score_rows)
    write_csv(out_dir / f"{prefix}_case_ledger.csv", case_rows)
    write_csv(out_dir / f"{prefix}_false_activation_ledger.csv", false_rows)
    write_csv(out_dir / f"{prefix}_retained_high_ledger.csv", hit_rows)
    formula = {
        "candidateId": "mts-v19-source-regime-candidate-v1",
        "status": verdict,
        "bestRegime": best,
        "baseEquation": "curvature-memory-growth-equation",
        "physicalQuestion": "does baryonic scale/coherence control whether the motion-field memory source may load?",
        "canonicalMtsChanged": False,
        "browserChanged": False,
        "forbiddenInputs": ["galaxy name", "raw residual", "raw RMSE", "NFW parameter", "MOND parameter", "weak/systematics fitting"],
    }
    (out_dir / f"{prefix}_formula.json").write_text(json.dumps(json_clean(formula), indent=2, sort_keys=True), encoding="utf-8")
    report = [
        "# MTS v19.4 Source Regime Candidate",
        "",
        "This tests whether the source-equation failure is controlled by a baryonic scale/coherence regime. It does not alter v18 or the browser law.",
        "",
        f"Verdict: `{verdict}`.",
        f"Best regime: `{best['regimeId']}`.",
        f"High v18 repair retention: `{fmt(best['highV18RepairRetentionPct'])}%`.",
        f"Clean v18 repair retention: `{fmt(best['cleanV18RepairRetentionPct'])}%`.",
        f"Protected max regression vs v18: `{fmt(best['protectedMaxRegressionVsV18KmS'])}` km/s.",
        f"Active high cases: `{best['activeHighCount']}`.",
        f"Active protected cases: `{best['activeProtectedCount']}`.",
        "",
        "## Interpretation",
        "",
        "This is aimed at the physical MTS question: what condition lets baryonic structure load the motion field? If mass/coherence gates fail, the missing condition is not simple luminosity or SPARC Table1 provenance; it is likely a dynamical morphology/kinematic coherence variable.",
        "",
        verdict,
    ]
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report) + "\n", encoding="utf-8")
    capsule = {
        "analysisName": "mts-v19-source-regime-candidate-v1",
        "verdict": verdict,
        "bestRegime": best,
        "falseActivationCount": len(false_rows),
        "retainedHighCount": len(hit_rows),
        "canonicalMtsChanged": False,
        "browserChanged": False,
        "outputFiles": [
            f"{prefix}_report.md",
            f"{prefix}_scores.csv",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_false_activation_ledger.csv",
            f"{prefix}_retained_high_ledger.csv",
            f"{prefix}_formula.json",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_v19sourceregime(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_V19_SOURCE_REGIME_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_v19_source_regime_artifacts(out_dir)
    best = capsule["bestRegime"]
    print("MTS v19.4 source-regime candidate")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"best={best['regimeId']}",
                f"high_retention={fmt(best['highV18RepairRetentionPct'])}%",
                f"clean_retention={fmt(best['cleanV18RepairRetentionPct'])}%",
                f"protected_reg={fmt(best['protectedMaxRegressionVsV18KmS'])}",
            ]
        )
    )
    print(f"Wrote v19 source-regime candidate to {out_dir.resolve()}")


V19_FIELD_COHERENCE_IDS = [
    "gradient-coherence-denominator",
    "curvature-resistance-denominator",
    "admissible-smoothing-coherence",
    "odd-kernel-balance",
]


def v19_first_derivative(values: list[float], radii: list[float]) -> list[float]:
    if len(values) < 2:
        return [0.0 for _ in values]
    out: list[float] = []
    for index, value in enumerate(values):
        if index == 0:
            dr = max(1.0e-9, radii[1] - radii[0])
            out.append((values[1] - value) / dr)
        elif index == len(values) - 1:
            dr = max(1.0e-9, radii[-1] - radii[-2])
            out.append((value - values[-2]) / dr)
        else:
            dr = max(1.0e-9, radii[index + 1] - radii[index - 1])
            out.append((values[index + 1] - values[index - 1]) / dr)
    return out


def v19_field_coherence_features(curve: dict) -> dict:
    radii = [max(1.0e-9, parse_float(point.get("r"), 0.0)) for point in curve["points"]]
    if len(radii) < 4:
        return {
            "gradientCoherence": 0.0,
            "curvatureResistance": 1.0,
            "admissibleSmoothness": 0.0,
            "oddKernelBalance": 0.0,
            "monotonicFraction": 0.0,
            "gradientSignChanges": 0,
            "roughness": 1.0,
            "innerOuterGradientContrast": 0.0,
        }
    state = v19_theory_kernel_state(curve)
    r_out = max(1.0e-9, curve.get("rOut", radii[-1]))
    l_eff = max(1.0e-9, state["lExact"])
    vbar2 = [max(0.0, parse_float(point.get("bar2"), 0.0)) for point in curve["points"]]
    smooth_len = max(0.12 * r_out, 0.18 * l_eff, 0.15 * parse_float(curve.get("h"), 1.0))
    smooth = v19_source_smooth(vbar2, radii, smooth_len)
    grad = v19_first_derivative(smooth, radii)
    curv = v19_source_second_derivative(smooth, radii)
    grad_abs = [abs(value) for value in grad]
    curv_abs = [abs(value) for value in curv]
    grad_scale = safe_mean(grad_abs) + 1.0e-9
    curv_scale = safe_mean(curv_abs) + 1.0e-9
    roughness = clamp(curv_scale * r_out / (grad_scale + 1.0e-9), 0.0, 20.0)
    resistance_integral = 0.0
    gradient_integral = 0.0
    for index in range(1, len(radii)):
        dr = max(1.0e-9, radii[index] - radii[index - 1])
        resistance_integral += 0.5 * (
            grad_abs[index] * curv_abs[index] + grad_abs[index - 1] * curv_abs[index - 1]
        ) * dr
        gradient_integral += 0.5 * (grad_abs[index] + grad_abs[index - 1]) * dr
    curvature_resistance = clamp(
        resistance_integral * r_out / ((gradient_integral + 1.0e-9) * (max(vbar2) + 1.0e-9)),
        0.0,
        8.0,
    )
    positive = [value >= -0.03 * grad_scale for value in grad]
    monotonic_fraction = sum(1 for value in positive if value) / len(positive)
    signs = []
    for value in grad:
        if abs(value) <= 0.05 * grad_scale:
            signs.append(0)
        else:
            signs.append(1 if value > 0 else -1)
    compact_signs = [value for value in signs if value != 0]
    sign_changes = sum(1 for left, right in zip(compact_signs, compact_signs[1:]) if left != right)
    oscillation_penalty = clamp(sign_changes / max(1, len(compact_signs) - 1), 0.0, 1.0)
    gradient_coherence = clamp(0.72 * monotonic_fraction + 0.28 * (1.0 - oscillation_penalty), 0.0, 1.0)
    admissible_smoothness = 1.0 / (1.0 + roughness)
    inner_grad = safe_mean(grad_abs[index] for index, radius in enumerate(radii) if radius <= 0.45 * r_out)
    outer_grad = safe_mean(grad_abs[index] for index, radius in enumerate(radii) if radius >= 0.65 * r_out)
    inner_outer_contrast = (outer_grad - inner_grad) / (abs(outer_grad) + abs(inner_grad) + 1.0e-9)
    odd_kernel_balance = clamp(0.5 + 0.5 * inner_outer_contrast, 0.0, 1.0)
    field_coherence = clamp(
        0.42 * gradient_coherence
        + 0.30 * admissible_smoothness
        + 0.18 * (1.0 / (1.0 + curvature_resistance))
        + 0.10 * odd_kernel_balance,
        0.0,
        1.0,
    )
    return {
        "gradientCoherence": gradient_coherence,
        "curvatureResistance": curvature_resistance,
        "admissibleSmoothness": admissible_smoothness,
        "oddKernelBalance": odd_kernel_balance,
        "fieldCoherence": field_coherence,
        "monotonicFraction": monotonic_fraction,
        "gradientSignChanges": sign_changes,
        "roughness": roughness,
        "innerOuterGradientContrast": inner_outer_contrast,
    }


def v19_field_coherence_activation(curve: dict, family_id: str) -> tuple[float, dict]:
    features = v19_field_coherence_features(curve)
    local = v19_admissibility_features(curve)
    route = curve.get("lockedModelRoute", "")
    route_loading = clamp(
        0.36 * clamp(local["memoryLoad"] / 6.0, 0.0, 1.0)
        + 0.24 * clamp(local["uOut"] / 0.45, 0.0, 1.0)
        + 0.20 * clamp(local["lGapOverH"] / 1.35, 0.0, 1.0)
        + 0.20 * (1.0 if route == "low-load" else 0.62),
        0.0,
        1.0,
    )
    if family_id == "gradient-coherence-denominator":
        activation = route_loading * features["gradientCoherence"] / (1.0 + 0.65 * features["curvatureResistance"])
    elif family_id == "curvature-resistance-denominator":
        activation = route_loading * features["fieldCoherence"] / (1.0 + 0.95 * features["curvatureResistance"])
    elif family_id == "admissible-smoothing-coherence":
        activation = route_loading * clamp(0.55 * features["admissibleSmoothness"] + 0.45 * features["gradientCoherence"], 0.0, 1.0)
    elif family_id == "odd-kernel-balance":
        activation = route_loading * features["gradientCoherence"] * clamp(
            0.35 + 0.65 * features["oddKernelBalance"], 0.0, 1.0
        )
    else:
        raise ValueError(f"Unknown v19 field-coherence family: {family_id}")
    return clamp(activation, 0.0, 1.0), {**local, **features, "routeLoading": route_loading}


def v19_field_coherence_scale(curves: list[dict], weak_names: set[str], supports_by_name: dict[str, list[float]], family_id: str) -> float:
    numerator = 0.0
    denominator = 0.0
    for curve in curves:
        if curve["name"] in weak_names:
            continue
        target = supports_by_name.get(curve["name"], [])
        if len(target) != len(curve["points"]):
            continue
        raw, _ = v19_source_raw_supports(curve, "curvature-memory-growth-equation")
        activation, _ = v19_field_coherence_activation(curve, family_id)
        for raw_value, target_value in zip(raw, target):
            candidate = max(0.0, raw_value) * activation
            numerator += candidate * max(0.0, target_value)
            denominator += candidate * candidate
    return numerator / denominator if denominator > 1.0e-12 else 0.0


def v19_field_coherence_case_rows(family_id: str) -> tuple[list[dict], dict]:
    context = observed_state_candidate_context()
    curves = context["curves"]
    weak_names = set(context["weakNames"])
    high_names = set(context["highNames"])
    supports_by_name = v18_39_remaining_nfw_gap_artifact_supports()
    scale = v19_field_coherence_scale(curves, weak_names, supports_by_name, family_id)
    rows: list[dict] = []
    for curve in curves:
        target = supports_by_name.get(curve["name"], [])
        if len(target) != len(curve["points"]):
            continue
        raw, _ = v19_source_raw_supports(curve, "curvature-memory-growth-equation")
        activation, features = v19_field_coherence_activation(curve, family_id)
        supports = [max(0.0, scale * activation * value) for value in raw]
        score = v18_competitor_support_score(curve, supports)
        target_score = v18_competitor_support_score(curve, target)
        canonical = v18_competitor_support_score(curve, v18_competitor_canonical_supports(curve))
        target_gain = pct_improvement(canonical["rmse"], target_score["rmse"])
        candidate_gain = pct_improvement(canonical["rmse"], score["rmse"])
        set_name = "weak-systematics-excluded" if curve["name"] in weak_names else ("clean-high-rmse" if curve["name"] in high_names else "clean-protected")
        rows.append(
            {
                "galaxy": curve["name"],
                "set": set_name,
                "familyId": family_id,
                "lockedRoute": curve.get("lockedModelRoute", ""),
                "activation": activation,
                "globalScale": scale,
                "canonicalRmse": canonical["rmse"],
                "lockedV18Rmse": target_score["rmse"],
                "fieldCoherenceRmse": score["rmse"],
                "sourceMinusV18KmS": score["rmse"] - target_score["rmse"],
                "gainVsCanonicalPct": candidate_gain,
                "v18RepairRetentionPct": candidate_gain / target_gain * 100.0 if abs(target_gain) > 1.0e-9 else math.nan,
                **v19_source_acceleration_shape_metrics(curve, target, supports),
                **features,
            }
        )
    return rows, {"globalScale": scale}


def v19_field_coherence_score_rows() -> tuple[list[dict], list[dict], str, dict]:
    score_rows: list[dict] = []
    all_case_rows: list[dict] = []
    for family_id in V19_FIELD_COHERENCE_IDS:
        rows, meta = v19_field_coherence_case_rows(family_id)
        all_case_rows.extend(rows)
        clean = [row for row in rows if row["set"] != "weak-systematics-excluded"]
        high = [row for row in clean if row["set"] == "clean-high-rmse"]
        protected = [row for row in clean if row["set"] == "clean-protected"]
        canonical_clean = safe_mean(parse_float(row["canonicalRmse"]) for row in clean)
        v18_clean = safe_mean(parse_float(row["lockedV18Rmse"]) for row in clean)
        candidate_clean = safe_mean(parse_float(row["fieldCoherenceRmse"]) for row in clean)
        canonical_high = safe_mean(parse_float(row["canonicalRmse"]) for row in high)
        v18_high = safe_mean(parse_float(row["lockedV18Rmse"]) for row in high)
        candidate_high = safe_mean(parse_float(row["fieldCoherenceRmse"]) for row in high)
        score_rows.append(
            {
                "familyId": family_id,
                "globalScale": meta["globalScale"],
                "cleanMeanRmse": candidate_clean,
                "cleanGainVsCanonicalPct": pct_improvement(canonical_clean, candidate_clean),
                "cleanV18RepairRetentionPct": (canonical_clean - candidate_clean) / (canonical_clean - v18_clean) * 100.0 if abs(canonical_clean - v18_clean) > 1.0e-9 else math.nan,
                "highMeanRmse": candidate_high,
                "highGainVsCanonicalPct": pct_improvement(canonical_high, candidate_high),
                "highV18RepairRetentionPct": (canonical_high - candidate_high) / (canonical_high - v18_high) * 100.0 if abs(canonical_high - v18_high) > 1.0e-9 else math.nan,
                "protectedMaxRegressionVsV18KmS": max([parse_float(row["sourceMinusV18KmS"], 0.0) for row in protected] or [0.0]),
                "protectedMeanRegressionVsV18KmS": safe_mean(max(0.0, parse_float(row["sourceMinusV18KmS"], 0.0)) for row in protected),
                "meanAccelerationShapeRmse": safe_mean(parse_float(row["accelerationShapeRmse"]) for row in clean),
                "activeHighCount": sum(1 for row in high if parse_float(row["activation"], 0.0) >= 0.5),
                "activeProtectedCount": sum(1 for row in protected if parse_float(row["activation"], 0.0) >= 0.5),
                "meanHighFieldCoherence": safe_mean(parse_float(row["fieldCoherence"]) for row in high),
                "meanProtectedFieldCoherence": safe_mean(parse_float(row["fieldCoherence"]) for row in protected),
                "weakSystematicsLeakage": 0,
            }
        )
    best = min(
        score_rows,
        key=lambda row: (
            parse_float(row["protectedMaxRegressionVsV18KmS"], math.inf),
            -parse_float(row["highV18RepairRetentionPct"], -math.inf),
            parse_float(row["meanAccelerationShapeRmse"], math.inf),
        ),
    )
    if (
        parse_float(best["protectedMaxRegressionVsV18KmS"], math.inf) <= 3.0
        and parse_float(best["highV18RepairRetentionPct"], 0.0) >= 45.0
        and parse_float(best["cleanV18RepairRetentionPct"], 0.0) > 0.0
    ):
        verdict = "field-coherence source-law candidate"
    elif parse_float(best["highV18RepairRetentionPct"], 0.0) >= 30.0:
        verdict = "field-coherence anatomy only"
    else:
        verdict = "current 1D field-coherence variables insufficient"
    return score_rows, all_case_rows, verdict, best


def write_v19_field_coherence_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_v19_field_coherence"
    score_rows, case_rows, verdict, best = v19_field_coherence_score_rows()
    best_cases = [row for row in case_rows if row["familyId"] == best["familyId"]]
    false_rows = sorted(
        [row for row in best_cases if row["set"] == "clean-protected" and parse_float(row["sourceMinusV18KmS"], 0.0) > 3.0],
        key=lambda row: parse_float(row["sourceMinusV18KmS"], 0.0),
        reverse=True,
    )
    retained_high_rows = sorted(
        [row for row in best_cases if row["set"] == "clean-high-rmse" and parse_float(row["v18RepairRetentionPct"], 0.0) >= 50.0],
        key=lambda row: parse_float(row["v18RepairRetentionPct"], 0.0),
        reverse=True,
    )
    support_shape_rows = []
    for row in case_rows:
        for zone in ["inner", "mid", "outer"]:
            support_shape_rows.append(
                {
                    "galaxy": row["galaxy"],
                    "set": row["set"],
                    "familyId": row["familyId"],
                    "zone": zone,
                    "accelerationBiasCandidateMinusV18": row[f"{zone}AccelerationBias"],
                    "accelerationShapeRmse": row["accelerationShapeRmse"],
                    "fieldCoherence": row["fieldCoherence"],
                    "curvatureResistance": row["curvatureResistance"],
                }
            )
    write_csv(out_dir / f"{prefix}_scores.csv", score_rows)
    write_csv(out_dir / f"{prefix}_case_ledger.csv", case_rows)
    write_csv(out_dir / f"{prefix}_support_shape.csv", support_shape_rows)
    write_csv(out_dir / f"{prefix}_false_activation_ledger.csv", false_rows)
    write_csv(out_dir / f"{prefix}_retained_high_ledger.csv", retained_high_rows)
    formula = {
        "candidateId": "mts-v19-field-coherence-v1",
        "status": verdict,
        "bestFamily": best,
        "baseEquation": "curvature-memory-growth-equation",
        "physicalReading": "motion-field loading is admissible when the smoothed baryonic field is coherent and curvature resistance is low enough",
        "featureDefinitions": {
            "gradientCoherence": "fraction of smoothed Vbar^2 radial field with consistent outward gradient, penalized for gradient sign changes",
            "curvatureResistance": "normalized integral of |dVbar^2/dr| |d2Vbar^2/dr2|, inspired by curvature-motion resistance",
            "admissibleSmoothness": "1/(1+roughness), with roughness from curvature over gradient scale",
            "oddKernelBalance": "outer-minus-inner gradient balance mapped to [0,1], a 1D proxy for antisymmetric radial source response",
        },
        "canonicalMtsChanged": False,
        "browserChanged": False,
        "forbiddenInputs": ["galaxy name", "raw residual", "raw RMSE", "NFW parameter", "MOND parameter", "weak/systematics fitting"],
    }
    (out_dir / f"{prefix}_formula.json").write_text(json.dumps(json_clean(formula), indent=2, sort_keys=True), encoding="utf-8")
    equations = [
        "# MTS v19 Field-Coherence Equations",
        "",
        "This pass treats the v18 support field as the circular-orbit limit of a motion-field response. It tests whether the source equation needs an admissibility term built from coherent baryonic field geometry.",
        "",
        "Let `B(r)=V_bar(r)^2` and `B_L(r)` be an exponentially smoothed baryonic field.",
        "",
        "`G(r)=dB_L/dr`",
        "",
        "`C(r)=d^2B_L/dr^2`",
        "",
        "`R_curv = norm int |G(r)| |C(r)| dr`",
        "",
        "`A_source = A_route * C_field / (1 + lambda R_curv)`",
        "",
        "The tested support remains the curvature-memory source equation multiplied by `A_source`; no v18/browser law is changed.",
    ]
    (out_dir / f"{prefix}_equations.md").write_text("\n".join(equations) + "\n", encoding="utf-8")
    report = [
        "# MTS v19 Field-Coherence Source Test",
        "",
        "This is a direct test of the Motion-TimeSpace interpretation: the support term is not treated as a fitted halo or residual repair, but as a motion-field loading response controlled by whether the baryonic radial field is coherent enough to source it.",
        "",
        f"Verdict: `{verdict}`.",
        f"Best family: `{best['familyId']}`.",
        f"High v18 repair retention: `{fmt(best['highV18RepairRetentionPct'])}%`.",
        f"Clean v18 repair retention: `{fmt(best['cleanV18RepairRetentionPct'])}%`.",
        f"Protected max regression vs v18: `{fmt(best['protectedMaxRegressionVsV18KmS'])}` km/s.",
        f"Mean high field coherence: `{fmt(best['meanHighFieldCoherence'])}`.",
        f"Mean protected field coherence: `{fmt(best['meanProtectedFieldCoherence'])}`.",
        "",
        "## What This Means",
        "",
        "The tested variables are all pre-residual curve/source variables: smoothed baryonic-field gradients, curvature resistance, admissible smoothness, and inner/outer radial balance. If this still cannot protect clean lookalikes while retaining high-RMSE repairs, the missing physical condition is probably not present in the one-dimensional SPARC mass-model curve alone.",
        "",
        verdict,
    ]
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report) + "\n", encoding="utf-8")
    capsule = {
        "analysisName": "mts-v19-field-coherence-v1",
        "verdict": verdict,
        "bestFamily": best,
        "falseActivationCount": len(false_rows),
        "retainedHighCount": len(retained_high_rows),
        "canonicalMtsChanged": False,
        "browserChanged": False,
        "weakSystematicsLeakage": 0,
        "outputFiles": [
            f"{prefix}_report.md",
            f"{prefix}_equations.md",
            f"{prefix}_scores.csv",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_support_shape.csv",
            f"{prefix}_false_activation_ledger.csv",
            f"{prefix}_retained_high_ledger.csv",
            f"{prefix}_formula.json",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_v19fieldcoherence(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_V19_FIELD_COHERENCE_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
