def v19_external_2d_slug(source_id: str, url: str) -> str:
    digest = hashlib.sha256(url.encode("utf-8")).hexdigest()[:12]
    tail = re.sub(r"[^A-Za-z0-9]+", "-", urllib.parse.urlparse(url).path.strip("/")).strip("-")[:46]
    return f"{source_id}-{tail}-{digest}".strip("-") or f"{source_id}-{digest}"


def v19_external_2d_fetch(url: str, path: Path, offline: bool, max_bytes: int = 2_000_000) -> dict:
    if path.exists():
        data = path.read_bytes()
        return {"cacheStatus": "available", "bytes": len(data), "sha256": hashlib.sha256(data).hexdigest(), "error": ""}
    if offline:
        return {"cacheStatus": "missing-offline", "bytes": 0, "sha256": "", "error": "offline and not cached"}
    try:
        request = urllib.request.Request(url, headers={"User-Agent": "MTS-Galaxy-Lab/2D-source-scout"})
        with urllib.request.urlopen(request, timeout=30) as response:
            data = response.read(max_bytes + 1)
        if len(data) > max_bytes:
            return {"cacheStatus": "skipped-too-large", "bytes": len(data), "sha256": "", "error": f"exceeds {max_bytes} byte cap"}
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)
        return {"cacheStatus": "available", "bytes": len(data), "sha256": hashlib.sha256(data).hexdigest(), "error": ""}
    except Exception as exc:  # noqa: BLE001 - provenance fetch must record failures, not crash the audit.
        return {"cacheStatus": "fetch-error", "bytes": 0, "sha256": "", "error": str(exc)[:240]}


def v19_external_2d_norm_name(name: str) -> str:
    raw = str(name).upper().replace("_", "").replace(" ", "")
    return re.sub(r"[^A-Z0-9]", "", raw)


def v19_external_2d_name_variants(name: str) -> set[str]:
    compact = v19_external_2d_norm_name(name)
    variants = {compact}
    match = re.match(r"^(NGC|UGC|DDO|IC|ESO|F|PGC|KK)(0*)([A-Z0-9]+)$", compact)
    if match:
        prefix, _zeros, rest = match.groups()
        variants.add(prefix + rest)
        if rest.isdigit():
            variants.add(prefix + rest.zfill(4))
            variants.add(prefix + rest.zfill(5))
    return variants


def v19_external_2d_targets() -> list[dict]:
    source_dir = DEFAULT_V19_TWO_D_SOURCE_FIELD_OUT
    case_path = source_dir / "mts_v19_two_d_source_field_case_ledger.csv"
    if not case_path.exists():
        write_v19_twod_source_field_artifacts(source_dir)
    rows = read_csv_rows(case_path) if case_path.exists() else []
    targets = []
    for row in rows:
        priority = 1
        if row.get("sourceClass") == "protected-false-activation":
            priority = 1
        elif parse_float(row.get("v18RepairRetentionPct"), 0.0) >= 70.0:
            priority = 2
        else:
            priority = 3
        targets.append(
            {
                "galaxy": row.get("galaxy", ""),
                "sourceClass": row.get("sourceClass", ""),
                "lockedRoute": row.get("lockedRoute", ""),
                "priority": priority,
                "qualityCode": row.get("qualityCode", ""),
                "referenceCodes": row.get("referenceCodes", ""),
                "nameVariants": ";".join(sorted(v19_external_2d_name_variants(row.get("galaxy", "")))),
            }
        )
    targets.sort(key=lambda item: (parse_float(item["priority"]), item["galaxy"]))
    return targets


def v19_external_2d_scan_text(text: str, target: dict) -> tuple[bool, str, str]:
    compact_text = v19_external_2d_norm_name(text)
    variants = [variant for variant in target.get("nameVariants", "").split(";") if variant]
    matched = [
        variant for variant in variants
        if variant and re.search(rf"(?<![A-Z0-9]){re.escape(variant)}(?![A-Z0-9])", compact_text)
    ]
    lowered = text.lower()
    keywords = [
        "velocity field",
        "residual velocity",
        "non-circular",
        "non circular",
        "warp",
        "bar",
        "lopsided",
        "asymmetry",
        "asymmetric",
        "approaching",
        "receding",
        "beam",
        "dispersion",
        "moment",
        "kinematic",
    ]
    hits = [keyword for keyword in keywords if keyword in lowered]
    return bool(matched), ";".join(matched[:5]), ";".join(hits)


def v19_external_2d_source_direct_match(source_id: str, target: dict, matched: bool, combined_text: str) -> bool:
    norm = v19_external_2d_norm_name(target.get("galaxy", ""))
    if source_id == "cds-blais-halpha-hi":
        direct_names = {
            "UGC02259",
            "NGC2403",
            "NGC6946",
            "NGC5055",
            "NGC2841",
            "NGC5985",
        }
        return norm in direct_names
    if source_id == "cds-ghasp-108":
        return matched and bool(re.search(rf"(?<![A-Z0-9]){re.escape(norm)}(?![A-Z0-9])", v19_external_2d_norm_name(combined_text)))
    return matched


def v19_external_2d_manifest_sources(source_manifest: Path | None) -> tuple[list[dict], list[dict]]:
    sources = [dict(source, urls=list(source["urls"])) for source in V19_EXTERNAL_TWO_D_SOURCES]
    manifest_rows: list[dict] = []
    if not source_manifest:
        return sources, manifest_rows
    if not source_manifest.exists():
        manifest_rows.append(
            {
                "sourceId": "",
                "family": "",
                "url": "",
                "status": "missing-manifest",
                "error": str(source_manifest),
            }
        )
        return sources, manifest_rows
    grouped: dict[str, dict] = {}
    for row in read_csv_rows(source_manifest):
        source_id = (row.get("sourceId") or row.get("source_id") or "").strip()
        url = (row.get("url") or "").strip()
        if not source_id or not url:
            manifest_rows.append(
                {
                    "sourceId": source_id,
                    "family": row.get("family", ""),
                    "url": url,
                    "status": "skipped",
                    "error": "sourceId and url are required",
                }
            )
            continue
        source = grouped.setdefault(
            source_id,
            {
                "sourceId": source_id,
                "family": row.get("family", "manifest external 2D source"),
                "urls": [],
                "dataKind": row.get("dataKind", "manifest supplied external 2D/source-field table"),
                "independent2DUse": row.get("independent2DUse", "manifest supplied source; inspect before using as formula evidence"),
                "sourceOrigin": "manifest",
                "maxBytes": int(parse_float(row.get("maxBytes"), 2_000_000) or 2_000_000),
            },
        )
        source["urls"].append(url)
        manifest_rows.append(
            {
                "sourceId": source_id,
                "family": source["family"],
                "url": url,
                "status": "accepted",
                "error": "",
            }
        )
    sources.extend(grouped.values())
    return sources, manifest_rows


def write_v19_external_2d_acquisition_artifacts(out_dir: Path, source_cache: Path, offline: bool, source_manifest: Path | None = None) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    source_cache.mkdir(parents=True, exist_ok=True)
    prefix = "mts_v19_external_2d"
    targets = v19_external_2d_targets()
    sources, manifest_rows = v19_external_2d_manifest_sources(source_manifest)
    source_rows = []
    fetch_rows = []
    hit_rows = []
    for source in sources:
        source_rows.append(
            {
                "sourceId": source["sourceId"],
                "family": source["family"],
                "dataKind": source["dataKind"],
                "independent2DUse": source["independent2DUse"],
                "urlCount": len(source["urls"]),
                "sourceOrigin": source.get("sourceOrigin", "built-in"),
                "largeDownloadsAllowed": False,
            }
        )
        combined_text = ""
        combined_paths = []
        for url in source["urls"]:
            path = source_cache / source["sourceId"] / v19_external_2d_slug(source["sourceId"], url)
            status = v19_external_2d_fetch(url, path, offline, int(parse_float(source.get("maxBytes"), 2_000_000) or 2_000_000))
            fetch_rows.append(
                {
                    "sourceId": source["sourceId"],
                    "family": source["family"],
                    "url": url,
                    "cachePath": str(path),
                    **status,
                }
            )
            if path.exists() and status["cacheStatus"] not in {"skipped-too-large"}:
                try:
                    text = path.read_text(encoding="utf-8", errors="ignore")
                except Exception:
                    text = path.read_bytes().decode("latin-1", errors="ignore")
                combined_text += "\n" + html.unescape(re.sub(r"<[^>]+>", " ", text))
                combined_paths.append(str(path))
        for target in targets:
            matched, variants, keyword_hits = v19_external_2d_scan_text(combined_text, target)
            if matched or keyword_hits:
                source_has_2d_terms = any(
                    term in keyword_hits
                    for term in ["velocity field", "residual velocity", "non-circular", "non circular", "warp", "lopsided", "asymmetry", "approaching", "receding", "dispersion"]
                )
                direct_candidate = source_has_2d_terms and v19_external_2d_source_direct_match(source["sourceId"], target, matched, combined_text)
                hit_rows.append(
                    {
                        "galaxy": target["galaxy"],
                        "sourceClass": target["sourceClass"],
                        "priority": target["priority"],
                        "sourceId": source["sourceId"],
                        "family": source["family"],
                        "matchedName": matched,
                        "matchedVariants": variants,
                        "keywordHits": keyword_hits,
                        "directExternal2DCandidate": direct_candidate,
                        "dataKind": source["dataKind"],
                        "cachePaths": ";".join(combined_paths),
                        "nextAction": "parse/import source-specific 2D table" if direct_candidate else "source family context only",
                    }
                )
    direct_hits = [row for row in hit_rows if parse_bool(row.get("directExternal2DCandidate"))]
    target_direct = sorted({row["galaxy"] for row in direct_hits})
    false_direct = sorted({row["galaxy"] for row in direct_hits if row["sourceClass"] == "protected-false-activation"})
    high_direct = sorted({row["galaxy"] for row in direct_hits if row["sourceClass"] == "retained-high-source-load"})
    summary_rows = [
        {"metric": "targetCount", "value": len(targets)},
        {"metric": "sourceFamilyCount", "value": len(sources)},
        {"metric": "manifestSourceRows", "value": len(manifest_rows)},
        {"metric": "fetchRows", "value": len(fetch_rows)},
        {"metric": "availableCacheRows", "value": sum(1 for row in fetch_rows if row["cacheStatus"] == "available")},
        {"metric": "directExternal2DTargetCount", "value": len(target_direct)},
        {"metric": "directExternal2DFalseActivationCount", "value": len(false_direct)},
        {"metric": "directExternal2DRetainedHighCount", "value": len(high_direct)},
        {"metric": "largeDownloadsAllowed", "value": False},
    ]
    if len(target_direct) >= 5 and false_direct and high_direct:
        verdict = "external 2D parser target found"
    elif len(target_direct) > 0:
        verdict = "partial external 2D overlap found"
    else:
        verdict = "no small external 2D overlap found yet"
    write_csv(out_dir / f"{prefix}_targets.csv", targets)
    write_csv(out_dir / f"{prefix}_source_inventory.csv", source_rows)
    write_csv(out_dir / f"{prefix}_source_manifest_import.csv", manifest_rows)
    write_csv(out_dir / f"{prefix}_fetch_inventory.csv", fetch_rows)
    write_csv(out_dir / f"{prefix}_hit_ledger.csv", hit_rows)
    write_csv(out_dir / f"{prefix}_summary.csv", summary_rows)
    manifest_template = [
        {
            "sourceId": "example-cds-or-paper-table",
            "family": "human-readable source family label",
            "url": "https://example.org/small-table.dat",
            "dataKind": "native velocity-field/asymmetry/warp/bar/provenance table",
            "independent2DUse": "why this source helps separate source-field admissibility",
            "maxBytes": 2000000,
        }
    ]
    write_csv(out_dir / f"{prefix}_source_manifest_template.csv", manifest_template)
    next_actions = []
    if direct_hits:
        for source_id in sorted({row["sourceId"] for row in direct_hits}):
            source_direct = [row for row in direct_hits if row["sourceId"] == source_id]
            next_actions.append(
                {
                    "sourceId": source_id,
                    "directTargetCount": len({row["galaxy"] for row in source_direct}),
                    "targets": ";".join(sorted({row["galaxy"] for row in source_direct})),
                    "recommendedNextMode": "v19external2dparser",
                    "action": "parse source-specific tables into 2D admissibility variables",
                }
            )
    else:
        next_actions.append(
            {
                "sourceId": "none",
                "directTargetCount": 0,
                "targets": "",
                "recommendedNextMode": "external 2D data-provider/manual source expansion",
                "action": "add source manifest URLs for papers/catalogues with actual velocity-field asymmetry, warp, bar, or residual maps",
            }
        )
    write_csv(out_dir / f"{prefix}_next_actions.csv", next_actions)
    report = [
        "# MTS v19 External 2D Source Acquisition",
        "",
        "This pass tries to acquire independent external 2D/source-field evidence before building our own descriptors. It caches only bounded catalogue pages and small ASCII tables on D:, and it does not score or change MTS.",
        "",
        f"Verdict: `{verdict}`.",
        f"Targets searched: `{len(targets)}`.",
        f"Source families: `{len(sources)}`.",
        f"Manifest source rows imported: `{len(manifest_rows)}`.",
        f"Available cached source products: `{sum(1 for row in fetch_rows if row['cacheStatus'] == 'available')}` / `{len(fetch_rows)}`.",
        f"Direct external 2D target overlaps: `{len(target_direct)}`.",
        f"False-activation overlaps: `{len(false_direct)}`.",
        f"Retained-high overlaps: `{len(high_direct)}`.",
        "",
        "## Direct Overlap Targets",
        "",
        "; ".join(target_direct) if target_direct else "None found in this bounded scout.",
        "",
        "## Next Action",
        "",
        next_actions[0]["action"],
        "",
        verdict,
    ]
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report) + "\n", encoding="utf-8")
    capsule = {
        "analysisName": "mts-v19-external-2d-acquisition-v1",
        "verdict": verdict,
        "targetCount": len(targets),
        "sourceFamilyCount": len(sources),
        "manifestSourceRows": len(manifest_rows),
        "directExternal2DTargetCount": len(target_direct),
        "directExternal2DFalseActivationCount": len(false_direct),
        "directExternal2DRetainedHighCount": len(high_direct),
        "largeDownloadsAllowed": False,
        "canonicalMtsChanged": False,
        "browserChanged": False,
        "cacheRoot": str(source_cache),
        "sourceManifest": str(source_manifest.resolve()) if source_manifest and source_manifest.exists() else "",
        "outputFiles": [
            f"{prefix}_report.md",
            f"{prefix}_targets.csv",
            f"{prefix}_source_inventory.csv",
            f"{prefix}_source_manifest_import.csv",
            f"{prefix}_source_manifest_template.csv",
            f"{prefix}_fetch_inventory.csv",
            f"{prefix}_hit_ledger.csv",
            f"{prefix}_summary.csv",
            f"{prefix}_next_actions.csv",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_v19external2dacquire(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_V19_EXTERNAL_TWO_D_ACQUIRE_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    source_cache = Path(args.source_cache) if args.source_cache else DEFAULT_V19_EXTERNAL_TWO_D_ACQUIRE_CACHE
    source_manifest = Path(args.source_manifest) if args.source_manifest else None
    capsule = write_v19_external_2d_acquisition_artifacts(out_dir, source_cache, args.offline, source_manifest)
    print("MTS v19 external 2D source acquisition")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"targets={capsule['targetCount']}",
                f"sources={capsule['sourceFamilyCount']}",
                f"direct_targets={capsule['directExternal2DTargetCount']}",
                f"cache={capsule['cacheRoot']}",
            ]
        )
    )
    print(f"Wrote v19 external 2D acquisition to {out_dir.resolve()}")


def v19_external_2d_substr_float(line: str, start: int, end: int) -> float:
    return parse_float(line[start - 1:end].strip(), math.nan)


def v19_external_2d_substr_text(line: str, start: int, end: int) -> str:
    return line[start - 1:end].strip()


def v19_external_2d_source_class_map() -> dict[str, dict]:
    rows = read_csv_rows(DEFAULT_V19_TWO_D_SOURCE_FIELD_OUT / "mts_v19_two_d_source_field_case_ledger.csv")
    out: dict[str, dict] = {}
    for row in rows:
        for variant in v19_external_2d_name_variants(row.get("galaxy", "")):
            out[variant] = row
    return out


def v19_parse_blais_side_tables(source_cache: Path) -> tuple[list[dict], list[dict]]:
    mapping = {
        "tablea1": "UGC02259",
        "tablea2": "NGC2403",
        "tablea3": "NGC6946",
        "tablea4": "NGC5055",
        "tablea5": "NGC2841",
        "tablea6": "NGC5985",
    }
    points: list[dict] = []
    cases: list[dict] = []
    source_class = v19_external_2d_source_class_map()
    base = source_cache / "cds-blais-halpha-hi"
    for table_id, galaxy in mapping.items():
        files = sorted(base.glob(f"*{table_id}*"))
        if not files:
            continue
        path = files[0]
        diffs = []
        frac_diffs = []
        sigma_values = []
        usable = 0
        for line_number, line in enumerate(path.read_text(encoding="utf-8", errors="ignore").splitlines(), start=1):
            if not line.strip():
                continue
            radius_arcsec = v19_external_2d_substr_float(line, 1, 6)
            n_app = v19_external_2d_substr_float(line, 8, 11)
            v_app = v19_external_2d_substr_float(line, 13, 15)
            sig_app = v19_external_2d_substr_float(line, 17, 19)
            n_rec = v19_external_2d_substr_float(line, 21, 24)
            v_rec = v19_external_2d_substr_float(line, 26, 28)
            sig_rec = v19_external_2d_substr_float(line, 30, 32)
            vel = v19_external_2d_substr_float(line, 34, 36)
            e_vel = v19_external_2d_substr_float(line, 38, 39)
            has_both = math.isfinite(v_app) and math.isfinite(v_rec) and math.isfinite(vel) and vel > 0
            side_diff = abs(v_app - v_rec) if has_both else math.nan
            frac = side_diff / vel if has_both else math.nan
            if has_both:
                usable += 1
                diffs.append(side_diff)
                frac_diffs.append(frac)
            if math.isfinite(sig_app):
                sigma_values.append(sig_app)
            if math.isfinite(sig_rec):
                sigma_values.append(sig_rec)
            points.append(
                {
                    "sourceId": "cds-blais-halpha-hi",
                    "galaxy": galaxy,
                    "tableId": table_id,
                    "lineNumber": line_number,
                    "radiusArcsec": radius_arcsec,
                    "nApproaching": n_app,
                    "vApproachingKmS": v_app,
                    "sigmaApproachingKmS": sig_app,
                    "nReceding": n_rec,
                    "vRecedingKmS": v_rec,
                    "sigmaRecedingKmS": sig_rec,
                    "vMeanKmS": vel,
                    "eVMeanKmS": e_vel,
                    "sideDiffKmS": side_diff,
                    "sideAsymmetryFraction": frac,
                    "sourcePath": str(path),
                    "provenance": "CDS J/A+A/420/147 Blais-Ouellette et al. 2004 tablea?.dat",
                }
            )
        target = source_class.get(v19_external_2d_norm_name(galaxy), {})
        cases.append(
            {
                "sourceId": "cds-blais-halpha-hi",
                "galaxy": galaxy,
                "sourceClass": target.get("sourceClass", "external-context-not-v19-target"),
                "pointCount": sum(1 for row in points if row["sourceId"] == "cds-blais-halpha-hi" and row["galaxy"] == galaxy),
                "usableSidePairCount": usable,
                "meanSideDiffKmS": safe_mean(diffs),
                "medianSideDiffKmS": safe_median(diffs),
                "maxSideDiffKmS": max(diffs or [math.nan]),
                "meanSideAsymmetryFraction": safe_mean(frac_diffs),
                "medianSideAsymmetryFraction": safe_median(frac_diffs),
                "meanSideSigmaKmS": safe_mean(sigma_values),
                "meanFieldResidualVelocityRaw": "",
                "meanFieldResidualVelocityKmSIfMS": "",
                "meanFieldResidualSigmaKmS": "",
                "inclinationMismatchDeg": "",
                "positionAngleMismatchDeg": "",
                "fieldModelChi2": "",
                "sourcePath": str(path),
            }
        )
    return points, cases


def v19_parse_ghasp_side_table(source_cache: Path) -> tuple[list[dict], list[dict]]:
    base = source_cache / "cds-ghasp-108"
    files = sorted(base.glob("*tablef*"))
    if not files:
        return [], []
    path = files[0]
    points: list[dict] = []
    by_galaxy: dict[str, dict[str, list[dict]]] = {}
    for line_number, line in enumerate(path.read_text(encoding="utf-8", errors="ignore").splitlines(), start=1):
        if not line.strip():
            continue
        galaxy = v19_external_2d_substr_text(line, 1, 9).replace(" ", "")
        radius = v19_external_2d_substr_float(line, 11, 15)
        e_radius = v19_external_2d_substr_float(line, 17, 20)
        radius_arcsec = v19_external_2d_substr_float(line, 22, 26)
        vrot = v19_external_2d_substr_float(line, 33, 35)
        e_vrot = v19_external_2d_substr_float(line, 37, 39)
        side = v19_external_2d_substr_text(line, 44, 44)
        row = {
            "sourceId": "cds-ghasp-108",
            "galaxy": galaxy,
            "lineNumber": line_number,
            "radiusKpc": radius,
            "eRadiusKpc": e_radius,
            "radiusArcsec": radius_arcsec,
            "vRotKmS": vrot,
            "eVRotKmS": e_vrot,
            "side": side,
            "sourcePath": str(path),
            "provenance": "CDS J/MNRAS/388/500 GHASP tablef.dat",
        }
        points.append(row)
        by_galaxy.setdefault(v19_external_2d_norm_name(galaxy), {}).setdefault(side, []).append(row)
    source_class = v19_external_2d_source_class_map()
    cases: list[dict] = []
    target_norms = set(source_class.keys())
    for norm_name, sides in by_galaxy.items():
        if norm_name not in target_norms:
            continue
        a_rows = sorted(sides.get("a", []), key=lambda row: parse_float(row["radiusKpc"], math.inf))
        r_rows = sorted(sides.get("r", []), key=lambda row: parse_float(row["radiusKpc"], math.inf))
        diffs = []
        frac_diffs = []
        used_pairs = 0
        for a in a_rows:
            ar = parse_float(a.get("radiusKpc"), math.nan)
            av = parse_float(a.get("vRotKmS"), math.nan)
            if not math.isfinite(ar) or not math.isfinite(av):
                continue
            candidates = [
                row for row in r_rows
                if math.isfinite(parse_float(row.get("radiusKpc"), math.nan))
                and abs(parse_float(row.get("radiusKpc"), 0.0) - ar) <= max(0.18, 0.18 * max(ar, 1.0))
            ]
            if not candidates:
                continue
            best = min(candidates, key=lambda row: abs(parse_float(row.get("radiusKpc"), 0.0) - ar))
            rv = parse_float(best.get("vRotKmS"), math.nan)
            if not math.isfinite(rv):
                continue
            denom = max(1.0e-9, 0.5 * (abs(av) + abs(rv)))
            diffs.append(abs(av - rv))
            frac_diffs.append(abs(av - rv) / denom)
            used_pairs += 1
        target = source_class.get(norm_name, {})
        cases.append(
            {
                "sourceId": "cds-ghasp-108",
                "galaxy": target.get("galaxy", norm_name),
                "sourceClass": target.get("sourceClass", "v19-target"),
                "pointCount": len(a_rows) + len(r_rows),
                "usableSidePairCount": used_pairs,
                "meanSideDiffKmS": safe_mean(diffs),
                "medianSideDiffKmS": safe_median(diffs),
                "maxSideDiffKmS": max(diffs or [math.nan]),
                "meanSideAsymmetryFraction": safe_mean(frac_diffs),
                "medianSideAsymmetryFraction": safe_median(frac_diffs),
                "meanSideSigmaKmS": safe_mean(parse_float(row.get("eVRotKmS"), math.nan) for row in a_rows + r_rows),
                "meanFieldResidualVelocityRaw": "",
                "meanFieldResidualVelocityKmSIfMS": "",
                "meanFieldResidualSigmaKmS": "",
                "inclinationMismatchDeg": "",
                "positionAngleMismatchDeg": "",
                "fieldModelChi2": "",
                "sourcePath": str(path),
            }
        )
    return points, cases


def v19_angle_delta_deg(a: float, b: float) -> float:
    if not math.isfinite(a) or not math.isfinite(b):
        return math.nan
    delta = abs((a - b) % 180.0)
    return min(delta, 180.0 - delta)


def v19_parse_ghasp_velocity_field_table(source_cache: Path) -> list[dict]:
    base = source_cache / "cds-ghasp-108"
    files = sorted(base.glob("*tablec2*"))
    if not files:
        return []
    path = files[0]
    source_class = v19_external_2d_source_class_map()
    cases: list[dict] = []
    for line_number, line in enumerate(path.read_text(encoding="utf-8", errors="ignore").splitlines(), start=1):
        if not line.strip():
            continue
        galaxy = v19_external_2d_substr_text(line, 1, 9).replace(" ", "")
        norm = v19_external_2d_norm_name(galaxy)
        target = source_class.get(norm)
        if not target:
            continue
        i_leda = v19_external_2d_substr_float(line, 27, 28)
        i_field = v19_external_2d_substr_float(line, 33, 34)
        pa_leda = v19_external_2d_substr_float(line, 40, 42)
        pa_field = v19_external_2d_substr_float(line, 71, 73)
        vres_raw = v19_external_2d_substr_float(line, 81, 87)
        sigres = v19_external_2d_substr_float(line, 89, 90)
        chi2 = v19_external_2d_substr_float(line, 92, 95)
        cases.append(
            {
                "sourceId": "cds-ghasp-108-field",
                "galaxy": target.get("galaxy", galaxy),
                "sourceClass": target.get("sourceClass", "v19-target"),
                "pointCount": 1,
                "usableSidePairCount": 0,
                "meanSideDiffKmS": "",
                "medianSideDiffKmS": "",
                "maxSideDiffKmS": "",
                "meanSideAsymmetryFraction": "",
                "medianSideAsymmetryFraction": "",
                "meanSideSigmaKmS": "",
                "meanFieldResidualVelocityRaw": vres_raw,
                "meanFieldResidualVelocityKmSIfMS": vres_raw / 1000.0 if math.isfinite(vres_raw) else math.nan,
                "meanFieldResidualSigmaKmS": sigres,
                "inclinationMismatchDeg": abs(i_field - i_leda) if math.isfinite(i_leda) and math.isfinite(i_field) else math.nan,
                "positionAngleMismatchDeg": v19_angle_delta_deg(pa_field, pa_leda),
                "fieldModelChi2": chi2,
                "sourcePath": str(path),
                "lineNumber": line_number,
            }
        )
    return cases


