def v19_parse_whisp_multiwavelength_tables(source_cache: Path) -> list[dict]:
    base = source_cache / "cds-whisp-multiwavelength-paper6"
    source_class = v19_external_2d_source_class_map()
    cases: list[dict] = []
    class_files = sorted(base.glob("*tablea1*"))
    for path in class_files:
        for line_number, line in enumerate(path.read_text(encoding="utf-8", errors="ignore").splitlines(), start=1):
            if not line.strip():
                continue
            ugc_value = parse_float(v19_external_2d_substr_text(line, 1, 5), math.nan)
            target = v19_external_2d_match_ugc_target(source_class, int(ugc_value) if math.isfinite(ugc_value) else -1)
            if not target:
                continue
            cases.append(
                {
                    "sourceId": "cds-whisp-multiwavelength-paper6-xuv",
                    "galaxy": target.get("galaxy", f"UGC{int(ugc_value)}"),
                    "sourceClass": target.get("sourceClass", "v19-target"),
                    "pointCount": 1,
                    "usableSidePairCount": 0,
                    "whispP6UGC": int(ugc_value),
                    "whispP6XuvClass": v19_external_2d_substr_text(line, 7, 9),
                    "sourcePath": str(path),
                    "lineNumber": line_number,
                }
            )
    table_map = {
        "tablec1": ("hi", "HI"),
        "tablec2": ("nuv", "NUV"),
        "tablec3": ("fuv", "FUV"),
    }
    for table_id, (suffix, band) in table_map.items():
        for path in sorted(base.glob(f"*{table_id}*")):
            for line_number, line in enumerate(path.read_text(encoding="utf-8", errors="ignore").splitlines(), start=1):
                if not line.strip():
                    continue
                ugc_value = parse_float(v19_external_2d_substr_text(line, 1, 5), math.nan)
                target = v19_external_2d_match_ugc_target(source_class, int(ugc_value) if math.isfinite(ugc_value) else -1)
                if not target:
                    continue
                cases.append(
                    {
                        "sourceId": f"cds-whisp-multiwavelength-paper6-{suffix}",
                        "galaxy": target.get("galaxy", f"UGC{int(ugc_value)}"),
                        "sourceClass": target.get("sourceClass", "v19-target"),
                        "pointCount": 1,
                        "usableSidePairCount": 0,
                        "whispP6UGC": int(ugc_value),
                        "whispP6Band": band,
                        "whispP6Gini": v19_external_2d_substr_float(line, 7, 11),
                        "whispP6M20": v19_external_2d_substr_float(line, 19, 24),
                        "whispP6Concentration": v19_external_2d_substr_float(line, 32, 36),
                        "whispP6AsymmetryA": v19_external_2d_substr_float(line, 44, 48),
                        "whispP6SmoothnessS": v19_external_2d_substr_float(line, 56, 60),
                        "whispP6Ellipticity": v19_external_2d_substr_float(line, 68, 72),
                        "whispP6MomentGini": v19_external_2d_substr_float(line, 80, 84),
                        "whispP6R50Arcsec": v19_external_2d_substr_float(line, 92, 98),
                        "sourcePath": str(path),
                        "lineNumber": line_number,
                    }
                )
    return cases


def v19_external_2d_union_rows(rows: list[dict]) -> list[dict]:
    keys: list[str] = []
    for row in rows:
        for key in row:
            if key not in keys:
                keys.append(key)
    return [{key: row.get(key, "") for key in keys} for row in rows]


def write_v19_external_2d_parser_artifacts(out_dir: Path, source_cache: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_v19_external_2d_parser"
    b_points, b_cases = v19_parse_blais_side_tables(source_cache)
    g_points, g_cases = v19_parse_ghasp_side_table(source_cache)
    gf_cases = v19_parse_ghasp_velocity_field_table(source_cache)
    s4g_cases = v19_parse_s4g_lopsidedness_table(source_cache)
    whisp_cases = v19_parse_whisp_morphology_tables(source_cache)
    things_whisp_cases = v19_parse_things_whisp_morphology_table(source_cache)
    whisp_p4_cases = v19_parse_whisp_complete_morphology_table(source_cache)
    whisp_p6_cases = v19_parse_whisp_multiwavelength_tables(source_cache)
    points = b_points + g_points
    cases = b_cases + g_cases + gf_cases + s4g_cases + whisp_cases + things_whisp_cases + whisp_p4_cases + whisp_p6_cases
    v19_cases = [row for row in cases if row.get("sourceClass") in {"protected-false-activation", "retained-high-source-load"}]
    false_cases = [row for row in v19_cases if row["sourceClass"] == "protected-false-activation"]
    high_cases = [row for row in v19_cases if row["sourceClass"] == "retained-high-source-load"]
    v19_unique = sorted({(row.get("galaxy", ""), row.get("sourceClass", "")) for row in v19_cases})
    false_unique = sorted({row.get("galaxy", "") for row in false_cases})
    high_unique = sorted({row.get("galaxy", "") for row in high_cases})
    threshold_rows = []
    feature_names = [
        "meanSideAsymmetryFraction",
        "meanFieldResidualSigmaKmS",
        "inclinationMismatchDeg",
        "positionAngleMismatchDeg",
        "fieldModelChi2",
        "s4gOuterA1",
        "s4gInnerA1",
        "s4gOuterA2",
        "s4gBarClass",
        "whispAsymmetryA",
        "whispLopsidedness",
        "whispGini",
        "whispM20",
        "thingsMorphologyM20",
        "thingsMorphologyAsymmetryA",
        "thingsMorphologyGini",
        "thingsMorphologyConcentration",
        "whispP4M20",
        "whispP4AsymmetryA",
        "whispP4Gini",
        "whispP4AxisSymmetryAxy",
        "whispP6M20",
        "whispP6AsymmetryA",
        "whispP6Gini",
        "whispP6R50Arcsec",
    ]
    for feature_name in feature_names:
        values = [parse_float(row.get(feature_name), math.nan) for row in v19_cases]
        values = [value for value in values if math.isfinite(value)]
        for threshold in sorted({v19_quantile(values, q) for q in [0.33, 0.50, 0.66, 0.80]}) if values else []:
            for direction in ["high", "low"]:
                def hit(row: dict, feature: str = feature_name, thresh: float = threshold, side: str = direction) -> bool:
                    value = parse_float(row.get(feature), math.nan)
                    if not math.isfinite(value):
                        return False
                    return value >= thresh if side == "high" else value <= thresh
                false_recall = sum(1 for row in false_cases if hit(row)) / len(false_cases) if false_cases else 0.0
                high_suppression = sum(1 for row in high_cases if hit(row)) / len(high_cases) if high_cases else 0.0
                threshold_rows.append(
                    {
                        "feature": feature_name,
                        "direction": direction,
                        "threshold": threshold,
                        "falseActivationRecall": false_recall,
                        "retainedHighSuppressionRate": high_suppression,
                        "utilityFalseRecallMinusHighSuppression": false_recall - high_suppression,
                    }
                )
    threshold_rows.sort(key=lambda row: parse_float(row["utilityFalseRecallMinusHighSuppression"], -math.inf), reverse=True)
    if len(v19_cases) >= 5 and false_cases and high_cases:
        verdict = "external 2D morphology pilot usable"
    elif v19_cases:
        verdict = "external 2D parser works but sample too small"
    else:
        verdict = "external 2D parser found no v19 overlap"
    write_csv(out_dir / f"{prefix}_points.csv", v19_external_2d_union_rows(points))
    write_csv(out_dir / f"{prefix}_case_metrics.csv", v19_external_2d_union_rows(cases))
    write_csv(out_dir / f"{prefix}_discriminator_scores.csv", threshold_rows)
    report = [
        "# MTS v19 External 2D Parser Pilot",
        "",
        "This parses independent small external tables into side-asymmetry, stellar-lopsidedness, and HI-morphology metrics. It does not alter or score the MTS law.",
        "",
        f"Verdict: `{verdict}`.",
        f"Parsed point rows: `{len(points)}`.",
        f"Parsed case metrics: `{len(cases)}`.",
        f"v19 overlap metric rows: `{len(v19_cases)}`.",
        f"Unique v19 overlap galaxies: `{len(v19_unique)}`.",
        f"Unique false-activation overlap galaxies: `{len(false_unique)}`.",
        f"Unique retained-high overlap galaxies: `{len(high_unique)}`.",
        "",
        "## v19 Overlap Cases",
        "",
        "| galaxy | class | source | usable pairs | mean side asymmetry | mean side diff |",
        "| --- | --- | --- | ---: | ---: | ---: |",
    ]
    for row in sorted(v19_cases, key=lambda item: item["galaxy"]):
        report.append(
            f"| {row.get('galaxy', '')} | {row.get('sourceClass', '')} | {row.get('sourceId', '')} | {row.get('usableSidePairCount', '')} | {fmt(row.get('meanSideAsymmetryFraction', ''))} | {fmt(row.get('meanSideDiffKmS', ''))} |"
        )
    report.extend(["", verdict])
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report) + "\n", encoding="utf-8")
    capsule = {
        "analysisName": "mts-v19-external-2d-parser-v1",
        "verdict": verdict,
        "parsedPointRows": len(points),
        "caseMetricRows": len(cases),
        "v19OverlapRows": len(v19_cases),
        "v19OverlapCases": len(v19_unique),
        "falseActivationOverlapCases": len(false_unique),
        "retainedHighOverlapCases": len(high_unique),
        "canonicalMtsChanged": False,
        "browserChanged": False,
        "cacheRoot": str(source_cache),
        "outputFiles": [
            f"{prefix}_report.md",
            f"{prefix}_points.csv",
            f"{prefix}_case_metrics.csv",
            f"{prefix}_discriminator_scores.csv",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_v19external2dparser(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_V19_EXTERNAL_TWO_D_PARSER_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    source_cache = Path(args.source_cache) if args.source_cache else DEFAULT_V19_EXTERNAL_TWO_D_ACQUIRE_CACHE
    capsule = write_v19_external_2d_parser_artifacts(out_dir, source_cache)
    print("MTS v19 external 2D parser pilot")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"points={capsule['parsedPointRows']}",
                f"cases={capsule['caseMetricRows']}",
                f"v19_overlap={capsule['v19OverlapCases']}",
                f"v19_rows={capsule.get('v19OverlapRows', capsule['v19OverlapCases'])}",
                f"false={capsule['falseActivationOverlapCases']}",
                f"high={capsule['retainedHighOverlapCases']}",
            ]
        )
    )
    print(f"Wrote v19 external 2D parser pilot to {out_dir.resolve()}")


