def v19_ngc3198_kinematic_fact_source_targets(source_cache: Path) -> list[dict]:
    out = []
    for source in V19_NGC3198_KINEMATIC_FACT_SOURCES:
        suffix = "pdf" if source["sourceRole"] == "candidate-pdf" or str(source["url"]).lower().endswith(".pdf") else "html"
        out.append(
            {
                **source,
                "cachePath": str(source_cache / source["sourceRole"] / f"{safe_file_stem(source['sourceId'])}.{suffix}"),
            }
        )
    return out


def v19_ngc3198_kinematic_fetch_inventory(source_cache: Path, offline: bool) -> list[dict]:
    rows = []
    source_cache.mkdir(parents=True, exist_ok=True)
    for target in v19_ngc3198_kinematic_fact_source_targets(source_cache):
        path = Path(target["cachePath"])
        status = v19_external_2d_fetch(target["url"], path, offline, int(parse_float(target.get("maxBytes"), 750_000) or 750_000))
        rows.append({**target, **status, "largeDownloadAllowed": False})
    return rows


def v19_ngc3198_text_variants(galaxy: str) -> list[str]:
    if galaxy.startswith("NGC") and " " not in galaxy:
        spaced = "NGC " + galaxy[3:]
    elif galaxy.startswith("UGC") and " " not in galaxy:
        spaced = "UGC " + galaxy[3:].lstrip("0")
    else:
        spaced = galaxy
    return sorted({galaxy, spaced, galaxy.replace("_", " "), spaced.replace("_", " ")}, key=len, reverse=True)


def v19_ngc3198_kinematic_extract_rows(fetch_rows: list[dict], offline: bool) -> list[dict]:
    rows = []
    number_pattern = re.compile(r"(?:[±+\-]?\d+(?:\.\d+)?\s*(?:per cent|percent|%|km\s*s(?:−|-)?1|km/s|km s-1|deg|degree|°|arcsec|kpc|Mpc))", re.IGNORECASE)
    for fetch in fetch_rows:
        if fetch.get("cacheStatus") != "available":
            continue
        path = Path(fetch["cachePath"])
        text, parser = v21_source_text(path, fetch.get("sourceRole", ""), offline)
        if not text:
            continue
        lowered = text.lower()
        for galaxy in V19_NGC3198_KINEMATIC_FACT_TARGETS:
            snippets = []
            quiet_hits: set[str] = set()
            boundary_hits: set[str] = set()
            numeric_hits: set[str] = set()
            for variant in v19_ngc3198_text_variants(galaxy):
                idx = lowered.find(variant.lower())
                while idx >= 0 and len(snippets) < 10:
                    snippet = re.sub(r"\s+", " ", text[max(0, idx - 520): idx + 1350]).strip()
                    snippet_lower = snippet.lower()
                    local_quiet = [term for term in V19_KINEMATIC_QUIET_TERMS if term in snippet_lower]
                    local_boundary = [term for term in V19_KINEMATIC_BOUNDARY_TERMS if term in snippet_lower]
                    local_numbers = number_pattern.findall(snippet)
                    if local_quiet or local_boundary or local_numbers:
                        snippets.append(snippet[:1800])
                        quiet_hits.update(local_quiet)
                        boundary_hits.update(local_boundary)
                        numeric_hits.update(item.strip() for item in local_numbers[:20])
                    idx = lowered.find(variant.lower(), idx + max(1, len(variant)))
            if snippets:
                if quiet_hits and boundary_hits:
                    evidence_class = "quiet field plus boundary/streaming evidence"
                elif quiet_hits:
                    evidence_class = "quiet/regular field evidence"
                elif boundary_hits:
                    evidence_class = "boundary/streaming evidence"
                else:
                    evidence_class = "numeric mention only"
                rows.append(
                    {
                        "galaxy": galaxy,
                        "sourceId": fetch["sourceId"],
                        "sourceRole": fetch["sourceRole"],
                        "url": fetch["url"],
                        "cachePath": fetch["cachePath"],
                        "parser": parser,
                        "caseSpecificSnippetCount": len(snippets),
                        "quietTerms": "; ".join(sorted(quiet_hits)),
                        "boundaryTerms": "; ".join(sorted(boundary_hits)),
                        "numericTokens": "; ".join(sorted(numeric_hits))[:2000],
                        "evidenceClass": evidence_class,
                        "snippet": " || ".join(snippets)[:6000],
                    }
                )
    return rows


def v19_ngc3198_kinematic_case_verdicts(evidence_rows: list[dict]) -> list[dict]:
    by_name: dict[str, list[dict]] = {}
    for row in evidence_rows:
        by_name.setdefault(row["galaxy"], []).append(row)
    coverage_path = DEFAULT_V19_KINEMATIC_TWO_D_FIELD_OUT / "mts_v19_kinematic_2d_field_case_coverage.csv"
    if not coverage_path.exists():
        write_v19_kinematic_2d_field_artifacts(DEFAULT_V19_KINEMATIC_TWO_D_FIELD_OUT, DEFAULT_V19_EXTERNAL_TWO_D_PARSER_OUT)
    coverage = {row["galaxy"]: row for row in read_csv_rows(coverage_path)}
    out = []
    for galaxy in V19_NGC3198_KINEMATIC_FACT_TARGETS:
        rows = by_name.get(galaxy, [])
        quiet_count = sum(1 for row in rows if row["quietTerms"])
        boundary_count = sum(1 for row in rows if row["boundaryTerms"])
        numeric_count = sum(1 for row in rows if row["numericTokens"])
        coverage_row = coverage.get(galaxy, {})
        has_table = parse_bool(coverage_row.get("hasDirect2DKinematics"))
        if galaxy == "NGC3198" and quiet_count and boundary_count and not has_table:
            verdict = "source facts show quiet-but-boundary field; table-grade discriminator still missing"
            next_action = "acquire machine-readable THINGS/velocity-field products or source table for NGC3198 before formula testing"
        elif quiet_count and not boundary_count:
            verdict = "quiet/control-like source facts"
            next_action = "use only as comparison control"
        elif boundary_count:
            verdict = "boundary/streaming source facts"
            next_action = "use as source-field anatomy, not formula input"
        elif rows:
            verdict = "case mentioned without decisive kinematic class"
            next_action = "needs numeric direct kinematic table"
        else:
            verdict = "no direct source facts found"
            next_action = "source search still missing"
        out.append(
            {
                "galaxy": galaxy,
                "sourceFactRows": len(rows),
                "quietEvidenceRows": quiet_count,
                "boundaryEvidenceRows": boundary_count,
                "numericEvidenceRows": numeric_count,
                "directTableRowsAlreadyAvailable": coverage_row.get("direct2DKinematicRowCount", 0),
                "verdict": verdict,
                "nextAction": next_action,
                "sourcePaths": ";".join(sorted({row["cachePath"] for row in rows})) if rows else "MISSING",
            }
        )
    return out


def write_v19_ngc3198_kinematic_facts_artifacts(out_dir: Path, source_cache: Path, offline: bool) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_v19_ngc3198_kinematic_facts"
    fetch_rows = v19_ngc3198_kinematic_fetch_inventory(source_cache, offline)
    evidence_rows = v19_ngc3198_kinematic_extract_rows(fetch_rows, offline)
    case_rows = v19_ngc3198_kinematic_case_verdicts(evidence_rows)
    ngc = next((row for row in case_rows if row["galaxy"] == "NGC3198"), {})
    if "quiet-but-boundary" in ngc.get("verdict", ""):
        verdict = "NGC3198 quiet-boundary evidence found; numeric table still needed"
    elif ngc.get("sourceFactRows", 0):
        verdict = "NGC3198 source facts found but not decisive"
    else:
        verdict = "NGC3198 kinematic source facts missing"
    inventory_rows = []
    for row in fetch_rows:
        cache_status = "available" if row.get("cacheStatus") == "available" else "unavailable"
        inventory_rows.append(
            {
                "sourceId": row["sourceId"],
                "sourceRole": row["sourceRole"],
                "url": row["url"],
                "cachePath": row["cachePath"],
                "cacheStatus": cache_status,
                "bytes": row.get("bytes", "") if cache_status == "available" else 0,
                "sha256": row.get("sha256", "") if cache_status == "available" else "",
                "largeDownloadAllowed": False,
                "reason": row.get("reason", ""),
            }
        )
    write_csv(out_dir / f"{prefix}_source_inventory.csv", inventory_rows)
    write_csv(out_dir / f"{prefix}_evidence_table.csv", evidence_rows)
    write_csv(out_dir / f"{prefix}_case_verdicts.csv", case_rows)
    report = [
        "# MTS v19 NGC3198 Kinematic Source Facts",
        "",
        "This mode fetches bounded source-paper pages and extracts case-specific kinematic facts for NGC3198 and controls. It does not change any MTS law or browser preset.",
        "",
        f"Verdict: `{verdict}`.",
        f"Fetched/available sources: `{sum(1 for row in fetch_rows if row.get('cacheStatus') == 'available')}` / `{len(fetch_rows)}`.",
        f"Evidence rows: `{len(evidence_rows)}`.",
        "",
        "| galaxy | source facts | quiet rows | boundary rows | numeric rows | verdict |",
        "| --- | ---: | ---: | ---: | ---: | --- |",
    ]
    for row in case_rows:
        report.append(
            f"| {row['galaxy']} | {row['sourceFactRows']} | {row['quietEvidenceRows']} | {row['boundaryEvidenceRows']} | {row['numericEvidenceRows']} | {row['verdict']} |"
        )
    report.extend(
        [
            "",
            "## Guardrails",
            "",
            "- Source facts are evidence only, not formula inputs.",
            "- No galaxy name, residual, raw RMSE, NFW parameter, or MOND parameter enters an MTS law.",
            "- No FITS cubes, survey archives, or large data products are downloaded.",
            "",
            verdict,
        ]
    )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report) + "\n", encoding="utf-8")
    capsule = {
        "analysisName": "mts-v19-ngc3198-kinematic-facts-v1",
        "verdict": verdict,
        "sourceCount": len(fetch_rows),
        "availableSourceCount": sum(1 for row in fetch_rows if row.get("cacheStatus") == "available"),
        "evidenceRowCount": len(evidence_rows),
        "caseVerdicts": {row["galaxy"]: row["verdict"] for row in case_rows},
        "canonicalMtsChanged": False,
        "browserChanged": False,
        "largeDownloadsAllowed": False,
        "cacheRoot": str(source_cache),
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_v19ngc3198kinematicfacts(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_V19_NGC3198_KINEMATIC_FACTS_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    source_cache = Path(args.source_cache) if args.source_cache else DEFAULT_V19_NGC3198_KINEMATIC_FACTS_CACHE
    capsule = write_v19_ngc3198_kinematic_facts_artifacts(out_dir, source_cache, args.offline)
    print("MTS v19 NGC3198 kinematic source facts")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"sources={capsule['availableSourceCount']}/{capsule['sourceCount']}",
                f"evidence_rows={capsule['evidenceRowCount']}",
                f"ngc3198={capsule['caseVerdicts'].get('NGC3198', '')}",
            ]
        )
    )
    print(f"Wrote v19 NGC3198 kinematic source facts to {out_dir.resolve()}")


V19_SOURCE_BOUNDARY_TARGET_ROLES = {
    "IC2574": "protected cap control",
    "NGC5055": "protected cap control",
    "UGC07089": "protected cap control",
    "NGC3198": "quiet-boundary protected countercase",
    "NGC2403": "admit high/source-load control",
    "NGC3521": "admit high/source-load control",
    "NGC7331": "admit high/source-load control",
    "UGC03205": "admit high/source-load control",
    "UGC05253": "admit high/source-load control",
    "NGC4157": "unexplained remaining-gap control",
    "NGC4100": "unexplained remaining-gap control",
}


def v19_source_boundary_variant_specs() -> list[dict]:
    cap_controls = {"IC2574", "NGC5055", "UGC07089"}
    quiet = {"NGC3198"}
    admit_boundary = {"NGC2403"}
    all_protected_boundary = cap_controls | quiet
    return [
        {
            "variantId": "full-source-equation",
            "variantClass": "control",
            "description": "Existing curvature-memory source equation; no boundary cap.",
            "factors": {},
            "promotable": False,
        },
        {
            "variantId": "prior-protected-cap-only",
            "variantClass": "evidence-gated-stress",
            "description": "Cap the three previously identified protected false activations; leave NGC3198 fully admitted.",
            "factors": {name: 0.0 for name in cap_controls},
            "promotable": False,
        },
        {
            "variantId": "quiet-boundary-soften-050",
            "variantClass": "evidence-gated-stress",
            "description": "Cap prior protected controls and soften NGC3198 halfway toward canonical support.",
            "factors": {**{name: 0.0 for name in cap_controls}, **{name: 0.50 for name in quiet}},
            "promotable": False,
        },
        {
            "variantId": "quiet-boundary-soften-025",
            "variantClass": "evidence-gated-stress",
            "description": "Cap prior protected controls and keep a small 25% source response in NGC3198.",
            "factors": {**{name: 0.0 for name in cap_controls}, **{name: 0.25 for name in quiet}},
            "promotable": False,
        },
        {
            "variantId": "quiet-boundary-cap",
            "variantClass": "evidence-gated-stress",
            "description": "Cap prior protected controls and cap NGC3198 fully to canonical support.",
            "factors": {name: 0.0 for name in all_protected_boundary},
            "promotable": False,
        },
        {
            "variantId": "overbroad-boundary-cap",
            "variantClass": "negative-control",
            "description": "Cap every boundary/streaming evidence case including NGC2403; should fail if boundary evidence alone is too broad.",
            "factors": {name: 0.0 for name in (all_protected_boundary | admit_boundary)},
            "promotable": False,
        },
    ]


def v19_source_boundary_supports(curve: dict, source_supports: list[float], factor: float) -> list[float]:
    canonical = v18_competitor_canonical_supports(curve)
    return [
        max(0.0, c + factor * (s - c))
        for c, s in zip(canonical, source_supports)
    ]


def v19_source_boundary_evidence_context() -> tuple[dict[str, dict], dict[str, dict]]:
    counter_path = DEFAULT_V19_COUNTER_EVIDENCE_OUT / "mts_v19_counter_evidence_admissibility_decisions.csv"
    if not counter_path.exists():
        write_v19_counter_evidence_artifacts(DEFAULT_V19_COUNTER_EVIDENCE_OUT, DEFAULT_V19_COUNTER_EVIDENCE_CACHE, True)
    facts_path = DEFAULT_V19_NGC3198_KINEMATIC_FACTS_OUT / "mts_v19_ngc3198_kinematic_facts_case_verdicts.csv"
    if not facts_path.exists():
        write_v19_ngc3198_kinematic_facts_artifacts(
            DEFAULT_V19_NGC3198_KINEMATIC_FACTS_OUT,
            DEFAULT_V19_NGC3198_KINEMATIC_FACTS_CACHE,
            True,
        )
    counter = {row.get("galaxy", ""): row for row in read_csv_rows(counter_path)} if counter_path.exists() else {}
    facts = {row.get("galaxy", ""): row for row in read_csv_rows(facts_path)} if facts_path.exists() else {}
    return counter, facts


def v19_source_boundary_case_base() -> tuple[dict[str, dict], dict[str, list[float]], dict[str, list[float]], dict[str, list[float]], dict]:
    if not V18_NFW_SHELF_ARTIFACT_PATH.exists():
        write_v18_nfw_gap_shelf_release_lock_artifacts(DEFAULT_OBSERVED_STATE_V18_38_NFW_SHELF_RELEASE_LOCK_OUT)
    context = observed_state_candidate_context()
    curves = {curve["name"]: curve for curve in context["curves"]}
    supports_by_name = v18_39_remaining_nfw_gap_artifact_supports()
    scales = v19_source_equation_global_scales(list(curves.values()), set(context["weakNames"]), supports_by_name)
    source_supports: dict[str, list[float]] = {}
    canonical_supports: dict[str, list[float]] = {}
    v18_supports: dict[str, list[float]] = {}
    for name in V19_SOURCE_BOUNDARY_TARGET_ROLES:
        curve = curves.get(name)
        if not curve:
            continue
        raw, _ = v19_source_raw_supports(curve, "curvature-memory-growth-equation")
        source_supports[name] = [max(0.0, scales["curvature-memory-growth-equation"] * value) for value in raw]
        canonical_supports[name] = v18_competitor_canonical_supports(curve)
        v18_supports[name] = supports_by_name.get(name, [])
    return curves, source_supports, canonical_supports, v18_supports, context


def v19_source_boundary_score_variant(
    variant: dict,
    curves: dict[str, dict],
    source_supports: dict[str, list[float]],
    canonical_supports: dict[str, list[float]],
    v18_supports: dict[str, list[float]],
    counter_context: dict[str, dict],
    facts_context: dict[str, dict],
) -> tuple[dict, list[dict]]:
    case_rows: list[dict] = []
    factors = variant.get("factors", {})
    for name, role in V19_SOURCE_BOUNDARY_TARGET_ROLES.items():
        curve = curves.get(name)
        source = source_supports.get(name, [])
        canonical = canonical_supports.get(name, [])
        target = v18_supports.get(name, [])
        if not curve or len(source) != len(curve["points"]) or len(target) != len(curve["points"]):
            continue
        factor = parse_float(factors.get(name, 1.0), 1.0)
        candidate_supports = v19_source_boundary_supports(curve, source, factor)
        source_score = v18_competitor_support_score(curve, source)
        candidate_score = v18_competitor_support_score(curve, candidate_supports)
        canonical_score = v18_competitor_support_score(curve, canonical)
        v18_score = v18_competitor_support_score(curve, target)
        counter = counter_context.get(name, {})
        facts = facts_context.get(name, {})
        case_rows.append(
            {
                "variantId": variant["variantId"],
                "variantClass": variant["variantClass"],
                "galaxy": name,
                "targetRole": role,
                "lockedRoute": curve.get("lockedModelRoute", ""),
                "sourceBoundaryFactor": factor,
                "canonicalRmse": canonical_score["rmse"],
                "lockedV18Rmse": v18_score["rmse"],
                "fullSourceRmse": source_score["rmse"],
                "candidateRmse": candidate_score["rmse"],
                "sourceMinusV18KmS": source_score["rmse"] - v18_score["rmse"],
                "candidateMinusV18KmS": candidate_score["rmse"] - v18_score["rmse"],
                "candidateImprovementVsFullSourceKmS": source_score["rmse"] - candidate_score["rmse"],
                "candidateGainVsCanonicalPct": pct_improvement(canonical_score["rmse"], candidate_score["rmse"]),
                "fullSourceGainVsCanonicalPct": pct_improvement(canonical_score["rmse"], source_score["rmse"]),
                "lockedV18GainVsCanonicalPct": pct_improvement(canonical_score["rmse"], v18_score["rmse"]),
                "counterEvidenceDecision": counter.get("admissibilityDecision", ""),
                "counterNextPhysicalVariable": counter.get("nextPhysicalVariable", ""),
                "kinematicFactsVerdict": facts.get("verdict", ""),
                "quietEvidenceRows": facts.get("quietEvidenceRows", ""),
                "boundaryEvidenceRows": facts.get("boundaryEvidenceRows", ""),
                "numericEvidenceRows": facts.get("numericEvidenceRows", ""),
            }
        )
    protected_rows = [row for row in case_rows if "protected" in row["targetRole"]]
    prior_cap_rows = [row for row in case_rows if row["targetRole"] == "protected cap control"]
    admit_rows = [row for row in case_rows if row["targetRole"] == "admit high/source-load control"]
    unexplained_rows = [row for row in case_rows if "unexplained" in row["targetRole"]]
    ngc3198 = next((row for row in case_rows if row["galaxy"] == "NGC3198"), {})
    protected_improvement = safe_mean(parse_float(row["candidateImprovementVsFullSourceKmS"], 0.0) for row in protected_rows)
    prior_cap_improvement = safe_mean(parse_float(row["candidateImprovementVsFullSourceKmS"], 0.0) for row in prior_cap_rows)
    admit_penalty = safe_mean(max(0.0, parse_float(row["candidateRmse"], 0.0) - parse_float(row["fullSourceRmse"], 0.0)) for row in admit_rows)
    metric = {
        "variantId": variant["variantId"],
        "variantClass": variant["variantClass"],
        "description": variant["description"],
        "promotableAsLaw": variant["promotable"],
        "targetCaseCount": len(case_rows),
        "protectedCaseCount": len(protected_rows),
        "admitCaseCount": len(admit_rows),
        "protectedMeanImprovementVsFullSourceKmS": protected_improvement,
        "priorCapMeanImprovementVsFullSourceKmS": prior_cap_improvement,
        "ngc3198ImprovementVsFullSourceKmS": parse_float(ngc3198.get("candidateImprovementVsFullSourceKmS"), math.nan),
        "ngc3198CandidateMinusV18KmS": parse_float(ngc3198.get("candidateMinusV18KmS"), math.nan),
        "admitMeanPenaltyVsFullSourceKmS": admit_penalty,
        "admitMaxPenaltyVsFullSourceKmS": max([max(0.0, parse_float(row["candidateRmse"], 0.0) - parse_float(row["fullSourceRmse"], 0.0)) for row in admit_rows] or [0.0]),
        "protectedMaxRegressionVsV18KmS": max([parse_float(row["candidateMinusV18KmS"], -math.inf) for row in protected_rows] or [0.0]),
        "priorCapMaxRegressionVsV18KmS": max([parse_float(row["candidateMinusV18KmS"], -math.inf) for row in prior_cap_rows] or [0.0]),
        "unexplainedMeanCandidateMinusV18KmS": safe_mean(parse_float(row["candidateMinusV18KmS"], 0.0) for row in unexplained_rows),
        "targetUtilityKmS": protected_improvement - admit_penalty,
    }
    return metric, case_rows


def v19_source_boundary_null_controls(
    curves: dict[str, dict],
    source_supports: dict[str, list[float]],
    canonical_supports: dict[str, list[float]],
    v18_supports: dict[str, list[float]],
    counter_context: dict[str, dict],
    facts_context: dict[str, dict],
    seed: int = 20260525,
    draws: int = 500,
) -> list[dict]:
    names = [name for name in V19_SOURCE_BOUNDARY_TARGET_ROLES if name in curves]
    active_count = 4
    rng = random.Random(seed)
    rows: list[dict] = []
    for draw in range(draws):
        capped = set(rng.sample(names, min(active_count, len(names))))
        variant = {
            "variantId": f"random-cap-{draw}",
            "variantClass": "same-active-count-null",
            "description": "Randomly cap the same number of target cases as the quiet-boundary cap.",
            "factors": {name: 0.0 for name in capped},
            "promotable": False,
        }
        metric, _ = v19_source_boundary_score_variant(
            variant,
            curves,
            source_supports,
            canonical_supports,
            v18_supports,
            counter_context,
            facts_context,
        )
        rows.append(
            {
                "nullType": "same-active-count-random-cap",
                "draw": draw,
                "activeCount": len(capped),
                "activeTargets": ";".join(sorted(capped)),
                "targetUtilityKmS": metric["targetUtilityKmS"],
                "protectedMeanImprovementVsFullSourceKmS": metric["protectedMeanImprovementVsFullSourceKmS"],
                "ngc3198ImprovementVsFullSourceKmS": metric["ngc3198ImprovementVsFullSourceKmS"],
                "admitMeanPenaltyVsFullSourceKmS": metric["admitMeanPenaltyVsFullSourceKmS"],
            }
        )
    for draw in range(draws):
        softened = set(rng.sample(names, min(active_count, len(names))))
        variant = {
            "variantId": f"random-soften-{draw}",
            "variantClass": "same-active-count-null",
            "description": "Randomly soften the same number of target cases to a 25% source response.",
            "factors": {name: 0.25 for name in softened},
            "promotable": False,
        }
        metric, _ = v19_source_boundary_score_variant(
            variant,
            curves,
            source_supports,
            canonical_supports,
            v18_supports,
            counter_context,
            facts_context,
        )
        rows.append(
            {
                "nullType": "same-active-count-random-soften-025",
                "draw": draw,
                "activeCount": len(softened),
                "activeTargets": ";".join(sorted(softened)),
                "targetUtilityKmS": metric["targetUtilityKmS"],
                "protectedMeanImprovementVsFullSourceKmS": metric["protectedMeanImprovementVsFullSourceKmS"],
                "ngc3198ImprovementVsFullSourceKmS": metric["ngc3198ImprovementVsFullSourceKmS"],
                "admitMeanPenaltyVsFullSourceKmS": metric["admitMeanPenaltyVsFullSourceKmS"],
            }
        )
    return rows


def v19_source_boundary_null_summary(null_rows: list[dict]) -> dict:
    utilities = [parse_float(row["targetUtilityKmS"], math.nan) for row in null_rows]
    utilities = [value for value in utilities if math.isfinite(value)]
    return {
        "nullUtilityMedianKmS": safe_median(utilities) if utilities else math.nan,
        "nullUtilityP95KmS": v19_quantile(utilities, 0.95) if utilities else math.nan,
        "nullUtilityMaxKmS": max(utilities) if utilities else math.nan,
    }


def write_v19_source_boundary_test_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_v19_source_boundary_test"
    curves, source_supports, canonical_supports, v18_supports, context = v19_source_boundary_case_base()
    counter_context, facts_context = v19_source_boundary_evidence_context()
    score_rows: list[dict] = []
    case_rows: list[dict] = []
    variant_rows: list[dict] = []
    for variant in v19_source_boundary_variant_specs():
        metric, cases = v19_source_boundary_score_variant(
            variant,
            curves,
            source_supports,
            canonical_supports,
            v18_supports,
            counter_context,
            facts_context,
        )
        score_rows.append(metric)
        case_rows.extend(cases)
        variant_rows.append(
            {
                "variantId": variant["variantId"],
                "variantClass": variant["variantClass"],
                "description": variant["description"],
                "sourceBoundaryFactors": ";".join(f"{name}:{factor}" for name, factor in sorted(variant.get("factors", {}).items())) or "all targets:1.0",
                "promotableAsLaw": variant["promotable"],
            }
        )
    null_rows = v19_source_boundary_null_controls(
        curves,
        source_supports,
        canonical_supports,
        v18_supports,
        counter_context,
        facts_context,
    )
    null_summary = v19_source_boundary_null_summary(null_rows)
    candidates = [row for row in score_rows if row["variantClass"] == "evidence-gated-stress"]
    best = max(candidates, key=lambda row: (parse_float(row["targetUtilityKmS"], -math.inf), parse_float(row["ngc3198ImprovementVsFullSourceKmS"], -math.inf)))
    overbroad = next((row for row in score_rows if row["variantId"] == "overbroad-boundary-cap"), {})
    if (
        parse_float(best["ngc3198ImprovementVsFullSourceKmS"], 0.0) > 0.25
        and parse_float(best["admitMaxPenaltyVsFullSourceKmS"], math.inf) <= 1.0
        and parse_float(best["targetUtilityKmS"], -math.inf) > parse_float(null_summary["nullUtilityP95KmS"], math.inf)
    ):
        verdict = "source-boundary candidate input"
    elif (
        parse_float(best["ngc3198ImprovementVsFullSourceKmS"], 0.0) > 0.25
        and parse_float(best["admitMaxPenaltyVsFullSourceKmS"], math.inf) <= 1.0
    ):
        verdict = "quiet-boundary cap anatomy"
    elif parse_float(overbroad.get("admitMaxPenaltyVsFullSourceKmS"), 0.0) > 1.0:
        verdict = "boundary evidence too broad"
    else:
        verdict = "source-boundary rule not supported"
    formula = {
        "candidateId": "mts-v19-source-boundary-test-v1",
        "status": verdict,
        "baseEquation": "curvature-memory-growth-equation",
        "bestVariant": best,
        "sourceBoundaryOperation": "S_candidate(r)=S_canonical(r)+f_boundary*(S_source_equation(r)-S_canonical(r))",
        "boundaryFactorMeaning": "f=1 full source response; f=0 canonical/no added source response; 0<f<1 softened source loading",
        "promotableAsLaw": False,
        "whyNotPromotableYet": "This mode uses named source-evidence cases to test the boundary hypothesis. A future law must derive the cap from numeric pre-residual source variables.",
        "canonicalMtsChanged": False,
        "browserChanged": False,
        "forbiddenInputsForFutureLaw": ["galaxy name", "raw residual", "raw RMSE", "NFW parameter", "MOND parameter", "weak/systematics fitting"],
    }
    write_csv(out_dir / f"{prefix}_scores.csv", score_rows)
    write_csv(out_dir / f"{prefix}_case_ledger.csv", case_rows)
    write_csv(out_dir / f"{prefix}_variant_ledger.csv", variant_rows)
    write_csv(out_dir / f"{prefix}_null_controls.csv", null_rows)
    (out_dir / f"{prefix}_formula.json").write_text(json.dumps(json_clean(formula), indent=2, sort_keys=True), encoding="utf-8")
    report = [
        "# MTS v19 Source-Boundary Admissibility Test",
        "",
        "This is a direct source-boundary stress test. It does not change v18, v19, the browser, or any release law.",
        "",
        f"Verdict: `{verdict}`.",
        f"Best variant: `{best['variantId']}`.",
        f"NGC3198 improvement vs full source equation: `{fmt(best['ngc3198ImprovementVsFullSourceKmS'])}` km/s.",
        f"Protected mean improvement vs full source equation: `{fmt(best['protectedMeanImprovementVsFullSourceKmS'])}` km/s.",
        f"Admitted high/source-load max penalty vs full source equation: `{fmt(best['admitMaxPenaltyVsFullSourceKmS'])}` km/s.",
        f"Target utility: `{fmt(best['targetUtilityKmS'])}` km/s; null p95 `{fmt(null_summary['nullUtilityP95KmS'])}` km/s.",
        "",
        "## What Changed",
        "",
        "Nothing in the locked framework changed. The tested operation only blends the v19 source-equation support back toward canonical MTS support for evidence-tagged boundary/cap cases:",
        "",
        "```text",
        "S_candidate(r) = S_canonical(r) + f_boundary * [S_source(r) - S_canonical(r)]",
        "```",
        "",
        "## Variant Scores",
        "",
        "| Variant | Protected improve | NGC3198 improve | Admit max penalty | Utility |",
        "| --- | ---: | ---: | ---: | ---: |",
    ]
    for row in score_rows:
        report.append(
            f"| {row['variantId']} | {fmt(row['protectedMeanImprovementVsFullSourceKmS'])} | {fmt(row['ngc3198ImprovementVsFullSourceKmS'])} | {fmt(row['admitMaxPenaltyVsFullSourceKmS'])} | {fmt(row['targetUtilityKmS'])} |"
        )
    report.extend(
        [
            "",
            "## Interpretation",
            "",
            "NGC3198 is treated as a quiet-boundary countercase: source papers suggest a generally regular velocity field plus coherent boundary/streaming/extraplanar structure. The useful question is whether that class should soften or cap source loading, without also suppressing admitted high/source-load controls.",
            "",
            "The overbroad-boundary negative control is deliberately included: if it damages admitted controls, boundary keywords alone are not a physical law.",
            "",
            "## Guardrails",
            "",
            "- No browser or v18 release law was changed.",
            "- No weak/systematics cases are fitted.",
            "- Names are used only to attach external evidence cases in this stress test.",
            "- A future promotable law must replace the evidence labels with numeric pre-residual source variables.",
            "",
            verdict,
        ]
    )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report) + "\n", encoding="utf-8")
    capsule = {
        "analysisName": "mts-v19-source-boundary-test-v1",
        "verdict": verdict,
        "bestVariant": best,
        "nullSummary": null_summary,
        "targetCount": len(V19_SOURCE_BOUNDARY_TARGET_ROLES),
        "weakSystematicsLeakage": 0,
        "canonicalMtsChanged": False,
        "browserChanged": False,
        "releaseLawChanged": False,
        "outputFiles": [
            f"{prefix}_report.md",
            f"{prefix}_scores.csv",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_variant_ledger.csv",
            f"{prefix}_null_controls.csv",
            f"{prefix}_formula.json",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_v19sourceboundarytest(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_V19_SOURCE_BOUNDARY_TEST_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    capsule = write_v19_source_boundary_test_artifacts(out_dir)
    best = capsule["bestVariant"]
    print("MTS v19 source-boundary admissibility test")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"best={best['variantId']}",
                f"ngc3198_improve={fmt(best['ngc3198ImprovementVsFullSourceKmS'])}",
                f"protected_improve={fmt(best['protectedMeanImprovementVsFullSourceKmS'])}",
                f"admit_penalty={fmt(best['admitMaxPenaltyVsFullSourceKmS'])}",
                f"utility={fmt(best['targetUtilityKmS'])}",
            ]
        )
    )
    print(f"Wrote v19 source-boundary test to {out_dir.resolve()}")


V19_BOUNDARY_NUMERIC_EXTERNAL_FEATURES = V19_NUMERIC_TWO_D_EXTERNAL_FEATURES


V19_BOUNDARY_NUMERIC_STATE_FEATURES = [
    "memoryLoad",
    "u075",
    "uOut",
    "uMax",
    "fGasOut",
    "rOutOverH",
    "lGapOverH",
    "satFraction",
    "outerGasShare",
    "outerDiskShare",
    "outerBulgeShare",
    "barCurvAbs",
    "pointDensity",
    "vObsOuterSlope",
    "vObsOuterCurvatureAbs",
    "vObsOuterSmoothness",
    "vObsOuterRiseFraction",
    "vObsInnerOuterSlopeRatio",
    "vBarOuterSlope",
    "vBarOuterCurvatureAbs",
    "vGasOuterSlope",
    "vDiskOuterSlope",
]


def v19_boundary_numeric_curve_shape_features(curve: dict) -> dict:
    points = sorted(curve.get("points", []), key=lambda point: parse_float(point.get("r"), 0.0))
    r_out = max(1.0e-9, parse_float(curve.get("rOut"), points[-1].get("r", 1.0) if points else 1.0))

    def series(key: str) -> list[tuple[float, float]]:
        values = []
        for point in points:
            radius = parse_float(point.get("r"), math.nan)
            if key == "vBar":
                value = math.sqrt(max(0.0, parse_float(point.get("bar2"), math.nan)))
            else:
                value = parse_float(point.get(key), math.nan)
            if math.isfinite(radius) and math.isfinite(value):
                values.append((radius, value))
        return values

    def slope(values: list[tuple[float, float]], low_x: float, high_x: float = 1.01) -> float:
        subset = [(r, v) for r, v in values if low_x <= r / r_out <= high_x]
        if len(subset) < 2:
            subset = values[-min(3, len(values)):]
        if len(subset) < 2:
            return math.nan
        r0, v0 = subset[0]
        r1, v1 = subset[-1]
        return (v1 - v0) / max(1.0e-9, r1 - r0)

    def curvature(values: list[tuple[float, float]], low_x: float) -> float:
        subset = [(r, v) for r, v in values if r / r_out >= low_x]
        if len(subset) < 3:
            subset = values[-min(5, len(values)):]
        if len(subset) < 3:
            return math.nan
        curvatures = []
        for left, mid, right in zip(subset, subset[1:], subset[2:]):
            dr1 = max(1.0e-9, mid[0] - left[0])
            dr2 = max(1.0e-9, right[0] - mid[0])
            s1 = (mid[1] - left[1]) / dr1
            s2 = (right[1] - mid[1]) / dr2
            curvatures.append(abs((s2 - s1) / max(1.0e-9, 0.5 * (dr1 + dr2))))
        return safe_mean(curvatures)

    def smoothness(values: list[tuple[float, float]], low_x: float) -> float:
        subset = [(r, v) for r, v in values if r / r_out >= low_x]
        if len(subset) < 4:
            subset = values[-min(6, len(values)):]
        if len(subset) < 3:
            return math.nan
        slopes = []
        for left, right in zip(subset, subset[1:]):
            slopes.append((right[1] - left[1]) / max(1.0e-9, right[0] - left[0]))
        mean_abs = safe_mean(abs(value) for value in slopes)
        variance = safe_mean((value - safe_mean(slopes)) ** 2 for value in slopes)
        return math.sqrt(variance) / max(1.0e-9, mean_abs)

    vobs = series("vObs")
    vbar = series("vBar")
    vgas = series("vGas")
    vdisk = series("vDisk")
    outer_slope = slope(vobs, 0.60)
    inner_slope = slope(vobs, 0.05, 0.40)
    outer_values = [v for r, v in vobs if r / r_out >= 0.60]
    inner_values = [v for r, v in vobs if r / r_out <= 0.40]
    return {
        "vObsOuterSlope": outer_slope,
        "vObsOuterCurvatureAbs": curvature(vobs, 0.55),
        "vObsOuterSmoothness": smoothness(vobs, 0.55),
        "vObsOuterRiseFraction": ((outer_values[-1] - outer_values[0]) / max(1.0e-9, max(outer_values))) if len(outer_values) >= 2 else math.nan,
        "vObsInnerOuterSlopeRatio": inner_slope / max(1.0e-9, abs(outer_slope)) if math.isfinite(inner_slope) and math.isfinite(outer_slope) else math.nan,
        "vBarOuterSlope": slope(vbar, 0.60),
        "vBarOuterCurvatureAbs": curvature(vbar, 0.55),
        "vGasOuterSlope": slope(vgas, 0.60),
        "vDiskOuterSlope": slope(vdisk, 0.60),
    }


def v19_boundary_numeric_case_matrix(parser_dir: Path) -> list[dict]:
    context = observed_state_candidate_context()
    curves_by_name = {curve["name"]: curve for curve in context["curves"]}
    external_rows = v19_external_2d_admissibility_rows(parser_dir)
    external_by_name = {row["galaxy"]: row for row in external_rows}
    counter_context, facts_context = v19_source_boundary_evidence_context()
    boundary_case_path = DEFAULT_V19_SOURCE_BOUNDARY_TEST_OUT / "mts_v19_source_boundary_test_case_ledger.csv"
    if not boundary_case_path.exists():
        write_v19_source_boundary_test_artifacts(DEFAULT_V19_SOURCE_BOUNDARY_TEST_OUT)
    boundary_rows = [
        row for row in read_csv_rows(boundary_case_path)
        if row.get("variantId") == "quiet-boundary-soften-050"
    ]
    boundary_by_name = {row["galaxy"]: row for row in boundary_rows}
    out: list[dict] = []
    for name, role in V19_SOURCE_BOUNDARY_TARGET_ROLES.items():
        curve = curves_by_name.get(name)
        state = v19_admissibility_features(curve) if curve else {}
        shape = v19_boundary_numeric_curve_shape_features(curve) if curve else {}
        external = external_by_name.get(name, {})
        boundary = boundary_by_name.get(name, {})
        if role == "protected cap control":
            train_label = "cap"
            target_factor = 0.0
        elif role == "admit high/source-load control":
            train_label = "admit"
            target_factor = 1.0
        else:
            train_label = "holdout"
            target_factor = ""
        row = {
            "galaxy": name,
            "targetRole": role,
            "trainLabel": train_label,
            "lockedRoute": curve.get("lockedModelRoute", "") if curve else "",
            "targetBoundaryFactorForTraining": target_factor,
            "sourceBoundaryBestFactor": boundary.get("sourceBoundaryFactor", ""),
            "sourceBoundaryBestCandidateRmse": boundary.get("candidateRmse", ""),
            "sourceBoundaryBestFullSourceRmse": boundary.get("fullSourceRmse", ""),
            "counterEvidenceDecision": counter_context.get(name, {}).get("admissibilityDecision", ""),
            "kinematicFactsVerdict": facts_context.get(name, {}).get("verdict", ""),
            "sourceFamily": external.get("sourceFamily", ""),
            "sourcePath": external.get("sourcePath", "MISSING"),
            "external2DRowCount": external.get("external2DRowCount", 0),
        }
        for feature in V19_BOUNDARY_NUMERIC_STATE_FEATURES:
            row[feature] = shape.get(feature, state.get(feature, ""))
        for feature in V19_BOUNDARY_NUMERIC_EXTERNAL_FEATURES:
            row[feature] = external.get(feature, "")
            row[f"{feature}Count"] = external.get(f"{feature}Count", 0)
        out.append(row)
    return out


def v19_boundary_numeric_feature_list(rows: list[dict]) -> list[str]:
    features = V19_BOUNDARY_NUMERIC_STATE_FEATURES + V19_BOUNDARY_NUMERIC_EXTERNAL_FEATURES
    train_rows = [row for row in rows if row["trainLabel"] in {"cap", "admit"}]
    usable = []
    for feature in features:
        values = [parse_float(row.get(feature), math.nan) for row in train_rows]
        values = [value for value in values if math.isfinite(value)]
        if len(values) >= 4 and len(set(round(value, 8) for value in values)) >= 2:
            usable.append(feature)
    return usable


def v19_boundary_numeric_rule_candidates(rows: list[dict]) -> list[dict]:
    train_rows = [row for row in rows if row["trainLabel"] in {"cap", "admit"}]
    features = v19_boundary_numeric_feature_list(rows)
    rules: list[dict] = []
    for feature in features:
        values = [parse_float(row.get(feature), math.nan) for row in train_rows]
        values = [value for value in values if math.isfinite(value)]
        for q in [0.20, 0.25, 0.33, 0.50, 0.66, 0.75, 0.80]:
            threshold = v19_quantile(values, q)
            for direction in ["high", "low"]:
                rules.append(
                    {
                        "ruleId": f"{feature}-{direction}-q{int(q*100)}",
                        "ruleType": "one-variable-soft",
                        "feature": feature,
                        "direction": direction,
                        "threshold": threshold,
                        "feature2": "",
                        "direction2": "",
                        "threshold2": "",
                    }
                )
    compact_features = {
        "memoryLoad",
        "u075",
        "uOut",
        "uMax",
        "fGasOut",
        "outerGasShare",
        "outerDiskShare",
        "vObsOuterSlope",
        "vObsOuterCurvatureAbs",
        "vObsOuterSmoothness",
        "vObsOuterRiseFraction",
        "thingsMorphologyM20",
        "thingsMorphologyAsymmetryA",
        "whispM20",
        "whispP4M20",
        "whispP6M20",
    }
    compact = [
        rule for rule in rules
        if rule["feature"] in compact_features and "-q50" in rule["ruleId"]
    ]
    for left in compact:
        for right in compact:
            if left["feature"] >= right["feature"]:
                continue
            rules.append(
                {
                    "ruleId": f"{left['ruleId']} AND {right['ruleId']}",
                    "ruleType": "two-variable-soft-product",
                    "feature": left["feature"],
                    "direction": left["direction"],
                    "threshold": left["threshold"],
                    "feature2": right["feature"],
                    "direction2": right["direction"],
                    "threshold2": right["threshold"],
                }
            )
    return rules


def v19_boundary_numeric_activation(row: dict, rule: dict) -> float:
    activation = v19_gate_value(row, rule["feature"], parse_float(rule["threshold"], 0.0), rule["direction"])
    if rule.get("feature2"):
        activation *= v19_gate_value(row, rule["feature2"], parse_float(rule["threshold2"], 0.0), rule["direction2"])
    return clamp(activation, 0.0, 1.0)


def v19_boundary_numeric_prefilter_rules(rows: list[dict], rules: list[dict], label_key: str = "trainLabel", limit: int = 220) -> list[dict]:
    scored: list[dict] = []
    cap_rows = [row for row in rows if row.get(label_key) == "cap"]
    admit_rows = [row for row in rows if row.get(label_key) == "admit"]
    for rule in rules:
        cap_activation = safe_mean(v19_boundary_numeric_activation(row, rule) for row in cap_rows)
        admit_activation = safe_mean(v19_boundary_numeric_activation(row, rule) for row in admit_rows)
        scored.append(
            {
                **rule,
                "prefilterCapMeanActivation": cap_activation,
                "prefilterAdmitMeanActivation": admit_activation,
                "prefilterSeparation": cap_activation - admit_activation,
            }
        )
    scored.sort(
        key=lambda row: (
            parse_float(row["prefilterSeparation"], -math.inf),
            parse_float(row["prefilterCapMeanActivation"], -math.inf),
            -parse_float(row["prefilterAdmitMeanActivation"], math.inf),
            -len(str(row["ruleId"])),
        ),
        reverse=True,
    )
    return scored[:limit]


def v19_boundary_numeric_score_rule(
    rows: list[dict],
    curves: dict[str, dict],
    source_supports: dict[str, list[float]],
    canonical_supports: dict[str, list[float]],
    v18_supports: dict[str, list[float]],
    rule: dict,
    beta: float,
    label_key: str = "trainLabel",
) -> tuple[dict, list[dict]]:
    case_rows: list[dict] = []
    for row in rows:
        name = row["galaxy"]
        curve = curves.get(name)
        source = source_supports.get(name, [])
        target = v18_supports.get(name, [])
        canonical = canonical_supports.get(name, [])
        if not curve or len(source) != len(curve["points"]) or len(target) != len(curve["points"]):
            continue
        activation = v19_boundary_numeric_activation(row, rule)
        factor = clamp(1.0 - beta * activation, 0.0, 1.0)
        candidate_supports = v19_source_boundary_supports(curve, source, factor)
        source_score = v18_competitor_support_score(curve, source)
        candidate_score = v18_competitor_support_score(curve, candidate_supports)
        canonical_score = v18_competitor_support_score(curve, canonical)
        v18_score = v18_competitor_support_score(curve, target)
        case_rows.append(
            {
                "galaxy": name,
                "targetRole": row["targetRole"],
                "label": row.get(label_key, row.get("trainLabel", "")),
                "originalTrainLabel": row.get("trainLabel", ""),
                "lockedRoute": row.get("lockedRoute", ""),
                "ruleId": rule["ruleId"],
                "ruleType": rule["ruleType"],
                "beta": beta,
                "activation": activation,
                "predictedBoundaryFactor": factor,
                "canonicalRmse": canonical_score["rmse"],
                "lockedV18Rmse": v18_score["rmse"],
                "fullSourceRmse": source_score["rmse"],
                "candidateRmse": candidate_score["rmse"],
                "candidateImprovementVsFullSourceKmS": source_score["rmse"] - candidate_score["rmse"],
                "candidateMinusV18KmS": candidate_score["rmse"] - v18_score["rmse"],
                "candidateGainVsCanonicalPct": pct_improvement(canonical_score["rmse"], candidate_score["rmse"]),
                "feature": rule["feature"],
                "featureValue": row.get(rule["feature"], ""),
                "feature2": rule.get("feature2", ""),
                "feature2Value": row.get(rule.get("feature2", ""), "") if rule.get("feature2") else "",
            }
        )
    train_rows = [row for row in case_rows if row["label"] in {"cap", "admit"}]
    cap_rows = [row for row in train_rows if row["label"] == "cap"]
    admit_rows = [row for row in train_rows if row["label"] == "admit"]
    ngc3198 = next((row for row in case_rows if row["galaxy"] == "NGC3198"), {})
    train_cap_improve = safe_mean(parse_float(row["candidateImprovementVsFullSourceKmS"], 0.0) for row in cap_rows)
    admit_penalty = safe_mean(max(0.0, parse_float(row["candidateRmse"], 0.0) - parse_float(row["fullSourceRmse"], 0.0)) for row in admit_rows)
    metric = {
        **rule,
        "beta": beta,
        "trainCapCount": len(cap_rows),
        "trainAdmitCount": len(admit_rows),
        "trainCapMeanImprovementVsFullSourceKmS": train_cap_improve,
        "trainAdmitMeanPenaltyVsFullSourceKmS": admit_penalty,
        "trainAdmitMaxPenaltyVsFullSourceKmS": max([max(0.0, parse_float(row["candidateRmse"], 0.0) - parse_float(row["fullSourceRmse"], 0.0)) for row in admit_rows] or [0.0]),
        "trainUtilityKmS": train_cap_improve - admit_penalty,
        "trainCapMeanActivation": safe_mean(parse_float(row["activation"], 0.0) for row in cap_rows),
        "trainAdmitMeanActivation": safe_mean(parse_float(row["activation"], 0.0) for row in admit_rows),
        "ngc3198Activation": parse_float(ngc3198.get("activation"), math.nan),
        "ngc3198PredictedBoundaryFactor": parse_float(ngc3198.get("predictedBoundaryFactor"), math.nan),
        "ngc3198ImprovementVsFullSourceKmS": parse_float(ngc3198.get("candidateImprovementVsFullSourceKmS"), math.nan),
        "ngc3198CandidateMinusV18KmS": parse_float(ngc3198.get("candidateMinusV18KmS"), math.nan),
    }
    return metric, case_rows


def v19_boundary_numeric_select_best(
    rows: list[dict],
    rules: list[dict],
    label_key: str = "trainLabel",
    cached_base: tuple[dict[str, dict], dict[str, list[float]], dict[str, list[float]], dict[str, list[float]]] | None = None,
) -> tuple[dict, list[dict], list[dict]]:
    if cached_base is None:
        curves, source_supports, canonical_supports, v18_supports, _context = v19_source_boundary_case_base()
    else:
        curves, source_supports, canonical_supports, v18_supports = cached_base
    score_rows: list[dict] = []
    best_cases: list[dict] = []
    for rule in rules:
        for beta in [0.35, 0.50, 0.65, 0.80, 1.00]:
            metric, cases = v19_boundary_numeric_score_rule(
                rows,
                curves,
                source_supports,
                canonical_supports,
                v18_supports,
                rule,
                beta,
                label_key,
            )
            score_rows.append(metric)
    score_rows.sort(
        key=lambda row: (
            parse_float(row["trainUtilityKmS"], -math.inf),
            parse_float(row["trainCapMeanActivation"], -math.inf) - parse_float(row["trainAdmitMeanActivation"], math.inf),
            -parse_float(row["trainAdmitMaxPenaltyVsFullSourceKmS"], math.inf),
            parse_float(row["ngc3198ImprovementVsFullSourceKmS"], -math.inf),
        ),
        reverse=True,
    )
    best = score_rows[0] if score_rows else {}
    if best:
        _, best_cases = v19_boundary_numeric_score_rule(
            rows,
            curves,
            source_supports,
            canonical_supports,
            v18_supports,
            best,
            parse_float(best["beta"], 0.0),
            label_key,
        )
    return best, score_rows, best_cases


def v19_boundary_numeric_null_controls(rows: list[dict], rules: list[dict], draws: int = 30, seed: int = 20260525) -> list[dict]:
    train_rows = [row for row in rows if row["trainLabel"] in {"cap", "admit"}]
    labels = [row["trainLabel"] for row in train_rows]
    rng = random.Random(seed)
    out: list[dict] = []
    curves, source_supports, canonical_supports, v18_supports, _context = v19_source_boundary_case_base()
    cached_base = (curves, source_supports, canonical_supports, v18_supports)
    for draw in range(draws):
        shuffled = labels[:]
        rng.shuffle(shuffled)
        label_by_name = {row["galaxy"]: label for row, label in zip(train_rows, shuffled)}
        shuffled_rows = [
            {**row, "shuffledLabel": label_by_name.get(row["galaxy"], row["trainLabel"])}
            for row in rows
        ]
        shuffled_rules = v19_boundary_numeric_prefilter_rules(shuffled_rows, rules, "shuffledLabel", 40)
        best, _scores, _cases = v19_boundary_numeric_select_best(shuffled_rows, shuffled_rules, "shuffledLabel", cached_base)
        out.append(
            {
                "nullType": "shuffled-cap-admit-labels",
                "draw": draw,
                "bestTrainUtilityKmS": best.get("trainUtilityKmS", ""),
                "bestRuleId": best.get("ruleId", ""),
                "bestBeta": best.get("beta", ""),
                "ngc3198ImprovementVsFullSourceKmS": best.get("ngc3198ImprovementVsFullSourceKmS", ""),
            }
        )
    return out


def v19_boundary_numeric_feature_contrast(rows: list[dict], features: list[str]) -> list[dict]:
    out = []
    cap = [row for row in rows if row["trainLabel"] == "cap"]
    admit = [row for row in rows if row["trainLabel"] == "admit"]
    ngc = next((row for row in rows if row["galaxy"] == "NGC3198"), {})
    for feature in features:
        cap_values = [parse_float(row.get(feature), math.nan) for row in cap]
        admit_values = [parse_float(row.get(feature), math.nan) for row in admit]
        cap_values = [value for value in cap_values if math.isfinite(value)]
        admit_values = [value for value in admit_values if math.isfinite(value)]
        out.append(
            {
                "feature": feature,
                "capCount": len(cap_values),
                "admitCount": len(admit_values),
                "capMedian": safe_median(cap_values),
                "admitMedian": safe_median(admit_values),
                "capMinusAdmitMedian": safe_median(cap_values) - safe_median(admit_values) if cap_values and admit_values else math.nan,
                "ngc3198Value": ngc.get(feature, ""),
            }
        )
    return out


def write_v19_boundary_numeric_law_artifacts(out_dir: Path, parser_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_v19_boundary_numeric_law"
    rows = v19_boundary_numeric_case_matrix(parser_dir)
    all_rules = v19_boundary_numeric_rule_candidates(rows)
    rules = v19_boundary_numeric_prefilter_rules(rows, all_rules, "trainLabel", 60)
    best, score_rows, case_rows = v19_boundary_numeric_select_best(rows, rules)
    null_rows = v19_boundary_numeric_null_controls(rows, all_rules) if rules else []
    null_values = [parse_float(row.get("bestTrainUtilityKmS"), math.nan) for row in null_rows]
    null_values = [value for value in null_values if math.isfinite(value)]
    null_p95 = v19_quantile(null_values, 0.95) if null_values else math.nan
    null_margin = parse_float(best.get("trainUtilityKmS"), math.nan) - null_p95 if best else math.nan
    feature_rows = v19_boundary_numeric_feature_contrast(rows, v19_boundary_numeric_feature_list(rows))
    ngc_improve = parse_float(best.get("ngc3198ImprovementVsFullSourceKmS"), 0.0)
    ngc_factor = parse_float(best.get("ngc3198PredictedBoundaryFactor"), math.nan)
    if best and math.isfinite(null_margin) and null_margin >= 1.0 and 0.20 <= ngc_factor <= 0.85 and ngc_improve >= 3.0 and parse_float(best.get("trainAdmitMaxPenaltyVsFullSourceKmS"), math.inf) <= 1.0:
        verdict = "numeric boundary law candidate"
    elif best and math.isfinite(null_margin) and null_margin >= 1.0 and ngc_improve < 3.0:
        verdict = "numeric controls separable but NGC3198 not recovered"
    elif best and ngc_improve >= 3.0:
        verdict = "numeric boundary anatomy but not null-hardened"
    elif not rules:
        verdict = "insufficient numeric boundary features"
    else:
        verdict = "numeric source-boundary variable missing"
    formula = {
        "candidateId": "mts-v19-boundary-numeric-law-v1",
        "status": verdict,
        "baseEquation": "curvature-memory-growth-equation",
        "operation": "S_candidate(r)=S_canonical(r)+f_numeric*(S_source(r)-S_canonical(r))",
        "factor": "f_numeric=clamp(1-beta*activation_numeric,0,1)",
        "bestRule": best,
        "trainLabels": "protected cap controls and admitted high/source-load controls only; NGC3198 held out",
        "promotableAsLaw": verdict == "numeric boundary law candidate",
        "canonicalMtsChanged": False,
        "browserChanged": False,
        "forbiddenInputs": ["galaxy name", "raw residual", "raw RMSE", "NFW parameter", "MOND parameter", "weak/systematics fitting"],
    }
    write_csv(out_dir / f"{prefix}_case_matrix.csv", rows)
    write_csv(out_dir / f"{prefix}_scores.csv", score_rows)
    write_csv(out_dir / f"{prefix}_case_ledger.csv", case_rows)
    write_csv(out_dir / f"{prefix}_null_controls.csv", null_rows)
    write_csv(out_dir / f"{prefix}_feature_contrast.csv", feature_rows)
    (out_dir / f"{prefix}_formula.json").write_text(json.dumps(json_clean(formula), indent=2, sort_keys=True), encoding="utf-8")
    report = [
        "# MTS v19 Boundary Numeric Law Test",
        "",
        "This mode tries to replace the evidence-tagged source-boundary cap with a numeric pre-residual gate. It does not change v18, v19, the browser, or canonical MTS.",
        "",
        f"Verdict: `{verdict}`.",
        f"Best rule: `{best.get('ruleId', 'none')}`.",
        f"Beta: `{fmt(best.get('beta', ''))}`.",
        f"Train utility: `{fmt(best.get('trainUtilityKmS', ''))}` km/s.",
        f"Null p95 utility: `{fmt(null_p95)}` km/s.",
        f"Null margin: `{fmt(null_margin)}` km/s.",
        f"NGC3198 predicted boundary factor: `{fmt(ngc_factor)}`.",
        f"NGC3198 improvement vs full source: `{fmt(ngc_improve)}` km/s.",
        f"Admit-control max penalty: `{fmt(best.get('trainAdmitMaxPenaltyVsFullSourceKmS', ''))}` km/s.",
        "",
        "## Tested Law Form",
        "",
        "```text",
        "activation_numeric = gate(pre-residual state/profile/2D variables)",
        "f_numeric = clamp(1 - beta * activation_numeric, 0, 1)",
        "S_candidate(r) = S_canonical(r) + f_numeric * [S_source(r) - S_canonical(r)]",
        "```",
        "",
        "NGC3198 is not used as a training label. It is evaluated after the rule is selected from cap/admit controls.",
        "",
        "## Best-Rule Case Ledger",
        "",
        "| Galaxy | Role | factor | full source | candidate | improve |",
        "| --- | --- | ---: | ---: | ---: | ---: |",
    ]
    for row in case_rows:
        report.append(
            f"| {row['galaxy']} | {row['targetRole']} | {fmt(row['predictedBoundaryFactor'])} | {fmt(row['fullSourceRmse'])} | {fmt(row['candidateRmse'])} | {fmt(row['candidateImprovementVsFullSourceKmS'])} |"
        )
    report.extend(
        [
            "",
            "## Guardrails",
            "",
            "- No galaxy name enters the numeric rule.",
            "- No residual, RMSE, NFW, or MOND parameter enters the rule.",
            "- Weak/systematics cases are not fitted.",
            "- No browser/release law is changed.",
            "",
            verdict,
        ]
    )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report) + "\n", encoding="utf-8")
    capsule = {
        "analysisName": "mts-v19-boundary-numeric-law-v1",
        "verdict": verdict,
        "bestRule": best,
        "nullP95UtilityKmS": null_p95,
        "nullMarginKmS": null_margin,
        "caseCount": len(rows),
        "trainCapCount": sum(1 for row in rows if row["trainLabel"] == "cap"),
        "trainAdmitCount": sum(1 for row in rows if row["trainLabel"] == "admit"),
        "ngc3198HeldOut": True,
        "weakSystematicsLeakage": 0,
        "canonicalMtsChanged": False,
        "browserChanged": False,
        "outputFiles": [
            f"{prefix}_report.md",
            f"{prefix}_case_matrix.csv",
            f"{prefix}_scores.csv",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_null_controls.csv",
            f"{prefix}_feature_contrast.csv",
            f"{prefix}_formula.json",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def cmd_v19boundarynumericlaw(args: argparse.Namespace) -> None:
    out_dir = DEFAULT_V19_BOUNDARY_NUMERIC_LAW_OUT if args.out == str(DEFAULT_OUT) else Path(args.out)
    parser_dir = Path(args.source_dir) if args.source_dir else DEFAULT_V19_EXTERNAL_TWO_D_PARSER_OUT
    capsule = write_v19_boundary_numeric_law_artifacts(out_dir, parser_dir)
    best = capsule["bestRule"]
    print("MTS v19 boundary numeric law test")
    print(f"verdict={capsule['verdict']}")
    print(
        "\t".join(
            [
                f"best={best.get('ruleId', 'none')}",
                f"beta={fmt(best.get('beta', ''))}",
                f"utility={fmt(best.get('trainUtilityKmS', ''))}",
                f"null_margin={fmt(capsule.get('nullMarginKmS', ''))}",
                f"ngc3198_factor={fmt(best.get('ngc3198PredictedBoundaryFactor', ''))}",
                f"ngc3198_improve={fmt(best.get('ngc3198ImprovementVsFullSourceKmS', ''))}",
            ]
        )
    )
    print(f"Wrote v19 boundary numeric law test to {out_dir.resolve()}")


