def v19_persistence_field_components(curve: dict, source_factor: float) -> dict:
    state = v19_theory_kernel_state(curve)
    features = v19_admissibility_features(curve)
    route = curve.get("lockedModelRoute", "")
    lowload = 1.0 if route == "low-load" else 0.0
    buffered = 1.0 if route == "buffered single-crossing" else 0.0
    memory_load = parse_float(features.get("memoryLoad"), 0.0)
    u075 = parse_float(features.get("u075"), 0.0)
    uout = parse_float(features.get("uOut"), 0.0)
    umax = parse_float(features.get("uMax"), 0.0)
    r_over_h = parse_float(features.get("rOutOverH"), 0.0)
    fgas = parse_float(features.get("fGasOut"), 0.0)
    outer_disk = parse_float(features.get("outerDiskShare"), 0.0)
    point_density = parse_float(features.get("pointDensity"), 0.0)
    boundary_drive = parse_float(state.get("boundaryDrive"), 0.0)
    profile_drive = parse_float(state.get("profileDrive"), 0.0)
    not_source = 1.0 - clamp(source_factor, 0.0, 1.0)
    lowload_memory = (
        not_source
        * lowload
        * v19_smoothstep01(boundary_drive, 0.35, 0.52)
        * v19_smoothstep01(outer_disk, 0.68, 0.84)
        * (1.0 - v19_smoothstep01(fgas, 0.32, 0.58))
    )
    lowload_gas_boundary = (
        not_source
        * lowload
        * v19_smoothstep01(fgas, 0.48, 0.62)
        * v19_smoothstep01(u075, 0.42, 0.50)
        * (1.0 - v19_smoothstep01(memory_load, 2.4, 5.5))
    )
    buffered_phase = (
        not_source
        * buffered
        * v19_smoothstep01(r_over_h, 5.6, 8.5)
        * v19_smoothstep01(umax, 1.05, 1.35)
        * (1.0 - v19_smoothstep01(point_density, 1.00, 1.85))
    )
    compact_bulge_phase = (
        not_source
        * buffered
        * v19_smoothstep01(memory_load, 5.5, 8.5)
        * (1.0 - v19_smoothstep01(fgas, 0.14, 0.28))
        * (1.0 - v19_smoothstep01(outer_disk, 0.45, 0.75))
    )
    persistence = 1.0 - (
        (1.0 - lowload_memory)
        * (1.0 - lowload_gas_boundary)
        * (1.0 - buffered_phase)
        * (1.0 - compact_bulge_phase)
    )
    return {
        "lowLoadMemoryPersistence": clamp(lowload_memory, 0.0, 1.0),
        "lowLoadGasBoundaryPersistence": clamp(lowload_gas_boundary, 0.0, 1.0),
        "bufferedPhasePersistence": clamp(buffered_phase, 0.0, 1.0),
        "compactBulgePhasePersistence": clamp(compact_bulge_phase, 0.0, 1.0),
        "persistenceFieldActivation": clamp(persistence, 0.0, 1.0),
        "boundaryDrive": boundary_drive,
        "profileDrive": profile_drive,
        "memoryLoad": memory_load,
        "u075": u075,
        "uOut": uout,
        "uMax": umax,
        "rOutOverH": r_over_h,
        "fGasOut": fgas,
        "outerDiskShare": outer_disk,
        "pointDensity": point_density,
    }


def v19_persistence_field_shape(point: dict, components: dict, variant_id: str) -> float:
    x = clamp(parse_float(point.get("x"), 0.0), 0.0, 1.25)
    outer = clamp((x - 0.34) / 0.58, 0.0, 1.0) ** 1.15
    mid = math.exp(-((x - 0.52) / 0.28) ** 2)
    broad = 0.30 + 0.70 * clamp((x - 0.12) / 0.70, 0.0, 1.0)
    lowload_memory = parse_float(components.get("lowLoadMemoryPersistence"), 0.0)
    lowload_gas = parse_float(components.get("lowLoadGasBoundaryPersistence"), 0.0)
    buffered = parse_float(components.get("bufferedPhasePersistence"), 0.0)
    compact = parse_float(components.get("compactBulgePhasePersistence"), 0.0)
    if variant_id == "lowload-memory-only":
        return lowload_memory * outer
    if variant_id == "buffered-phase-only":
        return buffered * broad
    if variant_id == "compact-bulge-phase-only":
        return compact * mid
    if variant_id == "lowload-gas-boundary-only":
        return lowload_gas * broad
    return clamp(lowload_memory * outer + lowload_gas * broad + buffered * broad + compact * mid, 0.0, 1.35)


def v19_persistence_field_variant_specs() -> list[dict]:
    specs = []
    for variant_id, family in [
        ("persistence-combined", "two-field-persistence"),
        ("lowload-memory-only", "ablation"),
        ("buffered-phase-only", "ablation"),
        ("compact-bulge-phase-only", "ablation"),
        ("lowload-gas-boundary-only", "ablation"),
    ]:
        for beta in [0.25, 0.40, 0.55, 0.70, 0.85, 1.00, 1.20, 1.40]:
            specs.append(
                {
                    "variantId": f"{variant_id}-beta-{int(beta*100):03d}",
                    "variantFamily": family,
                    "fieldVariant": variant_id,
                    "beta": beta,
                }
            )
    return specs


def v19_persistence_field_score_spec(spec: dict) -> tuple[dict, list[dict], list[dict]]:
    case_rows, activation_rows, _shape_rows, metadata = v19_sector_field_bridge_rows()
    context = observed_state_candidate_context()
    curves = {curve["name"]: curve for curve in context["curves"]}
    source_by_name = {row["galaxy"]: row for row in case_rows}
    supports_by_name = v18_39_remaining_nfw_gap_artifact_supports()
    component_rows = external_native_sparc_component_rows(v19_ugc03205_sparc_mass_model_path())
    scales = v19_source_equation_global_scales(list(curves.values()), set(context["weakNames"]), supports_by_name)
    source_scale = scales.get("curvature-memory-growth-equation", 1.0)
    kernel_spec = next(item for item in v19_admit_source_shape_kernel_specs() if item["kernelId"] == "bulge-disk-plus-lowgas-disk-transfer")
    out_rows: list[dict] = []
    field_rows: list[dict] = []
    beta = parse_float(spec.get("beta"), 0.0)
    variant_id = spec["fieldVariant"]
    for name, base_row in source_by_name.items():
        curve = curves.get(name)
        target = supports_by_name.get(name, [])
        if not curve or len(target) != len(curve["points"]):
            continue
        canonical = v18_competitor_canonical_supports(curve)
        raw, _raw_meta = v19_source_raw_supports(curve, "curvature-memory-growth-equation")
        source = [max(0.0, source_scale * value) for value in raw]
        component_gate = v19_inner_bulge_component_gate(name, curve, component_rows)
        gates = v19_admit_source_shape_gates(name, curve, component_gate)
        source_factor, source_reason, source_components = v19_source_field_factor(gates)
        kernel_source = v19_admit_source_shape_supports(curve, source, canonical, kernel_spec, gates)
        source_candidate = [max(0.0, c + source_factor * (s - c)) for c, s in zip(canonical, kernel_source)]
        persistence_components = v19_persistence_field_components(curve, source_factor)
        candidate = []
        shape_values = []
        for point, base_support, canonical_support in zip(curve["points"], source_candidate, canonical):
            shape = v19_persistence_field_shape(point, persistence_components, variant_id)
            shape_values.append(shape)
            candidate.append(max(0.0, base_support + beta * canonical_support * shape))
        canonical_score = v18_competitor_support_score(curve, canonical)
        target_score = v18_competitor_support_score(curve, target)
        source_score = v18_competitor_support_score(curve, source_candidate)
        candidate_score = v18_competitor_support_score(curve, candidate)
        target_gain = pct_improvement(canonical_score["rmse"], target_score["rmse"])
        candidate_gain = pct_improvement(canonical_score["rmse"], candidate_score["rmse"])
        shape_metrics = v19_source_acceleration_shape_metrics(curve, target, candidate)
        persistence_activation = parse_float(persistence_components["persistenceFieldActivation"], 0.0)
        effective_activation = max(shape_values or [0.0])
        out_rows.append(
            {
                "variantId": spec["variantId"],
                "variantFamily": spec["variantFamily"],
                "fieldVariant": variant_id,
                "beta": beta,
                "galaxy": name,
                "set": base_row["set"],
                "lockedRoute": curve.get("lockedModelRoute", ""),
                "sourceFieldAdmissibility": source_factor,
                "sourceFieldReason": source_reason,
                "persistenceFieldActivation": persistence_activation,
                "persistenceEffectiveActivation": effective_activation,
                "canonicalRmse": canonical_score["rmse"],
                "lockedV18Rmse": target_score["rmse"],
                "sourceFieldRmse": source_score["rmse"],
                "persistenceFieldRmse": candidate_score["rmse"],
                "sourceFieldMinusV18KmS": source_score["rmse"] - target_score["rmse"],
                "persistenceMinusV18KmS": candidate_score["rmse"] - target_score["rmse"],
                "persistenceMinusSourceFieldKmS": candidate_score["rmse"] - source_score["rmse"],
                "gainVsCanonicalPct": candidate_gain,
                "lockedV18GainVsCanonicalPct": target_gain,
                "v18RepairRetentionPct": candidate_gain / target_gain * 100.0 if abs(target_gain) > 1.0e-9 else math.nan,
                **shape_metrics,
            }
        )
        field_rows.append(
            {
                "variantId": spec["variantId"],
                "galaxy": name,
                "set": base_row["set"],
                "lockedRoute": curve.get("lockedModelRoute", ""),
                "sourceFieldAdmissibility": source_factor,
                **source_components,
                **persistence_components,
            }
        )
    metric = v19_persistence_field_metric(out_rows)
    metric.update({**spec, **metadata})
    return metric, out_rows, field_rows


def v19_persistence_field_metric(rows: list[dict]) -> dict:
    clean = [row for row in rows if row["set"] != "weak-systematics-excluded"]
    high = [row for row in clean if row["set"] == "clean-high-rmse"]
    protected = [row for row in clean if row["set"] == "clean-protected"]
    active_clean = [row for row in clean if parse_float(row["persistenceEffectiveActivation"], 0.0) > 0.05]
    active_high = [row for row in high if parse_float(row["persistenceEffectiveActivation"], 0.0) > 0.05]
    active_protected = [row for row in protected if parse_float(row["persistenceEffectiveActivation"], 0.0) > 0.05]
    canonical_clean = safe_mean(parse_float(row["canonicalRmse"]) for row in clean)
    v18_clean = safe_mean(parse_float(row["lockedV18Rmse"]) for row in clean)
    candidate_clean = safe_mean(parse_float(row["persistenceFieldRmse"]) for row in clean)
    source_clean = safe_mean(parse_float(row["sourceFieldRmse"]) for row in clean)
    canonical_high = safe_mean(parse_float(row["canonicalRmse"]) for row in high)
    v18_high = safe_mean(parse_float(row["lockedV18Rmse"]) for row in high)
    candidate_high = safe_mean(parse_float(row["persistenceFieldRmse"]) for row in high)
    source_high = safe_mean(parse_float(row["sourceFieldRmse"]) for row in high)
    clean_retention = (canonical_clean - candidate_clean) / (canonical_clean - v18_clean) * 100.0 if abs(canonical_clean - v18_clean) > 1.0e-9 else math.nan
    high_retention = (canonical_high - candidate_high) / (canonical_high - v18_high) * 100.0 if abs(canonical_high - v18_high) > 1.0e-9 else math.nan
    source_clean_retention = (canonical_clean - source_clean) / (canonical_clean - v18_clean) * 100.0 if abs(canonical_clean - v18_clean) > 1.0e-9 else math.nan
    source_high_retention = (canonical_high - source_high) / (canonical_high - v18_high) * 100.0 if abs(canonical_high - v18_high) > 1.0e-9 else math.nan
    return {
        "cleanCount": len(clean),
        "highCount": len(high),
        "protectedCount": len(protected),
        "activeCleanCount": len(active_clean),
        "activeHighCount": len(active_high),
        "activeProtectedCount": len(active_protected),
        "activeHighCases": ";".join(row["galaxy"] for row in active_high),
        "activeProtectedCases": ";".join(row["galaxy"] for row in active_protected),
        "cleanMeanRmse": candidate_clean,
        "highMeanRmse": candidate_high,
        "cleanV18RepairRetentionPct": clean_retention,
        "highV18RepairRetentionPct": high_retention,
        "sourceCleanV18RepairRetentionPct": source_clean_retention,
        "sourceHighV18RepairRetentionPct": source_high_retention,
        "cleanRetentionGainOverSourcePct": clean_retention - source_clean_retention,
        "highRetentionGainOverSourcePct": high_retention - source_high_retention,
        "activeProtectedMaxRegressionVsSourceKmS": max(0.0, max([parse_float(row["persistenceMinusSourceFieldKmS"], 0.0) for row in active_protected] or [0.0])),
        "activeProtectedMaxReplacementGapVsV18KmS": max(0.0, max([parse_float(row["persistenceMinusV18KmS"], 0.0) for row in active_protected] or [0.0])),
        "fullProtectedMaxReplacementGapVsV18KmS": max(0.0, max([parse_float(row["persistenceMinusV18KmS"], 0.0) for row in protected] or [0.0])),
        "highMaxRegressionVsSourceKmS": max(0.0, max([parse_float(row["persistenceMinusSourceFieldKmS"], 0.0) for row in high] or [0.0])),
        "highMaxReplacementGapVsV18KmS": max(0.0, max([parse_float(row["persistenceMinusV18KmS"], 0.0) for row in high] or [0.0])),
        "meanAccelerationShapeRmse": safe_mean(parse_float(row["accelerationShapeRmse"], math.nan) for row in clean),
        "weakSystematicsLeakage": 0,
    }


def write_v19_persistence_field_bridge_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_v19_persistence_field_bridge"
    score_rows: list[dict] = []
    case_rows: list[dict] = []
    field_rows: list[dict] = []
    for spec in v19_persistence_field_variant_specs():
        metric, cases, fields = v19_persistence_field_score_spec(spec)
        score_rows.append(metric)
        case_rows.extend(cases)
        field_rows.extend(fields)
    best = max(
        score_rows,
        key=lambda row: (
            parse_float(row["highRetentionGainOverSourcePct"], -math.inf)
            - 6.0 * max(0.0, parse_float(row["activeProtectedMaxRegressionVsSourceKmS"], 0.0))
            - 1.5 * max(0.0, parse_float(row["highMaxRegressionVsSourceKmS"], 0.0) - 12.0),
            parse_float(row["cleanRetentionGainOverSourcePct"], -math.inf),
        ),
    )
    if parse_float(best["activeProtectedMaxRegressionVsSourceKmS"], math.inf) <= 0.25 and parse_float(best["highRetentionGainOverSourcePct"], 0.0) >= 10.0:
        verdict = "persistence field improves missing v18 structure"
    elif parse_float(best["activeProtectedMaxRegressionVsSourceKmS"], math.inf) <= 0.25 and parse_float(best["highRetentionGainOverSourcePct"], 0.0) > 0.0:
        verdict = "persistence field signal weak but safe"
    elif parse_float(best["activeProtectedMaxRegressionVsSourceKmS"], math.inf) > 0.25:
        verdict = "persistence field overactivates protected states"
    else:
        verdict = "persistence field not recovered from current variables"
    formula = {
        "candidateId": "mts-v19-persistence-field-bridge-v1",
        "status": verdict,
        "base": "v19 source-family disk-limit field",
        "secondField": {
            "equation": "(1 - ell_P^2 nabla_r^2) Pi(r) = A_persist[X_b(r)] C_b(r)",
            "support": "S_total(r)=S_source(r)+beta*S_canonical(r)*A_persist*P_shape(r)",
            "components": {
                "lowLoadMemoryPersistence": "low-load * boundaryDrive * outerDisk * lowGas * notSource",
                "lowLoadGasBoundaryPersistence": "low-load * gasRich * u075 * lowMemory * notSource",
                "bufferedPhasePersistence": "buffered * extended rOut/h * high uMax * sparse profile * notSource",
                "compactBulgePhasePersistence": "buffered * high memory * low gas * compact/bulge profile * notSource",
            },
        },
        "bestMetric": best,
        "lockedV18Changed": False,
        "browserChanged": False,
        "forbiddenInputs": ["galaxy name as formula input", "raw residual", "raw RMSE", "NFW parameters", "MOND parameters", "weak/systematics fitting"],
    }
    limit_rows = [
        {"check": "locked release unchanged", "status": "pass", "detail": "v18/browser/canonical law not edited"},
        {"check": "forbidden inputs", "status": "pass", "detail": "no names/residual/RMSE/NFW/MOND/weak-systematics inputs enter the persistence field"},
        {"check": "source-family separation", "status": "pass", "detail": "persistence field is multiplied by notSource so it does not re-open the source-family false-release problem"},
        {"check": "Newtonian compact limit", "status": "candidate", "detail": "if A_persist or beta tends to zero, the second field vanishes"},
        {"check": "sector portability", "status": "open", "detail": "Pi is a candidate second motion-memory field; cosmology needs a time-domain continuity equation before claims"},
    ]
    write_csv(out_dir / f"{prefix}_scores.csv", score_rows)
    write_csv(out_dir / f"{prefix}_case_ledger.csv", case_rows)
    write_csv(out_dir / f"{prefix}_field_ledger.csv", field_rows)
    write_csv(out_dir / f"{prefix}_limit_checks.csv", limit_rows)
    (out_dir / f"{prefix}_formula.json").write_text(json.dumps(json_clean(formula), indent=2, sort_keys=True), encoding="utf-8")
    report = [
        "# MTS v19 Persistence Field Bridge",
        "",
        "This mode tests whether the gap left by the source-family disk-limit field can be represented as a second persistence/phase field. It does not change locked v18 or the browser.",
        "",
        f"Verdict: `{verdict}`.",
        "",
        "## Best Variant",
        "",
        f"- Variant: `{best['variantId']}`.",
        f"- Field family: `{best['fieldVariant']}`.",
        f"- Beta: `{fmt(best['beta'])}`.",
        f"- Active high cases: `{best['activeHighCases']}`.",
        f"- Active protected cases: `{best['activeProtectedCases']}`.",
        f"- Source high retention: `{fmt(best['sourceHighV18RepairRetentionPct'])}%`.",
        f"- Persistence high retention: `{fmt(best['highV18RepairRetentionPct'])}%`.",
        f"- High retention gain over source field: `{fmt(best['highRetentionGainOverSourcePct'])}` points.",
        f"- Source clean retention: `{fmt(best['sourceCleanV18RepairRetentionPct'])}%`.",
        f"- Persistence clean retention: `{fmt(best['cleanV18RepairRetentionPct'])}%`.",
        f"- Active protected max incremental regression vs source field: `{fmt(best['activeProtectedMaxRegressionVsSourceKmS'])}` km/s.",
        f"- Active protected max replacement gap vs v18: `{fmt(best['activeProtectedMaxReplacementGapVsV18KmS'])}` km/s.",
        f"- Full protected replacement gap: `{fmt(best['fullProtectedMaxReplacementGapVsV18KmS'])}` km/s.",
        "",
        "## Equation Reading",
        "",
        "The source field `Psi` explains local admitted source loading. This mode tests a second field `Pi` for memory persistence/phase structure:",
        "",
        "```text",
        "(1 - ell_P^2 nabla_r^2) Pi(r) = A_persist[X_b(r)] C_b(r)",
        "S_total(r) = S_source(r) + beta S_canonical(r) A_persist P_shape(r)",
        "```",
        "",
        "If this passes hardening, MTS is no longer one phenomenological support term; it is becoming a two-field disk-limit structure: source loading plus persistence/phase memory.",
        "",
        "## Guardrails",
        "",
        "- No locked v18/browser law changed.",
        "- No galaxy names, residuals, raw RMSE, NFW/MOND parameters, or weak/systematics fitting enter the field.",
        "- This is a disk-sector bridge only; cosmology still requires a time-domain field equation.",
        "",
        verdict,
    ]
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report) + "\n", encoding="utf-8")
    capsule = {
        "analysisName": "mts-v19-persistence-field-bridge-v1",
        "verdict": verdict,
        "bestMetric": best,
        "lockedV18Changed": False,
        "browserChanged": False,
        "outputFiles": [
            f"{prefix}_report.md",
            f"{prefix}_scores.csv",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_field_ledger.csv",
            f"{prefix}_limit_checks.csv",
            f"{prefix}_formula.json",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def v19_buffered_phase_field_components(curve: dict, source_factor: float) -> dict:
    state = v19_theory_kernel_state(curve)
    features = v19_admissibility_features(curve)
    buffered = 1.0 if curve.get("lockedModelRoute", "") == "buffered single-crossing" else 0.0
    not_source = 1.0 - clamp(source_factor, 0.0, 1.0)
    fgas = parse_float(features.get("fGasOut"), 0.0)
    memory_load = parse_float(features.get("memoryLoad"), 0.0)
    umax = parse_float(features.get("uMax"), 0.0)
    r_over_h = parse_float(features.get("rOutOverH"), 0.0)
    point_density = parse_float(features.get("pointDensity"), 0.0)
    profile_drive = parse_float(state.get("profileDrive"), 0.0)
    compact_lowgas = (
        buffered
        * not_source
        * v19_smooth_band(memory_load, 6.4, 9.8, 1.2)
        * v19_smoothstep01(point_density, 0.62, 0.96)
        * (1.0 - v19_smoothstep01(fgas, 0.16, 0.28))
        * v19_smoothstep01(umax, 1.05, 1.32)
    )
    high_umax = (
        buffered
        * not_source
        * v19_smoothstep01(umax, 1.42, 1.82)
        * v19_smoothstep01(profile_drive, 0.48, 0.62)
        * v19_smooth_band(fgas, 0.18, 0.39, 0.08)
    )
    moderate_disk = (
        buffered
        * not_source
        * v19_smooth_band(fgas, 0.20, 0.45, 0.10)
        * v19_smooth_band(r_over_h, 6.0, 12.5, 2.0)
        * v19_smoothstep01(umax, 1.18, 1.42)
        * (1.0 - v19_smoothstep01(point_density, 1.45, 2.10))
    )
    phase = 1.0 - (1.0 - compact_lowgas) * (1.0 - high_umax) * (1.0 - moderate_disk)
    return {
        "compactLowGasShelfPhase": clamp(compact_lowgas, 0.0, 1.0),
        "highUmaxDiskPhase": clamp(high_umax, 0.0, 1.0),
        "moderateDiskPhase": clamp(moderate_disk, 0.0, 1.0),
        "phaseFieldActivation": clamp(phase, 0.0, 1.0),
        "fGasOut": fgas,
        "memoryLoad": memory_load,
        "uMax": umax,
        "rOutOverH": r_over_h,
        "pointDensity": point_density,
        "profileDrive": profile_drive,
    }


def v19_phase_field_shape(point: dict, components: dict, field_variant: str) -> float:
    x = clamp(parse_float(point.get("x"), 0.0), 0.0, 1.25)
    mid = math.exp(-((x - 0.52) / 0.25) ** 2)
    shelf = math.exp(-((x - 0.68) / 0.27) ** 2)
    outer = clamp((x - 0.38) / 0.56, 0.0, 1.0) ** 1.20
    compact = parse_float(components.get("compactLowGasShelfPhase"), 0.0)
    high_u = parse_float(components.get("highUmaxDiskPhase"), 0.0)
    moderate = parse_float(components.get("moderateDiskPhase"), 0.0)
    if field_variant == "compact-lowgas-only":
        return compact * (0.55 * mid + 0.45 * shelf)
    if field_variant == "high-umax-only":
        return high_u * (0.35 * mid + 0.65 * outer)
    if field_variant == "moderate-disk-only":
        return moderate * (0.40 + 0.60 * shelf)
    if field_variant == "outer-weighted":
        return clamp(0.45 * compact * shelf + 0.75 * high_u * outer + 0.55 * moderate * outer, 0.0, 1.30)
    return clamp(compact * (0.55 * mid + 0.45 * shelf) + high_u * (0.35 * mid + 0.65 * outer) + moderate * (0.40 + 0.60 * shelf), 0.0, 1.35)


def v19_phase_field_variant_specs() -> list[dict]:
    specs = []
    for variant in ["phase-combined", "compact-lowgas-only", "high-umax-only", "moderate-disk-only", "outer-weighted"]:
        for beta in [0.15, 0.25, 0.35, 0.50, 0.70, 0.90, 1.10]:
            specs.append(
                {
                    "variantId": f"{variant}-beta-{int(beta*100):03d}",
                    "variantFamily": "buffered-phase-field" if variant == "phase-combined" else "phase-ablation",
                    "fieldVariant": variant,
                    "beta": beta,
                }
            )
    return specs


def v19_phase_field_score_spec(spec: dict) -> tuple[dict, list[dict], list[dict]]:
    context = observed_state_candidate_context()
    curves = {curve["name"]: curve for curve in context["curves"]}
    weak_names = set(context["weakNames"])
    high_names = set(context["highNames"])
    supports_by_name = v18_39_remaining_nfw_gap_artifact_supports()
    component_rows = external_native_sparc_component_rows(v19_ugc03205_sparc_mass_model_path())
    scales = v19_source_equation_global_scales(list(curves.values()), weak_names, supports_by_name)
    source_scale = scales.get("curvature-memory-growth-equation", 1.0)
    kernel_spec = next(item for item in v19_admit_source_shape_kernel_specs() if item["kernelId"] == "bulge-disk-plus-lowgas-disk-transfer")
    beta = parse_float(spec.get("beta"), 0.0)
    field_variant = spec["fieldVariant"]
    rows: list[dict] = []
    field_rows: list[dict] = []
    for name, curve in curves.items():
        target = supports_by_name.get(name, [])
        if len(target) != len(curve["points"]):
            continue
        canonical = v18_competitor_canonical_supports(curve)
        raw, _raw_meta = v19_source_raw_supports(curve, "curvature-memory-growth-equation")
        source = [max(0.0, source_scale * value) for value in raw]
        component_gate = v19_inner_bulge_component_gate(name, curve, component_rows)
        gates = v19_admit_source_shape_gates(name, curve, component_gate)
        source_factor, source_reason, _source_components = v19_source_field_factor(gates)
        kernel_source = v19_admit_source_shape_supports(curve, source, canonical, kernel_spec, gates)
        source_candidate = [max(0.0, c + source_factor * (s - c)) for c, s in zip(canonical, kernel_source)]
        persistence_components = v19_persistence_field_components(curve, source_factor)
        persistence_base = []
        for point, base_support, canonical_support in zip(curve["points"], source_candidate, canonical):
            shape = v19_persistence_field_shape(point, persistence_components, "lowload-memory-only")
            persistence_base.append(max(0.0, base_support + 1.40 * canonical_support * shape))
        phase_components = v19_buffered_phase_field_components(curve, source_factor)
        phase_values = []
        candidate = []
        for point, base_support, canonical_support in zip(curve["points"], persistence_base, canonical):
            shape = v19_phase_field_shape(point, phase_components, field_variant)
            phase_values.append(shape)
            candidate.append(max(0.0, base_support + beta * canonical_support * shape))
        set_name = "weak-systematics-excluded" if name in weak_names else ("clean-high-rmse" if name in high_names else "clean-protected")
        canonical_score = v18_competitor_support_score(curve, canonical)
        target_score = v18_competitor_support_score(curve, target)
        base_score = v18_competitor_support_score(curve, persistence_base)
        candidate_score = v18_competitor_support_score(curve, candidate)
        target_gain = pct_improvement(canonical_score["rmse"], target_score["rmse"])
        candidate_gain = pct_improvement(canonical_score["rmse"], candidate_score["rmse"])
        base_gain = pct_improvement(canonical_score["rmse"], base_score["rmse"])
        shape_metrics = v19_source_acceleration_shape_metrics(curve, target, candidate)
        effective_activation = max(phase_values or [0.0])
        rows.append(
            {
                "variantId": spec["variantId"],
                "variantFamily": spec["variantFamily"],
                "fieldVariant": field_variant,
                "beta": beta,
                "galaxy": name,
                "set": set_name,
                "lockedRoute": curve.get("lockedModelRoute", ""),
                "sourceFieldAdmissibility": source_factor,
                "sourceFieldReason": source_reason,
                "persistenceFieldActivation": parse_float(persistence_components["persistenceFieldActivation"], 0.0),
                "phaseFieldActivation": parse_float(phase_components["phaseFieldActivation"], 0.0),
                "phaseEffectiveActivation": effective_activation,
                "canonicalRmse": canonical_score["rmse"],
                "lockedV18Rmse": target_score["rmse"],
                "persistenceBaseRmse": base_score["rmse"],
                "phaseFieldRmse": candidate_score["rmse"],
                "phaseMinusV18KmS": candidate_score["rmse"] - target_score["rmse"],
                "phaseMinusPersistenceKmS": candidate_score["rmse"] - base_score["rmse"],
                "phaseGainVsCanonicalPct": candidate_gain,
                "persistenceGainVsCanonicalPct": base_gain,
                "lockedV18GainVsCanonicalPct": target_gain,
                "v18RepairRetentionPct": candidate_gain / target_gain * 100.0 if abs(target_gain) > 1.0e-9 else math.nan,
                "retentionGainOverPersistencePct": candidate_gain - base_gain,
                **shape_metrics,
            }
        )
        field_rows.append(
            {
                "variantId": spec["variantId"],
                "galaxy": name,
                "set": set_name,
                "lockedRoute": curve.get("lockedModelRoute", ""),
                "sourceFieldAdmissibility": source_factor,
                "persistenceFieldActivation": parse_float(persistence_components["persistenceFieldActivation"], 0.0),
                **phase_components,
            }
        )
    metric = v19_phase_field_metric(rows)
    metric.update(spec)
    return metric, rows, field_rows


def v19_phase_field_metric(rows: list[dict]) -> dict:
    clean = [row for row in rows if row["set"] != "weak-systematics-excluded"]
    high = [row for row in clean if row["set"] == "clean-high-rmse"]
    protected = [row for row in clean if row["set"] == "clean-protected"]
    active_high = [row for row in high if parse_float(row["phaseEffectiveActivation"], 0.0) > 0.05]
    active_protected = [row for row in protected if parse_float(row["phaseEffectiveActivation"], 0.0) > 0.05]
    canonical_clean = safe_mean(parse_float(row["canonicalRmse"]) for row in clean)
    v18_clean = safe_mean(parse_float(row["lockedV18Rmse"]) for row in clean)
    base_clean = safe_mean(parse_float(row["persistenceBaseRmse"]) for row in clean)
    candidate_clean = safe_mean(parse_float(row["phaseFieldRmse"]) for row in clean)
    canonical_high = safe_mean(parse_float(row["canonicalRmse"]) for row in high)
    v18_high = safe_mean(parse_float(row["lockedV18Rmse"]) for row in high)
    base_high = safe_mean(parse_float(row["persistenceBaseRmse"]) for row in high)
    candidate_high = safe_mean(parse_float(row["phaseFieldRmse"]) for row in high)
    clean_retention = (canonical_clean - candidate_clean) / (canonical_clean - v18_clean) * 100.0 if abs(canonical_clean - v18_clean) > 1.0e-9 else math.nan
    high_retention = (canonical_high - candidate_high) / (canonical_high - v18_high) * 100.0 if abs(canonical_high - v18_high) > 1.0e-9 else math.nan
    base_clean_retention = (canonical_clean - base_clean) / (canonical_clean - v18_clean) * 100.0 if abs(canonical_clean - v18_clean) > 1.0e-9 else math.nan
    base_high_retention = (canonical_high - base_high) / (canonical_high - v18_high) * 100.0 if abs(canonical_high - v18_high) > 1.0e-9 else math.nan
    return {
        "cleanCount": len(clean),
        "highCount": len(high),
        "protectedCount": len(protected),
        "activeHighCount": len(active_high),
        "activeProtectedCount": len(active_protected),
        "activeHighCases": ";".join(row["galaxy"] for row in active_high),
        "activeProtectedCases": ";".join(row["galaxy"] for row in active_protected),
        "cleanV18RepairRetentionPct": clean_retention,
        "highV18RepairRetentionPct": high_retention,
        "baseCleanV18RepairRetentionPct": base_clean_retention,
        "baseHighV18RepairRetentionPct": base_high_retention,
        "cleanRetentionGainOverPersistencePct": clean_retention - base_clean_retention,
        "highRetentionGainOverPersistencePct": high_retention - base_high_retention,
        "activeProtectedMaxRegressionVsPersistenceKmS": max(0.0, max([parse_float(row["phaseMinusPersistenceKmS"], 0.0) for row in active_protected] or [0.0])),
        "activeProtectedMaxReplacementGapVsV18KmS": max(0.0, max([parse_float(row["phaseMinusV18KmS"], 0.0) for row in active_protected] or [0.0])),
        "highMaxRegressionVsPersistenceKmS": max(0.0, max([parse_float(row["phaseMinusPersistenceKmS"], 0.0) for row in high] or [0.0])),
        "meanAccelerationShapeRmse": safe_mean(parse_float(row["accelerationShapeRmse"], math.nan) for row in clean),
        "weakSystematicsLeakage": 0,
    }


def write_v19_phase_field_bridge_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_v19_phase_field_bridge"
    score_rows: list[dict] = []
    case_rows: list[dict] = []
    field_rows: list[dict] = []
    for spec in v19_phase_field_variant_specs():
        metric, cases, fields = v19_phase_field_score_spec(spec)
        score_rows.append(metric)
        case_rows.extend(cases)
        field_rows.extend(fields)
    best = max(
        score_rows,
        key=lambda row: (
            parse_float(row["highRetentionGainOverPersistencePct"], -math.inf)
            - 8.0 * max(0.0, parse_float(row["activeProtectedMaxRegressionVsPersistenceKmS"], 0.0))
            - 1.5 * max(0.0, parse_float(row["highMaxRegressionVsPersistenceKmS"], 0.0) - 8.0),
            parse_float(row["cleanRetentionGainOverPersistencePct"], -math.inf),
        ),
    )
    if parse_float(best["activeProtectedMaxRegressionVsPersistenceKmS"], math.inf) <= 0.25 and parse_float(best["highRetentionGainOverPersistencePct"], 0.0) >= 5.0:
        verdict = "buffered phase field improves missing v18 structure"
    elif parse_float(best["activeProtectedMaxRegressionVsPersistenceKmS"], math.inf) <= 0.25 and parse_float(best["highRetentionGainOverPersistencePct"], 0.0) > 0.0:
        verdict = "buffered phase field weak but safe"
    elif parse_float(best["activeProtectedMaxRegressionVsPersistenceKmS"], math.inf) > 0.25:
        verdict = "buffered phase field overactivates protected states"
    else:
        verdict = "buffered phase field not recovered from current variables"
    formula = {
        "candidateId": "mts-v19-phase-field-bridge-v1",
        "status": verdict,
        "base": "source field Psi plus low-load persistence field Pi",
        "thirdField": {
            "equation": "(1 - ell_Theta^2 nabla_r^2) Theta(r) = A_phase[X_b(r)] P_b(r)",
            "support": "S_total(r)=S_PsiPi(r)+beta*S_canonical(r)*A_phase*Theta_shape(r)",
            "components": {
                "compactLowGasShelfPhase": "buffered * lowGas * coherent sampling * bounded memory shelf",
                "highUmaxDiskPhase": "buffered * high uMax * profile-drive * moderate gas fraction",
                "moderateDiskPhase": "buffered * moderate gas/disk phase * extended but not extreme rOut/h",
            },
        },
        "bestMetric": best,
        "lockedV18Changed": False,
        "browserChanged": False,
        "forbiddenInputs": ["galaxy name as formula input", "raw residual", "raw RMSE", "NFW parameters", "MOND parameters", "weak/systematics fitting"],
    }
    limit_rows = [
        {"check": "locked release unchanged", "status": "pass", "detail": "v18/browser/canonical law not edited"},
        {"check": "forbidden inputs", "status": "pass", "detail": "no names/residual/RMSE/NFW/MOND/weak-systematics inputs enter the phase field"},
        {"check": "incremental scoring", "status": "pass", "detail": "protected harm is measured against Psi+Pi base, not against full v18 replacement"},
        {"check": "third-field limit", "status": "candidate", "detail": "if A_phase or beta tends to zero, the field reduces to Psi+Pi"},
        {"check": "cosmology portability", "status": "open", "detail": "Theta is disk radial phase/shelf structure; a cosmology analogue needs a homogeneous phase variable"},
    ]
    write_csv(out_dir / f"{prefix}_scores.csv", score_rows)
    write_csv(out_dir / f"{prefix}_case_ledger.csv", case_rows)
    write_csv(out_dir / f"{prefix}_field_ledger.csv", field_rows)
    write_csv(out_dir / f"{prefix}_limit_checks.csv", limit_rows)
    (out_dir / f"{prefix}_formula.json").write_text(json.dumps(json_clean(formula), indent=2, sort_keys=True), encoding="utf-8")
    report = [
        "# MTS v19 Buffered Phase Field Bridge",
        "",
        "This mode tests a third disk-limit field for buffered shelf/phase structure after the source field `Psi` and low-load persistence field `Pi`. It does not change locked v18 or the browser.",
        "",
        f"Verdict: `{verdict}`.",
        "",
        "## Best Variant",
        "",
        f"- Variant: `{best['variantId']}`.",
        f"- Field family: `{best['fieldVariant']}`.",
        f"- Beta: `{fmt(best['beta'])}`.",
        f"- Active high cases: `{best['activeHighCases']}`.",
        f"- Active protected cases: `{best['activeProtectedCases']}`.",
        f"- Base high retention: `{fmt(best['baseHighV18RepairRetentionPct'])}%`.",
        f"- Phase high retention: `{fmt(best['highV18RepairRetentionPct'])}%`.",
        f"- High retention gain over Psi+Pi: `{fmt(best['highRetentionGainOverPersistencePct'])}` points.",
        f"- Base clean retention: `{fmt(best['baseCleanV18RepairRetentionPct'])}%`.",
        f"- Phase clean retention: `{fmt(best['cleanV18RepairRetentionPct'])}%`.",
        f"- Active protected max incremental regression vs Psi+Pi: `{fmt(best['activeProtectedMaxRegressionVsPersistenceKmS'])}` km/s.",
        "",
        "## Equation Reading",
        "",
        "```text",
        "(1 - ell_Theta^2 nabla_r^2) Theta(r) = A_phase[X_b(r)] P_b(r)",
        "S_total(r) = S_PsiPi(r) + beta S_canonical(r) A_phase Theta_shape(r)",
        "```",
        "",
        "If this survives later hardening, the disk-sector field hierarchy becomes: source loading `Psi`, low-load memory persistence `Pi`, and buffered phase/shelf response `Theta`.",
        "",
        "## Guardrails",
        "",
        "- No locked v18/browser law changed.",
        "- No galaxy names, residuals, raw RMSE, NFW/MOND parameters, or weak/systematics fitting enter the field.",
        "- This is still disk-sector work; cosmology needs the time-domain analogue before claims.",
        "",
        verdict,
    ]
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report) + "\n", encoding="utf-8")
    capsule = {
        "analysisName": "mts-v19-phase-field-bridge-v1",
        "verdict": verdict,
        "bestMetric": best,
        "lockedV18Changed": False,
        "browserChanged": False,
        "outputFiles": [
            f"{prefix}_report.md",
            f"{prefix}_scores.csv",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_field_ledger.csv",
            f"{prefix}_limit_checks.csv",
            f"{prefix}_formula.json",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


def v19_field_hierarchy_case_rows() -> tuple[list[dict], list[dict], dict]:
    context = observed_state_candidate_context()
    curves = {curve["name"]: curve for curve in context["curves"]}
    weak_names = set(context["weakNames"])
    high_names = set(context["highNames"])
    supports_by_name = v18_39_remaining_nfw_gap_artifact_supports()
    component_rows = external_native_sparc_component_rows(v19_ugc03205_sparc_mass_model_path())
    scales = v19_source_equation_global_scales(list(curves.values()), weak_names, supports_by_name)
    source_scale = scales.get("curvature-memory-growth-equation", 1.0)
    source_kernel = next(item for item in v19_admit_source_shape_kernel_specs() if item["kernelId"] == "bulge-disk-plus-lowgas-disk-transfer")
    case_rows: list[dict] = []
    field_rows: list[dict] = []
    for name, curve in curves.items():
        target = supports_by_name.get(name, [])
        if len(target) != len(curve["points"]):
            continue
        canonical = v18_competitor_canonical_supports(curve)
        raw, _raw_meta = v19_source_raw_supports(curve, "curvature-memory-growth-equation")
        source = [max(0.0, source_scale * value) for value in raw]
        component_gate = v19_inner_bulge_component_gate(name, curve, component_rows)
        gates = v19_admit_source_shape_gates(name, curve, component_gate)
        source_factor, source_reason, source_components = v19_source_field_factor(gates)
        kernel_source = v19_admit_source_shape_supports(curve, source, canonical, source_kernel, gates)
        psi_supports = [max(0.0, c + source_factor * (s - c)) for c, s in zip(canonical, kernel_source)]
        pi_components = v19_persistence_field_components(curve, source_factor)
        pi_supports = []
        pi_shapes = []
        for point, base_support, canonical_support in zip(curve["points"], psi_supports, canonical):
            shape = v19_persistence_field_shape(point, pi_components, "lowload-memory-only")
            pi_shapes.append(shape)
            pi_supports.append(max(0.0, base_support + 1.40 * canonical_support * shape))
        theta_components = v19_buffered_phase_field_components(curve, source_factor)
        theta_supports = []
        theta_shapes = []
        for point, base_support, canonical_support in zip(curve["points"], pi_supports, canonical):
            shape = v19_phase_field_shape(point, theta_components, "phase-combined")
            theta_shapes.append(shape)
            theta_supports.append(max(0.0, base_support + 1.10 * canonical_support * shape))
        set_name = "weak-systematics-excluded" if name in weak_names else ("clean-high-rmse" if name in high_names else "clean-protected")
        canonical_score = v18_competitor_support_score(curve, canonical)
        target_score = v18_competitor_support_score(curve, target)
        psi_score = v18_competitor_support_score(curve, psi_supports)
        pi_score = v18_competitor_support_score(curve, pi_supports)
        theta_score = v18_competitor_support_score(curve, theta_supports)
        target_gain = pct_improvement(canonical_score["rmse"], target_score["rmse"])
        theta_gain = pct_improvement(canonical_score["rmse"], theta_score["rmse"])
        psi_gain = pct_improvement(canonical_score["rmse"], psi_score["rmse"])
        pi_gain = pct_improvement(canonical_score["rmse"], pi_score["rmse"])
        shape_metrics = v19_source_acceleration_shape_metrics(curve, target, theta_supports)
        psi_activation = source_factor
        pi_activation = max(pi_shapes or [0.0])
        theta_activation = max(theta_shapes or [0.0])
        remaining_gap = theta_score["rmse"] - target_score["rmse"]
        class_label, class_reason = v19_field_hierarchy_remaining_class(curve, remaining_gap, psi_activation, pi_activation, theta_activation, source_components, pi_components, theta_components)
        case_rows.append(
            {
                "galaxy": name,
                "set": set_name,
                "lockedRoute": curve.get("lockedModelRoute", ""),
                "canonicalRmse": canonical_score["rmse"],
                "lockedV18Rmse": target_score["rmse"],
                "psiRmse": psi_score["rmse"],
                "psiPiRmse": pi_score["rmse"],
                "psiPiThetaRmse": theta_score["rmse"],
                "psiMinusV18KmS": psi_score["rmse"] - target_score["rmse"],
                "psiPiMinusV18KmS": pi_score["rmse"] - target_score["rmse"],
                "psiPiThetaMinusV18KmS": remaining_gap,
                "psiGainVsCanonicalPct": psi_gain,
                "psiPiGainVsCanonicalPct": pi_gain,
                "psiPiThetaGainVsCanonicalPct": theta_gain,
                "lockedV18GainVsCanonicalPct": target_gain,
                "hierarchyV18RepairRetentionPct": theta_gain / target_gain * 100.0 if abs(target_gain) > 1.0e-9 else math.nan,
                "psiActivation": psi_activation,
                "piActivation": pi_activation,
                "thetaActivation": theta_activation,
                "remainingClass": class_label,
                "remainingReason": class_reason,
                **shape_metrics,
            }
        )
        field_rows.append(
            {
                "galaxy": name,
                "set": set_name,
                "lockedRoute": curve.get("lockedModelRoute", ""),
                "psiActivation": psi_activation,
                "psiReason": source_reason,
                "piActivation": pi_activation,
                "thetaActivation": theta_activation,
                **{f"psi_{key}": value for key, value in source_components.items()},
                **{f"pi_{key}": value for key, value in pi_components.items()},
                **{f"theta_{key}": value for key, value in theta_components.items()},
            }
        )
    metadata = {
        "sourceEquationScale": source_scale,
        "psi": "source loading field",
        "pi": "low-load memory persistence field",
        "theta": "buffered phase/shelf field",
        "piBeta": 1.40,
        "thetaBeta": 1.10,
    }
    return case_rows, field_rows, metadata


def v19_field_hierarchy_remaining_class(
    curve: dict,
    remaining_gap: float,
    psi_activation: float,
    pi_activation: float,
    theta_activation: float,
    source_components: dict,
    pi_components: dict,
    theta_components: dict,
) -> tuple[str, str]:
    route = curve.get("lockedModelRoute", "")
    state = v19_theory_kernel_state(curve)
    features = v19_admissibility_features(curve)
    if remaining_gap <= 8.0:
        return "field hierarchy near v18", "remaining RMSE gap is below 8 km/s"
    if psi_activation > 0.05 or pi_activation > 0.05 or theta_activation > 0.05:
        if route == "low-load" and pi_activation > 0.05:
            return "active low-load memory underpowered", "Pi activates but the remaining gap is still large; likely amplitude/shape/conservation normalization rather than new source admission"
        if route == "buffered single-crossing" and theta_activation > 0.05:
            return "active buffered phase underpowered", "Theta activates but the remaining gap is still large; buffered radial phase shape is not yet the right disk-limit operator"
        if psi_activation > 0.05:
            return "active source family underpowered", "Psi activates but source-shape support does not reproduce the locked v18 target"
        return "active field underpowered", "at least one field activates but the hierarchy remains far from locked v18"
    if route == "low-load":
        memory_load = parse_float(features.get("memoryLoad"), 0.0)
        fgas = parse_float(features.get("fGasOut"), 0.0)
        if fgas >= 0.45 or memory_load <= 2.5:
            return "inactive gas-rich low-load boundary", "low-load case is gas-rich/low-memory; current Pi gate suppresses it, so a gas-boundary or quality/provenance variable may be missing"
        return "inactive low-load persistence state", "low-load case remains inactive despite large gap; missing low-load discriminator or field normalization"
    if route == "buffered single-crossing":
        umax = parse_float(features.get("uMax"), 0.0)
        point_density = parse_float(features.get("pointDensity"), 0.0)
        if umax < 1.15:
            return "inactive buffered low-phase state", "buffered case lacks current high-uMax phase trigger; may need another phase variable or M/L provenance"
        if point_density > 1.5:
            return "inactive coherent buffered state", "buffered case has coherent sampling but no safe Theta trigger; likely missing profile derivative/source-coherence term"
        return "inactive buffered phase state", "buffered case remains outside current Theta modes"
    return "inactive unclassified state", "case remains outside Psi/Pi/Theta field activations"


def v19_field_hierarchy_metric(case_rows: list[dict]) -> dict:
    clean = [row for row in case_rows if row["set"] != "weak-systematics-excluded"]
    high = [row for row in clean if row["set"] == "clean-high-rmse"]
    protected = [row for row in clean if row["set"] == "clean-protected"]
    def retention(rows: list[dict], rmse_key: str) -> float:
        canonical = safe_mean(parse_float(row["canonicalRmse"]) for row in rows)
        target = safe_mean(parse_float(row["lockedV18Rmse"]) for row in rows)
        candidate = safe_mean(parse_float(row[rmse_key]) for row in rows)
        return (canonical - candidate) / (canonical - target) * 100.0 if abs(canonical - target) > 1.0e-9 else math.nan
    active_protected = [row for row in protected if max(parse_float(row["psiActivation"]), parse_float(row["piActivation"]), parse_float(row["thetaActivation"])) > 0.05]
    unexplained_high = [row for row in high if parse_float(row["psiPiThetaMinusV18KmS"], 0.0) > 8.0]
    class_counts: dict[str, int] = {}
    for row in unexplained_high:
        class_counts[row["remainingClass"]] = class_counts.get(row["remainingClass"], 0) + 1
    return {
        "cleanCount": len(clean),
        "highCount": len(high),
        "protectedCount": len(protected),
        "psiCleanRetentionPct": retention(clean, "psiRmse"),
        "psiPiCleanRetentionPct": retention(clean, "psiPiRmse"),
        "psiPiThetaCleanRetentionPct": retention(clean, "psiPiThetaRmse"),
        "psiHighRetentionPct": retention(high, "psiRmse"),
        "psiPiHighRetentionPct": retention(high, "psiPiRmse"),
        "psiPiThetaHighRetentionPct": retention(high, "psiPiThetaRmse"),
        "activeProtectedCount": len(active_protected),
        "activeProtectedMaxIncrementalRegressionVsCanonicalHierarchyKmS": max(0.0, max([parse_float(row["psiPiThetaRmse"], 0.0) - min(parse_float(row["psiRmse"], 0.0), parse_float(row["psiPiRmse"], 0.0)) for row in active_protected] or [0.0])),
        "fullProtectedMaxReplacementGapVsV18KmS": max(0.0, max([parse_float(row["psiPiThetaMinusV18KmS"], 0.0) for row in protected] or [0.0])),
        "unexplainedHighCountGt8KmS": len(unexplained_high),
        "unexplainedHighCasesGt8KmS": ";".join(row["galaxy"] for row in unexplained_high),
        "meanAccelerationShapeRmse": safe_mean(parse_float(row["accelerationShapeRmse"], math.nan) for row in clean),
        "remainingClassCounts": "; ".join(f"{key}:{value}" for key, value in sorted(class_counts.items())),
        "weakSystematicsLeakage": 0,
    }


def write_v19_field_hierarchy_audit_artifacts(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = "mts_v19_field_hierarchy_audit"
    case_rows, field_rows, metadata = v19_field_hierarchy_case_rows()
    metric = v19_field_hierarchy_metric(case_rows)
    remaining_rows = [row for row in case_rows if row["set"] == "clean-high-rmse" and parse_float(row["psiPiThetaMinusV18KmS"], 0.0) > 8.0]
    class_rows = []
    for class_name in sorted({row["remainingClass"] for row in remaining_rows}):
        subset = [row for row in remaining_rows if row["remainingClass"] == class_name]
        class_rows.append(
            {
                "remainingClass": class_name,
                "caseCount": len(subset),
                "cases": ";".join(row["galaxy"] for row in subset),
                "meanRemainingGapKmS": safe_mean(parse_float(row["psiPiThetaMinusV18KmS"], math.nan) for row in subset),
                "meanPsiActivation": safe_mean(parse_float(row["psiActivation"], math.nan) for row in subset),
                "meanPiActivation": safe_mean(parse_float(row["piActivation"], math.nan) for row in subset),
                "meanThetaActivation": safe_mean(parse_float(row["thetaActivation"], math.nan) for row in subset),
                "interpretation": subset[0]["remainingReason"] if subset else "",
            }
        )
    if parse_float(metric["psiPiThetaHighRetentionPct"], 0.0) >= 30.0 and parse_float(metric["activeProtectedMaxIncrementalRegressionVsCanonicalHierarchyKmS"], math.inf) <= 0.25:
        verdict = "field hierarchy materially closes v18 gap"
    elif parse_float(metric["psiPiThetaHighRetentionPct"], 0.0) > parse_float(metric["psiHighRetentionPct"], 0.0) and parse_float(metric["activeProtectedMaxIncrementalRegressionVsCanonicalHierarchyKmS"], math.inf) <= 0.25:
        verdict = "field hierarchy is safe but incomplete"
    else:
        verdict = "field hierarchy not sufficient"
    formula = {
        "candidateId": "mts-v19-field-hierarchy-audit-v1",
        "status": verdict,
        "hierarchy": {
            "Psi": "source loading field",
            "Pi": "low-load memory persistence field",
            "Theta": "buffered phase/shelf field",
            "diskLimit": "V_model^2 = V_bar^2 + S_Psi + S_Pi + S_Theta",
        },
        "fixedStrengths": {"piBeta": 1.40, "thetaBeta": 1.10},
        "metric": metric,
        "lockedV18Changed": False,
        "browserChanged": False,
        "forbiddenInputs": ["galaxy name as formula input", "raw residual", "raw RMSE", "NFW parameters", "MOND parameters", "weak/systematics fitting"],
    }
    limit_rows = [
        {"check": "locked release unchanged", "status": "pass", "detail": "v18/browser/canonical law not edited"},
        {"check": "fixed hierarchy", "status": "pass", "detail": "Psi/Pi/Theta strengths are fixed from prior modes; this audit does not tune another field"},
        {"check": "protected incremental harm", "status": "pass" if parse_float(metric["activeProtectedMaxIncrementalRegressionVsCanonicalHierarchyKmS"], math.inf) <= 0.25 else "fail", "detail": f"active protected incremental regression={fmt(metric['activeProtectedMaxIncrementalRegressionVsCanonicalHierarchyKmS'])} km/s"},
        {"check": "weak/systematics leakage", "status": "pass", "detail": "weak/systematics rows excluded from framework-facing score"},
        {"check": "cosmology portability", "status": "open", "detail": "field hierarchy gives sector objects; cosmology still needs time-domain conservation equations"},
    ]
    equations = [
        "# MTS v19 Field Hierarchy Equations",
        "",
        "This audit freezes the current disk-sector hierarchy. It does not introduce a fourth field.",
        "",
        "```text",
        "V_model(r)^2 = V_bar(r)^2 + S_Psi(r) + S_Pi(r) + S_Theta(r)",
        "",
        "(1 - ell_Psi^2 nabla_r^2) Psi(r) = A_source[X_b(r)] W_b(r)",
        "(1 - ell_Pi^2 nabla_r^2) Pi(r) = A_persist[X_b(r)] C_b(r)",
        "(1 - ell_Theta^2 nabla_r^2) Theta(r) = A_phase[X_b(r)] P_b(r)",
        "```",
        "",
        "Current result: the hierarchy is safe but incomplete. The remaining classes tell us what kind of equation is still missing.",
    ]
    write_csv(out_dir / f"{prefix}_scores.csv", [metric])
    write_csv(out_dir / f"{prefix}_case_ledger.csv", case_rows)
    write_csv(out_dir / f"{prefix}_field_ledger.csv", field_rows)
    write_csv(out_dir / f"{prefix}_remaining_classes.csv", class_rows)
    write_csv(out_dir / f"{prefix}_limit_checks.csv", limit_rows)
    (out_dir / f"{prefix}_formula.json").write_text(json.dumps(json_clean(formula), indent=2, sort_keys=True), encoding="utf-8")
    (out_dir / f"{prefix}_equations.md").write_text("\n".join(equations) + "\n", encoding="utf-8")
    report = [
        "# MTS v19 Field Hierarchy Audit",
        "",
        "This mode freezes the current disk-field hierarchy: source loading `Psi`, low-load memory persistence `Pi`, and buffered phase/shelf response `Theta`. It does not change locked v18 or the browser.",
        "",
        f"Verdict: `{verdict}`.",
        "",
        "## Cumulative Recovery",
        "",
        f"- Clean retention: Psi `{fmt(metric['psiCleanRetentionPct'])}%`, Psi+Pi `{fmt(metric['psiPiCleanRetentionPct'])}%`, Psi+Pi+Theta `{fmt(metric['psiPiThetaCleanRetentionPct'])}%`.",
        f"- High retention: Psi `{fmt(metric['psiHighRetentionPct'])}%`, Psi+Pi `{fmt(metric['psiPiHighRetentionPct'])}%`, Psi+Pi+Theta `{fmt(metric['psiPiThetaHighRetentionPct'])}%`.",
        f"- Active protected incremental regression: `{fmt(metric['activeProtectedMaxIncrementalRegressionVsCanonicalHierarchyKmS'])}` km/s.",
        f"- Remaining high cases above 8 km/s: `{metric['unexplainedHighCountGt8KmS']}`.",
        f"- Remaining class counts: `{metric['remainingClassCounts']}`.",
        "",
        "## Remaining Classes",
        "",
        "| Class | count | mean gap | cases |",
        "| --- | ---: | ---: | --- |",
    ]
    for row in class_rows:
        report.append(f"| {row['remainingClass']} | {row['caseCount']} | {fmt(row['meanRemainingGapKmS'])} | {row['cases']} |")
    report.extend(
        [
            "",
            "## Interpretation",
            "",
            "The hierarchy is now a real field-equation scaffold rather than one empirical support term, but it is not a full derivation of locked v18. The remaining classes separate into inactive low-load, inactive buffered, and active-but-underpowered field states. That points to either a fourth field, a conservation/normalization constraint, or external mass-model/provenance variables.",
            "",
            "## Guardrails",
            "",
            "- No locked v18/browser law changed.",
            "- No galaxy names, residuals, raw RMSE, NFW/MOND parameters, or weak/systematics fitting enter the hierarchy.",
            "- Cosmology is not claimed; this only defines the disk-sector hierarchy that a cosmology limit would have to reduce from.",
            "",
            verdict,
        ]
    )
    (out_dir / f"{prefix}_report.md").write_text("\n".join(report) + "\n", encoding="utf-8")
    capsule = {
        "analysisName": "mts-v19-field-hierarchy-audit-v1",
        "verdict": verdict,
        "metric": metric,
        "metadata": metadata,
        "lockedV18Changed": False,
        "browserChanged": False,
        "outputFiles": [
            f"{prefix}_report.md",
            f"{prefix}_equations.md",
            f"{prefix}_scores.csv",
            f"{prefix}_case_ledger.csv",
            f"{prefix}_field_ledger.csv",
            f"{prefix}_remaining_classes.csv",
            f"{prefix}_limit_checks.csv",
            f"{prefix}_formula.json",
            f"{prefix}_capsule.json",
        ],
    }
    (out_dir / f"{prefix}_capsule.json").write_text(json.dumps(json_clean(capsule), indent=2, sort_keys=True), encoding="utf-8")
    return capsule


